                    | LitFloat32 a -> op a |> nan_guardf32 |> LitFloat32 |> DLit
                    | LitFloat64 a -> op a |> nan_guardf64 |> LitFloat64 |> DLit
                    | _ -> raise_type_error s <| sprintf "The literal must be a float type.\nGot: %s" (show_lit a)
                | a ->
                    let a_ty = data_to_ty s a
                    if is_float a_ty then push_op s Cos a a_ty
                    else raise_type_error s <| sprintf "The argument must be a float type.\nGot: %s" (show_ty a_ty)
            | EOp(_,Conv,[EType(_,typ);a]) ->
                let typ = ty s typ
                let a = term s a
                let at = data_to_ty s a
                if typ = at then a
                else
                    let inline conv_lit x =
                        match typ with
                        | YPrim Int8T -> int8 x |> LitInt8
                        | YPrim Int16T -> int16 x |> LitInt16
                        | YPrim Int32T -> int32 x |> LitInt32
                        | YPrim Int64T -> int64 x |> LitInt64
                        | YPrim UInt8T -> uint8 x |> LitUInt8
                        | YPrim UInt16T -> uint16 x |> LitUInt16
                        | YPrim UInt32T -> uint32 x |> LitUInt32
                        | YPrim UInt64T -> uint64 x |> LitUInt64
                        | YPrim Float32T -> float32 x |> LitFloat32
                        | YPrim Float64T -> float x |> LitFloat64
                        | _ -> raise_type_error s <| sprintf "Cannot convert the literal to the following type: %s" (show_ty typ)
                        |> DLit
                    match a with
                    | DLit (LitInt8 a) -> conv_lit a
                    | DLit (LitInt16 a) -> conv_lit a
                    | DLit (LitInt32 a) -> conv_lit a
                    | DLit (LitInt64 a) -> conv_lit a
                    | DLit (LitUInt8 a) -> conv_lit a
                    | DLit (LitUInt16 a) -> conv_lit a
                    | DLit (LitUInt32 a) -> conv_lit a
                    | DLit (LitUInt64 a) -> conv_lit a
                    | DLit (LitFloat32 a) -> conv_lit a
                    | DLit (LitFloat64 a) -> conv_lit a
                    | _ ->
                        let is_convertible_primt x =
                            match x with
                            | YPrim BoolT | YPrim CharT | YPrim StringT -> false
                            | YPrim _ -> true
                            | _ -> false
                        if is_convertible_primt at && is_convertible_primt typ then push_typedop s (TyConv(typ,a)) typ
                        else raise_type_error s <| sprintf "Cannot convert %s to the following type: %s" (show_data a) (show_ty typ)
            | EOp(_,NanIs,[a]) ->
                let a = term s a
                match data_to_ty s a with
                | YPrim (Float32T | Float64T) -> push_op s NanIs a (YPrim BoolT)
                | a -> raise_type_error s <| sprintf "Expected a float in NanIs. Got: %s" (show_ty a)
            | EOp(_,Infinity,[EType(_,a)]) ->
                match ty s a with
                | YPrim Float32T -> DLit (LitFloat32 infinityf)
                | YPrim Float64T -> DLit (LitFloat64 infinity)
                | a -> raise_type_error s "Expected a float.\nGot: %s" (show_ty a)
            | EOp(_,Pi,[EType(_,a)]) ->
                match ty s a with
                | YPrim Float32T -> DLit (LitFloat32 Single.Pi)
                | YPrim Float64T -> DLit (LitFloat64 Double.Pi)
                | a -> raise_type_error s "Expected a float.\nGot: %s" (show_ty a)
            | EOp(_,LitIs,[a]) ->
                match term s a with
                | DLit _ -> DLit (LitBool true)
                | _ -> DLit (LitBool false)
            | EOp(_,PrimIs,[a]) ->
                match term s a |> data_to_ty s with
                | YPrim _ -> DLit (LitBool true)
                | _ -> DLit (LitBool false)
            | EOp(_,SymbolIs,[a]) ->
                match term s a with
                | DSymbol _ -> DLit (LitBool true)
                | _ -> DLit (LitBool false)
            | EOp(_,VarIs,[a]) ->
                match term s a with
                | DNominal(DV _, _) | DV _ -> DLit (LitBool true)
                | _ -> DLit (LitBool false)
            | EOp(_,UnionIs,[a]) ->
                match term s a with
                | DNominal(DV(L(_,YUnion _)), _) | DNominal(DUnion _, _) -> DLit (LitBool true)
                | _ -> DLit (LitBool false)
            | EOp(_,HeapUnionIs,[a]) ->
                match term s a with
                | DNominal(DV(L(_,YUnion x)), _) | DNominal(DUnion(_,x), _) ->
                    match x.Item.layout with UHeap -> true | UStack -> false
                    |> LitBool |> DLit
                | _ -> DLit (LitBool false)
            | EOp(_,LayoutIs,[a]) ->
                match term s a with
                | DV(L(_,YLayout _)) -> DLit (LitBool true)
                | _ -> DLit (LitBool false)
            | EOp(_,NominalIs,[a]) ->
                match term s a with
                | DNominal(_, _) -> DLit (LitBool true)
                | _ -> DLit (LitBool false)
            | EOp(_,FunctionIs,[a]) ->
                match term s a with
                | DFunction _ | DV(L(_,YFun _)) -> DLit (LitBool true)
                | _ -> DLit (LitBool false)
            | EOp(_,ExistsIs,[a]) ->
                match term s a with
                | DExists _ -> DLit (LitBool true)
                | _ -> DLit (LitBool false)
            | EOp(_,PrimTypeIs,[EType(_,a)]) ->
                match ty s a with
                | YPrim _ -> DLit (LitBool true)
                | _ -> DLit (LitBool false)
            | EOp(_,SymbolTypeIs,[EType(_,a)]) ->
                match ty s a with
                | YSymbol _ -> DLit (LitBool true)
                | _ -> DLit (LitBool false)
            | EOp(_,UnionTypeIs,[EType(_,a)]) ->
                match ty s a with
                | YNominal _ | YApply _ as a ->
                    match nominal_type_apply s a with
                    | YUnion _ -> DLit (LitBool true)
                    | _ -> DLit (LitBool false)
                | _ -> DLit (LitBool false)
            | EOp(_,HeapUnionTypeIs,[EType(_,a)]) ->
                match ty s a with
                | YNominal _ | YApply _ as a ->
                    match nominal_type_apply s a with
                    | YUnion x -> DLit (LitBool (match x.Item.layout with UHeap -> true | UStack -> false))
                    | _ -> DLit (LitBool false)
                | _ -> DLit (LitBool false)
            | EOp(_,LayoutTypeIs,[EType(_,a)]) ->
                match ty s a with
                | YLayout _ -> DLit (LitBool true)
                | _ -> DLit (LitBool false)
            | EOp(_,ExistsTypeIs,[EType(_,a)]) ->
                match ty s a with
                | YExists -> DLit (LitBool true)
                | _ -> DLit (LitBool false)
            | EOp(_,NominalTypeIs,[EType(_,a)]) ->
                match ty s a with
                | YNominal _ | YApply _ -> DLit (LitBool true)
                | _ -> DLit (LitBool false)
            | EOp(_,NominalStrip,[a]) ->
                match term s a with
                | DNominal(DV(L(_,YUnion _)), _) | DNominal(DUnion _, _) -> raise_type_error s "Cannot strip the nominal wrapper from an union."
                | DNominal(a,_) -> a
                | a -> raise_type_error s <| sprintf "Expected a nominal.\nGot: %s" (show_data a)
            | EOp(_,NominalTypeApply,[EType(_,a)]) ->
                match ty s a with
                | YNominal _ | YApply _ as a -> DExists([|nominal_type_apply s a|], DB)
                | a -> raise_type_error s <| sprintf "Expected a nominal type.\nGot: %s" (show_ty a)
            | EOp(_,ExistsStrip,[a]) ->
                match term s a with
                | DExists(_,a) -> a
                | a -> raise_type_error s <| sprintf "Expected an existential.\nGot: %s" (show_data a)
            | EOp(_,PrototypeHas,[prot; EType(_,a)]) ->
                let body (x : Nominal) =
                    let prot_er () = raise_type_error s "Expected a forall or a prototype apply."
                    let rec loop = function
                        | EForall'(_,_,_,x) -> loop x
                        | EPrototypeApply(_,prot_id,_) -> env.prototypes_instances.ContainsKey(prot_id,x.node.id) |> LitBool |> DLit
                        | _ -> prot_er()
                    match term s prot with
                    | DForall(body,_,_,_,_) -> loop body
                    | _ -> prot_er()
                let rec loop = function
                    | YNominal x -> body x
                    | YApply(l,_) -> loop l
                    | a -> raise_type_error s <| sprintf "Expected a nominal.\nGot: %s" (show_ty a)
                loop (ty s a)
            | EOp(_,TypeEq,[EType(_,a);EType(_,b)]) -> DLit(LitBool(ty s a = ty s b))
            | EOp(_,FailWith,[EType(_,typ);a]) ->
                match ty s typ, term s a with
                | typ, (DV(L(_,YPrim StringT)) | DLit(LitString _)) & a -> push_typedop_no_rewrite s (TyFailwith(typ,a)) typ
                | _,a -> raise_type_error s "Expected a string as input to failwith.\nGot: %s" (show_data a)
            | EOp(_,FailWith,_) -> raise_type_error s "Malformed FailWith"
            | EOp(_,ErrorType,[a]) -> term s a |> show_data |> raise_type_error s
            | EOp(_,PrintStatic,[EType(_,a)]) -> PartEvalSeams.print hopacsota s (ty s a |> show_ty); DB
            | EOp(_,PrintStatic,[a]) -> PartEvalSeams.print hopacsota s (term s a |> show_data); DB
            | EOp(_,PrintRaw,[a]) -> PartEvalSeams.print hopacsota s (sprintf "%A" (Printable.eval(Choice1Of2(a,id)))); DB
            | EOp(_,UnionTag,[a]) ->
                let eval k (h : Union) = h.Item.tags.[k] |> LitInt32 |> DLit
                match term s a with
                | DNominal(DV(L(_,YUnion h) & v) & a, _) ->
                    match Map.tryFind v s.unions with
                    | Some (UnionData (k,_)) -> eval k h
                    | _ -> push_op s UnionTag a (YPrim Int32T)
                | DNominal(DUnion(DPair(DSymbol k,_),h), _) -> eval k h
                | a -> raise_type_error s <| sprintf "Expected an union.\nGot: %s" (show_data a)
            | EOp(_,UnionCaseName,a :: style) ->
                let style =
                    match style with
                    | [] -> "exact"
                    | [b] ->
                        match term s b with
                        | DLit (LitString x) -> x
                        | b -> raise_type_error s <| sprintf "UnionCaseName's style must be a string literal: exact, lower, initial, snake or kebab.\nGot: %s" (show_data b)
                    | _ -> raise_type_error s "UnionCaseName takes the union value and an optional style literal."
                let styled (k : string) =
                    match style with
                    | "exact" -> k
                    | "lower" -> k.ToLowerInvariant()
                    | "initial" -> string (System.Char.ToLowerInvariant k.[0])
                    | "snake" | "kebab" ->
                        let separator = if style = "snake" then "_" else "-"
                        k |> Seq.mapi (fun i c -> let lower = string (System.Char.ToLowerInvariant c) in if i > 0 && lower <> string c then separator + lower else lower) |> String.concat ""
                    | x -> raise_type_error s <| sprintf "UnionCaseName's style must be exact, lower, initial, snake or kebab.\nGot: %s" x
                let name (k : string) = DLit (LitString (styled k))
                match term s a with
                | DNominal(DV(L(_,YUnion h) & v) & a, _) ->
                    match Map.tryFind v s.unions with
                    | Some (UnionData (k,_)) -> name k
                    | _ when h.Item.tags.Count = 1 -> h.Item.tags.Keys |> Seq.head |> name
                    | _ ->
                        let names = Array.create h.Item.tag_cases.Length ""
                        for KeyValue(k,i) in h.Item.tags do names.[i] <- k
                        let table = names |> Array.toList |> List.map (name >> dyn false s)
                        let table = push_typedop_no_rewrite s (TyArrayLiteral(YPrim StringT, table)) (YArray (YPrim StringT))
                        push_binop_no_rewrite s ArrayIndex (table, push_op s UnionTag a (YPrim Int32T)) (YPrim StringT)
                | DNominal(DUnion(DPair(DSymbol k,_),_), _) -> name k
                | a -> raise_type_error s <| sprintf "Expected an union.\nGot: %s" (show_data a)
            | EOp(_,Global & op,[a']) ->
                match term s a' with
                | DLit (LitString text) & a ->
                    // if text.Contains "import " || text.Contains "Fable" then
                    //     let s = { s with trace = []; seq = ResizeArray() }
                    //     let l = s.cse |> List.map _.Count |> List.filter ((=) 0) |> List.length
                    //     Console.WriteLine ($"global / text: {text} / s: %A{s} / l: {l}")
                    let cse_counts = s.cse |> List.map _.Count |> List.filter ((=) 0) |> List.length
                    let x_ =
                        s.backend.node = env.backend
                        && s.i.contents < 2
                        && (cse_counts = 2 || cse_counts = 3)
                    if text.Contains "std_path_PathBuf"
                        || text.Contains "std_path_Display"
                        || text.Contains "regex_Regex"
                        || text.Contains "VarError"
                        then
                        trace Verbose (fun () -> $"PartEval.peval / | EOp(_,Global & op,[a]) -> / s.i.contents: %A{s.i.contents} / s.cse.count: %A{s.cse |> List.map _.Count} / s.backend.node: %A{s.backend.node} / op: %A{op} / a': %A{a'} / env.backend: %A{env.backend} / x_: %A{x_} / text: %A{text}") _locals
                    // A global belongs to the backend whose branch runs it (lib/spiral's F#-only declarations go through
                    // backend.fsharp_global, whose switch runs its Fsharp arm as F# in every build).
                    if s.backend.node = env.backend then
                        // trace Verbose (fun () -> $"PartEval.peval / | EOp(_,Global & op,[a]) -> / s.i.contents: %A{s.i.contents} / s.cse.count: %A{s.cse |> List.map _.Count} / s.backend.node: %A{s.backend.node} / op: %A{op} / a': %A{a'} / env.backend: %A{env.backend} / x_: %A{x_} / text: %A{text}") _locals
                    // && s.i.contents < 2
                    // && s.cse |> List.map _.Count |> List.filter ((=) 0) |> List.length = 2
                        global' text
                    push_op_no_rewrite s op a YB
                | a -> raise_type_error s $"Expected a string literal.\nGot: {show_data a}"
            | EOp(_,ToPythonRecord,[a]) ->
                match term s a |> dyn false s with
                | DRecord _ & a -> push_op_no_rewrite s ToPythonRecord a (YMacro [PartEvalMacro.Text "object"])
                | a -> raise_type_error s $"Expected a record.\nGot: {show_data a}"
            | EOp(_,ToPythonNamedTuple,[n;a]) ->
                match term s n, term s a |> dyn false s with
                | (DLit (LitString _) | DV(L(_,YPrim StringT))) & n, DRecord _ & a -> push_binop_no_rewrite s ToPythonNamedTuple (n,a) (YMacro [PartEvalMacro.Text "object"])
                | n, a -> raise_type_error s $"Expected a pair of string and record.\nGot: {show_data n}\nAnd: {show_data a}"
            | EOp(_,VarTag,[a]) ->
                match term s a with
                | DNominal(DV(L(i,_)), _) | DV(L(i,_)) -> DLit (LitInt32 i)
                | a -> raise_type_error s $"Expected a runtime variable.\nGot: {show_data a}"
            | EOp(_,TagToSymbol,[a]) ->
                match term s a with
                | DLit (LitInt32 i) -> DSymbol (string i)
                | a -> raise_type_error s $"Expected an i32 literal.\nGot: {show_data a}"
            | EOp(_,FunctionTermSlotsGet,[a]) ->
                match term s a with
                | DFunction(_,_,free_vars,_,_,_) -> Array.foldBack (fun x s -> DPair(x,s)) free_vars DB
                | DV(L(_,YFun _)) -> raise_type_error s $"Expected a compile time function. Got a runtime one."
                | a -> raise_type_error s $"Expected a compile time function.\nGot: {show_data a}"
            | EOp(_,FunctionTermSlotsSet,[a;b]) ->
                match term s a, term s b with
                | DFunction(q1,q2,free_vars,q4,q5,a6), b ->
                    let mutable b = b
                    let free_vars =
                        Array.init free_vars.Length (fun _ ->
                            match b with
                            | DPair(q,w) -> b <- w; q
                            | DB -> raise_type_error s "Unexpected end of the tuple to be set."
                            | _ -> raise_type_error s $"Expected a pair.\nGot: {show_data b}"
                            )
                    match b with
                    | DB -> DFunction(q1,q2,free_vars,q4,q5,a6)
                    | _ -> raise_type_error s $"Expected an unit end of the tuple.\nGot: {show_data b}"
                | DV(L(_,YFun _)), _ -> raise_type_error s $"Expected a compile time function. Got a runtime one."
                | a, _ -> raise_type_error s $"Expected a compile time function.\nGot: {show_data a}"
            | EOp(_,SizeOf,[EType(_,a)]) ->
                match ty s a with
                | YB | YSymbol _ -> DLit (LitInt32 0)
                | YPrim (Int8T | UInt8T | BoolT) -> DLit (LitInt32 1)
                | YPrim (Int16T | UInt16T) -> DLit (LitInt32 2)
                | YPrim (Int32T | UInt32T | Float32T) -> DLit (LitInt32 4)
                | YPrim (Int64T | UInt64T | Float64T) -> DLit (LitInt32 8)
                | a -> push_typedop s (TySizeOf a) (YPrim Int32T)
            | EOp(_,FreeVars,[a]) ->
                let x = term s a |> data_free_vars
                Array.foldBack (fun x s -> DPair(DV x,s)) x (DRecord Map.empty)
            | EOp(_,FreeVarsReplace,[a;b]) ->
                let a = term s a
                let b = term s b
                let a_fv = a |> data_free_vars
                let b_fv = b |> data_free_vars
                if a_fv.Length <> b_fv.Length then raise_type_error s "The two expressions need to have the same number of free variables."
                let d = Dictionary(HashIdentity.Reference)
                Array.iter2 (fun (L(_,ta) as a) (L(_,tb) as b) ->
                    if ta <> tb then raise_type_error s $"The free variables can only be replaced with free vars of the same type.\nGot: {show_ty ta}\nExpected: {show_ty tb}"
                    d.Add(a,b)
                    ) a_fv b_fv
                data_free_vars_replace s d a
            | EOp(_,HashSetCreate,[]) -> DHashSet(HashSet(HashIdentity.Reference))
            | EOp(_,HashSetAdd,[h;k]) ->
                match term s h, term s k with
                | DHashSet h, k -> DLit(LitBool(h.Add k))
                | h, _ -> raise_type_error s $"Expected a compile time HashSet.\nGot: {show_data h}"
            | EOp(_,HashSetContains,[h;k]) ->
                match term s h, term s k with
                | DHashSet h, k -> DLit(LitBool(h.Contains k))
                | h, _ -> raise_type_error s $"Expected a compile time HashSet.\nGot: {show_data h}"
            | EOp(_,HashSetRemove,[h;k]) ->
                match term s h, term s k with
                | DHashSet h, k -> DLit(LitBool(h.Remove k))
                | h, _ -> raise_type_error s $"Expected a compile time HashSet.\nGot: {show_data h}"
            | EOp(_,HashSetCount,[h]) ->
                match term s h with
                | DHashSet h -> DLit(LitInt32(h.Count))
                | h -> raise_type_error s $"Expected a compile time HashSet.\nGot: {show_data h}"
            | EOp(_,HashMapCreate,[]) -> DHashMap(OrderedDictionary(HashIdentity.Reference), ref true)
            | EOp(_,HashMapSetImmutable,[h]) ->
                match term s h with
                | DHashMap(_, is_writable) -> is_writable.Value <- false; DB
                | h -> raise_type_error s $"Expected a compile time HashMap.\nGot: {show_data h}"
            | EOp(_,HashMapSet,[h;k;v]) ->
                match term s h, term s k, term s v with
                | DHashMap(h, is_writable), k, v when is_writable.Value -> h.[k] <- v; DB
                | DHashMap(h, _), _, _ -> raise_type_error s "The hash map has been made read-only and cannot be added to."
                | h, _, _ -> raise_type_error s $"Expected a compile time HashMap.\nGot: {show_data h}"
            | EOp(_,HashMapAdd,[h;k;v]) ->
                match term s h, term s k, term s v with
                | DHashMap(h, is_writable), k, v when is_writable.Value -> if h.TryAdd(k,v) then DB else raise_type_error s "The entry with the same key already exists in the dictionary."
                | DHashMap(h, _), _, _ -> raise_type_error s "The hash map has been made read-only and cannot be added to."
                | h, _, _ -> raise_type_error s $"Expected a compile time HashMap.\nGot: {show_data h}"
            | EOp(_,HashMapTryAdd,[h;k;v]) ->
                match term s h, term s k, term s v with
                | DHashMap(h, is_writable), k, v -> if is_writable.Value then DLit(LitBool(h.TryAdd(k,v))) else raise_type_error s "The hash map has been made read-only and cannot be added to."
                | h, _, _ -> raise_type_error s $"Expected a compile time HashMap.\nGot: {show_data h}"
            | EOp(_,HashMapContains,[h;k]) ->
                match term s h, term s k with
                | DHashMap(h, _), k -> DLit(LitBool(h.ContainsKey k))
                | h, _ -> raise_type_error s $"Expected a compile time HashMap.\nGot: {show_data h}"
            | EOp(_,HashMapRemove,[h;k]) ->
                match term s h, term s k with
                | DHashMap(h, is_writable), k -> if is_writable.Value then DLit(LitBool(h.Remove k)) else raise_type_error s "The hash map has been made read-only and cannot be removed from."
                | h, _ -> raise_type_error s $"Expected a compile time HashMap.\nGot: {show_data h}"
            | EOp(_,HashMapCount,[h]) ->
                match term s h with
                | DHashMap(h, _) -> DLit(LitInt32(h.Count))
                | h -> raise_type_error s $"Expected a compile time HashMap.\nGot: {show_data h}"
            | EOp(_,HashMapTryGet,[h;k]) ->
                match term s h, term s k with
                | DHashMap(h, _), k ->
                    if k |> h.ContainsKey
                    then k |> h.GetValueOrDefault
                    else DSymbol "null"
                | h, _ -> raise_type_error s $"Expected a compile time HashMap.\nGot: {show_data h}"
            | EOp(_,PrimToString,[a]) ->
                let a = term s a
                match data_to_ty s a with
                | YPrim (Int8T | Int16T | Int32T | Int64T | UInt8T | UInt16T | UInt32T | UInt64T | BoolT | CharT) -> push_op s PrimToString a (YPrim StringT)
                | t -> raise_type_error s $"PrimToString expects an integer, bool or char.\nGot: {show_ty t}"
            | EOp(_,StaticStringConcat,[a;b]) ->
                match term2 s a b with
                | a,b when data_to_ty s a = YPrim StringT && data_to_ty s b = YPrim StringT ->
                    match a,b with
                    | DLit(LitString a), DLit(LitString b) -> DLit(LitString(a+b))
                    | _ -> push_binop s StaticStringConcat (a,b) (YPrim StringT)
                | a,b -> raise_type_error s $"Expected two strings as arguments.\nGot: {show_ty (data_to_ty s a)}\nAnd: {show_ty (data_to_ty s b)}"
            | EOp(_,StaticStringConcat,[l]) ->
                let value = term s l
                match value with
                | DPair(a,b) when data_to_ty s a = YPrim StringT && data_to_ty s b = YPrim StringT ->
                    match a,b with
                    | DLit(LitString a), DLit(LitString b) -> DLit(LitString(a+b))
                    | _ -> push_binop s StaticStringConcat (a,b) (YPrim StringT)
                | value ->
                    let strb = System.Text.StringBuilder()
                    let rec loop = function
                        | DPair(a,b) -> loop a; loop b
                        | DLit(LitString x) -> strb.Append(x) |> ignore
                        | DB -> ()
                        | x -> raise_type_error s $"Expected a compile time string or a pair of them.\nGot: {show_data x}"
                    loop value
                    DLit(LitString(strb.ToString()))
            | EOp(_,StdoutFlush,[]) ->
                push_op_no_rewrite' s StdoutFlush [] YB
            | EOp(_,Assign,[target;value]) ->
                match term s target, term s value with
                | DV(L(_,target_ty)) as target, value when target_ty = data_to_ty s value -> push_op_no_rewrite' s Assign [target; value] YB
                | DV(L(_,target_ty)), value -> raise_type_error s $"!!!!Assign needs a value of the target's type.\nTarget: {show_ty target_ty}\nValue: {show_ty (data_to_ty s value)}"
                | target, _ -> raise_type_error s $"!!!!Assign needs a dynamic local as its target (bind it with inl ~name or dyn first).\nGot: {show_data target}"
            | EOp(_,MonotonicDelayMs,[duration]) ->
                match term s duration with
                | DLit(LitInt32 milliseconds) as duration when milliseconds >= 0 -> push_op_no_rewrite s MonotonicDelayMs duration YB
                | DLit(LitInt32 milliseconds) -> raise_type_error s $"Expected a non-negative monotonic delay in milliseconds.\nGot: {milliseconds}"
                | duration -> raise_type_error s $"Expected a compile-time i32 duration in milliseconds.\nGot: {show_data duration}"
            // The format and its arguments (none, one value or tuple, or several: a tuple of them; printf_pieces).
            | EOp(_,Printf,fmt :: args) ->
                let fmt = term s fmt
                let str =
                    match args with
                    | [] -> DB
                    | [a] -> term s a
                    | args -> args |> List.map (term s) |> List.reduceBack (fun a b -> DPair(a,b))
                match fmt with
                | DLit(LitString _) -> push_binop_no_rewrite s Printf (fmt, str) YB
                | _ -> raise_type_error s $"Expected a compile time string as the format.\nGot: {show_data fmt}"
            | EOp(_,op,a) -> raise_type_error s <| sprintf "Compiler error: %A with %i args not implemented" op (List.length a)

        let s : LangEnv = {
            trace = []
            inline_depth = InlineDepthOps.root
            seq = null
            cse = []
            unions = Map.empty
            i = ref 0
            env_global_type = [||]
            env_global_term = [||]
            env_stack_type = [||]
            env_stack_term = [||]
            backend = backend_strings.Add env.backend
            globals = ResizeArray ()
            }
        validation_root_globals.Value <- Some s.globals
        let ty_to_data x = ty_to_data {s with i = ref 0} x
        let nominal_apply x = nominal_type_apply {s with i = ref 0} x

        match x with
        | EFun'(r,_,_,_,_) -> PartEvalSeams.root hopacsota s.globals (fun () -> term_scope s (EApply(r,x,EB r))), {join_point_method=join_point_method; join_point_closure=join_point_closure; ty_to_data=ty_to_data; nominal_apply=nominal_apply; globals=s.globals}
        | EForall' _ -> raise_type_error s "The main function should not have a forall."
        | _ -> raise_type_error s "Expected a function as the main."

    /// ## CodegenUtils
    // open System.Text

    /// ### CodegenEnv
    type CodegenEnv =
        {
        text : StringBuilder
        indent : int
        }

    /// ### string_builder_env
    // ws: upstream's name for CodegenEnv (CodegenUtils.fs:6). The C++ and Python generators are kept in upstream's
    // text and use this name; the other backends keep using CodegenEnv. Same type, so the two mix freely.
    type string_builder_env = CodegenEnv

    type CodegenTagAllocator() =
        let gate = obj()
        let mutable current = -1

        member _.Next() =
            lock gate (fun () ->
                current <- current + 1
                current)

    /// ### line
    let line x (s : string) = x.text.Append(' ', x.indent).Append(s).Append('\n') |> ignore

    /// ### indent
    let indent x : CodegenEnv = {x with indent=x.indent+4}

    /// ### preservesDuplicateGlobalFragment
    /// Backends deduplicate global lines by text, but a multi-line global arrives as fragments, and its
    /// continuation lines (indented, or a closing brace) legitimately repeat across different globals.
    /// Deduplicating those deleted lines from the middle of later blocks. (Ported from the single-flight core.)
    let preservesDuplicateGlobalFragment (x : string) =
        System.String.IsNullOrEmpty x
        || ((System.Char.IsWhiteSpace x.[0] || x.[0] = '}') && not (x.TrimEnd().Contains '\n'))

    type DecimalLiteralPointDispositionId =
        | DecimalLiteralHasPoint
        | DecimalLiteralHasExponent
        | DecimalLiteralNeedsPoint

    let private decimalLiteralPointDispositionId (value:string) =
        let mutable hasPoint = false
        let mutable hasExponent = false
        if not (System.Object.ReferenceEquals(value, null)) then
            for ch in value do
                match ch with
                | '.' -> hasPoint <- true
                | 'E' -> hasExponent <- true
                | _ -> ()
        if hasPoint then DecimalLiteralHasPoint
        elif hasExponent then DecimalLiteralHasExponent
        else DecimalLiteralNeedsPoint

    /// ### add_dec_point
    let add_dec_point (x : string) =
        match decimalLiteralPointDispositionId x with
        | DecimalLiteralNeedsPoint -> x + ".0"
        | DecimalLiteralHasPoint
        | DecimalLiteralHasExponent -> x

    /// ### CodegenError
    exception CodegenError of Range option * string

    /// ### CodegenErrorWithPos
    exception CodegenErrorWithPos of Trace * string

    /// ### raise_codegen_error
    let raise_codegen_error x = raise (CodegenError (None,x))

    /// ### raise_codegen_error_backend
    let raise_codegen_error_backend r x = raise (CodegenError (Some r,x))

    /// ### raise_codegen_error'
    let raise_codegen_error' trace (r,x) = raise (CodegenErrorWithPos(Option.fold (fun s x -> x :: s) trace r,x))

    /// ### codegen_runtime_file
    // ws: the text of a codegen runtime file (corelib.cuh, corelib.py). Upstream reads them from the compiler's own
    // directory (AppDomain.CurrentDomain.BaseDirectory, CodegenCpp.fs:1041, CodegenPython.fs:499); the workspace
    // ships its patched copies there as well (apps/compiler/runtime/, copied next to the host DLL), and
    // SPIRAL_CODEGEN_RUNTIME_DIR names another directory (the notebook host, tests). Replaces the old lookup in
    // <workspace_root>/deps/The-Spiral-Language, which served the fork's pre-2.18 corelib.
    // Last, the workspace's own copies (spiral: apps/compiler/runtime; polyglot: deps/spiral/apps/compiler/runtime), for
    // hosts that don't ship them next to their DLL (the dotnet-interactive kernel, polyglot's Supervisor).
    let codegen_runtime_file (f : string) =
        let workspace =
            try
                let root = SpiralFileSystem.get_workspace_root ()
                [ System.IO.Path.Join(root, "apps/compiler/runtime")
                  System.IO.Path.Join(root, "deps/spiral/apps/compiler/runtime") ]
            with _ -> []
        let dirs =
            [ System.Environment.GetEnvironmentVariable "SPIRAL_CODEGEN_RUNTIME_DIR"
              System.AppDomain.CurrentDomain.BaseDirectory ]
            @ workspace
            |> List.filter (System.String.IsNullOrWhiteSpace >> not)
        match dirs |> List.map (fun d -> System.IO.Path.Join(d, f)) |> List.tryFind System.IO.File.Exists with
        | Some path -> System.IO.File.ReadAllText path
        | None ->
            let looked = String.concat "; " dirs
            raise_codegen_error $"Cannot find the codegen runtime file {f} (looked in: {looked}). Set SPIRAL_CODEGEN_RUNTIME_DIR to the directory that holds corelib.cuh and corelib.py."

    /// ### printf_pieces
    // ws: the portable `!!!!Printf(format, arg, ..)` every backend but Cuda's C++ reads (that one hands the format to
    // printf as is). `%s` takes a string, `%d` an integer of any width and `%%` writes a percent sign; the rest of the
    // format is text. The pieces come back in order: `Choice1Of2 text` or `Choice2Of2 (specifier, argument)`.
    let printf_pieces (fmt : string) (args : TermVar []) =
        let kind = function
            | WV(L(_,YPrim t)) -> Some t
            | WLit l -> Some (lit_to_primitive_type l)
            | _ -> None
        let pieces = ResizeArray()
        let text = StringBuilder()
        let flush () =
            if text.Length > 0 then
                pieces.Add(Choice1Of2(text.ToString()))
                text.Clear() |> ignore
        let mutable next = 0
        let mutable i = 0
        while i < fmt.Length do
            let c = fmt.[i]
            let spec = if c = '%' && i + 1 < fmt.Length then fmt.[i + 1] else ' '
            if c <> '%' then
                text.Append c |> ignore
                i <- i + 1
            elif spec = '%' then
                text.Append '%' |> ignore
                i <- i + 2
            elif spec = 's' || spec = 'd' then
                if next >= args.Length then
                    raise_codegen_error (sprintf "Printf: the format %A has more placeholders than arguments (%i)." fmt args.Length)
                let arg = args.[next]
                match spec, kind arg with
                | 's', Some StringT -> ()
                | 'd', Some (Int8T | Int16T | Int32T | Int64T | UInt8T | UInt16T | UInt32T | UInt64T) -> ()
                | _, t ->
                    let want = if spec = 's' then "a string" else "an integer"
                    raise_codegen_error (sprintf "Printf: %%%c in the format %A takes %s; argument %i is %A." spec fmt want (next + 1) t)
                flush ()
                pieces.Add(Choice2Of2(spec, arg))
                next <- next + 1
                i <- i + 2
            else
                raise_codegen_error (sprintf "Printf: the format %A has an unsupported placeholder at %i; the portable ones are %%s (a string), %%d (an integer) and %%%%." fmt i)
        flush ()
        if next <> args.Length then
            raise_codegen_error (sprintf "Printf: the format %A has %i placeholders but %i arguments were given." fmt next args.Length)
        List.ofSeq pieces

    /// ### backend_cpp
    [<RequireQualifiedAccess>]
    type backend_cpp =
        | CudaDevice
        | CudaHost
        | CppHost

        member t.Name = t.ToString()

    /// ### codegen_env
    // Plain ResizeArrays: codegen runs sequentially (CodegenC relies on it too).
    type codegen_env =
        {
            globals : string ResizeArray
            fwd_dcls_types : string ResizeArray
            fwd_dcls_methods : string ResizeArray
            fwd_dcls_main_defs : string ResizeArray
            types : string ResizeArray
            functions : string ResizeArray
            main_defs : string ResizeArray
        }

        static member Create() =
            {
                globals = ResizeArray()
                fwd_dcls_types = ResizeArray()
                types = ResizeArray()
                fwd_dcls_methods = ResizeArray()
                fwd_dcls_main_defs = ResizeArray()
                functions = ResizeArray()
                main_defs = ResizeArray()
            }

    /// ### generatedMethodName
    let generatedMethodName (sourceName : string option) (tag : int) =
        match sourceName with
        | Some name when name |> Seq.exists System.Char.IsAsciiLetterOrDigit ->
            let safe = name |> String.map (fun c -> if System.Char.IsAsciiLetterOrDigit c || c = '_' then c else '_')
            let stem = if System.Char.IsAsciiDigit safe.[0] then "_" + safe else safe
            $"{stem}_{tag}"
        | _ -> $"method{tag}"

    /// ### generatedClosureName
    // The `_c` keeps a closure off the method name `{stem}_{tag}` even when both are tag 0.
    let generatedClosureName (sourceName : string option) (tag : int) =
        match sourceName with
        | Some name when name |> Seq.exists System.Char.IsAsciiLetterOrDigit ->
            let safe = name |> String.map (fun c -> if System.Char.IsAsciiLetterOrDigit c || c = '_' then c else '_')
            let stem = if System.Char.IsAsciiDigit safe.[0] then "_" + safe else safe
            $"{stem}_c{tag}"
        | _ -> $"closure{tag}"

    /// A named `inl f (x) = ...` used as a value is a closure whose body is the join point named `f`.
    /// Curried functions nest `EFun'` outside that join point. Anonymous functions stay `closure{tag}`.
    let rec closureSourceName (body : E) =
        match closureBindingNames.TryGetValue body with
        | true, name -> Some name
        | _ ->
            match body with
            | EJoinPoint'(_, _, _, _, _, name) -> name
            | EJoinPoint(_, _, _, _, name) -> name
            | EFun'(_, _, _, inner, _) -> closureSourceName inner
            | EAnnot(_, inner, _) -> closureSourceName inner
            | _ -> None

    /// ### generatedCaseNames
    let generatedCaseNames (cases : (int * string) seq) : Map<int, string> =
        let readable =
            cases |> Seq.map (fun (index, name) ->
                let safe = name |> String.map (fun c -> if System.Char.IsAsciiLetterOrDigit c || c = '_' then c else '_')
                index, (if safe |> Seq.exists System.Char.IsAsciiLetterOrDigit then safe else ""))
            |> Seq.toArray
        let uses = readable |> Array.countBy snd |> dict
        readable
        |> Array.map (fun (index, safe) -> index, (if safe = "" then string index elif uses.[safe] > 1 then $"{safe}_{index}" else safe))
        |> Map.ofArray

    /// ### caseFoldedSuffixes
    /// Pascal identifiers ignore case: a suffix that equals another one of the same union under case folding gets its
    /// position appended, so Brasil and BRASIL stay two cases. Suffixes without such a twin are unchanged.
    let caseFoldedSuffixes (suffixes : string []) : string [] =
        let folded = suffixes |> Array.countBy (fun s -> s.ToLowerInvariant()) |> dict
        suffixes |> Array.mapi (fun i s -> if folded.[s.ToLowerInvariant()] > 1 then $"{s}_{i}" else s)

    /// ### generatedCaseSuffixes
    let generatedCaseSuffixes (cases : Map<int * string, 'a>) : string [] =
        let names = generatedCaseNames (cases |> Map.keys)
        cases |> Map.toArray |> Array.map (fun ((index, _), _) -> names.[index])

    /// ### generatedCaseName
    let generatedCaseName (prefix_tag : string) (cases : Map<int * string, 'a>) (position : int) = $"{prefix_tag}_{(generatedCaseSuffixes cases).[position]}"

    /// ### generatedCaseNameOfTag
    let generatedCaseNameOfTag (prefix_tag : string) (cases : Map<int * string, 'a>) (tag : int) = $"{prefix_tag}_{(generatedCaseNames (cases |> Map.keys)).[tag]}"

    /// ### leanCaseName
    let leanCaseName (cases : Map<int * string, 'a>) (position : int) =
        let suffix = (generatedCaseSuffixes cases).[position]
        if System.Char.IsAsciiLetterUpper suffix.[0] then suffix else $"c{suffix}"

    /// ### gleamCaseName
    let gleamCaseName (prefix_tag : string) (cases : Map<int * string, 'a>) (position : int) =
        let upper_camel (suffix : string) =
            if System.Char.IsAsciiDigit suffix.[0] then None
            else suffix.Split('_', System.StringSplitOptions.RemoveEmptyEntries) |> Array.map (fun part -> string (System.Char.ToUpperInvariant part.[0]) + part.Substring 1) |> String.concat "" |> Some
        let shaped = generatedCaseSuffixes cases |> Array.map upper_camel
        let uses = shaped |> Array.choose id |> Array.countBy id |> dict
        match shaped.[position] with
        | Some name when uses.[name] = 1 -> prefix_tag + name
        | _ -> $"{prefix_tag}i{position}"

    /// ### UnusedGlobals
    module UnusedGlobals =
        let private declaration =
            System.Text.RegularExpressions.Regex(@"^(?:(?:private|inline|local|static|async)\s+|extern\s+""[^""]*""\s+)*(?:fn|func|fun|function|def|const|let|var|type|struct|class|enum|interface|module)\s+([A-Za-z_][A-Za-z0-9_]*)")
        let private isFragment (text : string) = System.String.IsNullOrEmpty text || System.Char.IsWhiteSpace text.[0] || text.[0] = '}'
        let private exported = System.Text.RegularExpressions.Regex(@"(?<![A-Za-z0-9_])(?:pub|export)(?![A-Za-z0-9_])")
        let private singleItem (text : string) =
            let topLevel =
                text.Split('\n')
                |> Array.map (fun line -> line.TrimEnd('\r'))
                |> Array.filter (fun line -> line.Length > 0 && not (System.Char.IsWhiteSpace line.[0]) && line.TrimEnd(';', ')', ']') <> "}")
            topLevel.Length = 1 && not (exported.IsMatch text)
        let private mentions (name : string) (text : string) =
            System.Text.RegularExpressions.Regex.Matches(text, $@"(?<![A-Za-z0-9_]){System.Text.RegularExpressions.Regex.Escape name}(?![A-Za-z0-9_])").Count
        let private removeOnce (code : string) (text : string) =
            let at = code.IndexOf(text + "\n", System.StringComparison.Ordinal)
            if at >= 0 then code.Remove(at, text.Length + 1)
            else
                let atCrlf = code.IndexOf(text + "\r\n", System.StringComparison.Ordinal)
                if atCrlf >= 0 then code.Remove(atCrlf, text.Length + 2) else code
        let prune (globals : ResizeArray<string>) (code : string) =
            let entries = globals |> Seq.toArray
            let candidates =
                entries |> Array.mapi (fun i text ->
                    let m = declaration.Match text
                    let headsFragments = i + 1 < entries.Length && isFragment entries.[i + 1]
                    if m.Success && not (isFragment text) && not headsFragments && singleItem text && code.Contains(text, System.StringComparison.Ordinal) then Some (text, m.Groups.[1].Value) else None)
                |> Array.choose id
            let rec settle (code : string) (left : (string * string) []) =
                let unused = left |> Array.filter (fun (text, name) -> mentions name code <= mentions name text)
                if unused.Length = 0 then code
                else
                    let code = unused |> Array.fold (fun code (text, _) -> removeOnce code text) code
                    settle code (left |> Array.filter (fun entry -> not (Array.contains entry unused)))
            if candidates.Length = 0 then code else settle code candidates

    /// ### DeadPureLetElision
    module DeadPureLetElision =
        let pureOp op =
            match op with
            | Op.Add | Op.Sub | Op.Mult | Op.Pow | Op.LTE | Op.LT | Op.EQ | Op.NEQ | Op.GT | Op.GTE | Op.BoolAnd | Op.BoolOr
            | Op.BitwiseAnd | Op.BitwiseOr | Op.BitwiseXor | Op.BitwiseComplement | Op.ShiftLeft | Op.ShiftRight
            | Op.Neg | Op.Tanh | Op.Log | Op.Exp | Op.Sin | Op.Cos | Op.Sqrt | Op.NanIs | Op.UnionTag | Op.StringLength | Op.ArrayLength | Op.StaticStringConcat
            | Op.Dyn -> true
            | _ -> false
        let pureTypedOp op =
            match op with
            | TyOp(op, _) -> pureOp op
            | TyUnionBox _ | TyToLayout _ | TyLayoutIndexAll _ | TyLayoutIndexByKey _ | TyArrayLength _ | TyStringLength _
            | TySizeOf _ | TyConv _ | TyArrayLiteral _ -> true
            | _ -> false
        let rec pureBlock (block : TypedBind []) =
            block |> Array.forall (function
                | TyLet(_, _, op) | TyLocalReturnOp(_, op, _) -> pureBranchingOp op
                | TyLocalReturnData _ -> true)
        and pureBranchingOp op =
            match op with
            | TyIf(_, tr, fl) -> pureBlock tr && pureBlock fl
            | TyUnionUnbox(_, _, on_succs, on_fail) -> Map.forall (fun _ (_, block) -> pureBlock block) on_succs && Option.forall pureBlock on_fail
            | TyIntSwitch(_, cases, on_fail) -> Array.forall pureBlock cases && pureBlock on_fail
            | _ -> pureTypedOp op
        let tagOf (L(tag, _) : TyV) = tag
        let markData (live : HashSet<int>) d = for v in data_free_vars d do live.Add (tagOf v) |> ignore
        let markVar (live : HashSet<int>) (v : TyV) = live.Add (tagOf v) |> ignore
        let rec markBlock live (block : TypedBind []) = for x in block do markBind live x
        and markBind live x =
            match x with
            | TyLet(d, _, op) -> markData live d; markOp live op
            | TyLocalReturnOp(_, op, d) -> markOp live op; markData live d
            | TyLocalReturnData(d, _) -> markData live d
        and markOp live op =
            match op with
            | TyMacro parts -> for part in parts do (match part with CMTerm(d, _) -> markData live d | _ -> ())
            | TyOp(_, args) | TyArrayLiteral(_, args) -> for d in args do markData live d
            | TyUnionBox(_, d, _) | TyToLayout(d, _) | TyFailwith(_, d) | TyConv(_, d)
            | TyArrayCreate(_, d) | TyArrayLength(_, d) | TyStringLength(_, d) -> markData live d
            | TyUnionUnbox(vs, _, on_succs, on_fail) ->
                for v in vs do markVar live v
                for KeyValue(_, (bound, block)) in on_succs do
                    for d in bound do markData live d
                    markBlock live block
                on_fail |> Option.iter (markBlock live)
            | TyIntSwitch(v, cases, on_fail) -> markVar live v; (for block in cases do markBlock live block); markBlock live on_fail
            | TyLayoutIndexAll v | TyLayoutIndexByKey(v, _) -> markVar live v
            | TyLayoutMutableSet(v, _, d) | TyApply(v, d) -> markVar live v; markData live d
            | TyIf(cond, tr, fl) -> markData live cond; markBlock live tr; markBlock live fl
            | TyWhile((_, args), block) -> (for v in args do markVar live v); markBlock live block
            | TyDo block | TyIndent block -> markBlock live block
            | TyJoinPoint(_, args) -> for v in args do markVar live v
            | TySizeOf _ | TyBackend _ -> ()
        let isDead (live : HashSet<int>) x =
            match x with
            | TyLet(d, _, op) -> pureBranchingOp op && data_free_vars d |> Seq.forall (fun v -> live.Contains (tagOf v) |> not)
            | _ -> false
        let sameItems (a : 'a []) (b : 'a []) = a.Length = b.Length && Array.forall2 (fun x y -> obj.ReferenceEquals(x, y)) a b
        let dataOfLeaves (leaves : Data []) =
            match leaves with
            | [|leaf|] -> leaf
            | _ -> Array.foldBack (fun leaf rest -> DPair(leaf, rest)) leaves DB
        let leafData = function WV v -> DV v | WLit l -> DLit l
        let keepLiveLeaves (keep : bool []) (d : Data) =
            let leaves = data_term_vars d
            if leaves.Length <> keep.Length then None
            else leaves |> Array.indexed |> Array.choose (fun (i, leaf) -> if keep.[i] then Some (leafData leaf) else None) |> dataOfLeaves |> Some
        let rec pruneBlockReturns (keep : bool []) (block : TypedBind []) : TypedBind [] option =
            if block.Length = 0 then None
            else
                let last = block.Length - 1
                let rebuilt =
                    match block.[last] with
                    | TyLocalReturnData(d, trace) -> keepLiveLeaves keep d |> Option.map (fun d' -> TyLocalReturnData(d', trace))
                    | TyLocalReturnOp(trace, op, d) ->
                        match keepLiveLeaves keep d, pruneOpReturns keep op with
                        | Some d', Some op' -> Some (TyLocalReturnOp(trace, op', d'))
                        | _ -> None
                    | TyLet _ -> None
                rebuilt |> Option.map (fun x -> Array.append block.[.. last - 1] [|x|])
        and pruneOpReturns (keep : bool []) op =
            let all (blocks : TypedBind [] list) = blocks |> List.map (pruneBlockReturns keep) |> fun xs -> if List.forall Option.isSome xs then Some (List.map Option.get xs) else None
            match op with
            | TyIf(cond, tr, fl) -> all [tr; fl] |> Option.map (function [tr'; fl'] -> TyIf(cond, tr', fl') | _ -> op)
            | TyUnionUnbox(vs, u, on_succs, on_fail) ->
                let keys = on_succs |> Map.toList |> List.map fst
                let blocks = (on_succs |> Map.toList |> List.map (snd >> snd)) @ (Option.toList on_fail)
                all blocks |> Option.map (fun blocks' ->
                    let succs' = List.zip keys (List.take keys.Length blocks') |> List.fold (fun m (k, b) -> Map.add k (fst on_succs.[k], b) m) on_succs
                    let fail' = match on_fail with Some _ -> Some (List.last blocks') | None -> None
                    TyUnionUnbox(vs, u, succs', fail'))
            | TyIntSwitch(v, cases, on_fail) ->
                all (List.ofArray cases @ [on_fail]) |> Option.map (fun blocks' -> TyIntSwitch(v, Array.ofList (List.take cases.Length blocks'), List.last blocks'))
            | _ -> None
        let rec elide (block : TypedBind []) : TypedBind [] =
            let live = HashSet<int>()
            let kept = ResizeArray<TypedBind>()
            for i = block.Length - 1 downto 0 do
                let original = block.[i]
                let x =
                    match original with
                    | TyLet(d, trace, op) when pureBranchingOp op ->
                        let vars = data_free_vars d
                        let keep = vars |> Array.map (fun v -> live.Contains (tagOf v))
                        if vars.Length > 1 && Array.exists not keep && Array.exists id keep then
                            match pruneOpReturns keep op with
                            | Some op' -> rewriteBind (TyLet(vars |> Array.indexed |> Array.choose (fun (i, v) -> if keep.[i] then Some (DV v) else None) |> dataOfLeaves, trace, op'))
                            | None -> rewriteBind original
                        else rewriteBind original
                    | _ -> rewriteBind original
                if isDead live x |> not then
                    markBind live x
                    kept.Add x
            kept.Reverse()
            let kept = kept.ToArray()
            if sameItems kept block then block else kept
        and rewriteBind x =
            match x with
            | TyLet(d, trace, op) -> let op' = rewriteOp op in if obj.ReferenceEquals(op', op) then x else TyLet(d, trace, op')
            | TyLocalReturnOp(trace, op, d) -> let op' = rewriteOp op in if obj.ReferenceEquals(op', op) then x else TyLocalReturnOp(trace, op', d)
            | TyLocalReturnData _ -> x
        and rewriteOp op =
            match op with
            | TyIf(cond, tr, fl) ->
                let tr', fl' = elide tr, elide fl
                if obj.ReferenceEquals(tr', tr) && obj.ReferenceEquals(fl', fl) then op else TyIf(cond, tr', fl')
            | TyUnionUnbox(vs, u, on_succs, on_fail) ->
                let on_succs' = on_succs |> Map.map (fun _ (bound, block) -> bound, elide block)
                let on_fail' = on_fail |> Option.map elide
                let unchanged =
                    Map.forall (fun k (_, block) -> obj.ReferenceEquals(snd on_succs'.[k], block)) on_succs
                    && (match on_fail, on_fail' with Some a, Some b -> obj.ReferenceEquals(a, b) | _ -> true)
                if unchanged then op else TyUnionUnbox(vs, u, on_succs', on_fail')
            | TyIntSwitch(v, cases, on_fail) ->
                let cases', on_fail' = Array.map elide cases, elide on_fail
                if sameItems cases' cases && obj.ReferenceEquals(on_fail', on_fail) then op else TyIntSwitch(v, cases', on_fail')
            | TyWhile(cond, block) -> let block' = elide block in if obj.ReferenceEquals(block', block) then op else TyWhile(cond, block')
            | TyDo block -> let block' = elide block in if obj.ReferenceEquals(block', block) then op else TyDo block'
            | TyIndent block -> let block' = elide block in if obj.ReferenceEquals(block', block) then op else TyIndent block'
            | _ -> op
        let elided = System.Runtime.CompilerServices.ConditionalWeakTable<TypedBind [], TypedBind []>()
        let block (body : TypedBind []) : TypedBind [] = elided.GetValue(body, fun body -> elide body)

    /// ### exportedUnionNames
    let exportedUnionNames (env : PartEvalResult) (x : TypedBind []) =
        let names = Dictionary<obj, string>(HashIdentity.Reference)
        let declared = Dictionary<string, obj>()
        let visited = HashSet<obj>(HashIdentity.Reference)
        let declaredIn (node : obj) =
            match unionSourcePackages.TryGetValue node with
            | true, id -> Map.tryFind id.Value packageDirsById.Value |> Option.defaultValue $"package {id.Value}"
            | _ -> "an unknown package"
        let rec walk (t : Ty) =
            match t with
            | YUnion u when visited.Add(box u) ->
                match unionSourceNames.TryGetValue(box u) with
                | true, source ->
                    let clean = source |> String.map (fun c -> if System.Char.IsLetterOrDigit c || c = '_' then c else '_')
                    match declared.TryGetValue clean with
                    | true, other ->
                        raise_codegen_error $"Two unions reached by this unit's exports are both named {clean}: {show_ty (YUnion (unbox<Union> other))} declared in {declaredIn other}, and {show_ty (YUnion u)} declared in {declaredIn (box u)}. A linked unit exports each union under its source name; rename one of the two declarations."
                    | _ ->
                        declared.[clean] <- box u
                        names.[box u] <- clean
                | _ -> ()
                u.Item.cases |> Map.iter (fun _ v -> walk v)
            | YNominal _ | YApply _ -> walk (env.nominal_apply t)
            | YPair(a,b) | YFun(a,b,_) -> walk a; walk b
            | YRecord m -> m |> Map.iter (fun _ v -> walk v)
            | YArray a | YLayout(a,_) -> walk a
            | _ -> ()
        x |> Array.iter (function
            | TyLet(_,_,TyOp(Export, [_; DV(L(_,YFun(domain,range,_)))])) | TyLocalReturnOp(_,TyOp(Export, [_; DV(L(_,YFun(domain,range,_)))]),_) -> walk domain; walk range
            | _ -> ())
        names

    /// ### linkedUnionName
    /// The unit and exported name of a union that comes from a `link:` unit. A built unit's graph owns only the unions its
    /// exports reach, matched by source name and concrete shape; every other union of that package stays local. A union
    /// declared outside every linked unit (core's list or option instantiated over a unit's types) belongs to the first
    /// linked unit whose graph reached the same source name and shape, so every crate shares that unit's copy.
    let linkedUnionName (linked : Map<int, LinkedUnit>) (node : obj) (source : string) =
        let shape = show_ty (YUnion (unbox<Union> node))
        let caseNames (shape : string) =
            let names = HashSet<string>()
            let mutable depth = 0
            let mutable i = 0
            while i < shape.Length do
                let c = shape.[i]
                if c = '{' || c = '(' || c = '[' then depth <- depth + 1
                elif c = '}' || c = ')' || c = ']' then depth <- depth - 1
                if depth = 1 && (c = '{' || c = '|') then
                    let mutable j = i + 1
                    while j < shape.Length && shape.[j] = ' ' do j <- j + 1
                    let start = j
                    while j < shape.Length && (System.Char.IsLetterOrDigit shape.[j] || shape.[j] = '_') do j <- j + 1
                    if j > start then names.Add(shape.Substring(start, j - start)) |> ignore
                i <- i + 1
            Set.ofSeq names
        match unionOwnerUnit linked node with
        | Some {unit = unit; exported = Some exported} ->
            match exported |> Map.tryFind (source, shape) with
            | Some name -> Some (unit, name)
            | None ->
                let cases = caseNames shape
                match exported |> Map.toSeq |> Seq.tryPick (fun ((s, recorded), _) -> if s = source && caseNames recorded <> cases then Some recorded else None) with
                | Some recorded -> raise_codegen_error $"The link: unit {unit}'s unit graph records union {source} as {recorded}, but this build declares it as {shape}. The graph is stale: rebuild {unit}, and every unit between it and this one, before this unit."
                | None -> None
        | Some {unit = unit; exported = None} -> raise_codegen_error $"The link: unit {unit} has no unit graph ({unit}/*.unit.json). Build {unit} before the units that link it."
        | None -> linked |> Map.toSeq |> Seq.tryPick (fun (_, l) -> l.exported |> Option.bind (Map.tryFind (source, shape)) |> Option.map (fun name -> l.unit, name))

    /// ### unitGraphJson
    /// What a unit with exports writes beside its input as `<stem>.unit.json`: its exports with their signatures, the units
    /// it links, and each union its exports reach (source name, concrete shape, exported name). Importers read the unions
    /// through `link:`; kit generates Cargo dependencies from the links.
    let unitGraphJson (links : string list) (env : PartEvalResult) (x : TypedBind []) =
        let closure_bodies = Dictionary<int, E>()
        x |> Array.iter (function TyLet(DV(L(i,_)),_,TyJoinPoint(JPClosure((_,e),_),_)) -> closure_bodies.[i] <- e | _ -> ())
        let target i =
            match closure_bodies.TryGetValue i with
            | true, e -> (match definitionSources.TryGetValue e with | true, t -> t | _ -> match curriedDefinitionSources.TryGetValue e with | true, t -> t | _ -> ("", ""))
            | _ -> ("", "")
        let wraps i =
            let rec head (f : E) =
                match f with
                | EApply(_, g, _) | EAnnot(_, g, _) | ETypeApply(_, g, _) -> head g
                | ERecursive r -> head r.Value
                | g -> g
            let rec peel (e : E) =
                match e with
                | EFun'(_, _, _, body, _) | EFun(_, _, body, _) | EForall'(_, _, _, body) | EAnnot(_, body, _) -> peel body
                | EApply(_, f, _) ->
                    let h = head f
                    match definitionSources.TryGetValue h with
                    | true, t -> Some t
                    | _ -> match curriedDefinitionSources.TryGetValue h with | true, t -> Some t | _ -> None
                | _ -> None
            match closure_bodies.TryGetValue i with
            | true, e -> peel e
            | _ -> None
        let exports =
            x |> Array.choose (function
                | TyLet(_,_,TyOp(Export, [DLit (LitString name); DV(L(i,(YFun _ as t)))])) | TyLocalReturnOp(_,TyOp(Export, [DLit (LitString name); DV(L(i,(YFun _ as t)))]),_) ->
                    let path, source = target i
                    let rec unresolved (t : Ty) =
                        match t with
                        | YMetavar _ | YForall | YTypeFunction _ -> true
                        | YPair(a, b) | YFun(a, b, _) | YApply(a, b) -> unresolved a || unresolved b
                        | YRecord m -> m |> Map.exists (fun _ v -> unresolved v)
                        | YArray a | YLayout(a, _) -> unresolved a
                        | _ -> false
                    if unresolved t then
                        raise_codegen_error $"The export {name} has a signature with an unresolved type: {show_ty t}. A linked unit's exports must be concrete; wrap a type parameter or a GADT index in an existential at the boundary (the EJP0041 fix)."
                    Some {| name = name; signature = show_ty t; target_path = path; target_name = source |}
                | _ -> None)
        if exports.Length = 0 then None
        else
            let unions =
                [| for KeyValue(node, name) in exportedUnionNames env x ->
                    {| source = (match unionSourceNames.TryGetValue node with | true, source -> source | _ -> name); shape = show_ty (YUnion (unbox<Union> node)); name = name |} |]
                |> Array.sortBy (fun u -> u.name)
            let wrapped =
                x |> Array.choose (function
                    | TyLet(_,_,TyOp(Export, [DLit (LitString name); DV(L(i,YFun _))])) | TyLocalReturnOp(_,TyOp(Export, [DLit (LitString name); DV(L(i,YFun _))]),_) when fst (target i) = "" ->
                        wraps i |> Option.map (fun (path, definition) -> {| export = name; path = path; name = definition |})
                    | _ -> None)
            let options = System.Text.Json.JsonSerializerOptions(WriteIndented = true, DefaultIgnoreCondition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)
            Some (System.Text.Json.JsonSerializer.Serialize({| exports = exports; links = links; unions = unions; wraps = (if Array.isEmpty wrapped then null else wrapped) |}, options))

    /// ### unitGraphDir
    /// Where a unit's graph lives: outside the source tree, in the user cache under a key of the unit's package folder
    /// (`SPIRAL_UNIT_GRAPH_DIR` overrides the root), so a build never writes into a repo.
    let unitGraphDir (packageDir : string) =
        let root =
            match System.Environment.GetEnvironmentVariable "SPIRAL_UNIT_GRAPH_DIR" with
            | null | "" -> System.IO.Path.Combine(System.Environment.GetFolderPath System.Environment.SpecialFolder.LocalApplicationData, "spiral-bin", "units")
            | dir -> dir
        let key = packageDir.Replace('\\', '/').TrimEnd('/').ToLowerInvariant()
        let hash = System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes key) |> Array.take 8 |> Array.map (fun b -> b.ToString "x2") |> String.concat ""
        System.IO.Path.Combine(root, hash)

    /// ### writeUnitGraph
    let writeUnitGraph (packageDir : string) (file : string) (linked : Map<int, LinkedUnit>) (env : PartEvalResult) (x : TypedBind []) =
        let path = System.IO.Path.Combine(unitGraphDir packageDir, System.IO.Path.GetFileNameWithoutExtension file + ".unit.json")
        match unitGraphJson (linked |> Map.toList |> List.map (fun (_, l) -> l.unit)) env x with
        | Some json when not (System.IO.File.Exists path && System.IO.File.ReadAllText path = json) ->
            System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName path) |> ignore
            System.IO.File.WriteAllText(path, json)
        | Some _ -> ()
        | None -> if System.IO.File.Exists path then System.IO.File.Delete path

    /// ## CodegenAdapter
    module UnionTagIdOps =
        let text (tag : string) = tag
    module LayoutFieldNameIdOps =
        let matchesText (fieldId : string) (text : string) = fieldId = text
    let codegenMethodKeyArgs (key : ConsedNode<RData [] * Ty []>) = fst key.node
    let codegenMemoTable (comparer : IEqualityComparer<'k>) : Dictionary<'k, 'v> = Dictionary(comparer)
    type RefcDecrTable = Dictionary<TypedBind, TyV Set>
    let refcDecrTable () : RefcDecrTable = Dictionary(HashIdentity.Reference)
    let refcDecrAdd (table : RefcDecrTable) key value = table.Add(key, value)
    let codegenMethodBody (env : PartEvalResult) (_ : string) jp_body key =
        match (fst env.join_point_method.[jp_body]).[key] with
        | Some body, Some range, name -> DeadPureLetElision.block body, range, name
        | _ -> raise_codegen_error "Compiler error: The method dictionary is malformed"
    let codegenClosureBody (env : PartEvalResult) (_ : string) jp_body key =
        match (fst env.join_point_closure.[jp_body]).[key] with
        | Some(domain_args, body) -> domain_args, DeadPureLetElision.block body, closureSourceName (snd jp_body)
        | _ -> raise_codegen_error "Compiler error: The closure dictionary is malformed"
    let codegenOwnerBackendName (jp_body : string ConsedNode * E) = (fst jp_body).node
    let codegenFsharpMethodBody (env : PartEvalResult) jp_body key (_ : int) =
        match (fst env.join_point_method.[jp_body]).[key] with
        | Some a, Some range, sourceName -> a, range, sourceName
        | _ -> raise_codegen_error "Compiler error: The method dictionary is malformed"
    let codegenFsharpClosureBody (env : PartEvalResult) jp_body key (_ : int) =
        match (fst env.join_point_closure.[jp_body]).[key] with
        | Some(domain_args, body) -> domain_args, body, closureSourceName (snd jp_body)
        | _ -> raise_codegen_error "Compiler error: The method dictionary is malformed"

    /// ## CodegenFsharp

    /// ### backend_nameFsharp
    let backend_nameFsharp = "Fsharp"

    /// ### litFsharp
    let litFsharp = function
        | LitInt8 x -> sprintf "%iy" x
        | LitInt16 x -> sprintf "%is" x
        | LitInt32 x -> sprintf "%i" x
        | LitInt64 x -> sprintf "%iL" x
        | LitUInt8 x -> sprintf "%iuy" x
        | LitUInt16 x -> sprintf "%ius" x
        | LitUInt32 x -> sprintf "%iu" x
        | LitUInt64 x -> sprintf "%iUL" x
        | LitFloat32 x ->
            if x = infinityf then "infinityf"
            elif x = -infinityf then "-infinityf"
            elif Single.IsNaN x then "nanf"
            else x.ToString("R") |> add_dec_point |> sprintf "%sf"
        | LitFloat64 x ->
            if x = infinity then "infinity"
            elif x = -infinity then "-infinity"
            elif Double.IsNaN x then "nan"
            else x.ToString("R") |> add_dec_point
        | LitString x ->
            let strb = StringBuilder(x.Length+2)
            strb.Append '"' |> ignore
            String.iter (function
                | '"' -> strb.Append "\\\""
                | '\b' -> strb.Append @"\b"
                | '\t' -> strb.Append @"\t"
                | '\n' -> strb.Append @"\n"
                | '\r' -> strb.Append @"\r"
                | '\\' -> strb.Append @"\\"
                | x -> strb.Append x
                >> ignore
                ) x
            strb.Append '"' |> ignore
            strb.ToString()
        | LitChar x ->
            match x with
            | '\b' -> @"\b"
            | '\n' -> @"\n"
            | '\t' -> @"\t"
            | '\r' -> @"\r"
            | '\\' -> @"\\"
            | '\000' -> @"\000"
            | x -> string x
            |> sprintf "'%s'"
        | LitBool x -> if x then "true" else "false"

    /// ### primFsharp
    let primFsharp = function
        | Int8T -> "int8"
        | Int16T -> "int16"
        | Int32T -> "int32"
        | Int64T -> "int64"
        | UInt8T -> "uint8"
        | UInt16T -> "uint16"
        | UInt32T -> "uint32"
        | UInt64T -> "uint64"
        | Float32T -> "float32"
        | Float64T -> "float"
        | BoolT -> "bool"
        | StringT -> "string"
        | CharT -> "char"

    /// ### type_litFsharp
    let type_litFsharp = function
        | YLit x -> litFsharp x
        | YSymbol x -> x
        | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."

    /// ### UnionRecFsharp
    type UnionRecFsharp = {tag : int; free_vars : Map<int * string, TyV[]>}

    /// ### LayoutRecFsharp
    type LayoutRecFsharp = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>}

    /// ### MethodRecFsharp
    type MethodRecFsharp = {tag : int; free_vars : L<Tag,Ty>[]; range : Ty; body : TypedBind[]}

    /// ### ClosureRecFsharp
    type ClosureRecFsharp = {tag : int; free_vars : L<Tag,Ty>[]; domain_args : TyV[]; range : Ty; body : TypedBind[]}

    /// ### codegenFsharp
    let codegenFsharp (env : PartEvalResult) (x : TypedBind []) =
        let method_names = Dictionary<int, string>()
        let closure_names = Dictionary<int, string>()
        let types = ResizeArray()
        let functions = ResizeArray()
        let exports = ResizeArray<string>()
        let export_names = HashSet<string>()
        let closure_of_var = Dictionary<int, int>()

        let print is_type show r =
            let s = {text=StringBuilder(); indent=0}
            show s r
            let text = s.text.ToString()
            if is_type then types.Add(text) else functions.Add(text)

        let layout show =
            let dict' = Dictionary(HashIdentity.Structural)
            let dict = Dictionary(HashIdentity.Reference)
            let f x : LayoutRecFsharp =
                match x with
                | YLayout(x,_) ->
                let x = env.ty_to_data x
                let a, b =
                    match x with
                    | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                    | _ -> data_free_vars x, Map.empty
                {data=x; free_vars=a; free_vars_by_key=b; tag=dict'.Count}
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (3).\nGot: %s{show_ty x}"
            fun x ->
                let mutable dirty = false
                let r = memoize dict (memoize dict' (fun x -> dirty <- true; f x)) x
                if dirty then print true show r
                r

        let union show =
            let dict = Dictionary(HashIdentity.Reference)
            let f (a : Map<int * string,Ty>) : UnionRecFsharp = {free_vars=a |> Map.map (fun _ -> env.ty_to_data >> data_free_vars); tag=dict.Count}
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print true show r
                r

        let jp f show =
            let dict = Dictionary(HashIdentity.Structural)
            let f x = f (x, dict.Count)
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print false show r
                r

        let args x = x |> Array.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "
        let show_w = function WV (L(i,_)) -> sprintf "v%i" i | WLit a -> litFsharp a
        let args' x = x |> data_term_vars |> Array.map show_w |> String.concat ", "

        let global' =
            let has_added = HashSet env.globals
            let preserves_duplicate_fragment (x : string) =
                System.String.IsNullOrEmpty x
                || ((System.Char.IsWhiteSpace x.[0] || x.[0] = '}') && not (x.TrimEnd().Contains '\n'))
            fun x -> if preserves_duplicate_fragment x || has_added.Add(x) then env.globals.Add x

        let rec macro_assigned_binds (x : TypedBind []) : Set<int> =
            x |> Array.fold (fun s -> function TyLet(_,_,o) | TyLocalReturnOp(_,o,_) -> s + macro_assigned_op o | TyLocalReturnData _ -> s) Set.empty
        and macro_assigned_op (x : TypedOp) : Set<int> =
            match x with
            | TyMacro parts ->
                let rec targets acc = function
                    | CMTerm (d,_) :: (CMText text :: _ as rest) when text.TrimStart().StartsWith "<-" ->
                        targets (data_free_vars d |> Array.fold (fun s (L(i,_)) -> Set.add i s) acc) rest
                    | _ :: rest -> targets acc rest
                    | [] -> acc
                targets Set.empty parts
            | TyWhile(_,body) | TyDo body | TyIndent body -> macro_assigned_binds body
            | TyIf(_,tr,fl) -> macro_assigned_binds tr + macro_assigned_binds fl
            | TyUnionUnbox(_,_,on_succs,on_fail) ->
                Map.fold (fun s _ (_,body) -> s + macro_assigned_binds body) (match on_fail with Some x -> macro_assigned_binds x | None -> Set.empty) on_succs
            | TyIntSwitch(_,on_succs,on_fail) -> Array.fold (fun s body -> s + macro_assigned_binds body) (macro_assigned_binds on_fail) on_succs
            | TyOp(Assign, [DV(L(i,_)); _]) -> Set.singleton i
            | _ -> Set.empty
        let mutable macro_assigned : Set<int> = Set.empty
        let with_macro_assigned (body : TypedBind []) (emit : unit -> unit) =
            let outer = macro_assigned
            macro_assigned <- macro_assigned_binds body
            emit ()
            macro_assigned <- outer

        let rec tyv x =
            match x with
            | YUnion a ->
                let a = a.Item
                match a.layout with
                | UHeap -> sprintf "UH%i" (uheap a.cases).tag
                | UStack -> sprintf "US%i" (ustack a.cases).tag
            | YLayout(_,lay) as a ->
                match lay with
                | Heap -> sprintf "Heap%i" (heap a).tag
                | HeapMutable -> sprintf "Mut%i" (mut a).tag
                | StackMutable -> raise_codegen_error "Compiler error: The F# backend doesn't support stack mutable layout types."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
            | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameFsharp then Some v else None) with
                | Some x -> tup_ty x
                | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{backend_nameFsharp}' field."
            | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_litFsharp a) |> String.concat ""
            | YPrim a -> primFsharp a
            | YArray a -> sprintf "(%s [])" (tup_ty a)
            | YFun(a,b,(FT_Vanilla | FT_Pointer)) -> sprintf "(%s -> %s)" (tup_ty a) (tup_ty b)
            | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
            | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
            | a -> raise_codegen_error $"Type not supported in the codegen.\nGot: %A{a}"
        and args_tys x = x |> Array.map (fun (L(i,t)) -> sprintf "v%i : %s" i (tup_ty t)) |> String.concat ", "
        and binds (s : CodegenEnv) (x : TypedBind []) =
            Array.iter (function
                | TyLet(d,trace,a) -> try op s (Some d) a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) -> try op s None a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) -> try line s (tup d) with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) x
        and tup x =
            match data_term_vars x with
            | [||] -> "()"
            | [|x|] -> show_w x
            | x -> Array.map show_w x |> String.concat ", " |> sprintf "struct (%s)"
        and tup_ty x =
            match env.ty_to_data x |> data_free_vars |> Array.map (fun (L(_,x)) -> tyv x) with
            | [||] -> "unit"
            | [|x|] -> x
            | x -> String.concat " * " x |> sprintf "struct (%s)"
        and op s d a =
            let jp (a, b) =
                let args = args b
                match a with
                | JPMethod(a,b) -> sprintf "%s(%s)" method_names.[(method (a,b)).tag] args
                | JPClosure(a,b) -> sprintf "%s(%s)" closure_names.[(closure (a,b)).tag] args
            let free_vars do_annot x =
                let f (L(i,t)) = if do_annot then sprintf "v%i : %s" i (tyv t) else sprintf "v%i" i
                match data_free_vars x with
                | [||] -> "()"
                | [|x|] -> f x
                | x -> Array.map f x |> String.concat ", " |> sprintf "struct (%s)"
            let declared d =
                match data_free_vars d with
                | [|L(i,_)|] when macro_assigned.Contains i -> "mutable " + free_vars true d
                | _ -> free_vars true d
            let simple x =
                match d with
                | None -> x
                | Some d -> match declared d with "()" -> x | d -> sprintf "let %s = %s" d x
                |> line s
            let complex f =
                match d with
                | None -> f s : unit
                | Some d -> match declared d with "()" -> f s | d -> line s (sprintf "let %s =" d); f (indent s)
            let layout_vars a =
                let f i x =
                    match x with
                    | WV(L(i',_)) -> sprintf "l%i = v%i" i i'
                    | WLit x -> sprintf "l%i = %s" i (litFsharp x)
                a |> data_term_vars |> Array.mapi f |> String.concat "; "
            let layout_index i x =
                x |> Array.map (fun (L(i',_)) -> sprintf "v%i.l%i" i i')
                |> String.concat ", "
                |> function "" -> () | x -> simple x
            let length_of_text a text =
                match a with
                | YPrim UInt8T -> sprintf "System.Convert.ToByte %s" text
                | YPrim UInt16T -> sprintf "System.Convert.ToUInt16 %s" text
                | YPrim UInt32T -> sprintf "System.Convert.ToUInt32 %s" text
                | YPrim UInt64T -> sprintf "System.Convert.ToUInt64 %s" text
                | YPrim Int8T -> sprintf "System.Convert.ToSByte %s" text
                | YPrim Int16T -> sprintf "System.Convert.ToInt16 %s" text
                | YPrim Int32T -> text
                | YPrim Int64T -> sprintf "System.Convert.ToInt64 %s" text
                | _ -> raise_codegen_error "Compiler error: Expected an int in length"
                |> simple
            let length (a,b) = length_of_text a (sprintf "%s.Length" (tup b))
            let utf8_string_helpers () =
                global' "let spiralStringIndex (s : string) (i : int) : char = char (System.Text.Encoding.UTF8.GetBytes(s).[i])"
                global' "let spiralStringSlice (s : string) (from : int) (upto : int) : string =\n    let bytes = System.Text.Encoding.UTF8.GetBytes(s)\n    let length = bytes.Length\n    if from < 0 || from > length || upto < from - 1 || upto >= length then exit 3\n    elif upto < from then \"\"\n    elif (bytes.[from] &&& 0xC0uy) = 0x80uy || (upto + 1 < length && (bytes.[upto + 1] &&& 0xC0uy) = 0x80uy) then exit 3\n    else System.Text.Encoding.UTF8.GetString(bytes, from, upto - from + 1)"
            match a with
            | TyMacro a -> a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup x) | CMType x -> tup_ty x | CMTypeLit x -> type_litFsharp x) |> String.concat "" |> simple
            | TySizeOf t -> simple $"sizeof<{tup_ty t}>"
            | TyIf(cond,tr,fl) ->
                complex <| fun s ->
                line s (sprintf "if %s then" (tup cond))
                binds (indent s) tr
                match fl with
                | [|TyLocalReturnData(DB,_)|] -> ()
                | _ ->
                    line s "else"
                    binds (indent s) fl
            | TyJoinPoint(JPClosure(a,c) as a',args) ->
                match d with
                | Some (DV(L(i,_))) when args.Length = 0 -> closure_of_var.[i] <- (closure (a,c)).tag
                | _ -> ()
                simple (jp (a', args))
            | TyJoinPoint(a,args) -> simple (jp (a, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The F# backend does not support nesting other backends."
            | TyWhile(a,b) ->
                complex <| fun s ->
                line s (sprintf "while %s do" (jp a))
                binds (indent s) b
            | TyDo a ->
                complex <| fun s ->
                line s "do"
                binds (indent s) a
            | TyIndent a ->
                complex <| fun s ->
                binds (indent s) a
            | TyIntSwitch(L(i,_),on_succ,on_fail) ->
                complex <| fun s ->
                line s (sprintf "match v%i with" i)
                Array.iteri (fun i x ->
                    line s (sprintf "| %i ->" i)
                    binds (indent s) x
                    ) on_succ
                line s "| _ ->"
                binds (indent s) on_fail
            | TyUnionUnbox(is,x,on_succs,on_fail) ->
                complex <| fun s ->
                line s (sprintf "match %s with" (is |> List.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "))
                let union_rec, prefix =
                    let x = x.Item
                    match x.layout with
                    | UHeap -> let u = uheap x.cases in u, sprintf "UH%i" u.tag
                    | UStack -> let u = ustack x.cases in u, sprintf "US%i" u.tag
                let case_index k =
                    union_rec.free_vars
                    |> Seq.map (fun (KeyValue ((_,k'),_)) -> k')
                    |> Seq.tryFindIndex (fun k' -> UnionTagIdOps.text k = k')
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text k}.")
                Map.iter (fun k (a,b) ->
                    let i = case_index k
                    let cases =
                        a |> List.map (fun a ->
                            match data_free_vars a with
                            | [||] -> ""
                            | x -> sprintf "(%s)" (args x)
                            |> sprintf "%s%s" (generatedCaseName prefix union_rec.free_vars i)
                            )
                        |> String.concat ", "
                    line s (sprintf "| %s -> (* %s *)" cases (UnionTagIdOps.text k))
                    binds (indent s) b
                    ) on_succs
                on_fail |> Option.iter (fun b ->
                    line s "| _ ->"
                    binds (indent s) b
                    )
            | TyUnionBox(a,b,c) ->
                let c = c.Item
                let union_rec, prefix =
                    match c.layout with
                    | UHeap -> let u = uheap c.cases in u, sprintf "UH%i" u.tag
                    | UStack -> let u = ustack c.cases in u, sprintf "US%i" u.tag
                let i =
                    union_rec.free_vars
                    |> Seq.map (fun (KeyValue ((_,k),_)) -> k)
                    |> Seq.tryFindIndex (fun k -> UnionTagIdOps.text a = k)
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text a}.")
                let vars =
                    match data_term_vars b with
                    | [||] -> ""
                    | x -> Array.map show_w x |> String.concat ", " |> sprintf "(%s)"
                sprintf "%s%s" (generatedCaseName prefix union_rec.free_vars i) vars |> simple
            | TyToLayout(a,b) ->
                let a = layout_vars a
                match b with
                | YLayout(_,layout) ->
                    match layout with
                    | Heap -> if a = "" then sprintf "Heap%i()" (heap b).tag else sprintf "{%s} : Heap%i" a (heap b).tag
                    | HeapMutable -> if a = "" then sprintf "Mut%i()" (mut b).tag else sprintf "{%s} : Mut%i" a (mut b).tag
                    | StackMutable -> raise_codegen_error "The F# backend doesn't support stack mutable layout types."
                    | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (4).\nGot: %s{show_ty b}"
                |> simple
            | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The F# backend doesn't support indexing into stack mutable layout types."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                |> fun x -> x.free_vars |> layout_index i
            | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The F# backend doesn't support indexing into stack mutable layout types."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                |> fun x ->
                    x.free_vars_by_key
                    |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None)
                    |> Option.iter (layout_index i)
            | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
            | TyLayoutMutableSet(L(i,t),b,c) ->
                let a = List.fold (fun s k ->
                    match s with
                    | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                    | _ -> raise_codegen_error "Compiler error: Expected a record.") (mut t).data b
                Array.iter2 (fun (L(i',_)) b ->
                    line s (sprintf "v%i.l%i <- %s" i i' (show_w b))
                    ) (data_free_vars a) (data_term_vars c)
            | TyArrayLiteral(a,b) -> simple <| sprintf "[|%s|]" (List.map tup b |> String.concat "; ")
            | TyArrayCreate(a,b) ->
                match b with
                | DLit(LitInt32 _) | DV(L(_,YPrim Int32T)) -> simple (sprintf "Array.zeroCreate<%s> (%s)" (tup_ty a) (tup b))
                | _ -> simple (sprintf "Array.zeroCreate<%s> (System.Convert.ToInt32(%s))" (tup_ty a) (tup b))
            | TyArrayLength(a,b) -> length (a,b)
            | TyStringLength(a,b) -> length_of_text a (sprintf "(System.Text.Encoding.UTF8.GetByteCount(%s))" (tup b))
            | TyFailwith(a,b) -> simple (sprintf "failwith<%s> %s" (tup_ty a) (tup b))
            | TyConv(a,b) ->
                let b = tup b
                match a with
                | YPrim Int8T -> $"int8 {b}"
                | YPrim Int16T -> $"int16 {b}"
                | YPrim Int32T -> $"int32 {b}"
                | YPrim Int64T -> $"int64 {b}"
                | YPrim UInt8T -> $"uint8 {b}"
                | YPrim UInt16T -> $"uint16 {b}"
                | YPrim UInt32T -> $"uint32 {b}"
                | YPrim UInt64T -> $"uint64 {b}"
                | YPrim Float32T -> $"float32 {b}"
                | YPrim Float64T -> $"float {b}"
                | _ -> raise_codegen_error $"Compiler error: Unexpected type in Conv. Got: {show_ty a}"
                |> simple
            | TyApply(L(i,_),b) -> sprintf "v%i %s" i (tup b) |> simple
            | TyOp(Global, [DLit (LitString x)]) -> global' x
            | TyOp(Export, [DLit (LitString name); DV(L(i,YFun(domain,range,_)))]) ->
                if not (export_names.Add name) then raise_codegen_error $"Duplicate export: {name}."
                let tag =
                    match closure_of_var.TryGetValue i with
                    | true, tag -> tag
                    | _ -> raise_codegen_error $"Compiler error: the exported function {name} is not a closure without captures."
                let parameters = env.ty_to_data domain |> data_free_vars
                let decl =
                    match parameters |> Array.map (fun (L(k,t)) -> $"v{k} : {tyv t}") with
                    | [||] -> "()"
                    | [|x|] -> $"({x})"
                    | x -> String.concat ", " x |> sprintf "(%s)"
                let call =
                    match parameters |> Array.map (fun (L(k,_)) -> $"v{k}") with
                    | [||] -> "()"
                    | [|x|] -> x
                    | x -> String.concat ", " x |> sprintf "(struct (%s))"
                let closure_name = closure_names.[tag]
                let range_type = tup_ty range
                exports.Add($"let {name} {decl} : {range_type} =\n    {closure_name} () {call}\n")
                if d.IsNone then line s "()"
            | TyOp(op,l) ->
                match op, l with
                | Dyn,[a] -> tup a
                | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                | Assign,[a;b] -> sprintf "%s <- %s" (tup a) (tup b)
                | StringIndex, [a;b] -> utf8_string_helpers (); sprintf "(spiralStringIndex %s (int %s))" (tup a) (tup b)
                | StringSlice, [a;b;c] -> utf8_string_helpers (); sprintf "(spiralStringSlice %s (int %s) (int %s))" (tup a) (tup b) (tup c)
                | StaticStringConcat, [a;b] -> sprintf "(%s + %s)" (tup a) (tup b)
                | ArrayIndex, [a;b] -> sprintf "%s.[int %s]" (tup a) (tup b)
                | ArrayIndexSet, [a;b;c] -> sprintf "%s.[int %s] <- %s" (tup a) (tup b) (tup c)

                // Math
                | Add, [a;b] -> sprintf "%s + %s" (tup a) (tup b)
                | Sub, [a;b] -> sprintf "%s - %s" (tup a) (tup b)
                | Mult, [a;b] -> sprintf "%s * %s" (tup a) (tup b)
                | Div, [a;b] -> sprintf "%s / %s" (tup a) (tup b)
                | Mod, [a;b] -> sprintf "%s %% %s" (tup a) (tup b)
                | Pow, [a;b] -> sprintf "%s ** %s" (tup a) (tup b)
                | LT, [a;b] -> sprintf "%s < %s" (tup a) (tup b)
                | LTE, [a;b] -> sprintf "%s <= %s" (tup a) (tup b)
                | EQ, [a;b] -> sprintf "%s = %s" (tup a) (tup b)
                | NEQ, [a;b] -> sprintf "%s <> %s" (tup a) (tup b)
                | GT, [a;b] -> sprintf "%s > %s" (tup a) (tup b)
                | GTE, [a;b] -> sprintf "%s >= %s" (tup a) (tup b)
                | BoolAnd, [a;b] -> sprintf "%s && %s" (tup a) (tup b)
                | BoolOr, [a;b] -> sprintf "%s || %s" (tup a) (tup b)
                | BitwiseAnd, [a;b] -> sprintf "%s &&& %s" (tup a) (tup b)
                | BitwiseOr, [a;b] -> sprintf "%s ||| %s" (tup a) (tup b)
                | BitwiseXor, [a;b] -> sprintf "%s ^^^ %s" (tup a) (tup b)
                | BitwiseComplement, [a] -> sprintf "~~~%s" (tup a)

                | ShiftLeft, [a;b] -> sprintf "%s <<< %s" (tup a) (tup b)
                | ShiftRight, [a;b] -> sprintf "%s >>> %s" (tup a) (tup b)

                | Neg, [x] -> sprintf " -%s" (tup x)
                | Log, [x] -> sprintf "log %s" (tup x)
                | Exp, [x] -> sprintf "exp %s" (tup x)
                | Tanh, [x] -> sprintf "tanh %s" (tup x)
                | Sqrt, [x] -> sprintf "sqrt %s" (tup x)
                | Sin, [x] -> sprintf "sin %s" (tup x)
                | Cos, [x] -> sprintf "cos %s" (tup x)
                | PrimToString, [x] ->
                    match x with
                    | DLit(LitBool _) | DV(L(_,YPrim BoolT)) -> sprintf "(if %s then \"true\" else \"false\")" (tup x)
                    | _ -> sprintf "(string (%s))" (tup x)
                | NanIs, [x] ->
                    match x with
                    | DLit(LitFloat32 _) | DV(L(_,YPrim Float32T)) -> sprintf "System.Single.IsNaN(%s)" (tup x)
                    | DLit(LitFloat64 _) | DV(L(_,YPrim Float64T)) -> sprintf "System.Double.IsNaN(%s)" (tup x)
                    | _ -> raise_codegen_error "Compiler error: Invalid type in NanIs."
                | UnionTag, [DV(L(i,YUnion h))] ->
                    let h = h.Item
                    let union_rec, prefix =
                        match h.layout with
                        | UHeap -> let u = uheap h.cases in u, sprintf "UH%i" u.tag
                        | UStack -> let u = ustack h.cases in u, sprintf "US%i" u.tag
                    let arms =
                        union_rec.free_vars
                        |> Seq.mapi (fun position (KeyValue ((tag, _), fields)) ->
                            let pattern = generatedCaseName prefix union_rec.free_vars position
                            match fields with
                            | [||] -> $"| {pattern} -> {tag}"
                            | _ -> $"| {pattern} _ -> {tag}"
                        )
                        |> String.concat " "
                    $"(match v{i} with {arms})"
                | Printf, [DLit (LitString fmt); b] ->
                    match printf_pieces fmt (data_term_vars b) with
                    | [] -> "()"
                    | pieces ->
                        pieces |> List.map (function
                            | Choice1Of2 t -> litFsharp (LitString t)
                            | Choice2Of2 ('s', a) -> show_w a
                            | Choice2Of2 (_, a) -> $"string ({show_w a})")
                        |> String.concat " + " |> sprintf "System.Console.Write(%s)"
                | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported" op l.Length
                |> simple
        and heap : _ -> LayoutRecFsharp = layout (fun s x ->
            let b = x.free_vars |> Array.map (fun (L(i,t)) -> sprintf "l%i : %s" i (tyv t)) |> String.concat "; "
            if b = "" then line s (sprintf "Heap%i() = class end" x.tag)
            else line s (sprintf "Heap%i = {%s}" x.tag b)
            )
        and mut : _ -> LayoutRecFsharp = layout (fun s x ->
            let b = x.free_vars |> Array.map (fun (L(i,t)) -> sprintf "mutable l%i : %s" i (tyv t)) |> String.concat "; "
            if b = "" then line s (sprintf "Mut%i() = class end" x.tag)
            else line s (sprintf "Mut%i = {%s}" x.tag b)
            )
        and uheap : _ -> UnionRecFsharp = union (fun s x ->
            line s (sprintf "UH%i =" x.tag)
            x.free_vars |> Seq.iteri (fun position (KeyValue(_, a)) ->
                let case_name = generatedCaseName (sprintf "UH%i" x.tag) x.free_vars position
                match a with
                | [||] -> line (indent s) (sprintf "| %s" case_name)
                | a -> line (indent s) (sprintf "| %s of %s" case_name (a |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat " * "))
                )
            )
        and ustack : _ -> UnionRecFsharp = union (fun s x ->
            line s (sprintf "[<Struct>] US%i =" x.tag)
            x.free_vars |> Seq.iteri (fun position (KeyValue(_, a)) ->
                let case_name = generatedCaseName (sprintf "US%i" x.tag) x.free_vars position
                match a with
                | [||] -> line (indent s) (sprintf "| %s" case_name)
                | a -> line (indent s) (sprintf "| %s of %s" case_name (a |> Array.mapi (fun i' (L(_,t)) -> sprintf "f%i_%i : %s" position i' (tyv t)) |> String.concat " * "))
                )
            )
        and method : _ -> MethodRecFsharp =
            jp (fun ((jp_body,key),i) ->
                let a, range, sourceName = codegenFsharpMethodBody env jp_body key i
                method_names.[i] <- generatedMethodName sourceName i
                {tag=i; free_vars=rdata_free_vars (codegenMethodKeyArgs key); range=range; body=a}
                ) (fun s x ->
                line s (sprintf "%s (%s) : %s =" method_names.[x.tag] (args_tys x.free_vars) (tup_ty x.range))
                with_macro_assigned x.body (fun () -> binds (indent s) x.body)
                )
        and closure : _ -> ClosureRecFsharp =
            jp (fun ((jp_body,key & (C(args,_,fun_ty))),i) ->
                match fun_ty with
                | YFun(domain,range,(FT_Vanilla | FT_Pointer)) ->
                    let domain_args, body, sourceName = codegenFsharpClosureBody env jp_body key i
                    closure_names.[i] <- generatedClosureName sourceName i
                    {tag=i; free_vars=rdata_free_vars args; domain_args=data_free_vars domain_args; range=range; body=body}
                | YFun(_,_,_) -> raise_codegen_error "Non-standard functions are not supported in the F# backend."
                | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."
                ) (fun s x ->
                let domain =
                    match x.domain_args |> Array.map (fun (L(i,t)) -> sprintf "v%i : %s" i (tyv t)) with
                    | [||] -> "()"
                    | [|x|] -> sprintf "(%s)" x
                    | x -> String.concat ", " x |> sprintf "struct (%s)"
                line s (sprintf "%s (%s) %s : %s =" closure_names.[x.tag] (args_tys x.free_vars) domain (tup_ty x.range))
                with_macro_assigned x.body (fun () -> binds (indent s) x.body)
                )

        let main = StringBuilder()
        with_macro_assigned x (fun () -> binds {text=main; indent=0} x)

        let program = StringBuilder()
        env.globals |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        // Rust-only code an F# build still carries (the join points a backend_switch's other arms create are emitted too)
        // calls lib/spiral's emit marker: defined here so the F# compiles, it fails only if such code runs.
        if (functions |> Seq.exists (fun x -> (string x).Contains "__spiral_emit_rust")) || main.ToString().Contains "__spiral_emit_rust" then
            program.AppendLine("let __spiral_emit_rust (_ : 'a) (_ : 'b) : 'c = failwith \"lib/spiral: Rust-only code reached in an F# build\"") |> ignore
        types |> Seq.iteri (fun i x -> program.Append(if i = 0 then "type " else "and ").Append(x) |> ignore)
        functions |> Seq.iteri (fun i x -> program.Append(if i = 0 then "let rec " else "and ").Append(x) |> ignore)
        exports |> Seq.iter (fun x -> program.Append(x) |> ignore)
        program.Append(main).ToString()

    /// ## CodegenRust

    /// ### backend_nameRust
    let backend_nameRust = "Rust"


    /// ### litRust
    let litRust = function
        | LitInt8 x -> sprintf "%ii8" x
        | LitInt16 x -> sprintf "%ii16" x
        | LitInt32 x -> sprintf "%ii32" x
        | LitInt64 x -> sprintf "%ii64" x
        | LitUInt8 x -> sprintf "%iu8" x
        | LitUInt16 x -> sprintf "%iu16" x
        | LitUInt32 x -> sprintf "%iu32" x
        | LitUInt64 x -> sprintf "%iu64" x
        | LitFloat32 x ->
            if x = infinityf then "f32::INFINITY"
            elif x = -infinityf then "f32::NEG_INFINITY"
            elif Single.IsNaN x then "f32::NAN"
            else x.ToString("R") |> add_dec_point |> sprintf "%sf32"
        | LitFloat64 x ->
            if x = infinity then "f64::INFINITY"
            elif x = -infinity then "f64::NEG_INFINITY"
            elif Double.IsNaN x then "f64::NAN"
            else x.ToString("R") |> add_dec_point |> sprintf "%sf64"
        | LitString x ->
            let strb = StringBuilder(x.Length+2)
            strb.Append '"' |> ignore
            String.iter (function
                | '"' -> strb.Append "\\\""
                | '\t' -> strb.Append @"\t"
                | '\n' -> strb.Append @"\n"
                | '\r' -> strb.Append @"\r"
                | '\\' -> strb.Append @"\\"
                | x when Char.IsControl x -> strb.Append(sprintf "\\u{%x}" (int x))
                | x -> strb.Append x
                >> ignore
                ) x
            strb.Append '"' |> ignore
            sprintf "Rc::<str>::from(%s)" (strb.ToString())
        | LitChar x ->
            if int x > 127 then raise_codegen_error $"The Rust backend represents chars as bytes; '{x}' is not ASCII."
            match x with
            | '\n' -> @"b'\n'"
            | '\t' -> @"b'\t'"
            | '\r' -> @"b'\r'"
            | '\\' -> @"b'\\'"
            | '\'' -> @"b'\''"
            | x when Char.IsControl x -> sprintf "%iu8" (int x)
            | x -> sprintf "b'%c'" x
        | LitBool x -> if x then "true" else "false"

    /// ### primRust
    let primRust = function
        | Int8T -> "i8"
        | Int16T -> "i16"
        | Int32T -> "i32"
        | Int64T -> "i64"
        | UInt8T -> "u8"
        | UInt16T -> "u16"
        | UInt32T -> "u32"
        | UInt64T -> "u64"
        | Float32T -> "f32"
        | Float64T -> "f64"
        | BoolT -> "bool"
        | StringT -> "Rc<str>"
        | CharT -> "u8"

    /// ### type_litRust
    let type_litRust = function
        | YLit x -> litRust x
        | YSymbol x -> x
        | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."

    /// ### rustEmitMarkers
    let rustEmitMarkers = [ "__spiral_emit_rust" ]

    /// ### rustClosureFactoryMarker
    let rustClosureFactoryMarker = "__spiral_closure_factory"

    /// ### translateFsharpInterpolations
    let translateFsharpInterpolations (generated : string) =
        if not (generated.Contains("= $\"", System.StringComparison.Ordinal)) then generated
        else
            let pattern = System.Text.RegularExpressions.Regex(@"(?m)^(?<prefix>[ \t]*let mut v[0-9]+: Rc<str> = )\$""(?<body>(?:[^""\\]|\\.)*)"";[ \t]*\r?$")
            let translate (body : string) =
                let fmt = StringBuilder()
                let args = ResizeArray<string>()
                let mutable ok = true
                let mutable i = 0
                while ok && i < body.Length do
                    let c = body.[i]
                    if c = '\\' && i + 5 < body.Length && body.[i + 1] = 'u' && System.Text.RegularExpressions.Regex.IsMatch(body.Substring(i + 2, 4), "^[0-9a-fA-F]{4}$") then
                        fmt.Append("\\u{").Append(body.Substring(i + 2, 4)).Append('}') |> ignore; i <- i + 6
                    elif c = '\\' && i + 1 < body.Length then
                        match body.[i + 1] with
                        | 'n' | 'r' | 't' | '\\' | '0' | '\'' | '"' as e -> fmt.Append('\\').Append(e) |> ignore
                        | 'a' -> fmt.Append("\\x07") |> ignore
                        | 'b' -> fmt.Append("\\x08") |> ignore
                        | 'f' -> fmt.Append("\\x0C") |> ignore
                        | 'v' -> fmt.Append("\\x0B") |> ignore
                        | e -> fmt.Append("\\\\").Append(e) |> ignore
                        i <- i + 2
                    elif c = '{' && i + 1 < body.Length && body.[i + 1] = '{' then fmt.Append("{{") |> ignore; i <- i + 2
                    elif c = '}' && i + 1 < body.Length && body.[i + 1] = '}' then fmt.Append("}}") |> ignore; i <- i + 2
                    elif c = '%' && i + 1 < body.Length && body.[i + 1] = '%' then fmt.Append('%') |> ignore; i <- i + 2
                    elif c = '{' then
                        let close = body.IndexOf('}', i)
                        let hole = if close < 0 then "" else body.Substring(i + 1, close - i - 1)
                        if System.Text.RegularExpressions.Regex.IsMatch(hole, @"^(v[0-9]+|-?[0-9]+(?:[iu](?:8|16|32|64|size))?)$") then
                            fmt.Append("{}") |> ignore
                            args.Add hole
                            i <- close + 1
                        else ok <- false
                    elif c = '}' then ok <- false
                    else fmt.Append(c) |> ignore; i <- i + 1
                if not ok then None
                elif args.Count = 0 then
                    let literal = fmt.ToString().Replace("{{", "{").Replace("}}", "}")
                    Some ("Rc::<str>::from(\"" + literal + "\")")
                else Some $"""Rc::<str>::from(format!("{fmt}", {String.concat ", " args}))"""
            pattern.Replace(generated, System.Text.RegularExpressions.MatchEvaluator(fun m ->
                match translate m.Groups.["body"].Value with
                | Some expression -> m.Groups.["prefix"].Value + expression + ";"
                | None -> m.Value))

    /// ### foldStringBindings
    let foldStringBindings (generated : string) =
        let rx (p : string) = System.Text.RegularExpressions.Regex p
        let binding = rx @"^(?<ind>[ \t]*)let mut (?<v>v[0-9]+): Rc<str> = (?<rhs>.*?);[ \t]*\r?$"
        let assignment = rx @"^[ \t]*(?<v>v[0-9]+) = "
        let literal = rx @"^""(?<b>(?:[^""\\]|\\.)*)""$"
        let fsLiteral = rx @"^\$""(?<b>(?:[^""\\{}]|\\.)*)""$"
        let fromLiteral = rx @"^Rc::<str>::from\(""(?<b>(?:[^""\\]|\\.)*)""\)$"
        let fromFormat = rx @"^Rc::<str>::from\(format!\(""(?<b>(?:[^""\\]|\\.)*)""(?:, (?<a>[v0-9, ]+))?\)\)$"
        let unescape (b : string) =
            let s = StringBuilder()
            let mutable i = 0
            while i < b.Length do
                if b.[i] = '\\' && i + 1 < b.Length then
                    match b.[i + 1] with
                    | 'n' -> s.Append '\n' |> ignore; i <- i + 2
                    | 'r' -> s.Append '\r' |> ignore; i <- i + 2
                    | 't' -> s.Append '\t' |> ignore; i <- i + 2
                    | 'u' when i + 2 < b.Length && b.[i + 2] = '{' ->
                        let close = b.IndexOf('}', i)
                        s.Append(System.Char.ConvertFromUtf32(System.Convert.ToInt32(b.Substring(i + 3, close - i - 3), 16))) |> ignore
                        i <- close + 1
                    | c -> s.Append c |> ignore; i <- i + 2
                else s.Append b.[i] |> ignore; i <- i + 1
            s.ToString()
        let escape (s : string) = s.Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("\n", "\\n").Replace("\r", "\\r").Replace("\t", "\\t")
        let known = Dictionary<string, string>(System.StringComparer.Ordinal)
        let groupArm = rx @"^[ \t]*Group[0-9]+::M[0-9]+(?:\(.*\))? => \{[ \t]*\r?$"
        let splitPlus (e : string) =
            let parts = ResizeArray<string>()
            let mutable start = 0
            let mutable inStr = false
            let mutable i = 0
            while i < e.Length do
                let c = e.[i]
                if inStr then
                    if c = '\\' then i <- i + 1
                    elif c = '"' then inStr <- false
                elif c = '"' then inStr <- true
                elif c = '+' && i > 0 && e.[i - 1] = ' ' && i + 1 < e.Length && e.[i + 1] = ' ' then
                    parts.Add(e.Substring(start, i - 1 - start).Trim())
                    start <- i + 2
                i <- i + 1
            parts.Add(e.Substring(start).Trim())
            parts |> Seq.toList
        let rec value (e : string) : string option =
            let e = e.Trim()
            let m = literal.Match e
            if m.Success then Some (unescape m.Groups.["b"].Value) else
            let m = fsLiteral.Match e
            if m.Success then Some (unescape m.Groups.["b"].Value) else
            let m = fromLiteral.Match e
            if m.Success then Some (unescape m.Groups.["b"].Value) else
            let m = fromFormat.Match e
            if m.Success then
                let args = if m.Groups.["a"].Success then m.Groups.["a"].Value.Split([|','|], System.StringSplitOptions.RemoveEmptyEntries) |> Array.map (fun a -> a.Trim()) else [||]
                if args |> Array.forall known.ContainsKey then
                    let f = unescape m.Groups.["b"].Value
                    let s = StringBuilder()
                    let mutable k = 0
                    let mutable i = 0
                    let mutable ok = true
                    while ok && i < f.Length do
                        if f.[i] = '{' && i + 1 < f.Length && f.[i + 1] = '{' then s.Append '{' |> ignore; i <- i + 2
                        elif f.[i] = '}' && i + 1 < f.Length && f.[i + 1] = '}' then s.Append '}' |> ignore; i <- i + 2
                        elif f.[i] = '{' && i + 1 < f.Length && f.[i + 1] = '}' && k < args.Length then s.Append known.[args.[k]] |> ignore; k <- k + 1; i <- i + 2
                        elif f.[i] = '{' || f.[i] = '}' then ok <- false
                        else s.Append f.[i] |> ignore; i <- i + 1
                    if ok then Some (s.ToString()) else None
                else None
            elif System.Text.RegularExpressions.Regex.IsMatch(e, @"^v[0-9]+$") then
                match known.TryGetValue e with true, v -> Some v | _ -> None
            else
                match splitPlus e with
                | [_] -> None
                | parts ->
                    let vs = parts |> List.map value
                    if vs |> List.forall Option.isSome then Some (vs |> List.map Option.get |> String.concat "") else None
        generated.Split([|"\n"|], System.StringSplitOptions.None)
        |> Array.map (fun line ->
            if line.StartsWith "fn " || groupArm.IsMatch line then
                known.Clear()
                line
            else
                let m = binding.Match line
                if m.Success then
                    let v = m.Groups.["v"].Value
                    let cr = if line.EndsWith "\r" then "\r" else ""
                    let ind = m.Groups.["ind"].Value
                    match (if m.Groups.["rhs"].Value.Trim() = v then None else value m.Groups.["rhs"].Value) with
                    | Some s ->
                        known.[v] <- s
                        let lit = escape s
                        $"{ind}let mut {v}: Rc<str> = Rc::<str>::from(\"{lit}\");{cr}"
                    | None ->
                        known.Remove v |> ignore
                        match splitPlus m.Groups.["rhs"].Value with
                        | _ :: _ :: _ as parts when parts |> List.forall (fun p -> System.Text.RegularExpressions.Regex.IsMatch(p, @"^((?:string )?v[0-9]+|""(?:[^""\\]|\\.)*""|\$""(?:[^""\\{}]|\\.)*"")$")) ->
                            let fmt = StringBuilder()
                            let args = ResizeArray<string>()
                            for p in parts do
                                if p.StartsWith "string " then fmt.Append "{}" |> ignore; args.Add(p.Substring 7)
                                elif p.StartsWith "v" then fmt.Append "{}" |> ignore; args.Add p
                                else
                                    let body = if p.StartsWith "$" then p.Substring(2, p.Length - 3) else p.Substring(1, p.Length - 2)
                                    fmt.Append(body.Replace("{", "{{").Replace("}", "}}")) |> ignore
                            let a = String.concat ", " args
                            $"{ind}let mut {v}: Rc<str> = Rc::<str>::from(format!(\"{fmt}\", {a}));{cr}"
                        | _ -> line
                else
                    let a = assignment.Match line
                    if a.Success then known.Remove a.Groups.["v"].Value |> ignore
                    line)
        |> String.concat "\n"

    /// ### rustSpliceConsumes
    let private rustConsumingMethod =
        System.Text.RegularExpressions.Regex(@"^\.\s*(?:(?:into_\w+|unwrap\w*|expect\w*|ok|err|map|map_err|map_or\w*|and_then|or_else|unzip|collect|sum|count|fold|for_each|json|borsh)\b|[0-9]+\s*(?:$|[),;}\]]))")
    let private rustPrevKeyword = System.Text.RegularExpressions.Regex(@"(?:^|[^\w])(?:match|in)$")
    let private rustPrevBlocks = System.Text.RegularExpressions.Regex(@"(?:&|&\s*mut|\*|=|(?:^|[^\w])let(?:\s+mut)?|\{)$")
    let private rustInMacroCall (p : string) =
        let mutable depth = 0
        let mutable i = p.Length - 1
        let mutable opener = -1
        while opener < 0 && i >= 0 do
            match p.[i] with
            | ')' | ']' | '}' -> depth <- depth + 1
            | '(' | '[' | '{' -> if depth = 0 then opener <- i else depth <- depth - 1
            | _ -> ()
            i <- i - 1
        opener > 0 && p.[opener] = '(' && p.Substring(0, opener).TrimEnd().EndsWith "!"
    let rustSpliceConsumes (prev : string) (next : string) =
        let p = prev.TrimEnd()
        let n = next.TrimStart()
        if rustInMacroCall p then false
        elif (p.Length > 0 && "+-*/%^|<>".IndexOf p.[p.Length - 1] >= 0) || (n.Length > 0 && "+-*/%^|<>".IndexOf n.[0] >= 0) then false
        elif rustPrevKeyword.IsMatch p then true
        elif rustPrevBlocks.IsMatch p then false
        elif n.StartsWith "." then rustConsumingMethod.IsMatch n
        elif n.StartsWith "=" || (n.Length >= 2 && n.[1] = '=' && "+-*/%|&^".IndexOf n.[0] >= 0) || n.StartsWith "<<=" || n.StartsWith ">>=" then false
        elif n.StartsWith ")" && p.EndsWith "(" && (p.Length = 1 || not (System.Char.IsLetterOrDigit p.[p.Length - 2] || "_>)!".IndexOf p.[p.Length - 2] >= 0)) then
            let rest = n.Substring(1).TrimStart()
            if rest.StartsWith "." then rustConsumingMethod.IsMatch rest
            else not (rest.StartsWith "(" || rest.StartsWith "[" || rest.StartsWith "?")
        else n = "" || n.StartsWith ")" || n.StartsWith "," || n.StartsWith ";" || n.StartsWith "}" || n.StartsWith "]"

    /// ### immutableRustLets
    let immutableRustLets (generated : string) =
        if not (generated.Contains("let mut v", System.StringComparison.Ordinal)) then generated
        else
            let binding = System.Text.RegularExpressions.Regex(@"\blet mut (v[0-9]+)\b")
            let target = @"(v[0-9]+)(?:\s*(?:\.\s*\w+|\[[^\]\n]*\]))*"
            let assignment = System.Text.RegularExpressions.Regex(@"(?<![\w.])" + target + @"\s*(?:=(?![=>])|\+=|-=|\*=|/=|%=|<<=|>>=|&=|\|=|\^=)")
            let mutableBorrow = System.Text.RegularExpressions.Regex(@"&\s*mut\s+(v[0-9]+)\b")
            let directCall = System.Text.RegularExpressions.Regex(@"(?<![\w.])(v[0-9]+)\s*\(")
            let methodCall = System.Text.RegularExpressions.Regex(@"(?<![\w.])(v[0-9]+)(?:\s*\.\s*\w+)*?\s*\.\s*(\w+)\s*(?:::<[^>]*>)?\s*\(")
            let readOnly =
                HashSet<string>(
                    [ "clone"; "borrow"; "len"; "is_empty"; "as_str"; "as_ref"; "as_ptr"; "chars"; "bytes"; "get"; "iter"; "contains"; "starts_with"; "ends_with"
                      "to_string"; "to_owned"; "eq"; "ne"; "cmp"; "partial_cmp"; "lt"; "le"; "gt"; "ge"; "abs"; "pow"; "powf"; "powi"; "sqrt"; "exp"; "ln"; "log"; "log10"
                      "sin"; "cos"; "tan"; "tanh"; "atan2"; "floor"; "ceil"; "round"; "trunc"; "is_nan"; "is_infinite"; "to_bits"; "count_ones"; "leading_zeros"; "trailing_zeros"
                      "wrapping_add"; "wrapping_sub"; "wrapping_mul"; "wrapping_div"; "wrapping_rem"; "wrapping_neg"; "wrapping_shl"; "wrapping_shr"; "wrapping_pow"
                      "checked_add"; "checked_sub"; "checked_mul"; "checked_div"; "checked_rem"; "overflowing_add"; "overflowing_sub"; "overflowing_mul"
                      "find"; "split"; "trim"; "parse"; "char_indices"; "is_char_boundary"; "repeat"; "replace"; "to_lowercase"; "to_uppercase"; "lines"
                      "unwrap"; "expect"; "is_some"; "is_none"; "copied"; "cloned"; "map"; "tag"; "hash"; "fmt"; "as_bytes"; "into" ],
                    System.StringComparer.Ordinal)
            let body = binding.Replace(generated, "let BOUND")
            let mutated = HashSet<string>(System.StringComparer.Ordinal)
            for found in assignment.Matches body do mutated.Add found.Groups.[1].Value |> ignore
            for found in mutableBorrow.Matches body do mutated.Add found.Groups.[1].Value |> ignore
            for found in directCall.Matches body do mutated.Add found.Groups.[1].Value |> ignore
            for found in methodCall.Matches body do
                if not (readOnly.Contains found.Groups.[2].Value) then mutated.Add found.Groups.[1].Value |> ignore
            binding.Replace(generated, fun (found : System.Text.RegularExpressions.Match) ->
                if mutated.Contains found.Groups.[1].Value then found.Value else "let " + found.Groups.[1].Value)
    /// ### rustMoveOnLastUse
    let rustMoveOnLastUse (generated : string) =
        if not (generated.Contains(".clone()", System.StringComparison.Ordinal)) then generated
        else
            let lines = generated.Replace("\r\n", "\n").Split('\n')
            let word = System.Text.RegularExpressions.Regex(@"(?<![\w.])(v[0-9]+)\b")
            let fnHead = System.Text.RegularExpressions.Regex(@"^(?:pub )?fn \w+")
            let selfRebind = System.Text.RegularExpressions.Regex(@"^\s*let (?:mut )?(v[0-9]+): [^=]+ = \1\.clone\(\);\s*$")
            let borrowedParam = System.Text.RegularExpressions.Regex(@"\b(v[0-9]+): &")
            let spans = ResizeArray<int * int>()
            let mutable start = -1
            for i = 0 to lines.Length - 1 do
                if fnHead.IsMatch lines.[i] then start <- i
                elif lines.[i] = "}" && start >= 0 then
                    spans.Add((start, i))
                    start <- -1
            for (s, e) in spans do
                let closure = System.Text.RegularExpressions.Regex(@"\|[^|\n]*\|\s*[{\w(&*!\-\[]|\|\|\s*[{\w(]")
                let captureFreeCache = System.Text.RegularExpressions.Regex(@"\b(?:LIT|CASE|CLOSURE)\.with\(\|(?:lit|case|closure)\| (?:lit|case|closure)\.clone\(\)\)")
                let loops = seq { s .. e } |> Seq.exists (fun l -> let line = captureFreeCache.Replace(lines.[l], "") in line.Contains "loop {" || line.Contains "while " || closure.IsMatch line)
                if not loops then
                    let borrowed = HashSet<string>(borrowedParam.Matches lines.[s] |> Seq.map (fun found -> found.Groups.[1].Value))
                    let positions = ResizeArray<int * int * string>()
                    for li = s to e do
                        for found in word.Matches lines.[li] do
                            positions.Add((li, found.Index + found.Length, found.Groups.[1].Value))
                    let cuts = ResizeArray<int * int>()
                    for idx = 0 to positions.Count - 1 do
                        let li, b, name = positions.[idx]
                        if lines.[li].Substring(b).StartsWith(".clone()", System.StringComparison.Ordinal) && not (selfRebind.IsMatch lines.[li]) && not (borrowed.Contains name) then
                            let mutable later = false
                            for next = idx + 1 to positions.Count - 1 do
                                let _, _, other = positions.[next]
                                if other = name then later <- true
                            let mutable borrowedBefore = false
                            let mutable prev = idx - 1
                            while prev >= 0 && (let pl, _, _ = positions.[prev] in pl = li) do
                                let _, pb, other = positions.[prev]
                                if other = name then
                                    let before = lines.[li].Substring(0, pb - other.Length).TrimEnd('*')
                                    if before.EndsWith "&" || before.EndsWith "&mut " then borrowedBefore <- true
                                prev <- prev - 1
                            if not later && not borrowedBefore then cuts.Add((li, b))
                    for (li, b) in cuts |> Seq.sortDescending do
                        lines.[li] <- lines.[li].Substring(0, b) + lines.[li].Substring(b + ".clone()".Length)
            System.String.Join("\n", lines)

    /// ### inlineRustEmits
    let inlineRustEmits (generated : string) =
        if not (rustEmitMarkers |> List.exists (fun (m : string) -> generated.Contains(m, System.StringComparison.Ordinal))) then generated
        else
            let lines = generated.Split([|"\r\n"; "\n"|], System.StringSplitOptions.None)
            let bindingPattern = System.Text.RegularExpressions.Regex(@"^\s*let mut (v[0-9]+): Rc<str> = (?:Rc::<str>::from\()?(""(?:\\.|[^""\\])*"")\)?;\s*$")
            let emitPattern =
                System.Text.RegularExpressions.Regex(@"^(?<prefix>\s*(?:let .+? = )?)__spiral_emit_rust (?<args>.*?) (?<code>v[0-9]+) ;\s*$")
            let unescape (literal : string) =
                let body = literal.Substring(1, literal.Length - 2)
                let text = StringBuilder()
                let mutable i = 0
                while i < body.Length do
                    if body.[i] = '\\' && i + 1 < body.Length then
                        match body.[i + 1] with
                        | 'n' -> text.Append('\n') |> ignore
                        | 'r' -> text.Append('\r') |> ignore
                        | 't' -> text.Append('\t') |> ignore
                        | '"' -> text.Append('"') |> ignore
                        | '\\' -> text.Append('\\') |> ignore
                        | other -> text.Append('\\').Append(other) |> ignore
                        i <- i + 2
                    else
                        text.Append(body.[i]) |> ignore
                        i <- i + 1
                text.ToString()
            let splitArgs (value : string) =
                let value = value.Trim()
                if value = "()" then [ "()" ]
                else
                    let body = if value.Length >= 2 && value.[0] = '(' && value.[value.Length - 1] = ')' then value.Substring(1, value.Length - 2) else value
                    let parts = ResizeArray<string>()
                    let mutable start = 0
                    let mutable depth = 0
                    for index = 0 to body.Length - 1 do
                        match body.[index] with
                        | '(' | '[' | '<' -> depth <- depth + 1
                        | ')' | ']' -> depth <- depth - 1
                        | '>' when index > 0 && body.[index - 1] <> '-' -> depth <- depth - 1
                        | ',' when depth = 0 ->
                            parts.Add(body.Substring(start, index - start).Trim())
                            start <- index + 1
                        | _ -> ()
                    parts.Add(body.Substring(start).Trim())
                    parts |> Seq.filter (fun part -> part <> "") |> Seq.toList
            let borrow (argument : string) =
                if System.Text.RegularExpressions.Regex.IsMatch(argument, @"^v[0-9]+\.clone\(\)$") then argument.Substring(0, argument.Length - ".clone()".Length) else argument
            let snippets = Dictionary<string, string>(System.StringComparer.Ordinal)
            let bindingLine = Dictionary<string, int>(System.StringComparer.Ordinal)
            let drop = HashSet<int>()
            let rewritten = Array.copy lines
            for index = 0 to lines.Length - 1 do
                let binding = bindingPattern.Match lines.[index]
                if binding.Success then
                    snippets.[binding.Groups.[1].Value] <- (unescape binding.Groups.[2].Value).Replace("{{", "{").Replace("}}", "}")
                    bindingLine.[binding.Groups.[1].Value] <- index
                let emitted = emitPattern.Match lines.[index]
                if emitted.Success then
                    let code = emitted.Groups.["code"].Value
                    match snippets.TryGetValue code, bindingLine.TryGetValue code with
                    | (true, payload), (true, lineIndex) ->
                        drop.Add lineIndex |> ignore
                        let args = splitArgs emitted.Groups.["args"].Value
                        let named = System.Text.RegularExpressions.Regex.Matches(payload, @"\$([0-9]+)") |> Seq.map (fun m -> int m.Groups.[1].Value + 1) |> Seq.fold max 0
                        let args =
                            if named >= 1 && args.Length > named then
                                List.take (named - 1) args @ [List.skip (named - 1) args |> String.concat ", " |> sprintf "(%s)"]
                            else args
                        let args = List.toArray args
                        let expression =
                            System.Text.RegularExpressions.Regex.Replace(payload, @"\$([0-9]+)", System.Text.RegularExpressions.MatchEvaluator(fun m ->
                                let mutable digits = m.Groups.[1].Value
                                while digits.Length > 1 && int digits >= args.Length do digits <- digits.Substring(0, digits.Length - 1)
                                let k = int digits
                                if k >= args.Length then m.Value
                                else
                                    let a = args.[k]
                                    let next = payload.Substring(m.Index + 1 + digits.Length)
                                    let a = if borrow a <> a && rustSpliceConsumes (payload.Substring(0, m.Index)) next then a else borrow a
                                    a + m.Groups.[1].Value.Substring(digits.Length)))
                        rewritten.[index] <- emitted.Groups.["prefix"].Value + expression + ";"
                    | _ -> ()
            rewritten
            |> Array.mapi (fun index line -> if drop.Contains index then None else Some line)
            |> Array.choose id
            |> String.concat "\n"

    /// ### nonCloneRustType
    let nonCloneRustType =
        System.Text.RegularExpressions.Regex(
            @"^\s*(?:SpiralNearVec|near_sdk(?:::|_)store(?:::|_)(?:[a-z_]+(?:::|_))?(?:Vector|LookupMap|LookupSet|UnorderedMap|UnorderedSet|IterableMap|IterableSet|TreeMap|LazyOption|Lazy)|(?:std(?:::|_)sync(?:::|_))?MutexGuard|(?:std(?:::|_)process(?:::|_))?(?:Command|Child|ChildStdin|ChildStdout|ChildStderr)|(?:std(?:::|_)fs(?:::|_))?File|(?:std(?:::|_)thread(?:::|_))?JoinHandle|(?:async_walkdir(?:::|_))?Filtering|std(?:::|_)io(?:::|_)Error|anyhow(?:::|_)Error|near_workspaces(?:::|_)error(?:::|_)Error|(?:std(?:::|_)pin(?:::|_))?Pin|(?:leptos(?:::|_)(?:prelude|dom)(?:::|_))?(?:AnyView|Fragment)_?|(?:(?:reqwest(?:_wasm)?|ureq)(?:::|_))?RequestBuilder|ureq(?:::|_)(?:(?:http(?:::|_))?Response|Body|Error)|(?:rexie(?:::|_))?Rexie|Box\s*<\s*dyn)\b")
    let boxRustType = System.Text.RegularExpressions.Regex(@"^\s*(?:std(?:::|_)boxed(?:::|_))?Box\s*<\s*$")
    let dynRustType = System.Text.RegularExpressions.Regex(@"^\s*(?:dyn\b|Dyn\s*<)")
    let cloneIfContentsRustType =
        System.Text.RegularExpressions.Regex(@"^\s*(?:Result|Option|(?:std(?:::|_)vec(?:::|_))?Vec)\s*<")

    /// ### dropDeadRustLiterals
    let dropDeadRustLiterals (text : string) =
        let decl = System.Text.RegularExpressions.Regex(@"^\s*let (?:mut )?(v\d+): (?:(?:::)?std::rc::)?Rc<str> = (?:(?:::)?std::rc::)?Rc::<str>::from\(""(?:[^""\\]|\\.)*""\);\s*$")
        let starts (line : string) = line.StartsWith "fn " || line.StartsWith "pub fn " || line.StartsWith "pub(crate) fn "
        let lines = text.Split '\n'
        let keep = Array.create lines.Length true
        let mutable segment = 0
        let scan (first : int) (last : int) =
            if last >= first then
                let body = System.String.Join("\n", lines, first, last - first + 1)
                for i in first .. last do
                    let m = decl.Match lines.[i]
                    if m.Success then
                        let uses = System.Text.RegularExpressions.Regex.Matches(body, @"\b" + m.Groups.[1].Value + @"\b").Count
                        if uses = 1 then keep.[i] <- false
        for i in 0 .. lines.Length - 1 do
            if starts lines.[i] then
                scan segment (i - 1)
                segment <- i
        scan segment (lines.Length - 1)
        if Array.forall id keep then text
        else System.String.Join("\n", lines |> Array.indexed |> Array.filter (fun (i, _) -> keep.[i]) |> Array.map snd)

    /// ### cacheRustStringLiterals
    let cacheRustStringLiterals (text : string) =
        let literal = System.Text.RegularExpressions.Regex(@"(?<![\w:])((?:::)?std::rc::)?Rc::<str>::from\(""((?:[^""\\]|\\.)*)""\)")
        literal.Replace(text, System.Text.RegularExpressions.MatchEvaluator(fun m ->
            let path = m.Groups.[1].Value
            "{ thread_local!{ static LIT: " + path + "Rc<str> = " + path + "Rc::<str>::from(\"" + m.Groups.[2].Value + "\"); } LIT.with(|lit| lit.clone()) }"))

    /// ### ParamEscape
    type ParamUse = Borrowed | Escapes

    let paramEscapeTracked (L(_,t) : TyV) = match t with YArray _ | YPrim StringT -> true | _ -> false

    let paramEscapeScan (uses : Dictionary<JoinPointKey, ParamUse []>) (self : JoinPointKey option) (borrowedHere : TyV Set) (body : TypedBind []) =
        let escaped = HashSet<TyV>()
        let demoted = ResizeArray<JoinPointKey * int>()
        let esc (vs : TyV seq) = for v in vs do if borrowedHere.Contains v then escaped.Add v |> ignore
        let fv d = data_free_vars d
        let call tail ((key, args) : JoinPointCall) =
            match key, uses.TryGetValue key with
            | JPMethod _, (true, u) ->
                args |> Array.iteri (fun i a ->
                    if i < u.Length && u.[i] = Borrowed then
                        if (tail || self = Some key) && not (borrowedHere.Contains a) then demoted.Add((key, i))
                    else esc [a])
            | _ -> esc args
        let rec binds (x : TypedBind []) = for b in x do bind b
        and bind = function
            | TyLet(_,_,o) -> op false o
            | TyLocalReturnOp(_,o,_) -> op true o
            | TyLocalReturnData(d,_) -> esc (fv d)
        and op tail = function
            | TyJoinPoint c -> call tail c
            | TyOp(ArrayIndex, _) | TyArrayLength _ | TyStringLength _ | TySizeOf _ | TyBackend _ -> ()
            | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> ()
            | TyOp(ArrayIndexSet, [_; _; c]) -> esc (fv c)
            | TyOp(_, l) | TyArrayLiteral(_, l) -> for d in l do esc (fv d)
            | TyMacro l -> for m in l do (match m with CMTerm(d,_) -> esc (fv d) | _ -> ())
            | TyUnionBox(_,x,_) | TyToLayout(x,_) | TyFailwith(_,x) | TyConv(_,x) | TyArrayCreate(_,x) -> esc (fv x)
            | TyApply(i,d) -> esc [i]; esc (fv d)
            | TyLayoutMutableSet(_,_,d) -> esc (fv d)
            | TyWhile(_,body) | TyDo body | TyIndent body -> binds body
            | TyIf(_,a,b) -> binds a; binds b
            | TyUnionUnbox(_,_,cases,fail) ->
                for kv in cases do binds (snd kv.Value)
                Option.iter binds fail
            | TyIntSwitch(_,cases,fail) ->
                Array.iter binds cases
                binds fail
        binds body
        escaped, demoted

    let paramEscape (tracked : TyV -> bool) (env : PartEvalResult) (main : TypedBind []) : JoinPointKey -> int -> bool =
        let methods = ResizeArray<JoinPointKey * TyV [] * TypedBind []>()
        for kv in env.join_point_method do
            for m in fst kv.Value do
                match m.Value with
                | Some body, _, _ -> methods.Add((JPMethod(kv.Key, m.Key), rdata_free_vars (codegenMethodKeyArgs m.Key), DeadPureLetElision.block body))
                | _ -> ()
        let closures = ResizeArray<TypedBind []>()
        for kv in env.join_point_closure do
            for c in fst kv.Value do
                match c.Value with
                | Some(_, body) -> closures.Add(DeadPureLetElision.block body)
                | None -> ()
        let uses = Dictionary<JoinPointKey, ParamUse []>(HashIdentity.Structural)
        for key, ps, _ in methods do uses.[key] <- ps |> Array.map (fun p -> if tracked p then Borrowed else Escapes)
        let mutable changed = true
        let demote key i =
            let u = uses.[key]
            if u.[i] = Borrowed then
                u.[i] <- Escapes
                changed <- true
        let scan self borrowed body =
            let escaped, demoted = paramEscapeScan uses self borrowed body
            for key, i in demoted do demote key i
            escaped
        while changed do
            changed <- false
            for key, ps, body in methods do
                let u = uses.[key]
                let borrowed = ps |> Array.indexed |> Array.choose (fun (i, p) -> if u.[i] = Borrowed then Some p else None) |> Set
                let escaped = scan (Some key) borrowed body
                ps |> Array.iteri (fun i p -> if escaped.Contains p then demote key i)
            for body in closures do scan None Set.empty body |> ignore
            scan None Set.empty main |> ignore
        fun key i ->
            match uses.TryGetValue key with
            | true, u -> i < u.Length && u.[i] = Borrowed
            | _ -> false

    /// ### codegenRust
    let unionCaseSuffix (x : UnionRecFsharp) (index : int) = (generatedCaseNames (x.free_vars |> Map.keys)).[index]

    let codegenRust (rust_extern : (string * string list) list) (linked_units : Map<int, LinkedUnit>) (env : PartEvalResult) (x : TypedBind []) =
        match rust_extern |> List.tryFind (fun (name, _) -> name <> "rc_str") with
        | Some (name, _) -> raise_codegen_error $"rust-extern: '{name} = ...' is retired (LINKED-UNITS-DERIVE-OUT): generated types derive Clone only, and linked units export Spiral equality/display functions instead. Only 'rc_str = ...' entries remain."
        | None -> ()
        let rc_str_exports = rust_extern |> List.tryPick (fun (name, exports) -> if name = "rc_str" then Some (Set.ofList exports) else None) |> Option.defaultValue Set.empty
        let method_names = Dictionary<int, string>()
        let closure_names = Dictionary<int, string>()
        let types = ResizeArray()
        let functions = ResizeArray()
        let exports = ResizeArray()
        let closure_of_var = Dictionary<int, int>()
        let export_names = HashSet<string>()
        let exported_record_names = HashSet<string>()
        let union_tag_impls = Dictionary<string, string>()
        let union_tags_used = HashSet<string>()
        let exported_union_names = exportedUnionNames env x
        let default_impls = Dictionary<string, string>()

        let print is_type show r =
            let s = {text=StringBuilder(); indent=0}
            show s r
            let text = s.text.ToString()
            if is_type then types.Add(text) else functions.Add(text)

        let layout show =
            let dict' = codegenMemoTable HashIdentity.Structural
            let dict = codegenMemoTable HashIdentity.Reference
            let f x : LayoutRecFsharp =
                match x with
                | YLayout(x,_) ->
                let x = env.ty_to_data x
                let a, b =
                    match x with
                    | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                    | _ -> data_free_vars x, Map.empty
                {data=x; free_vars=a; free_vars_by_key=b; tag=dict'.Count}
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (3).\nGot: %s{show_ty x}"
            fun x ->
                let mutable dirty = false
                let r = memoize dict (memoize dict' (fun x -> dirty <- true; f x)) x
                if dirty then print true show r
                r

        let union show =
            let dict = codegenMemoTable HashIdentity.Reference
            let f (a : Map<int * string,Ty>) : UnionRecFsharp = {free_vars=a |> Map.map (fun _ -> env.ty_to_data >> data_free_vars); tag=dict.Count}
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print true show r
                r

        let jp f show =
            let dict = codegenMemoTable HashIdentity.Structural
            let f x = f (x, dict.Count)
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print false show r
                r

        let mutable self_loop : (int * L<Tag,Ty> []) option = None
        let mutable group_loop : (string * HashSet<int>) option = None
        let rust_tracked (L(_,t) : TyV) = match t with YArray _ | YPrim StringT | YLayout(_, (Heap | HeapMutable)) -> true | YUnion u -> u.Item.layout = UHeap | _ -> false
        let borrowed_param = paramEscape rust_tracked env x
        let method_borrowed = Dictionary<int, Set<int>>()
        let group_sizes = Dictionary<int, int>()
        let mutable current_borrowed : Set<int> = Set.empty
        let method_records = Dictionary<int, MethodRecFsharp>()
        let emitted_groups = HashSet<int>()
        let without_self_loop f =
            let saved, saved_group = self_loop, group_loop
            self_loop <- None
            group_loop <- None
            f ()
            self_loop <- saved
            group_loop <- saved_group
        let is_copy = function YPrim StringT -> false | YPrim _ -> true | _ -> false
        let stack_union_moves = Dictionary<Union, bool>(HashIdentity.Reference)
        let rustSwitchArm = function
            | YMacro [Text "backend_switch "; Type (YRecord r)] as t ->
                match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameRust then Some v else None) with
                | Some x -> x
                | None -> t
            | t -> t
        let rec moves = function
            | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameRust then Some v else None) with
                | Some t -> env.ty_to_data t |> data_free_vars |> Array.exists (fun (L(_,t)) -> moves t)
                | None -> false
            | YMacro (Text a :: _) when nonCloneRustType.IsMatch a -> true
            | YMacro (Text a :: Type t :: _) when boxRustType.IsMatch a ->
                env.ty_to_data t |> data_free_vars |> Array.exists (function
                    | L(_,t) when (match rustSwitchArm t with YMacro (Text b :: _) -> dynRustType.IsMatch b | _ -> false) -> true
                    | L(_,t) -> moves t)
            | YMacro (Text a :: rest) when cloneIfContentsRustType.IsMatch a ->
                rest |> List.exists (function Type t | TypeLit t -> env.ty_to_data t |> data_free_vars |> Array.exists (fun (L(_,t)) -> moves t) | Text _ -> false)
            | YUnion u when u.Item.layout = UStack ->
                match stack_union_moves.TryGetValue u with
                | true, r -> r
                | _ ->
                    stack_union_moves.[u] <- false
                    let r = u.Item.cases |> Map.exists (fun _ t -> env.ty_to_data t |> data_free_vars |> Array.exists (fun (L(_,t)) -> moves t))
                    stack_union_moves.[u] <- r
                    r
            | _ -> false
        let rust_int (a : Data) =
            match data_term_vars a with
            | [|WV(L(_,YPrim p))|] -> (match p with Int8T | Int16T | Int32T | Int64T | UInt8T | UInt16T | UInt32T | UInt64T -> true | _ -> false)
            | [|WLit l|] -> (match lit_to_primitive_type l with Int8T | Int16T | Int32T | Int64T | UInt8T | UInt16T | UInt32T | UInt64T -> true | _ -> false)
            | _ -> false
        let rust_receiver (x : string) = if System.Text.RegularExpressions.Regex.IsMatch(x, @"^[A-Za-z_0-9]+$") then x else $"({x})"
        let macro_var = function WV (L(i,_)) -> $"v{i}" | WLit a -> litRust a
        let macro_args x = x |> data_term_vars |> Array.map macro_var |> String.concat ", "
        let live_after = Dictionary<TypedBind, int -> bool>(HashIdentity.Reference)
        let unbox_arm_uses = Dictionary<TypedOp, Set<int>>(HashIdentity.Reference)
        let current_live = ref (fun (_ : int) -> false)
        let tags_of_data (d : Data) = data_free_vars d |> Array.fold (fun s (L(i,_)) -> Set.add i s) Set.empty
        let tags_of_vars (x : TyV seq) = x |> Seq.fold (fun s (L(i,_)) -> Set.add i s) Set.empty
        let outer_none = fun (_ : int) -> false
        let current_known = ref false
        let current_counts = ref (Dictionary<int, int>())
        let mutable allow_moves = true
        let var (L(i,t)) =
            if is_copy t || moves t then $"v{i}"
            elif allow_moves && current_known.Value && not (current_live.Value i) && not (current_borrowed.Contains i) && (match current_counts.Value.TryGetValue i with | true, n -> n = 1 | _ -> false) then $"v{i}"
            else $"v{i}.clone()"
        let args x = x |> Array.map var |> String.concat ", "
        let show_w = function WV x -> var x | WLit a -> litRust a
        let direct_counts (b : TypedBind) =
            let counts = Dictionary<int, int>()
            let add (vs : TyV seq) = for (L(i,_)) in vs do counts.[i] <- (match counts.TryGetValue i with | true, n -> n + 1 | _ -> 1)
            let data d = data_term_vars d |> Array.iter (function WV v -> add [v] | WLit _ -> ())
            match b with
            | TyLet(_,_,o) | TyLocalReturnOp(_,o,_) ->
                match o with
                | TyJoinPoint(_,a) -> add a
                | TyOp(_,l) | TyArrayLiteral(_,l) -> List.iter data l
                | TyMacro l -> l |> List.iter (function CMTerm(d,_) -> data d | _ -> ())
                | TyToLayout(x,_) | TyUnionBox(_,x,_) | TyFailwith(_,x) | TyConv(_,x) | TyArrayCreate(_,x) | TyArrayLength(_,x) | TyStringLength(_,x) -> data x
                | TyApply(v,d) | TyLayoutMutableSet(v,_,d) -> add [v]; data d
                | TyIf(c,_,_) -> data c
                | TyUnionUnbox(vs,_,_,_) -> add vs
                | TyIntSwitch(v,_,_) -> add [v]
                | TyLayoutIndexAll v | TyLayoutIndexByKey(v,_) -> add [v]
                | _ -> ()
            | TyLocalReturnData(d,_) -> data d
            counts
        let concatPrefix = "Rc::<str>::from(format!(\""
        let isConcat parts = match parts with CMText t :: _ -> t.StartsWith concatPrefix | _ -> false
        let fuseConcat (body : TypedBind []) : TypedBind [] =
            let uses = Dictionary<int, int>()
            let mutable opaque = false
            let bump i = uses.[i] <- (match uses.TryGetValue i with | true, n -> n + 1 | _ -> 1)
            let useData (d : Data) = for L(i,_) in data_free_vars d do bump i
            let useVar (L(i,_) : TyV) = bump i
            let rec countBlock (x : TypedBind []) = for b in x do countBind b
            and countBind b =
                match b with
                | TyLet(_,_,o) -> countOp o
                | TyLocalReturnOp(_,o,d) -> countOp o; useData d
                | TyLocalReturnData(d,_) -> useData d
            and countOp o =
                match o with
                | TyMacro parts -> for part in parts do (match part with CMTerm(d,_) -> useData d | _ -> ())
                | TyOp(_, args) | TyArrayLiteral(_, args) -> for d in args do useData d
                | TyUnionBox(_, d, _) | TyToLayout(d, _) | TyFailwith(_, d) | TyConv(_, d)
                | TyArrayCreate(_, d) | TyArrayLength(_, d) | TyStringLength(_, d) -> useData d
                | TyUnionUnbox(vs, _, on_succs, on_fail) ->
                    for v in vs do useVar v
                    for KeyValue(_, (bound, block)) in on_succs do
                        for d in bound do useData d
                        countBlock block
                    on_fail |> Option.iter countBlock
                | TyIntSwitch(v, cases, on_fail) -> useVar v; (for block in cases do countBlock block); countBlock on_fail
                | TyLayoutIndexAll v | TyLayoutIndexByKey(v, _) -> useVar v
                | TyLayoutMutableSet(v, _, d) | TyApply(v, d) -> useVar v; useData d
                | TyIf(cond, tr, fl) -> useData cond; countBlock tr; countBlock fl
                | TyWhile((_, args), block) -> (for v in args do useVar v); countBlock block
                | TyDo block | TyIndent block -> countBlock block
                | TyJoinPoint(_, args) -> for v in args do useVar v
                | TySizeOf _ | TyBackend _ -> ()
                | _ -> opaque <- true
            countBlock body
            let usedOnce i = (match uses.TryGetValue i with | true, n -> n = 1 | _ -> false)
            let tryFuse (prev : TypedBind) (next : TypedBind) =
                match prev, next with
                | TyLet(d1, _, TyMacro p1), TyLet(d2, trace2, TyMacro p2) when isConcat p1 && isConcat p2 && (data_free_vars d1).Length = 1 ->
                    let (L(i,_)) = (data_free_vars d1).[0]
                    let direct = p2 |> List.sumBy (function CMTerm(DV(L(j,_)),_) when j = i -> 1 | _ -> 0)
                    let nested = p2 |> List.exists (function CMTerm(DV _,_) -> false | CMTerm(d,_) -> data_free_vars d |> Array.exists (fun (L(j,_)) -> j = i) | _ -> false)
                    if usedOnce i && direct = 1 && not nested then
                        Some (TyLet(d2, trace2, TyMacro (p2 |> List.collect (function CMTerm(DV(L(j,_)),_) when j = i -> p1 | part -> [ part ]))))
                    else None
                | _ -> None
            let rec fuseBlock (x : TypedBind []) : TypedBind [] =
                let out = ResizeArray<TypedBind>(x.Length)
                for b in x do
                    let b = fuseBind b
                    let fused = if out.Count > 0 then tryFuse out.[out.Count - 1] b else None
                    match fused with
                    | Some f -> out.[out.Count - 1] <- f
                    | None -> out.Add b
                out.ToArray()
            and fuseBind b =
                match b with
                | TyLet(d, t, o) -> TyLet(d, t, fuseOp o)
                | TyLocalReturnOp(t, o, d) -> TyLocalReturnOp(t, fuseOp o, d)
                | x -> x
            and fuseOp o =
                match o with
                | TyIf(c, tr, fl) -> TyIf(c, fuseBlock tr, fuseBlock fl)
                | TyWhile(c, block) -> TyWhile(c, fuseBlock block)
                | TyDo block -> TyDo (fuseBlock block)
                | TyIndent block -> TyIndent (fuseBlock block)
                | TyUnionUnbox(vs, u, on_succs, on_fail) -> TyUnionUnbox(vs, u, on_succs |> Map.map (fun _ (bound, block) -> bound, fuseBlock block), on_fail |> Option.map fuseBlock)
                | TyIntSwitch(v, cases, on_fail) -> TyIntSwitch(v, cases |> Array.map fuseBlock, fuseBlock on_fail)
                | x -> x
            if opaque then body else fuseBlock body
        let rec live_binds (outer : int -> bool) (x : TypedBind []) : Set<int> =
            let mutable rest = Set.empty
            for k = x.Length - 1 downto 0 do
                let b = x.[k]
                let later = rest
                let after = fun i -> later.Contains i || outer i
                live_after.[b] <- after
                rest <- rest + (match b with TyLet(_,_,o) | TyLocalReturnOp(_,o,_) -> live_op after o | TyLocalReturnData(d,_) -> tags_of_data d)
            rest
        and live_op (after : int -> bool) (o : TypedOp) : Set<int> =
            match o with
            | TyMacro l -> l |> List.fold (fun s -> function CMTerm (d,_) -> s + tags_of_data d | _ -> s) Set.empty
            | TyArrayLiteral(_,l) | TyOp(_,l) -> l |> List.fold (fun s d -> s + tags_of_data d) Set.empty
            | TyToLayout(x,_) | TyUnionBox(_,x,_) | TyFailwith(_,x) | TyConv(_,x) | TyArrayCreate(_,x) | TyArrayLength(_,x) | TyStringLength(_,x) -> tags_of_data x
            | TyWhile((_,cond),body) ->
                let uses = live_binds outer_none body - defs_binds body
                let loop = tags_of_vars cond + uses
                live_binds (fun i -> loop.Contains i || after i) body |> ignore
                loop
            | TyDo body | TyIndent body -> live_binds after body
            | TyLayoutIndexAll(L(i,_)) | TyLayoutIndexByKey(L(i,_),_) -> Set.singleton i
            | TyApply(L(i,_),d) | TyLayoutMutableSet(L(i,_),_,d) -> Set.add i (tags_of_data d)
            | TyJoinPoint(_,args) -> tags_of_vars args
            | TyBackend _ | TySizeOf _ -> Set.empty
            | TyIf(cond,tr,fl) -> tags_of_data cond + live_binds after tr + live_binds after fl
            | TyUnionUnbox(vs,_,on_succs,on_fail) ->
                let arms = on_succs |> Map.fold (fun s _ (_,b) -> s + live_binds after b) (match on_fail with Some b -> live_binds after b | None -> Set.empty)
                unbox_arm_uses.[o] <- arms
                tags_of_vars vs + arms
            | TyIntSwitch(L(i,_),on_succ,on_fail) -> on_succ |> Array.fold (fun s b -> s + live_binds after b) (Set.add i (live_binds after on_fail))
        and defs_binds (x : TypedBind []) : Set<int> =
            x |> Array.fold (fun s b ->
                match b with
                | TyLet(d,_,o) -> s + tags_of_data d + defs_op o
                | TyLocalReturnOp(_,o,_) -> s + defs_op o
                | TyLocalReturnData _ -> s) Set.empty
        and defs_op (o : TypedOp) : Set<int> =
            match o with
            | TyWhile(_,b) | TyDo b | TyIndent b -> defs_binds b
            | TyIf(_,tr,fl) -> defs_binds tr + defs_binds fl
            | TyUnionUnbox(_,_,on_succs,on_fail) ->
                let s = match on_fail with Some b -> defs_binds b | None -> Set.empty
                on_succs |> Map.fold (fun s _ (lets,b) -> s + (lets |> List.fold (fun s d -> s + tags_of_data d) Set.empty) + defs_binds b) s
            | TyIntSwitch(_,on_succ,on_fail) -> on_succ |> Array.fold (fun s b -> s + defs_binds b) (defs_binds on_fail)
            | _ -> Set.empty
        let closure_opener = System.Text.RegularExpressions.Regex(@"\|[^|\n]*\|\s*[{\w(&*!\-\[]|\bmove\s*\|")
        let rec opens_closure (x : TypedBind []) =
            x |> Array.exists (function
                | TyLet(_,_,o) | TyLocalReturnOp(_,o,_) -> op_opens_closure o
                | TyLocalReturnData _ -> false)
        and op_opens_closure (o : TypedOp) =
            match o with
            | TyMacro l -> l |> List.exists (function CMText t -> closure_opener.IsMatch t | _ -> false)
            | TyIf(_,tr,fl) -> opens_closure tr || opens_closure fl
            | TyWhile(_,b) | TyDo b | TyIndent b -> opens_closure b
            | TyUnionUnbox(_,_,on_succs,on_fail) -> (on_succs |> Map.exists (fun _ (_,b) -> opens_closure b)) || (on_fail |> Option.exists opens_closure)
            | TyIntSwitch(_,on_succ,on_fail) -> Array.exists opens_closure on_succ || opens_closure on_fail
            | _ -> false
        let frozen = HashSet<TypedBind>(HashIdentity.Reference)
        let rec freeze (x : TypedBind []) =
            for b in x do
                frozen.Add b |> ignore
                match b with
                | TyLet(_,_,o) | TyLocalReturnOp(_,o,_) -> freeze_op o
                | TyLocalReturnData _ -> ()
        and freeze_op (o : TypedOp) =
            match o with
            | TyIf(_,tr,fl) -> freeze tr; freeze fl
            | TyWhile(_,b) | TyDo b | TyIndent b -> freeze b
            | TyUnionUnbox(_,_,on_succs,on_fail) -> on_succs |> Map.iter (fun _ (_,b) -> freeze b); on_fail |> Option.iter freeze
            | TyIntSwitch(_,on_succ,on_fail) -> Array.iter freeze on_succ; freeze on_fail
            | _ -> ()
        let macro_text (b : TypedBind) =
            match b with
            | TyLet(_,_,TyMacro l) | TyLocalReturnOp(_,TyMacro l,_) -> l |> List.choose (function CMText t -> Some t | _ -> None) |> String.concat ""
            | _ -> ""
        let braces (t : string) = (t |> Seq.filter ((=) '{') |> Seq.length) - (t |> Seq.filter ((=) '}') |> Seq.length)
        let rec freeze_regions (x : TypedBind []) : bool =
            let mutable closed = true
            let mutable i = 0
            while i < x.Length do
                let t = macro_text x.[i]
                if closure_opener.IsMatch t && braces t > 0 then
                    let mutable depth = braces t
                    let mutable j = i
                    while depth > 0 && j + 1 < x.Length do
                        j <- j + 1
                        depth <- depth + braces (macro_text x.[j])
                    if depth > 0 then closed <- false
                    freeze x.[i..j]
                    i <- j + 1
                else
                    match x.[i] with
                    | TyLet(_,_,o) | TyLocalReturnOp(_,o,_) -> if not (freeze_regions_op o) then closed <- false
                    | TyLocalReturnData _ -> ()
                    i <- i + 1
            closed
        and freeze_regions_op (o : TypedOp) : bool =
            match o with
            | TyIf(_,tr,fl) -> let a = freeze_regions tr in freeze_regions fl && a
            | TyWhile(_,b) | TyDo b | TyIndent b -> freeze_regions b
            | TyUnionUnbox(_,_,on_succs,on_fail) ->
                let a = on_succs |> Map.fold (fun ok _ (_,b) -> freeze_regions b && ok) true
                (match on_fail with Some b -> freeze_regions b | None -> true) && a
            | TyIntSwitch(_,on_succ,on_fail) -> let a = on_succ |> Array.fold (fun ok b -> freeze_regions b && ok) true in freeze_regions on_fail && a
            | _ -> true
        let live_root (outer : int -> bool) (x : TypedBind []) =
            live_binds outer x |> ignore
            if opens_closure x && not (freeze_regions x) then freeze x
        let splice_live (again : bool) = function WV (L(i,t)) -> not (is_copy t) && not (moves t) && (again || current_live.Value i) | WLit _ -> false
        let clone_or_name again w = match w with WV (L(i,_)) when splice_live again w -> $"v{i}.clone()" | _ -> macro_var w
        let emit_args (again : int -> bool) x =
            let arg w = match w with WV (L(i,_)) -> clone_or_name (again i) w | WLit _ -> macro_var w
            match data_term_vars x with
            | [||] -> "()"
            | [|x|] -> arg x
            | _ ->
                let rec spine = function DPair(a, b) -> a :: spine b | x -> [x]
                (match x with DNominal(x, _) -> spine x | x -> spine x) |> List.collect (fun e ->
                    match data_term_vars e with
                    | [||] -> []
                    | [|w|] -> [arg w]
                    | ws -> [ws |> Array.map show_w |> String.concat ", " |> sprintf "(%s)"])
                |> String.concat ", " |> sprintf "(%s)"

        let global' =
            let has_added = HashSet env.globals
            fun x -> if has_added.Add(x) then env.globals.Add x

        let string_slice () =
            global' "fn string_slice(value: &str, from: i64, to: i64) -> Rc<str> {\n    let bytes = value.as_bytes();\n    let length = bytes.len() as i64;\n    if from < 0 || from > length || to < from - 1 || to >= length { std::process::abort(); }\n    if to < from { return Rc::<str>::from(\"\"); }\n    if (bytes[from as usize] & 0xC0) == 0x80 || (to + 1 < length && (bytes[(to + 1) as usize] & 0xC0) == 0x80) { std::process::exit(3); }\n    let slice = &bytes[from as usize..(to + 1) as usize];\n    match std::str::from_utf8(slice) { Ok(text) => Rc::<str>::from(text), Err(error) => Rc::<str>::from(std::str::from_utf8(&slice[..error.valid_up_to()]).unwrap_or(\"\")) }\n}"

        let string_concat () =
            global' "fn string_concat(parts: &[&str]) -> Rc<str> {\n    let mut joined = Rc::<[u8]>::new_uninit_slice(parts.iter().map(|part| part.len()).sum());\n    let bytes = Rc::get_mut(&mut joined).unwrap().as_mut_ptr() as *mut u8;\n    let mut at = 0;\n    for part in parts {\n        unsafe { std::ptr::copy_nonoverlapping(part.as_ptr(), bytes.add(at), part.len()) };\n        at += part.len();\n    }\n    unsafe { Rc::from_raw(Rc::into_raw(joined.assume_init()) as *const str) }\n}"
        let concat_planned = Dictionary<TypedOp, Data list>(HashIdentity.Reference)
        let concat_reads (l : Data list) = l |> List.collect (fun d -> data_term_vars d |> Array.toList |> List.choose (function WV(L(j,_)) -> Some j | _ -> None))
        let concat_fusions (x : TypedBind []) =
            let fused = HashSet<int>()
            let defined = Dictionary<int, int>()
            let chain_reads = Dictionary<int, Set<int>>()
            let parts = Dictionary<int, Data list>()
            let vars (vs : TyV seq) = vs |> Seq.map (fun (L(i,_)) -> i) |> Seq.toList
            let plain_reads t =
                match x.[t] with
                | TyLet(_,_,o) ->
                    match o with
                    | TyOp(_,l) | TyArrayLiteral(_,l) -> Some (concat_reads l)
                    | TyMacro l -> Some (l |> List.collect (function CMTerm(d,_) -> concat_reads [d] | _ -> []))
                    | TyJoinPoint(_,a) -> Some (vars a)
                    | TyToLayout(d,_) | TyUnionBox(_,d,_) | TyConv(_,d) | TyArrayCreate(_,d) | TyArrayLength(_,d) | TyStringLength(_,d) -> Some (concat_reads [d])
                    | TyApply(v,d) -> Some (vars [v] @ concat_reads [d])
                    | TyLayoutIndexAll v | TyLayoutIndexByKey(v,_) -> Some (vars [v])
                    | _ -> None
                | _ -> None
            for m in 0 .. x.Length - 1 do
                match x.[m] with
                | TyLet(d,_,(TyOp(StaticStringConcat,([_;_] as l)) as o)) ->
                    let reads = concat_reads l
                    let mutable chain = Set.ofList reads
                    let absorbed = Dictionary<int, int>()
                    for j in List.distinct reads do
                        match defined.TryGetValue j with
                        | true, k ->
                            let inner = chain_reads.[k]
                            let once = reads |> List.filter ((=) j) |> List.length = 1
                            let dead_after = match live_after.TryGetValue x.[m] with | true, f -> not (f j) | _ -> false
                            let untouched = seq { k + 1 .. m - 1 } |> Seq.forall (fun t -> match x.[t] with TyLet(_,_,TyOp(StaticStringConcat,l')) -> not (List.contains j (concat_reads l')) | _ -> match plain_reads t with Some vs -> vs |> List.forall (fun v -> v <> j && not (Set.contains v inner)) | None -> false)
                            if once && dead_after && untouched then
                                fused.Add k |> ignore
                                absorbed.[j] <- k
                                chain <- Set.union (Set.remove j chain) inner
                        | _ -> ()
                    chain_reads.[m] <- chain
                    parts.[m] <- l |> List.collect (fun part ->
                        match data_term_vars part with
                        | [|WV(L(j,_))|] when absorbed.ContainsKey j -> parts.[absorbed.[j]]
                        | _ -> [part])
                    concat_planned.[o] <- parts.[m]
                    match data_free_vars d with
                    | [|L(i,_)|] -> defined.[i] <- m
                    | _ -> ()
                | _ -> ()
            fused

        let layout_default_ready = Dictionary<string, bool>()
        let union_default_ready = Dictionary<string, bool>()
        let rec tyv x =
            match x with
            | YUnion a ->
                let a = a.Item
                match a.layout with
                | UHeap -> sprintf "Rc<UH%i>" (uheap a.cases).tag
                | UStack -> sprintf "US%i" (ustack a.cases).tag
            | YLayout(_,lay) as a ->
                match lay with
                | Heap -> sprintf "Rc<Heap%i>" (heap a).tag
                | HeapMutable -> sprintf "Rc<RefCell<Mut%i>>" (mut a).tag
                | StackMutable -> raise_codegen_error "Compiler error: The Rust backend doesn't support stack mutable layout types."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
            | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameRust then Some v else None) with
                | Some x -> tup_ty x
                | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{backend_nameRust}' field."
            | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_litRust a) |> String.concat ""
            | YPrim a -> primRust a
            | YArray a -> sprintf "Rc<RefCell<Vec<%s>>>" (tup_ty a)
            | YFun(a,b,_) -> sprintf "Rc<dyn Fn(%s) -> %s>" (params_ty a) (tup_ty b)
            | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
            | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
            | a -> raise_codegen_error $"Type not supported in the codegen.\nGot: %A{a}"
        and params_ty x = env.ty_to_data x |> data_free_vars |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat ", "
        and param_list x = x |> Array.map (fun (L(i,t)) -> $"mut v{i}: {tyv t}") |> String.concat ", "
        and rust_borrowed (tag : int) (index : int) =
            (match method_borrowed.TryGetValue tag with | true, s -> s.Contains index | _ -> false)
            && (match group_sizes.TryGetValue tag with
                | true, n -> n
                | _ -> let n = (tail_group tag).Length in group_sizes.[tag] <- n; n) <= 1
        and method_param_list (tag : int) (x : TyV []) = x |> Array.mapi (fun n (L(i,t)) -> if rust_borrowed tag n then $"mut v{i}: &{tyv t}" else $"mut v{i}: {tyv t}") |> String.concat ", "
        and method_args (tag : int) (x : TyV []) = x |> Array.mapi (fun n (L(i,_) as v) -> if rust_borrowed tag n then (if current_borrowed.Contains i then $"v{i}" else $"&v{i}") else var v) |> String.concat ", "
        and binds (s : CodegenEnv) (x : TypedBind []) =
            let fused = concat_fusions x
            x |> Array.iteri (fun k b ->
              match b with
              | TyLet(_,_,TyOp(StaticStringConcat,_)) when fused.Contains k -> ()
              | _ ->
                let saved = current_live.Value
                let saved_known = current_known.Value
                let saved_counts = current_counts.Value
                current_live.Value <- (match live_after.TryGetValue b with | true, f -> f | _ -> outer_none)
                current_known.Value <- live_after.ContainsKey b && not (frozen.Contains b)
                current_counts.Value <- direct_counts b
                match b with
                | TyLet(d,trace,a) -> try op s (Some d) a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) -> try op s None a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) -> try line s (if self_loop.IsSome then $"return {tup d};" else tup d) with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                current_live.Value <- saved
                current_known.Value <- saved_known
                current_counts.Value <- saved_counts
                )
        and tup x =
            match data_term_vars x with
            | [||] -> "()"
            | [|x|] -> show_w x
            | x -> Array.map show_w x |> String.concat ", " |> sprintf "(%s)"
        and tup_ty x =
            match env.ty_to_data x |> data_free_vars |> Array.map (fun (L(_,x)) -> tyv x) with
            | [||] -> "()"
            | [|x|] -> x
            | x -> String.concat ", " x |> sprintf "(%s)"
        and op s d a =
            let concat_op = a
            let jp (a, b) =
                match a with
                | JPMethod(a,c) -> let tag = (method (a,c)).tag in sprintf "%s(%s)" method_names.[tag] (method_args tag b)
                | JPClosure(a,c) -> sprintf "%s(%s)" closure_names.[(closure (a,c)).tag] (args b)
            let annot t = let x = tyv t in if x.StartsWith "impl " || x.StartsWith "Impl<" then "_" else x
            let binding d =
                match data_free_vars d with
                | [||] -> None
                | [|L(i,t)|] -> Some $"let mut v{i}: {annot t} ="
                | x ->
                    let names = x |> Array.map (fun (L(i,_)) -> $"mut v{i}") |> String.concat ", "
                    let tys = x |> Array.map (fun (L(_,t)) -> annot t) |> String.concat ", "
                    Some $"let ({names}): ({tys}) ="
            let simple x =
                match d with
                | None -> line s (if self_loop.IsSome then $"return {x};" else x)
                | Some d -> match binding d with Some b -> line s $"{b} {x};" | None -> line s $"{x};"
            let complex head (f : CodegenEnv -> unit) =
                match d with
                | None -> line s head; f s; line s "}"
                | Some d ->
                    match binding d with
                    | Some b -> line s $"{b} {head}"; without_self_loop (fun () -> f s); line s "};"
                    | None -> line s head; without_self_loop (fun () -> f s); line s "};"
            let block s (x : TypedBind []) = binds (indent s) x
            let layout_index i (lay : Layout) x =
                let field = match lay with HeapMutable -> $"v{i}.borrow()" | _ -> $"v{i}"
                x |> Array.map (fun (L(i',t')) -> if is_copy t' then $"{field}.l{i'}" else $"{field}.l{i'}.clone()")
                |> function
                    | [||] -> ()
                    | [|x|] -> simple x
                    | x -> String.concat ", " x |> sprintf "(%s)" |> simple
            let length (a,b) len =
                match a with
                | YPrim (Int8T | Int16T | Int32T | Int64T | UInt8T | UInt16T | UInt32T | UInt64T) -> simple $"({tup b}{len} as {tyv a})"
                | _ -> raise_codegen_error "Compiler error: Expected an int in length"
            let union_case_name prefix (union_rec : UnionRecFsharp) i = $"{prefix}{union_rec.tag}::{prefix}{union_rec.tag}_{unionCaseSuffix union_rec i}"
            match a with
            | TyMacro a ->
                let a = List.toArray a
                let text k = if k >= 0 && k < a.Length then (match a.[k] with CMText t -> t | _ -> "") else ""
                let tags = a |> Array.map (function CMTerm (x,_) -> data_term_vars x |> Array.choose (function WV (L(i,_)) -> Some i | WLit _ -> None) | _ -> [||])
                let again k i = (tags.[k] |> Array.filter ((=) i)).Length > 1 || Seq.exists (fun j -> Array.contains i tags.[j]) (seq { k + 1 .. a.Length - 1 })
                let sb = StringBuilder()
                let factoryMarked k = (text (k-1)).EndsWith (rustClosureFactoryMarker + " ")
                a |> Array.iteri (fun k part ->
                    let s : string =
                      match part with
                      | CMText x when x.EndsWith (rustClosureFactoryMarker + " ") && (match Array.tryItem (k + 1) a with Some (CMTerm _) -> true | _ -> false) ->
                          x.Substring (0, x.Length - rustClosureFactoryMarker.Length - 1)
                      | CMText x -> x
                      | CMTerm (x,false) when factoryMarked k ->
                          match data_term_vars x with
                          | [| WV (L (i, _)) |] when closure_of_var.ContainsKey i -> closure_names.[closure_of_var.[i]]
                          | _ -> raise_codegen_error "A closure that crosses threads must capture nothing: its factory runs once per worker thread, so captured Rc values would be shared between threads."
                      | CMTerm (x,false) when (let t = text (k-1) in rustEmitMarkers |> List.exists (fun m -> t.EndsWith (m + " "))) -> emit_args (again k) x
                      | CMTerm (x,inl) ->
                          let name w = match w with WV (L(i,_)) when rustSpliceConsumes (sb.ToString()) (text (k+1)) -> clone_or_name (again k i) w | _ -> macro_var w
                          if inl then x |> data_term_vars |> Array.map name |> String.concat ", "
                          else match data_term_vars x with [|w|] -> name w | _ -> tup x
                      | CMType x -> tup_ty x
                      | CMTypeLit x -> type_litRust x
                    sb.Append(s) |> ignore)
                sb.ToString() |> simple
            | TySizeOf t -> simple $"(std::mem::size_of::<{tup_ty t}>() as i32)"
            | TyIf(cond,tr,fl) ->
                complex $"if {tup cond} {{" <| fun s' ->
                    block s' tr
                    match fl with
                    | [|TyLocalReturnData(DB,_)|] -> ()
                    | _ -> line s' "} else {"; block s' fl
            | TyJoinPoint(JPMethod(a,c),args) when d.IsNone && (match group_loop with Some (_, members) -> members.Contains (method (a,c)).tag | None -> false) ->
                let name = fst group_loop.Value
                let tag = (method (a,c)).tag
                let values = Array.map var args |> String.concat ", "
                line s (if values = "" then $"st = {name}::M{tag};" else $"st = {name}::M{tag}({values});")
                line s "continue;"
            | TyJoinPoint(JPMethod(a,c),args) when d.IsNone && (match self_loop with Some (tag, _) -> (method (a,c)).tag = tag | None -> false) ->
                let loop_tag = fst self_loop.Value
                let slot_value (n : int) (L(j,_) as a) = if rust_borrowed loop_tag n then $"v{j}" else var a
                let changed = Array.zip (snd self_loop.Value) args |> Array.indexed |> Array.filter (fun (_, (L(i,_), L(j,_))) -> i <> j)
                match changed with
                | [||] -> ()
                | [|n, (L(i,_), a)|] -> line s $"v{i} = {slot_value n a};"
                | _ ->
                    let names = changed |> Array.map (fun (_, (L(i,_), _)) -> $"v{i}") |> String.concat ", "
                    let values = changed |> Array.map (fun (n, (_, a)) -> slot_value n a) |> String.concat ", "
                    line s $"({names}) = ({values});"
                line s "continue;"
            | TyJoinPoint(JPClosure(a,c) as a',args) ->
                match d with
                | Some (DV(L(i,_))) when args.Length = 0 -> closure_of_var.[i] <- (closure (a,c)).tag
                | _ -> ()
                simple (jp (a', args))
            | TyJoinPoint(a,args) -> simple (jp (a, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The Rust backend does not support nesting other backends."
            | TyWhile(a,b) ->
                let saved_moves = allow_moves
                allow_moves <- false
                let cond = jp a
                allow_moves <- saved_moves
                complex $"while {cond} {{" <| fun s' -> without_self_loop (fun () -> block s' b)
            | TyDo a | TyIndent a -> complex "{" <| fun s' -> block s' a
            | TyIntSwitch(L(i,_),on_succ,on_fail) ->
                complex $"match v{i} {{" <| fun s' ->
                    let s'' = indent s'
                    Array.iteri (fun i x -> line s'' $"{i} => {{"; block s'' x; line s'' "}") on_succ
                    line s'' "_ => {"; block s'' on_fail; line s'' "}"
            | TyUnionUnbox(is,x,on_succs,on_fail) ->
                let x' = x.Item
                let union_rec, prefix =
                    match x'.layout with
                    | UHeap -> uheap x'.cases, "UH"
                    | UStack -> ustack x'.cases, "US"
                let moving = union_has_moving_field union_rec
                let dead (L(i,_)) =
                    allow_moves && current_known.Value && not (current_live.Value i) && not (current_borrowed.Contains i)
                    && (match current_counts.Value.TryGetValue i with | true, n -> n = 1 | _ -> false)
                    && (match unbox_arm_uses.TryGetValue a with | true, arms -> not (arms.Contains i) | _ -> false)
                let heap_value = x'.layout = UHeap && not moving && List.forall dead is
                let by_value = heap_value || (x'.layout = UStack && (moving || List.forall dead is))
                let scrutinee (L(i,_)) = match x'.layout with UHeap when heap_value -> $"Rc::unwrap_or_clone(v{i})" | UHeap when current_borrowed.Contains i -> $"&**v{i}" | UHeap -> $"&*v{i}" | UStack when by_value -> $"v{i}" | UStack -> $"&v{i}"
                let bind_field (L(v,t)) =
                    if by_value then $"let mut v{v}: {tyv t} = v{v};"
                    elif is_copy t then $"let mut v{v}: {tyv t} = *v{v};"
                    elif not (moves t) then $"let mut v{v}: {tyv t} = v{v}.clone();"
                    else match x'.layout with UStack -> $"let mut v{v}: {tyv t} = v{v};" | UHeap -> $"let mut v{v} = v{v};"
                let case_tag k =
                    union_rec.free_vars
                    |> Seq.tryPick (function KeyValue ((tag, name), _) when name = UnionTagIdOps.text k -> Some tag | _ -> None)
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text k}.")
                let scrutinees = is |> List.map scrutinee
                let head = match scrutinees with [x] -> x | x -> String.concat ", " x |> sprintf "(%s)"
                complex $"match {head} {{" <| fun s' ->
                    let s'' = indent s'
                    Map.iter (fun k (a,b) ->
                        let i = case_tag k
                        let fields = a |> List.map data_free_vars
                        let patterns =
                            fields |> List.map (fun vars ->
                                match vars with
                                | [||] -> union_case_name prefix union_rec i
                                | vars -> vars |> Array.map (fun (L(v,_)) -> $"v{v}") |> String.concat ", " |> sprintf "%s(%s)" (union_case_name prefix union_rec i))
                        let pattern = match patterns with [x] -> x | x -> String.concat ", " x |> sprintf "(%s)"
                        line s'' $"{pattern} => {{"
                        fields |> List.iter (Array.iter (fun x -> line (indent s'') (bind_field x)))
                        block s'' b
                        line s'' "}"
                        ) on_succs
                    match on_fail with
                    | Some b -> line s'' "_ => {"; block s'' b; line s'' "}"
                    | None when List.length is = 1 && on_succs.Count > 0 && on_succs.Count = union_rec.free_vars.Count -> ()
                    | None -> line s'' "_ => unreachable!(),"
            | TyUnionBox(a,b,c) ->
                let c = c.Item
                let union_rec, prefix =
                    match c.layout with
                    | UHeap -> uheap c.cases, "UH"
                    | UStack -> ustack c.cases, "US"
                let i =
                    union_rec.free_vars
                    |> Seq.tryPick (function KeyValue ((tag, name), _) when name = UnionTagIdOps.text a -> Some tag | _ -> None)
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text a}.")
                let value =
                    match data_term_vars b with
                    | [||] -> union_case_name prefix union_rec i
                    | x -> Array.map show_w x |> String.concat ", " |> sprintf "%s(%s)" (union_case_name prefix union_rec i)
                match c.layout with
                | UHeap when Array.isEmpty (data_term_vars b) ->
                    $"{{ thread_local!{{ static CASE: Rc<{prefix}{union_rec.tag}> = Rc::new({value}); }} CASE.with(|case| case.clone()) }}"
                | UHeap -> $"Rc::new({value})"
                | UStack -> value
                |> simple
            | TyToLayout(a,b) ->
                let fields = a |> data_term_vars |> Array.mapi (fun i x -> $"l{i}: {show_w x}") |> String.concat ", "
                match b with
                | YLayout(_,Heap) -> $"Rc::new(Heap{(heap b).tag} {{ {fields} }})"
                | YLayout(_,HeapMutable) -> $"Rc::new(RefCell::new(Mut{(mut b).tag} {{ {fields} }}))"
                | YLayout(_,StackMutable) -> raise_codegen_error "The Rust backend doesn't support stack mutable layout types."
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (4).\nGot: %s{show_ty b}"
                |> simple
            | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The Rust backend doesn't support indexing into stack mutable layout types."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                |> fun x -> layout_index i lay x.free_vars
            | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The Rust backend doesn't support indexing into stack mutable layout types."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                |> fun x ->
                    x.free_vars_by_key
                    |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None)
                    |> Option.iter (layout_index i lay)
            | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
            | TyLayoutMutableSet(L(i,t),b,c) ->
                let a = List.fold (fun s k ->
                    match s with
                    | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                    | _ -> raise_codegen_error "Compiler error: Expected a record.") (mut t).data b
                Array.iter2 (fun (L(i',_)) b -> line s $"v{i}.borrow_mut().l{i'} = {show_w b};") (data_free_vars a) (data_term_vars c)
                if d.IsNone then line s "()"
            | TyArrayLiteral(a,b) -> simple $"""Rc::new(RefCell::new(vec![{List.map tup b |> String.concat ", "}]))"""
            | TyArrayCreate(a,b) ->
                let elem =
                    let funTy =
                        match a with
                        | YFun _ -> Some a
                        | _ ->
                            match env.ty_to_data a |> data_free_vars with
                            | [|L(_, (YFun _ as f))|] -> Some f
                            | _ -> None
                    match funTy with
                    | Some f ->
                        match rust_default_expr f with
                        | Some value -> value
                        | None -> $"<{tup_ty a}>::default()"
                    | None -> $"<{tup_ty a}>::default()"
                simple $"Rc::new(RefCell::new(vec![{elem}; {tup b} as usize]))"
            | TyArrayLength(a,b) -> length (a,b) ".borrow().len()"
            | TyStringLength(a,b) -> length (a,b) ".len()"
            | TyFailwith(a,b) -> simple $"std::panic::panic_any::<std::string::String>(format!(\"{{}}\", {tup b}))"
            | TyConv(a,b) ->
                match a with
                | YPrim (Int8T | Int16T | Int32T | Int64T | UInt8T | UInt16T | UInt32T | UInt64T | Float32T | Float64T) -> simple $"({tup b} as {tyv a})"
                | _ -> raise_codegen_error $"Compiler error: Unexpected type in Conv. Got: {show_ty a}"
            | TyApply(L(i,_),b) -> simple $"""v{i}({data_term_vars b |> Array.map show_w |> String.concat ", "})"""
            | TyOp(Global, [DLit (LitString x)]) -> global' x
            | TyOp(Export, [DLit (LitString name); DV(L(i,YFun(domain,range,_)))]) ->
                if not (export_names.Add name) then raise_codegen_error $"Duplicate export: {name}."
                let tag =
                    match closure_of_var.TryGetValue i with
                    | true, tag -> tag
                    | _ -> raise_codegen_error $"Compiler error: the exported function {name} is not a closure without captures."
                let parameters = env.ty_to_data domain |> data_free_vars
                let exported_record =
                    match domain with
                    | YNominal n ->
                        match env.nominal_apply domain with
                        | YRecord fields when not fields.IsEmpty && fields |> Map.forall (fun _ t -> match t with YPrim _ -> true | _ -> false) -> Some (n.node.name, fields)
                        | _ -> None
                    | _ -> None
                let decl, call =
                    match exported_record with
                    | Some (record_name, fields) ->
                        let record_name = record_name |> String.map (fun c -> if System.Char.IsLetterOrDigit c || c = '_' then c else '_')
                        if exported_record_names.Add record_name then
                            let members = fields |> Map.toArray |> Array.map (fun ((_,k),t) -> $"    pub {k}: {tyv t},") |> String.concat "\n"
                            exports.Insert(0, $"pub struct {record_name} {{\n{members}\n}}\n")
                        $"v: {record_name}", (fields |> Map.toArray |> Array.map (fun ((_,k),_) -> $"v.{k}") |> String.concat ", ")
                    | None ->
                        let shares_rc = rc_str_exports.Contains name
                        parameters |> Array.map (fun (L(k,t)) -> match t with YPrim StringT -> (if shares_rc then $"v{k}: &Rc<str>" else $"v{k}: &str") | t -> $"v{k}: {tyv t}") |> String.concat ", ",
                        parameters |> Array.map (fun (L(k,t)) -> match t with YPrim StringT -> (if shares_rc then $"Rc::clone(v{k})" else $"Rc::<str>::from(v{k})") | _ -> $"v{k}") |> String.concat ", "
                let returned_record =
                    match range with
                    | YNominal n ->
                        match env.nominal_apply range with
                        | YRecord fields when not fields.IsEmpty && fields |> Map.forall (fun _ t -> match t with YPrim _ -> true | _ -> false) ->
                            Some (n.node.name |> String.map (fun c -> if System.Char.IsLetterOrDigit c || c = '_' then c else '_'), fields)
                        | _ -> None
                    | _ -> None
                match returned_record with
                | Some (record_name, fields) ->
                    if exported_record_names.Add record_name then
                        let members = fields |> Map.toArray |> Array.map (fun ((_,k),t) -> $"    pub {k}: {tyv t},") |> String.concat "\n"
                        exports.Insert(0, $"pub struct {record_name} {{\n{members}\n}}\n")
                    let parts = fields |> Map.toArray |> Array.mapi (fun j ((_,k),_) -> k, $"f{j}")
                    let binding = if parts.Length = 1 then snd parts.[0] else parts |> Array.map snd |> String.concat ", " |> sprintf "(%s)"
                    let build = parts |> Array.map (fun (k, f) -> $"{k}: {f}") |> String.concat ", "
                    exports.Add($"pub fn {name}({decl}) -> {record_name} {{\n    let {binding} = {closure_names.[tag]}()({call});\n    {record_name} {{ {build} }}\n}}\n")
                | None ->
                    exports.Add($"pub fn {name}({decl}) -> {tup_ty range} {{\n    {closure_names.[tag]}()({call})\n}}\n")
                if d.IsNone then line s "()"
            | TyOp(op,l) ->
                let unary f = match l with [x] -> f $"({tup x})" | _ -> raise_codegen_error $"Compiler error: {op} expects one argument."
                match op, l with
                | Dyn,[a] -> tup a
                | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                | StringIndex, [a;b] -> $"{tup a}.as_bytes()[{tup b} as usize]"
                | StringSlice, [a;b;c] -> string_slice (); $"string_slice(&{tup a}, {tup b} as i64, {tup c} as i64)"
                | StaticStringConcat, [a;b] ->
                    string_concat ()
                    let literal (text : string) =
                        let owned = litRust (LitString text)
                        if owned.StartsWith "Rc::<str>::from(" && owned.EndsWith ")" then owned.Substring(16, owned.Length - 17) else owned
                    let parts, pending =
                        (([], None), (match concat_planned.TryGetValue concat_op with | true, planned -> planned | _ -> [a;b])) ||> List.fold (fun (parts, pending) d ->
                            match data_term_vars d, pending with
                            | [|WLit (LitString text)|], Some before -> parts, Some (before + text)
                            | [|WLit (LitString text)|], None -> parts, Some text
                            | terms, _ ->
                                let parts = match pending with Some text -> literal text :: parts | None -> parts
                                let part = match terms with [|WV(L(i,_))|] -> $"&*v{i}" | _ -> $"&*{tup d}"
                                part :: parts, None)
                    let parts = match pending with Some text -> literal text :: parts | None -> parts
                    $"""string_concat(&[{parts |> List.rev |> String.concat ", "}])"""
                | ArrayIndex, [a;b] ->
                    let handle, element = match data_term_vars a with [|WV(L(i,YArray t))|] -> $"v{i}", Some t | _ -> tup a, None
                    let read = $"{handle}.borrow()[{tup b} as usize]"
                    match element with Some t when is_copy t -> read | _ -> read + ".clone()"
                | ArrayIndexSet, [a;b;c] ->
                    let handle = match data_term_vars a with [|WV(L(i,_))|] -> $"v{i}" | _ -> tup a
                    $"{handle}.borrow_mut()[{tup b} as usize] = {tup c}"

                | (Add | Sub | Mult | Div | Mod | ShiftLeft | ShiftRight), [a;b] when rust_int a ->
                    let m = match op with Add -> "wrapping_add" | Sub -> "wrapping_sub" | Mult -> "wrapping_mul" | Div -> "wrapping_div" | Mod -> "wrapping_rem" | ShiftLeft -> "wrapping_shl" | _ -> "wrapping_shr"
                    let b = match op with ShiftLeft | ShiftRight -> $"({tup b}) as u32" | _ -> tup b
                    $"{rust_receiver (tup a)}.{m}({b})"
                | Neg, [a] when rust_int a -> $"{rust_receiver (tup a)}.wrapping_neg()"
                | Add, [a;b] -> $"{tup a} + {tup b}"
                | Sub, [a;b] -> $"{tup a} - {tup b}"
                | Mult, [a;b] -> $"{tup a} * {tup b}"
                | Div, [a;b] -> $"{tup a} / {tup b}"
                | Mod, [a;b] -> $"{tup a} %% {tup b}"
                | Pow, [a;b] -> $"{tup a}.powf({tup b})"
                | (EQ | NEQ | LT | LTE | GT | GTE), [a;b] when (match data_term_vars a with [|WV(L(_,YPrim StringT))|] | [|WLit (LitString _)|] -> true | _ -> false) ->
                    let borrowed_str (d : Data) =
                        match data_term_vars d with
                        | [|WV(L(i,_))|] -> $"&*v{i}"
                        | [|WLit (LitString _ as l)|] ->
                            let owned = litRust l
                            if owned.StartsWith "Rc::<str>::from(" && owned.EndsWith ")" then owned.Substring(16, owned.Length - 17) else owned
                        | _ -> tup d
                    let symbol = match op with EQ -> "==" | NEQ -> "!=" | LT -> "<" | LTE -> "<=" | GT -> ">" | _ -> ">="
                    $"{borrowed_str a} {symbol} {borrowed_str b}"
                | LT, [a;b] -> $"{tup a} < {tup b}"
                | LTE, [a;b] -> $"{tup a} <= {tup b}"
                | EQ, [a;b] -> $"{tup a} == {tup b}"
                | NEQ, [a;b] -> $"{tup a} != {tup b}"
                | GT, [a;b] -> $"{tup a} > {tup b}"
                | GTE, [a;b] -> $"{tup a} >= {tup b}"
                | BoolAnd, [a;b] -> $"{tup a} && {tup b}"
                | BoolOr, [a;b] -> $"{tup a} || {tup b}"
                | BitwiseAnd, [a;b] -> $"{tup a} & {tup b}"
                | BitwiseOr, [a;b] -> $"{tup a} | {tup b}"
                | BitwiseXor, [a;b] -> $"{tup a} ^ {tup b}"
                | BitwiseComplement, [a] -> $"!{tup a}"
                | ShiftLeft, [a;b] -> $"{tup a} << {tup b}"
                | ShiftRight, [a;b] -> $"{tup a} >> {tup b}"

                | Neg, _ -> unary (sprintf "-%s")
                | Log, _ -> unary (sprintf "%s.ln()")
                | Exp, _ -> unary (sprintf "%s.exp()")
                | Tanh, _ -> unary (sprintf "%s.tanh()")
                | Sqrt, _ -> unary (sprintf "%s.sqrt()")
                | Sin, _ -> unary (sprintf "%s.sin()")
                | Cos, _ -> unary (sprintf "%s.cos()")
                | PrimToString, [a] ->
                    match a with
                    | DLit(LitChar _) | DV(L(_,YPrim CharT)) -> $"Rc::<str>::from((({tup a}) as char).to_string())"
                    | _ -> $"Rc::<str>::from(({tup a}).to_string())"
                | NanIs, _ -> unary (sprintf "%s.is_nan()")
                | StdoutFlush, [] -> "{ use std::io::Write; std::io::stdout().flush().unwrap(); }"
                | Assign, [a;b] -> $"{tup a} = {tup b}"
                | MonotonicDelayMs, [a] -> $"std::thread::sleep(std::time::Duration::from_millis({tup a} as u64))"
                | Printf, [DLit (LitString fmt); b] ->
                    let rfmt = StringBuilder()
                    let args = ResizeArray()
                    for p in printf_pieces fmt (data_term_vars b) do
                        match p with
                        | Choice1Of2 t -> rfmt.Append(t.Replace("{", "{{").Replace("}", "}}")) |> ignore
                        | Choice2Of2 (_, a) -> rfmt.Append "{}" |> ignore; args.Add(show_w a)
                    let quoted = litRust (LitString (rfmt.ToString()))
                    let quoted = quoted.Substring(quoted.IndexOf '"', quoted.LastIndexOf '"' - quoted.IndexOf '"' + 1)
                    String.concat ", " (quoted :: List.ofSeq args) |> sprintf "print!(%s)"
                | UnionTag, [DV(L(i,YUnion u))] ->
                    let ty = match d with Some (DV(L(_,t))) -> tyv t | _ -> "i32"
                    union_tags_used.Add(union_name u.Item) |> ignore
                    $"(v{i}.tag() as {ty})"
                | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported in the Rust backend" op l.Length
                |> simple
        and rust_emit_default (s : CodegenEnv) (name : string) (body : string) =
            let impl = {text=StringBuilder(); indent=s.indent}
            line impl $"impl Default for {name} {{"
            line (indent impl) "fn default() -> Self {"
            line (indent (indent impl)) body
            line (indent impl) "}"
            line impl "}"
            default_impls.[name] <- impl.text.ToString()
        // Rc<str> has no Default, and dyn Fn cannot. A derive on every heap would reject samples that never call default().
        and rust_layout_default (kind : string) (x : LayoutRecFsharp) =
            let key = $"{kind}{x.tag}"
            let mutable ready = true
            let parts = ResizeArray<string>()
            for L(i, t) in x.free_vars do
                match rust_default_expr t with
                | Some value -> parts.Add($"l{i}: {value}")
                | None -> ready <- false
            layout_default_ready.[key] <- ready
            let joined = String.concat ", " parts
            if ready then Some $"{key} {{ {joined} }}" else None
        and rust_union_default (prefix : string) (x : UnionRecFsharp) =
            let key = $"{prefix}{x.tag}"
            if Map.isEmpty x.free_vars then
                union_default_ready.[key] <- false
                None
            else
                let ((i0, _), fields0) = x.free_vars |> Map.toSeq |> Seq.head
                let case = $"{key}::{key}_{unionCaseSuffix x i0}"
                let mutable ready = true
                let parts = ResizeArray<string>()
                for L(_, t) in fields0 do
                    match rust_default_expr t with
                    | Some value -> parts.Add(value)
                    | None -> ready <- false
                union_default_ready.[key] <- ready
                if not ready then None
                elif fields0.Length = 0 then Some case
                else Some (case + "(" + (parts |> String.concat ", ") + ")")
        and rust_default_expr (t : Ty) : string option =
            let rec go depth (t : Ty) =
                if depth > 64 then None else
                match t with
                | YPrim StringT -> Some "Rc::<str>::from(\"\")"
                | YPrim p -> Some $"<{primRust p}>::default()"
                | YArray _ -> Some $"<{tyv t}>::default()"
                | YLayout(_, Heap) ->
                    let rec_layout = heap t
                    match layout_default_ready.TryGetValue($"Heap{rec_layout.tag}") with
                    | true, true -> Some $"<{tyv t}>::default()"
                    | _ -> None
                | YLayout(_, HeapMutable) ->
                    let rec_layout = mut t
                    match layout_default_ready.TryGetValue($"Mut{rec_layout.tag}") with
                    | true, true -> Some $"<{tyv t}>::default()"
                    | _ -> None
                | YLayout _ -> None
                | YUnion u ->
                    let prefix, rec_u =
                        match u.Item.layout with
                        | UHeap -> "UH", uheap u.Item.cases
                        | UStack -> "US", ustack u.Item.cases
                    match union_default_ready.TryGetValue($"{prefix}{rec_u.tag}") with
                    | true, true -> Some $"<{tyv t}>::default()"
                    | _ -> None
                | YFun(domain, range, _) ->
                    match go_ty (depth + 1) range with
                    | None -> None
                    | Some ret ->
                        let args = env.ty_to_data domain |> data_free_vars |> Array.map (fun (L(i, pt)) -> $"mut v{i}: {tyv pt}") |> String.concat ", "
                        Some $"{{ let f: {tyv t} = Rc::new(|{args}| -> {tup_ty range} {{ {ret} }}); f }}"
                | YMacro [Text "backend_switch "; Type (YRecord r)] ->
