                line s "#[derive(Clone)]"
            line s $"enum {name} {{"
            x.free_vars |> Map.iter (fun (i,_) a ->
                match a with
                | [||] -> line (indent s) $"{name}_{unionCaseSuffix x i},"
                | a -> line (indent s) $"""{name}_{unionCaseSuffix x i}({a |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat ", "}),"""
                )
            line s "}"
            let impl = {text=StringBuilder(); indent=s.indent}
            line impl $"impl {name} {{"
            line (indent impl) "fn tag(&self) -> i32 {"
            line (indent (indent impl)) "match self {"
            x.free_vars |> Map.iter (fun (i,_) a ->
                let pattern = match a with [||] -> $"{name}::{name}_{unionCaseSuffix x i}" | _ -> $"{name}::{name}_{unionCaseSuffix x i}(..)"
                line (indent (indent (indent impl))) $"{pattern} => {i},"
                )
            line (indent (indent impl)) "}"
            line (indent impl) "}"
            line impl "}"
            union_tag_impls.[name] <- impl.text.ToString()
            match rust_union_default prefix x with
            | Some body -> rust_emit_default s name body
            | None -> ()
        and union_name (a : _) =
            match a.layout with
            | UHeap -> $"UH{(uheap a.cases).tag}"
            | UStack -> $"US{(ustack a.cases).tag}"
        and union_has_moving_field (x : UnionRecFsharp) = x.free_vars |> Map.exists (fun _ a -> a |> Array.exists (fun (L(_,t)) -> moves t))
        and uheap : _ -> UnionRecFsharp = union (union_type "UH")
        and ustack : _ -> UnionRecFsharp = union (union_type "US")
        and method : _ -> MethodRecFsharp =
            jp (fun ((jp_body,key),i) ->
                let args = codegenMethodKeyArgs key
                match codegenMethodBody env "Rust" jp_body key with
                | a, range, name ->
                    let a = fuseConcat a
                    method_names.[i] <- generatedMethodName name i
                    method_borrowed.[i] <- rdata_free_vars args |> Array.indexed |> Array.choose (fun (n, _) -> if borrowed_param (JPMethod(jp_body, key)) n then Some n else None) |> Set.ofArray
                    let record = {tag=i; free_vars=rdata_free_vars args; range=range; body=a}
                    method_records.[i] <- record
                    record
                ) (fun s x ->
                let group = tail_group x.tag
                let saved_group = group_loop
                let saved_borrowed = current_borrowed
                current_borrowed <- x.free_vars |> Array.indexed |> Array.choose (fun (n, L(i,_)) -> if rust_borrowed x.tag n then Some i else None) |> Set.ofArray
                group_loop <- None
                line s $"fn {method_names.[x.tag]}({method_param_list x.tag x.free_vars}) -> {tup_ty x.range} {{"
                if group.Length > 1 then
                    let values = x.free_vars |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
                    let variant = if values = "" then $"Group{group.Head}::M{x.tag}" else $"Group{group.Head}::M{x.tag}({values})"
                    line (indent s) $"group_{group.Head}({variant})"
                    if emitted_groups.Add group.Head then emit_group group x.range
                else
                    let looped = self_tail x.tag x.body
                    let body = if looped then tail_lets x.tag x.body else x.body
                    live_root outer_none body
                    let saved = self_loop
                    if looped then
                        self_loop <- Some (x.tag, x.free_vars)
                        line (indent s) "loop {"
                        binds (indent (indent s)) body
                        if tup_ty x.range = "()" then line (indent (indent s)) "return ();"
                        line (indent s) "}"
                    else
                        self_loop <- None
                        binds (indent s) x.body
                    self_loop <- saved
                line s "}"
                current_borrowed <- saved_borrowed
                group_loop <- saved_group
                )
        and tail_callees (body : TypedBind []) : int list =
            match Array.tryLast body with
            | Some (TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _)) -> [(method (a,c)).tag]
            | Some (TyLocalReturnOp(_, TyIf(_,tr,fl), _)) -> tail_callees tr @ tail_callees fl
            | Some (TyLocalReturnOp(_, TyUnionUnbox(_,_,on_succs,on_fail), _)) -> (on_succs |> Map.toList |> List.collect (fun (_,(_,b)) -> tail_callees b)) @ (on_fail |> Option.map tail_callees |> Option.defaultValue [])
            | Some (TyLocalReturnOp(_, TyIntSwitch(_,on_succ,on_fail), _)) -> (on_succ |> Array.toList |> List.collect tail_callees) @ tail_callees on_fail
            | Some (TyLocalReturnOp(_, (TyDo b | TyIndent b), _)) -> tail_callees b
            | _ -> []
        and tail_group (tag : int) : int list =
            let edges = Dictionary<int, int list>()
            let edges_of t =
                match edges.TryGetValue t with
                | true, e -> e
                | _ ->
                    let e = tail_callees method_records.[t].body
                    edges.[t] <- e
                    e
            let reach (start : int) =
                let seen = HashSet<int>()
                let rec go t = for u in edges_of t do if seen.Add u then go u
                go start
                seen
            let from_tag = reach tag
            if not (from_tag.Contains tag) then [tag]
            else from_tag |> Seq.filter (fun u -> u = tag || (reach u).Contains tag) |> Seq.sort |> List.ofSeq
