                if tup_ty range = "()" then line (indent arm) "return ();"
                line arm "}"
            self_loop <- saved_self
            group_loop <- saved_group
            line (indent (indent g)) "}"
            line (indent g) "}"
            line g "}"
            functions.Add(g.text.ToString())
