            | TyIntSwitch(v,on_succ,on_fail) -> TyIntSwitch(v, Array.map (tail_lets tag) on_succ, tail_lets tag on_fail)
            | TyDo b -> TyDo (tail_lets tag b)
            | TyIndent b -> TyIndent (tail_lets tag b)
