                ) (fun s x ->
                let domain_tys = x.domain_args |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat ", "
                let range = tup_ty x.range
                let saved_borrowed = current_borrowed
                current_borrowed <- Set.empty
                line s $"fn {closure_names.[x.tag]}({param_list x.free_vars}) -> Rc<dyn Fn({domain_tys}) -> {range}> {{"
                let captured = tags_of_vars x.free_vars
                live_root (fun i -> captured.Contains i) x.body
                if Array.isEmpty x.free_vars then
                    line (indent s) $"thread_local!{{ static CLOSURE: Rc<dyn Fn({domain_tys}) -> {range}> = Rc::new(move |{param_list x.domain_args}| -> {range} {{"
                    without_self_loop (fun () -> binds (indent (indent s)) x.body)
                    line (indent s) "}); } CLOSURE.with(|closure| closure.clone())"
                else
                    line (indent s) $"Rc::new(move |{param_list x.domain_args}| -> {range} {{"
                    without_self_loop (fun () -> binds (indent (indent s)) x.body)
                    line (indent s) "})"
                line s "}"
                current_borrowed <- saved_borrowed
                )

        let main = StringBuilder()
        let x = fuseConcat x
        live_root outer_none x
        binds {text=main; indent=4} x

        let program = StringBuilder()
        program.Append("#![allow(unused_mut, unused_variables, unused_imports, unused_parens, unused_braces, unused_assignments, dead_code, non_snake_case, non_camel_case_types, unreachable_code, while_true)]") |> ignore
        let inner, globals = env.globals |> Seq.toArray |> Array.partition (fun (x : string) -> x.TrimStart().StartsWith "#![")
        let static_closures = functions |> Seq.sumBy (fun (x : string) -> System.Text.RegularExpressions.Regex.Matches(x, @"thread_local!\{ static CLOSURE:").Count)
        if static_closures > 16 && not (inner |> Array.exists (fun x -> x.Contains "recursion_limit")) then
            let mutable limit = 256
            while limit < 4 * static_closures + 64 do limit <- limit * 2
            program.Append($" #![recursion_limit = \"{limit}\"]") |> ignore
        program.AppendLine() |> ignore
        inner |> Array.iter (fun x -> program.AppendLine(x) |> ignore)
        program.AppendLine("use std::cell::RefCell;").AppendLine("use std::rc::Rc;") |> ignore
        globals |> Array.iter (fun x -> program.AppendLine(x) |> ignore)
        types |> Seq.iter (fun x -> program.Append(x) |> ignore)
        let exported_generated = exported_union_names.Keys |> Seq.map (fun node -> union_name (unbox<Union> node).Item) |> HashSet
        union_tag_impls |> Seq.iter (fun kv ->
            if union_tags_used.Contains kv.Key || exported_generated.Contains kv.Key then program.Append(kv.Value) |> ignore)
        let default_uses = System.Text.RegularExpressions.Regex(@"<((?:[^<>]|<(?<d>)|>(?<-d>))*(?(d)(?!)))>::default\(\)")
        let default_names = System.Text.RegularExpressions.Regex(@"\w+")
        let defaults_reached = HashSet<string>()
        let rec reach_defaults (text : string) =
            for found in default_uses.Matches text do
                for word in default_names.Matches found.Groups.[1].Value do
                    let name = word.Value
                    if default_impls.ContainsKey name && defaults_reached.Add name then reach_defaults default_impls.[name]
        functions |> Seq.iter reach_defaults
        exports |> Seq.iter reach_defaults
        types |> Seq.iter reach_defaults
        reach_defaults (main.ToString())
        exported_generated |> Seq.iter (fun name ->
            if default_impls.ContainsKey name && defaults_reached.Add name then reach_defaults default_impls.[name])
        default_impls |> Seq.iter (fun kv -> if defaults_reached.Contains kv.Key then program.Append(kv.Value) |> ignore)
        functions |> Seq.iter (fun x -> program.Append(x) |> ignore)
        if exports.Count > 0 then
            exports |> Seq.iter (fun x -> program.Append(x) |> ignore)
        else
            match Array.tryLast x with
            | Some (TyLocalReturnOp(_,_,d)) | Some (TyLocalReturnData(d,_)) ->
                match data_term_vars d |> Array.map (function WV(L(_,t)) -> t | WLit l -> YPrim (lit_to_primitive_type l)) with
                | [||] | [|YPrim Int32T|] -> ()
                | _ -> raise_codegen_error "The return type of main in the Rust backend should be a 32-bit int (or unit)."
            | _ -> ()
            let main =
                let unitMain =
                    match Array.tryLast x with
                    | Some (TyLocalReturnOp(_,_,d)) | Some (TyLocalReturnData(d,_)) -> Array.isEmpty (data_term_vars d)
                    | _ -> true
                let text = main.ToString().TrimEnd()
                if not unitMain then text + "\n"
                elif text.EndsWith "\n    ()" || text = "    ()" then text.Substring(0, text.Length - 2) + "0\n"
                elif text.EndsWith "}" || text.EndsWith ";" || text = "" then text + "\n    0\n"
                else text + ";\n    0\n"
            program.AppendLine("fn spiral_main() -> i32 {").Append(main).AppendLine("}") |> ignore
            program.AppendLine("fn main() { #[cfg(target_arch = \"wasm32\")] { spiral_main(); return; }").AppendLine("    let main = std::thread::Builder::new().stack_size(1 << 30).spawn(spiral_main).unwrap();").AppendLine("    std::process::exit(match main.join() { Ok(code) => code, Err(_) => 1 });").AppendLine("}") |> ignore
        let rename_exported_unions (code : string) =
            exported_union_names |> Seq.fold (fun (code : string) (KeyValue(node, name)) ->
                let u = (unbox<Union> node).Item
                let generated = match u.layout with UHeap -> $"UH{(uheap u.cases).tag}" | UStack -> $"US{(ustack u.cases).tag}"
                let renamed = System.Text.RegularExpressions.Regex.Replace(code, $@"\b{generated}(?=\b|_)", name)
                let renamed = renamed.Replace($"\nenum {name} ", $"\npub enum {name} ")
                System.Text.RegularExpressions.Regex.Replace(renamed, $@"(\nimpl {name} \{{\r?\n    )fn tag\(", "${1}pub fn tag(")
                ) code
        let import_rust_unions (code : string) =
            if linked_units.IsEmpty then code
            else
                let candidates =
                    [ for KeyValue(node, source) in unionSourceNames do
                        match linkedUnionName linked_units node source with
                        | Some (unitName, name) -> yield union_name (unbox<Union> node).Item, name, unitName
                        | None -> () ]
                let renamed =
                    candidates |> List.fold (fun (code : string) (generated, name, _) ->
                        System.Text.RegularExpressions.Regex.Replace(code, $@"\b{generated}(?=\b|_)", name)) code
                let local_definitions name =
                    [
                        $@"(?m)^#\[derive\([^\]]*\)\]\r?\n(?=(pub )?enum {name} \{{)"
                        $@"(?ms)^(pub )?enum {name} \{{\r?\n.*?^\}}\r?\n"
                        $@"(?ms)^impl {name} \{{\r?\n.*?^\}}\r?\n"
                        $@"(?ms)^impl Default for {name} \{{\r?\n.*?^\}}\r?\n"
                    ]
                let dropped =
                    candidates
                    |> List.map (fun (_, name, _) -> name)
                    |> List.distinct
                    |> List.fold (fun (code : string) name ->
                        local_definitions name |> List.fold (fun (code : string) pattern ->
                            System.Text.RegularExpressions.Regex.Replace(code, pattern, "")) code) renamed
                let uses =
                    candidates
                    |> List.map (fun (_, name, unitName) -> unitName, name)
                    |> List.distinct
                    |> List.groupBy fst
                    |> List.map (fun (unitName, names) -> $"""use {unitName}::{{{names |> List.map snd |> String.concat ", "}}};""" + "\n")
                    |> String.concat ""
                System.Text.RegularExpressions.Regex("use std::rc::Rc;(\r?\n)").Replace(dropped, "use std::rc::Rc;${1}" + uses.Replace("$", "$$"), 1)
        program.ToString() |> translateFsharpInterpolations |> foldStringBindings |> inlineRustEmits
        |> rename_exported_unions
        |> import_rust_unions
        |> dropDeadRustLiterals
        |> cacheRustStringLiterals
        |> immutableRustLets
        |> rustMoveOnLastUse

    /// ### ParallelMove
    type ParallelMove =
        | MoveVar of target : int * source : int
        | SaveTemp of slot : int * source : int
        | MoveTemp of target : int * slot : int

    /// ### parallelMoves
    let parallelMoves (moves : (int * int) []) =
        let steps = ResizeArray<ParallelMove> ()
        let pending = moves |> Array.filter (fun (target, source) -> target <> source) |> Array.map (fun (target, source) -> target, Choice1Of2 source) |> ResizeArray
        let mutable slots = 0
        while pending.Count > 0 do
            let reads (target : int) = pending |> Seq.exists (fun (_, source) -> source = Choice1Of2 target)
            match pending |> Seq.tryFindIndex (fun (target, _) -> not (reads target)) with
            | Some index ->
                let target, source = pending.[index]
                steps.Add (match source with Choice1Of2 variable -> MoveVar (target, variable) | Choice2Of2 slot -> MoveTemp (target, slot))
                pending.RemoveAt index
            | None ->
                let target, _ = pending.[0]
                steps.Add (SaveTemp (slots, target))
                for index = 0 to pending.Count - 1 do
                    let moveTarget, source = pending.[index]
                    if source = Choice1Of2 target then pending.[index] <- (moveTarget, Choice2Of2 slots)
                slots <- slots + 1
        List.ofSeq steps

    /// ## CodegenPascal

    /// ### backend_namePascal
    let backend_namePascal = "Pascal"

    /// ### litPascal
    let litPascal = function
        | LitInt8 x -> if x < 0y then sprintf "(%i)" x else sprintf "%i" x
        | LitInt16 x -> if x < 0s then sprintf "(%i)" x else sprintf "%i" x
        | LitInt32 x -> if x < 0 then sprintf "(%i)" x else sprintf "%i" x
        | LitInt64 x -> if x < 0L then sprintf "(%i)" x else sprintf "%i" x
        | LitUInt8 x -> sprintf "%i" x
        | LitUInt16 x -> sprintf "%i" x
        | LitUInt32 x -> sprintf "%i" x
        | LitUInt64 x -> sprintf "%i" x
        | LitFloat32 x ->
            if x = infinityf then "Infinity"
            elif x = -infinityf then "(-Infinity)"
            elif Single.IsNaN x then "NaN"
            else x.ToString("R") |> add_dec_point |> fun x -> if x.StartsWith "-" then $"({x})" else x
        | LitFloat64 x ->
            if x = infinity then "Infinity"
            elif x = -infinity then "(-Infinity)"
            elif Double.IsNaN x then "NaN"
            else x.ToString("R") |> add_dec_point |> fun x -> if x.StartsWith "-" then $"({x})" else x
        | LitString x ->
            if x = "" then "''" else
            let strb = StringBuilder()
            let mutable quoted = false
            for b in Text.Encoding.UTF8.GetBytes x do
                if b >= 32uy && b < 127uy then
                    if not quoted then strb.Append '\'' |> ignore; quoted <- true
                    if b = byte '\'' then strb.Append "''" |> ignore else strb.Append (char b) |> ignore
                else
                    if quoted then strb.Append '\'' |> ignore; quoted <- false
                    strb.Append('#').Append(int b) |> ignore
            if quoted then strb.Append '\'' |> ignore
            strb.ToString()
        | LitChar x ->
            if int x > 127 then raise_codegen_error $"The Pascal backend represents chars as bytes; '{x}' is not ASCII."
            elif x >= ' ' && x <> '\'' && int x < 127 then sprintf "'%c'" x
            else sprintf "#%i" (int x)
        | LitBool x -> if x then "True" else "False"

    /// ### primPascal
    let primPascal = function
        | Int8T -> "ShortInt"
        | Int16T -> "SmallInt"
        | Int32T -> "LongInt"
        | Int64T -> "Int64"
        | UInt8T -> "Byte"
        | UInt16T -> "Word"
        | UInt32T -> "LongWord"
        | UInt64T -> "QWord"
        | Float32T -> "Single"
        | Float64T -> "Double"
        | BoolT -> "Boolean"
        | StringT -> "AnsiString"
        | CharT -> "AnsiChar"

    /// ### type_litPascal
    let type_litPascal = function
        | YLit x -> litPascal x
        | YSymbol x -> x
        | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."

    /// ### BindsReturnPascal
    type BindsReturnPascal = DLocal of TyV [] | DTail of Ty

    /// ### codegenPascal
    let codegenPascal (refc : TyV [] -> TypedBind [] -> (TypedBind -> Map<TyV, int>)) (env : PartEvalResult) (x : TypedBind []) =
        let refc_counts : (TypedBind -> Map<TyV, int>) ref = ref (fun _ -> Map.empty)
        let rcTy (t : Ty) = match t with YUnion u -> u.Item.layout = UHeap | YLayout(_,HeapMutable) | YFun _ -> true | _ -> false
        let rcValueHelpers = HashSet<string>()
        let method_names = Dictionary<int, string>()
        let closure_names = Dictionary<int, string>()
        let forwards = ResizeArray()
        let types = ResizeArray()
        let headers = ResizeArray()
        let bodies = ResizeArray()
        let globals = ResizeArray()
        let sharedSingletons = ResizeArray<string>()
        let rcClass (ty : string) = ty.StartsWith "TUH" || ty.StartsWith "TMut" || ty.StartsWith "TFun"
        let dropDecl (owned : string []) = if owned.Length = 0 then "" else " procedure DropFields; override;"
        let dropBody (name : string) (owned : string []) =
            if owned.Length > 0 then
                let releases = owned |> Array.map (fun field -> if field.EndsWith ";" then field else $"SpiralRelease({field});") |> String.concat " "
                bodies.Add($"procedure {name}.DropFields;\nbegin\n  {releases}\nend;")

        let memo (f : 'k -> int -> unit) =
            let dict = Dictionary<'k, int>(HashIdentity.Structural)
            fun (k : 'k) ->
                match dict.TryGetValue k with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[k] <- tag
                    f k tag
                    tag
        let memo_ref (f : 'k -> int -> unit) =
            let dict = Dictionary<'k, int>(HashIdentity.Reference)
            fun (k : 'k) ->
                match dict.TryGetValue k with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[k] <- tag
                    f k tag
                    tag
        let global' =
            let has_added = HashSet env.globals
            fun x -> if has_added.Add(x) then globals.Add x

        let new_locals (parameters : TyV []) =
            let names = HashSet(parameters |> Array.map (fun (L(i,_)) -> i))
            let decls = ResizeArray<string>()
            names, decls
        let text (s : CodegenEnv) = s.text.ToString()

        let is_float = function DV(L(_,YPrim (Float32T | Float64T))) | DLit(LitFloat32 _ | LitFloat64 _) -> true | _ -> false
        let prim_of = function DV(L(_,YPrim t)) -> Some t | DLit (LitInt8 _) -> Some Int8T | DLit (LitInt16 _) -> Some Int16T | DLit (LitInt32 _) -> Some Int32T | DLit (LitInt64 _) -> Some Int64T | _ -> None
        let show_w = function WV (L(i,_)) -> $"v{i}" | WLit a -> litPascal a
        let args (x : TyV []) = x |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
        let args' x = data_term_vars x |> Array.map show_w |> String.concat ", "

        let string_slice () =
            global' "function StringSlice(const value: AnsiString; from, upto: Int64): AnsiString;\nvar len: Int64;\nbegin\n  len := Length(value);\n  if (from < 0) or (from > len) or (upto < from - 1) or (upto >= len) then Halt(3);\n  if upto < from then Exit('');\n  if ((Ord(value[from + 1]) and $C0) = $80) or ((upto + 1 < len) and ((Ord(value[upto + 2]) and $C0) = $80)) then Halt(3);\n  Result := Copy(value, from + 1, upto - from + 1);\nend;"

        let layout_tags = Dictionary<Ty, LayoutRecFsharp>(HashIdentity.Structural)
        let mutable self_loop : (int * TyV []) option = None
        let rec tyv x =
            match x with
            | YUnion a ->
                let a = a.Item
                match a.layout with
                | UHeap -> sprintf "TUH%i" (uheap a.cases)
                | UStack -> sprintf "TUS%i" (ustack a.cases)
            | YLayout(_,lay) as a ->
                match lay with
                | Heap -> sprintf "THeap%i" (heap a).tag
                | HeapMutable -> sprintf "TMut%i" (mut a).tag
                | StackMutable -> raise_codegen_error "Compiler error: The Pascal backend doesn't support stack mutable layout types."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
            | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                match r |> Map.tryPick (fun (_, k) v -> if backend_key_canonical k = backend_namePascal then Some v else None) with
                | Some x -> tup_ty x
                | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{backend_namePascal}' field."
            | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_litPascal a) |> String.concat ""
            | YPrim a -> primPascal a
            | YArray a -> if countedElement a then sprintf "TBoxArray%i" (box_array_type a) else sprintf "TArray%i" (array_type (tup_ty a))
            | YFun(a,b,_) -> sprintf "TFun%i" (fun_type (a, b))
            | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
            | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
            | a -> raise_codegen_error $"Type not supported in the codegen.\nGot: %A{a}"
        and tyvs (x : Ty) = env.ty_to_data x |> data_free_vars
        and tup_ty x =
            match tyvs x |> Array.map (fun (L(_,t)) -> tyv t) with
            | [||] -> ""
            | [|x|] -> x
            | x -> sprintf "TTuple%i" (tuple_type x)
        and tup d = data_term_vars d |> Array.map show_w |> String.concat ", "
        and tup_as (range : Ty) d =
            match data_term_vars d with
            | [||] -> ""
            | [|x|] -> show_w x
            | x -> sprintf "TupleCreate%i(%s)" (tyvs range |> Array.map (fun (L(_,t)) -> tyv t) |> tuple_type) (Array.map show_w x |> String.concat ", ")
        and param_list (x : TyV []) = x |> Array.map (fun (L(i,t)) -> $"v{i}: {tyv t}") |> String.concat "; "
        and header name (parameters : TyV []) (range : string) =
            let ps = match param_list parameters with "" -> "" | ps -> $"({ps})"
            if range = "" then $"procedure {name}{ps}" else $"function {name}{ps}: {range}"
        and emit_function (name : string) (parameters : TyV []) (range : Ty) (body : TypedBind []) (forward : bool) =
            emit_function' None name parameters range body forward
        and emit_function' (self_tag : int option) (name : string) (parameters : TyV []) (range : Ty) (body : TypedBind []) (forward : bool) =
            let range' = tup_ty range
            let locals = new_locals parameters
            let s = {text=StringBuilder(); indent=2}
            let saved = self_loop
            let saved_refc = refc_counts.Value
            refc_counts.Value <- refc parameters body
            match self_tag with
            | Some tag when self_tail tag body ->
                self_loop <- Some (tag, parameters)
                line s "while True do begin"
                binds locals (indent s) (DTail range) body
                line s "end;"
            | _ ->
                self_loop <- None
                binds locals s (DTail range) body
            self_loop <- saved
            refc_counts.Value <- saved_refc
            if forward then headers.Add($"{header name parameters range'}; forward;")
            let decls = snd locals
            let var = if decls.Count = 0 then "" else "var\n" + (decls |> Seq.map (sprintf "  %s;") |> String.concat "\n") + "\n"
            bodies.Add($"{header name parameters range'};\n{var}begin\n{text s}end;")
        and declare (names : HashSet<int>, decls : ResizeArray<string>) (L(i,t)) =
            if names.Add i then decls.Add($"v{i}: {tyv t}")
        and temp (_ : HashSet<int>, decls : ResizeArray<string>) (ty : string) =
            let name = $"tmp{decls.Count}"
            decls.Add($"{name}: {ty}")
            name
        and refc_prefix (s : CodegenEnv) (stmt : TypedBind) =
            let counts = refc_counts.Value stmt

            counts |> Map.iter (fun (L(i,t)) n -> if n > 0 then (match rcCall "Retain" t $"v{i}" with Some call -> (for _ in 1 .. n do line s call) | None -> ()))
            counts |> Map.iter (fun (L(i,t)) n -> if n < 0 then (match rcCall "Release" t $"v{i}" with Some call -> (for _ in 1 .. -n do line s call) | None -> ()))
        and rcValue (t : Ty) : string option =
            let fields =
                match t with
                | YUnion u when u.Item.layout = UStack ->
                    Some (u.Item.cases |> Map.toArray |> Array.mapi (fun c (_, ct) -> env.ty_to_data ct |> data_free_vars |> Array.mapi (fun f (L(_,ft)) -> Some c, $"x.c{c}_{f}", ft)) |> Array.concat)
                | YLayout(_,Heap) -> Some ((heap t).free_vars |> Array.map (fun (L(i,ft)) -> None, $"x.l{i}", ft))
                | _ -> None
            match fields with
            | Some fields when fields |> Array.exists (fun (_, _, ft) -> rcTy ft || (rcValue ft).IsSome) ->
                let name = tyv t
                if rcValueHelpers.Add name then
                    let body (verb : string) =
                        let calls = fields |> Array.choose (fun (c, target, ft) -> rcCall verb ft target |> Option.map (fun call -> c, call))
                        let text =
                            match t with
                            | YUnion _ ->
                                let arms = calls |> Array.groupBy fst |> Array.map (fun (c, xs) -> "    " + string (Option.defaultValue 0 c) + ": begin " + (xs |> Array.map snd |> String.concat " ") + " end;") |> String.concat "\n"
                                "  case x.tag of\n" + arms + "\n  end;"
                            | _ -> "  " + (calls |> Array.map snd |> String.concat " ")
                        $"procedure Spiral{verb}_{name}(const x: {name});\nbegin\n{text}\nend;"
                    headers.Add($"procedure SpiralRetain_{name}(const x: {name}); forward;")
                    headers.Add($"procedure SpiralRelease_{name}(const x: {name}); forward;")
                    headers.Add($"function SpiralKeep_{name}(const x: {name}): {name}; forward;")
                    bodies.Add(body "Retain")
                    bodies.Add(body "Release")
                    bodies.Add($"function SpiralKeep_{name}(const x: {name}): {name};\nbegin\n  SpiralRetain_{name}(x); Result := x;\nend;")
                Some name
            | _ -> None
        and rcCall (verb : string) (t : Ty) (target : string) : string option =
            if rcTy t || (match t with YArray el -> countedElement el | _ -> false) then Some $"Spiral{verb}({target});"
            else rcValue t |> Option.map (fun name -> $"Spiral{verb}_{name}({target});")
        and binds locals (s : CodegenEnv) (ret : BindsReturnPascal) (stmts : TypedBind []) =
            Array.iter (fun stmt ->
                refc_prefix s stmt
                match stmt with
                | TyLet(d,trace,a) ->
                    try let d = data_free_vars d
                        d |> Array.iter (declare locals)
                        op locals s (DLocal d) a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) -> try op locals s ret a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) ->
                    try match ret with
                        | DLocal l -> Array.iter2 (fun (L(i,_)) b -> line s $"v{i} := {show_w b};") l (data_term_vars d)
                        | DTail range ->
                            match tup_as range d with "" -> () | x -> line s $"Result := {x};"
                            if self_loop.IsSome then line s "Exit;"
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) stmts
        and op locals (s : CodegenEnv) (ret : BindsReturnPascal) a =
            let binds = binds locals
            let return' (x : string) =
                match ret with
                | DLocal [||] -> line s $"{x};"
                | DLocal [|L(i,_)|] -> line s $"v{i} := {x};"
                | DLocal l ->
                    let tmp = temp locals (tuple_type (l |> Array.map (fun (L(_,t)) -> tyv t)) |> sprintf "TTuple%i")
                    line s $"{tmp} := {x};"
                    l |> Array.iteri (fun k (L(i,_)) -> line s $"v{i} := {tmp}.f{k};")
                | DTail range ->
                    if tup_ty range = "" then line s $"{x};" else line s $"Result := {x};"
                    if self_loop.IsSome then line s "Exit;"
            let layout_index (i : int) (fields : TyV []) =
                match ret with
                | DLocal l -> Array.iter2 (fun (L(t,_)) (L(f,_)) -> line s $"v{t} := v{i}.l{f};") l fields
                | DTail _ -> raise_codegen_error "Compiler error: Layout index should never come in end position."
            let jp (a, b) =
                let a' = match b with [||] -> "" | b -> $"({args b})"
                match a with
                | JPMethod(a,c) -> $"{method_names.[(method (a,c)).tag]}{a'}"
                | JPClosure(a,c) -> $"ClosureCreate{(closure (a,c)).tag}{a'}"
            let unary f = function [x] -> f (tup x) | _ -> raise_codegen_error "Compiler error: Expected one argument."
            match a with
            | TyMacro a -> a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup x) | CMType x -> tup_ty x | CMTypeLit x -> type_litPascal x) |> String.concat "" |> return'
            | TySizeOf t -> return' $"SizeOf({tup_ty t})"
            | TyIf(cond,tr,fl) ->
                line s $"if {tup cond} then begin"
                binds (indent s) ret tr
                line s "end else begin"
                binds (indent s) ret fl
                line s "end;"
            | TyJoinPoint(JPMethod(a,c),args) when (match ret, self_loop with DTail _, Some (tag, _) -> (method (a,c)).tag = tag | _ -> false) ->
                let parameters = snd self_loop.Value
                let types = parameters |> Array.map (fun (L(i,t)) -> i, t) |> dict
                let temps = System.Collections.Generic.Dictionary<int, string> ()
                for step in parallelMoves (Array.map2 (fun (L(target,_)) (L(source,_)) -> target, source) parameters args) do
                    match step with
                    | MoveVar (target, source) -> line s $"v{target} := v{source};"
                    | SaveTemp (slot, source) ->
                        temps.[slot] <- temp locals (tyv types.[source])
                        line s $"{temps.[slot]} := v{source};"
                    | MoveTemp (target, slot) -> line s $"v{target} := {temps.[slot]};"
                line s "Continue;"
            | TyJoinPoint(a,args) -> return' (jp (a, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The Pascal backend does not support nesting other backends."
            | TyWhile(a,b) ->
                let cond =
                    match a with
                    | JPMethod(x,c), wargs when wargs |> Array.exists (fun (L(_,t)) -> (rcCall "Retain" t "").IsSome) ->
                        let kept = wargs |> Array.map (fun (L(i,t)) -> if rcTy t then $"{tyv t}(SpiralKeep(v{i}))" else match rcValue t with Some name -> $"SpiralKeep_{name}(v{i})" | None -> $"v{i}") |> String.concat ", "
                        $"{method_names.[(method (x,c)).tag]}({kept})"
                    | _ -> jp a
                line s $"while {cond} do begin"
                binds (indent s) (DLocal [||]) b
                line s "end;"
            | TyDo a | TyIndent a -> binds s ret a
            | TyIntSwitch(L(i,_),on_succ,on_fail) ->
                line s $"case v{i} of"
                on_succ |> Array.iteri (fun k b -> line (indent s) $"{k}: begin"; binds (indent (indent s)) ret b; line (indent s) "end;")
                line (indent s) "else begin"; binds (indent (indent s)) ret on_fail; line (indent s) "end;"
                line s "end;"
            | TyUnionUnbox(is,x,on_succs,on_fail) ->
                let x' = x.Item
                let tag = match x'.layout with UHeap -> uheap x'.cases | UStack -> ustack x'.cases
                let case_index k =
                    x'.cases |> Seq.map (fun (KeyValue ((_,k'),_)) -> k') |> Seq.tryFindIndex (fun k' -> UnionTagIdOps.text k = k')
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text k}.")
                let head =
                    match is with
                    | [L(i,_)] -> $"v{i}.tag"
                    | L(i,_) :: _ ->
                        let tmp = temp locals "LongInt"
                        let same = is |> List.pairwise |> List.map (fun (L(a,_), L(b,_)) -> $"(v{a}.tag = v{b}.tag)") |> String.concat " and "
                        line s $"if {same} then {tmp} := v{i}.tag else {tmp} := -1;"
                        tmp
                    | [] -> raise_codegen_error "Compiler error: Union unbox without a scrutinee."
                line s $"case {head} of"
                on_succs |> Map.iter (fun k (a,b) ->
                    let c = case_index k
                    line (indent s) $"{c}: begin"
                    List.iter2 (fun (L(v,_)) a ->
                        data_free_vars a |> Array.iteri (fun f (L(i,_) as field) ->
                            declare locals field
                            line (indent (indent s)) $"v{i} := v{v}.c{c}_{f};")) is a
                    binds (indent (indent s)) ret b
                    line (indent s) "end;")
                on_fail |> Option.iter (fun b -> line (indent s) "else begin"; binds (indent (indent s)) ret b; line (indent s) "end;")
                line s "end;"
            | TyUnionBox(a,b,c) ->
                let c = c.Item
                let tag, prefix = match c.layout with UHeap -> uheap c.cases, "UH" | UStack -> ustack c.cases, "US"
                let i =
                    c.cases |> Seq.map (fun (KeyValue ((_,k),_)) -> k) |> Seq.tryFindIndex (fun k -> UnionTagIdOps.text a = k)
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text a}.")
                let vars = match args' b with "" -> "" | x -> $"({x})"
                return' $"{prefix}{tag}_{(generatedCaseSuffixes c.cases |> caseFoldedSuffixes).[i]}{vars}"
            | TyToLayout(a,b) ->
                let vars = match args' a with "" -> "" | x -> $"({x})"
                match b with
                | YLayout(_,Heap) -> $"HeapCreate{(heap b).tag}{vars}"
                | YLayout(_,HeapMutable) -> $"MutCreate{(mut b).tag}{vars}"
                | YLayout(_,StackMutable) -> raise_codegen_error "The Pascal backend doesn't support stack mutable layout types."
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (4).\nGot: %s{show_ty b}"
                |> return'
            | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                match lay with
                | Heap -> (heap a).free_vars
                | HeapMutable -> (mut a).free_vars
                | StackMutable -> raise_codegen_error "The Pascal backend doesn't support indexing into stack mutable layout types."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                |> layout_index i
            | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The Pascal backend doesn't support indexing into stack mutable layout types."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                |> fun (x : LayoutRecFsharp) -> x.free_vars_by_key |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None) |> Option.iter (layout_index i)
            | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
            | TyLayoutMutableSet(L(i,t),b,c) ->
                let a = List.fold (fun s k ->
                    match s with
                    | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                    | _ -> raise_codegen_error "Compiler error: Expected a record.") (mut t : LayoutRecFsharp).data b
                Array.iter2 (fun (L(i',t')) b ->
                    match b with
                    | WV _ when (rcCall "Retain" t' "").IsSome ->
                        let slot = $"v{i}.l{i'}"
                        line s ((rcCall "Retain" t' (show_w b)).Value + " " + (rcCall "Release" t' slot).Value + " " + slot + " := " + show_w b + ";")
                    | _ -> line s $"v{i}.l{i'} := {show_w b};") (data_free_vars a) (data_term_vars c)
            | TyArrayLiteral(a,b) when countedElement a ->
                let tag = box_array_type a
                let tmp = temp locals $"TBoxArray{tag}"
                line s $"{tmp} := TBoxArray{tag}.Create;"
                line s $"SetLength({tmp}.items, {b.Length});"
                b |> List.iteri (fun k x -> line s $"{tmp}.items[{k}] := {tup x};")
                return' tmp
            | TyArrayLiteral(a,b) ->
                let tag = array_type (tup_ty a)
                let tmp = temp locals $"TArray{tag}"
                line s $"SetLength({tmp}, {b.Length});"
                b |> List.iteri (fun k x -> line s $"{tmp}[{k}] := {tup x};")
                return' tmp
            | TyArrayCreate(a,b) when countedElement a ->
                let tag = box_array_type a
                let tmp = temp locals $"TBoxArray{tag}"
                line s $"{tmp} := TBoxArray{tag}.Create;"
                line s $"SetLength({tmp}.items, {tup b});"
                return' tmp
            | TyArrayCreate(a,b) ->
                let tag = array_type (tup_ty a)
                let tmp = temp locals $"TArray{tag}"
                line s $"{tmp} := nil;"
                line s $"SetLength({tmp}, {tup b});"
                return' tmp
            | TyArrayLength(a,b) -> return' $"{tyv a}(Length({tup b}{arrayItems b}))"
            | TyStringLength(a,b) -> return' $"{tyv a}(Length({tup b}))"
            | TyFailwith(a,b) -> line s $"begin WriteLn(StdErr, {tup b}); Halt(1); end;"
            | TyConv(a,b) ->
                match a, prim_of b with
                | YPrim (Float32T | Float64T), _ -> return' (tup b)
                | YPrim t, Some (Float32T | Float64T) -> return' $"{primPascal t}(Trunc({tup b}))"
                | YPrim t, _ -> return' $"{primPascal t}({tup b})"
                | _ -> raise_codegen_error $"Compiler error: Unexpected type in Conv. Got: {show_ty a}"
            | TyApply(L(i,_),b) -> return' (match args' b with "" -> $"v{i}.Invoke" | x -> $"v{i}.Invoke({x})")
            | TyOp(Global, [DLit (LitString x)]) -> global' x
            | TyOp(ArrayIndexSet, [DV(L(_,YArray element)) as a;b;c]) when (rcCall "Retain" element "").IsSome ->
                let slot = tup a + arrayItems a + "[" + tup b + "]"
                line s ((rcCall "Retain" element (tup c)).Value + " " + (rcCall "Release" element slot).Value + " " + slot + " := " + tup c + ";")
            | TyOp(ArrayIndexSet, [DV(L(_,YArray element)) as a;b;c]) -> line s $"{tup a}[{tup b}] := {tup_as element c};"
            | TyOp(ArrayIndexSet, [a;b;c]) -> line s $"{tup a}[{tup b}] := {tup c};"
            | TyOp(Assign, [a;b]) -> line s $"{tup a} := {tup b};"
            | TyOp(op,l) ->
                let bin f = match l with [a;b] -> f (tup a) (tup b) | _ -> raise_codegen_error "Compiler error: Expected two arguments."
                match op, l with
                | Dyn,[a] -> tup a
                | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                | StringIndex, [DLit (LitString _) as a; b] -> $"AnsiString({tup a})[{tup b} + 1]"
                | StringIndex, [a;b] -> $"{tup a}[{tup b} + 1]"
                | StringSlice, [a;b;c] -> string_slice (); $"StringSlice({tup a}, {tup b}, {tup c})"
                | StaticStringConcat, _ -> bin (sprintf "%s + %s")
                | ArrayIndex, [a;b] -> $"{tup a}{arrayItems a}[{tup b}]"
                | Add, _ -> bin (sprintf "%s + %s")
                | Sub, _ -> bin (sprintf "%s - %s")
                | Mult, _ -> bin (sprintf "%s * %s")
                | Div, [a;_] -> bin (if is_float a then sprintf "%s / %s" else sprintf "%s div %s")
                | Mod, _ -> bin (sprintf "%s mod %s")
                | Pow, _ -> bin (sprintf "Power(%s, %s)")
                | LT, _ -> bin (sprintf "%s < %s")
                | LTE, _ -> bin (sprintf "%s <= %s")
                | EQ, _ -> bin (sprintf "%s = %s")
                | NEQ, _ -> bin (sprintf "%s <> %s")
                | GT, _ -> bin (sprintf "%s > %s")
                | GTE, _ -> bin (sprintf "%s >= %s")
                | (BoolAnd | BitwiseAnd), _ -> bin (sprintf "%s and %s")
                | (BoolOr | BitwiseOr), _ -> bin (sprintf "%s or %s")
                | BitwiseXor, _ -> bin (sprintf "%s xor %s")
                | BitwiseComplement, _ -> unary (sprintf "not %s") l
                | ShiftLeft, [DLit (LitUInt64 _);_] -> bin (sprintf "QWord(%s) shl %s")
                | ShiftLeft, _ -> bin (sprintf "%s shl %s")
                | ShiftRight, [a;_] ->
                    match prim_of a, a with
                    | Some Int8T, _ -> bin (sprintf "SarShortint(%s, %s)")
                    | Some Int16T, _ -> bin (sprintf "SarSmallint(%s, %s)")
                    | Some Int32T, _ -> bin (sprintf "SarLongint(%s, %s)")
                    | Some Int64T, _ -> bin (sprintf "SarInt64(%s, %s)")
                    | _, DLit (LitUInt64 _) -> bin (sprintf "QWord(%s) shr %s")
                    | _ -> bin (sprintf "%s shr %s")
                | Neg, _ -> unary (sprintf "-%s") l
                | Log, _ -> unary (sprintf "Ln(%s)") l
                | Exp, _ -> unary (sprintf "Exp(%s)") l
                | Tanh, _ -> unary (sprintf "Tanh(%s)") l
                | Sqrt, _ -> unary (sprintf "Sqrt(%s)") l
                | Sin, _ -> unary (sprintf "Sin(%s)") l
                | Cos, _ -> unary (sprintf "Cos(%s)") l
                | PrimToString, [a] ->
                    match a with
                    | DLit(LitBool _) | DV(L(_,YPrim BoolT)) -> unary (sprintf "LowerCase(BoolToStr(%s, True))") l
                    | DLit(LitUInt8 _ | LitUInt16 _ | LitUInt32 _ | LitUInt64 _) | DV(L(_,YPrim (UInt8T | UInt16T | UInt32T | UInt64T))) -> unary (sprintf "UIntToStr(QWord(%s))") l
                    | DLit(LitChar _) | DV(L(_,YPrim CharT)) -> unary (sprintf "string(%s)") l
                    | _ -> unary (sprintf "IntToStr(Int64(%s))") l
                | NanIs, _ -> unary (sprintf "IsNan(%s)") l
                | StdoutFlush, [] -> "Flush(Output)"
                | MonotonicDelayMs, _ -> unary (sprintf "Sleep(%s)") l
                | Printf, [DLit (LitString fmt); b] ->
                    match printf_pieces fmt (data_term_vars b) with
                    | [] -> "Write('')"
                    | pieces ->
                        pieces |> List.map (function Choice1Of2 t -> litPascal (LitString t) | Choice2Of2 (_, a) -> show_w a)
                        |> String.concat ", " |> sprintf "Write(%s)"
                | UnionTag, [DV(L(i,YUnion u))] ->
                    let declared = u.Item.cases |> Map.toArray |> Array.map (fun ((d,_),_) -> d)
                    if declared |> Array.mapi (fun c d -> c = d) |> Array.forall id then $"v{i}.tag"
                    else
                        global' "function SpiralDeclaredTag(tag: LongInt; const declared: array of LongInt): LongInt;\nbegin\n  Result := declared[tag];\nend;"
                        let table = declared |> Array.map string |> String.concat ", "
                        $"SpiralDeclaredTag(v{i}.tag, [{table}])"
                | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported in the Pascal backend" op l.Length
                |> return'
        and tuple_type : string [] -> int = memo (fun tys tag ->
            let fields = tys |> Array.mapi (fun k t -> $"f{k}: {t}")
            let fields = String.concat "; " fields
            types.Add($"  TTuple{tag} = record {fields}; end;")
            let ps = tys |> Array.mapi (fun k t -> $"f{k}: {t}") |> String.concat "; "
            let assigns = tys |> Array.mapi (fun k _ -> $"Result.f{k} := f{k};") |> String.concat " "
            bodies.Add($"function TupleCreate{tag}({ps}): TTuple{tag};\nbegin\n  {assigns}\nend;"))
        and array_type : string -> int = memo (fun el tag -> types.Add($"  TArray{tag} = array of {el};"))
        and countedElement (el : Ty) = rcTy el || (rcValue el).IsSome
        and box_array_type : Ty -> int = memo (fun el tag ->
            let item = tup_ty el
            forwards.Add($"  TBoxArray{tag} = class;")
            types.Add($"  TBoxArray{tag} = class(TSpiralRc) items: array of {item}; procedure DropFields; override; end;")
            let release = (rcCall "Release" el "items[i]").Value
            bodies.Add($"procedure TBoxArray{tag}.DropFields;\nvar i: Int64;\nbegin\n  for i := 0 to High(items) do begin {release} end;\nend;"))
        and arrayItems (d : Data) = match d with DV(L(_,YArray el)) when countedElement el -> ".items" | _ -> ""
        and fun_type : Ty * Ty -> int = memo (fun (a, b) tag ->
            forwards.Add($"  TFun{tag} = class;")
            let ps = tyvs a |> Array.mapi (fun k (L(_,t)) -> $"a{k}: {tyv t}") |> String.concat "; "
            let ps = if ps = "" then "" else $"({ps})"
            let decl = match tup_ty b with "" -> $"procedure Invoke{ps}; virtual; abstract;" | r -> $"function Invoke{ps}: {r}; virtual; abstract;"
            types.Add($"  TFun{tag} = class(TSpiralRc)\n    {decl}\n  end;"))
        and layout_rec (x : Ty) : LayoutRecFsharp =
            match x with
            | YLayout(x,_) ->
                let x = env.ty_to_data x
                let a, b =
                    match x with
                    | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                    | _ -> data_free_vars x, Map.empty
                {data=x; free_vars=a; free_vars_by_key=b; tag=0}
            | _ -> raise_codegen_error $"Compiler error: Expected a layout type (3).\nGot: %s{show_ty x}"
        and layout (kind : string) (x : Ty) : LayoutRecFsharp =
            match layout_tags.TryGetValue x with
            | true, r -> r
            | _ ->
                let r = { layout_rec x with tag = layout_tags.Count }
                layout_tags.[x] <- r
                let fields = r.free_vars |> Array.map (fun (L(i,t)) -> $"l{i}: {tyv t};") |> String.concat " "
                let ps = r.free_vars |> Array.mapi (fun k (L(_,t)) -> $"a{k}: {tyv t}") |> String.concat "; "
                let ps = if ps = "" then "" else $"({ps})"
                let assigns = r.free_vars |> Array.mapi (fun k (L(i,_)) -> $"Result.l{i} := a{k};") |> String.concat " "
                if kind = "Heap" then
                    types.Add($"  THeap{r.tag} = record {fields} end;")
                    bodies.Add($"function HeapCreate{r.tag}{ps}: THeap{r.tag};\nbegin\n  {assigns}\nend;")
                else
                    forwards.Add($"  TMut{r.tag} = class;")
                    let owned = r.free_vars |> Array.choose (fun (L(i,t)) -> if rcClass (tyv t) then Some $"l{i}" else rcValue t |> Option.map (fun n -> $"SpiralRelease_{n}(l{i});"))
                    types.Add($"  TMut{r.tag} = class(TSpiralRc) {fields}{dropDecl owned} end;")
                    dropBody $"TMut{r.tag}" owned
                    bodies.Add($"function MutCreate{r.tag}{ps}: TMut{r.tag};\nbegin\n  Result := TMut{r.tag}.Create; {assigns}\nend;")
                r
        and heap x : LayoutRecFsharp = layout "Heap" x
        and mut x : LayoutRecFsharp = layout "Mut" x
        and union_type (heap : bool) = memo_ref (fun (cases : Map<int * string, Ty>) tag ->
            let name = if heap then $"TUH{tag}" else $"TUS{tag}"
            let prefix = if heap then $"UH{tag}" else $"US{tag}"
            let suffixes = generatedCaseSuffixes cases |> caseFoldedSuffixes
            let cases = cases |> Map.toArray |> Array.map (fun (_, t) -> env.ty_to_data t |> data_free_vars)
            if heap then forwards.Add($"  {name} = class;")
            let fields = cases |> Array.mapi (fun c vars -> vars |> Array.mapi (fun f (L(_,t)) -> $"c{c}_{f}: {tyv t};")) |> Array.concat |> String.concat " "
            let owned = cases |> Array.mapi (fun c vars -> vars |> Array.mapi (fun f (L(_,t)) -> if rcClass (tyv t) then Some $"c{c}_{f}" elif heap then rcValue t |> Option.map (fun n -> $"SpiralRelease_{n}(c{c}_{f});") else None)) |> Array.concat |> Array.choose id
            types.Add(if heap then $"  {name} = class(TSpiralRc) tag: LongInt; {fields}{dropDecl owned} end;" else $"  {name} = record tag: LongInt; {fields} end;")
            if heap then dropBody name owned
            cases |> Array.iteri (fun c vars ->
                let ps = vars |> Array.mapi (fun f (L(_,t)) -> $"a{f}: {tyv t}") |> String.concat "; "
                let ps = if ps = "" then "" else $"({ps})"
                let create = if heap then $"Result := {name}.Create; " else ""
                let assigns = vars |> Array.mapi (fun f _ -> $"Result.c{c}_{f} := a{f};") |> String.concat " "
                if heap && vars.Length = 0 then
                    let shared = $"{prefix}_{suffixes.[c]}_shared"
                    sharedSingletons.Add shared
                    bodies.Add($"var {shared}: {name} = nil;\nfunction {prefix}_{suffixes.[c]}: {name};\nbegin\n  if {shared} = nil then begin {shared} := {name}.Create; {shared}.tag := {c}; {shared}.refc := High(LongInt) div 2; end;\n  Result := {shared};\nend;")
                else
                    bodies.Add($"function {prefix}_{suffixes.[c]}{ps}: {name};\nbegin\n  {create}Result.tag := {c}; {assigns}\nend;")))
        and uheap_memo = lazy (union_type true)
        and ustack_memo = lazy (union_type false)
        and uheap x = uheap_memo.Force() x
        and ustack x = ustack_memo.Force() x
        and method_memo = lazy (memo (fun ((jp_body,key) : _ * _) tag ->
            let args = codegenMethodKeyArgs key
            match codegenMethodBody env "Pascal" jp_body key with
            | body, range, name ->
                method_names.[tag] <- generatedMethodName name tag
                emit_function' (Some tag) method_names.[tag] (rdata_free_vars args) range body true))
        and method (a, b) : {| tag : int |} = {| tag = method_memo.Force() (a, b) |}
        and closure_memo = lazy (memo (fun ((jp_body,key & (C(args,_,fun_ty))) : _ * _) tag ->
            match fun_ty with
            | YFun(domain,range,_) ->
                match codegenClosureBody env "Pascal" jp_body key with
                | domain_args, body, sourceName ->
                    closure_names.[tag] <- generatedClosureName sourceName tag
                    let free_vars = rdata_free_vars args
                    let domain_args = data_free_vars domain_args
                    let parent = fun_type (domain, range)
                    let fields = free_vars |> Array.map (fun (L(i,t)) -> $"v{i}: {tyv t};") |> String.concat " "
                    let invoke = header "Invoke" domain_args (tup_ty range)
                    let owned = free_vars |> Array.choose (fun (L(i,t)) -> rcCall "Release" t $"v{i}")
                    types.Add($"  T{closure_names.[tag]} = class(TFun{parent}) {fields} {invoke}; override;{dropDecl owned} end;")
                    dropBody $"T{closure_names.[tag]}" owned
                    let saved = bodies.Count
                    emit_function $"T{closure_names.[tag]}.Invoke" domain_args range body false
                    let invoked = bodies.Count - 1
                    bodies.[invoked] <- bodies.[invoked].Substring(0, bodies.[invoked].Length - "end;".Length) + "  SpiralRelease(Self);\nend;"
                    let assigns = free_vars |> Array.map (fun (L(i,_)) -> $"c.v{i} := v{i};") |> String.concat " "
                    let ps = match param_list free_vars with "" -> "" | ps -> $"({ps})"
                    bodies.Add($"function ClosureCreate{tag}{ps}: TFun{parent};\nvar c: T{closure_names.[tag]};\nbegin\n  c := T{closure_names.[tag]}.Create; {assigns}\n  Result := c;\nend;")
                    headers.Add($"function ClosureCreate{tag}{ps}: TFun{parent}; forward;")
            | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."))
        and closure (a, b) : {| tag : int |} = {| tag = closure_memo.Force() (a, b) |}
        and self_tail tag (body : TypedBind []) =
            body.Length > 0 &&
            match Array.last body with
            | TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _) -> (method (a,c)).tag = tag
            | TyLocalReturnOp(_, TyIf(_,tr,fl), _) -> self_tail tag tr || self_tail tag fl
            | TyLocalReturnOp(_, TyUnionUnbox(_,_,on_succs,on_fail), _) -> (on_succs |> Map.exists (fun _ (_,b) -> self_tail tag b)) || (on_fail |> Option.exists (self_tail tag))
            | TyLocalReturnOp(_, TyIntSwitch(_,on_succ,on_fail), _) -> Array.exists (self_tail tag) on_succ || self_tail tag on_fail
            | TyLocalReturnOp(_, (TyDo b | TyIndent b), _) -> self_tail tag b
            | _ -> false

        match Array.tryLast x with
        | Some (TyLocalReturnOp(_,_,d)) | Some (TyLocalReturnData(d,_)) ->
            match data_term_vars d |> Array.map (function WV(L(_,t)) -> t | WLit l -> YPrim (lit_to_primitive_type l)) with
            | [||] | [|YPrim Int32T|] -> ()
            | _ -> raise_codegen_error "The return type of main in the Pascal backend should be a 32-bit int (or unit)."
        | _ -> ()
        emit_function "SpiralMain" [||] (YPrim Int32T) x false

        let program = StringBuilder()
        let is_uses (x : string) = x.StartsWith("uses ", System.StringComparison.Ordinal)
        let units = env.globals |> Seq.filter is_uses |> Seq.map (fun x -> x.Substring(5).Trim().TrimEnd(';').Trim()) |> Seq.filter (fun x -> x <> "") |> Seq.distinct |> Seq.filter (fun x -> x <> "SysUtils" && x <> "Math") |> List.ofSeq
        program.AppendLine("program SpiralGenerated;").AppendLine("{$mode delphi}{$H+}").AppendLine("{$IFDEF CPUX86_64}{$OPTIMIZATION NOREGVAR}{$ENDIF}").AppendLine("{$MAXSTACKSIZE $10000000}").AppendLine("uses " + String.concat ", " ("SysUtils" :: "Math" :: units) + ";") |> ignore
        if forwards.Count > 0 || types.Count > 0 then
            program.AppendLine("type") |> ignore
            if forwards.Count > 0 then program.AppendLine("  TSpiralRc = class refc: LongInt; procedure DropFields; virtual; end;") |> ignore
            forwards |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
            types |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
        env.globals |> Seq.filter (is_uses >> not) |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        globals |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        if forwards.Count > 0 then
            program
                .AppendLine("procedure TSpiralRc.DropFields;\nbegin\nend;")
                .AppendLine("procedure SpiralRetain(o: TSpiralRc);\nbegin\n  if o <> nil then Inc(o.refc);\nend;")
                .AppendLine("procedure SpiralRelease(o: TSpiralRc);\nbegin\n  if o <> nil then begin Dec(o.refc); if o.refc < 0 then begin o.DropFields; o.Free; end; end;\nend;")
                .AppendLine("function SpiralKeep(o: TSpiralRc): TSpiralRc;\nbegin\n  SpiralRetain(o); Result := o;\nend;") |> ignore
        headers |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
        bodies |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
        let exitLines =
            if sharedSingletons.Count = 0 then "  Halt(SpiralMain);"
            else "  SpiralExitCode := SpiralMain;\n" + (sharedSingletons |> Seq.map (fun x -> $"  if {x} <> nil then {x}.Free;\n") |> String.concat "") + "  Halt(SpiralExitCode);"
        program.AppendLine("var SpiralOutputBuffer: array[0..65535] of Char;" + (if sharedSingletons.Count = 0 then "" else "\nvar SpiralExitCode: LongInt;")).AppendLine("begin").AppendLine("  SetTextBuf(Output, SpiralOutputBuffer, SizeOf(SpiralOutputBuffer));").AppendLine("  SetExceptionMask([exInvalidOp, exDenormalized, exZeroDivide, exOverflow, exUnderflow, exPrecision]);").AppendLine(exitLines).AppendLine("end.").ToString()

    /// ## CodegenZig

    /// ### backend_nameZig
    let backend_nameZig = "Zig"

    /// ### litZig
    let litZig = function
        | LitInt8 x -> $"@as(i8, {x})"
        | LitInt16 x -> $"@as(i16, {x})"
        | LitInt32 x -> $"@as(i32, {x})"
        | LitInt64 x -> $"@as(i64, {x})"
        | LitUInt8 x -> $"@as(u8, {x})"
        | LitUInt16 x -> $"@as(u16, {x})"
        | LitUInt32 x -> $"@as(u32, {x})"
        | LitUInt64 x -> $"@as(u64, {x})"
        | LitFloat32 x ->
            if x = infinityf then "std.math.inf(f32)"
            elif x = -infinityf then "(-std.math.inf(f32))"
            elif Single.IsNaN x then "std.math.nan(f32)"
            else let r = x.ToString "R" |> add_dec_point in $"@as(f32, {r})"
        | LitFloat64 x ->
            if x = infinity then "std.math.inf(f64)"
            elif x = -infinity then "(-std.math.inf(f64))"
            elif Double.IsNaN x then "std.math.nan(f64)"
            else let r = x.ToString "R" |> add_dec_point in $"@as(f64, {r})"
        | LitString x ->
            let strb = StringBuilder("\"")
            for b in Text.Encoding.UTF8.GetBytes x do
                match char b with
                | '"' -> strb.Append "\\\"" |> ignore
                | '\\' -> strb.Append "\\\\" |> ignore
                | '\n' -> strb.Append "\\n" |> ignore
                | '\r' -> strb.Append "\\r" |> ignore
                | '\t' -> strb.Append "\\t" |> ignore
                | c when b >= 32uy && b < 127uy -> strb.Append c |> ignore
                | _ -> strb.Append(sprintf "\\x%02x" b) |> ignore
            strb.Append('"').ToString()
        | LitChar x ->
            if int x > 127 then raise_codegen_error $"The Zig backend represents chars as bytes; '{x}' is not ASCII."
            else $"@as(u8, {int x})"
        | LitBool x -> if x then "true" else "false"

    /// ### primZig
    let primZig = function
        | Int8T -> "i8"
        | Int16T -> "i16"
        | Int32T -> "i32"
        | Int64T -> "i64"
        | UInt8T -> "u8"
        | UInt16T -> "u16"
        | UInt32T -> "u32"
        | UInt64T -> "u64"
        | Float32T -> "f32"
        | Float64T -> "f64"
        | BoolT -> "bool"
        | StringT -> "[]const u8"
        | CharT -> "u8"

    /// ### type_litZig
    let type_litZig = function
        | YLit x -> litZig x
        | YSymbol x -> x
        | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."

    /// ### zigPrelude
    let zigPrelude = """const std = @import("std");
const builtin = @import("builtin");
var spiral_arena = std.heap.ArenaAllocator.init(std.heap.page_allocator);
extern "kernel32" fn GetStdHandle(id: u32) callconv(.winapi) ?*anyopaque;
extern "kernel32" fn WriteFile(handle: ?*anyopaque, buffer: [*]const u8, length: u32, written: ?*u32, overlapped: ?*anyopaque) callconv(.winapi) i32;
fn spiralWrite(stream: u2, bytes: []const u8) void {
    if (builtin.os.tag == .windows) {
        const handle = GetStdHandle(if (stream == 1) 0xFFFFFFF5 else 0xFFFFFFF4);
        var rest = bytes;
        while (rest.len > 0) {
            var written: u32 = 0;
            const chunk: u32 = @intCast(@min(rest.len, 1 << 30));
            if (WriteFile(handle, rest.ptr, chunk, &written, null) == 0) return;
            rest = rest[written..];
        }
    } else if (builtin.os.tag == .linux) {
        var rest = bytes;
        while (rest.len > 0) {
            const n = std.os.linux.write(stream, rest.ptr, rest.len);
            if (@as(isize, @bitCast(n)) <= 0) return;
            rest = rest[n..];
        }
    } else {
        _ = std.c.write(stream, bytes.ptr, bytes.len);
    }
}
pub const panic = std.debug.FullPanic(spiralPanic);
fn spiralPanic(message: []const u8, _: ?usize) noreturn {
    spiralFlush();
    spiralWrite(2, message);
    spiralWrite(2, "\n");
    std.process.exit(3);
}
var spiral_gpa: std.mem.Allocator = undefined;
var spiral_environ: std.process.Environ = .empty;
var spiral_true: bool = true;
var spiral_out_buffer: [1 << 16]u8 = undefined;
var spiral_out_len: usize = 0;
fn spiralFlush() void {
    if (spiral_out_len == 0) return;
    spiralWrite(1, spiral_out_buffer[0..spiral_out_len]);
    spiral_out_len = 0;
}
fn spiralPrint(s: []const u8) void {
    if (s.len > spiral_out_buffer.len - spiral_out_len) spiralFlush();
    if (s.len > spiral_out_buffer.len) {
        spiralWrite(1, s);
        return;
    }
    @memcpy(spiral_out_buffer[spiral_out_len..][0..s.len], s);
    spiral_out_len += s.len;
}
fn spiralFloatText(x: anytype) []u8 {
    var buffer: [std.fmt.float.bufferSize(.decimal, @TypeOf(x))]u8 = undefined;
    const text = std.fmt.float.render(&buffer, x, .{ .mode = .decimal }) catch unreachable;
    return spiral_gpa.dupe(u8, text) catch @panic("out of memory");
}
fn spiralPrintAny(x: anytype) void {
    const T = @TypeOf(x);
    if (T == []const u8) return spiralPrint(x);
    if (@typeInfo(T) == .float) return spiralPrint(spiralFloatText(x));
    const s = switch (@typeInfo(T)) {
        .bool => std.fmt.allocPrint(spiral_gpa, "{}", .{x}),
        else => std.fmt.allocPrint(spiral_gpa, "{d}", .{x}),
    } catch @panic("out of memory");
    spiralPrint(s);
}
fn spiralFail(s: []const u8) noreturn {
    spiralFlush();
    spiralWrite(2, s);
    spiralWrite(2, "\n");
    std.process.exit(1);
}
fn spiralConv(comptime T: type, x: anytype) T {
    const S = @TypeOf(x);
    if (@typeInfo(T) == .float) {
        if (@typeInfo(S) == .float) return @floatCast(x) else return @floatFromInt(x);
    }
    if (@typeInfo(S) == .float) return @intFromFloat(x);
    const U = @Int(.unsigned, @bitSizeOf(T));
    const wide: i128 = x;
    return @bitCast(@as(U, @truncate(@as(u128, @bitCast(wide)))));
}
fn spiralConcat(a: []const u8, b: []const u8) []const u8 {
    return std.mem.concat(spiral_gpa, u8, &.{ a, b }) catch @panic("out of memory");
}
fn spiralStringSlice(s: []const u8, from: i64, upto: i64) []const u8 {
    const len: i64 = @intCast(s.len);
    if (from < 0 or from > len or upto < from - 1 or upto >= len) std.process.exit(3);
    if (upto < from) return "";
    const a: usize = @intCast(from);
    const b: usize = @intCast(upto + 1);
    if ((s[a] & 0xC0) == 0x80 or (b < s.len and (s[b] & 0xC0) == 0x80)) std.process.exit(3);
    return s[a..b];
}
fn spiralIndex(len: usize, i: anytype) usize {
    if (i < 0 or i >= len) std.process.exit(3);
    return @intCast(i);
}
fn spiralNewArray(comptime T: type, n: anytype) []T {
    const len: usize = @intCast(n);
    const a = spiral_gpa.alloc(T, len) catch @panic("out of memory");
    switch (@typeInfo(T)) {
        .int, .float, .bool => @memset(a, std.mem.zeroes(T)),
        else => if (T == []const u8) @memset(a, ""),
    }
    return a;
}
fn spiralCreate(comptime T: type, v: T) *T {
    const p = spiral_gpa.create(T) catch @panic("out of memory");
    p.* = v;
    return p;
}
"""

    /// ### zigUsedPrelude
    let zigUsedPrelude (program : string) =
        let chunks = ResizeArray<string>()
        let current = StringBuilder()
        for line in zigPrelude.TrimEnd('\n').Split('\n') do
            if current.Length > 0 && line.Length > 0 && not (System.Char.IsWhiteSpace line.[0]) && line <> "}" then
                chunks.Add(current.ToString())
                current.Clear() |> ignore
            current.Append(line).Append('\n') |> ignore
        if current.Length > 0 then chunks.Add(current.ToString())
        let helperName (chunk : string) =
            let m = System.Text.RegularExpressions.Regex.Match(chunk, @"^fn (\w+)\(")
            if m.Success then Some m.Groups.[1].Value else None
        let rec settle (kept : string []) =
            let reached (index : int) (name : string) =
                let pattern = @"\b" + name + @"\b"
                System.Text.RegularExpressions.Regex.IsMatch(program, pattern)
                || (kept |> Array.indexed |> Array.exists (fun (other, chunk) -> other <> index && System.Text.RegularExpressions.Regex.IsMatch(chunk, pattern)))
            let next = kept |> Array.indexed |> Array.filter (fun (index, chunk) -> match helperName chunk with Some name -> reached index name | None -> true) |> Array.map snd
            if next.Length = kept.Length then kept else settle next
        settle (chunks.ToArray()) |> String.concat ""

    /// ### BindsReturnZig
    type BindsReturnZig = ZLocal of TyV [] | ZTail of Ty

    /// ### ZigLayoutRec
    type ZigLayoutRec = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>}

    /// ### codegenZig
    /// ### zigConstLocals
    let zigConstLocals (generated : string) =
        if not (generated.Contains("= undefined; _ = &v", System.StringComparison.Ordinal)) then generated
        else
            let lines = generated.Replace("\r\n", "\n").Split('\n')
            let hoisted = System.Text.RegularExpressions.Regex(@"^(?<indent>[ \t]+)var (?<name>v[0-9]+): (?<type>[^=]+?) = undefined; _ = &\k<name>;$")
            let functionHead = System.Text.RegularExpressions.Regex(@"^(pub )?fn \w+\(.*\{$")
            let word = System.Text.RegularExpressions.Regex(@"(?<![\w.])v[0-9]+\b")
            let compound = System.Text.RegularExpressions.Regex(@"^(?:\s*(?:\.\w+|\[[^\]\n]*\]))+\s*(?:=(?!=)|\+=|-=|\*=|/=|%=|<<=|>>=|&=|\|=|\^=|\+%=|-%=|\*%=)|^\s*(?:\+=|-=|\*=|/=|%=|<<=|>>=|&=|\|=|\^=|\+%=|-%=|\*%=)")
            let dropped = HashSet<int>()
            let replaced = Dictionary<int, string>()
            let mutable start = -1
            for index = 0 to lines.Length - 1 do
                if functionHead.IsMatch lines.[index] then start <- index
                elif lines.[index] = "}" && start >= 0 then
                    let occurrences = Dictionary<string, ResizeArray<int>>()
                    for at = start + 1 to index - 1 do
                        for found in word.Matches lines.[at] do
                            match occurrences.TryGetValue found.Value with
                            | true, rows -> if rows.Count = 0 || rows.[rows.Count - 1] <> at then rows.Add at
                            | _ -> occurrences.[found.Value] <- ResizeArray [ at ]
                    for at = start + 1 to index - 1 do
                        let declared = hoisted.Match lines.[at]
                        if declared.Success then
                            let name = declared.Groups.["name"].Value
                            let indent = declared.Groups.["indent"].Value
                            let prefix = indent + name + " = "
                            let others = occurrences.[name] |> Seq.filter (fun row -> row <> at) |> List.ofSeq
                            let assignments = others |> List.filter (fun row -> lines.[row].TrimStart().StartsWith(name + " = ", System.StringComparison.Ordinal))
                            match assignments with
                            | [ assigned ] when assigned > at && lines.[assigned].StartsWith(prefix, System.StringComparison.Ordinal) && lines.[assigned].EndsWith(";", System.StringComparison.Ordinal) ->
                                let rest = lines.[assigned].Substring prefix.Length
                                let readsEarly = others |> List.exists (fun row -> row < assigned && not (dropped.Contains row))
                                let selfReference = System.Text.RegularExpressions.Regex.IsMatch(rest, @"(?<![\w.])" + name + @"\b")
                                let mutated =
                                    others
                                    |> List.filter (fun row -> row <> assigned)
                                    |> List.exists (fun row ->
                                        let text = lines.[row]
                                        text.Contains("&" + name) ||
                                        (System.Text.RegularExpressions.Regex.Matches(text, @"(?<![\w.])" + name + @"\b")
                                         |> Seq.exists (fun found -> compound.IsMatch(text.Substring(found.Index + found.Length)))))
                                if not readsEarly && not selfReference && not mutated then
                                    let used = others |> List.exists (fun row -> row <> assigned)
                                    dropped.Add at |> ignore
                                    replaced.[assigned] <- indent + "const " + name + ": " + declared.Groups.["type"].Value + " = " + rest + (if used then "" else " _ = &" + name + ";")
                            | _ -> ()
                    start <- -1
            let output = System.Text.StringBuilder(generated.Length)
            let mutable first = true
            for index = 0 to lines.Length - 1 do
                if not (dropped.Contains index) then
                    if not first then output.Append('\n') |> ignore
                    first <- false
                    output.Append(match replaced.TryGetValue index with | true, text -> text | _ -> lines.[index]) |> ignore
            output.ToString()

    let codegenZig (linked_units : Map<int, LinkedUnit>) (env : PartEvalResult) (x : TypedBind []) =
        let zig_fast = System.Environment.GetEnvironmentVariable "SPIRAL_ZIG_FAST" = "1"
        let method_names = Dictionary<int, string>()
        let closure_names = Dictionary<int, string>()
        let types = ResizeArray()
        let bodies = ResizeArray()
        let globals = ResizeArray()
        let closure_of_var = Dictionary<int, int>()
        let export_names = HashSet<string>()

        let memo (f : 'k -> int -> unit) =
            let dict = Dictionary<'k, int>(HashIdentity.Structural)
            fun (k : 'k) ->
                match dict.TryGetValue k with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[k] <- tag
                    f k tag
                    tag
        let memo_ref (f : 'k -> int -> unit) =
            let dict = Dictionary<'k, int>(HashIdentity.Reference)
            fun (k : 'k) ->
                match dict.TryGetValue k with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[k] <- tag
                    f k tag
                    tag
        let global' =
            let has_added = HashSet env.globals
            fun x -> if has_added.Add(x) then globals.Add x

        let new_locals (parameters : TyV []) = HashSet(parameters |> Array.map (fun (L(i,_)) -> i)), ResizeArray<string>()
        let text (s : CodegenEnv) = s.text.ToString()

        let prim_of = function
            | DV(L(_,YPrim t)) -> Some t
            | DLit l -> Some (lit_to_primitive_type l)
            | _ -> None
        let is_int d = match prim_of d with Some (Int8T | Int16T | Int32T | Int64T | UInt8T | UInt16T | UInt32T | UInt64T) -> true | _ -> false
        let is_float d = match prim_of d with Some (Float32T | Float64T) -> true | _ -> false
        let is_string d = match prim_of d with Some StringT -> true | _ -> false
        let show_w = function WV (L(i,_)) -> $"v{i}" | WLit a -> litZig a
        let args (x : TyV []) = x |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
        let args' x = data_term_vars x |> Array.map show_w |> String.concat ", "

        let layout_tags = Dictionary<Ty, ZigLayoutRec>(HashIdentity.Structural)
        let self_loop : (int * TyV []) option ref = ref None
        let rec tyv x =
            match x with
            | YUnion a ->
                let a = a.Item
                match a.layout with
                | UHeap -> sprintf "*UH%i" (uheap a.cases)
                | UStack -> sprintf "US%i" (ustack a.cases)
            | YLayout(_,lay) as a ->
                match lay with
                | Heap -> sprintf "*Heap%i" (heap a).tag
                | HeapMutable -> sprintf "*Mut%i" (mut a).tag
                | StackMutable -> raise_codegen_error "The Zig backend doesn't support stack mutable layout types yet."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
            | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameZig then Some v else None) with
                | Some x -> tup_ty x
                | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{backend_nameZig}' field."
            | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_litZig a) |> String.concat ""
            | YPrim a -> primZig a
            | YArray a -> sprintf "[]%s" (tup_ty' a)
            | YFun(a,b,_) -> sprintf "Fun%i" (fun_type (a, b))
            | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
            | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
            | a -> raise_codegen_error $"Type not supported in the codegen.\nGot: %A{a}"
        and tyvs (x : Ty) = env.ty_to_data x |> data_free_vars
        and tup_ty x =
            match tyvs x |> Array.map (fun (L(_,t)) -> tyv t) with
            | [||] -> "void"
            | [|x|] -> x
            | x -> sprintf "Tuple%i" (tuple_type x)
        and tup_ty' x = match tup_ty x with "void" -> "u8" | t -> t
        and tup d = data_term_vars d |> Array.map show_w |> String.concat ", "
        and tup_as (range : Ty) d =
            match data_term_vars d with
            | [||] -> ""
            | [|x|] -> show_w x
            | x ->
                let tag = tyvs range |> Array.map (fun (L(_,t)) -> tyv t) |> tuple_type
                let fields = x |> Array.mapi (fun k w -> $".f{k} = {show_w w}") |> String.concat ", "
                $"Tuple{tag}{{ {fields} }}"
        and param_list (x : TyV []) = x |> Array.map (fun (L(i,t)) -> $"p{i}: {tyv t}") |> String.concat ", "
        and emit_function (name : string) (self_tag : int option) (parameters : TyV []) (extra : string) (range : Ty) (body : TypedBind []) (tail : string) =
            let range' = tup_ty range
            let locals = new_locals parameters
            let s = {text=StringBuilder(); indent=4}
            let saved = self_loop.Value
            match self_tag with
            | Some tag when self_tail tag body ->
                self_loop.Value <- Some (tag, parameters)
                line s "while (true) {"
                binds locals (indent s) (ZTail range) body
                line s "}"
            | _ ->
                self_loop.Value <- None
                binds locals s (ZTail range) body
            self_loop.Value <- saved
            if tail <> "" then line s tail
            let ps = match extra, param_list parameters with "", p -> p | e, "" -> e | e, p -> $"{e}, {p}"
            let copies = parameters |> Array.map (fun (L(i,t)) -> $"    var v{i}: {tyv t} = p{i}; _ = &v{i};\n") |> String.concat ""
            let decls = snd locals |> Seq.map (sprintf "    %s\n") |> String.concat ""
            let float_mode = if zig_fast then "    @setFloatMode(.optimized);\n" else ""
            bodies.Add($"fn {name}({ps}) {range'} {{\n{float_mode}{copies}{decls}{text s}}}\n")
        and declare (names : HashSet<int>, decls : ResizeArray<string>) (L(i,t)) =
            if names.Add i then decls.Add($"var v{i}: {tyv t} = undefined; _ = &v{i};")
        and temp (_ : HashSet<int>, decls : ResizeArray<string>) (ty : string) =
            let name = $"tmp{decls.Count}"
            decls.Add($"var {name}: {ty} = undefined; _ = &{name};")
            name
        and binds locals (s : CodegenEnv) (ret : BindsReturnZig) (stmts : TypedBind []) =
            Array.iter (function
                | TyLet(d,trace,a) ->
                    try let d = data_free_vars d
                        d |> Array.iter (declare locals)
                        op locals s (ZLocal d) a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) -> try op locals s ret a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) ->
                    try match ret with
                        | ZLocal l -> Array.iter2 (fun (L(i,_)) b -> line s $"v{i} = {show_w b};") l (data_term_vars d)
                        | ZTail range ->
                            match tup_as range d with
                            | "" -> if self_loop.Value.IsSome then line s "return;"
                            | x -> line s $"return {x};"
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) stmts
        and op locals (s : CodegenEnv) (ret : BindsReturnZig) a =
            let binds = binds locals
            let return' (x : string) =
                match ret with
                | ZLocal [||] -> if x.Trim() <> "" then line s $"_ = {x};"
                | ZLocal [|L(i,_)|] -> line s $"v{i} = {x};"
                | ZLocal l ->
                    let tmp = temp locals (tuple_type (l |> Array.map (fun (L(_,t)) -> tyv t)) |> sprintf "Tuple%i")
                    line s $"{tmp} = {x};"
                    l |> Array.iteri (fun k (L(i,_)) -> line s $"v{i} = {tmp}.f{k};")
                | ZTail range ->
                    if tup_ty range = "void" then
                        if x.Trim() <> "" then line s $"_ = {x};"
                        if self_loop.Value.IsSome then line s "return;"
                    else line s $"return {x};"
            let layout_index (i : int) (fields : TyV []) =
                match ret with
                | ZLocal l -> Array.iter2 (fun (L(t,_)) (L(f,_)) -> line s $"v{t} = v{i}.l{f};") l fields
                | ZTail _ -> raise_codegen_error "Compiler error: Layout index should never come in end position."
            let jp (a, b) =
                match a with
                | JPMethod(a,c) -> $"{method_names.[(method (a,c)).tag]}({args b})"
                | JPClosure(a,c) -> $"closureCreate{(closure (a,c)).tag}({args b})"
            let unary f = function [x] -> f (tup x) | _ -> raise_codegen_error "Compiler error: Expected one argument."
            match a with
            | TyMacro a ->
                let text = a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup x) | CMType x -> tup_ty x | CMTypeLit x -> type_litZig x) |> String.concat ""
                let statement () = if text.Trim() <> "" then (let t = text.Trim() in if t.StartsWith "{" && t.EndsWith "}" then line s t else line s $"{text};")
                match ret with
                | ZLocal [||] -> statement ()
                | ZTail range when tup_ty range = "void" ->
                    statement ()
                    if self_loop.Value.IsSome then line s "return;"
                | _ -> return' text
            | TySizeOf t -> return' $"@as(i64, @sizeOf({tup_ty t}))"
            | TyIf(cond,tr,fl) ->
                line s $"if ({tup cond}) {{"
                binds (indent s) ret tr
                line s "} else {"
                binds (indent s) ret fl
                line s "}"
            | TyJoinPoint(JPMethod(a,c),b) when (match ret, self_loop.Value with ZTail _, Some (tag, _) -> (method (a,c)).tag = tag | _ -> false) ->
                let parameters = snd self_loop.Value.Value
                let types = parameters |> Array.map (fun (L(i,t)) -> i, t) |> dict
                let temps = System.Collections.Generic.Dictionary<int, string> ()
                for step in parallelMoves (Array.map2 (fun (L(target,_)) (L(source,_)) -> target, source) parameters b) do
                    match step with
                    | MoveVar (target, source) -> line s $"v{target} = v{source};"
                    | SaveTemp (slot, source) ->
                        temps.[slot] <- temp locals (tyv types.[source])
                        line s $"{temps.[slot]} = v{source};"
                    | MoveTemp (target, slot) -> line s $"v{target} = {temps.[slot]};"
                line s "continue;"
            | TyJoinPoint(a,args) ->
                match a, ret with
                | JPClosure(a,c), ZLocal [|L(i,_)|] when args.Length = 0 -> closure_of_var.[i] <- (closure (a,c)).tag
                | _ -> ()
                return' (jp (a, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The Zig backend does not support nesting other backends."
            | TyWhile(a,b) ->
                line s $"while ({jp a}) {{"
                binds (indent s) (ZLocal [||]) b
                line s "}"
            | TyDo a | TyIndent a -> binds s ret a
            | TyIntSwitch(L(i,_),on_succ,on_fail) ->
                line s $"switch (v{i}) {{"
                on_succ |> Array.iteri (fun k b -> line (indent s) $"{k} => {{"; binds (indent (indent s)) ret b; line (indent s) "},")
                line (indent s) "else => {"; binds (indent (indent s)) ret on_fail; line (indent s) "},"
                line s "}"
            | TyUnionUnbox(is,x,on_succs,on_fail) ->
                let x' = x.Item
                let _ = match x'.layout with UHeap -> uheap x'.cases | UStack -> ustack x'.cases
                let case_index k =
                    x'.cases |> Seq.map (fun (KeyValue ((_,k'),_)) -> k') |> Seq.tryFindIndex (fun k' -> UnionTagIdOps.text k = k')
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text k}.")
                let head =
                    match is with
                    | [L(i,_)] -> $"v{i}.tag"
                    | L(i,_) :: _ ->
                        let tmp = temp locals "i32"
                        let same = is |> List.pairwise |> List.map (fun (L(a,_), L(b,_)) -> $"(v{a}.tag == v{b}.tag)") |> String.concat " and "
                        line s $"{tmp} = if ({same}) v{i}.tag else -1;"
                        tmp
                    | [] -> raise_codegen_error "Compiler error: Union unbox without a scrutinee."
                line s $"switch ({head}) {{"
                on_succs |> Map.iter (fun k (a,b) ->
                    let c = case_index k
                    line (indent s) $"{c} => {{"
                    List.iter2 (fun (L(v,_)) a ->
                        data_free_vars a |> Array.iteri (fun f (L(i,_) as field) ->
                            declare locals field
                            line (indent (indent s)) $"v{i} = v{v}.c{c}_{f};")) is a
                    binds (indent (indent s)) ret b
                    line (indent s) "},")
                match on_fail with
                | Some b -> line (indent s) "else => {"; binds (indent (indent s)) ret b; line (indent s) "},"
                | None -> line (indent s) "else => unreachable,"
                line s "}"
            | TyUnionBox(a,b,c) ->
                let c = c.Item
                let tag, prefix = match c.layout with UHeap -> uheap c.cases, "UH" | UStack -> ustack c.cases, "US"
                let i =
                    c.cases |> Seq.map (fun (KeyValue ((_,k),_)) -> k) |> Seq.tryFindIndex (fun k -> UnionTagIdOps.text a = k)
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text a}.")
                return' $"{prefix}{tag}_{(generatedCaseSuffixes c.cases).[i]}({args' b})"
            | TyToLayout(a,b) ->
                match b with
                | YLayout(_,Heap) -> $"heapCreate{(heap b).tag}({args' a})"
                | YLayout(_,HeapMutable) -> $"mutCreate{(mut b).tag}({args' a})"
                | YLayout(_,StackMutable) -> raise_codegen_error "The Zig backend doesn't support stack mutable layout types yet."
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (4).\nGot: %s{show_ty b}"
                |> return'
            | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                match lay with
                | Heap -> (heap a).free_vars
                | HeapMutable -> (mut a).free_vars
                | StackMutable -> raise_codegen_error "The Zig backend doesn't support indexing into stack mutable layout types yet."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                |> layout_index i
            | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The Zig backend doesn't support indexing into stack mutable layout types yet."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                |> fun (x : ZigLayoutRec) -> x.free_vars_by_key |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None) |> Option.iter (layout_index i)
            | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
            | TyLayoutMutableSet(L(i,t),b,c) ->
                let a = List.fold (fun s k ->
                    match s with
                    | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                    | _ -> raise_codegen_error "Compiler error: Expected a record.") (mut t).data b
                Array.iter2 (fun (L(i',_)) b -> line s $"v{i}.l{i'} = {show_w b};") (data_free_vars a) (data_term_vars c)
            | TyArrayLiteral(a,b) ->
                let el = tup_ty' a
                let tmp = temp locals $"[]{el}"
                line s $"{tmp} = spiralNewArray({el}, {b.Length});"
                b |> List.iteri (fun k x -> line s $"{tmp}[{k}] = {tup_as a x};")
                return' tmp
            | TyArrayCreate(a,b) -> return' $"spiralNewArray({tup_ty' a}, {tup b})"
            | TyArrayLength(a,b) | TyStringLength(a,b) -> return' $"@as({tyv a}, @intCast({tup b}.len))"
            | TyFailwith(a,b) ->
                match ret with
                | ZTail _ -> line s $"spiralFail({tup b});"
                | ZLocal _ -> line s $"if (spiral_true) spiralFail({tup b});"
            | TyConv(a,b) ->
                match a with
                | YPrim (Int8T | Int16T | Int32T | Int64T | UInt8T | UInt16T | UInt32T | UInt64T | Float32T | Float64T) -> return' $"spiralConv({tyv a}, {tup b})"
                | _ -> raise_codegen_error $"Compiler error: Unexpected type in Conv. Got: {show_ty a}"
            | TyApply(L(i,_),b) -> return' (match args' b with "" -> $"v{i}.call(v{i}.ctx)" | x -> $"v{i}.call(v{i}.ctx, {x})")
            | TyOp(Global, [DLit (LitString x)]) -> global' x
            | TyOp(Export, [DLit (LitString name); DV(L(i,YFun(domain,range,_)))]) ->
                if not (export_names.Add name) then raise_codegen_error $"Duplicate export: {name}."
                let tag =
                    match closure_of_var.TryGetValue i with
                    | true, tag -> tag
                    | _ -> raise_codegen_error $"Compiler error: the exported function {name} is not a closure without captures."
                let parameters = env.ty_to_data domain |> data_free_vars
                let decl = parameters |> Array.map (fun (L(k,t)) -> $"v{k}: {tyv t}") |> String.concat ", "
                let call = parameters |> Array.map (fun (L(k,_)) -> $", v{k}") |> String.concat ""
                types.Add($"var spiral_export_env{tag}: ClosureEnv{tag} = .{{}};")
                bodies.Add($"pub fn {name}({decl}) {tup_ty range} {{\n    return {closure_names.[tag]}(@ptrCast(&spiral_export_env{tag}){call});\n}}\n")
                match ret with
                | ZLocal [||] -> ()
                | _ -> return' ""
            | TyOp(ArrayIndexSet, [a;b;c]) ->
                let value = match a with DV(L(_,YArray el)) -> tup_as el c | _ -> tup c
                line s $"{tup a}[spiralIndex({tup a}.len, {tup b})] = {value};"
            | TyOp(Assign, [a;b]) -> line s $"{tup a} = {tup b};"
            | TyOp(op,l) ->
                let bin f = match l with [a;b] -> f (tup a) (tup b) | _ -> raise_codegen_error "Compiler error: Expected two arguments."
                let cmp o = match l with [a;_] when is_string a -> bin (fun a b -> match o with "<" -> $"std.mem.lessThan(u8, {a}, {b})" | "<=" -> $"!std.mem.lessThan(u8, {b}, {a})" | ">" -> $"std.mem.lessThan(u8, {b}, {a})" | _ -> $"!std.mem.lessThan(u8, {a}, {b})") | _ -> bin (fun a b -> $"{a} {o} {b}")
                match op, l with
                | Dyn,[a] -> tup a
                | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                | StringIndex, [a;b] -> $"{tup a}[spiralIndex({tup a}.len, {tup b})]"
                | StringSlice, [a;b;c] -> $"spiralStringSlice({tup a}, @as(i64, {tup b}), @as(i64, {tup c}))"
                | StaticStringConcat, _ -> bin (sprintf "spiralConcat(%s, %s)")
                | ArrayIndex, [a;b] -> $"{tup a}[spiralIndex({tup a}.len, {tup b})]"
                | Add, [a;_] -> bin (if is_int a then sprintf "%s +%% %s" else sprintf "%s + %s")
                | Sub, [a;_] -> bin (if is_int a then sprintf "%s -%% %s" else sprintf "%s - %s")
                | Mult, [a;_] -> bin (if is_int a then sprintf "%s *%% %s" else sprintf "%s * %s")
                | Div, [a;_] -> bin (if is_float a then sprintf "%s / %s" else sprintf "@divTrunc(%s, %s)")
                | Mod, _ -> bin (sprintf "@rem(%s, %s)")
                | Pow, [a;_] -> bin (sprintf "std.math.pow(@TypeOf(%s), %s, %s)" (tup a))
                | LT, _ -> cmp "<"
                | LTE, _ -> cmp "<="
                | EQ, [a;_] when is_string a -> bin (sprintf "std.mem.eql(u8, %s, %s)")
                | NEQ, [a;_] when is_string a -> bin (sprintf "!std.mem.eql(u8, %s, %s)")
                | EQ, _ -> bin (sprintf "%s == %s")
                | NEQ, _ -> bin (sprintf "%s != %s")
                | GT, _ -> cmp ">"
                | GTE, _ -> cmp ">="
                | BoolAnd, _ -> bin (sprintf "(%s and %s)")
                | BoolOr, _ -> bin (sprintf "(%s or %s)")
                | BitwiseAnd, _ -> bin (sprintf "%s & %s")
                | BitwiseOr, _ -> bin (sprintf "%s | %s")
                | BitwiseXor, _ -> bin (sprintf "%s ^ %s")
                | BitwiseComplement, _ -> unary (sprintf "~%s") l
                | ShiftLeft, [a;_] -> bin (sprintf "std.math.shl(@TypeOf(%s), %s, %s)" (tup a))
                | ShiftRight, [a;_] -> bin (sprintf "std.math.shr(@TypeOf(%s), %s, %s)" (tup a))
                | Neg, [a] -> if is_int a then unary (sprintf "-%%%s") l else unary (sprintf "-%s") l
                | Log, _ -> unary (sprintf "@log(%s)") l
                | Exp, _ -> unary (sprintf "@exp(%s)") l
                | Tanh, _ -> unary (sprintf "std.math.tanh(%s)") l
                | Sqrt, _ -> unary (sprintf "@sqrt(%s)") l
                | Sin, _ -> unary (sprintf "@sin(%s)") l
                | Cos, _ -> unary (sprintf "@cos(%s)") l
                | PrimToString, [a] ->
                    match a with
                    | DLit(LitBool _) | DV(L(_,YPrim BoolT)) -> unary (sprintf "(std.fmt.allocPrint(spiral_gpa, \"{}\", .{%s}) catch @panic(\"out of memory\"))") l
                    | DLit(LitChar _) | DV(L(_,YPrim CharT)) -> unary (sprintf "(std.fmt.allocPrint(spiral_gpa, \"{c}\", .{%s}) catch @panic(\"out of memory\"))") l
                    | _ -> unary (sprintf "(std.fmt.allocPrint(spiral_gpa, \"{d}\", .{%s}) catch @panic(\"out of memory\"))") l
                | NanIs, _ -> unary (sprintf "std.math.isNan(%s)") l
                | StdoutFlush, [] -> "spiralFlush()"
                | Printf, [DLit (LitString fmt); b] ->
                    match printf_pieces fmt (data_term_vars b) with
                    | [] -> "{}"
                    | [Choice2Of2 (_, (WV _ as a))] -> $"spiralPrintAny({show_w a})"
                    | pieces ->
                        pieces |> List.map (function
                            | Choice1Of2 t -> $"spiralPrint({litZig (LitString t)})"
                            | Choice2Of2 ('s', a) -> $"spiralPrint({show_w a})"
                            | Choice2Of2 (_, a) -> $"spiralPrintAny({show_w a})")
                        |> String.concat "; "
                | UnionTag, [DV(L(i,YUnion u))] ->
                    let declared = u.Item.cases |> Map.toArray |> Array.map (fun ((d,_),_) -> d)
                    let tag =
                        if declared |> Array.mapi (fun c d -> c = d) |> Array.forall id then $"v{i}.tag"
                        else
                            let arms = declared |> Array.mapi (fun c d -> $"{c} => {d}") |> String.concat ", "
                            $"@as(i32, switch (v{i}.tag) {{ {arms}, else => unreachable }})"
                    match ret with
                    | ZLocal [|L(_,t)|] -> $"spiralConv({tyv t}, {tag})"
                    | _ -> tag
                | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported in the Zig backend" op l.Length
                |> return'
        and tuple_type : string [] -> int = memo (fun tys tag ->
            let fields = tys |> Array.mapi (fun k t -> $"f{k}: {t}") |> String.concat ", "
            types.Add($"const Tuple{tag} = struct {{ {fields} }};"))
        and fun_type : Ty * Ty -> int = memo (fun (a, b) tag ->
            let ps = tyvs a |> Array.map (fun (L(_,t)) -> tyv t)
            let ps = Array.append [|"*anyopaque"|] ps |> String.concat ", "
            types.Add($"const Fun{tag} = struct {{ ctx: *anyopaque, call: *const fn ({ps}) {tup_ty b} }};"))
        and layout_rec (x : Ty) : ZigLayoutRec =
            match x with
            | YLayout(x,_) ->
                let x = env.ty_to_data x
                let a, b =
                    match x with
                    | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                    | _ -> data_free_vars x, Map.empty
                {data=x; free_vars=a; free_vars_by_key=b; tag=0}
            | _ -> raise_codegen_error $"Compiler error: Expected a layout type (3).\nGot: %s{show_ty x}"
        and layout (kind : string) (x : Ty) : ZigLayoutRec =
            match layout_tags.TryGetValue x with
            | true, r -> r
            | _ ->
                let r = { layout_rec x with tag = layout_tags.Count }
                layout_tags.[x] <- r
                let fields = r.free_vars |> Array.map (fun (L(i,t)) -> $"l{i}: {tyv t}") |> String.concat ", "
                let ps = r.free_vars |> Array.mapi (fun k (L(_,t)) -> $"a{k}: {tyv t}") |> String.concat ", "
                let inits = r.free_vars |> Array.mapi (fun k (L(i,_)) -> $".l{i} = a{k}") |> String.concat ", "
                let name = if kind = "Heap" then "Heap" else "Mut"
                let create = if kind = "Heap" then "heapCreate" else "mutCreate"
                types.Add($"const {name}{r.tag} = struct {{ {fields} }};")
                bodies.Add($"fn {create}{r.tag}({ps}) *{name}{r.tag} {{\n    return spiralCreate({name}{r.tag}, .{{ {inits} }});\n}}\n")
                r
        and heap x : ZigLayoutRec = layout "Heap" x
        and mut x : ZigLayoutRec = layout "Mut" x
        and union_type (heap : bool) = memo_ref (fun (cases : Map<int * string, Ty>) tag ->
            let name = if heap then $"UH{tag}" else $"US{tag}"
            let suffixes = generatedCaseSuffixes cases
            let cases = cases |> Map.toArray |> Array.map (fun (_, t) -> env.ty_to_data t |> data_free_vars)
            let fields = cases |> Array.mapi (fun c vars -> vars |> Array.mapi (fun f (L(_,t)) -> $"c{c}_{f}: {tyv t} = undefined")) |> Array.concat
            let fields = Array.append [|"tag: i32"|] fields |> String.concat ", "
            types.Add($"const {name} = struct {{ {fields} }};")
            cases |> Array.iteri (fun c vars ->
                let ps = vars |> Array.mapi (fun f (L(_,t)) -> $"a{f}: {tyv t}") |> String.concat ", "
                let inits = vars |> Array.mapi (fun f _ -> $", .c{c}_{f} = a{f}") |> String.concat ""
                let value = $"{name}{{ .tag = {c}{inits} }}"
                if heap && vars.Length = 0 then bodies.Add($"fn {name}_{suffixes.[c]}() *{name} {{\n    const shared = struct {{\n        var value: {name} = {value};\n    }};\n    return &shared.value;\n}}\n")
                elif heap then bodies.Add($"fn {name}_{suffixes.[c]}({ps}) *{name} {{\n    return spiralCreate({name}, {value});\n}}\n")
                else bodies.Add($"fn {name}_{suffixes.[c]}({ps}) {name} {{\n    return {value};\n}}\n")))
        and uheap_memo = lazy (union_type true)
        and ustack_memo = lazy (union_type false)
        and uheap x = uheap_memo.Force() x
        and ustack x = ustack_memo.Force() x
        and method_memo = lazy (memo (fun ((jp_body,key) : _ * _) tag ->
            let args = codegenMethodKeyArgs key
            match codegenMethodBody env "Zig" jp_body key with
            | body, range, name ->
                method_names.[tag] <- generatedMethodName name tag
                emit_function method_names.[tag] (Some tag) (rdata_free_vars args) "" range body ""))
        and method (a, b) : {| tag : int |} = {| tag = method_memo.Force() (a, b) |}
        and closure_memo = lazy (memo (fun ((jp_body,key & (C(args,_,fun_ty))) : _ * _) tag ->
            match fun_ty with
            | YFun(domain,range,_) ->
                match codegenClosureBody env "Zig" jp_body key with
                | domain_args, body, sourceName ->
                    closure_names.[tag] <- generatedClosureName sourceName tag
                    let free_vars = rdata_free_vars args
                    let domain_args = data_free_vars domain_args
                    let parent = fun_type (domain, range)
                    let fields = free_vars |> Array.map (fun (L(i,t)) -> $"v{i}: {tyv t}, ") |> String.concat ""
                    types.Add($"const ClosureEnv{tag} = struct {{ {fields}pad: u8 = 0 }};")
                    let loads = free_vars |> Array.map (fun (L(i,t)) -> $"    var v{i}: {tyv t} = env.v{i}; _ = &v{i};") |> String.concat "\n"
                    let prologue = $"    const env: *ClosureEnv{tag} = @ptrCast(@alignCast(ctx)); _ = &env;\n{loads}"
                    emit_function closure_names.[tag] None domain_args "ctx: *anyopaque" range body ""
                    let head = $"fn {closure_names.[tag]}("
                    let saved = bodies.FindLastIndex(fun (b : string) -> b.StartsWith head)
                    let f : string = bodies.[saved]
                    let at = f.IndexOf('\n') + 1
                    bodies.[saved] <- f.Substring(0, at) + prologue + (if loads = "" then "\n" else "\n") + f.Substring(at)
                    let inits = free_vars |> Array.map (fun (L(i,_)) -> $".v{i} = p{i}, ") |> String.concat ""
                    bodies.Add($"fn closureCreate{tag}({param_list free_vars}) Fun{parent} {{\n    return .{{ .ctx = spiralCreate(ClosureEnv{tag}, .{{ {inits}}}), .call = &{closure_names.[tag]} }};\n}}\n")
            | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."))
        and closure (a, b) : {| tag : int |} = {| tag = closure_memo.Force() (a, b) |}
        and self_tail tag (body : TypedBind []) =
            body.Length > 0 &&
            match Array.last body with
            | TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _) -> (method (a,c)).tag = tag
            | TyLocalReturnOp(_, TyIf(_,tr,fl), _) -> self_tail tag tr || self_tail tag fl
            | TyLocalReturnOp(_, TyUnionUnbox(_,_,on_succs,on_fail), _) -> (on_succs |> Map.exists (fun _ (_,b) -> self_tail tag b)) || (on_fail |> Option.exists (self_tail tag))
            | TyLocalReturnOp(_, TyIntSwitch(_,on_succ,on_fail), _) -> Array.exists (self_tail tag) on_succ || self_tail tag on_fail
            | TyLocalReturnOp(_, (TyDo b | TyIndent b), _) -> self_tail tag b
            | _ -> false

        let mainResult =
            match Array.tryLast x with
            | Some (TyLocalReturnOp(_,_,d)) | Some (TyLocalReturnData(d,_)) ->
                match data_term_vars d |> Array.map (function WV(L(_,t)) -> t | WLit l -> YPrim (lit_to_primitive_type l)) with
                | [||] -> YB
                | [|t|] -> t
                | _ -> raise_codegen_error "The main of a Zig program returns a single value (an i32 exit code, unit, or one value that is discarded), not a tuple."
            | _ -> YB
        match mainResult with
        | YPrim Int32T -> emit_function "spiralMain" None [||] "" (YPrim Int32T) x ""
        | YB ->
            emit_function "spiralMainUnit" None [||] "" YB x ""
            bodies.Add("fn spiralMain() i32 {\n    spiralMainUnit();\n    return 0;\n}\n")
        | value ->
            emit_function "spiralMainValue" None [||] "" value x ""
            bodies.Add("fn spiralMain() i32 {\n    _ = spiralMainValue();\n    return 0;\n}\n")
        let program = StringBuilder()
        env.globals |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        globals |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        types |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
        bodies |> Seq.iter (fun x -> program.Append(x) |> ignore)
        program.AppendLine("var spiral_exit_code: i32 = 0;").AppendLine("fn spiralMainThread() void {").AppendLine("    spiral_exit_code = spiralMain();").AppendLine("}") |> ignore
        program.AppendLine("extern \"kernel32\" fn CreateThread(attributes: ?*anyopaque, stack_size: usize, start: *const fn (?*anyopaque) callconv(.winapi) u32, parameter: ?*anyopaque, flags: u32, id: ?*u32) callconv(.winapi) ?std.os.windows.HANDLE;") |> ignore
        program.AppendLine("extern \"kernel32\" fn WaitForSingleObject(handle: std.os.windows.HANDLE, milliseconds: u32) callconv(.winapi) u32;") |> ignore
        program.AppendLine("extern \"kernel32\" fn ExitProcess(code: u32) callconv(.winapi) noreturn;") |> ignore
        program.AppendLine("fn spiralMainThreadReserved(_: ?*anyopaque) callconv(.winapi) u32 {").AppendLine("    spiralMainThread();").AppendLine("    return 0;").AppendLine("}") |> ignore
        program.AppendLine("pub fn main(init: std.process.Init.Minimal) void {") |> ignore
        program.AppendLine("    spiral_gpa = spiral_arena.allocator();").AppendLine("    spiral_environ = init.environ;") |> ignore
        program.AppendLine("    if (@import(\"builtin\").os.tag == .windows) {").AppendLine("        const handle = CreateThread(null, 1 << 30, spiralMainThreadReserved, null, 0x00010000, null) orelse @panic(\"spiral: could not start the main thread\");").AppendLine("        _ = WaitForSingleObject(handle, 0xFFFFFFFF);").AppendLine("    } else {").AppendLine("        const thread = std.Thread.spawn(.{ .stack_size = 1 << 30 }, spiralMainThread, .{}) catch @panic(\"spiral: could not start the main thread\");").AppendLine("        thread.join();").AppendLine("    }").AppendLine("    spiralFlush();") |> ignore
        program.AppendLine("    if (@import(\"builtin\").os.tag == .windows) ExitProcess(@bitCast(spiral_exit_code)) else std.process.exit(@truncate(@as(u32, @bitCast(spiral_exit_code))));").AppendLine("}") |> ignore
        let rename_exported_unions (code : string) =
            exportedUnionNames env x |> Seq.fold (fun (code : string) (KeyValue(node, name)) ->
                let u = (unbox<Union> node).Item
                let generated = match u.layout with UHeap -> $"UH{uheap u.cases}" | UStack -> $"US{ustack u.cases}"
                let renamed = System.Text.RegularExpressions.Regex.Replace(code, $@"\b{generated}(?=\b|_)", name)
                let renamed = System.Text.RegularExpressions.Regex.Replace(renamed, $@"(?m)^const {name} = ", $"pub const {name} = ")
                System.Text.RegularExpressions.Regex.Replace(renamed, $@"(?m)^fn {name}_", $"pub fn {name}_")
                ) code
        let import_zig_unions (code : string) =
            if linked_units.IsEmpty then code
            else
                [ for KeyValue(node, source) in unionSourceNames do
                    match linkedUnionName linked_units node source with
                    | Some (unitName, name) ->
                        let u = (unbox<Union> node).Item
                        let generated = match u.layout with UHeap -> $"UH{uheap u.cases}" | UStack -> $"US{ustack u.cases}"
                        let local = System.Text.RegularExpressions.Regex($@"(?m)^const {generated} = struct \{{.*\}};$")
                        if local.IsMatch code then yield local, generated, unitName, name
                    | None -> () ]
                |> List.fold (fun (code : string) (local, generated, unitName, name) ->
                    let code = local.Replace(code, $"const {generated} = {unitName}.{name};")
                    let import = $"const {unitName} = @import(\"{unitName}.zig\");"
                    if code.Contains import then code else import + "\n" + code) code
        let body = program.ToString() |> zigConstLocals |> rename_exported_unions |> import_zig_unions
        let body =
            let imported = linked_units |> Map.toList |> List.map (fun (_, (l : LinkedUnit)) -> l.unit) |> List.distinct |> List.filter (fun u -> body.Contains $"@import(\"{u}.zig\")")
            let forwards = imported |> List.map (fun u -> $"    {u}.spiralShareAllocator(a);\n") |> String.concat ""
            let library = body.Contains "spiral_export_env"
            let body = if library || not imported.IsEmpty then body + $"pub fn spiralShareAllocator(a: std.mem.Allocator) void {{\n    spiral_gpa = a;\n{forwards}}}\n" else body
            if imported.IsEmpty then body
            else
                let calls = imported |> List.map (fun u -> $"    {u}.spiralShareAllocator(spiral_gpa);\n") |> String.concat ""
                System.Text.RegularExpressions.Regex.Replace(body, @"(    spiral_gpa = spiral_arena\.allocator\(\);\r?\n)", "$1" + calls)
        let body =
            let decl = System.Text.RegularExpressions.Regex(@"(?m)^const (\w+) = (struct \{.*\});\r?$")
            let alias = System.Text.RegularExpressions.Regex(@"(?m)^const (\w+) = (\w+\.\w+);\r?$")
            let hash (text : string) = System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes text) |> Array.take 6 |> Array.map (fun b -> b.ToString "x2") |> String.concat ""
            let shapes =
                let decls = decl.Matches body |> Seq.map (fun m -> m.Groups.[1].Value, m.Groups.[2].Value) |> Array.ofSeq
                let leaves = alias.Matches body |> Seq.map (fun m -> m.Groups.[1].Value, m.Groups.[2].Value) |> dict
                let word = System.Text.RegularExpressions.Regex(@"\b\w+\b")
                let initial = Dictionary<string, string>()
                for (n, _) in decls do initial.[n] <- "T"
                let current = ref initial
                for _ in 1 .. 6 do
                    let next = Dictionary<string, string>()
                    for (n, def) in decls do
                        let canonical = word.Replace(def, fun (w : System.Text.RegularExpressions.Match) -> match current.Value.TryGetValue w.Value with | true, h -> "S" + h | _ -> match leaves.TryGetValue w.Value with | true, target -> target | _ -> w.Value)
                        next.[n] <- hash canonical
                    current.Value <- next
                current.Value
            let imported = linked_units |> Map.toList |> List.map (fun (_, (l : LinkedUnit)) -> l.unit) |> List.distinct |> List.filter (fun u -> body.Contains $"@import(\"{u}.zig\")")
            let body =
                if imported.IsEmpty then body
                else
                    decl.Replace(body, fun (m : System.Text.RegularExpressions.Match) ->
                        let name, def = m.Groups.[1].Value, m.Groups.[2].Value
                        let h = shapes.[name]
                        let chain = imported |> List.fold (fun (rest : string) u -> $"if (@hasDecl({u}, \"SpiralShape_{h}\")) {u}.SpiralShape_{h} else {rest}") def
                        $"const {name} = {chain};")
            if body.Contains "spiral_export_env" then
                let aliases =
                    shapes |> Seq.map (fun kv -> kv.Key, kv.Value) |> Seq.distinctBy snd
                    |> Seq.map (fun (name, h) -> $"pub const SpiralShape_{h} = {name};\n") |> String.concat ""
                body + aliases
            else body
        let prelude = zigUsedPrelude body
        (if zig_fast then prelude.Replace("    if (i < 0 or i >= len) std.process.exit(3);\n", "    _ = len;\n") else prelude) + body

    /// ## CodegenLean

    /// ### backend_nameLean
    let backend_nameLean = "Lean"

    /// ### leanString
    let leanString (x : string) =
        let strb = StringBuilder("\"")
        for c in x do
            match c with
            | '"' -> strb.Append "\\\"" |> ignore
            | '\\' -> strb.Append "\\\\" |> ignore
            | '\n' -> strb.Append "\\n" |> ignore
            | '\r' -> strb.Append "\\r" |> ignore
            | '\t' -> strb.Append "\\t" |> ignore
            | c when int c >= 32 && int c < 127 -> strb.Append c |> ignore
            | c when int c < 32 || int c = 127 -> strb.Append(sprintf "\\x%02x" (int c)) |> ignore
            | c -> strb.Append c |> ignore
        strb.Append('"').ToString()

    /// ### litLean
    let litLean = function
        | LitInt8 x -> $"({x} : Int8)"
        | LitInt16 x -> $"({x} : Int16)"
        | LitInt32 x -> $"({x} : Int32)"
        | LitInt64 x -> $"({x} : Int64)"
        | LitUInt8 x -> $"({x} : UInt8)"
        | LitUInt16 x -> $"({x} : UInt16)"
        | LitUInt32 x -> $"({x} : UInt32)"
        | LitUInt64 x -> $"({x} : UInt64)"
        | LitFloat32 x ->
            if x = infinityf then "(1.0 / 0.0 : Float32)"
            elif x = -infinityf then "(-1.0 / 0.0 : Float32)"
            elif Single.IsNaN x then "(0.0 / 0.0 : Float32)"
            else let r = x.ToString "R" |> add_dec_point in $"({r} : Float32)"
        | LitFloat64 x ->
            if x = infinity then "(1.0 / 0.0 : Float)"
            elif x = -infinity then "(-1.0 / 0.0 : Float)"
            elif Double.IsNaN x then "(0.0 / 0.0 : Float)"
            else let r = x.ToString "R" |> add_dec_point in $"({r} : Float)"
        | LitString x -> leanString x
        | LitChar x ->
            match x with
            | '\'' -> "'\\''"
            | '\\' -> "'\\\\'"
            | '\n' -> "'\\n'"
            | '\r' -> "'\\r'"
            | '\t' -> "'\\t'"
            | c when int c >= 32 && int c < 127 -> $"'{c}'"
            | c when int c < 32 || int c = 127 -> sprintf "'\\x%02x'" (int c)
            | c -> $"'{c}'"
        | LitBool x -> if x then "true" else "false"

    /// ### primLean
    let primLean = function
        | Int8T -> "Int8" | Int16T -> "Int16" | Int32T -> "Int32" | Int64T -> "Int64"
        | UInt8T -> "UInt8" | UInt16T -> "UInt16" | UInt32T -> "UInt32" | UInt64T -> "UInt64"
        | Float32T -> "Float32" | Float64T -> "Float"
        | BoolT -> "Bool" | StringT -> "String" | CharT -> "Char"

    /// ### leanPrelude
    let leanPrelude =
        "set_option linter.all false\n" +
        "class SpiralToInt (α : Type) where toI : α → Int\n" +
        "instance : SpiralToInt Int8 := ⟨Int8.toInt⟩\ninstance : SpiralToInt Int16 := ⟨Int16.toInt⟩\n" +
        "instance : SpiralToInt Int32 := ⟨Int32.toInt⟩\ninstance : SpiralToInt Int64 := ⟨Int64.toInt⟩\n" +
        "instance : SpiralToInt UInt8 := ⟨fun x => x.toNat⟩\ninstance : SpiralToInt UInt16 := ⟨fun x => x.toNat⟩\n" +
        "instance : SpiralToInt UInt32 := ⟨fun x => x.toNat⟩\ninstance : SpiralToInt UInt64 := ⟨fun x => x.toNat⟩\n" +
        "instance : SpiralToInt Float := ⟨fun x => if x < 0 then -(Int.ofNat (Float.toUInt64 (-x)).toNat) else Int.ofNat (Float.toUInt64 x).toNat⟩\n" +
        "instance : SpiralToInt Float32 := ⟨fun x => if x < 0 then -(Int.ofNat (Float32.toUInt64 (-x)).toNat) else Int.ofNat (Float32.toUInt64 x).toNat⟩\n" +
        "def spiralFail {α : Type} (msg : String) : IO α := throw (IO.userError msg)\n" +
        "def spiralIdx {α : Type} [SpiralToInt α] (i : α) : Nat := (SpiralToInt.toI i).toNat\n" +
        "def spiralAbort {α : Type} [Inhabited α] : IO α := do (← IO.getStdout).flush; IO.Process.exit 3\n" +
        "def spiralIsContinuation (b : UInt8) : Bool := b &&& 0xC0 == 0x80\n" +
        "def spiralIndex {α : Type} (xs : Array α) (i : Nat) : IO α := match xs[i]? with\n  | some x => pure x\n  | none => IO.Process.exit 3\n" +
        "def spiralStringSlice (s : String) (a b : Int) : IO String := do\n  let bytes := s.toUTF8\n  let length : Int := bytes.size\n  if a < 0 || a > length || b < a - 1 || b >= length then spiralAbort\n  else if b >= a && (spiralIsContinuation (bytes.get! a.toNat) || (b + 1 < length && spiralIsContinuation (bytes.get! (b + 1).toNat))) then spiralAbort\n  else pure (String.Pos.Raw.extract s ⟨a.toNat⟩ ⟨(b + 1).toNat⟩)\n"

    /// ### codegenLean
    /// ### leanLetAtAssignment
    let leanLetAtAssignment (generated : string) =
        if not (generated.Contains(":= default", System.StringComparison.Ordinal)) then generated
        else
            let lines = generated.Replace("\r\n", "\n").Split('\n')
            let hoisted = System.Text.RegularExpressions.Regex(@"^(?<indent>[ \t]+)let mut (?<name>v[0-9]+) : (?<type>.+?) := default$")
            let functionHead = System.Text.RegularExpressions.Regex(@"^(partial )?def \w+.*:= do$")
            let word = System.Text.RegularExpressions.Regex(@"(?<![\w.])(v[0-9]+)\b")
            let dropped = HashSet<int>()
            let replaced = Dictionary<int, string>()
            let closeFunction (start : int) (stop : int) =
                let seen = Dictionary<string, ResizeArray<int>>()
                for at = start + 1 to stop - 1 do
                    for found in word.Matches lines.[at] do
                        let name = found.Groups.[1].Value
                        match seen.TryGetValue name with
                        | true, rows -> if rows.[rows.Count - 1] <> at then rows.Add at
                        | _ -> seen.[name] <- ResizeArray [ at ]
                for at = start + 1 to stop - 1 do
                    let found = hoisted.Match lines.[at]
                    if found.Success then
                        let name = found.Groups.["name"].Value
                        let indent = found.Groups.["indent"].Value
                        let others = match seen.TryGetValue name with | true, rows -> rows |> Seq.filter (fun row -> row <> at) |> List.ofSeq | _ -> []
                        let assigns =
                            others |> List.filter (fun row ->
                                System.Text.RegularExpressions.Regex.IsMatch(lines.[row], @"^\s*" + name + " :=")
                                || System.Text.RegularExpressions.Regex.IsMatch(lines.[row], @"^\s*" + name + " ←"))
                        match assigns with
                        | [ row ] ->
                            let prefix = indent + name + " := "
                            if lines.[row].StartsWith(prefix, System.StringComparison.Ordinal) then
                                let rest = lines.[row].Substring prefix.Length
                                let selfReference = word.Matches rest |> Seq.exists (fun found -> found.Groups.[1].Value = name)
                                if not selfReference && not (others |> List.exists (fun other -> other < row)) then
                                    dropped.Add at |> ignore
                                    replaced.[row] <- indent + "let " + name + " : " + found.Groups.["type"].Value + " := " + rest
                        | _ -> ()
            let mutable start = -1
            for index = 0 to lines.Length do
                let isHead = index < lines.Length && functionHead.IsMatch lines.[index]
                let ends = index = lines.Length || (start >= 0 && lines.[index] <> "" && not (lines.[index].StartsWith " " || lines.[index].StartsWith "\t"))
                if start >= 0 && (ends || isHead) then
                    closeFunction start index
                    start <- -1
                if isHead then start <- index
            let output = System.Text.StringBuilder(generated.Length)
            let mutable first = true
            for index = 0 to lines.Length - 1 do
                if not (dropped.Contains index) then
                    if not first then output.Append('\n') |> ignore
                    first <- false
                    output.Append(match replaced.TryGetValue index with | true, text -> text | _ -> lines.[index]) |> ignore
            output.ToString()

    let codegenLean (env : PartEvalResult) (x : TypedBind []) =
        let method_names = Dictionary<int, string>()
        let closure_names = Dictionary<int, string>()
        let bodies = ResizeArray()
        let types = ResizeArray()
        let union_names = ResizeArray<string>()
        let structure_names = ResizeArray<string>()
        let union_tags = ResizeArray<string>()
        let boxed_fields = HashSet<int * int * int>()
        let memo_ref (f : 'k -> int -> unit) =
            let dict = Dictionary<'k, int>(HashIdentity.Reference)
            fun (k : 'k) ->
                match dict.TryGetValue k with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[k] <- tag
                    f k tag
                    tag
        let globals = ResizeArray()
        let memo (f : 'k -> int -> unit) =
            let dict = Dictionary<'k, int>(HashIdentity.Structural)
            fun (k : 'k) ->
                match dict.TryGetValue k with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[k] <- tag
                    f k tag
                    tag
        let global' =
            let has_added = HashSet env.globals
            fun x -> if has_added.Add(x) then globals.Add x
        let new_locals (parameters : TyV []) = HashSet(parameters |> Array.map (fun (L(i,_)) -> i)), ResizeArray<string>()
        let text (s : CodegenEnv) = s.text.ToString()
        let prim_of = function
            | DV(L(_,YPrim t)) -> Some t
            | DLit l -> Some (lit_to_primitive_type l)
            | _ -> None
        let is_int d = match prim_of d with Some (Int8T | Int16T | Int32T | Int64T | UInt8T | UInt16T | UInt32T | UInt64T) -> true | _ -> false
        let is_float d = match prim_of d with Some (Float32T | Float64T) -> true | _ -> false
        let show_w = function WV (L(i,_)) -> $"v{i}" | WLit a -> litLean a
        let unsupported what = raise_codegen_error $"The Lean backend doesn't support {what} yet."
        let self_loop : (int * TyV []) option ref = ref None
        let fresh = ref 0
        let next_fresh () = fresh.Value <- fresh.Value + 1; fresh.Value
        let rec tyv x =
            match x with
            | YPrim a -> primLean a
            | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameLean then Some v else None) with
                | Some x -> tup_ty x
                | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{backend_nameLean}' field."
            | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> unsupported "type literals") |> String.concat ""
            | YUnion a -> $"U{union_tag a.Item.cases}"
            | YLayout(_,Heap) as a -> $"H{(layout a).tag}"
            | YLayout(_,HeapMutable) as a -> $"(IO.Ref M{(layout a).tag})"
            | YLayout _ -> unsupported "stack layout types"
            | YArray a -> $"(IO.Ref (Array {tup_ty a}))"
            | YFun(a,b,_) ->
                match tyvs a with
                | [||] -> $"(Unit → IO {tup_ty b})"
                | ps -> ps |> Array.map (fun (L(_,t)) -> $"{tyv t} → ") |> String.concat "" |> fun ps -> $"({ps}IO {tup_ty b})"
            | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
            | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
            | a -> raise_codegen_error $"Type not supported in the codegen.\nGot: %A{a}"
        and tyvs (x : Ty) = env.ty_to_data x |> data_free_vars
        and tup_ty x =
            match tyvs x |> Array.map (fun (L(_,t)) -> tyv t) with
            | [||] -> "Unit"
            | [|x|] -> x
            | xs -> xs |> String.concat " × " |> sprintf "(%s)"
        and tup d =
            match data_term_vars d with
            | [||] -> "()"
            | [|x|] -> show_w x
            | xs -> xs |> Array.map show_w |> String.concat ", " |> sprintf "(%s)"
        and union_case_index (cases : Map<int * string, Ty>) k =
            cases |> Seq.map (fun (KeyValue ((_,k'),_)) -> k') |> Seq.tryFindIndex (fun k' -> UnionTagIdOps.text k = k')
            |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text k}.")
        and union_memo = lazy (memo_ref (fun (cases : Map<int * string, Ty>) tag ->
            let ctors =
                cases |> Map.toArray |> Array.mapi (fun c (_, t) ->
                    let fields =
                        env.ty_to_data t |> data_free_vars |> Array.mapi (fun j (L(_,t)) ->
                            let field = tyv t
                            match t with
                            | YFun _ when System.Text.RegularExpressions.Regex.IsMatch(field, $@"\bU{tag}\b") ->
                                boxed_fields.Add((tag, c, j)) |> ignore
                                "NonScalar → "
                            | _ -> $"{field} → ")
                        |> String.concat ""
                    $"  | {leanCaseName cases c} : {fields}U{tag}")
            let declared = cases |> Map.toArray |> Array.map (fun ((d,_),_) -> d)
            let tags = Array.init ctors.Length (fun c -> $"  | .{leanCaseName cases c} .. => {declared.[c]}")
            types.Add($"""inductive U{tag} where{"\n"}{String.concat "\n" ctors}{"\n"}""")
            union_names.Add($"U{tag}")
            union_tags.Add($"""def U{tag}.spiralTag : U{tag} → Int32{"\n"}{String.concat "\n" tags}{"\n"}""")))
        and union_tag (cases : Map<int * string, Ty>) : int = union_memo.Force() cases
        and layout_tags = Dictionary<Ty, ZigLayoutRec>(HashIdentity.Structural)
        and layout (x : Ty) : ZigLayoutRec =
            match layout_tags.TryGetValue x with
            | true, r -> r
            | _ ->
                match x with
                | YLayout(d,lay) ->
                    let d = env.ty_to_data d
                    let free_vars, by_key =
                        match d with
                        | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                        | _ -> data_free_vars d, Map.empty
                    let r = {data=d; free_vars=free_vars; free_vars_by_key=by_key; tag=layout_tags.Count}
                    layout_tags.[x] <- r
                    let name = match lay with HeapMutable -> $"M{r.tag}" | _ -> $"H{r.tag}"
                    let fields = r.free_vars |> Array.map (fun (L(i,t)) -> $"  l{i} : {tyv t}\n") |> String.concat ""
                    types.Add($"structure {name} where\n{fields}")
                    structure_names.Add name
                    r
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type.\nGot: %s{show_ty x}"
        and call (name : string) (args : TyV []) =
            match args with
            | [||] -> $"(← {name})"
            | args -> args |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat " " |> fun a -> $"(← {name} {a})"
        and emit_function (name : string) (self_tag : int option) (parameters : TyV []) (range : Ty) (body : TypedBind []) =
            let locals = new_locals parameters
            let s = {text=StringBuilder(); indent=4}
            let saved = self_loop.Value
            match self_tag with
            | Some tag when self_tail tag body ->
                self_loop.Value <- Some (tag, parameters)
                line s "repeat"
                binds locals (indent s) (ZTail range) body
            | _ ->
                self_loop.Value <- None
                binds locals s (ZTail range) body
            self_loop.Value <- saved
            let ps = parameters |> Array.map (fun (L(i,t)) -> $" (p{i} : {tyv t})") |> String.concat ""
            let copies = parameters |> Array.map (fun (L(i,t)) -> $"    let mut v{i} : {tyv t} := p{i}\n") |> String.concat ""
            let decls = snd locals |> Seq.map (sprintf "    %s\n") |> String.concat ""
            bodies.Add($"partial def {name}{ps} : IO {tup_ty range} := do\n{copies}{decls}{text s}")
        and declare (names : HashSet<int>, decls : ResizeArray<string>) (L(i,t)) =
            if names.Add i then
                match t with
                | YArray _ -> decls.Add($"let mut v{i} : {tyv t} ← IO.mkRef #[]")
                | YLayout(_,HeapMutable) -> decls.Add($"let mut v{i} : {tyv t} ← IO.mkRef default")
                | _ -> decls.Add($"let mut v{i} : {tyv t} := default")
        and binds locals (s : CodegenEnv) (ret : BindsReturnZig) (stmts : TypedBind []) =
            let emitted_before = s.text.Length
            Array.iter (function
                | TyLet(d,trace,a) ->
                    try let d = data_free_vars d
                        d |> Array.iter (declare locals)
                        op locals s (ZLocal d) a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) -> try op locals s ret a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) ->
                    try match ret with
                        | ZLocal l -> Array.iter2 (fun (L(i,_)) b -> line s $"v{i} := {show_w b}") l (data_term_vars d)
                        | ZTail range ->
                            match data_term_vars d with
                            | [||] -> line s "return ()"
                            | _ -> line s $"return {tup d}"
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) stmts
            if s.text.Length = emitted_before then line s "pure ()"
        and op locals (s : CodegenEnv) (ret : BindsReturnZig) a =
            let binds = binds locals
            let return' (x : string) =
                match ret with
                | ZLocal [||] -> line s $"let _ := {x}"
                | ZLocal [|L(i,_)|] -> line s $"v{i} := {x}"
                | ZLocal l ->
                    let k = next_fresh ()
                    let names = l |> Array.mapi (fun j _ -> $"r{k}_{j}")
                    line s $"""let ({String.concat ", " names}) := {x}"""
                    Array.iter2 (fun (L(i,_)) n -> line s $"v{i} := {n}") l names
                | ZTail range -> if tup_ty range = "Unit" then (line s $"let _ := {x}"; line s "return ()") else line s $"return {x}"
            let jp (a, b) =
                match a with
                | JPMethod(a,c) -> call method_names.[(method (a,c)).tag] b
                | JPClosure(a,c) ->
                    let name = closure_names.[(closure (a,c)).tag]
                    match b with
                    | [||] -> name
                    | b -> b |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat " " |> fun a -> $"({name} {a})"
            let layout_index (i : int) (fields : TyV []) (mutable' : bool) =
                let source = if mutable' then $"(← v{i}.get)" else $"v{i}"
                match ret with
                | ZLocal l -> Array.iter2 (fun (L(t,_)) (L(f,_)) -> line s $"v{t} := {source}.l{f}") l fields
                | ZTail _ -> raise_codegen_error "Compiler error: Layout index should never come in end position."
            match a with
            | TyMacro a ->
                let text = a |> List.map (function CMText x -> x | CMTerm (x,_) -> tup x | CMType x -> tup_ty x | CMTypeLit _ -> unsupported "type literals") |> String.concat ""
                match ret with
                | ZLocal [||] -> line s text
                | ZTail range when tup_ty range = "Unit" -> line s text; line s "return ()"
                | _ -> return' text
            | TyIf(cond,tr,fl) ->
                line s $"if {tup cond} then"
                binds (indent s) ret tr
                line s "else"
                binds (indent s) ret fl
            | TyJoinPoint(JPMethod(a,c),b) when (match ret, self_loop.Value with ZTail _, Some (tag, _) -> (method (a,c)).tag = tag | _ -> false) ->
                let parameters = snd self_loop.Value.Value
                let temps = System.Collections.Generic.Dictionary<int, string> ()
                for step in parallelMoves (Array.map2 (fun (L(target,_)) (L(source,_)) -> target, source) parameters b) do
                    match step with
                    | MoveVar (target, source) -> line s $"v{target} := v{source}"
                    | SaveTemp (slot, source) ->
                        temps.[slot] <- $"t{source}"
                        line s $"let t{source} := v{source}"
                    | MoveTemp (target, slot) -> line s $"v{target} := {temps.[slot]}"
                line s "continue"
            | TyJoinPoint(a,args) -> return' (jp (a, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The Lean backend does not support nesting other backends."
            | TyWhile(a,b) ->
                line s "repeat"
                line (indent s) $"if !{jp a} then break"
                binds (indent s) (ZLocal [||]) b
            | TyDo a | TyIndent a -> binds s ret a
            | TyFailwith(_,b) -> line s $"spiralFail {tup b}"
            | TyConv(a,b) ->
                match a with
                | YPrim (Int8T | Int16T | Int32T | Int64T as t) -> return' $"({primLean t}.ofInt (SpiralToInt.toI {tup b}))"
                | YPrim (UInt8T | UInt16T | UInt32T | UInt64T as t) -> return' $"({primLean t}.ofInt (SpiralToInt.toI {tup b}))"
                | YPrim Float64T when prim_of b = Some Float32T -> return' $"(Float32.toFloat {tup b})"
                | YPrim Float64T -> return' (if is_float b then tup b else $"(Float.ofInt (SpiralToInt.toI {tup b}))")
                | YPrim Float32T when prim_of b = Some Float64T -> return' $"(Float.toFloat32 {tup b})"
                | YPrim Float32T -> return' (if is_float b then tup b else $"(Float.toFloat32 (Float.ofInt (SpiralToInt.toI {tup b})))")
                | _ -> raise_codegen_error $"Compiler error: Unexpected type in Conv. Got: {show_ty a}"
            | TyStringLength(a,b) -> return' $"({tyv a}.ofNat {tup b}.utf8ByteSize)"
            | TyOp(ArrayIndexSet, [a;b;c]) ->
                line s $"{tup a}.modify (fun xs => xs.set! (spiralIdx {tup b}) {tup c})"
                match ret with ZTail _ -> line s "return ()" | _ -> ()
            | TyOp(Global, [DLit (LitString x)]) -> global' x
            | TyOp(Printf, [DLit (LitString fmt); b]) ->
                printf_pieces fmt (data_term_vars b) |> List.iter (function
                    | Choice1Of2 t -> line s $"IO.print {leanString t}"
                    | Choice2Of2 (_, w) -> line s $"IO.print (toString {show_w w})")
                match ret with ZTail _ -> line s "return ()" | _ -> ()
            | TyOp(op,l) ->
                let bin f = match l with [a;b] -> f (tup a) (tup b) | _ -> raise_codegen_error "Compiler error: Expected two arguments."
                let unary f = match l with [x] -> f (tup x) | _ -> raise_codegen_error "Compiler error: Expected one argument."
                let float_ns = match l with x :: _ when prim_of x = Some Float32T -> "Float32" | _ -> "Float"
                let shift o = match l with [a;b] when prim_of a <> prim_of b && prim_of a <> None -> $"({tup a} {o} ({primLean (prim_of a).Value}.ofInt (SpiralToInt.toI {tup b})))" | _ -> bin (fun a b -> $"({a} {o} {b})")
                match op, l with
                | Dyn,[a] -> tup a
                | UnionTag, [DV(L(i,YUnion u))] -> $"(U{union_tag u.Item.cases}.spiralTag v{i})"
                | ArrayIndex, [a;b] -> $"(← spiralIndex (← {tup a}.get) (spiralIdx {tup b}))"
                | StringIndex, [a;b] -> $"(Char.ofNat ({tup a}.toUTF8.get! (spiralIdx {tup b})).toNat)"
                | StringSlice, [a;b;c] -> $"(← spiralStringSlice {tup a} (SpiralToInt.toI {tup b}) (SpiralToInt.toI {tup c}))"
                | StaticStringConcat, _ -> bin (sprintf "(%s ++ %s)")
                | Add, _ -> bin (sprintf "(%s + %s)")
                | Sub, _ -> bin (sprintf "(%s - %s)")
                | Mult, _ -> bin (sprintf "(%s * %s)")
                | Div, _ -> bin (sprintf "(%s / %s)")
                | Mod, _ -> bin (sprintf "(%s %% %s)")
                | Pow, [a;_] when is_float a -> bin (sprintf "(%s.pow %s %s)" float_ns)
                | LT, _ -> bin (sprintf "(decide (%s < %s))")
                | LTE, _ -> bin (sprintf "(decide (%s <= %s))")
                | GT, _ -> bin (sprintf "(decide (%s > %s))")
                | GTE, _ -> bin (sprintf "(decide (%s >= %s))")
                | EQ, _ -> bin (sprintf "(%s == %s)")
                | NEQ, _ -> bin (sprintf "(%s != %s)")
                | BoolAnd, _ -> bin (sprintf "(%s && %s)")
                | BoolOr, _ -> bin (sprintf "(%s || %s)")
                | BitwiseAnd, _ -> bin (sprintf "(%s &&& %s)")
                | BitwiseOr, _ -> bin (sprintf "(%s ||| %s)")
                | BitwiseXor, _ -> bin (sprintf "(%s ^^^ %s)")
                | BitwiseComplement, _ -> unary (sprintf "(~~~%s)")
                | ShiftLeft, _ -> shift "<<<"
                | ShiftRight, _ -> shift ">>>"
                | Neg, _ -> unary (sprintf "(-%s)")
                | Log, _ -> unary (sprintf "(%s.log %s)" float_ns)
                | Exp, _ -> unary (sprintf "(%s.exp %s)" float_ns)
                | Tanh, _ -> unary (sprintf "(%s.tanh %s)" float_ns)
                | Sqrt, _ -> unary (sprintf "(%s.sqrt %s)" float_ns)
                | Sin, _ -> unary (sprintf "(%s.sin %s)" float_ns)
                | Cos, _ -> unary (sprintf "(%s.cos %s)" float_ns)
                | PrimToString, _ -> unary (sprintf "(toString (%s))")
                | NanIs, _ -> unary (sprintf "(%s.isNaN %s)" float_ns)
                | StdoutFlush, [] -> "(← (← IO.getStdout).flush)"
                | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported in the Lean backend" op l.Length
                |> return'
            | TyUnionUnbox(is,x,on_succs,on_fail) ->
                let x' = x.Item
                let tag = union_tag x'.cases
                line s ($"match " + (is |> List.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", ") + " with")
                on_succs |> Map.iter (fun k (a,b) ->
                    let c = union_case_index x'.cases k
                    let fields = a |> List.map data_free_vars
                    fields |> List.iter (Array.iter (declare locals))
                    let pats = fields |> List.map (fun fs -> $"U{tag}.{leanCaseName x'.cases c}" + (fs |> Array.map (fun (L(i,_)) -> $" f{i}") |> String.concat ""))
                    line s ("| " + String.concat ", " pats + " =>")
                    fields |> List.iter (Array.iteri (fun j (L(i,_)) ->
                        line (indent s) (if boxed_fields.Contains((tag, c, j)) then $"v{i} := spiralUnbox f{i}" else $"v{i} := f{i}")))
                    binds (indent s) ret b)
                let wildcard = "| " + (is |> List.map (fun _ -> "_") |> String.concat ", ") + " =>"
                match on_fail with
                | Some b -> line s wildcard; binds (indent s) ret b
                | None when is.Length > 1 || on_succs.Count < x'.cases.Count -> line s wildcard; line (indent s) "spiralFail \"union unbox: unreachable case\""
                | None -> ()
            | TyUnionBox(a,b,c) ->
                let c = c.Item
                let tag = union_tag c.cases
                let i = union_case_index c.cases a
                match data_term_vars b |> Array.map show_w with
                | [||] -> return' $"U{tag}.{leanCaseName c.cases i}"
                | args ->
                    let args = args |> Array.mapi (fun j w -> if boxed_fields.Contains((tag, i, j)) then $"(spiralBox {w})" else w)
                    return' $"""(U{tag}.{leanCaseName c.cases i} {String.concat " " args})"""
            | TyToLayout(a,b) ->
                let r = layout b
                let values = data_term_vars a |> Array.map show_w |> Array.map ((+) " ") |> String.concat ""
                match b with
                | YLayout(_,HeapMutable) -> return' $"(← IO.mkRef (M{r.tag}.mk{values}))"
                | _ -> return' $"(H{r.tag}.mk{values})"
            | TyLayoutIndexAll(L(i,(YLayout(_,lay) as a))) -> layout_index i (layout a).free_vars (lay = HeapMutable)
            | TyLayoutIndexByKey(L(i,(YLayout(_,lay) as a)),key) ->
                (layout a).free_vars_by_key |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None)
                |> Option.iter (fun fields -> layout_index i fields (lay = HeapMutable))
            | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
            | TyLayoutMutableSet(L(i,t),b,c) ->
                let r = layout t
                let a = List.fold (fun s k ->
                    match s with
                    | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                    | _ -> raise_codegen_error "Compiler error: Expected a record.") r.data b
                let updates = Array.map2 (fun (L(i',_)) b -> $"l{i'} := {show_w b}") (data_free_vars a) (data_term_vars c) |> String.concat ", "
                line s $"v{i}.modify (fun r => {{ r with {updates} }})"
                match ret with ZTail _ -> line s "return ()" | _ -> ()
            | TyArrayLiteral(a,b) -> return' $"""(← IO.mkRef (#[{b |> List.map tup |> String.concat ", "}] : Array {tup_ty a}))"""
            | TyArrayCreate(a,b) ->
                match tyvs a with
                | [|L(_,(YArray _ | YLayout(_,HeapMutable)))|] -> return' $"(← IO.mkRef (← (Array.replicate (spiralIdx {tup b}) ()).mapM (fun _ => IO.mkRef default)))"
                | _ -> return' $"(← IO.mkRef (Array.replicate (spiralIdx {tup b}) (default : {tup_ty a})))"
            | TyArrayLength(a,b) -> return' $"({tyv a}.ofNat (← {tup b}.get).size)"
            | TyIntSwitch(L(i,_),on_succ,on_fail) ->
                line s $"match v{i}.toInt with"
                on_succ |> Array.iteri (fun k b -> line s $"| {k} =>"; binds (indent s) ret b)
                line s "| _ =>"
                binds (indent s) ret on_fail
            | TyApply(L(i,_),b) ->
                match data_term_vars b |> Array.map show_w with
                | [||] -> return' $"(← v{i} ())"
                | args -> return' $"""(← v{i} {String.concat " " args})"""
            | TySizeOf _ -> unsupported "sizeof"
        and method_memo = lazy (memo (fun ((jp_body,key) : _ * _) tag ->
            let args = codegenMethodKeyArgs key
            match codegenMethodBody env "Lean" jp_body key with
            | body, range, name ->
                method_names.[tag] <- generatedMethodName name tag
                emit_function method_names.[tag] (Some tag) (rdata_free_vars args) range body))
        and method (a, b) : {| tag : int |} = {| tag = method_memo.Force() (a, b) |}
        and closure_memo = lazy (memo (fun ((jp_body,key & (C(args,_,fun_ty))) : _ * _) tag ->
            match fun_ty with
            | YFun(_,range,_) ->
                match codegenClosureBody env "Lean" jp_body key with
                | domain_args, body, sourceName ->
                    closure_names.[tag] <- generatedClosureName sourceName tag
                    let captured = rdata_free_vars args
                    let domain = data_free_vars domain_args
                    emit_function closure_names.[tag] None (Array.append captured domain) range body
                    if domain.Length = 0 then
                        let at = bodies.Count - 1
                        let head = $"partial def {closure_names.[tag]}"
                        let f : string = bodies.[at]
                        if f.StartsWith head then
                            let colon = f.IndexOf(" : IO ")
                            bodies.[at] <- f.Substring(0, colon) + " (_ : Unit)" + f.Substring(colon)
            | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."))
        and closure (a, b) : {| tag : int |} = {| tag = closure_memo.Force() (a, b) |}
        and self_tail tag (body : TypedBind []) =
            body.Length > 0 &&
            match Array.last body with
            | TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _) -> (method (a,c)).tag = tag
            | TyLocalReturnOp(_, TyIf(_,tr,fl), _) -> self_tail tag tr || self_tail tag fl
            | TyLocalReturnOp(_, (TyDo b | TyIndent b), _) -> self_tail tag b
            | _ -> false

        let unitMain =
            match Array.tryLast x with
            | Some (TyLocalReturnOp(_,_,d)) | Some (TyLocalReturnData(d,_)) ->
                match data_term_vars d |> Array.map (function WV(L(_,t)) -> t | WLit l -> YPrim (lit_to_primitive_type l)) with
                | [||] -> true
                | [|YPrim Int32T|] -> false
                | _ -> raise_codegen_error "The return type of main in the Lean backend should be a 32-bit int (or unit)."
            | _ -> true
        emit_function "spiralMain" None [||] (if unitMain then YB else YPrim Int32T) x
        let program = StringBuilder()
        program.Append(leanPrelude) |> ignore
        if bodies |> Seq.exists (fun (x : string) -> x.Split('\n').Length > 400) then program.Append("set_option maxRecDepth 100000\n") |> ignore
        env.globals |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        globals |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        if types.Count > 0 then
            if boxed_fields.Count > 0 then program.Append("private unsafe def spiralBoxUnsafe {α : Type} (x : α) : NonScalar := unsafeCast x\n@[implemented_by spiralBoxUnsafe] opaque spiralBox {α : Type} (x : α) : NonScalar\nprivate unsafe def spiralUnboxUnsafe {α : Type} [Inhabited α] (x : NonScalar) : α := unsafeCast x\n@[implemented_by spiralUnboxUnsafe] opaque spiralUnbox {α : Type} [Inhabited α] (x : NonScalar) : α\n") |> ignore
            if types |> Seq.exists (fun (x : string) -> x.Contains "IO.Ref") then program.Append("private unsafe def spiralRefDefaultUnsafe {α : Type} : IO.Ref α := unsafeCast ()\naxiom spiralRefNonempty {α : Type} : Nonempty (IO.Ref α)\nattribute [instance] spiralRefNonempty\n@[implemented_by spiralRefDefaultUnsafe] opaque spiralRefDefault {α : Type} : IO.Ref α\ninstance {α : Type} : Inhabited (IO.Ref α) := ⟨spiralRefDefault⟩\n") |> ignore
            let type_names = types |> Seq.map (fun (x : string) -> x.Split([|' '; '\n'|], System.StringSplitOptions.RemoveEmptyEntries).[1]) |> Seq.toArray
            let type_index = type_names |> Array.mapi (fun i name -> name, i) |> dict
            let type_deps = types |> Seq.map (fun (x : string) -> System.Text.RegularExpressions.Regex.Matches(x, @"\b[UHM]\d+\b") |> Seq.map (fun m -> m.Value) |> Seq.filter type_index.ContainsKey |> Seq.map (fun name -> type_index.[name]) |> Set.ofSeq) |> Seq.toArray
            let components = ResizeArray<int []>()
            let visit_index = Array.create type_names.Length -1
            let low_link = Array.zeroCreate<int> type_names.Length
            let on_stack = Array.zeroCreate<bool> type_names.Length
            let pending = System.Collections.Generic.Stack<int>()
            let next_index = ref 0
            let rec strong_component v =
                visit_index.[v] <- next_index.Value
                low_link.[v] <- next_index.Value
                next_index.Value <- next_index.Value + 1
                pending.Push v
                on_stack.[v] <- true
                for w in type_deps.[v] do
                    if visit_index.[w] < 0 then
                        strong_component w
                        low_link.[v] <- min low_link.[v] low_link.[w]
                    elif on_stack.[w] then low_link.[v] <- min low_link.[v] visit_index.[w]
                if low_link.[v] = visit_index.[v] then
                    let members = ResizeArray<int>()
                    let mutable popping = true
                    while popping do
                        let w = pending.Pop()
                        on_stack.[w] <- false
                        members.Add w
                        popping <- w <> v
                    components.Add(members |> Seq.sort |> Seq.toArray)
            for v in 0 .. type_names.Length - 1 do if visit_index.[v] < 0 then strong_component v
            for members in components do
                let cyclic = members.Length > 1 || type_deps.[members.[0]].Contains members.[0]
                if cyclic then program.AppendLine("mutual") |> ignore
                for i in members do program.Append(types.[i]) |> ignore
                if cyclic then program.AppendLine("end") |> ignore
                for i in members do program.AppendLine($"deriving instance Inhabited for {type_names.[i]}") |> ignore
            union_tags |> Seq.iter (fun (x : string) -> program.Append(x) |> ignore)
        program.AppendLine("mutual") |> ignore
        bodies |> Seq.iter (fun x -> program.Append(x) |> ignore)
        program.AppendLine("end") |> ignore
        program.AppendLine("def main : IO UInt32 := do") |> ignore
        if unitMain then program.AppendLine("  spiralMain").AppendLine("  return 0") |> ignore
        else program.AppendLine("  let code ← spiralMain").AppendLine("  return code.toUInt32") |> ignore
        program.ToString() |> leanLetAtAssignment

    /// ## CodegenBend

    /// ### backend_nameBend
    let backend_nameBend = "Bend"

    /// ### bendPrelude
    let bendPrelude = """import Base

def spiral_i32_bias(+x: U32) -> U32:
  U32.xor(x, 2147483648)

def spiral_i32_lt(+a: U32, +b: U32) -> Bool:
  U32.is_lt(spiral_i32_bias(a), spiral_i32_bias(b))

def spiral_i32_le(+a: U32, +b: U32) -> Bool:
  U32.is_le(spiral_i32_bias(a), spiral_i32_bias(b))

def spiral_i32_gt(+a: U32, +b: U32) -> Bool:
  U32.is_gt(spiral_i32_bias(a), spiral_i32_bias(b))

def spiral_i32_ge(+a: U32, +b: U32) -> Bool:
  U32.is_ge(spiral_i32_bias(a), spiral_i32_bias(b))

def spiral_i32_is_negative(+x: U32) -> Bool:
  U32.is_ge(x, 2147483648)

def spiral_i32_negate_if(+c: Bool, +x: U32) -> U32:
  match c:
    case True{}:
      U32.sub(0, x)
    case False{}:
      x

def spiral_i32_abs(+x: U32) -> U32:
  spiral_i32_negate_if(spiral_i32_is_negative(x), x)

def spiral_i32_div(+a: U32, +b: U32) -> U32:
  spiral_i32_negate_if(Bool.xor(spiral_i32_is_negative(a), spiral_i32_is_negative(b)), U32.div(spiral_i32_abs(a), spiral_i32_abs(b)))

def spiral_i32_mod(+a: U32, +b: U32) -> U32:
  spiral_i32_negate_if(spiral_i32_is_negative(a), U32.mod(spiral_i32_abs(a), spiral_i32_abs(b)))

def spiral_i32_shift_right_if(+c: Bool, +a: U32, +n: U32) -> U32:
  match c:
    case True{}:
      U32.not(U32.shrn(U32.not(a), U32.to_nat(n)))
    case False{}:
      U32.shrn(a, U32.to_nat(n))

def spiral_i32_shift_right(+a: U32, +n: U32) -> U32:
  spiral_i32_shift_right_if(spiral_i32_is_negative(a), a, n)

def spiral_i32_show_if(+c: Bool, +x: U32) -> String:
  match c:
    case True{}:
      "-" ++ U32.show(U32.sub(0, x))
    case False{}:
      U32.show(x)

def spiral_i32_show(+x: U32) -> String:
  spiral_i32_show_if(spiral_i32_is_negative(x), x)
def spiral_utf8_width_from(+c: U32, +below_2: Bool, +below_3: Bool, +below_4: Bool) -> U32:
  match below_2:
    case True{}:
      {1 : U32}
    case False{}:
      match below_3:
        case True{}:
          {2 : U32}
        case False{}:
          match below_4:
            case True{}:
              {3 : U32}
            case False{}:
              {4 : U32}

def spiral_utf8_width(+c: U32) -> U32:
  spiral_utf8_width_from(c, U32.is_lt(c, 128), U32.is_lt(c, 2048), U32.is_lt(c, 65536))

def spiral_utf8_lead_mask(+single: Bool, +w: U32) -> U32:
  match single:
    case True{}:
      {0 : U32}
    case False{}:
      U32.and(U32.shln(255, U32.to_nat(U32.sub(8, w))), 255)

def spiral_utf8_byte_from(+lead: Bool, +c: U32, +w: U32, +k: U32) -> U32:
  match lead:
    case True{}:
      U32.or(spiral_utf8_lead_mask(U32.is_eq(w, 1), w), U32.shrn(c, U32.to_nat(U32.mul(6, U32.sub(w, 1)))))
    case False{}:
      U32.or(128, U32.and(U32.shrn(c, U32.to_nat(U32.mul(6, U32.sub(U32.sub(w, 1), k)))), 63))

def spiral_utf8_byte(+c: U32, +w: U32, +k: U32) -> U32:
  spiral_utf8_byte_from(U32.is_eq(k, 0), c, w, k)

@unsafe
def spiral_string_bytes(+s: String) -> U32:
  match s:
    case SNil{}:
      {0 : U32}
    case SCon{+h, +t}:
      U32.add(spiral_utf8_width(Char.to_u32(h)), spiral_string_bytes(t))

@unsafe
def spiral_string_byte_at_from(+inside: Bool, +c: U32, +w: U32, +i: U32, +t: String) -> U32:
  match inside:
    case True{}:
      spiral_utf8_byte(c, w, i)
    case False{}:
      spiral_string_byte_at(t, U32.sub(i, w))

@unsafe
def spiral_string_byte_at(+s: String, +i: U32) -> U32:
  match s:
    case SNil{}:
      {0 : U32}
    case SCon{+h, +t}:
