        while changed && rounds < 20 do
            rounds <- rounds + 1
            let lines = text.Split('\n')
            let heads = Dictionary<string, int * string list * Set<int>>()
            for index = 0 to lines.Length - 1 do
                let found = head.Match lines.[index]
                if found.Success then
                    let body = System.Text.StringBuilder()
                    let mutable next = index + 1
                    while next < lines.Length && (lines.[next] = "" || lines.[next].StartsWith " " || lines.[next].StartsWith "\t") do
                        body.Append(lines.[next]).Append('\n') |> ignore
                        next <- next + 1
                    let bodyText = body.ToString().TrimEnd('\n')
                    let parts = splitTop found.Groups.["params"].Value
                    let drop =
                        parts
                        |> List.indexed
                        |> List.filter (fun (_, part) ->
                            let name = nameOf part
                            name <> "" && name <> "c" && not (System.Text.RegularExpressions.Regex.IsMatch(bodyText, @"(?<![\w.])" + System.Text.RegularExpressions.Regex.Escape name + @"\b")))
                        |> List.map fst
                        |> Set.ofList
                    if not drop.IsEmpty then heads.[found.Groups.["name"].Value] <- (index, parts, drop)
            if heads.Count = 0 then changed <- false
            else
                for KeyValue(name, (index, parts, drop)) in heads do
                    let found = head.Match lines.[index]
                    let kept = parts |> List.indexed |> List.filter (fun (i, _) -> not (drop.Contains i)) |> List.map snd
                    lines.[index] <- "def " + name + "(" + String.concat ", " kept + ") -> " + found.Groups.["ret"].Value + ":"
                text <- System.String.Join("\n", lines)
                let pieces = System.Text.StringBuilder()
                let mutable last = 0
                for found in calls.Matches text do
                    let name = found.Groups.[1].Value
                    let isDef = found.Index >= 4 && text.Substring(found.Index - 4, 4) = "def "
                    if heads.ContainsKey name && not isDef && found.Index + found.Length >= last then
                        let openAt = found.Index + found.Length
                        let mutable depth = 1
                        let mutable index = openAt
                        while index < text.Length && depth > 0 do
                            match text.[index] with
                            | '(' | '[' | '{' -> depth <- depth + 1
                            | ')' | ']' | '}' -> depth <- depth - 1
                            | _ -> ()
                            index <- index + 1
                        let closeAt = index - 1
                        let _, parts, drop = heads.[name]
                        let args = splitTop (text.Substring(openAt, closeAt - openAt))
                        if args.Length = parts.Length then
                            let kept = args |> List.indexed |> List.filter (fun (i, _) -> not (drop.Contains i)) |> List.map snd
                            pieces.Append(text.Substring(last, openAt - last)).Append(String.concat ", " kept) |> ignore
                            last <- closeAt
                pieces.Append(text.Substring last) |> ignore
                text <- pieces.ToString()
        text

    let codegenBend (env : PartEvalResult) (x : TypedBind []) =

        let method_names = Dictionary<int, string>()
        let closure_names = Dictionary<int, string>()
        let defs = ResizeArray<string>()
        let types = ResizeArray<string>()
        let unsupported what = raise_codegen_error $"The Bend backend doesn't support {what} yet."
        let primBend = function
            | Int32T | UInt32T | CharT | Int8T | Int16T | UInt8T | UInt16T -> "U32"
            | Int64T | UInt64T -> "(U32 & U32)"
            | BoolT -> "Bool"
            | StringT -> "String"
            | Float32T -> "F32"
            | t -> unsupported $"the primitive type %A{t}"
        let fresh = ref 0
        let next_fresh () = fresh.Value <- fresh.Value + 1; fresh.Value
        let linear_unions = HashSet<int>()
        let layout_parts_memo = Dictionary<Ty, TyV [] * Map<int * string, TyV []> * Data>(HashIdentity.Structural)
        let type_argument (t : string) = if t.Contains " & " then $"({t})" else t
        let rec tyv = function
            | YPrim a -> primBend a
            | YUnion a -> $"U{union_tag a.Item.cases}"
            | YArray a -> $"(Chan(Array<{type_argument (tup_ty a)}>) & U32)"
            | YFun(a,b,_) -> $"(({tup_ty a}) -> IO({tup_ty b}))"
            | YLayout(_, Heap) as a -> $"({layout_tuple_type a})"
            | YLayout(_, HeapMutable) as a -> $"(Chan(Array<{type_argument (layout_tuple_type a)}>) & U32)"
            | a -> unsupported $"the type {show_ty a}"
        and layout_parts (x : Ty) =
            match layout_parts_memo.TryGetValue x with
            | true, parts -> parts
            | _ ->
                match x with
                | YLayout(d, _) ->
                    let d = env.ty_to_data d
                    let fields, fields_by_key =
                        match d with
                        | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                        | _ -> data_free_vars d, Map.empty
                    let parts = fields, fields_by_key, d
                    layout_parts_memo.[x] <- parts
                    parts
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type.\nGot: %s{show_ty x}"
        and layout_tuple_type (x : Ty) =
            let fields, _, _ = layout_parts x
            match fields |> Array.map (fun (L(_,t)) -> tyv t) with
            | [||] -> "Unit"
            | [|x|] -> x
            | xs -> String.concat " & " xs
        and tyvs (x : Ty) = env.ty_to_data x |> data_free_vars
        and tup_ty x =
            match tyvs x |> Array.map (fun (L(_,t)) -> tyv t) with
            | [||] -> "Unit"
            | [|x|] -> x
            | xs -> String.concat " & " xs
        and union_case_index (cases : Map<int * string, Ty>) k =
            cases |> Seq.map (fun (KeyValue ((_,k'),_)) -> k') |> Seq.tryFindIndex (fun k' -> UnionTagIdOps.text k = k')
            |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text k}.")
        and union_memo = lazy (
            let dict = Dictionary<Map<int * string, Ty>, int>(HashIdentity.Reference)
            fun (cases : Map<int * string, Ty>) ->
                match dict.TryGetValue cases with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[cases] <- tag
                    let field_types = cases |> Map.toArray |> Array.map (fun (_, t) -> env.ty_to_data t |> data_free_vars |> Array.map (fun (L(_,t)) -> t))
                    let ctors =
                        field_types |> Array.mapi (fun c fields ->
                            let fields = fields |> Array.mapi (fun j t -> match t with YPrim (Int64T | UInt64T) -> $"f{j}_hi: U32, f{j}_lo: U32" | _ -> $"f{j}: {tyv t}") |> String.concat ", "
                            let case_name = generatedCaseName (sprintf "U%i" tag) cases c
                            $"  {case_name}{{{fields}}}")
                    let linear = field_types |> Array.exists (Array.exists linear_ty)
                    if linear then linear_unions.Add tag |> ignore
                    types.Add($"""type U{tag} is {(if linear then "Type" else "Data")}:{"\n"}{String.concat "\n" ctors}{"\n"}""")
                    tag)
        and union_tag (cases : Map<int * string, Ty>) : int = union_memo.Force() cases
        and linear_ty = function
            | YArray _ -> true
            | YFun _ -> true
            | YUnion u -> linear_unions.Contains (union_tag u.Item.cases)
            | YLayout(_, HeapMutable) -> true
            | YLayout(_, Heap) as a -> let fields, _, _ = layout_parts a in fields.Length > 1 || fields |> Array.exists (fun (L(_,t)) -> linear_ty t)
            | _ -> false
        let lit = function
            | LitInt32 x -> $"{{{uint32 x} : U32}}"
            | LitUInt32 x -> $"{{{x} : U32}}"
            | LitInt64 x -> $"({{{uint32 (uint64 x >>> 32)} : U32}}, {{{uint32 (uint64 x)} : U32}})"
            | LitUInt64 x -> $"({{{uint32 (x >>> 32)} : U32}}, {{{uint32 x} : U32}})"
            | LitInt8 x -> $"{{{uint32 (int32 x)} : U32}}"
            | LitInt16 x -> $"{{{uint32 (int32 x)} : U32}}"
            | LitUInt8 x -> $"{{{x} : U32}}"
            | LitUInt16 x -> $"{{{x} : U32}}"
            | LitBool x -> if x then "True{}" else "False{}"
            | LitString x -> bendString x
            | LitChar x -> $"{{{int x} : U32}}"
            | LitFloat32 x when Single.IsPositiveInfinity x -> "F32.div(1.0, 0.0)"
            | LitFloat32 x when Single.IsNegativeInfinity x -> "F32.div(F32.neg(1.0), 0.0)"
            | LitFloat32 x when Single.IsNaN x -> "F32.div(0.0, 0.0)"
            | LitFloat32 x when x < 0.0f -> "F32.neg(" + add_dec_point ((-x).ToString("R", Globalization.CultureInfo.InvariantCulture)) + ")"
            | LitFloat32 x -> add_dec_point (x.ToString("R", Globalization.CultureInfo.InvariantCulture))
            | l -> unsupported $"the literal %A{l}"
        let show_w = function WV (L(i,_)) -> $"v{i}" | WLit a -> lit a
        let tup d =
            match data_term_vars d with
            | [||] -> "Unit{}"
            | [|x|] -> show_w x
            | xs -> xs |> Array.map show_w |> String.concat ", " |> sprintf "(%s)"
        let prim_of = function
            | DV(L(_,YPrim t)) -> Some t
            | DLit l -> Some (lit_to_primitive_type l)
            | _ -> None
        let narrow_small (t : PrimitiveType) (e : string) =
            match t with
            | Int8T -> $"spiral_narrow_i8({e})"
            | Int16T -> $"spiral_narrow_i16({e})"
            | UInt8T -> $"U32.and({e}, 255)"
            | UInt16T -> $"U32.and({e}, 65535)"
            | _ -> e
        let is_small_int = function Some (Int8T | Int16T | UInt8T | UInt16T) -> true | _ -> false
        let param (L(i,t)) = $"+v{i}: {tyv t}"
        let params (vs : TyV seq) = vs |> Seq.map (fun v -> ", " + param v) |> String.concat ""
        let args (vs : TyV seq) = vs |> Seq.map (fun (L(i,_)) -> $", v{i}") |> String.concat ""
        let array_helper_suffixes = Dictionary<string, int>()
        let nested_array_creators = HashSet<string>()
        let union_tag_readers = HashSet<int>()
        let array_suffix_of_type (element_type : string) =
            let element_type = type_argument element_type
            match array_helper_suffixes.TryGetValue element_type with
            | true, k -> $"_a{k}"
            | _ ->
                let k = array_helper_suffixes.Count
                array_helper_suffixes.[element_type] <- k
                defs.Add(bendArrayHelpers.Replace("__T__", element_type).Replace("__K__", $"_a{k}"))
                $"_a{k}"
        let array_suffix (element : Ty) = array_suffix_of_type (tup_ty element)
        let tuple_of (names : string []) =
            match names with
            | [||] -> "Unit{}"
            | [|x|] -> x
            | xs -> xs |> String.concat ", " |> sprintf "(%s)"
        let destructure (source : string) (prefix : string) (count : int) =
            match count with
            | 0 | 1 -> [||], (if count = 1 then [|source|] else [||])
            | n ->
                let names = Array.init n (fun j -> $"{prefix}{j}")
                let binders = names |> Array.map (fun x -> "+" + x) |> String.concat ", "
                [|$"  ({binders}) = {source}"|], names
        let layout_cell_slot = "{0 : U32}"
        let array_element (d : Data) =
            match data_free_vars d with
            | [|L(_, YArray element)|] -> element
            | _ -> raise_codegen_error "Compiler error: Expected an array."
        let default_depth_limit = 8
        let rec default_value (depth : int) (t : Ty) : string =
            if depth > default_depth_limit then unsupported $"default values of the recursive type {show_ty t}"
            match t with
            | YPrim (Int32T | UInt32T | CharT | Int8T | Int16T | UInt8T | UInt16T) -> "{0 : U32}"
            | YPrim (Int64T | UInt64T) -> "({0 : U32}, {0 : U32})"
            | YPrim BoolT -> "False{}"
            | YPrim StringT -> bendString ""
            | YPrim Float32T -> "0.0"
            | YUnion u ->
                let cases = u.Item.cases
                let tag = union_tag cases
                let field_types (_, t) = env.ty_to_data t |> data_free_vars |> Array.map (fun (L(_,t)) -> t)
                let indexed = cases |> Map.toArray |> Array.mapi (fun c case -> c, field_types case)
                let c, fields = indexed |> Array.minBy (fun (_, fields) -> fields.Length)
                let values = fields |> Array.map (fun t -> match t with YPrim (Int64T | UInt64T) -> "{0 : U32}, {0 : U32}" | _ -> default_value (depth + 1) t) |> String.concat ", "
                let case_name = generatedCaseName (sprintf "U%i" tag) cases c
                $"{case_name}{{{values}}}"
            | YLayout(_, Heap) ->
                let fields, _, _ = layout_parts t
                match fields |> Array.map (fun (L(_,t)) -> default_value (depth + 1) t) with
                | [||] -> "Unit{}"
                | [|x|] -> x
                | xs -> xs |> String.concat ", " |> sprintf "(%s)"
            | _ -> unsupported $"default values of the type {show_ty t}"
        let default_tuple (element : Ty) =
            match tyvs element |> Array.map (fun (L(_,t)) -> default_value 0 t) with
            | [||] -> "Unit{}"
            | [|x|] -> x
            | xs -> xs |> String.concat ", " |> sprintf "(%s)"
        let rec emit_def (name : string) (parameters : TyV []) (range : Ty) (body : TypedBind []) =
            let text = StringBuilder()
            binds name "  " (tup_ty range) text (ResizeArray parameters) body
            let ps = parameters |> Array.map param |> String.concat ", "
            defs.Add($"@unsafe\ndef {name}({ps}) -> IO({tup_ty range}):\n{text}")
        and binds owner (indentation : string) (range : string) (text : StringBuilder) (scope : ResizeArray<TyV>) (stmts : TypedBind []) =
            text.Append(indentation).Append($"do IO<{range}>:\n") |> ignore
            let emit (x : string) = text.Append(indentation).Append("  ").Append(x).Append('\n') |> ignore
            let rec go i =
                if i >= stmts.Length then emit "return Unit{}"
                else
                    match stmts.[i] with
                    | TyLet(d, trace, a) ->
                        try match data_free_vars d with
                            | [||] -> emit (op owner "Unit" scope a); go (i + 1)
                            | [|L(j,t) as v|] ->
                                emit $"+v{j} : {tyv t} <- {op owner (tyv t) scope a}"
                                scope.Add v
                                go (i + 1)
                            | vs ->
                                let result = vs |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat " & "
                                let value = op owner result scope a
                                let name = $"{owner}_k{next_fresh ()}"
                                let captured = scope.ToArray()
                                let body = StringBuilder()
                                let destructure = vs |> Array.map (fun (L(j,_)) -> $"+v{j}") |> String.concat ", "
                                body.Append($"  ({destructure}) = p\n") |> ignore
                                binds name "  " range body (ResizeArray(Array.append captured vs)) stmts.[i + 1 ..]
                                defs.Add($"@unsafe\ndef {name}(+p: {result}{params captured}) -> IO({range}):\n{body}")
                                emit $"+p : {result} <- {value}"
                                emit $"{name}(p{args captured})"
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                    | TyLocalReturnOp(trace, a, _) ->
                        try emit (op owner range scope a)
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                    | TyLocalReturnData(d, trace) ->
                        try emit $"return {tup d}"
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
            go 0
        and op owner (result : string) (scope : ResizeArray<TyV>) a =
            let signed l = match l with x :: _ -> (match prim_of x with Some (Int32T | Int8T | Int16T) -> true | _ -> false) | [] -> false
            match a with
            | TyIf(cond, tr, fl) ->
                let name = $"{owner}_if{next_fresh ()}"
                let captured = scope.ToArray()
                let branch (stmts : TypedBind []) =
                    let text = StringBuilder()
                    binds name "      " result text (ResizeArray captured) stmts
                    text.ToString()
                let true_branch = branch tr
                let false_branch = branch fl
                defs.Add($"@unsafe\ndef {name}(+c: Bool{params captured}) -> IO({result}):\n  match c:\n    case True{{}}:\n{true_branch}    case False{{}}:\n{false_branch}")
                $"{name}({tup cond}{args captured})"
            | TyUnionUnbox(scrutinees, x, on_succs, on_fail) ->
                let cases = x.Item.cases
                let tag = union_tag cases
                let name = $"{owner}_unbox{next_fresh ()}"
                let captured = scope.ToArray()
                let text = StringBuilder()
                let subjects = List.toArray scrutinees
                let subject k = if k = 0 then "u" else $"u{k}"
                let last = subjects.Length - 1
                let ruled_out (pad : string) =
                    match on_fail with
                    | Some b -> binds name pad result text (ResizeArray captured) b
                    | None -> text.Append($"{pad}do IO<{result}>:\n{pad}  IO.die({result}, 3, \"\")\n") |> ignore
                let rec level k (bound : TyV []) (only : int option) =
                    let case_pad = String.replicate (4 + 4 * k) " "
                    let body_pad = String.replicate (6 + 4 * k) " "
                    let match_pad = String.replicate (2 + 4 * k) " "
                    if k > 0 then text.Append($"{match_pad}match {subject k}:\n") |> ignore
                    cases |> Map.toArray |> Array.iteri (fun c ((_, case_text), t) ->
                        let handled = on_succs |> Map.tryPick (fun k' v -> if UnionTagIdOps.text k' = case_text then Some v else None)
                        let case_name = generatedCaseName (sprintf "U%i" tag) cases c
                        let same_case = match only with Some c' -> c' = c | None -> true
                        match handled with
                        | Some (payloads, b) when same_case ->
                            let fields = data_free_vars (List.item k payloads)
                            let binders = fields |> Array.map (fun (L(j,t)) -> match t with YPrim (Int64T | UInt64T) -> $"+v{j}_hi, +v{j}_lo" | _ -> $"+v{j}") |> String.concat ", "
                            text.Append($"{case_pad}case {case_name}{{{binders}}}:\n") |> ignore
                            let bound = Array.append bound fields
                            if k = last then
                                let arm = text.Length
                                binds name body_pad result text (ResizeArray(Array.append captured bound)) b
                                let rebuilt =
                                    bound
                                    |> Array.choose (fun (L(j,t)) -> match t with YPrim (Int64T | UInt64T) -> Some $"{body_pad}  +v{j} : (U32 & U32) <- IO.pure((U32 & U32), (v{j}_hi, v{j}_lo))\n" | _ -> None)
                                    |> String.concat ""
                                if rebuilt <> "" then text.Insert(arm + text.ToString(arm, text.Length - arm).IndexOf('\n') + 1, rebuilt) |> ignore
                            else level (k + 1) bound (Some c)
                        | _ ->
                            let width = env.ty_to_data t |> data_free_vars |> Array.sumBy (fun (L(_,t)) -> match t with YPrim (Int64T | UInt64T) -> 2 | _ -> 1)
                            let ignored = Array.init width (fun j -> $"unused{j}") |> String.concat ", "
                            text.Append($"{case_pad}case {case_name}{{{ignored}}}:\n") |> ignore
                            ruled_out body_pad)
                level 0 [||] None
                let parameters = subjects |> Array.mapi (fun k _ -> $"+{subject k}: U{tag}") |> String.concat ", "
                let arguments = subjects |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
                defs.Add($"@unsafe\ndef {name}({parameters}{params captured}) -> IO({result}):\n  match u:\n{text}")
                $"{name}({arguments}{args captured})"
            | TyUnionBox(a,b,c) ->
                let c = c.Item
                let tag = union_tag c.cases
                let i = union_case_index c.cases a
                let wide = function WV (L(_, YPrim (Int64T | UInt64T))) -> true | WLit a -> (match lit_to_primitive_type a with Int64T | UInt64T -> true | _ -> false) | _ -> false
                let values = data_term_vars b |> Array.map (fun w -> if wide w then $"w64_hi({show_w w}), w64_lo({show_w w})" else show_w w) |> String.concat ", "
                let case_name = generatedCaseName (sprintf "U%i" tag) c.cases i
                $"IO.pure({result}, {case_name}{{{values}}})"
            | TyJoinPoint(JPMethod(a,c), arguments) ->
                let arguments = arguments |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
                $"{method_names.[(method (a,c)).tag]}({arguments})"
            | TyJoinPoint(JPClosure(a,c), captured) ->
                let name = closure_names.[(closure (a,c)).tag]
                let captured_args = captured |> Array.map (fun (L(i,_)) -> $"v{i}, ") |> String.concat ""
                $"IO.pure({result}, d => {name}({captured_args}d))"
            | TyApply(L(i,_), b) -> $"v{i}({tup b})"
            | TyConv(YPrim (Int64T | UInt64T), b) when (match prim_of b with Some (Int64T | UInt64T) -> true | _ -> false) -> $"IO.pure({result}, {tup b})"
            | TyConv(YPrim (Int64T | UInt64T), b) when (match prim_of b with Some (Int32T | Int8T | Int16T) -> true | _ -> false) -> $"IO.pure({result}, w64_of_i32({tup b}))"
            | TyConv(YPrim (Int64T | UInt64T), b) when (match prim_of b with Some (UInt32T | UInt8T | UInt16T | CharT) -> true | _ -> false) -> $"IO.pure({result}, w64_of_u32({tup b}))"
            | TyConv(YPrim (Int32T | UInt32T), b) when (match prim_of b with Some (Int64T | UInt64T) -> true | _ -> false) -> $"IO.pure({result}, w64_lo({tup b}))"
            | TyConv(YPrim (Int32T | UInt32T), b) when (match prim_of b with Some (Int32T | UInt32T) -> true | _ -> false) -> $"IO.pure({result}, {tup b})"
            | TyConv(YPrim (Int8T | Int16T | UInt8T | UInt16T as t), b) when is_small_int (prim_of b) || prim_of b = Some Int32T || prim_of b = Some UInt32T -> $"IO.pure({result}, {narrow_small t (tup b)})"
            | TyConv(YPrim (Int32T | UInt32T), b) when is_small_int (prim_of b) -> $"IO.pure({result}, {tup b})"
            | TyConv(YPrim Float32T, b) when prim_of b = Some Float32T -> $"IO.pure({result}, {tup b})"
            | TyConv(YPrim Float32T, b) when prim_of b = Some Int32T -> $"IO.pure({result}, spiral_i32_to_f32({tup b}))"
            | TyConv(YPrim Float32T, b) when prim_of b = Some UInt32T -> $"IO.pure({result}, U32.to_f32({tup b}))"
            | TyConv(YPrim Int32T, b) when prim_of b = Some Float32T -> $"IO.pure({result}, spiral_f32_to_i32({tup b}))"
            | TyConv(YPrim UInt32T, b) when prim_of b = Some Float32T -> $"IO.pure({result}, F32.to_u32({tup b}))"
            | TyOp(Printf, [DLit (LitString fmt); b]) ->
                let pieces =
                    printf_pieces fmt (data_term_vars b) |> List.map (function
                        | Choice1Of2 text -> bendString text
                        | Choice2Of2 (_, w) ->
                            match w with
                            | WV(L(_,YPrim Int64T)) | WLit (LitInt64 _) -> $"w64_show_s({show_w w})"
                            | WV(L(_,YPrim UInt64T)) | WLit (LitUInt64 _) -> $"w64_show_u({show_w w})"
                            | WV(L(_,YPrim Int32T)) | WLit (LitInt32 _) -> $"spiral_i32_show({show_w w})"
                            | WV(L(_,YPrim UInt32T)) | WLit (LitUInt32 _) -> $"U32.show({show_w w})"
                            | WV(L(_,YPrim (Int8T | Int16T))) | WLit (LitInt8 _ | LitInt16 _) -> $"spiral_i32_show({show_w w})"
                            | WV(L(_,YPrim (UInt8T | UInt16T))) | WLit (LitUInt8 _ | LitUInt16 _) -> $"U32.show({show_w w})"
                            | WV(L(_,YPrim StringT)) | WLit (LitString _) -> show_w w
                            | _ -> unsupported "printing this value type")
                match pieces with
                | [] -> "IO.pure(Unit, Unit{})"
                | pieces -> $"""IO.write({String.concat " ++ " pieces})"""
            | TyArrayCreate(a, b) ->
                match tyvs a with
                | [|L(_, YArray inner)|] ->
                    let outer = array_suffix a
                    let name = $"spiral_array_new_nested{outer}"
                    if nested_array_creators.Add name then
                        let inner_type = tyv (YArray inner)
                        let outer_type = tyv (YArray a)
                        defs.Add($"@unsafe\ndef {name}(+length: U32) -> IO({outer_type}):\n  do IO<{outer_type}>:\n    +empty : {inner_type} <- spiral_array_new{array_suffix inner}(0, {default_tuple inner})\n    spiral_array_new{outer}(length, empty)\n")
                    $"{name}({tup b})"
                | _ -> $"spiral_array_new{array_suffix a}({tup b}, {default_tuple a})"
            | TyArrayLength(_, b) -> $"IO.pure({result}, spiral_array_length{array_suffix (array_element b)}({tup b}))"
            | TyOp(ArrayIndex, [a;b]) -> $"spiral_array_get{array_suffix (array_element a)}({tup a}, {tup b})"
            | TyOp(ArrayIndexSet, [a;b;c]) -> $"spiral_array_set{array_suffix (array_element a)}({tup a}, {tup b}, {tup c})"
            | TyStringLength(_, b) -> $"IO.pure({result}, spiral_string_bytes({tup b}))"
            | TyOp(StringSlice, [a;b;c]) -> $"spiral_string_slice({tup a}, {tup b}, {tup c})"
            | TyOp(op, l) ->
                let bin f = match l with [a;b] -> f (tup a) (tup b) | _ -> raise_codegen_error "Compiler error: Expected two arguments."
                let unary f = match l with [x] -> f (tup x) | _ -> raise_codegen_error "Compiler error: Expected one argument."
                let is_bool = match l with x :: _ -> prim_of x = Some BoolT | [] -> false
                let is_string = match l with x :: _ -> prim_of x = Some StringT | [] -> false
                let is_float = match l with x :: _ -> prim_of x = Some Float32T | [] -> false
                let is_w64 = match l with x :: _ -> (match prim_of x with Some (Int64T | UInt64T) -> true | _ -> false) | [] -> false
                let signed64 = match l with x :: _ -> prim_of x = Some Int64T | [] -> false
                let expr =
                  match op with
                  | Dyn -> unary id
                  | UnionTag ->
                      match l with
                      | [DV(L(i,YUnion u))] ->
                          let cases = u.Item.cases
                          let tag = union_tag cases
                          if linear_unions.Contains tag then unsupported "UnionTag on a union with linear fields"
                          let prefix = sprintf "U%i" tag
                          if union_tag_readers.Add tag then
                              let arms =
                                  cases |> Map.toArray |> Array.mapi (fun c ((declared, _), t) ->
                                      let width = env.ty_to_data t |> data_free_vars |> Array.sumBy (fun (L(_,t)) -> match t with YPrim (Int64T | UInt64T) -> 2 | _ -> 1)
                                      let ignored = Array.init width (fun j -> $"unused{j}") |> String.concat ", "
                                      $"    case {generatedCaseName prefix cases c}{{{ignored}}}:\n      {{{declared} : U32}}\n")
                                  |> String.concat ""
                              defs.Add($"def U{tag}_spiral_tag(u: U{tag}) -> U32:\n  match u:\n{arms}")
                          $"U{tag}_spiral_tag(v{i})"
                      | _ -> raise_codegen_error "Compiler error: Expected one union argument."
                  | Add when is_float -> bin (sprintf "F32.add(%s, %s)")
                  | Sub when is_float -> bin (sprintf "F32.sub(%s, %s)")
                  | Mult when is_float -> bin (sprintf "F32.mul(%s, %s)")
                  | Div when is_float -> bin (sprintf "F32.div(%s, %s)")
                  | Mod when is_float -> bin (sprintf "F32.mod(%s, %s)")
                  | LT when is_float -> bin (sprintf "F32.is_lt(%s, %s)")
                  | LTE when is_float -> bin (sprintf "F32.is_le(%s, %s)")
                  | GT when is_float -> bin (sprintf "F32.is_gt(%s, %s)")
                  | GTE when is_float -> bin (sprintf "F32.is_ge(%s, %s)")
                  | EQ when is_float -> bin (sprintf "F32.is_eq(%s, %s)")
                  | NEQ when is_float -> bin (sprintf "F32.is_ne(%s, %s)")
                  | Neg when is_float -> unary (sprintf "F32.neg(%s)")
                  | Sqrt when is_float -> unary (sprintf "F32.sqrt(%s)")
                  | Exp when is_float -> unary (sprintf "F32.exp(%s)")
                  | Log when is_float -> unary (sprintf "F32.log(%s)")
                  | Sin when is_float -> unary (sprintf "F32.sin(%s)")
                  | Cos when is_float -> unary (sprintf "F32.cos(%s)")
                  | Tanh when is_float -> unary (sprintf "F32.tanh(%s)")
                  | Pow when is_float -> bin (sprintf "F32.pow(%s, %s)")
                  | PrimToString ->
                      match l with
                      | [x] ->
                          match prim_of x with
                          | Some BoolT -> $"spiral_bool_show({tup x})"
                          | Some CharT -> $"SCon{{Char.from_u32({tup x}), SNil{{}}}}"
                          | Some Int64T -> $"w64_show_s({tup x})"
                          | Some UInt64T -> $"w64_show_u({tup x})"
                          | Some (Int32T | Int8T | Int16T) -> $"spiral_i32_show({tup x})"
                          | _ -> $"U32.show({tup x})"
                      | _ -> raise_codegen_error "Compiler error: Expected one argument."
                  | NanIs when is_float -> unary (fun x -> $"F32.is_ne({x}, {x})")
                  | LT when is_string -> bin (sprintf "String.is_lt(%s, %s)")
                  | LTE when is_string -> bin (sprintf "String.is_le(%s, %s)")
                  | GT when is_string -> bin (sprintf "String.is_gt(%s, %s)")
                  | GTE when is_string -> bin (sprintf "String.is_ge(%s, %s)")
                  | Add when is_w64 -> bin (sprintf "w64_add(%s, %s)")
                  | Sub when is_w64 -> bin (sprintf "w64_sub(%s, %s)")
                  | Mult when is_w64 -> bin (sprintf "w64_mul(%s, %s)")
                  | Div when is_w64 -> bin (if signed64 then sprintf "w64_sdiv(%s, %s)" else sprintf "w64_udiv(%s, %s)")
                  | Mod when is_w64 -> bin (if signed64 then sprintf "w64_srem(%s, %s)" else sprintf "w64_urem(%s, %s)")
                  | LT when is_w64 -> bin (if signed64 then sprintf "w64_slt(%s, %s)" else sprintf "w64_ult(%s, %s)")
                  | GT when is_w64 -> bin (fun a b -> if signed64 then $"w64_slt({b}, {a})" else $"w64_ult({b}, {a})")
                  | LTE when is_w64 -> bin (fun a b -> if signed64 then $"Bool.not(w64_slt({b}, {a}))" else $"Bool.not(w64_ult({b}, {a}))")
                  | GTE when is_w64 -> bin (fun a b -> if signed64 then $"Bool.not(w64_slt({a}, {b}))" else $"Bool.not(w64_ult({a}, {b}))")
                  | EQ when is_w64 -> bin (sprintf "w64_equal(%s, %s)")
                  | NEQ when is_w64 -> bin (sprintf "Bool.not(w64_equal(%s, %s))")
                  | BitwiseAnd when is_w64 -> bin (sprintf "w64_and(%s, %s)")
                  | BitwiseOr when is_w64 -> bin (sprintf "w64_or(%s, %s)")
                  | BitwiseXor when is_w64 -> bin (sprintf "w64_xor(%s, %s)")
                  | BitwiseComplement when is_w64 -> unary (sprintf "w64_not(%s)")
                  | ShiftLeft when is_w64 -> bin (sprintf "w64_shl(%s, %s)")
                  | ShiftRight when is_w64 -> bin (if signed64 then sprintf "w64_ashr(%s, %s)" else sprintf "w64_lshr(%s, %s)")
                  | Neg when is_w64 -> unary (sprintf "w64_neg(%s)")
                  | Add -> bin (sprintf "U32.add(%s, %s)")
                  | Sub -> bin (sprintf "U32.sub(%s, %s)")
                  | Mult -> bin (sprintf "U32.mul(%s, %s)")
                  | Div -> bin (if signed l then sprintf "spiral_i32_div(%s, %s)" else sprintf "U32.div(%s, %s)")
                  | Mod -> bin (if signed l then sprintf "spiral_i32_mod(%s, %s)" else sprintf "U32.mod(%s, %s)")
                  | LT -> bin (if signed l then sprintf "spiral_i32_lt(%s, %s)" else sprintf "U32.is_lt(%s, %s)")
                  | LTE -> bin (if signed l then sprintf "spiral_i32_le(%s, %s)" else sprintf "U32.is_le(%s, %s)")
                  | GT -> bin (if signed l then sprintf "spiral_i32_gt(%s, %s)" else sprintf "U32.is_gt(%s, %s)")
                  | GTE -> bin (if signed l then sprintf "spiral_i32_ge(%s, %s)" else sprintf "U32.is_ge(%s, %s)")
                  | EQ -> bin (if is_bool then sprintf "Bool.not(Bool.xor(%s, %s))" elif is_string then sprintf "String.eq(%s, %s)" else sprintf "U32.is_eq(%s, %s)")
                  | NEQ -> bin (if is_bool then sprintf "Bool.xor(%s, %s)" elif is_string then sprintf "Bool.not(String.eq(%s, %s))" else sprintf "U32.is_ne(%s, %s)")
                  | StringIndex -> bin (sprintf "spiral_string_byte_at(%s, %s)")
                  | StaticStringConcat -> bin (sprintf "String.append(%s, %s)")
                  | BoolAnd -> bin (sprintf "Bool.and(%s, %s)")
                  | BoolOr -> bin (sprintf "Bool.or(%s, %s)")
                  | BitwiseAnd -> bin (sprintf "U32.and(%s, %s)")
                  | BitwiseOr -> bin (sprintf "U32.or(%s, %s)")
                  | BitwiseXor -> bin (sprintf "U32.xor(%s, %s)")
                  | BitwiseComplement -> unary (sprintf "U32.not(%s)")
                  | ShiftLeft -> bin (sprintf "U32.shln(%s, U32.to_nat(%s))")
                  | ShiftRight -> bin (if signed l then sprintf "spiral_i32_shift_right(%s, %s)" else sprintf "U32.shrn(%s, U32.to_nat(%s))")
                  | Neg -> unary (sprintf "U32.sub(0, %s)")
                  | _ -> unsupported $"the operation %A{op}"
                let narrowed =
                    match op, (match l with x :: _ -> prim_of x | [] -> None) with
                    | (Add | Sub | Mult | Div | Mod | Neg | BitwiseAnd | BitwiseOr | BitwiseXor | BitwiseComplement | ShiftLeft | ShiftRight), Some t -> narrow_small t expr
                    | _ -> expr
                $"IO.pure({result}, {narrowed})"
            | TyFailwith(_, b) -> $"IO.die({result}, 1, {tup b})"
            | TyToLayout(a, (YLayout(_, Heap))) -> $"IO.pure({result}, {tup a})"
            | TyToLayout(a, (YLayout(_, HeapMutable) as t)) ->
                $"spiral_array_new{array_suffix_of_type (layout_tuple_type t)}({{1 : U32}}, {tup a})"
            | TyLayoutIndexAll(L(i, (YLayout(_, Heap)))) -> $"IO.pure({result}, v{i})"
            | TyLayoutIndexAll(L(i, (YLayout(_, HeapMutable) as t))) ->
                $"spiral_array_get{array_suffix_of_type (layout_tuple_type t)}(v{i}, {layout_cell_slot})"
            | TyLayoutIndexByKey(L(i, (YLayout(_, lay) as t)), key) when lay = Heap || lay = HeapMutable ->
                let fields, fields_by_key, _ = layout_parts t
                let selected =
                    fields_by_key |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None)
                    |> Option.defaultWith (fun () -> raise_codegen_error "Compiler error: The layout has no field with that key.")
                let full_type = layout_tuple_type t
                let name = $"{owner}_field{next_fresh ()}"
                let lines, names = destructure "p" "w" fields.Length
                let position (L(tag, _)) = fields |> Array.findIndex (fun (L(tag', _)) -> tag' = tag)
                let picked = selected |> Array.map (fun v -> names.[position v]) |> tuple_of
                defs.Add($"""@unsafe{"\n"}def {name}(+p: {full_type}) -> IO({result}):{"\n"}{lines |> Array.map (fun x -> x + "\n") |> String.concat ""}  IO.pure({result}, {picked}){"\n"}""")
                match lay with
                | HeapMutable ->
                    let cell = $"{name}_cell"
                    defs.Add($"@unsafe\ndef {cell}(+c: {tyv t}) -> IO({result}):\n  do IO<{result}>:\n    +p : {full_type} <- spiral_array_get{array_suffix_of_type full_type}(c, {layout_cell_slot})\n    {name}(p)\n")
                    $"{cell}(v{i})"
                | _ -> $"{name}(v{i})"
            | TyLayoutMutableSet(L(i, (YLayout(_, HeapMutable) as t)), keys, c) ->
                let fields, _, data = layout_parts t
                let target =
                    List.fold (fun s k ->
                        match s with
                        | DRecord l -> l |> Map.pick (fun (_, k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                        | _ -> raise_codegen_error "Compiler error: Expected a record.") data keys
                    |> data_free_vars
                let full_type = layout_tuple_type t
                let sub_type =
                    match target |> Array.map (fun (L(_,t)) -> tyv t) with
                    | [||] -> "Unit"
                    | [|x|] -> x
                    | xs -> String.concat " & " xs
                let suffix = array_suffix_of_type full_type
                let name = $"{owner}_set{next_fresh ()}"
                let old_lines, old_names = destructure "p" "w" fields.Length
                let new_lines, new_names = destructure "n" "x" target.Length
                let rebuilt =
                    fields |> Array.mapi (fun j (L(tag, _)) ->
                        match target |> Array.tryFindIndex (fun (L(tag', _)) -> tag' = tag) with
                        | Some k -> new_names.[k]
                        | None -> old_names.[j])
                    |> tuple_of
                let body = Array.append old_lines new_lines |> Array.map (fun x -> x + "\n") |> String.concat ""
                defs.Add($"@unsafe\ndef {name}_put(+c: {tyv t}, +p: {full_type}, +n: {sub_type}) -> IO(Unit):\n{body}  spiral_array_set{suffix}(c, {layout_cell_slot}, {rebuilt})\n")
                defs.Add($"@unsafe\ndef {name}(+c: {tyv t}, +n: {sub_type}) -> IO(Unit):\n  do IO<Unit>:\n    +p : {full_type} <- spiral_array_get{suffix}(c, {layout_cell_slot})\n    {name}_put(c, p, n)\n")
                $"{name}(v{i}, {tup c})"
            | TyWhile((JPMethod(a, c), cond_args), body) ->
                let name = $"{owner}_while{next_fresh ()}"
                let captured = scope.ToArray()
                let parameters = captured |> Array.map param |> String.concat ", "
                let arguments = captured |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
                let cond = cond_args |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", " |> sprintf "%s(%s)" method_names.[(method (a, c)).tag]
                let body_text = StringBuilder()
                binds $"{name}_body" "  " "Unit" body_text (ResizeArray captured) body
                defs.Add($"@unsafe\ndef {name}_body({parameters}) -> IO(Unit):\n{body_text}")
                defs.Add($"@unsafe\ndef {name}_step(+c: Bool{params captured}) -> IO(Unit):\n  match c:\n    case True{{}}:\n      do IO<Unit>:\n        {name}_body({arguments})\n        {name}({arguments})\n    case False{{}}:\n      do IO<Unit>:\n        return Unit{{}}\n")
                defs.Add($"@unsafe\ndef {name}({parameters}) -> IO(Unit):\n  do IO<Unit>:\n    +c : Bool <- {cond}\n    {name}_step(c{args captured})\n")
                $"{name}({arguments})"
            | TyMacro a when result <> "" && result <> "Unit" ->
                let text = a |> List.map (function CMText x -> x | CMTerm (x, _) -> tup x | CMType x -> tyv x | CMTypeLit _ -> unsupported "type literals in macros") |> String.concat ""
                $"IO.pure({result}, {text})"
            | TyMacro _ -> unsupported "unit macros"
            | a ->
                let construct = (sprintf "%A" a).Split('(').[0]
                unsupported construct
        and method_memo = lazy (
            let dict = Dictionary(HashIdentity.Structural)
            fun ((jp_body,key) : _ * _) ->
                match dict.TryGetValue((jp_body,key)) with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[(jp_body,key)] <- tag
                    let args = codegenMethodKeyArgs key
                    match codegenMethodBody env backend_nameBend jp_body key with
                    | body, range, name ->
                        method_names.[tag] <- generatedMethodName name tag
                        emit_def method_names.[tag] (rdata_free_vars args) range body
                    tag)
        and method (a, b) : {| tag : int |} = {| tag = method_memo.Force() (a, b) |}
        and closure_memo = lazy (
            let dict = Dictionary(HashIdentity.Structural)
            fun ((jp_body, key & (C(args,_,fun_ty))) : _ * _) ->
                match dict.TryGetValue((jp_body, key)) with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[(jp_body, key)] <- tag
                    match fun_ty with
                    | YFun(domain_ty, range, _) ->
                        match codegenClosureBody env backend_nameBend jp_body key with
                        | domain_args, body, sourceName ->
                            closure_names.[tag] <- generatedClosureName sourceName tag
                            let captured = rdata_free_vars args
                            let domain = data_free_vars domain_args
                            let text = StringBuilder()
                            match domain with
                            | [||] -> ()
                            | [|_|] -> ()
                            | vs -> text.Append($"""  ({vs |> Array.map (fun (L(j,_)) -> $"+v{j}") |> String.concat ", "}) = d{"\n"}""") |> ignore
                            binds closure_names.[tag] "  " (tup_ty range) text (ResizeArray(Array.append captured domain)) body
                            let domain_param =
                                match domain with
                                | [|v|] -> param v
                                | _ -> $"+d: {tup_ty domain_ty}"
                            let captured_params = captured |> Array.map (fun v -> param v + ", ") |> String.concat ""
                            defs.Add($"@unsafe\ndef {closure_names.[tag]}({captured_params}{domain_param}) -> IO({tup_ty range}):\n{text}")
                    | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."
                    tag)
        and closure (a, b) : {| tag : int |} = {| tag = closure_memo.Force() (a, b) |}

        let unitMain =
            match Array.tryLast x with
            | Some (TyLocalReturnOp(_,_,d)) | Some (TyLocalReturnData(d,_)) ->
                match data_term_vars d |> Array.map (function WV(L(_,t)) -> t | WLit l -> YPrim (lit_to_primitive_type l)) with
                | [||] -> true
                | [|YPrim Int32T|] -> false
                | _ -> raise_codegen_error "The return type of main in the Bend backend should be a 32-bit int (or unit)."
            | _ -> true
        emit_def "spiral_main" [||] (if unitMain then YB else YPrim Int32T) x
        let program = StringBuilder()
        let emittedDefs = String.concat "\n" defs
        if emittedDefs.Contains "w64_" then program.Append(bendW64Prelude) |> ignore
        if emittedDefs.Contains "spiral_narrow_i8(" then program.Append("def spiral_narrow_i8(+x: U32) -> U32:\n  U32.sub(U32.xor(U32.and(x, 255), 128), 128)\n\n") |> ignore
        if emittedDefs.Contains "spiral_narrow_i16(" then program.Append("def spiral_narrow_i16(+x: U32) -> U32:\n  U32.sub(U32.xor(U32.and(x, 65535), 32768), 32768)\n\n") |> ignore
        if emittedDefs.Contains "spiral_bool_show(" then program.Append("def spiral_bool_show(+b: Bool) -> String:\n  match b:\n    case True{}:\n      \"true\"\n    case False{}:\n      \"false\"\n\n") |> ignore
        types |> Seq.iter (fun x -> program.Append(x).Append('\n') |> ignore)
        let ordered_defs =
            let header = System.Text.RegularExpressions.Regex(@"^@unsafe\ndef (\w+)\(")
            let parsed = defs |> Seq.map (fun (d : string) -> let m = header.Match d in (if m.Success then m.Groups.[1].Value else ""), d) |> Array.ofSeq
            if parsed |> Array.exists (fun (n, _) -> n = "") then Array.ofSeq defs
            else
                let index = Dictionary<string, int>()
                parsed |> Array.iteri (fun i (n, _) -> index.[n] <- i)
                let word = System.Text.RegularExpressions.Regex(@"\w+")
                let typeKinds = HashSet<string>(types |> Seq.choose (fun (x : string) -> let m = System.Text.RegularExpressions.Regex.Match(x, @"^type (\w+)\b[^\n]* is Type:") in if m.Success then Some m.Groups.[1].Value else None))
                let mentionsTypeKind (d : string) = word.Matches d |> Seq.exists (fun m -> typeKinds.Contains m.Value)
                let mentionsFunctionType (d : string) = d.Split('\n') |> Array.exists (fun (l : string) -> (if l.StartsWith "def " then (match l.LastIndexOf ") -> " with -1 -> l | at -> l.Substring(0, at)) else l).Contains " -> ")
                let edges =
                    parsed |> Array.map (fun (_, (d : string)) ->
                        let body = d.Split('\n') |> Array.skip 2 |> String.concat "\n"
                        word.Matches body |> Seq.choose (fun m -> match index.TryGetValue m.Value with | true, j -> Some j | _ -> None) |> Seq.distinct |> Array.ofSeq)
                let n = parsed.Length
                let order = Array.create n -1
                let low = Array.zeroCreate<int> n
                let on_stack = Array.zeroCreate<bool> n
                let stack = Stack<int>()
                let components = ResizeArray<int list>()
                let counter = ref 0
                let rec strong v =
                    order.[v] <- counter.Value
                    low.[v] <- counter.Value
                    counter.Value <- counter.Value + 1
                    stack.Push v
                    on_stack.[v] <- true
                    for w in edges.[v] do
                        if order.[w] < 0 then
                            strong w
                            low.[v] <- min low.[v] low.[w]
                        elif on_stack.[w] then low.[v] <- min low.[v] order.[w]
                    if low.[v] = order.[v] then
                        let mutable members = []
                        let mutable finished = false
                        while not finished do
                            let w = stack.Pop()
                            on_stack.[w] <- false
                            members <- w :: members
                            if w = v then finished <- true
                        components.Add members
                for v in 0 .. n - 1 do if order.[v] < 0 then strong v
                components
                |> Seq.collect (fun members ->
                    let cyclic = List.length members > 1 || (let v = List.head members in Array.contains v edges.[v])
                    let linearize (d : string) =
                        let declared = System.Text.RegularExpressions.Regex.Matches(d, @"(?<![\w.])\+([A-Za-z_]\w*)") |> Seq.map (fun m -> m.Groups.[1].Value) |> Seq.distinct |> Array.ofSeq
                        declared |> Array.fold (fun (d : string) name ->
                            let uses = System.Text.RegularExpressions.Regex.Matches(d, $@"(?<![\w.]){name}(?!\w)").Count
                            if uses = 2 && not (System.Text.RegularExpressions.Regex.IsMatch(d, $@"(?m)\)\s*=\s*{name}\s*$")) then System.Text.RegularExpressions.Regex.Replace(d, $@"(?<![\w.])\+{name}(?!\w)", name) else d) d
                    let splitParams (ps : string) =
                        let parts = ResizeArray<string>()
                        let cur = System.Text.StringBuilder()
                        let mutable depth = 0
                        for k in 0 .. ps.Length - 1 do
                            let c = ps.[k]
                            if c = ',' && depth = 0 then
                                parts.Add(cur.ToString())
                                cur.Clear() |> ignore
                            else
                                if c = '(' || c = '<' || c = '{' then depth <- depth + 1
                                elif c = ')' || c = '}' || (c = '>' && not (k > 0 && ps.[k - 1] = '-')) then depth <- depth - 1
                                cur.Append c |> ignore
                        parts.Add(cur.ToString())
                        parts.ToArray()
                    let plusTypes (d : string) =
                        [ for l in d.Split('\n') do
                            let t = l.TrimStart()
                            if t.StartsWith "def " then
                                let a = t.IndexOf '('
                                let b = match t.LastIndexOf ") -> " with -1 -> t.LastIndexOf ')' | x -> x
                                if a >= 0 && b > a then
                                    for p in splitParams (t.Substring(a + 1, b - a - 1)) do
                                        let p = p.Trim()
                                        if p.StartsWith "+" then
                                            match p.IndexOf ':' with
                                            | -1 -> yield None
                                            | k -> yield Some (p.Substring(k + 1))
                            elif t.StartsWith "+" then
                                match t.IndexOf " <- ", t.IndexOf ':' with
                                | e, k when e > 0 && k > 0 && k < e -> yield Some (t.Substring(k + 1, e - k - 1))
                                | _ -> yield None
                            elif System.Text.RegularExpressions.Regex.IsMatch(t, @"(^|[(,{ ])\+[A-Za-z_]") then yield None ]
                    let dupNeedsUnsafe (d : string) =
                        plusTypes d |> List.exists (function
                            | None -> true
                            | Some (ty : string) -> ty.Contains " & " || ty.Contains "Chan(" || ty.Contains " -> " || (word.Matches ty |> Seq.exists (fun m -> typeKinds.Contains m.Value)))
                    members |> List.sort |> List.map (fun v -> let d = linearize (snd parsed.[v]) in if cyclic || dupNeedsUnsafe d then d else d.Substring("@unsafe\n".Length)))
                |> Array.ofSeq
        ordered_defs |> Seq.iter (fun x -> program.Append(x).Append('\n') |> ignore)
        let body = program.Append(if unitMain then "def main() -> IO(Unit):\n  do IO<Unit>:\n    spiral_main()\n    return Unit{}\n" else "def main() -> IO(Unit):\n  do IO<Unit>:\n    +code : U32 <- spiral_main()\n    IO.die(Unit, code, \"\")\n").ToString()
        let body = bendPruneIfParameters body
        bendUsedPrelude body + body
    /// ## CodegenGleam

    /// ### backend_nameGleam
    let backend_nameGleam = "Gleam"

    /// ### litGleam
    let gleamFloatText (text : string) =
        match text.IndexOfAny [|'E'; 'e'|] with
        | -1 -> text |> add_dec_point
        | at ->
            let mantissa = text.Substring(0, at)
            let exponent = text.Substring(at + 1).Replace("+", "")
            (if mantissa.Contains "." then mantissa else mantissa + ".0") + "e" + exponent
    let litGleam = function
        | LitInt8 x -> sprintf "%i" x
        | LitInt16 x -> sprintf "%i" x
        | LitInt32 x -> sprintf "%i" x
        | LitInt64 x -> sprintf "%i" x
        | LitUInt8 x -> sprintf "%i" x
        | LitUInt16 x -> sprintf "%i" x
        | LitUInt32 x -> sprintf "%i" x
        | LitUInt64 x -> sprintf "%i" x
        | LitFloat32 x ->
            if x = infinityf then "infinityf"
            elif x = -infinityf then "-infinityf"
            elif Single.IsNaN x then "nanf"
            else x.ToString("R") |> gleamFloatText
        | LitFloat64 x ->
            if x = infinity then "infinity"
            elif x = -infinity then "-infinity"
            elif Double.IsNaN x then "nan"
            else x.ToString("R") |> gleamFloatText
        | LitString x ->
            let strb = StringBuilder(x.Length+2)
            strb.Append '"' |> ignore
            String.iter (function
                | '"' -> strb.Append "\\\""
                | '\b' -> strb.Append @"\b"
                | '\t' -> strb.Append @"\t"
                | '\n' -> strb.Append @"\n"
                | '\r' -> strb.Append @"\r"
                | '\\' -> strb.Append @"\\"
                | x -> strb.Append x
                >> ignore
                ) x
            strb.Append '"' |> ignore
            strb.ToString()
        | LitChar x ->
            match x with
            | '\b' -> @"\b"
            | '\n' -> @"\n"
            | '\t' -> @"\t"
            | '\r' -> @"\r"
            | '\\' -> @"\\"
            | '"' -> "\\\""
            | '\000' -> @"\u{0}"
            | x -> string x
            |> sprintf "\"%s\""
        | LitBool x -> if x then "True" else "False"

    /// ### primGleam
    let primGleam = function
        | Int8T -> "Int"
        | Int16T -> "Int"
        | Int32T -> "Int"
        | Int64T -> "Int"
        | UInt8T -> "Int"
        | UInt16T -> "Int"
        | UInt32T -> "Int"
        | UInt64T -> "Int"
        | Float32T -> "Float"
        | Float64T -> "Float"
        | BoolT -> "Bool"
        | StringT -> "String"
        | CharT -> "String"

    /// ### type_litGleam
    let type_litGleam = function
        | YLit x -> litGleam x
        | YSymbol x -> x
        | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."

    /// ### UnionRecGleam
    type UnionRecGleam = {tag : int; free_vars : Map<int * string, TyV[]>}

    /// ### LayoutRecGleam
    type LayoutRecGleam = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>}

    /// ### MethodRecGleam
    type MethodRecGleam = {tag : int; free_vars : L<Tag,Ty>[]; range : Ty; body : TypedBind[]}

    /// ### ClosureRecGleam
    type ClosureRecGleam = {tag : int; free_vars : L<Tag,Ty>[]; domain_args : TyV[]; range : Ty; body : TypedBind[]}

    /// ### gleamTidy
    let gleamTidy (code : string) =
        let literal = System.Text.RegularExpressions.Regex(@"^(\s*)let (v\d+) = (-?\d+(?:\.\d+)?|""(?:[^""\\]|\\.)*""|[A-Z]\w*)$")
        let tail = System.Text.RegularExpressions.Regex(@"^(\s*)let (v\d+) = ([^{}]+)$")
        let stringLit = System.Text.RegularExpressions.Regex(@"""(?:[^""\\]|\\.)*""")
        let tidy (body : ResizeArray<string>) =
            let mutable changed = true
            while changed do
                changed <- false
                let mutable k = 0
                while k < body.Count do
                    let m = literal.Match body.[k]
                    if m.Success then
                        let var = m.Groups.[2].Value
                        let value = m.Groups.[3].Value
                        let name = System.Text.RegularExpressions.Regex($@"\b{var}\b")
                        let uses = [ for j in 0 .. body.Count - 1 do if j <> k then for u in name.Matches body.[j] do yield j, u.Index ]
                        match uses with
                        | [ j, at ] when not (stringLit.Matches body.[j] |> Seq.exists (fun s -> at >= s.Index && at < s.Index + s.Length))
                                         && not (value.StartsWith "-" && at > 0 && body.[j].[at - 1] = '-') ->
                            body.[j] <- body.[j].Substring(0, at) + value + body.[j].Substring(at + var.Length)
                            body.RemoveAt k
                            changed <- true
                        | _ -> k <- k + 1
                    else k <- k + 1
            let mutable k = 0
            while k + 1 < body.Count do
                let m = tail.Match body.[k]
                if m.Success && body.[k + 1] = m.Groups.[1].Value + m.Groups.[2].Value then
                    body.[k] <- m.Groups.[1].Value + m.Groups.[3].Value
                    body.RemoveAt(k + 1)
                else k <- k + 1
            body
        let lines = code.Replace("\r\n", "\n").Split('\n')
        let out = ResizeArray<string>()
        let mutable i = 0
        while i < lines.Length do
            if (lines.[i].StartsWith "pub fn " || lines.[i].StartsWith "fn ") && lines.[i].TrimEnd().EndsWith "{" then
                let mutable j = i
                while j < lines.Length - 1 && lines.[j] <> "}" do j <- j + 1
                out.AddRange(tidy (ResizeArray(lines.[i .. j])))
                i <- j + 1
            else
                out.Add lines.[i]
                i <- i + 1
        String.concat "\n" out

    /// ### GleamFfi
    /// The Erlang and JavaScript modules a Gleam program's storage externals call, written beside it as <stem>_ffi.erl and
    /// <stem>_ffi.mjs. Arrays and refs keep their state in the process dictionary on Erlang and in plain objects on JavaScript.
    type GleamFfi = NoGleamFfi | GleamStorageFfi of arrays : bool * refs : bool * catches : bool

    let gleamStorageFfiErlang (ffi_module : string) (arrays : bool) (refs : bool) (catches : bool) =
        let exports = [ if arrays then yield! [ "array_new/2"; "array_get/2"; "array_set/3" ]
                        if refs then yield! [ "ref_new/1"; "ref_get/1"; "ref_set/2" ]
                        if catches then yield "try_call/1" ]
        let bodies =
            [ if arrays then yield "array_new(Size, Fill) ->\n    Key = make_ref(),\n    put(Key, array:new(Size, [{fixed, true}, {default, Fill}])),\n    Key.\n\narray_get(Key, I) -> array:get(I, get(Key)).\n\narray_set(Key, I, Value) ->\n    put(Key, array:set(I, Value, get(Key))),\n    nil.\n"
              if refs then yield "ref_new(Value) ->\n    Key = make_ref(),\n    put(Key, Value),\n    Key.\n\nref_get(Key) -> get(Key).\n\nref_set(Key, Value) ->\n    put(Key, Value),\n    nil.\n" ]
        let try_call = "try_call(F) ->\n    try {ok, F(nil)}\n    catch Class:Reason -> {error, unicode:characters_to_binary(io_lib:format(\"~p: ~p\", [Class, Reason]))}\n    end.\n"
        let export_list = String.concat ", " exports
        $"-module({ffi_module}).\n-export([{export_list}]).\n\n" + String.concat "\n" (bodies @ (if catches then [ try_call ] else []))

    let gleamStorageFfiJavaScript (arrays : bool) (refs : bool) =
        (if arrays then "export function array_new(size, fill) { return new Array(size).fill(fill); }\nexport function array_get(store, i) { return store[i]; }\nexport function array_set(store, i, value) { store[i] = value; }\n" else "")
        + (if refs then "export function ref_new(value) { return { value }; }\nexport function ref_get(ref) { return ref.value; }\nexport function ref_set(ref, value) { ref.value = value; }\n" else "")

    /// ### codegenGleam
    let codegenGleam (ffi_module : string) (linked_units : Map<int, LinkedUnit>) (env : PartEvalResult) (x : TypedBind []) =
        let ffi = ref NoGleamFfi
        let method_names = Dictionary<int, string>()
        let closure_names = Dictionary<int, string>()
        let types = ResizeArray()
        let functions = ResizeArray()
        let exports = ResizeArray<string>()
        let closure_of_var = Dictionary<int, int>()
        let export_names = HashSet<string>()
        let exported_record_names = HashSet<string>()
        let exported_union_names = exportedUnionNames env x

        let print is_type show r =
            let s = {text=StringBuilder(); indent=0}
            show s r
            let text = s.text.ToString()
            if is_type then types.Add(text) else functions.Add(text)

        let layout show =
            let dict' = codegenMemoTable HashIdentity.Structural
            let dict = codegenMemoTable HashIdentity.Reference
            let f x : LayoutRecGleam =
                match x with
                | YLayout(x,_) ->
                let x = env.ty_to_data x
                let a, b =
                    match x with
                    | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                    | _ -> data_free_vars x, Map.empty
                {data=x; free_vars=a; free_vars_by_key=b; tag=dict'.Count}
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (3).\nGot: %s{show_ty x}"
            fun x ->
                let mutable dirty = false
                let r = memoize dict (memoize dict' (fun x -> dirty <- true; f x)) x
                if dirty then print true show r
                r

        let union show =
            let dict = codegenMemoTable HashIdentity.Reference
            let f (a : Map<int * string,Ty>) : UnionRecGleam = {free_vars=a |> Map.map (fun _ -> env.ty_to_data >> data_free_vars); tag=dict.Count}
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print true show r
                r

        let jp f show =
            let dict = codegenMemoTable HashIdentity.Structural
            let f x = f (x, dict.Count)
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print false show r
                r

        let args x = x |> Array.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "
        let show_w = function WV (L(i,_)) -> sprintf "v%i" i | WLit a -> litGleam a
        let args' x = x |> data_term_vars |> Array.map show_w |> String.concat ", "

        let global' =
            let has_added = HashSet env.globals
            let preserves_duplicate_fragment (x : string) =
                System.String.IsNullOrEmpty x
                || ((System.Char.IsWhiteSpace x.[0] || x.[0] = '}') && not (x.TrimEnd().Contains '\n'))
            fun x -> if preserves_duplicate_fragment x || has_added.Add(x) then env.globals.Add x

        let externals = System.Collections.Generic.List<string>()
        let portableMath (name : string) (arg : string) =
            global' "import gleam_community/maths"
            $"maths.{name}({arg})"
        let floatResultMath (name : string) (stdlib : string) (arg : string) =
            global' "import gleam/float"
            let decl = $"pub fn spiral_math_{name}(x: Float) -> Float {{\n  case float.{stdlib}(x) {{\n    Ok(value) -> value\n    Error(_) -> panic as \"spiral math: {name} outside the real domain\"\n  }}\n}}"
            if not (externals.Contains decl) then externals.Add decl
            $"spiral_math_{name}({arg})"
        let floatExponential (arg : string) =
            global' "import gleam/float"
            $"float.exponential({arg})"

        let mutable while_id = 0

        let spiralArrays () =
            ffi.Value <- (match ffi.Value with GleamStorageFfi(_, refs, catches) -> GleamStorageFfi(true, refs, catches) | NoGleamFfi -> GleamStorageFfi(true, false, false))
            global' "import gleam/list"
            global' "import gleam/option"
            let decl = "pub type SpiralArrayStore(a)\n\npub type SpiralArray(a) {\n  SpiralArray(store: SpiralArrayStore(option.Option(a)), size: Int)\n}\n\n@external(erlang, \"SPIRAL_FFI\", \"array_new\")\n@external(javascript, \"./SPIRAL_FFI.mjs\", \"array_new\")\npub fn spiral_array_store_new(size: Int, fill: a) -> SpiralArrayStore(a)\n\n@external(erlang, \"SPIRAL_FFI\", \"array_get\")\n@external(javascript, \"./SPIRAL_FFI.mjs\", \"array_get\")\npub fn spiral_array_store_get(store: SpiralArrayStore(a), i: Int) -> a\n\n@external(erlang, \"SPIRAL_FFI\", \"array_set\")\n@external(javascript, \"./SPIRAL_FFI.mjs\", \"array_set\")\npub fn spiral_array_store_set(store: SpiralArrayStore(a), i: Int, value: a) -> Nil\n\npub fn spiral_array_create(size: Int) -> SpiralArray(a) {\n  SpiralArray(store: spiral_array_store_new(size, option.None), size: size)\n}\n\npub fn spiral_array_create_filled(size: Int, value: a) -> SpiralArray(a) {\n  SpiralArray(store: spiral_array_store_new(size, option.Some(value)), size: size)\n}\n\npub fn spiral_array_from_list(values: List(a)) -> SpiralArray(a) {\n  let xs = spiral_array_create(list.length(values))\n  let _ = list.index_map(values, fn(x, i) { spiral_array_set(xs, i, x) })\n  xs\n}\n\npub fn spiral_array_to_list(xs: SpiralArray(a)) -> List(a) {\n  list.repeat(Nil, xs.size) |> list.index_map(fn(_, i) { spiral_array_get(xs, i) })\n}\n\npub fn spiral_array_get(xs: SpiralArray(a), i: Int) -> a {\n  case i >= 0 && i < xs.size {\n    True ->\n      case spiral_array_store_get(xs.store, i) {\n        option.Some(x) -> x\n        option.None -> panic as \"spiral array: read of an element that was never set\"\n      }\n    False -> panic as \"spiral array: index out of bounds\"\n  }\n}\n\npub fn spiral_array_set(xs: SpiralArray(a), i: Int, value: a) -> Nil {\n  case i >= 0 && i < xs.size {\n    True -> spiral_array_store_set(xs.store, i, option.Some(value))\n    False -> panic as \"spiral array: index out of bounds\"\n  }\n}"
            let decl = decl.Replace("SPIRAL_FFI", ffi_module)
            if not (externals.Contains decl) then externals.Add decl
        let spiralRefs () =
            ffi.Value <- (match ffi.Value with GleamStorageFfi(arrays, _, catches) -> GleamStorageFfi(arrays, true, catches) | NoGleamFfi -> GleamStorageFfi(false, true, false))
            let decl = "pub type SpiralRefCell(a)\n\npub type SpiralRef(a) {\n  SpiralRef(cell: SpiralRefCell(a))\n}\n\n@external(erlang, \"SPIRAL_FFI\", \"ref_new\")\n@external(javascript, \"./SPIRAL_FFI.mjs\", \"ref_new\")\npub fn spiral_ref_cell_new(value: a) -> SpiralRefCell(a)\n\n@external(erlang, \"SPIRAL_FFI\", \"ref_get\")\n@external(javascript, \"./SPIRAL_FFI.mjs\", \"ref_get\")\npub fn spiral_ref_cell_get(cell: SpiralRefCell(a)) -> a\n\n@external(erlang, \"SPIRAL_FFI\", \"ref_set\")\n@external(javascript, \"./SPIRAL_FFI.mjs\", \"ref_set\")\npub fn spiral_ref_cell_set(cell: SpiralRefCell(a), value: a) -> Nil\n\npub fn spiral_ref_new(value: a) -> SpiralRef(a) {\n  SpiralRef(cell: spiral_ref_cell_new(value))\n}\n\npub fn spiral_ref_get(reference: SpiralRef(a)) -> a {\n  spiral_ref_cell_get(reference.cell)\n}\n\npub fn spiral_ref_set(reference: SpiralRef(a), value: a) -> Nil {\n  spiral_ref_cell_set(reference.cell, value)\n}"
            let decl = decl.Replace("SPIRAL_FFI", ffi_module)
            if not (externals.Contains decl) then externals.Add decl
        let integerWidth (d : Data) =
            let width = function
                | Int8T -> Some (8, true) | Int16T -> Some (16, true) | Int32T -> Some (32, true) | Int64T -> Some (64, true)
                | UInt8T -> Some (8, false) | UInt16T -> Some (16, false) | UInt32T -> Some (32, false) | UInt64T -> Some (64, false)
                | _ -> None
            match d with
            | DV(L(_,YPrim t)) -> width t
            | DLit l -> width (lit_to_primitive_type l)
            | _ -> None
        let spiralIntegers () =
            global' "import gleam/int"
            let decl = "pub fn spiral_wrap_signed(value: Int, bits: Int) -> Int {\n  let half = int.bitwise_shift_left(1, bits - 1)\n  int.bitwise_and(value + half, int.bitwise_shift_left(1, bits) - 1) - half\n}\n\npub fn spiral_wrap_unsigned(value: Int, bits: Int) -> Int {\n  int.bitwise_and(value, int.bitwise_shift_left(1, bits) - 1)\n}"
            if not (externals.Contains decl) then externals.Add decl
        let spiralIntPower () =
            let decl = "pub fn spiral_int_power(base: Int, exponent: Int) -> Int {\n  case exponent <= 0 {\n    True -> 1\n    False -> base * spiral_int_power(base, exponent - 1)\n  }\n}"
            if not (externals.Contains decl) then externals.Add decl
        let spiralFloatPower () =
            global' "import gleam/float"
            let decl = "pub fn spiral_math_pow(base: Float, exponent: Float) -> Float {\n  case float.power(base, exponent) {\n    Ok(power) -> power\n    Error(_) -> panic as \"spiral math: pow outside the real domain\"\n  }\n}"
            if not (externals.Contains decl) then externals.Add decl
        let wrapInteger (d : Data) (text : string) =
            match integerWidth d with
            | Some (bits, true) -> spiralIntegers (); $"spiral_wrap_signed({text}, {bits})"
            | Some (bits, false) -> spiralIntegers (); $"spiral_wrap_unsigned({text}, {bits})"
            | None -> text
        let spiralStrings () =
            global' "import gleam/bit_array"
            global' "import gleam/string"
            let decl = "pub fn spiral_string_length(text: String) -> Int {\n  bit_array.byte_size(bit_array.from_string(text))\n}"
            if not (externals.Contains decl) then externals.Add decl
        let spiralStringSlicing () =
            spiralStrings ()
            let decl = "@external(erlang, \"erlang\", \"halt\")\n@external(javascript, \"node:process\", \"exit\")\npub fn spiral_halt(code: Int) -> a\n\npub fn spiral_string_index(text: String, index: Int) -> String {\n  case bit_array.slice(bit_array.from_string(text), index, 1) {\n    Ok(<<byte>>) ->\n      case string.utf_codepoint(byte) {\n        Ok(codepoint) -> string.from_utf_codepoints([codepoint])\n        Error(_) -> panic as \"spiral string index: not a single-byte character\"\n      }\n    _ -> panic as \"spiral string index: out of range\"\n  }\n}\n\n@external(erlang, \"gleam_stdlib\", \"identity\")\nfn spiral_string_of_checked_bytes(bytes: BitArray) -> String {\n  case bit_array.to_string(bytes) {\n    Ok(text) -> text\n    Error(_) -> panic as \"spiral string slice: splits a character\"\n  }\n}\n\nfn spiral_string_starts_character(bytes: BitArray, at: Int) -> Bool {\n  case bit_array.slice(bytes, at, 1) {\n    Ok(<<lead>>) -> lead < 128 || lead >= 192\n    _ -> True\n  }\n}\n\npub fn spiral_string_slice(text: String, from: Int, to: Int) -> String {\n  let bytes = bit_array.from_string(text)\n  let length = bit_array.byte_size(bytes)\n  case from < 0 || from > length || to < from - 1 || to >= length {\n    True -> panic as \"spiral string slice: out of range\"\n    False ->\n      case to < from {\n        True -> \"\"\n        False ->\n          case spiral_string_starts_character(bytes, from) && spiral_string_starts_character(bytes, to + 1) {\n            False -> panic as \"spiral string slice: splits a character\"\n            True ->\n              case bit_array.slice(bytes, from, to - from + 1) {\n                Ok(part) -> spiral_string_of_checked_bytes(part)\n                Error(_) -> panic as \"spiral string slice: out of range\"\n              }\n          }\n      }\n  }\n}"
            if not (externals.Contains decl) then externals.Add decl
        let rec tyv x =
            match x with
            | YUnion a ->
                let a = a.Item
                match a.layout with
                | UHeap -> sprintf "Uh%i" (uheap a.cases).tag
                | UStack -> sprintf "Us%i" (ustack a.cases).tag
            | YLayout(_,lay) as a ->
                match lay with
                | Heap -> sprintf "Heap%i" (heap a).tag
                | HeapMutable -> spiralRefs (); sprintf "SpiralRef(Mut%i)" (mut a).tag
                | StackMutable -> raise_codegen_error "Compiler error: The F# backend doesn't support stack mutable layout types."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
            | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameGleam then Some v else None) with
                | Some x -> tup_ty x
                | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{backend_nameGleam}' field."
            | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_litGleam a) |> String.concat ""
            | YPrim a -> primGleam a
            | YArray a ->
                spiralArrays ()
                sprintf "SpiralArray(%s)" (tup_ty a)
            | YFun(a,b,FT_Vanilla) -> sprintf "fn(%s) -> %s" (tup_ty a) (tup_ty b)
            | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
            | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
            | a -> raise_codegen_error $"Type not supported in the codegen.\nGot: %A{a}"
        and args_tys x = x |> Array.map (fun (L(i,t)) -> sprintf "v%i: %s" i (tup_ty t)) |> String.concat ", "
        and binds (s : CodegenEnv) (x : TypedBind []) =
            Array.iter (function
                | TyLet(d,trace,a) -> try op s (Some d) a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) -> try op s None a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) -> try line s (tup d) with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) x
        and tup x =
            match data_term_vars x with
            | [||] -> "Nil"
            | [|x|] -> show_w x
            | x -> $"""#({x |> Array.map show_w |> String.concat ", "})"""
        and tup_ty x =
            match env.ty_to_data x |> data_free_vars |> Array.map (fun (L(_,x)) -> tyv x) with
            | [||] -> "Nil"
            | [|x|] -> x
            | x -> String.concat ", " x |> sprintf "#(%s)"
        and op s d a =
            let a'' = a
            let jp (a, b) =
                let a' = a
                let b' = b
                let args = args b
                match a with
                | JPMethod(a,b) -> sprintf "%s(%s)" method_names.[(method (a,b)).tag] args
                | JPClosure (a, b) ->
                    let name = closure_names.[(closure (a, b)).tag]
                    let fv =
                        match args with
                        | "" -> "Nil"
                        | xs -> sprintf "#(%s)" xs
                    sprintf "%s(%s)" name fv
            let free_vars do_annot x =
                let f (L(i,t)) = if do_annot then sprintf "v%i: %s" i (tyv t) else sprintf "v%i" i
                match data_free_vars x with
                | [||] -> "Nil"
                | [|x|] -> f x
                | x -> Array.map f x |> String.concat ", " |> sprintf "#(%s)"
            let simple x =
                match d with
                | None -> x
                | Some d ->
                    match free_vars false d |> SpiralSm.trim with
                    | "Nil" -> x
                    | d -> sprintf "let %s = %s" d x
                |> line s
            let complex f =
                match d with
                | None -> f s : unit
                | Some d ->
                    match free_vars false d |> SpiralSm.trim with
                    | "Nil" -> f s
                    | d ->
                        line s (sprintf "let %s =" d)
                        f (indent s)
            let layout_vars a =
                let f i x =
                    match x with
                    | WV(L(i',_)) -> sprintf "l%i: v%i" i i'
                    | WLit x -> sprintf "l%i: %s" i (litGleam x)
                a |> data_term_vars |> Array.mapi f |> String.concat ", "
            let arm (s : CodegenEnv) (head : string) (render : CodegenEnv -> unit) =
                let body = indent { s with text = StringBuilder() }
                render body
                let rendered = body.text.ToString()
                match rendered.Split('\n') |> Array.filter (fun row -> row.Trim() <> "") with
                | [| single |] when not (single.TrimStart().StartsWith "let ") -> line s $"{head} -> {single.Trim()}"
                | _ ->
                    line s $"{head} -> {{"
                    s.text.Append(rendered) |> ignore
                    line s "}"
            let layout_index_from (source : string) x =
                x |> Array.map (fun (L(i',_)) -> sprintf "%s.l%i" source i')
                |> function [||] -> () | [|x|] -> simple x | l -> String.concat ", " l |> sprintf "#(%s)" |> simple
            let length (a,b) =
                spiralStrings ()
                sprintf "spiral_string_length(%s)" (tup b)
                |> simple

            match a with
            | TyMacro a -> a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup x) | CMType x -> tup_ty x | CMTypeLit x -> type_litGleam x) |> String.concat "" |> simple
            | TySizeOf t -> simple $"0"
            | TyIf(cond,tr,fl) ->
                complex <| fun s ->
                line s (sprintf "case %s {" (tup cond))
                arm (indent s) "True" (fun b -> binds b tr)
                arm (indent s) "False" (fun b ->
                    match fl with
                    | [|TyLocalReturnData(DB,_)|] -> line b "Nil"
                    | _ -> binds b fl)
                line s "}"
            | TyJoinPoint(JPClosure(a,c) as a',args) ->
                match d with
                | Some (DV(L(i,_))) when args.Length = 0 -> closure_of_var.[i] <- (closure (a,c)).tag
                | _ -> ()
                simple (jp (a', args))
            | TyJoinPoint(a,args) -> simple (jp (a, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The Gleam backend does not support nesting other backends."
            | TyWhile(a, b) ->
                let fv x = x |> data_free_vars |> Set
                let rec fv_binds (x : TypedBind []) =
                    Array.foldBack (fun k vs ->
                        match k with
                        | TyLet(d,_,o) -> vs + fv_op o - fv d
                        | TyLocalReturnOp(_,o,_) -> vs + fv_op o
                        | TyLocalReturnData(d,_) -> vs + fv d
                        ) x Set.empty
                and fv_op (x : TypedOp) : TyV Set =
                    match x with
                    | TySizeOf _ | TyBackend _ -> Set.empty
                    | TyMacro l -> List.fold (fun s -> function CMTerm (d,_) -> s + fv d | _ -> s) Set.empty l
                    | TyArrayLiteral(_,l) | TyOp(_,l) -> List.fold (fun s x -> s + fv x) Set.empty l
                    | TyToLayout(x,_) | TyUnionBox(_,x,_) | TyFailwith(_,x) | TyConv(_,x) | TyArrayCreate(_,x) | TyArrayLength(_,x) | TyStringLength(_,x) -> fv x
                    | TyWhile(cond,body) -> Set (snd cond) + fv_binds body
                    | TyDo body | TyIndent body -> fv_binds body
                    | TyLayoutIndexAll(i) | TyLayoutIndexByKey(i,_) -> Set.singleton i
                    | TyApply(i,d) | TyLayoutMutableSet(i,_,d) -> Set.singleton i + fv d
                    | TyJoinPoint x -> Set (snd x)
                    | TyIf(cond,tr,fl) -> fv cond + fv_binds tr + fv_binds fl
                    | TyUnionUnbox(vs,_,on_succs,on_fail) ->
                        let on_fail = match on_fail with Some x -> fv_binds x | None -> Set.empty
                        Map.fold (fun s _ (lets,body) -> s + (fv_binds body - List.fold (fun s x -> s + fv x) Set.empty lets)) (Set vs + on_fail) on_succs
                    | TyIntSwitch(tag,on_succs,on_fail) -> Array.fold (fun s body -> s + fv_binds body) (Set.singleton tag + fv_binds on_fail) on_succs
                let rec sets_binds (x : TypedBind []) =
                    x |> Array.fold (fun s -> function TyLet(_,_,o) | TyLocalReturnOp(_,o,_) -> s + sets_op o | TyLocalReturnData _ -> s) Set.empty
                and sets_op (x : TypedOp) : TyV Set =
                    match x with
                    | TyLayoutMutableSet(i,_,_) | TyOp(ArrayIndexSet, DV i :: _) -> Set.singleton i
                    | TyWhile(_,body) | TyDo body | TyIndent body -> sets_binds body
                    | TyIf(_,tr,fl) -> sets_binds tr + sets_binds fl
                    | TyUnionUnbox(_,_,on_succs,on_fail) ->
                        Map.fold (fun s _ (_,body) -> s + sets_binds body) (match on_fail with Some x -> sets_binds x | None -> Set.empty) on_succs
                    | TyIntSwitch(_,on_succs,on_fail) -> Array.fold (fun s body -> s + sets_binds body) (sets_binds on_fail) on_succs
                    | _ -> Set.empty
                let body =
                    match Array.tryLast b with
                    | Some (TyLocalReturnData _) -> Array.take (b.Length - 1) b
                    | _ -> b
                let vars = Set (snd a) + fv_binds b
                let names (x : TyV seq) = x |> Seq.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "
                let ps = names vars
                let ret =
                    match Set.intersect (sets_binds b) vars |> Set.toArray with
                    | [||] -> "Nil"
                    | [|x|] -> names [x]
                    | x -> $"#({names x})"
                let id = while_id
                while_id <- while_id + 1
                print
                    false
                    (fun s id' ->
                        line s $"loop{id'} ({args_tys (Set.toArray vars)}) {{"
                        line (indent s) $"case {jp a} {{"
                        line (indent (indent s)) "True -> {"
                        binds (indent (indent (indent s))) body
                        line (indent (indent (indent s))) $"loop{id'}({ps})"
                        line (indent (indent s)) "}"
                        line (indent (indent s)) $"False -> {ret}"
                        line (indent s) "}"
                        line s "}"
                    )
                    id
                line s (if ret = "Nil" then $"let _ = loop{id}({ps})" else $"let {ret} = loop{id}({ps})")

            | TyDo a ->
                complex <| fun s ->
                line s "{"
                binds (indent s) a
                line s "}"
            | TyIndent a ->
                complex <| fun s ->
                binds (indent s) a
            | TyIntSwitch(L(i,_),on_succ,on_fail) ->
                complex <| fun s ->
                line s (sprintf "case v%i {" i)
                Array.iteri (fun i x ->
                    arm (indent s) (sprintf "%i" i) (fun b -> binds b x)
                    ) on_succ
                arm (indent s) "_" (fun b -> binds b on_fail)
            | TyUnionUnbox(is,x,on_succs,on_fail) ->
                complex <| fun s ->
                let case_tags = x.Item.tags
                line s ($"""case {is |> List.map (fun (L(i,_)) -> $"v{i}") |> String.concat ","}  {{""")
                let prefix =
                    let x = x.Item
                    match x.layout with
                    | UHeap -> sprintf "Uh%i" (uheap x.cases).tag
                    | UStack -> sprintf "Us%i" (ustack x.cases).tag
                Map.iter (fun k (a,b) ->
                    let i = x.Item.cases |> Seq.tryFindIndex (fun (KeyValue ((_, k'), _)) -> k' = UnionTagIdOps.text k) |> Option.defaultWith (fun () -> case_tags.[k])
                    let cases =
                        a |> List.map (fun a ->
                            match data_free_vars a with
                            | [||] -> ""
                            | x -> sprintf "(%s)" (args x)
                            |> sprintf "%s%s" (gleamCaseName prefix x.Item.cases i)
                            )
                        |> String.concat ","
                    arm (indent s) cases (fun body -> binds body b)
                    ) on_succs
                let covers_every_case = is.Length = 1 && Map.count on_succs = Map.count x.Item.cases
                let wildcard = is |> List.map (fun _ -> "_") |> String.concat ","
                match on_fail with
                | Some on_fail ->
                    arm (indent s) wildcard (fun b -> binds b on_fail)
                | None when covers_every_case -> ()
                | None -> line (indent s) $"{wildcard} -> panic as \"spiral: union case ruled out by partial evaluation\""
                line s "}"
            | TyUnionBox(a,b,c) ->
                let c = c.Item
                let i = c.cases |> Seq.tryFindIndex (fun (KeyValue ((_, k), _)) -> k = UnionTagIdOps.text a) |> Option.defaultWith (fun () -> c.tags.[a])
                let vars =
                    match data_term_vars b with
                    | [||] -> ""
                    | x -> Array.map show_w x |> String.concat ", " |> sprintf "(%s)"
                match c.layout with
                | UHeap -> sprintf "%s%s" (gleamCaseName (sprintf "Uh%i" (uheap c.cases).tag) c.cases i) vars
                | UStack -> sprintf "%s%s" (gleamCaseName (sprintf "Us%i" (ustack c.cases).tag) c.cases i) vars
                |> simple
            | TyToLayout(a,b) ->
                let a = layout_vars a
                match b with
                | YLayout(_,layout) ->
                    match layout with
                    | Heap -> if a = "" then sprintf "Heap%i()" (heap b).tag else sprintf "Heap%i(%s)" (heap b).tag a
                    | HeapMutable -> spiralRefs (); if a = "" then sprintf "spiral_ref_new(Mut%i())" (mut b).tag else sprintf "spiral_ref_new(Mut%i(%s))" (mut b).tag a
                    | StackMutable -> raise_codegen_error "The F# backend doesn't support stack mutable layout types."
                    | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (4).\nGot: %s{show_ty b}"
                |> simple
            | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                match lay with
                | Heap -> (heap a).free_vars |> layout_index_from $"v{i}"
                | HeapMutable -> (mut a).free_vars |> layout_index_from $"spiral_ref_get(v{i})"
                | StackMutable -> raise_codegen_error "The Gleam backend doesn't support indexing into stack mutable layout types."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
            | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                let source, record =
                    match lay with
                    | Heap -> $"v{i}", heap a
                    | HeapMutable -> $"spiral_ref_get(v{i})", mut a
                    | StackMutable -> raise_codegen_error "The Gleam backend doesn't support indexing into stack mutable layout types."
                    | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                record.free_vars_by_key
                |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None)
                |> Option.iter (layout_index_from source)
            | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
            | TyLayoutMutableSet(L(i,t),b,c) ->
                let a = List.fold (fun s k ->
                    match s with
                    | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                    | _ -> raise_codegen_error "Compiler error: Expected a record.") (mut t).data b
                let updates = Array.map2 (fun (L(i',_)) b -> sprintf "l%i: %s" i' (show_w b)) (data_free_vars a) (data_term_vars c) |> String.concat ", "
                if (data_free_vars a).Length = (mut t).free_vars.Length then line s (sprintf "spiral_ref_set(v%i, Mut%i(%s))" i (mut t).tag updates)
                else line s (sprintf "spiral_ref_set(v%i, Mut%i(..spiral_ref_get(v%i), %s))" i (mut t).tag i updates)
            | TyArrayLiteral(a,b) ->
                spiralArrays ()
                $"""spiral_array_from_list([ {List.map tup b |> String.concat ", "} ])"""
                |> simple
            | TyArrayCreate(a,b) ->
                spiralArrays ()
                let gleamPrimZero = function
                    | Float32T | Float64T -> "0.0"
                    | BoolT -> "False"
                    | StringT -> "\"\""
                    | CharT -> "\"\\u{0000}\""
                    | _ -> "0"
                match env.ty_to_data a |> data_free_vars with
                | [|L(_, YPrim p)|] -> $"spiral_array_create_filled({tup b}, {gleamPrimZero p})" |> simple
                | _ -> $"spiral_array_create({tup b})" |> simple
            | TyArrayLength(a,b) ->
                spiralArrays ()
                $"{tup b}.size" |> simple
            | TyStringLength(a,b) -> length (a,b)
            | TyFailwith(a,b) ->
                match d with
                | Some d when (free_vars false d |> SpiralSm.trim) <> "Nil" -> line s $"let {free_vars false d |> SpiralSm.trim}: {tup_ty a} = panic as {tup b}"
                | _ -> simple (sprintf "panic as %s" (tup b))
            | TyConv(a,b) ->
                let t = tyv a |> SpiralSm.to_lower
                let d = tup b
                let source =
                    match b with
                    | DV(L(_,YPrim p)) -> tyv (YPrim p) |> SpiralSm.to_lower
                    | DLit l -> tyv (YPrim (lit_to_primitive_type l)) |> SpiralSm.to_lower
                    | _ -> ""
                (match t, source with
                 | "int", "int" -> wrapInteger (DV(L(0, a))) d
                 | "int", "float" ->
                     global' $"import gleam/float"
                     $"float.truncate({d})"
                 | "int", "bool" -> $"case {d} {{ True -> 1 False -> 0 }}"
                 | "float", "float" -> d
                 | "float", "int" ->
                     global' $"import gleam/int"
                     $"int.to_float({d})"
                 | "float", "bool" -> $"case {d} {{ True -> 1.0 False -> 0.0 }}"
                 | "bool", _ -> $"{d} > 0"
                 | "int", _ ->
                     global' $"import gleam/float"
                     $"float.truncate({d})"
                 | "float", _ ->
                     global' $"import gleam/int"
                     $"int.to_float({d})"
                 | _ -> $"{d} // spiral_compiler.TyConv / t: {t}")
                |> simple
            | TyApply (L(i, t), b) ->
                let arg_code = tup b
                let call =
                  match t with
                  | YFun (domain, _, FT_Vanilla) ->
                      let domain_is_nil =
                        env.ty_to_data domain |> data_free_vars |> Array.isEmpty
                      if arg_code |> SpiralSm.trim = "Nil" then
                        if domain_is_nil then sprintf "v%i(Nil)" i else sprintf "v%i " i
                      else
                        if domain_is_nil then $"v%i{i}({arg_code}(Nil)) "
                        else sprintf "v%i(%s)" i arg_code
                  | _ ->
                      sprintf "v%i(%s)" i arg_code
                call
                |> fun code ->
                    call
                |> simple
            | TyOp(Export, [DLit (LitString name); DV(L(i,YFun(domain,range,_)))]) ->
                if not (export_names.Add name) then raise_codegen_error $"Duplicate export: {name}."
                let tag =
                    match closure_of_var.TryGetValue i with
                    | true, tag -> tag
                    | _ -> raise_codegen_error $"Compiler error: the exported function {name} is not a closure without captures."
                let parameters = env.ty_to_data domain |> data_free_vars
                let prim_record (t : Ty) =
                    match t with
                    | YNominal n ->
                        match env.nominal_apply t with
                        | YRecord fields when not fields.IsEmpty && fields |> Map.forall (fun _ t -> match t with YPrim _ -> true | _ -> false) ->
                            Some (ExternCalls.pascal (n.node.name |> String.map (fun c -> if System.Char.IsLetterOrDigit c || c = '_' then c else '_')), fields)
                        | _ -> None
                    | _ -> None
                let declare_record (record_name : string, fields : Map<int * string, Ty>) =
                    if exported_record_names.Add record_name then
                        let members = fields |> Map.toArray |> Array.map (fun ((_,k),t) -> $"{k}: {tyv t}") |> String.concat ", "
                        exports.Insert(0, $"pub type {record_name} {{\n  {record_name}({members})\n}}\n")
                let decl, call =
                    match prim_record domain with
                    | Some (record_name, fields) ->
                        declare_record (record_name, fields)
                        let reads = fields |> Map.toArray |> Array.map (fun ((_,k),_) -> $"v.{k}")
                        $"v: {record_name}", (match reads with [|one|] -> one | many -> many |> String.concat ", " |> sprintf "#(%s)")
                    | None ->
                        parameters |> Array.map (fun (L(k,t)) -> sprintf "v%i: %s" k (tyv t)) |> String.concat ", ",
                        (match parameters with
                         | [||] -> "Nil"
                         | [|L(k,_)|] -> sprintf "v%i" k
                         | ps -> ps |> Array.map (fun (L(k,_)) -> sprintf "v%i" k) |> String.concat ", " |> sprintf "#(%s)")
                match prim_record range with
                | Some (record_name, fields) ->
                    declare_record (record_name, fields)
                    let parts = fields |> Map.toArray |> Array.mapi (fun j ((_,k),_) -> k, $"f{j}")
                    let binding = if parts.Length = 1 then snd parts.[0] else parts |> Array.map snd |> String.concat ", " |> sprintf "#(%s)"
                    let build = parts |> Array.map (fun (k, f) -> $"{k}: {f}") |> String.concat ", "
                    exports.Add($"pub fn {name}({decl}) -> {record_name} {{\n  let {binding} = {closure_names.[tag]}(Nil)({call})\n  {record_name}({build})\n}}\n")
                | None ->
                    exports.Add($"pub fn {name}({decl}) -> {tup_ty range} {{\n  {closure_names.[tag]}(Nil)({call})\n}}\n")
                match d with
                | None -> line s "let _ = Nil"
                | Some bound ->
                    match free_vars false bound |> SpiralSm.trim with
                    | "Nil" -> line s "let _ = Nil"
                    | bound_name -> line s (sprintf "let %s = Nil" bound_name)
            | TyOp(Global, [DLit (LitString x)]) when x.Contains "SPIRAL_FFI" ->
                if x.Contains "\"try_call\"" then ffi.Value <- (match ffi.Value with GleamStorageFfi(arrays, refs, _) -> GleamStorageFfi(arrays, refs, true) | NoGleamFfi -> GleamStorageFfi(false, false, true))
                env.globals.Remove x |> ignore
                global' (x.Replace("SPIRAL_FFI", ffi_module))
            | TyOp(Global, [DLit (LitString x)]) -> global' x
            | TyOp(op,l) ->
                let dot = function
                    | DV(L(_,YPrim Float32T)) | DLit(LitFloat32 _)
                    | DV(L(_,YPrim Float64T)) | DLit(LitFloat64 _) -> "."
                    | _ -> ""
                match op, l with
                | Dyn,[a] -> tup a
                | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                | StaticStringConcat, [a;b] -> sprintf "{ %s } <> { %s }" (tup a) (tup b)
                | StringIndex, [a;b] ->
                    spiralStringSlicing ()
                    sprintf "spiral_string_index(%s, %s)" (tup a) (tup b)
                | StringSlice, [a;b;c] ->
                    spiralStringSlicing ()
                    sprintf "spiral_string_slice(%s, %s, %s)" (tup a) (tup b) (tup c)
                | ArrayIndex, [a;b] ->
                    spiralArrays ()
                    $"spiral_array_get({tup a}, {tup b})"
                | ArrayIndexSet, [a;b;c] ->
                    spiralArrays ()
                    $"spiral_array_set({tup a}, {tup b}, {tup c})"

                | Add, [a;b] -> wrapInteger a $"{a |> tup} +{a |> dot} {b |> tup}"
                | Sub, [a;b] -> wrapInteger a $"{a |> tup} -{a |> dot} {b |> tup}"
                | Mult, [a;b] -> wrapInteger a $"{a |> tup} *{a |> dot} {b |> tup}"
                | Div, [a;b] -> $"{a |> tup} /{a |> dot} {b |> tup}"
                | Mod, [a;b] when dot a = "." ->
                    global' "import gleam/float"
                    global' "fn spiral_fmod(a: Float, b: Float) -> Float {\n  let q = a /. b\n  let t = case q >=. 0.0 {\n    True -> float.floor(q)\n    False -> float.ceiling(q)\n  }\n  a -. t *. b\n}"
                    $"spiral_fmod({tup a}, {tup b})"
                | Mod, [a;b] -> $"{a |> tup} %% {b |> tup}"
                | Pow, [a;b] -> if dot a = "." then (spiralFloatPower (); $"spiral_math_pow({tup a}, {tup b})") else (spiralIntPower (); wrapInteger a $"spiral_int_power({tup a}, {tup b})")
                | LT, [(DV(L(_,YPrim (StringT | CharT))) | DLit(LitString _ | LitChar _)) as a;b] -> global' "import gleam/string"; global' "import gleam/order"; $"string.compare({tup a}, {tup b}) == order.Lt"
                | LTE, [(DV(L(_,YPrim (StringT | CharT))) | DLit(LitString _ | LitChar _)) as a;b] -> global' "import gleam/string"; global' "import gleam/order"; $"string.compare({tup a}, {tup b}) != order.Gt"
                | GT, [(DV(L(_,YPrim (StringT | CharT))) | DLit(LitString _ | LitChar _)) as a;b] -> global' "import gleam/string"; global' "import gleam/order"; $"string.compare({tup a}, {tup b}) == order.Gt"
                | GTE, [(DV(L(_,YPrim (StringT | CharT))) | DLit(LitString _ | LitChar _)) as a;b] -> global' "import gleam/string"; global' "import gleam/order"; $"string.compare({tup a}, {tup b}) != order.Lt"
                | LT, [a;b] -> $"{a |> tup} <{a |> dot} {b |> tup}"
                | LTE, [a;b] -> $"{a |> tup} <={a |> dot} {b |> tup}"
                | EQ, [a;b] -> sprintf "%s == %s" (tup a) (tup b)
                | NEQ, [a;b] -> sprintf "%s != %s" (tup a) (tup b)
                | GT, [a;b] -> $"{a |> tup} >{a |> dot} {b |> tup}"
                | GTE, [a;b] -> $"{a |> tup} >={a |> dot} {b |> tup}"
                | BoolAnd, [a;b] -> sprintf "%s && %s" (tup a) (tup b)
                | BoolOr, [a;b] -> sprintf "%s || %s" (tup a) (tup b)
                | BitwiseAnd, [a;b] -> spiralIntegers (); $"int.bitwise_and({tup a}, {tup b})"
                | BitwiseOr, [a;b] -> spiralIntegers (); $"int.bitwise_or({tup a}, {tup b})"
                | BitwiseXor, [a;b] -> spiralIntegers (); $"int.bitwise_exclusive_or({tup a}, {tup b})"
                | BitwiseComplement, [a] -> spiralIntegers (); wrapInteger a $"int.bitwise_not({tup a})"

                | ShiftLeft, [a;b] -> spiralIntegers (); wrapInteger a $"int.bitwise_shift_left({tup a}, {tup b})"
                | ShiftRight, [a;b] -> spiralIntegers (); $"int.bitwise_shift_right({tup a}, {tup b})"

                | Neg, [x] -> if dot x = "." then $"0.0 -. {tup x}" else wrapInteger x $"0 - {tup x}"
                | Log, [x] -> floatResultMath "log" "logarithm" (tup x)
                | Exp, [x] -> floatExponential (tup x)
                | Tanh, [x] -> portableMath "tanh" (tup x)
                | Sqrt, [x] -> floatResultMath "sqrt" "square_root" (tup x)
                | Sin, [x] -> portableMath "sin" (tup x)
                | Cos, [x] -> portableMath "cos" (tup x)
                | PrimToString, [x] ->
                    match x with
                    | DLit(LitBool _) | DV(L(_,YPrim BoolT)) -> sprintf "case %s { True -> \"true\" False -> \"false\" }" (tup x)
                    | DLit(LitChar _) | DV(L(_,YPrim CharT)) -> tup x
                    | _ -> global' "import gleam/int"; sprintf "int.to_string(%s)" (tup x)
                | NanIs, [x] -> "False"
                | UnionTag, [DV(L(i,YUnion h))] ->
                    let h = h.Item
                    let union_rec, ty =
                        match h.layout with
                        | UHeap -> let u = uheap h.cases in u, sprintf "Uh%i" u.tag
                        | UStack -> let u = ustack h.cases in u, sprintf "Us%i" u.tag
                    let arms =
                        union_rec.free_vars
                        |> Seq.mapi (fun position (KeyValue ((tag, _), fields)) ->
                            let pattern = gleamCaseName ty union_rec.free_vars position
                            match fields with
                            | [||] -> $"{pattern} -> {tag}"
                            | _ -> $"{pattern}(..) -> {tag}")
                        |> String.concat " "
                    $"case v{i} {{ {arms} }}"
                | Printf, [DLit (LitString fmt); b] ->
                    global' "import gleam/io"
                    let pieces =
                        printf_pieces fmt (data_term_vars b) |> List.map (function
                            | Choice1Of2 t -> litGleam (LitString t)
                            | Choice2Of2 ('s', a) -> show_w a
                            | Choice2Of2 (_, a) -> global' "import gleam/int"; $"int.to_string({show_w a})")
                    match pieces with
                    | [] -> "Nil"
                    | l -> String.concat " <> " l |> sprintf "io.print(%s)"
                | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported" op l.Length
                |> simple
        and heap : _ -> LayoutRecGleam = layout (fun s x ->
            let b = x.free_vars |> Array.map (fun (L(i,t)) -> sprintf "l%i : %s" i (tyv t)) |> String.concat ", "
            if b = "" then line s (sprintf "Heap%i { Heap%i() }" x.tag x.tag)
            else line s (sprintf "Heap%i { Heap%i(%s) }" x.tag x.tag b)
            )
        and mut : _ -> LayoutRecGleam = layout (fun s x ->
            let b = x.free_vars |> Array.map (fun (L(i,t)) -> sprintf "l%i : %s" i (tyv t)) |> String.concat ", "
            if b = "" then line s (sprintf "Mut%i { Mut%i() }" x.tag x.tag)
            else line s (sprintf "Mut%i { Mut%i(%s) }" x.tag x.tag b)
            )
        and uheap : _ -> UnionRecGleam = union (fun s x ->
            line s (sprintf "Uh%i {" x.tag)
            let mutable i = 0
            x.free_vars |> Map.iter (fun _ a ->
                match a with
                | [||] -> line (indent s) (gleamCaseName (sprintf "Uh%i" x.tag) x.free_vars i)
                | a -> line (indent s) (sprintf "%s(%s)" (gleamCaseName (sprintf "Uh%i" x.tag) x.free_vars i) (a |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat ", "))
                i <- i+1
                )
            line s "}"
            )
        and ustack : _ -> UnionRecGleam = union (fun s x ->
            line s (sprintf "Us%i {" x.tag)
            let mutable i = 0
            x.free_vars |> Map.iter (fun _ a ->
                match a with
                | [||] -> line (indent s) (gleamCaseName (sprintf "Us%i" x.tag) x.free_vars i)
                | a -> line (indent s) (sprintf "%s(%s)" (gleamCaseName (sprintf "Us%i" x.tag) x.free_vars i) (a |> Array.mapi (fun i' (L(_,t)) -> sprintf "f%ii%i : %s" i i' (tyv t)) |> String.concat ", "))
                i <- i+1
                )
            line s "}"
            )
        and method : _ -> MethodRecGleam =
            jp (fun ((jp_body,key),i) ->
                let args = codegenMethodKeyArgs key
                match codegenMethodBody env "Gleam" jp_body key with
                | a, range, name ->
                    method_names.[i] <- (generatedMethodName name i).ToLowerInvariant()
                    {tag=i; free_vars=rdata_free_vars args; range=range; body=a}
                ) (fun s x ->
                let range_ty = tup_ty x.range
                let is_fn = range_ty |> SpiralSm.starts_with "fn(Nil  ) -> "
                let ret =
                    if is_fn
                    then $"{range_ty} {{ fn(_)"
                    else range_ty
                line s $"{method_names.[x.tag]}({args_tys x.free_vars}) -> {ret} {{"
                binds (indent s) x.body
                if is_fn
                then line s "(    Nil  )}}"
                else line s "}"
                )
        and closure : _ -> ClosureRecGleam =
            jp
                (fun ((jp_body, key & (C(args, _, fun_ty))), i) ->
                match fun_ty with
                | YFun (domain, range, _) ->
                    match codegenClosureBody env "Gleam" jp_body key with
                    | domain_args, body, sourceName ->
                        closure_names.[i] <- (generatedClosureName sourceName i).ToLowerInvariant()
                        {   tag = i
                            free_vars = rdata_free_vars args
                            domain_args = data_free_vars domain_args
                            range = range
                            body = body }
                | _ ->
                    raise_codegen_error "Compiler error: Unexpected type in the closure join point.")
                (fun s x ->
                let fv_tys =
                    x.free_vars
                    |> Array.map (fun (L(_, t)) -> tyv t)

                let dom_ty =
                    match x.domain_args with
                    | [||] -> "Nil"
                    | [| L(_, t) |] -> tyv t
                    | many ->
                        many
                        |> Array.map (fun (L(_, t)) -> tyv t)
                        |> String.concat ", "
                        |> sprintf "#(%s)"

                let capt_ty =
                    fv_tys
                    |> function
                    | [||] -> "Nil"
                    | [|one|] -> sprintf "#(%s)" one
                    | many -> many |> String.concat ", " |> sprintf "#(%s)"

                let fv_bind =
                    match x.free_vars with
                    | [||] -> None
                    | arr ->
                        let names =
                            arr
                            |> Array.mapi (fun idx (L(i,_)) -> sprintf "v%i" i)
                            |> String.concat ", "
                        Some (sprintf "let #(%s) = capt" names)

                let dom_name =
                    match x.domain_args with
                    | [| L(i, _) |] -> sprintf "v%i" i
                    | _ -> "dom"

                line s (sprintf "%s(capt: %s) -> fn(%s) -> %s {" closure_names.[x.tag] capt_ty dom_ty (tup_ty x.range))
                line (indent s) (sprintf "fn (%s) {" dom_name)

                match x.domain_args with
                | [||] -> ()
                | [| L(_, _) |] -> ()
                | many ->
                    let names =
                        many
                        |> Array.mapi (fun idx (L(i, _)) -> sprintf "v%i" i)
                        |> String.concat ", "
                    line (indent (indent s)) (sprintf "let #(%s) = dom" names)

                fv_bind |> Option.iter (line (indent (indent s)))

                binds (indent (indent s)) x.body

                line (indent s) "}"
                line s "}"
            )

        let main = StringBuilder()
        binds {text=main; indent=0} x

        let program = StringBuilder()
        env.globals |> Seq.distinct |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        externals |> Seq.iter (fun (x : string) -> program.AppendLine(x).AppendLine() |> ignore)
        types |> Seq.iteri (fun i x -> program.Append("pub type ").Append(x) |> ignore)
        functions |> Seq.iteri (fun i x -> program.Append("pub fn ").Append(x) |> ignore)
        exports |> Seq.iter (fun x -> program.Append(x) |> ignore)
        let silenceUnusedBindings (code : string) =
            let names = System.Text.RegularExpressions.Regex(@"\bv\d+\b")
            let bindings = System.Text.RegularExpressions.Regex(@"\blet\s+(#\([^)]*\)|v\d+)\s*=|(?<=[(,]\s*)(v\d+)(?=:)")
            System.Text.RegularExpressions.Regex(@"(?m)^(?=pub fn )").Split(code)
            |> Array.map (fun chunk ->
                let counts = names.Matches(chunk) |> Seq.countBy (fun m -> m.Value) |> dict
                let unused =
                    bindings.Matches(chunk)
                    |> Seq.collect (fun m -> names.Matches(m.Value) |> Seq.map (fun n -> n.Value))
                    |> Seq.filter (fun name -> counts.[name] = 1)
                    |> Set.ofSeq
                if unused.IsEmpty then chunk
                else names.Replace(chunk, fun m -> if unused.Contains m.Value then "_" + m.Value else m.Value))
            |> String.concat ""
        let gleamUsedHelpers (code : string) =
            let definition = System.Text.RegularExpressions.Regex(@"(?m)^(?:@external\([^\n]*\)\n)*pub fn (spiral_\w+)\(")
            let rec prune (text : string) =
                let without (found : System.Text.RegularExpressions.Match) =
                    let lineEnd = text.IndexOf('\n', found.Index + found.Length)
                    if lineEnd < 0 then None
                    else
                        let stop =
                            if text.Substring(found.Index, lineEnd - found.Index).TrimEnd().EndsWith "{" then
                                let close = text.IndexOf("\n}\n", found.Index)
                                if close >= 0 then close + 3 else lineEnd + 1
                            else lineEnd + 1
                        let rest = text.Remove(found.Index, stop - found.Index)
                        if System.Text.RegularExpressions.Regex.IsMatch(rest, @"(?<![\w.])" + found.Groups.[1].Value + @"\b") then None else Some rest
                match definition.Matches(text) |> Seq.tryPick without with
                | Some rest -> prune rest
                | None -> text
            prune (code.Replace("\r\n", "\n"))
        let gleamIndentedMain (body : string) =
            let lines = body.Replace("\r\n", "\n").Split('\n')
            let oddQuotes (line : string) = (line.Replace("\\\\", "").Replace("\\\"", "") |> Seq.filter (fun c -> c = '"') |> Seq.length) % 2 = 1
            if lines |> Array.exists oddQuotes then body
            else lines |> Array.map (fun line -> if line = "" then line else "    " + line) |> String.concat "\n"
        let gleamTypeName (name : string) =
            name.Split('_', System.StringSplitOptions.RemoveEmptyEntries)
            |> Array.map (fun part -> string (System.Char.ToUpperInvariant part.[0]) + part.Substring 1)
            |> String.concat ""
        let renameExportedUnions (code : string) =
            exported_union_names |> Seq.fold (fun (code : string) (KeyValue(node, name)) ->
                let u = (unbox<Union> node).Item
                let generated = match u.layout with UHeap -> $"Uh{(uheap u.cases).tag}" | UStack -> $"Us{(ustack u.cases).tag}"
                System.Text.RegularExpressions.Regex.Replace(code, $@"\b{generated}(?![0-9])", gleamTypeName name)
                ) code
        let importUnions (code : string) =
            if linked_units.IsEmpty then code
            else
                let candidates =
                    [ for KeyValue(node, source) in unionSourceNames do
                        match linkedUnionName linked_units node source with
                        | Some (unitName, name) ->
                            let u = (unbox<Union> node).Item
                            let generated = match u.layout with UHeap -> $"Uh{(uheap u.cases).tag}" | UStack -> $"Us{(ustack u.cases).tag}"
                            yield generated, gleamTypeName name, unitName
                        | None -> () ]
                let renamed =
                    candidates |> List.fold (fun (code : string) (generated, name, _) ->
                        System.Text.RegularExpressions.Regex.Replace(code, $@"\b{generated}(?![0-9])", name)) code
                let dropped, imports =
                    candidates
                    |> List.map (fun (_, name, unitName) -> name, unitName)
                    |> List.distinct
                    |> List.fold (fun ((code : string), imports) (name, unitName) ->
                        let block = System.Text.RegularExpressions.Regex($@"(?ms)^pub type {name} \{{\n(.*?)^\}}\n")
                        let found = block.Match code
                        if not found.Success then code, imports
                        else
                            let constructors =
                                found.Groups.[1].Value.Split('\n', System.StringSplitOptions.RemoveEmptyEntries)
                                |> Array.map (fun line -> line.Trim())
                                |> Array.filter (fun line -> line <> "")
                                |> Array.map (fun line -> match line.IndexOf '(' with -1 -> line | at -> line.Substring(0, at))
                                |> List.ofArray
                            code.Remove(found.Index, found.Length), imports @ [ unitName, $"type {name}" :: constructors ]) (renamed, [])
                let lines =
                    imports
                    |> List.groupBy fst
                    |> List.map (fun (unitName, groups) -> $"""import {unitName}.{{{groups |> List.collect snd |> String.concat ", "}}}""" + "\n")
                    |> String.concat ""
                let dropped =
                    imports |> List.map fst |> List.distinct |> List.fold (fun (code : string) unitName ->
                        System.Text.RegularExpressions.Regex.Replace(code, $@"(?m)^import {System.Text.RegularExpressions.Regex.Escape unitName}\r?\n", "")) dropped
                lines + dropped
        (program.Append($"pub fn main() {{\n{gleamIndentedMain (string main)}}}\n").ToString() |> silenceUnusedBindings |> gleamUsedHelpers |> renameExportedUnions |> importUnions), ffi.Value

    /// ## CodegenLua

    /// ### backend_nameLua
    let backend_nameLua = "Lua"

    /// ### litLua
    let litLua = function
        | LitInt8 x -> sprintf "%i" x
        | LitInt16 x -> sprintf "%i" x
        | LitInt32 x -> sprintf "%i" x
        | LitInt64 x -> sprintf "%i" x
        | LitUInt8 x -> sprintf "%i" x
        | LitUInt16 x -> sprintf "%i" x
        | LitUInt32 x -> sprintf "%i" x
        | LitUInt64 x -> sprintf "%i" x
        | LitFloat32 x ->
            if x = infinityf then "math.huge"
            elif x = -infinityf then "(-math.huge)"
            elif Single.IsNaN x then "(0/0)"
            else x.ToString("R") |> add_dec_point |> sprintf "%s"
        | LitFloat64 x ->
            if x = infinity then "math.huge"
            elif x = -infinity then "(-math.huge)"
            elif Double.IsNaN x then "(0/0)"
            else x.ToString("R") |> add_dec_point
        | LitString x ->
            let strb = StringBuilder(x.Length+2)
            strb.Append '"' |> ignore
            String.iter (function
                | '"' -> strb.Append "\\\""
                | '\b' -> strb.Append @"\b"
                | '\t' -> strb.Append @"\t"
                | '\n' -> strb.Append @"\n"
                | '\r' -> strb.Append @"\r"
                | '\\' -> strb.Append @"\\"
                | x -> strb.Append x
                >> ignore
                ) x
            strb.Append '"' |> ignore
            strb.ToString()
        | LitChar x ->
            match x with
            | '\b' -> @"\b"
            | '\n' -> @"\n"
            | '\t' -> @"\t"
            | '\r' -> @"\r"
            | '\\' -> @"\\"
            | '"' -> "\\\""
            | '\000' -> @"\0"
            | x -> string x
            |> sprintf "\"%s\""
        | LitBool x -> if x then "true" else "false"

    /// ### primLua
    let primLua = function
        | Int8T -> "Int"
        | Int16T -> "Int"
        | Int32T -> "Int"
        | Int64T -> "Int"
        | UInt8T -> "Int"
        | UInt16T -> "Int"
        | UInt32T -> "Int"
        | UInt64T -> "Int"
        | Float32T -> "Float"
        | Float64T -> "Float"
        | BoolT -> "Bool"
        | StringT -> "String"
        | CharT -> "String"

    /// ### type_litLua
    let type_litLua = function
        | YLit x -> litLua x
        | YSymbol x -> x
        | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."

    /// ### UnionRecLua
    type UnionRecLua = {tag : int; free_vars : Map<int * string, TyV[]>}

    /// ### LayoutRecLua
    type LayoutRecLua = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>}

    /// ### MethodRecLua
    type MethodRecLua = {tag : int; free_vars : L<Tag,Ty>[]; range : Ty; body : TypedBind[]}

    /// ### ClosureRecLua
    type ClosureRecLua = {tag : int; free_vars : L<Tag,Ty>[]; domain_args : TyV[]; range : Ty; body : TypedBind[]}

    /// ### codegenLua
    let codegenLua (env : PartEvalResult) (x : TypedBind []) =
        let method_names = Dictionary<int, string>()
        let closure_names = Dictionary<int, string>()
        let luaHelpers = System.Collections.Generic.List<string>()
        let useLuaHelper (text : string) = if not (luaHelpers.Contains text) then luaHelpers.Add text
        let luaUsedHelpers (code : string) =
            let blocks =
                luaHelpers
                |> Seq.collect (fun (x : string) -> System.Text.RegularExpressions.Regex.Split(x, @"(?m)^(?=local )"))
                |> Seq.filter (fun block -> block <> "")
                |> Array.ofSeq
            let nameOf (block : string) =
                let found = System.Text.RegularExpressions.Regex.Match(block, @"^local function (spiral_\w+)\(")
                if found.Success then Some found.Groups.[1].Value else None
            let kept = Array.create blocks.Length true
            let mutable changed = true
            while changed do
                changed <- false
                for index = 0 to blocks.Length - 1 do
                    match nameOf blocks.[index] with
                    | Some name when kept.[index] ->
                        let others =
                            blocks
                            |> Seq.indexed
                            |> Seq.filter (fun (other, _) -> other <> index && kept.[other])
                            |> Seq.map snd
                            |> Seq.append [code]
                            |> String.concat "\n"
                        if not (System.Text.RegularExpressions.Regex.IsMatch(others, @"(?<![\w.])" + name + @"\b")) then
                            kept.[index] <- false
                            changed <- true
                    | _ -> ()
            blocks |> Array.indexed |> Array.filter (fun (index, _) -> kept.[index]) |> Array.map snd
        let luaWrapHelpers =
            "local function spiral_wrap_unsigned(value, bits)\n    return value % (2 ^ bits)\nend\nlocal function spiral_wrap_signed(value, bits)\n    local modulus = 2 ^ bits\n    value = value % modulus\n    if value >= modulus / 2 then value = value - modulus end\n    return value\nend\nlocal function spiral_mul_mod32(a, b)\n    a = a % 4294967296\n    b = b % 4294967296\n    local a_low = a % 65536\n    local a_high = (a - a_low) / 65536\n    return (a_low * b + ((a_high * b) % 65536) * 65536) % 4294967296\nend\n"
        let luaBitHelpers =
            "local function spiral_bit_combine(a, b, keep)\n    a = a % 4294967296\n    b = b % 4294967296\n    local result, place = 0, 1\n    for _ = 1, 32 do\n        local a_bit, b_bit = a % 2, b % 2\n        if keep(a_bit, b_bit) then result = result + place end\n        a = (a - a_bit) / 2\n        b = (b - b_bit) / 2\n        place = place * 2\n    end\n    return result\nend\nlocal bit = bit32 or bit or {\n    band = function(a, b) return spiral_bit_combine(a, b, function(x, y) return x == 1 and y == 1 end) end,\n    bor = function(a, b) return spiral_bit_combine(a, b, function(x, y) return x == 1 or y == 1 end) end,\n    bxor = function(a, b) return spiral_bit_combine(a, b, function(x, y) return x ~= y end) end,\n    bnot = function(a) return 4294967295 - a % 4294967296 end,\n    lshift = function(a, n) return (a % 4294967296) * 2 ^ n % 4294967296 end,\n    rshift = function(a, n) return math.floor((a % 4294967296) / 2 ^ n) end,\n}\n"
        let luaIntegerWidth (d : Data) =
            let width = function
                | Int8T -> Some (8, true) | Int16T -> Some (16, true) | Int32T -> Some (32, true) | Int64T -> Some (64, true)
                | UInt8T -> Some (8, false) | UInt16T -> Some (16, false) | UInt32T -> Some (32, false) | UInt64T -> Some (64, false)
                | _ -> None
            match d with
            | DV(L(_,YPrim t)) -> width t
            | DLit l -> width (lit_to_primitive_type l)
            | _ -> None
        let luaWrap (d : Data) (text : string) =
            match luaIntegerWidth d with
            | Some (bits, signed) when bits <= 32 ->
                useLuaHelper luaWrapHelpers
                if signed then $"spiral_wrap_signed({text}, {bits})" else $"spiral_wrap_unsigned({text}, {bits})"
            | _ -> text
        let luaBit (d : Data) (call : string) =
            useLuaHelper luaBitHelpers
            luaWrap d call
        let luaW64Helpers = """local spiral_w64 = {}
function spiral_w64.split(x)
    if type(x) == "table" then return x[1], x[2] end
    local lo = x % 4294967296
    return ((x - lo) / 4294967296) % 4294967296, lo
end
function spiral_w64.make(h, l, s)
    if h < 2097152 then return h * 4294967296 + l end
    if s and h >= 4292870144 then return (h - 4294967296) * 4294967296 + l end
    return { h, l }
end
function spiral_w64.small(r, s)
    return r < 9007199254740992 and r > -9007199254740992 and (s or r >= 0)
end
function spiral_w64.neg_halves(h, l)
    if l == 0 then return (4294967296 - h) % 4294967296, 0 end
    return 4294967295 - h, 4294967296 - l
end
function spiral_w64.add(a, b, s)
    if type(a) == "number" and type(b) == "number" then
        local r = a + b
        if spiral_w64.small(r, s) then return r + 0 end
    end
    local ah, al = spiral_w64.split(a)
    local bh, bl = spiral_w64.split(b)
    local l, c = al + bl, 0
    if l >= 4294967296 then l, c = l - 4294967296, 1 end
    return spiral_w64.make((ah + bh + c) % 4294967296, l, s)
end
function spiral_w64.sub(a, b, s)
    if type(a) == "number" and type(b) == "number" then
        local r = a - b
        if spiral_w64.small(r, s) then return r + 0 end
    end
    local ah, al = spiral_w64.split(a)
    local bh, bl = spiral_w64.split(b)
    local l, c = al - bl, 0
    if l < 0 then l, c = l + 4294967296, 1 end
    return spiral_w64.make((ah - bh - c) % 4294967296, l, s)
end
function spiral_w64.neg(a, s)
    return spiral_w64.sub(0, a, s)
end
function spiral_w64.mul(a, b, s)
    if type(a) == "number" and type(b) == "number" then
        local r = a * b
        if spiral_w64.small(r, s) then return r + 0 end
    end
    local ah, al = spiral_w64.split(a)
    local bh, bl = spiral_w64.split(b)
    local a0, a1, a2, a3 = al % 65536, math.floor(al / 65536), ah % 65536, math.floor(ah / 65536)
    local b0, b1, b2, b3 = bl % 65536, math.floor(bl / 65536), bh % 65536, math.floor(bh / 65536)
    local c = a0 * b0
    local d0 = c % 65536
    c = math.floor(c / 65536) + a1 * b0 + a0 * b1
    local d1 = c % 65536
    c = math.floor(c / 65536) + a2 * b0 + a1 * b1 + a0 * b2
    local d2 = c % 65536
    c = math.floor(c / 65536) + a3 * b0 + a2 * b1 + a1 * b2 + a0 * b3
    local d3 = c % 65536
    return spiral_w64.make(d3 * 65536 + d2, d1 * 65536 + d0, s)
end
function spiral_w64.udivmod(ah, al, bh, bl)
    if bh == 0 and bl == 0 then error("spiral: integer division by zero") end
    if ah == 0 and bh == 0 then
        local r = math.fmod(al, bl)
        return 0, (al - r) / bl, 0, r
    end
    local qh, ql, rh, rl = 0, 0, 0, 0
    for i = 63, 0, -1 do
        local d
        if i >= 32 then d = math.floor(ah / 2 ^ (i - 32)) % 2 else d = math.floor(al / 2 ^ i) % 2 end
        rh = rh * 2 + math.floor(rl / 2147483648)
        rl = (rl % 2147483648) * 2 + d
        qh = (qh * 2 + math.floor(ql / 2147483648)) % 4294967296
        ql = (ql % 2147483648) * 2
        if rh > bh or (rh == bh and rl >= bl) then
            rl, rh = rl - bl, rh - bh
            if rl < 0 then rl, rh = rl + 4294967296, rh - 1 end
            ql = ql + 1
        end
    end
    return qh, ql, rh, rl
end
function spiral_w64.divmod(a, b, s)
    if type(a) == "number" and type(b) == "number" and b ~= 0 then
        local r = math.fmod(a, b)
        return (a - r) / b + 0, r + 0
    end
    local ah, al = spiral_w64.split(a)
    local bh, bl = spiral_w64.split(b)
    local an, bn = false, false
    if s and ah >= 2147483648 then an = true; ah, al = spiral_w64.neg_halves(ah, al) end
    if s and bh >= 2147483648 then bn = true; bh, bl = spiral_w64.neg_halves(bh, bl) end
    local qh, ql, rh, rl = spiral_w64.udivmod(ah, al, bh, bl)
