                  | YFun (domain, _, FT_Vanilla) ->
                      let domain_is_nil = env.ty_to_data domain |> data_free_vars |> Array.isEmpty
                      if arg_code |> SpiralSm.trim = "nil" then
                        if domain_is_nil then sprintf "v%i(nil)" i else sprintf "v%i" i
                      else
                        if domain_is_nil then sprintf "v%i((%s)(nil))" i arg_code
                        else sprintf "v%i(%s)" i arg_code
                  | _ ->
                      sprintf "v%i(%s)" i arg_code
                call |> simple
            | TyOp(Global, [DLit (LitString x)]) -> global' x
            | TyOp(op,l) ->
                match op, l with
                | Dyn,[a] -> tup a
                | Assign,[a;b] -> sprintf "%s = %s" (tup a) (tup b)
                | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                | StaticStringConcat, [a;b] -> sprintf "(%s .. %s)" (tup a) (tup b)
                | StringIndex, [a;b] ->
                    sprintf "string.sub(%s, (%s)+1, (%s)+1)" (tup a) (tup b) (tup b)
                | StringSlice, [a;b;c] ->
                    sprintf "string.sub(%s, (%s)+1, (%s)+1)" (tup a) (tup b) (tup c)
                | ArrayIndex, [a;b] ->
                    sprintf "(%s)[(%s)+1]" (tup a) (tup b)
                | ArrayIndexSet, [a;b;c] ->
                    let target = tup a
                    if System.Text.RegularExpressions.Regex.IsMatch(target, @"^[A-Za-z_][A-Za-z0-9_]*$") then sprintf "%s[(%s)+1] = %s" target (tup b) (tup c)
                    else sprintf ";(%s)[(%s)+1] = %s" target (tup b) (tup c)

                | (Add | Sub | Mult | Div | Mod | BitwiseAnd | BitwiseOr | BitwiseXor | ShiftLeft | ShiftRight), [a;b] when (luaW64 a).IsSome ->
                    let name =
                        match op with
                        | Add -> "add" | Sub -> "sub" | Mult -> "mul" | Div -> "div" | Mod -> "mod"
                        | BitwiseAnd -> "band" | BitwiseOr -> "bor" | BitwiseXor -> "bxor" | ShiftLeft -> "shl" | _ -> "shr"
                    sprintf "spiral_w64.%s(%s, %s, %s)" name (tup a) (tup b) (luaW64 a).Value
                | (LT | LTE | GT | GTE | EQ | NEQ), [a;b] when (luaW64 a).IsSome ->
                    let signed = (luaW64 a).Value
                    match op with
                    | LT -> sprintf "spiral_w64.lt(%s, %s, %s)" (tup a) (tup b) signed
                    | LTE -> sprintf "(not spiral_w64.lt(%s, %s, %s))" (tup b) (tup a) signed
                    | GT -> sprintf "spiral_w64.lt(%s, %s, %s)" (tup b) (tup a) signed
                    | GTE -> sprintf "(not spiral_w64.lt(%s, %s, %s))" (tup a) (tup b) signed
                    | EQ -> sprintf "spiral_w64.eq(%s, %s)" (tup a) (tup b)
                    | _ -> sprintf "(not spiral_w64.eq(%s, %s))" (tup a) (tup b)
                | (Neg | BitwiseComplement), [x] when (luaW64 x).IsSome ->
                    sprintf "spiral_w64.%s(%s, %s)" (match op with Neg -> "neg" | _ -> "bnot") (tup x) (luaW64 x).Value
                | Add, [a;b] -> luaWrap a (sprintf "(%s + %s)" (tup a) (tup b))
                | Sub, [a;b] -> luaWrap a (sprintf "(%s - %s)" (tup a) (tup b))
                | Mult, [a;b] ->
                    match luaIntegerWidth a with
                    | Some (32, _) -> useLuaHelper luaWrapHelpers; luaWrap a (sprintf "spiral_mul_mod32(%s, %s)" (tup a) (tup b))
                    | _ -> luaWrap a (sprintf "(%s * %s)" (tup a) (tup b))
                | Div, [a;b] when (match data_term_vars a with [|WV(L(_,YPrim (Int8T | Int16T | Int32T | Int64T | UInt8T | UInt16T | UInt32T | UInt64T)))|] | [|WLit (LitInt8 _ | LitInt16 _ | LitInt32 _ | LitInt64 _ | LitUInt8 _ | LitUInt16 _ | LitUInt32 _ | LitUInt64 _)|] -> true | _ -> false) ->
                    sprintf "(math.modf(%s / %s))" (tup a) (tup b)
                | Div, [a;b] -> sprintf "%s / %s" (tup a) (tup b)
                | Mod, [a;b] -> sprintf "math.fmod(%s, %s)" (tup a) (tup b)
                | Pow, [a;b] -> sprintf "%s ^ %s" (tup a) (tup b)
                | LT, [a;b] -> sprintf "%s < %s" (tup a) (tup b)
                | LTE, [a;b] -> sprintf "%s <= %s" (tup a) (tup b)
                | EQ, [a;b] -> sprintf "%s == %s" (tup a) (tup b)
                | NEQ, [a;b] -> sprintf "%s ~= %s" (tup a) (tup b)
                | GT, [a;b] -> sprintf "%s > %s" (tup a) (tup b)
                | GTE, [a;b] -> sprintf "%s >= %s" (tup a) (tup b)
                | BoolAnd, [a;b] -> sprintf "(%s) and (%s)" (tup a) (tup b)
                | BoolOr, [a;b] -> sprintf "(%s) or (%s)" (tup a) (tup b)
                | BitwiseAnd, [a;b] -> luaBit a (sprintf "bit.band(%s, %s)" (tup a) (tup b))
                | BitwiseOr, [a;b] -> luaBit a (sprintf "bit.bor(%s, %s)" (tup a) (tup b))
                | BitwiseXor, [a;b] -> luaBit a (sprintf "bit.bxor(%s, %s)" (tup a) (tup b))
                | BitwiseComplement, [a] -> luaBit a (sprintf "bit.bnot(%s)" (tup a))
                | ShiftLeft, [a;b] -> luaBit a (sprintf "bit.lshift(%s, %s)" (tup a) (tup b))
                | ShiftRight, [a;b] ->
                    match luaIntegerWidth a with
                    | Some (_, true) -> luaWrap a (sprintf "math.floor(%s / 2 ^ %s)" (tup a) (tup b))
                    | _ -> luaBit a (sprintf "bit.rshift(%s, %s)" (tup a) (tup b))

                | Neg, [x] -> luaWrap x (sprintf "-(%s)" (tup x))
                | Log, [x] -> sprintf "math.log(%s)" (tup x)
                | Exp, [x] -> sprintf "math.exp(%s)" (tup x)
                | Tanh, [x] -> sprintf "math.tanh(%s)" (tup x)
                | Sqrt, [x] -> sprintf "math.sqrt(%s)" (tup x)
                | Sin, [x] -> sprintf "math.sin(%s)" (tup x)
                | Cos, [x] -> sprintf "math.cos(%s)" (tup x)
                | PrimToString, [x] ->
                    match x with
                    | DLit(LitChar _) | DV(L(_,YPrim CharT)) -> tup x
                    | DLit(LitBool _) | DV(L(_,YPrim BoolT)) -> sprintf "tostring(%s)" (tup x)
                    | DLit(LitInt64 _ | LitUInt64 _) | DV(L(_,YPrim (Int64T | UInt64T))) ->
                        luaW64Use ()
                        let signed = match x with DLit(LitInt64 _) | DV(L(_,YPrim Int64T)) -> "true" | _ -> "false"
                        sprintf "spiral_w64.tostring(%s, %s)" (tup x) signed
                    | DLit(LitUInt32 _) | DV(L(_,YPrim UInt32T)) -> sprintf "string.format(\"%%.0f\", %s)" (tup x)
                    | _ -> sprintf "string.format(\"%%d\", %s)" (tup x)
                | NanIs, [x] -> sprintf "(%s ~= %s)" (tup x) (tup x)
                | UnionTag, [DV(L(i,YUnion h))] ->
                    let h = h.Item
                    let ty =
                        match h.layout with
                        | UHeap -> sprintf "Uh%i" (uheap h.cases).tag
                        | UStack -> sprintf "Us%i" (ustack h.cases).tag
                    let mutable code = StringBuilder()
                    code.Append("(function () local __tag\n") |> ignore
                    h.cases |> Seq.iteri (fun idx (KeyValue ((ci,_), _)) ->
                        if idx = 0 then
                            code.AppendFormat("if v{0}.tag == \"{1}\" then __tag = {2}\n", i, generatedCaseName ty h.cases idx, ci) |> ignore
                        else
                            code.AppendFormat("elseif v{0}.tag == \"{1}\" then __tag = {2}\n", i, generatedCaseName ty h.cases idx, ci) |> ignore
                    )
                    code.Append("else __tag = 0 end\nreturn __tag end)()") |> ignore
                    code.ToString()
                | Printf, [DLit (LitString fmt); b] ->
                    printf_pieces fmt (data_term_vars b)
                    |> List.map (function
                        | Choice1Of2 t -> litLua (LitString t)
                        | Choice2Of2 ('s', a) -> show_w a
                        | Choice2Of2 (_, (WV(L(_,YPrim (Int64T | UInt64T))) | WLit (LitInt64 _ | LitUInt64 _) as a)) ->
                            luaW64Use ()
                            let signed = match a with WV(L(_,YPrim Int64T)) | WLit (LitInt64 _) -> "true" | _ -> "false"
                            "spiral_w64.tostring(" + show_w a + ", " + signed + ")"
                        | Choice2Of2 (_, (WV(L(_,YPrim UInt32T)) | WLit (LitUInt32 _) as a)) -> "string.format(\"%.0f\", " + show_w a + ")"
                        | Choice2Of2 (_, a) -> "string.format(\"%d\", " + show_w a + ")")
                    |> String.concat ", " |> sprintf "io.write(%s)"
                | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported" op l.Length
                |> simple
        and heap : _ -> LayoutRecLua = layout (fun s x ->
            let b = x.free_vars |> Array.map (fun (L(i,t)) -> sprintf "l%i" i) |> String.concat ", "
            if b = "" then line s (sprintf "Heap%i = function() return { __tag = \"Heap%i\" } end" x.tag x.tag)
            else line s (sprintf "Heap%i = function(%s) return { __tag = \"Heap%i\", %s } end" x.tag b x.tag b)
            )
        and mut : _ -> LayoutRecLua = layout (fun s x ->
            let b = x.free_vars |> Array.map (fun (L(i,t)) -> sprintf "l%i" i) |> String.concat ", "
            if b = ""
            then line s (sprintf "Mut%i = function() return { __tag = \"Mut%i\" } end" x.tag x.tag)
            else
                let b' = x.free_vars |> Array.map (fun (L(i,t)) -> sprintf "l%i = l%i" i i) |> String.concat ", "
                line s (sprintf "Mut%i = function(%s) return { __tag = \"Mut%i\", %s } end" x.tag b x.tag b')
            )
        and uheap : _ -> UnionRecLua = union (fun s x ->
            let tag = x.tag
            let mutable i = 0
            x.free_vars |> Map.iter (fun _ a ->
                match a with
                | [||] -> line s (sprintf "%s = (function() local shared = { tag = \"%s\" } return function() return shared end end)()" (generatedCaseName $"Uh{tag}" x.free_vars i) (generatedCaseName $"Uh{tag}" x.free_vars i))
                | a ->
                    let params' = a |> Array.mapi (fun j _ -> sprintf "v%i" j) |> String.concat ", "
                    let fields = a |> Array.mapi (fun j _ -> sprintf " _%i = v%i" (j+1) j) |> String.concat ", "
                    line s (sprintf "function %s(%s) return { tag = \"%s\", %s } end" (generatedCaseName $"Uh{tag}" x.free_vars i) params' (generatedCaseName $"Uh{tag}" x.free_vars i) fields)
                i <- i + 1
            )
        )
        and ustack : _ -> UnionRecLua = union (fun s x ->
            let tag = x.tag
            let mutable i = 0
            x.free_vars |> Map.iter (fun _ a ->
                match a with
                | [||] -> line s (sprintf "function %s() return { tag = \"%s\" } end" (generatedCaseName $"Us{tag}" x.free_vars i) (generatedCaseName $"Us{tag}" x.free_vars i))
                | a ->
                    let params' = a |> Array.mapi (fun j _ -> sprintf "v%i" j) |> String.concat ", "
                    let fields = a |> Array.mapi (fun j _ -> sprintf " _%i = v%i" (j+1) j) |> String.concat ", "
                    line s (sprintf "function %s(%s) return { tag = \"%s\", %s } end" (generatedCaseName $"Us{tag}" x.free_vars i) params' (generatedCaseName $"Us{tag}" x.free_vars i) fields)
                i <- i + 1
            )
        )
        and method : _ -> MethodRecLua =
            jp (fun ((jp_body,key),i) ->
                let args = codegenMethodKeyArgs key
                match codegenMethodBody env "Lua" jp_body key with
                | a, range, name ->
                    method_names.[i] <- generatedMethodName name i
                    {tag=i; free_vars=rdata_free_vars args; range=range; body=a}
                ) (fun s x ->
                line s (sprintf "function %s(%s)" method_names.[x.tag] (args_tys x.free_vars))
                binds (indent s) x.body
                line s "end"
                )
        and closure : _ -> ClosureRecLua =
            jp
                (fun ((jp_body, key & (C(args, _, fun_ty))), i) ->
                match fun_ty with
                | YFun (domain, range, FT_Vanilla) ->
                    match codegenClosureBody env "Lua" jp_body key with
                    | domain_args, body, sourceName ->
                        closure_names.[i] <- generatedClosureName sourceName i
                        {   tag = i
                            free_vars = rdata_free_vars args
                            domain_args = data_free_vars domain_args
                            range = range
                            body = body }
                | YFun (_, _, _) ->
                    raise_codegen_error "Non-standard functions are not supported in the Lua backend."
                | _ ->
                    raise_codegen_error "Compiler error: Unexpected type in the closure join point.")
                (fun s x ->
                let fv_bind =
                    match x.free_vars with
                    | [||] -> "local __capt = nil"
                    | arr ->
                        let names = arr |> Array.mapi (fun _ (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "
                        sprintf "local %s = capt[1], %s" (arr |> Array.mapi (fun _ (L(i,_)) -> sprintf "v%i" i) |> Array.head) (names |> SpiralSm.replace (arr |> Array.mapi (fun _ (L(i,_)) -> sprintf "v%i" i) |> Array.head) "" |> SpiralSm.trim)
                line s (sprintf "function %s(capt)" closure_names.[x.tag])
                if x.free_vars.Length > 0 then line (indent s) (sprintf "local %s = (table.unpack or unpack)(capt)" (x.free_vars |> Array.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "))
                match x.domain_args with
                | [||] ->
                    line (indent s) "return function(dom)"
                | [| L(i, _) |] ->
                    line (indent s) (sprintf "return function(v%i)" i)
                | many ->
                    line (indent s) "return function(dom)"
                    line (indent (indent s)) (sprintf "local %s = (table.unpack or unpack)(dom)" (many |> Array.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "))
                binds (indent (indent s)) x.body
                line (indent s) "end"
                line s "end"
            )

        let main = StringBuilder()
        binds {text=main; indent=0} x

        let program = StringBuilder()

        let usedHelpers = luaUsedHelpers (String.concat "\n" types + String.concat "\n" functions + main.ToString())
        usedHelpers |> Seq.iter (fun (x : string) -> program.Append(x) |> ignore)
        let definitions =
            Seq.append types functions
            |> Seq.collect (fun (text : string) ->
                System.Text.RegularExpressions.Regex.Matches(text, @"(?m)^(?:function\s+(\w+)\(|(\w+)\s*=\s*function\()")
                |> Seq.map (fun m -> if m.Groups.[1].Success then m.Groups.[1].Value else m.Groups.[2].Value))
            |> Seq.distinct
            |> Array.ofSeq
        let chunkLocals = System.Text.RegularExpressions.Regex.Matches(main.ToString(), @"(?m)^local\s").Count
        let helperLocals = usedHelpers |> Seq.sumBy (fun (x : string) -> System.Text.RegularExpressions.Regex.Matches(x, @"(?m)^local\s").Count)
        if definitions.Length > 0 && definitions.Length + chunkLocals + helperLocals < 190 then
            program.Append("local ").Append(String.concat ", " definitions).Append("\n") |> ignore
        types |> Seq.iteri (fun i x -> program.Append(x).Append("\n") |> ignore)
        functions |> Seq.iteri (fun i x -> program.Append(x).Append("\n") |> ignore)
        let spillChunkLocals (code : string) =
            let code = code.Replace("\r\n", "\n")
            let declared =
                System.Text.RegularExpressions.Regex.Matches(code, @"(?m)^local\s+([A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*)\s*=")
                |> Seq.collect (fun m -> m.Groups.[1].Value.Split(',') |> Seq.map (fun s -> s.Trim()))
                |> HashSet
            if declared.Count < 150 then code
            else
                let isNamePart (c : char) = Char.IsLetterOrDigit c || c = '_'
                let rewritten = StringBuilder("local spilled = {}\n")
                let mutable i = 0
                while i < code.Length do
                    let c = code.[i]
                    if c = '"' || c = '\'' then
                        let start = i
                        i <- i + 1
                        while i < code.Length && code.[i] <> c do
                            if code.[i] = '\\' then i <- i + 1
                            i <- i + 1
                        i <- min code.Length (i + 1)
                        rewritten.Append(code, start, i - start) |> ignore
                    elif (Char.IsLetter c || c = '_') && (i = 0 || not (isNamePart code.[i - 1] || code.[i - 1] = '.' || code.[i - 1] = ':')) then
                        let mutable j = i + 1
                        while j < code.Length && isNamePart code.[j] do j <- j + 1
                        let name = code.Substring(i, j - i)
                        if declared.Contains name then rewritten.Append("spilled.").Append(name) |> ignore
                        else rewritten.Append(name) |> ignore
                        i <- j
                    else
                        rewritten.Append(c) |> ignore
                        i <- i + 1
                System.Text.RegularExpressions.Regex.Replace(rewritten.ToString(), @"(?m)^local\s+(spilled\.)", "$1")
        program.Append(spillChunkLocals (main.ToString())).ToString()

    /// ## CodegenWasm

    /// ### backend_nameWasm
    let backend_nameWasm = "Wasm"

    /// ### wasmPrimValType
    let wasmPrimValType = function
        | Int64T | UInt64T -> "i64"
        | Float32T -> "f32"
        | Float64T -> "f64"
        | Int8T | Int16T | Int32T | UInt8T | UInt16T | UInt32T | BoolT | CharT | StringT -> "i32"

    /// ### wasmScratchEnd
    let wasmScratchEnd = 72

    /// ### wasmPrelude
    let wasmPrelude = """  (import "wasi_snapshot_preview1" "fd_write" (func $fd_write (param i32 i32 i32 i32) (result i32)))
  (import "wasi_snapshot_preview1" "proc_exit" (func $proc_exit (param i32)))
  (func $write (param $fd i32) (param $ptr i32) (param $len i32)
    (i32.store (i32.const 0) (local.get $ptr))
    (i32.store (i32.const 4) (local.get $len))
    (drop (call $fd_write (local.get $fd) (i32.const 0) (i32.const 1) (i32.const 8))))
  (func $print_str (param $s i32)
    (call $write (i32.const 1) (i32.add (local.get $s) (i32.const 4)) (i32.load (local.get $s))))
  (func $eprint_line (param $s i32)
    (call $write (i32.const 2) (i32.add (local.get $s) (i32.const 4)) (i32.load (local.get $s)))
    (i32.store8 (i32.const 12) (i32.const 10))
    (call $write (i32.const 2) (i32.const 12) (i32.const 1)))
  (data (i32.const 48) "\04\00\00\00true")
  (data (i32.const 56) "\05\00\00\00false")
  (data (i32.const 66) "\01\00\00\00-")
  (func $print_newline
    (i32.store8 (i32.const 12) (i32.const 10))
    (call $write (i32.const 1) (i32.const 12) (i32.const 1)))
  (func $bool_to_str (param $b i32) (result i32)
    (select (i32.const 48) (i32.const 56) (local.get $b)))
  (func $char_to_str (param $c i32) (result i32) (local $r i32)
    (local.set $r (call $alloc (i32.const 5)))
    (i32.store (local.get $r) (i32.const 1))
    (i32.store8 offset=4 (local.get $r) (local.get $c))
    (local.get $r))
  (func $u64_to_str (param $x i64) (result i32) (local $p i32) (local $n i32) (local $r i32)
    (local.set $p (i32.const 48))
    (loop $digit
      (local.set $p (i32.sub (local.get $p) (i32.const 1)))
      (i32.store8 (local.get $p) (i32.add (i32.const 48) (i32.wrap_i64 (i64.rem_u (local.get $x) (i64.const 10)))))
      (local.set $x (i64.div_u (local.get $x) (i64.const 10)))
      (br_if $digit (i64.ne (local.get $x) (i64.const 0))))
    (local.set $n (i32.sub (i32.const 48) (local.get $p)))
    (local.set $r (call $alloc (i32.add (local.get $n) (i32.const 4))))
    (i32.store (local.get $r) (local.get $n))
    (memory.copy (i32.add (local.get $r) (i32.const 4)) (local.get $p) (local.get $n))
    (local.get $r))
  (func $i64_to_str (param $x i64) (result i32)
    (if (result i32) (i64.lt_s (local.get $x) (i64.const 0))
      (then (call $str_concat (i32.const 66) (call $u64_to_str (i64.sub (i64.const 0) (local.get $x)))))
      (else (call $u64_to_str (local.get $x)))))
  (func $print_u64 (param $x i64) (local $p i32)
    (local.set $p (i32.const 48))
    (loop $digit
      (local.set $p (i32.sub (local.get $p) (i32.const 1)))
      (i32.store8 (local.get $p) (i32.add (i32.const 48) (i32.wrap_i64 (i64.rem_u (local.get $x) (i64.const 10)))))
      (local.set $x (i64.div_u (local.get $x) (i64.const 10)))
      (br_if $digit (i64.ne (local.get $x) (i64.const 0))))
    (call $write (i32.const 1) (local.get $p) (i32.sub (i32.const 48) (local.get $p))))
  (func $print_i64 (param $x i64)
    (if (i64.lt_s (local.get $x) (i64.const 0))
      (then
        (i32.store8 (i32.const 12) (i32.const 45))
        (call $write (i32.const 1) (i32.const 12) (i32.const 1))
        (call $print_u64 (i64.sub (i64.const 0) (local.get $x))))
      (else (call $print_u64 (local.get $x)))))
  (func $alloc (param $n i32) (result i32) (local $p i32) (local $limit i32)
    (local.set $p (global.get $hp))
    (global.set $hp (i32.and (i32.add (i32.add (local.get $p) (local.get $n)) (i32.const 7)) (i32.const -8)))
    (local.set $limit (i32.mul (memory.size) (i32.const 65536)))
    (if (i32.gt_u (global.get $hp) (local.get $limit))
      (then
        (if (i32.eq (memory.grow (i32.add (i32.shr_u (i32.sub (global.get $hp) (local.get $limit)) (i32.const 16)) (i32.const 1))) (i32.const -1))
          (then (unreachable)))))
    (local.get $p))
  (func $str_concat (param $a i32) (param $b i32) (result i32) (local $la i32) (local $lb i32) (local $r i32)
    (local.set $la (i32.load (local.get $a)))
    (local.set $lb (i32.load (local.get $b)))
    (local.set $r (call $alloc (i32.add (i32.add (local.get $la) (local.get $lb)) (i32.const 4))))
    (i32.store (local.get $r) (i32.add (local.get $la) (local.get $lb)))
    (memory.copy (i32.add (local.get $r) (i32.const 4)) (i32.add (local.get $a) (i32.const 4)) (local.get $la))
