                at

        let nullary_objects = Dictionary<int, int>()
        let nullary_object (k : int) =
            match nullary_objects.TryGetValue k with
            | true, at -> at
            | _ ->
                let at = data_end
                let escaped = [| k &&& 0xff; (k >>> 8) &&& 0xff; (k >>> 16) &&& 0xff; (k >>> 24) &&& 0xff |] |> Array.map (sprintf "\\%02x") |> String.concat ""
                data.Add $"  (data (i32.const {at}) \"{escaped}\")"
                data_end <- at + 8
                nullary_objects.[k] <- at
                at

        let memo (f : 'k -> int -> unit) =
            let dict = Dictionary<'k, int>(HashIdentity.Structural)
            fun (k : 'k) ->
                match dict.TryGetValue k with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[k] <- tag
                    f k tag
                    tag

        let lit = function
            | LitInt8 x -> $"(i32.const {x})"
            | LitInt16 x -> $"(i32.const {x})"
            | LitInt32 x -> $"(i32.const {x})"
            | LitInt64 x -> $"(i64.const {x})"
            | LitUInt8 x -> $"(i32.const {x})"
            | LitUInt16 x -> $"(i32.const {x})"
            | LitUInt32 x -> $"(i32.const {x})"
            | LitUInt64 x -> $"(i64.const {x})"
            | LitFloat32 x ->
                if x = infinityf then "(f32.const inf)"
                elif x = -infinityf then "(f32.const -inf)"
                elif Single.IsNaN x then "(f32.const nan)"
                else let r = x.ToString "R" in $"(f32.const {r})"
            | LitFloat64 x ->
                if x = infinity then "(f64.const inf)"
                elif x = -infinity then "(f64.const -inf)"
                elif Double.IsNaN x then "(f64.const nan)"
                else let r = x.ToString "R" in $"(f64.const {r})"
            | LitString x -> $"(i32.const {intern x})"
            | LitChar x -> $"(i32.const {int x})"
            | LitBool x -> if x then "(i32.const 1)" else "(i32.const 0)"

        let prim_of = function
            | DV(L(_,YPrim t)) -> Some t
            | DLit l -> Some (lit_to_primitive_type l)
            | _ -> None
        let value_type d = match prim_of d with Some p -> wasmPrimValType p | None -> "i32"
        let is_unsigned d = match prim_of d with Some (UInt8T | UInt16T | UInt32T | UInt64T | BoolT | CharT) -> true | _ -> false
        let is_float d = match prim_of d with Some (Float32T | Float64T) -> true | _ -> false
        let is_string d = match prim_of d with Some StringT -> true | _ -> false
        let narrow d (x : string) =
            match prim_of d with
            | Some Int8T -> $"(i32.extend8_s {x})"
            | Some Int16T -> $"(i32.extend16_s {x})"
            | Some UInt8T -> $"(i32.and {x} (i32.const 255))"
            | Some UInt16T -> $"(i32.and {x} (i32.const 65535))"
            | _ -> x
        let show_w = function WV (L(i,_)) -> $"(local.get $v{i})" | WLit a -> lit a
        let args (x : TyV []) = x |> Array.map (fun (L(i,_)) -> $"(local.get $v{i})") |> String.concat " "
        let args' x = data_term_vars x |> Array.map show_w |> String.concat " "

        let slot_offset (slot : int) = 8 + 8 * slot
        let slot_load (value_type : string) (pointer : string) (slot : int) = $"({value_type}.load offset={slot_offset slot} {pointer})"
        let slot_store (value_type : string) (pointer : string) (slot : int) (value : string) = $"({value_type}.store offset={slot_offset slot} {pointer} {value})"
        let local_get (i : int) = $"(local.get $v{i})"
        let env_pointer = "(local.get $env)"
        let types = ResizeArray<string>()
        let closure_names = ResizeArray<string>()
        let array_element (array : string) (index : string) (width : int) = $"(i32.add {array} (i32.mul {index} (i32.const {8 * max 1 width})))"
        let layout_cache = Dictionary<Ty, ZigLayoutRec>(HashIdentity.Structural)
        let case_index (cases : Map<int * string, Ty>) k =
            cases |> Seq.map (fun (KeyValue ((_,k'),_)) -> k') |> Seq.tryFindIndex (fun k' -> UnionTagIdOps.text k = k')
            |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text k}.")

        let self_loop : (int * TyV []) option ref = ref None
        let rec term_type = function
            | WV(L(_,t)) -> tyv t
            | WLit l -> wasmPrimValType (lit_to_primitive_type l)
        and tyv x =
            match x with
            | YPrim a -> wasmPrimValType a
            | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameWasm then Some v else None) with
                | Some x -> tup_tys x |> String.concat " "
                | None -> raise_codegen_error $"In the backend_switch, expected a record with the '{backend_nameWasm}' field."
            | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_tys a |> String.concat " " | TypeLit _ -> raise_codegen_error "The Wasm backend has no type literals.") |> String.concat ""
            | YLayout(_,(StackMutable | StackRefs | HeapRefs)) -> raise_codegen_error "The Wasm backend supports only the heap and heap mutable layout types."
            | YUnion _ | YLayout _ | YArray _ | YFun _ -> "i32"
            | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
            | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
            | a -> raise_codegen_error $"Type not supported in the codegen.\nGot: %A{a}"
        and tyvs (x : Ty) = env.ty_to_data x |> data_free_vars
        and tup_tys x = tyvs x |> Array.map (fun (L(_,t)) -> tyv t)
        and tup d = data_term_vars d |> Array.map show_w |> String.concat " "
        and index32_data d = match prim_of d with Some (Int64T | UInt64T) -> $"(i32.wrap_i64 {tup d})" | _ -> tup d
        and layout (x : Ty) : ZigLayoutRec =
            match layout_cache.TryGetValue x with
            | true, r -> r
            | _ ->
                let r =
                    match x with
                    | YLayout(x,_) ->
                        let x = env.ty_to_data x
                        let a, b =
                            match x with
                            | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                            | _ -> data_free_vars x, Map.empty
                        ({data=x; free_vars=a; free_vars_by_key=b; tag=layout_cache.Count} : ZigLayoutRec)
                    | _ -> raise_codegen_error $"Compiler error: Expected a layout type.\nGot: %s{show_ty x}"
                layout_cache.[x] <- r
                r
        and layout_slot (r : ZigLayoutRec) (field : int) = r.free_vars |> Array.findIndex (fun (L(j,_)) -> j = field)
        and emit_function (name : string) (self_tag : int option) (parameters : TyV []) (captured : TyV []) (export : string) (range : Ty) (body : TypedBind []) =
            let locals = HashSet(parameters |> Array.map (fun (L(i,_)) -> i)), ResizeArray<string>()
            let s = {text=StringBuilder(); indent=4}
            captured |> Array.iteri (fun k (L(i,t) as field) ->
                declare locals field
                line s $"(local.set $v{i} {slot_load (tyv t) env_pointer k})")
            let saved = self_loop.Value
            match self_tag with
            | Some tag when self_tail tag body ->
                self_loop.Value <- Some (tag, parameters)
                line s "(loop $self"
                binds locals (indent s) (WasmTail range) body
                line s ")"
            | _ ->
                self_loop.Value <- None
                binds locals s (WasmTail range) body
            self_loop.Value <- saved
            let results = tup_tys range
            if results.Length > 0 then line s "(unreachable)"
            let ps = parameters |> Array.map (fun (L(i,t)) -> $" (param $v{i} {tyv t})") |> String.concat ""
            let ps = if closure_names.Contains ("$" + name) then " (param $env i32)" + ps else ps
            let rs = if results.Length = 0 then "" else " (result " + String.concat " " results + ")"
            let decls = snd locals |> Seq.map (sprintf "    %s\n") |> String.concat ""
            functions.Add($"  (func ${name}{export}{ps}{rs}\n{decls}{s.text.ToString()}  )")
        and declare (names : HashSet<int>, decls : ResizeArray<string>) (L(i,t)) =
            if names.Add i then decls.Add($"(local $v{i} {tyv t})")
        and temp (_ : HashSet<int>, decls : ResizeArray<string>) (ty : string) =
            let name = $"t{decls.Count}"
            decls.Add($"(local ${name} {ty})")
            name
        and binds locals (s : CodegenEnv) (ret : BindsReturnWasm) (stmts : TypedBind []) =
            Array.iter (function
                | TyLet(d,trace,a) ->
                    try let d = data_free_vars d
                        d |> Array.iter (declare locals)
                        op locals s (WasmLocal d) a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) -> try op locals s ret a with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) ->
                    try match ret with
                        | WasmLocal l -> Array.iter2 (fun (L(i,_)) b -> line s $"(local.set $v{i} {show_w b})") l (data_term_vars d)
                        | WasmTail _ ->
                            match tup d with
                            | "" -> if self_loop.Value.IsSome then line s "(return)"
                            | x -> line s $"(return {x})"
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) stmts
        and op locals (s : CodegenEnv) (ret : BindsReturnWasm) a =
            let binds = binds locals
            let return' (x : string) =
                match ret with
                | WasmLocal [||] -> if x <> "" then line s x
                | WasmLocal [|L(i,_)|] -> line s $"(local.set $v{i} {x})"
                | WasmLocal l ->
                    line s x
                    l |> Array.rev |> Array.iter (fun (L(i,_)) -> line s $"(local.set $v{i})")
                | WasmTail range ->
                    if (tup_tys range).Length = 0 then
                        if x <> "" then line s x
                        if self_loop.Value.IsSome then line s "(return)"
                    else line s $"(return {x})"
            let jp (a, b) =
                match a with
                | JPMethod(a,c) -> $"(call ${method_names.[(method (a,c)).tag]} {args b})"
                | JPClosure(a,c) ->
                    let tag = (closure (a,c)).tag
                    let p = temp locals "i32"
                    line s $"(local.set ${p} (call $alloc (i32.const {8 + 8 * b.Length})))"
                    line s $"(i32.store (local.get ${p}) (i32.const {tag}))"
                    b |> Array.iteri (fun k (L(i,t)) -> line s (slot_store (tyv t) $"(local.get ${p})" k (local_get i)))
                    $"(local.get ${p})"
            let unary f = function [x] -> f (tup x) | _ -> raise_codegen_error "Compiler error: Expected one argument."
            match a with
            | TyMacro a -> a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup x) | CMType x -> tup_tys x |> String.concat " " | CMTypeLit _ -> raise_codegen_error "The Wasm backend has no type literals.") |> String.concat "" |> return'
            | TyIf(cond,tr,fl) ->
                line s $"(if {tup cond}"
                line (indent s) "(then"
                binds (indent (indent s)) ret tr
                line (indent s) ")"
                line (indent s) "(else"
                binds (indent (indent s)) ret fl
                line (indent s) "))"
            | TyJoinPoint(JPMethod(a,c),b) when (match ret, self_loop.Value with WasmTail _, Some (tag, _) -> (method (a,c)).tag = tag | _ -> false) ->
                let parameters = snd self_loop.Value.Value
                let types = parameters |> Array.map (fun (L(i,t)) -> i, t) |> dict
                let temps = System.Collections.Generic.Dictionary<int, string> ()
                for step in parallelMoves (Array.map2 (fun (L(target,_)) (L(source,_)) -> target, source) parameters b) do
                    match step with
                    | MoveVar (target, source) -> line s $"(local.set $v{target} (local.get $v{source}))"
                    | SaveTemp (slot, source) ->
                        temps.[slot] <- temp locals (tyv types.[source])
                        line s $"(local.set ${temps.[slot]} (local.get $v{source}))"
                    | MoveTemp (target, slot) -> line s $"(local.set $v{target} (local.get ${temps.[slot]}))"
                line s "(br $self)"
            | TyJoinPoint(a,args) -> return' (jp (a, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The Wasm backend does not support nesting other backends."
            | TyWhile(a,b) ->
                let n = next_label ()
                line s $"(block $while_exit{n}"
                line (indent s) $"(loop $while_next{n}"
                line (indent (indent s)) $"(br_if $while_exit{n} (i32.eqz {jp a}))"
                binds (indent (indent s)) (WasmLocal [||]) b
                line (indent (indent s)) $"(br $while_next{n})))"
            | TyDo a | TyIndent a -> binds s ret a
            | TyIntSwitch(L(i,t),on_succ,on_fail) ->
                let rec cases k =
                    if k >= on_succ.Length then binds (indent s) ret on_fail
                    else
                        line s $"(if ({tyv t}.eq (local.get $v{i}) ({tyv t}.const {k}))"
                        line (indent s) "(then"
                        binds (indent (indent s)) ret on_succ.[k]
                        line (indent s) ")"
                        line (indent s) "(else"
                        cases (k + 1)
                        line (indent s) "))"
                cases 0
            | TyFailwith(_,b) ->
                line s $"(call $eprint_line {tup b})"
                line s "(call $proc_exit (i32.const 1))"
                line s "(unreachable)"
            | TyConv(a,b) ->
                let target = match a with YPrim p -> p | _ -> raise_codegen_error $"Compiler error: Unexpected type in Conv. Got: {show_ty a}"
                let source = match prim_of b with Some p -> p | None -> raise_codegen_error "Compiler error: Conv expects a primitive."
                let value = tup b
                let unsigned_source = match source with UInt8T | UInt16T | UInt32T | UInt64T | BoolT | CharT -> true | _ -> false
                let unsigned_target = match target with UInt8T | UInt16T | UInt32T | UInt64T | BoolT | CharT -> true | _ -> false
                let su = if unsigned_source then "u" else "s"
                let tu = if unsigned_target then "u" else "s"
                let narrow_target (x : string) =
                    match target with
                    | Int8T -> $"(i32.extend8_s {x})"
                    | Int16T -> $"(i32.extend16_s {x})"
                    | UInt8T -> $"(i32.and {x} (i32.const 255))"
                    | UInt16T -> $"(i32.and {x} (i32.const 65535))"
                    | _ -> x
                match wasmPrimValType source, wasmPrimValType target with
                | "i32", "i32" -> narrow_target value
                | "i32", "i64" -> $"(i64.extend_i32_{su} {value})"
                | "i64", "i32" -> narrow_target $"(i32.wrap_i64 {value})"
                | "i64", "i64" -> value
                | (("i32" | "i64") as f), (("f32" | "f64") as t) -> $"({t}.convert_{f}_{su} {value})"
                | (("f32" | "f64") as f), "i32" -> narrow_target $"(i32.trunc_sat_{f}_{tu} {value})"
                | (("f32" | "f64") as f), "i64" -> $"(i64.trunc_sat_{f}_{tu} {value})"
                | "f32", "f64" -> $"(f64.promote_f32 {value})"
                | "f64", "f32" -> $"(f32.demote_f64 {value})"
                | _ -> value
                |> return'
            | TyUnionBox(a,b,c) ->
                let c = c.Item
                let k = case_index c.cases a
                let fields = data_term_vars b
                if fields.Length = 0 then return' $"(i32.const {nullary_object k})"
                else
                    let p = temp locals "i32"
                    line s $"(local.set ${p} (call $alloc (i32.const {8 + 8 * fields.Length})))"
                    line s $"(i32.store (local.get ${p}) (i32.const {k}))"
                    fields |> Array.iteri (fun f w -> line s (slot_store (term_type w) $"(local.get ${p})" f (show_w w)))
                    return' $"(local.get ${p})"
            | TyUnionUnbox(is,x,on_succs,on_fail) ->
                let x' = x.Item
                let tag = temp locals "i32"
                match is with
                | L(first,_) :: rest ->
                    line s $"(local.set ${tag} (i32.load (local.get $v{first})))"
                    rest |> List.iter (fun (L(other,_)) -> line s $"(if (i32.ne (local.get ${tag}) (i32.load (local.get $v{other}))) (then (local.set ${tag} (i32.const -1))))")
                | [] -> raise_codegen_error "Compiler error: Union unbox without a scrutinee."
                let cases = on_succs |> Map.toList
                let rec chain = function
                    | [] ->
                        match on_fail with
                        | Some b -> binds s ret b
                        | None -> line s "(unreachable)"
                    | (k, (a, b)) :: rest ->
                        let c = case_index x'.cases k
                        line s $"(if (i32.eq (local.get ${tag}) (i32.const {c}))"
                        line (indent s) "(then"
                        let inner = indent (indent s)
                        List.iter2 (fun (L(v,_)) a ->
                            let scrutinee = sprintf "(local.get $v%i)" v
                            data_free_vars a |> Array.iteri (fun f (L(i,t) as field) ->
                                declare locals field
                                let value = slot_load (tyv t) scrutinee f
                                line inner $"(local.set $v{i} {value})")) is a
                        binds inner ret b
                        line (indent s) ")"
                        line (indent s) "(else"
                        chain rest
                        line (indent s) "))"
                chain cases
            | TyToLayout(a,b) ->
                let fields = (layout b).free_vars
                let values = data_term_vars a
                let p = temp locals "i32"
                line s $"(local.set ${p} (call $alloc (i32.const {8 + 8 * fields.Length})))"
                Array.iteri2 (fun k (L(_,t)) w -> line s (slot_store (tyv t) $"(local.get ${p})" k (show_w w))) fields values
                return' $"(local.get ${p})"
            | TyLayoutIndexAll(L(i,(YLayout _ as a))) ->
                match ret with
                | WasmLocal l ->
                    l |> Array.iteri (fun k (L(target,t)) -> line s $"(local.set $v{target} {slot_load (tyv t) (local_get i) k})")
                | WasmTail _ -> raise_codegen_error "Compiler error: Layout index should never come in end position."
            | TyLayoutIndexByKey(L(i,(YLayout _ as a)),key) ->
                let r = layout a
                match r.free_vars_by_key |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None), ret with
                | Some vars, WasmLocal l ->
                    Array.iter2 (fun (L(target,t)) (L(field,_)) -> line s $"(local.set $v{target} {slot_load (tyv t) (local_get i) (layout_slot r field)})") l vars
                | Some _, WasmTail _ -> raise_codegen_error "Compiler error: Layout index should never come in end position."
                | None, _ -> ()
            | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
            | TyLayoutMutableSet(L(i,t),b,c) ->
                let r = layout t
                let a = List.fold (fun s k ->
                    match s with
                    | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                    | _ -> raise_codegen_error "Compiler error: Expected a record.") r.data b
                Array.iter2 (fun (L(field,ft)) w -> line s (slot_store (tyv ft) (local_get i) (layout_slot r field) (show_w w))) (data_free_vars a) (data_term_vars c)
            | TyArrayCreate(a,b) ->
                let width = (tup_tys a).Length
                let n = temp locals "i32"
                let p = temp locals "i32"
                line s $"(local.set ${n} {index32_data b})"
                line s $"(local.set ${p} (call $alloc (i32.add (i32.const 8) (i32.mul (local.get ${n}) (i32.const {8 * max 1 width})))))"
                line s $"(i32.store (local.get ${p}) (local.get ${n}))"
                return' $"(local.get ${p})"
            | TyArrayLiteral(a,b) ->
                let element = tup_tys a
                let width = element.Length
                let p = temp locals "i32"
                line s $"(local.set ${p} (call $alloc (i32.const {8 + b.Length * 8 * max 1 width})))"
                line s $"(i32.store (local.get ${p}) (i32.const {b.Length}))"
                b |> List.iteri (fun index x ->
                    let address = array_element $"(local.get ${p})" $"(i32.const {index})" width
                    data_term_vars x |> Array.iteri (fun k w -> line s (slot_store element.[k] address k (show_w w))))
                return' $"(local.get ${p})"
            | TyArrayLength(a,b) ->
                let length = $"(i32.load {tup b})"
                return' (if tyv a = "i64" then $"(i64.extend_i32_u {length})" else length)
            | TyApply(L(i,t),b) ->
                match t with
                | YFun(domain,range,_) ->
                    let signature = fun_type (domain, range)
                    let arguments = match args' b with "" -> "" | x -> " " + x
                    return' $"(call_indirect (type $fun{signature}) (local.get $v{i}){arguments} (i32.load (local.get $v{i})))"
                | _ -> raise_codegen_error "Compiler error: Expected a function type in the application."
            | TyStringLength(a,b) ->
                let length = $"(i32.load {tup b})"
                return' (if tyv a = "i64" then $"(i64.extend_i32_u {length})" else length)
            | TySizeOf _ -> raise_codegen_error "The Wasm backend doesn't support sizeof yet."
            | TyOp(Global, [DLit (LitString x)]) -> if not (globals.Contains x) then globals.Add x
            | TyOp(op,l) ->
                let bin f = match l with [a;b] -> f (tup a) (tup b) | _ -> raise_codegen_error "Compiler error: Expected two arguments."
                let typed (name : string) = match l with a :: _ -> $"{value_type a}.{name}" | [] -> raise_codegen_error "Compiler error: Expected arguments."
                let arith name = match l with a :: _ -> bin (fun x y -> narrow a $"({typed name} {x} {y})") | [] -> raise_codegen_error "Compiler error: Expected arguments."
                let signed_op name = match l with a :: _ -> (if is_float a then typed name else typed (name + (if is_unsigned a then "_u" else "_s"))) | [] -> raise_codegen_error "Compiler error: Expected arguments."
                let compare name = match l with a :: _ when is_string a -> bin (fun x y -> $"(i32.{name}_s (call $str_cmp {x} {y}) (i32.const 0))") | _ -> bin (fun x y -> $"({signed_op name} {x} {y})")
                let instruction name = bin (fun x y -> sprintf "(%s %s %s)" (typed name) x y)
                let narrowed name = match l with a :: _ -> bin (fun x y -> narrow a (sprintf "(%s %s %s)" name x y)) | [] -> raise_codegen_error "Compiler error: Expected arguments."
                let index32 b = if value_type b = "i64" then sprintf "(i32.wrap_i64 %s)" (tup b) else tup b
                match op, l with
                | Dyn,[a] -> tup a
                | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                | StaticStringConcat, _ -> bin (sprintf "(call $str_concat %s %s)")
                | StringIndex, [a;b] -> sprintf "(i32.load8_u (i32.add (i32.add %s (i32.const 4)) %s))" (tup a) (index32 b)
                | StringSlice, [a;b;c] -> sprintf "(call $str_slice %s %s %s)" (tup a) (index32 b) (index32 c)
                | ArrayIndexSet, [a;b;c] ->
                    let element = match a with DV(L(_,YArray el)) -> tup_tys el | _ -> raise_codegen_error "Compiler error: Expected an array."
                    let address = array_element (tup a) (index32 b) element.Length
                    data_term_vars c |> Array.mapi (fun k w -> slot_store element.[k] address k (show_w w)) |> String.concat " "
                | Add, _ -> arith "add"
                | Sub, _ -> arith "sub"
                | Mult, _ -> arith "mul"
                | Div, _ -> narrowed (signed_op "div")
                | Mod, [a;_] when not (is_float a) -> narrowed (signed_op "rem")
                | LT, _ -> compare "lt"
                | LTE, _ -> compare "le"
                | GT, _ -> compare "gt"
                | GTE, _ -> compare "ge"
                | EQ, [a;_] when is_string a -> bin (sprintf "(call $str_eq %s %s)")
                | NEQ, [a;_] when is_string a -> bin (sprintf "(i32.eqz (call $str_eq %s %s))")
                | EQ, _ -> instruction "eq"
                | NEQ, _ -> instruction "ne"
                | BoolAnd, _ -> bin (sprintf "(i32.and %s %s)")
                | BoolOr, _ -> bin (sprintf "(i32.or %s %s)")
                | BitwiseAnd, _ -> instruction "and"
                | BitwiseOr, _ -> instruction "or"
                | BitwiseXor, _ -> instruction "xor"
                | BitwiseComplement, [a] -> narrow a (sprintf "(%s.xor %s (%s.const -1))" (value_type a) (tup a) (value_type a))
                | (ShiftLeft | ShiftRight), [a;b] ->
                    let count =
                        match value_type a, value_type b with
                        | "i64", "i32" -> sprintf "(i64.extend_i32_u %s)" (tup b)
                        | "i32", "i64" -> sprintf "(i32.wrap_i64 %s)" (tup b)
                        | _ -> tup b
                    match op with
                    | ShiftLeft -> narrow a (sprintf "(%s %s %s)" (typed "shl") (tup a) count)
                    | _ -> sprintf "(%s %s %s)" (signed_op "shr") (tup a) count
                | Neg, [a] when is_float a -> $"({value_type a}.neg {tup a})"
                | Neg, [a] -> narrow a $"({value_type a}.sub ({value_type a}.const 0) {tup a})"
                | Sqrt, [a] -> $"({value_type a}.sqrt {tup a})"
                | (Log | Exp | Sin | Cos | Tanh), [a] ->
                    let helper = match op with Log -> "math_log" | Exp -> "math_exp" | Sin -> "math_sin" | Cos -> "math_cos" | _ -> "math_tanh"
                    if value_type a = "f32" then sprintf "(f32.demote_f64 (call $%s (f64.promote_f32 %s)))" helper (tup a)
                    else sprintf "(call $%s %s)" helper (tup a)
                | Pow, [a;b] ->
                    if value_type a = "f32" then sprintf "(f32.demote_f64 (call $math_pow (f64.promote_f32 %s) (f64.promote_f32 %s)))" (tup a) (tup b)
                    else sprintf "(call $math_pow %s %s)" (tup a) (tup b)
                | PrimToString, [a] ->
                    match prim_of a with
                    | Some BoolT -> $"(call $bool_to_str {tup a})"
                    | Some CharT -> $"(call $char_to_str {tup a})"
                    | Some Int64T -> $"(call $i64_to_str {tup a})"
                    | Some UInt64T -> $"(call $u64_to_str {tup a})"
                    | Some (UInt8T | UInt16T | UInt32T) -> $"(call $u64_to_str (i64.extend_i32_u {tup a}))"
                    | _ -> $"(call $i64_to_str (i64.extend_i32_s {tup a}))"
                | NanIs, [a] -> $"({value_type a}.ne {tup a} {tup a})"
                | StdoutFlush, [] -> ""
                | UnionTag, [DV(L(i,t))] ->
                    let stored = $"(i32.load (local.get $v{i}))"
                    let tag =
                        match t with
                        | YUnion u ->
                            let declared = u.Item.cases |> Map.toArray |> Array.map (fun ((d,_),_) -> d)
                            if declared |> Array.mapi (fun c d -> c = d) |> Array.forall id then stored
                            else
                                let last = declared.Length - 1
                                Seq.foldBack (fun c rest -> $"(select (i32.const {declared.[c]}) {rest} (i32.eq {stored} (i32.const {c})))") (seq { 0 .. last - 1 }) $"(i32.const {declared.[last]})"
                        | _ -> stored
                    match ret with
                    | WasmLocal [|L(_,t)|] when tyv t = "i64" -> $"(i64.extend_i32_s {tag})"
                    | _ -> tag
                | ArrayIndex, [a;b] ->
                    let element = match a with DV(L(_,YArray el)) -> tup_tys el | _ -> raise_codegen_error "Compiler error: Expected an array."
                    let address = array_element (tup a) (index32 b) element.Length
                    element |> Array.mapi (fun k t -> slot_load t address k) |> String.concat " "
                | Printf, [DLit (LitString fmt); b] ->
                    printf_pieces fmt (data_term_vars b) |> List.map (function
                        | Choice1Of2 t -> $"(call $print_str (i32.const {intern t}))"
                        | Choice2Of2 ('s', a) -> $"(call $print_str {show_w a})"
                        | Choice2Of2 (_, a) ->
                            let p = match a with WV(L(_,YPrim p)) -> Some p | WLit l -> Some (lit_to_primitive_type l) | _ -> None
                            match p with
                            | Some Int64T -> $"(call $print_i64 {show_w a})"
                            | Some UInt64T -> $"(call $print_u64 {show_w a})"
                            | Some (UInt8T | UInt16T | UInt32T) -> $"(call $print_u64 (i64.extend_i32_u {show_w a}))"
                            | _ -> $"(call $print_i64 (i64.extend_i32_s {show_w a}))")
                    |> String.concat " "
                | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported in the Wasm backend" op l.Length
                |> return'
        and method_memo = lazy (memo (fun ((jp_body,key) : _ * _) tag ->
            let args = codegenMethodKeyArgs key
            match codegenMethodBody env "Wasm" jp_body key with
            | body, range, name ->
                method_names.[tag] <- generatedMethodName name tag
                emit_function method_names.[tag] (Some tag) (rdata_free_vars args) [||] "" range body))
        and method (a, b) : {| tag : int |} = {| tag = method_memo.Force() (a, b) |}
        and fun_type : Ty * Ty -> int = memo (fun (domain, range) tag ->
            let ps = tup_tys domain |> Array.map (sprintf " %s") |> String.concat ""
            let rs = match tup_tys range with [||] -> "" | r -> " (result " + String.concat " " r + ")"
            types.Add($"  (type $fun{tag} (func (param i32{ps}){rs}))"))
        and closure_memo = lazy (memo (fun ((jp_body,key & (C(args,_,fun_ty))) : _ * _) tag ->
            match fun_ty with
            | YFun(domain,range,_) ->
                match codegenClosureBody env "Wasm" jp_body key with
                | domain_args, body, sourceName ->
                    let closure_name = generatedClosureName sourceName tag
                    closure_names.Add $"${closure_name}"
                    fun_type (domain, range) |> ignore
                    emit_function closure_name None (data_free_vars domain_args) (rdata_free_vars args) "" range body
            | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."))
        and closure (a, b) : {| tag : int |} = {| tag = closure_memo.Force() (a, b) |}
        and self_tail tag (body : TypedBind []) =
            body.Length > 0 &&
            match Array.last body with
            | TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _) -> (method (a,c)).tag = tag
            | TyLocalReturnOp(_, TyIf(_,tr,fl), _) -> self_tail tag tr || self_tail tag fl
            | TyLocalReturnOp(_, TyIntSwitch(_,on_succ,on_fail), _) -> Array.exists (self_tail tag) on_succ || self_tail tag on_fail
            | TyLocalReturnOp(_, (TyDo b | TyIndent b), _) -> self_tail tag b
            | _ -> false

        let unitMain =
            match Array.tryLast x with
            | Some (TyLocalReturnOp(_,_,d)) | Some (TyLocalReturnData(d,_)) ->
                match data_term_vars d |> Array.map (function WV(L(_,t)) -> t | WLit l -> YPrim (lit_to_primitive_type l)) with
                | [||] -> true
                | [|YPrim Int32T|] -> false
                | _ -> raise_codegen_error "The return type of main in the Wasm backend should be a 32-bit int (or unit)."
            | _ -> true
        if unitMain then
            emit_function "spiralMainUnit" None [||] [||] "" YB x
            functions.Add("  (func $spiralMain (result i32)\n    (call $spiralMainUnit)\n    (i32.const 0))")
        else emit_function "spiralMain" None [||] [||] "" (YPrim Int32T) x
        let heap_start = (data_end + 7) &&& ~~~7
        let pages = heap_start / 65536 + 2
        let prelude_fields = ResizeArray<string>()
        let prelude_helpers = ResizeArray<string * string>()
        let current_helper : (string * StringBuilder) option ref = ref None
        let close_helper () =
            match current_helper.Value with
            | Some (name, text) -> prelude_helpers.Add((name, text.ToString()))
            | None -> ()
            current_helper.Value <- None
        for prelude_line in wasmPrelude.Split('\n') do
            if prelude_line.StartsWith "  (func $" then
                close_helper ()
                let name = prelude_line.Substring(9).Split([|' '; ')'|]).[0]
                current_helper.Value <- Some (name, StringBuilder().AppendLine(prelude_line))
            elif prelude_line.StartsWith "  (" then
                close_helper ()
                prelude_fields.Add prelude_line
            elif prelude_line.Trim() <> "" then
                match current_helper.Value with
                | Some (_, text) -> text.AppendLine(prelude_line) |> ignore
                | None -> prelude_fields.Add prelude_line
        close_helper ()
        let called (text : string) =
            Text.RegularExpressions.Regex.Matches(text, @"call \$([A-Za-z0-9_]+)") |> Seq.map (fun m -> m.Groups.[1].Value)
        let helper_text = dict prelude_helpers
        let needed = HashSet<string>()
        let pending = Stack<string>()
        let reach (text : string) = for name in called text do if needed.Add name then pending.Push name
        Seq.concat [seq env.globals; seq globals; seq functions] |> Seq.iter reach
        reach "call $spiralMain"
        while pending.Count > 0 do
            match helper_text.TryGetValue (pending.Pop()) with
            | true, text -> reach text
            | _ -> ()
        let program = StringBuilder()
        program.AppendLine("(module") |> ignore
        let emitted_text =
            Seq.concat [seq env.globals; seq globals; seq functions; prelude_helpers |> Seq.filter (fun (name, _) -> needed.Contains name) |> Seq.map snd]
            |> String.concat "\n"
        let prelude_field_needed (field : string) =
            let import = Text.RegularExpressions.Regex.Match(field, @"^  \(import ""[^""]+"" ""[^""]+"" \(func \$([A-Za-z0-9_]+)")
            let segment = Text.RegularExpressions.Regex.Match(field, @"^  \(data \(i32\.const ([0-9]+)\)")
            if import.Success then import.Groups.[1].Value = "proc_exit" || needed.Contains import.Groups.[1].Value
            elif segment.Success then Text.RegularExpressions.Regex.IsMatch(emitted_text, @"i32\.const " + segment.Groups.[1].Value + @"\b")
            else true
        prelude_fields |> Seq.iter (fun x -> if prelude_field_needed x then program.AppendLine(x) |> ignore)
        prelude_helpers |> Seq.iter (fun (name, text) -> if needed.Contains name then program.Append(text) |> ignore)
        program.AppendLine($"  (memory (export \"memory\") {pages})") |> ignore
        program.AppendLine($"  (global $hp (mut i32) (i32.const {heap_start}))") |> ignore
        env.globals |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        globals |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        types |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
        if closure_names.Count > 0 then
            program.AppendLine($"  (table $closures {closure_names.Count} funcref)") |> ignore
            program.AppendLine("  (elem (table $closures) (i32.const 0) func " + String.concat " " closure_names + ")") |> ignore
        functions |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
        data |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
        program.AppendLine("  (func $_start (export \"_start\")\n    (call $proc_exit (call $spiralMain)))") |> ignore
        program.AppendLine(")").ToString()

    /// ## CodegenWgsl
    // WGSL has no recursion and no function pointers. Self-tail calls become loops.
    // Everything else that would need a call stack or a closure is rejected.
    // The compute entry writes main's i32 into a storage buffer; spiral-wgsl reads it back.

    /// ### WgslRet
    type WgslRet =
        | WgslLocal of TyV []
        | WgslTail of Ty

    /// ### spiralWgslW64Helpers
    let spiralWgslW64Helpers = """struct SpiralW64DivMod {
  q: vec2<u32>,
  r: vec2<u32>,
}
fn spiral_w64_add(a: vec2<u32>, b: vec2<u32>) -> vec2<u32> {
  let lo = a.x + b.x;
  return vec2<u32>(lo, a.y + b.y + select(0u, 1u, lo < a.x));
}
fn spiral_w64_neg(a: vec2<u32>) -> vec2<u32> { return spiral_w64_add(~a, vec2<u32>(1u, 0u)); }
fn spiral_w64_sub(a: vec2<u32>, b: vec2<u32>) -> vec2<u32> { return spiral_w64_add(a, spiral_w64_neg(b)); }
fn spiral_w32_wide_mul(a: u32, b: u32) -> vec2<u32> {
  let a0 = a & 0xFFFFu;
  let a1 = a >> 16u;
  let b0 = b & 0xFFFFu;
  let b1 = b >> 16u;
  let p00 = a0 * b0;
  let p01 = a0 * b1;
  let p10 = a1 * b0;
  let mid = (p00 >> 16u) + (p01 & 0xFFFFu) + (p10 & 0xFFFFu);
  return vec2<u32>((p00 & 0xFFFFu) | (mid << 16u), a1 * b1 + (p01 >> 16u) + (p10 >> 16u) + (mid >> 16u));
}
fn spiral_w64_mul(a: vec2<u32>, b: vec2<u32>) -> vec2<u32> {
  let low = spiral_w32_wide_mul(a.x, b.x);
  return vec2<u32>(low.x, low.y + a.x * b.y + a.y * b.x);
}
fn spiral_u64_lt(a: vec2<u32>, b: vec2<u32>) -> bool { return a.y < b.y || (a.y == b.y && a.x < b.x); }
fn spiral_i64_lt(a: vec2<u32>, b: vec2<u32>) -> bool {
  let sa = bitcast<i32>(a.y);
  let sb = bitcast<i32>(b.y);
  return sa < sb || (sa == sb && a.x < b.x);
}
fn spiral_w64_shl(a: vec2<u32>, n: u32) -> vec2<u32> {
  let k = n & 63u;
  if (k == 0u) { return a; }
  if (k >= 32u) { return vec2<u32>(0u, a.x << (k - 32u)); }
  return vec2<u32>(a.x << k, (a.y << k) | (a.x >> (32u - k)));
}
fn spiral_u64_shr(a: vec2<u32>, n: u32) -> vec2<u32> {
  let k = n & 63u;
  if (k == 0u) { return a; }
  if (k >= 32u) { return vec2<u32>(a.y >> (k - 32u), 0u); }
  return vec2<u32>((a.x >> k) | (a.y << (32u - k)), a.y >> k);
}
fn spiral_i64_shr(a: vec2<u32>, n: u32) -> vec2<u32> {
  let k = n & 63u;
  let high = bitcast<i32>(a.y);
  if (k == 0u) { return a; }
  if (k >= 32u) { return vec2<u32>(bitcast<u32>(high >> (k - 32u)), select(0u, 0xFFFFFFFFu, high < 0i)); }
  return vec2<u32>((a.x >> k) | (a.y << (32u - k)), bitcast<u32>(high >> k));
}
fn spiral_u64_divmod(a: vec2<u32>, b: vec2<u32>) -> SpiralW64DivMod {
  var q = vec2<u32>(0u, 0u);
  var r = vec2<u32>(0u, 0u);
  for (var i = 63i; i >= 0i; i = i - 1i) {
    r = spiral_w64_shl(r, 1u);
    let word = select(a.x, a.y, i >= 32i);
    r.x = r.x | ((word >> (u32(i) & 31u)) & 1u);
    if (!spiral_u64_lt(r, b)) {
      r = spiral_w64_sub(r, b);
      if (i >= 32i) { q.y = q.y | (1u << (u32(i) - 32u)); } else { q.x = q.x | (1u << u32(i)); }
    }
  }
  return SpiralW64DivMod(q, r);
}
fn spiral_i64_negative(a: vec2<u32>) -> bool { return bitcast<i32>(a.y) < 0i; }
fn spiral_i64_magnitude(a: vec2<u32>) -> vec2<u32> { return select(a, spiral_w64_neg(a), spiral_i64_negative(a)); }
fn spiral_i64_div(a: vec2<u32>, b: vec2<u32>) -> vec2<u32> {
  let q = spiral_u64_divmod(spiral_i64_magnitude(a), spiral_i64_magnitude(b)).q;
  return select(q, spiral_w64_neg(q), spiral_i64_negative(a) != spiral_i64_negative(b));
}
fn spiral_i64_mod(a: vec2<u32>, b: vec2<u32>) -> vec2<u32> {
  let r = spiral_u64_divmod(spiral_i64_magnitude(a), spiral_i64_magnitude(b)).r;
  return select(r, spiral_w64_neg(r), spiral_i64_negative(a));
}
fn spiral_w64_of_f32(v: f32, is_signed: bool) -> vec2<u32> {
  let m = abs(trunc(v));
  let hi = floor(m / 4294967296.0f);
  let magnitude = vec2<u32>(u32(m - hi * 4294967296.0f), u32(hi));
  return select(magnitude, spiral_w64_neg(magnitude), is_signed && v < 0.0f);
}
fn spiral_f32_of_w64(a: vec2<u32>, is_signed: bool) -> f32 {
  let negative = is_signed && spiral_i64_negative(a);
  let m = select(a, spiral_w64_neg(a), negative);
  let v = f32(m.y) * 4294967296.0f + f32(m.x);
  return select(v, -v, negative);
}
"""

    /// ### codegenWgsl
    let codegenWgsl (env : PartEvalResult) (x : TypedBind []) =
        let functions = ResizeArray<string>()
        let tuple_bodies = ResizeArray<string>()
        let tuple_names = Dictionary<string, string>()
        let method_names = Dictionary<int, string>()
        let methods_being_emitted = HashSet<int>()
        let unsupported what = raise_codegen_error $"The WGSL backend doesn't support {what} yet."
        let next_id = ref 0
        let fresh_id () = next_id.Value <- next_id.Value + 1; next_id.Value
        let is_unit_ty = function YB -> true | _ -> false
        let case_payloads (h : Union) = h.Item.tag_cases |> Array.map (fun case -> match box case with null -> YB | _ -> snd case)
        let is_tag_only_union (h : Union) = case_payloads h |> Array.forall is_unit_ty
        let union_layouts = Dictionary<obj, string * string [] []>(HashIdentity.Reference)
        let unions_being_laid_out = HashSet<obj>(HashIdentity.Reference)
        let uses_heap = ref false
        let uses_w64 = ref false
        let rec tyv = function
            | YPrim Int32T | YPrim CharT -> "i32"
            | YPrim UInt32T -> "u32"
            | YPrim (Int8T | Int16T) -> "i32"
            | YPrim (UInt8T | UInt16T) -> "u32"
            | YPrim BoolT -> "bool"
            | YPrim Float32T -> "f32"
            | YPrim Float64T -> unsupported "f64 (WGSL has no 64-bit float)"
            | YPrim (Int64T | UInt64T) -> uses_w64.Value <- true; "vec2<u32>"
            | YPrim t -> unsupported $"the primitive {t}"
            | YUnion h when is_tag_only_union h -> "u32"
            | YUnion h -> fst (union_layout h)
            | YArray _ -> "u32"
            | YNominal _ | YApply _ as t -> tyv (env.nominal_apply t)
            | t -> unsupported $"""the type {show_ty t} ({(sprintf "%A" t).Split([|' '; '('|]).[0]})"""
        and union_layout (h : Union) : string * string [] [] =
            let key = box h.Item
            match union_layouts.TryGetValue key with
            | true, layout -> layout
            | _ ->
                if not (unions_being_laid_out.Add key) then unsupported "recursive unions (WGSL has no pointers)"
                let case_fields = case_payloads h |> Array.map (fun payload -> env.ty_to_data payload |> data_free_vars |> Array.map (fun (L(_,t)) -> tyv t))
                let name = $"SpiralUnion{union_layouts.Count}"
                let fields = case_fields |> Array.mapi (fun case tys -> tys |> Array.mapi (fun field t -> $"  c{case}f{field}: {t},")) |> Array.concat
                tuple_bodies.Add($"""struct {name} {{{"\n"}{String.concat "\n" (Array.append [|"  tag: u32,"|] fields)}{"\n"}}}{"\n"}""")
                unions_being_laid_out.Remove key |> ignore
                union_layouts.[key] <- (name, case_fields)
                name, case_fields
        let zero = function
            | "i32" -> "0i"
            | "u32" -> "0u"
            | "bool" -> "false"
            | "f32" -> "0.0f"
            | "vec2<u32>" -> "vec2<u32>(0u, 0u)"
            | other when other.StartsWith "Spiral" -> $"{other}()"
            | other -> unsupported $"a zero value of {other}"
        let array_element_tys = function
            | YArray element -> env.ty_to_data element |> data_free_vars |> Array.map (fun (L(_, t)) -> t)
            | _ -> raise_codegen_error "Compiler error: Expected an array type."
        let array_element_ty array_ty =
            match array_element_tys array_ty with
            | [|t|] -> t
            | _ -> unsupported "arrays whose element is more than one value here"
        let array_ty_of = function
            | DV(L(_, t)) -> t
            | _ -> raise_codegen_error "Compiler error: Expected an array variable."
        let to_heap_word scalar value =
            match scalar with
            | "i32" | "f32" -> $"bitcast<u32>({value})"
            | "u32" -> value
            | "bool" -> $"select(0u, 1u, {value})"
            | other -> unsupported $"array elements of type {other}"
        let from_heap_word scalar word =
            match scalar with
            | "i32" -> $"bitcast<i32>({word})"
            | "f32" -> $"bitcast<f32>({word})"
            | "u32" -> word
            | "bool" -> $"({word} != 0u)"
            | other -> unsupported $"array elements of type {other}"
        let rec element_words (t : Ty) : (string * string) list =
            match t with
            | YUnion h when not (is_tag_only_union h) ->
                let _, case_fields = union_layout h
                let field_tys = case_payloads h |> Array.map (fun payload -> env.ty_to_data payload |> data_free_vars |> Array.map (fun (L(_,t)) -> t))
                ("tag", "u32") :: [ for case in 0 .. case_fields.Length - 1 do
                                        for field in 0 .. field_tys.[case].Length - 1 do
                                            for path, scalar in element_words field_tys.[case].[field] do
                                                yield (if path = "" then $"c{case}f{field}" else $"c{case}f{field}.{path}"), scalar ]
            | YNominal _ | YApply _ -> element_words (env.nominal_apply t)
            | YPrim (Int64T | UInt64T) -> uses_w64.Value <- true; [("x", "u32"); ("y", "u32")]
            | t -> [("", tyv t)]
        let rec element_value (t : Ty) (word_at : int -> string) (offset : int) : string * int =
            match t with
            | YUnion h when not (is_tag_only_union h) ->
                let name, _ = union_layout h
                let field_tys = case_payloads h |> Array.map (fun payload -> env.ty_to_data payload |> data_free_vars |> Array.map (fun (L(_,t)) -> t))
                let next = ref (offset + 1)
                let fields = [ for tys in field_tys do
                                for ft in tys do
                                    let value, after = element_value ft word_at next.Value
                                    next.Value <- after
                                    yield value ]
                $"""{name}({String.concat ", " (from_heap_word "u32" (word_at offset) :: fields)})""", next.Value
            | YNominal _ | YApply _ -> element_value (env.nominal_apply t) word_at offset
            | YPrim (Int64T | UInt64T) -> uses_w64.Value <- true; $"vec2<u32>({word_at offset}, {word_at (offset + 1)})", offset + 2
            | t -> from_heap_word (tyv t) (word_at offset), offset + 1
        let heap_word_at array index stride k = $"spiral_heap[{array} + 1u + bitcast<u32>({index}) * {stride}u + {k}u]"
        let element_stride (tys : Ty []) = tys |> Array.sumBy (fun t -> (element_words t).Length)
        let element_reads (tys : Ty []) (word_at : int -> string) =
            let next = ref 0
            tys |> Array.map (fun t ->
                let value, after = element_value t word_at next.Value
                next.Value <- after
                value)
        let element_writes (tys : Ty []) (values : string []) (word_at : int -> string) =
            let next = ref 0
            Array.map2 (fun t (value : string) ->
                element_words t |> List.map (fun (path, scalar) ->
                    let field = if path = "" then value else $"{value}.{path}"
                    let k = next.Value
                    next.Value <- k + 1
                    $"{word_at k} = {to_heap_word scalar field}")) tys values
            |> List.concat |> String.concat "; "
        let lit = function
            | LitInt32 x when x = Int32.MinValue -> "bitcast<i32>(0x80000000u)"
            | LitInt32 x -> $"{x}i"
            | LitUInt32 x -> $"{x}u"
            | LitBool x -> if x then "true" else "false"
            | LitChar x -> $"{int x}i"
            | LitInt8 x -> $"{int x}i"
            | LitInt16 x -> $"{int x}i"
            | LitUInt8 x -> $"{int x}u"
            | LitUInt16 x -> $"{int x}u"
            | LitInt64 x -> uses_w64.Value <- true; $"vec2<u32>({uint64 x &&& 0xFFFFFFFFUL}u, {uint64 x >>> 32}u)"
            | LitUInt64 x -> uses_w64.Value <- true; $"vec2<u32>({x &&& 0xFFFFFFFFUL}u, {x >>> 32}u)"
            | LitFloat32 x when Single.IsNaN x -> "(0.0f / 0.0f)"
            | LitFloat32 x when Single.IsPositiveInfinity x -> "(1.0f / 0.0f)"
            | LitFloat32 x when Single.IsNegativeInfinity x -> "(-1.0f / 0.0f)"
            | LitFloat32 x ->
                let text = x.ToString("R", Globalization.CultureInfo.InvariantCulture)
                let text = if text.Contains('.') || text.Contains('e') || text.Contains('E') then text else text + ".0"
                text + "f"
            | l -> unsupported $"the literal %A{l}"
        let show_w = function WV (L(i,_)) -> $"v{i}" | WLit a -> lit a
        let prim_of = function
            | DV(L(_,YPrim t)) -> Some t
            | DLit l -> Some (lit_to_primitive_type l)
            | _ -> None
        let narrow t (x : string) =
            match t with
            | Int8T -> $"(({x} << 24u) >> 24u)"
            | Int16T -> $"(({x} << 16u) >> 16u)"
            | UInt8T -> $"({x} & 0xFFu)"
            | UInt16T -> $"({x} & 0xFFFFu)"
            | _ -> x
        let is_subword = function Int8T | Int16T | UInt8T | UInt16T -> true | _ -> false
        let integer_word = function
            | Int8T | Int16T | Int32T | CharT -> Some "i32"
            | UInt8T | UInt16T | UInt32T -> Some "u32"
            | _ -> None
        let wgsl_of d =
            match prim_of d with
            | Some t -> tyv (YPrim t)
            | None -> unsupported "an operation on a non-primitive"
        let tup d =
            match data_term_vars d with
            | [|w|] -> show_w w
            | [||] -> ""
            | _ -> unsupported "tuple values"
        let flatten_ty t = env.ty_to_data t |> data_free_vars |> Array.map (fun (L(_,t)) -> t)
        let tuple_name (tys : string []) =
            let key = String.concat "," tys
            match tuple_names.TryGetValue key with
            | true, name -> name
            | _ ->
                let name = $"SpiralTuple{tuple_names.Count}"
                tuple_names.[key] <- name
                let fields = tys |> Array.mapi (fun i t -> $"  v{i}: {t},") |> String.concat "\n"
                tuple_bodies.Add($"struct {name} {{\n{fields}\n}}\n")
                name
        let ret_ty range =
            match flatten_ty range |> Array.map tyv with
            | [||] -> ""
            | [|t|] -> t
            | tys -> tuple_name tys
        let self_loop : (int * TyV []) option ref = ref None
        let rec emit_function (name : string) (tag : int option) (parameters : TyV []) (range : Ty) (body : TypedBind []) =
            let saved = self_loop.Value
            let tail = match tag with Some t when self_tail t body -> true | _ -> false
            if tail then self_loop.Value <- Some (tag.Value, parameters)
            try
                let text = StringBuilder()
                let formals = parameters |> Array.map (fun (L(i,t)) -> $"p{i}: {tyv t}") |> String.concat ", "
                let result = ret_ty range
                let returns = if result = "" then "" else $" -> {result}"
                text.AppendLine($"fn {name}({formals}){returns} {{") |> ignore
                let s0 = { text = text; indent = 4 }
                parameters |> Array.iter (fun (L(i,t)) -> line s0 $"var v{i}: {tyv t} = p{i};")
                if tail then
                    line s0 "loop {"
                    binds (indent s0) (WgslTail range) body
                    line s0 "}"
                    // The validator treats fallthrough after a loop that never breaks
                    // as a valueless return, so a value-returning function needs a dead return.
                    if result <> "" then
                        let dead =
                            match flatten_ty range |> Array.map tyv with
                            | [|t|] -> zero t
                            | tys ->
                                let zeros = tys |> Array.map zero |> String.concat ", "
                                $"{result}({zeros})"
                        line s0 $"return {dead};"
                else binds s0 (WgslTail range) body
                text.AppendLine("}") |> ignore
                functions.Add(text.ToString())
            finally
                self_loop.Value <- saved
        and returned_call_as_tail (body : TypedBind []) =
            let n = body.Length
            if n < 2 then body else
            match body.[n - 2], body.[n - 1] with
            | TyLet(bound, trace, call), TyLocalReturnData(returned, _) ->
                let bound_ids = data_free_vars bound |> Array.map (fun (L(i,_)) -> i)
                let returned_ids = data_term_vars returned |> Array.choose (function WV(L(i,_)) -> Some i | WLit _ -> None)
                if bound_ids.Length = (data_term_vars returned).Length && bound_ids = returned_ids
                then Array.append body.[.. n - 3] [| TyLocalReturnOp(trace, call, bound) |]
                else body
            | _ -> body
        and self_tail tag (body : TypedBind []) =
            let body = returned_call_as_tail body
            body.Length > 0 &&
            match Array.last body with
            | TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _) -> (method (a,c)).tag = tag
            | TyLocalReturnOp(_, TyIf(_,tr,fl), _) -> self_tail tag tr || self_tail tag fl
            | TyLocalReturnOp(_, TyUnionUnbox(_,_,on_succs,on_fail), _) -> (on_succs |> Map.exists (fun _ (_,b) -> self_tail tag b)) || (on_fail |> Option.exists (self_tail tag))
            | TyLocalReturnOp(_, TyIntSwitch(_,on_succ,on_fail), _) -> Array.exists (self_tail tag) on_succ || self_tail tag on_fail
            | TyLocalReturnOp(_, (TyDo b | TyIndent b), _) -> self_tail tag b
            | _ -> false
        and binds (s : CodegenEnv) (ret : WgslRet) (stmts : TypedBind []) =
            let stmts = match ret with WgslTail _ -> returned_call_as_tail stmts | WgslLocal _ -> stmts
            Array.iter (function
                | TyLet(d,trace,a) ->
                    try
                        let vs = data_free_vars d
                        vs |> Array.iter (fun (L(i,t)) -> line s $"var v{i}: {tyv t} = {zero (tyv t)};")
                        op s (WgslLocal vs) a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) ->
                    try op s ret a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) ->
                    try
                        match ret with
                        | WgslLocal targets ->
                            let values = data_term_vars d
                            if targets.Length <> values.Length then raise_codegen_error "Compiler error: A binding has the wrong number of values."
                            Array.iter2 (fun (L(i,_)) w -> line s $"v{i} = {show_w w};") targets values
                        | WgslTail range ->
                            match data_term_vars d with
                            | [||] -> if self_loop.Value.IsSome then line s "return;"
                            | [|w|] -> line s $"return {show_w w};"
                            | many ->
                                let args = many |> Array.map show_w |> String.concat ", "
                                line s $"return {ret_ty range}({args});"
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) stmts
        and op (s : CodegenEnv) (ret : WgslRet) a =
            let return' (x : string) =
                match ret with
                | WgslLocal [||] -> if x <> "" then line s $"{x};"
                | WgslLocal [|L(i,_)|] -> line s $"v{i} = {x};"
                | WgslLocal targets ->
                    let name = $"spiral_tuple{fresh_id ()}"
                    line s $"let {name} = {x};"
                    targets |> Array.iteri (fun k (L(i,_)) -> line s $"v{i} = {name}.v{k};")
                | WgslTail range when is_unit_ty range ->
                    if x <> "" then line s $"{x};"
                    if self_loop.Value.IsSome then line s "return;"
                | WgslTail _ -> line s $"return {x};"
            let jp_text (jp, args) =
                match jp with
                | JPMethod(a,c) ->
                    let tag = (method (a,c)).tag
                    if methods_being_emitted.Contains tag then unsupported "recursion that is not a self-tail call (WGSL has no call stack)"
                    let name = method_names.[tag]
                    let arguments = args |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
                    $"{name}({arguments})"
                | JPClosure _ -> unsupported "closures (WGSL has no function pointers)"
            let is_self (a, c) =
                match ret, self_loop.Value with
                | WgslTail _, Some (tag, _) -> (method (a,c)).tag = tag
                | _ -> false
            match a with
            | TyIf(cond,tr,fl) ->
                line s $"if ({tup cond}) {{"
                binds (indent s) ret tr
                line s "} else {"
                binds (indent s) ret fl
                line s "}"
            | TyJoinPoint(JPMethod(a,c), arguments) when is_self (a, c) ->
                let _, parameters = self_loop.Value.Value
                if arguments.Length <> parameters.Length then raise_codegen_error "Compiler error: A tail call has the wrong number of arguments."
                let types = parameters |> Array.map (fun (L(i,t)) -> i, t) |> dict
                let temps = System.Collections.Generic.Dictionary<int, string> ()
                for step in parallelMoves (Array.map2 (fun (L(target,_)) (L(source,_)) -> target, source) parameters arguments) do
                    match step with
                    | MoveVar (target, source) -> line s $"v{target} = v{source};"
                    | SaveTemp (slot, source) ->
                        temps.[slot] <- $"spiral_t{fresh_id ()}"
                        line s $"let {temps.[slot]}: {tyv types.[source]} = v{source};"
                    | MoveTemp (target, slot) -> line s $"v{target} = {temps.[slot]};"
                line s "continue;"
            | TyJoinPoint(jp, args) -> return' (jp_text (jp, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The WGSL backend does not support nesting other backends."
            | TyWhile(cond, body) ->
                match ret with
                | WgslLocal [||] -> ()
                | WgslTail range when is_unit_ty range -> ()
                | _ -> unsupported "a while loop in value position"
                line s "loop {"
                line (indent s) $"if (!({jp_text cond})) {{ break; }}"
                binds (indent s) (WgslLocal [||]) body
                line s "}"
                match ret with
                | WgslTail _ when self_loop.Value.IsSome -> line s "return;"
                | _ -> ()
            | TyDo body | TyIndent body -> binds s ret body
            | TyUnionBox(tag_id, _, h) when is_tag_only_union h -> return' $"{h.Item.tags.[tag_id]}u"
            | TyUnionBox(tag_id, payload, h) ->
                let name, case_fields = union_layout h
                let case = h.Item.tags.[tag_id]
                let values = data_term_vars payload |> Array.map show_w
                if values.Length <> case_fields.[case].Length then raise_codegen_error "Compiler error: A union payload has the wrong number of values."
                let fields = case_fields |> Array.mapi (fun other tys -> if other = case then values else Array.map zero tys) |> Array.concat
                return' $"""{name}({String.concat ", " (Array.append [|$"{case}u"|] fields)})"""
            | TyUnionUnbox(scrutinees, h, on_succs, on_fail) when not scrutinees.IsEmpty ->
                let tag_only = is_tag_only_union h
                let tag_of (L(i,_)) = if tag_only then $"v{i}" else $"v{i}.tag"
                let arm s' (case, payloads, body) =
                    if not tag_only then
                        List.iter2 (fun (L(i,_)) payload ->
                            data_free_vars payload |> Array.iteri (fun field (L(vi, t)) -> line s' $"var v{vi}: {tyv t} = v{i}.c{case}f{field};")) scrutinees payloads
                    binds s' ret body
                let arms = on_succs |> Map.toArray |> Array.map (fun (tag_id, (payloads, body)) -> h.Item.tags.[tag_id], payloads, body) |> Array.sortBy (fun (case, _, _) -> case)
                let guarded, last_branch =
                    match on_fail with
                    | Some fallback -> arms, (fun s' -> binds s' ret fallback)
                    | None when arms.Length > 0 -> Array.take (arms.Length - 1) arms, (fun s' -> arm s' (Array.last arms))
                    | None -> raise_codegen_error "Compiler error: A union unbox has no cases and no fallback."
                if guarded.Length = 0 then last_branch s
                else
                    guarded |> Array.iteri (fun n (case, payloads, body) ->
                        let keyword = if n = 0 then "if" else "} else if"
                        let condition = scrutinees |> List.map (fun v -> $"{tag_of v} == {case}u") |> String.concat " && "
                        line s $"{keyword} ({condition}) {{"
                        arm (indent s) (case, payloads, body))
                    line s "} else {"
                    last_branch (indent s)
                    line s "}"
            | TyConv(YPrim target, b) ->
                let source = prim_of b
                let text = tup b
                let same =
                    match source with
                    | Some s when s = target -> true
                    | Some CharT when target = Int32T -> true
                    | Some Int32T when target = CharT -> true
                    | _ -> false
                let converted =
                    if same then text
                    else
                        match source, target with
                        | Some (Int64T | UInt64T), (Int64T | UInt64T) -> text
                        | Some (Int64T | UInt64T), t when (integer_word t).IsSome -> narrow t (if integer_word t = Some "i32" then $"bitcast<i32>({text}.x)" else $"{text}.x")
                        | Some s, (Int64T | UInt64T) when integer_word s = Some "i32" -> $"vec2<u32>(bitcast<u32>({text}), select(0u, 0xFFFFFFFFu, {text} < 0i))"
                        | Some s, (Int64T | UInt64T) when integer_word s = Some "u32" -> $"vec2<u32>({text}, 0u)"
                        | Some Float32T, (Int64T | UInt64T) -> $"spiral_w64_of_f32({text}, {(target = Int64T).ToString().ToLowerInvariant()})"
                        | Some (Int64T | UInt64T as s), Float32T -> $"spiral_f32_of_w64({text}, {(s = Int64T).ToString().ToLowerInvariant()})"
                        | Some BoolT, (Int64T | UInt64T) -> $"vec2<u32>(select(0u, 1u, {text}), 0u)"
                        | Some s, t when (is_subword s || is_subword t) && (integer_word s).IsSome && (integer_word t).IsSome ->
                            let from_word, to_word = (integer_word s).Value, (integer_word t).Value
                            narrow t (if from_word = to_word then text else $"bitcast<{to_word}>({text})")
                        | Some Float32T, (Int8T | Int16T) -> narrow target $"i32({text})"
                        | Some Float32T, (UInt8T | UInt16T) -> narrow target $"u32({text})"
                        | Some (Int8T | Int16T | UInt8T | UInt16T), Float32T -> $"f32({text})"
                        | Some BoolT, (Int8T | Int16T) -> $"select(0i, 1i, {text})"
                        | Some BoolT, (UInt8T | UInt16T) -> $"select(0u, 1u, {text})"
                        | Some (Int32T | CharT), UInt32T | Some UInt32T, (Int32T | CharT) -> $"bitcast<{tyv (YPrim target)}>({text})"
                        | Some (Int32T | UInt32T | CharT), Float32T -> $"f32({text})"
                        | Some Float32T, (Int32T | CharT) -> $"i32({text})"
                        | Some Float32T, UInt32T -> $"u32({text})"
                        | Some BoolT, (Int32T | CharT) -> $"select(0i, 1i, {text})"
                        | Some (Int32T | CharT), BoolT -> $"({text} != 0i)"
                        | _ -> unsupported "this conversion"
                return' converted
            | TyFailwith _ -> unsupported "failwith"
            | TyMacro parts ->
                let piece = function
                    | CMText x -> x
                    | CMTerm (x, true) -> data_term_vars x |> Array.map show_w |> String.concat ", "
                    | CMTerm (x, false) -> tup x
                    | CMType x -> tyv x
                    | CMTypeLit _ -> unsupported "a macro type literal"
                return' (parts |> List.map piece |> String.concat "")
            | TyOp(Global, _) -> unsupported "globals"
            | TyOp(ArrayIndex, [a;b]) when (array_element_tys (array_ty_of a)).Length > 1 ->
                let tys = array_element_tys (array_ty_of a)
                let values = element_reads tys (heap_word_at (tup a) (tup b) (element_stride tys))
                match ret with
                | WgslLocal targets when targets.Length = values.Length ->
                    Array.iter2 (fun (L(i,_)) value -> line s $"v{i} = {value};") targets values
                | WgslTail range ->
                    line s $"""return {ret_ty range}({String.concat ", " values});"""
                | _ -> raise_codegen_error "Compiler error: An array read has the wrong number of targets."
            | TyOp(operation, l) ->
                let binary symbol a b = $"({tup a} {symbol} {tup b})"
                // WGSL shifts take a u32 count. Signed `>>` stays arithmetic.
                let shift symbol a b =
                    let count = if wgsl_of b = "u32" then tup b else $"bitcast<u32>({tup b})"
                    $"({tup a} {symbol} {count})"
                let subword_of a = match prim_of a with Some t when is_subword t -> Some t | _ -> None
                let wide_of a = match prim_of a with Some (Int64T | UInt64T as t) -> Some t | _ -> None
                let wide_count b = match prim_of b with Some (Int64T | UInt64T) -> $"{tup b}.x" | _ -> (if wgsl_of b = "u32" then tup b else $"bitcast<u32>({tup b})")
                let expr =
                    match operation, l with
                    | (Add | Sub | Mult | Div | Mod | LT | LTE | GT | GTE | EQ | NEQ | ShiftLeft | ShiftRight), [a;b] when (wide_of a).IsSome ->
                        let signed = wide_of a = Some Int64T
                        let lt x y = if signed then $"spiral_i64_lt({x}, {y})" else $"spiral_u64_lt({x}, {y})"
                        match operation with
                        | Add -> $"spiral_w64_add({tup a}, {tup b})"
                        | Sub -> $"spiral_w64_sub({tup a}, {tup b})"
                        | Mult -> $"spiral_w64_mul({tup a}, {tup b})"
                        | Div -> if signed then $"spiral_i64_div({tup a}, {tup b})" else $"spiral_u64_divmod({tup a}, {tup b}).q"
                        | Mod -> if signed then $"spiral_i64_mod({tup a}, {tup b})" else $"spiral_u64_divmod({tup a}, {tup b}).r"
                        | LT -> lt (tup a) (tup b)
                        | LTE -> $"(!{lt (tup b) (tup a)})"
                        | GT -> lt (tup b) (tup a)
                        | GTE -> $"(!{lt (tup a) (tup b)})"
                        | EQ -> $"all({tup a} == {tup b})"
                        | NEQ -> $"any({tup a} != {tup b})"
                        | ShiftLeft -> $"spiral_w64_shl({tup a}, {wide_count b})"
                        | _ -> if signed then $"spiral_i64_shr({tup a}, {wide_count b})" else $"spiral_u64_shr({tup a}, {wide_count b})"
                    | Neg, [a] when (wide_of a).IsSome -> $"spiral_w64_neg({tup a})"
                    | (Add | Sub | Mult | Div | ShiftLeft), [a;b] when (subword_of a).IsSome ->
                        let wide = match operation with Add -> binary "+" a b | Sub -> binary "-" a b | Mult -> binary "*" a b | Div -> binary "/" a b | _ -> shift "<<" a b
                        narrow (subword_of a).Value wide
                    | (Neg | BitwiseComplement), [a] when (subword_of a).IsSome ->
                        narrow (subword_of a).Value (match operation with Neg -> $"(-{tup a})" | _ -> $"(~{tup a})")
                    | Dyn, [a] -> tup a
                    | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                    | Add, [a;b] -> binary "+" a b
                    | Sub, [a;b] -> binary "-" a b
                    | Mult, [a;b] -> binary "*" a b
                    | Div, [a;b] -> binary "/" a b
                    | Mod, [a;b] -> binary "%" a b
                    | LT, [a;b] -> binary "<" a b
                    | LTE, [a;b] -> binary "<=" a b
                    | GT, [a;b] -> binary ">" a b
                    | GTE, [a;b] -> binary ">=" a b
                    | EQ, [a;b] -> binary "==" a b
                    | NEQ, [a;b] -> binary "!=" a b
                    | BoolAnd, [a;b] -> binary "&&" a b
                    | BoolOr, [a;b] -> binary "||" a b
                    | BitwiseAnd, [a;b] -> binary "&" a b
                    | BitwiseOr, [a;b] -> binary "|" a b
                    | BitwiseXor, [a;b] -> binary "^" a b
                    | BitwiseComplement, [a] -> $"(~{tup a})"
                    | ShiftLeft, [a;b] -> shift "<<" a b
                    | ShiftRight, [a;b] -> shift ">>" a b
                    | Neg, [a] -> $"(-{tup a})"
                    | NanIs, [a] -> $"({tup a} != {tup a})"
                    | StdoutFlush, [] -> ""
                    | ArrayIndex, [a;b] ->
                        let element = array_element_ty (array_ty_of a)
                        let stride = (element_words element).Length
                        fst (element_value element (heap_word_at (tup a) (tup b) stride) 0)
                    | ArrayIndexSet, [a;b;c] ->
                        let tys = array_element_tys (array_ty_of a)
                        let values = data_term_vars c |> Array.map show_w
                        if values.Length <> tys.Length then raise_codegen_error "Compiler error: An array element has the wrong number of values."
                        element_writes tys values (heap_word_at (tup a) (tup b) (element_stride tys))
                    | _ -> unsupported $"the operation %A{operation}"
                return' expr
            | TyArrayCreate(element, size) ->
                let stride = element_stride (array_element_tys (YArray element))
                uses_heap.Value <- true
                return' $"spiral_array_create({tup size}, {stride}u)"
            | TyArrayLength(_, a) -> return' $"bitcast<i32>(spiral_heap[{tup a}])"
            | other ->
                let construct = (sprintf "%A" other).Split('(').[0]
                unsupported construct
        and method_memo = lazy (
            let dict = Dictionary(HashIdentity.Structural)
            fun ((jp_body, key) : _ * _) ->
                match dict.TryGetValue((jp_body, key)) with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[(jp_body, key)] <- tag
                    let args = codegenMethodKeyArgs key
                    match codegenMethodBody env "Wgsl" jp_body key with
                    | body, range, name ->
                        method_names.[tag] <- "sp_" + generatedMethodName name tag
                        methods_being_emitted.Add tag |> ignore
                        emit_function method_names.[tag] (Some tag) (rdata_free_vars args) range body
                        methods_being_emitted.Remove tag |> ignore
                    tag)
        and method (a, b) : {| tag : int |} = {| tag = method_memo.Force() (a, b) |}

        let unit_main =
            match Array.tryLast x with
            | Some (TyLocalReturnOp(_,_,d)) | Some (TyLocalReturnData(d,_)) ->
                match data_term_vars d |> Array.map (function WV(L(_,t)) -> t | WLit l -> YPrim (lit_to_primitive_type l)) with
                | [||] -> true
                | [|YPrim Int32T|] -> false
                | _ -> raise_codegen_error "The return type of main in the WGSL backend should be a 32-bit int (or unit)."
            | _ -> true
        emit_function "spiral_main" None [||] (if unit_main then YB else YPrim Int32T) x
        let program = StringBuilder()
        program.AppendLine("struct SpiralIo {") |> ignore
        program.AppendLine("  code: i32,") |> ignore
        program.AppendLine("  lanes: u32,") |> ignore
        program.AppendLine("  heap_words_per_lane: u32,") |> ignore
        program.AppendLine("  lane_base: u32,") |> ignore
        program.AppendLine("  heap_overflow: atomic<u32>,") |> ignore
        program.AppendLine("}") |> ignore
        program.AppendLine("@group(0) @binding(0) var<storage, read_write> spiral_io: SpiralIo;") |> ignore
        program.AppendLine("@group(0) @binding(2) var<storage, read_write> spiral_results: array<i32>;") |> ignore
        program.AppendLine("var<private> spiral_lane: u32 = 0u;") |> ignore
        if uses_heap.Value then
            program.AppendLine("@group(0) @binding(1) var<storage, read_write> spiral_heap: array<u32>;") |> ignore
            program.AppendLine("var<private> spiral_heap_top: u32 = 0u;") |> ignore
            program.AppendLine("var<private> spiral_heap_end: u32 = 0u;") |> ignore
            program.AppendLine("fn spiral_array_create(length: i32, stride: u32) -> u32 {") |> ignore
            program.AppendLine("  let base = spiral_heap_top;") |> ignore
            program.AppendLine("  let next = base + 1u + bitcast<u32>(length) * stride;") |> ignore
            program.AppendLine("  if (next > spiral_heap_end || next < base) { atomicAdd(&spiral_io.heap_overflow, 1u); }") |> ignore
            program.AppendLine("  if (base < spiral_heap_end) { spiral_heap[base] = bitcast<u32>(length); }") |> ignore
            program.AppendLine("  spiral_heap_top = next;") |> ignore
            program.AppendLine("  return base;") |> ignore
            program.AppendLine("}") |> ignore
        if uses_w64.Value then program.Append(spiralWgslW64Helpers) |> ignore
        tuple_bodies |> Seq.iter (fun text -> program.Append(text) |> ignore)
        functions |> Seq.iter (fun fn -> program.Append(fn) |> ignore)
        program.AppendLine("@compute @workgroup_size(64)") |> ignore
        program.AppendLine("fn main(@builtin(global_invocation_id) invocation: vec3<u32>) {") |> ignore
        program.AppendLine("  let lane_count = max(spiral_io.lanes, 1u);") |> ignore
        program.AppendLine("  let lane = spiral_io.lane_base + invocation.x;") |> ignore
        program.AppendLine("  if (lane >= lane_count) { return; }") |> ignore
        program.AppendLine("  spiral_lane = lane;") |> ignore
        if uses_heap.Value then
            program.AppendLine("  let heap_words = select(arrayLength(&spiral_heap) / lane_count, spiral_io.heap_words_per_lane, spiral_io.heap_words_per_lane > 0u);") |> ignore
            program.AppendLine("  spiral_heap_top = invocation.x * heap_words;") |> ignore
            program.AppendLine("  spiral_heap_end = spiral_heap_top + heap_words;") |> ignore
        if unit_main then
            program.AppendLine("  spiral_main();") |> ignore
            program.AppendLine("  let result = 0i;") |> ignore
        else
            program.AppendLine("  let result = spiral_main();") |> ignore
        program.AppendLine("  spiral_results[spiral_lane] = result;") |> ignore
        program.AppendLine("  if (spiral_lane == 0u) { spiral_io.code = result; }") |> ignore
        program.AppendLine("}") |> ignore
        program.ToString()

    // Calyx has no recursion. Self-tail calls become a while on a go register.
    // The integer subset lowers to one register per local and one group per assignment.
    // component main writes the i32 into the external memory spiral_io; cider dumps it.

    /// ### CalyxRet
    type CalyxRet =
        | CalyxLocal of TyV []
        | CalyxTail of Ty

    /// ### CalyxPart
    type CalyxPart = {
        tag : int option
        cells : ResizeArray<string>
        wires : ResizeArray<string>
        declared : HashSet<int>
        calls : Dictionary<int, string>
        serial : int ref
    }

    /// ### codegenCalyx
    let codegenCalyx (env : PartEvalResult) (x : TypedBind []) =
        let components = ResizeArray<string>()
        let method_info = Dictionary<int, string * int [] * TyV []>()
        let unsupported what = raise_codegen_error $"The Calyx backend doesn't support {what} yet."
        let is_unit_ty = function YB -> true | _ -> false
        let width = function
            | YPrim (Int32T | UInt32T | CharT) -> 32
            | YPrim (Int16T | UInt16T) -> 16
            | YPrim (Int8T | UInt8T) -> 8
            | YPrim BoolT -> 1
            | YPrim Float32T -> unsupported "f32"
            | YPrim Float64T -> unsupported "f64 (Calyx integer subset)"
            | YPrim (Int64T | UInt64T) -> 64
            | YPrim t -> unsupported $"the primitive {t}"
            | t -> unsupported $"the type {show_ty t}"
        let rec flatten_ty t =
            match t with
            | YB -> [||]
            | YPair(a, b) -> Array.append (flatten_ty a) (flatten_ty b)
            | _ -> [|t|]
        let ret_widths range = flatten_ty range |> Array.map width
        let ret_register count index = if count = 1 then "spiral_ret" else sprintf "spiral_ret%d" index
        let out_port count index = if count = 1 then "out" else sprintf "out%d" index
        let lit = function
            | LitInt32 x -> sprintf "32'd%u" (uint32 x)
            | LitUInt32 x -> sprintf "32'd%u" x
            | LitInt16 x -> sprintf "16'd%u" (uint16 x)
            | LitUInt16 x -> sprintf "16'd%u" x
            | LitInt8 x -> sprintf "8'd%u" (uint8 x)
            | LitUInt8 x -> sprintf "8'd%u" x
            | LitInt64 x -> sprintf "64'd%u" (uint64 x)
            | LitUInt64 x -> sprintf "64'd%u" x
            | LitBool true -> "1'd1"
            | LitBool false -> "1'd0"
            | LitChar x -> sprintf "32'd%d" (int x)
            | l -> unsupported $"the literal {l}"
        let show_port = function WV (L(i,_)) -> sprintf "v%d.out" i | WLit a -> lit a
        let prim_of = function
            | DV(L(_,YPrim t)) -> Some t
            | DLit l -> Some (lit_to_primitive_type l)
            | _ -> None
        let width_of d =
            match prim_of d with
            | Some t -> width (YPrim t)
            | None -> unsupported "an operation on a non-primitive"
        let signed_of d =
            match prim_of d with
            | Some (Int64T | Int32T | Int16T | Int8T | CharT) -> true
            | _ -> false
        let is_int_prim = function
            | Int64T | UInt64T | Int32T | UInt32T | Int16T | UInt16T | Int8T | UInt8T | CharT -> true
            | _ -> false
        let is_signed_prim = function
            | Int64T | Int32T | Int16T | Int8T | CharT -> true
            | _ -> false
        let one_port d =
            match data_term_vars d with
            | [|w|] -> show_port w
            | [||] -> unsupported "a unit value where a scalar is required"
            | _ -> unsupported "tuple values"
        let fresh (part : CalyxPart) =
            part.serial.Value <- part.serial.Value + 1
            part.serial.Value
        let add_cell (part : CalyxPart) text = part.cells.Add("    " + text)
        let ensure (part : CalyxPart) i w =
            if part.declared.Add i then add_cell part (sprintf "v%d = std_reg(%d);" i w)
        let add_group (part : CalyxPart) name (lines : string seq) =
            part.wires.Add(sprintf "    group %s {" name)
            for line in lines do part.wires.Add("      " + line)
            part.wires.Add "    }"
        // One register write per group, so the next group observes .out.
        let write_group (part : CalyxPart) (control : ResizeArray<string>) (extras : string list) (assigns : (string * string) list) (write_en : string) =
            if not assigns.IsEmpty then
                let g = sprintf "g%d" (fresh part)
                let lines = ResizeArray<string>()
                for extra in extras do lines.Add extra
                for dest, port in assigns do
                    lines.Add(sprintf "%s.in = %s;" dest port)
                    lines.Add(sprintf "%s.write_en = %s;" dest write_en)
                let done_expr =
                    match assigns |> List.map fst with
                    | [one] -> sprintf "%s.done" one
                    | many -> (many |> List.map (sprintf "%s.done") |> String.concat " & ") + " ? 1'd1"
                lines.Add(sprintf "%s[done] = %s;" g done_expr)
                add_group part g lines
                control.Add(g + ";")
        let self_loop : (int * TyV []) option ref = ref None
        let rec emit_function (name : string) (tag : int option) (parameters : TyV []) (range : Ty) (body : TypedBind []) =
            let saved = self_loop.Value
            try
                self_loop.Value <- None
                let part =
                    { tag = tag
                      cells = ResizeArray<string>()
                      wires = ResizeArray<string>()
                      declared = HashSet<int>()
                      calls = Dictionary<int, string>()
                      serial = ref 0 }
                add_cell part "spiral_tick = std_reg(1);"
                let widths = ret_widths range
                widths |> Array.iteri (fun index w -> add_cell part (sprintf "%s = std_reg(%d);" (ret_register widths.Length index) w))
                for L(i,t) in parameters do ensure part i (width t)
                let rec binds (control : ResizeArray<string>) (ret : CalyxRet) (stmts : TypedBind []) =
                    Array.iter (function
                        | TyLet(d,trace,a) ->
                            try
                                let vs = data_free_vars d
                                vs |> Array.iter (fun (L(i,t)) -> ensure part i (width t))
                                op control (CalyxLocal vs) a
                            with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                        | TyLocalReturnOp(trace,a,_) ->
                            try op control ret a
                            with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                        | TyLocalReturnData(d,trace) ->
                            try
                                match ret with
                                | _ -> give control ret (data_term_vars d)
                            with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                        ) stmts
                and give (control : ResizeArray<string>) (ret : CalyxRet) values =
                    match ret with
                    | CalyxLocal targets ->
                        if targets.Length <> Array.length values then raise_codegen_error "Compiler error: A binding has the wrong number of values."
                        let assigns =
                            Array.map2 (fun (L(i,t)) value ->
                                ensure part i (width t)
                                sprintf "v%d" i, show_port value) targets values
                            |> Array.filter (fun (dest, port) -> port <> dest + ".out")
                            |> Array.toList
                        write_group part control [] assigns "1'd1"
                    | CalyxTail _ ->
                        if Array.length values > 0 then
                            write_group part control [] (values |> Array.mapi (fun index value -> ret_register values.Length index, show_port value) |> Array.toList) "1'd1"
                        clear_go control
                and clear_go (control : ResizeArray<string>) =
                    match self_loop.Value with
                    | Some _ -> write_group part control [] [("spiral_go", "1'd0")] "1'd1"
                    | None -> ()
                and place (control : ResizeArray<string>) (ret : CalyxRet) (produce : string -> unit) =
                    match ret with
                    | CalyxLocal [||] -> ()
                    | CalyxLocal [|L(i,t)|] ->
                        ensure part i (width t)
                        produce (sprintf "v%d" i)
                    | CalyxLocal _ -> unsupported "tuple values"
                    | CalyxTail range when is_unit_ty range -> ()
                    | CalyxTail _ ->
                        produce "spiral_ret"
                        clear_go control
                and op (control : ResizeArray<string>) (ret : CalyxRet) a =
                    let comb dest prim w left right =
                        let cell = sprintf "op%d" (fresh part)
                        add_cell part (sprintf "%s = %s(%d);" cell prim w)
                        write_group part control [sprintf "%s.left = %s;" cell left; sprintf "%s.right = %s;" cell right] [(dest, cell + ".out")] "1'd1"
                    let pipe dest prim w left right out_port =
                        let cell = sprintf "op%d" (fresh part)
                        add_cell part (sprintf "%s = %s(%d);" cell prim w)
                        write_group part control [
                            sprintf "%s.left = %s;" cell left
                            sprintf "%s.right = %s;" cell right
                            sprintf "%s.go = !%s.done ? 1'd1;" cell cell
                        ] [(dest, sprintf "%s.%s" cell out_port)] (cell + ".done")
                    let unary dest prim w input =
                        let cell = sprintf "op%d" (fresh part)
                        add_cell part (sprintf "%s = %s(%d);" cell prim w)
                        write_group part control [sprintf "%s.in = %s;" cell input] [(dest, cell + ".out")] "1'd1"
                    let pair_width a b =
                        let wa, wb = width_of a, width_of b
                        if wa <> wb then unsupported "operands of different widths"
                        wa
                    let invoke (a, c) (args : TyV []) =
                        let mname, mwidth, mparams, mtag = method (a, c)
                        if part.tag = Some mtag then unsupported "recursion that is not a self-tail call"
                        let cell =
                            match part.calls.TryGetValue mtag with
                            | true, found -> found
                            | _ ->
                                let found = sprintf "c%d" (fresh part)
                                part.calls.[mtag] <- found
                                add_cell part (sprintf "%s = %s();" found mname)
                                found
                        if args.Length <> mparams.Length then raise_codegen_error "Compiler error: A call has the wrong number of arguments."
                        let ports =
                            Array.map2 (fun (L(pi,_)) (L(ai,at)) ->
                                ensure part ai (width at)
                                sprintf "in%d = v%d.out" pi ai) mparams args
                            |> String.concat ", "
                        control.Add(sprintf "invoke %s(%s)();" cell ports)
                        cell, mwidth
                    let fill_seq (src : ResizeArray<string>) =
                        if src.Count > 0 then src else
                        let tmp = ResizeArray<string>()
                        write_group part tmp [] [("spiral_tick", "1'd0")] "1'd1"
                        tmp
                    match a with
                    | TyIf(cond,tr,fl) ->
                        let guard = sprintf "b%d" (fresh part)
                        add_cell part (guard + " = std_reg(1);")
                        match prim_of cond with
                        | Some BoolT -> write_group part control [] [(guard, one_port cond)] "1'd1"
                        | Some t when is_int_prim t ->
                            let w = width (YPrim t)
                            let cell = sprintf "op%d" (fresh part)
                            add_cell part (sprintf "%s = std_neq(%d);" cell w)
                            write_group part control [sprintf "%s.left = %s;" cell (one_port cond); sprintf "%s.right = %d'd0;" cell w] [(guard, cell + ".out")] "1'd1"
                        | _ -> unsupported "a condition that is not a bool or an int"
                        let tr_c, fl_c = ResizeArray<string>(), ResizeArray<string>()
                        binds tr_c ret tr
                        binds fl_c ret fl
                        control.Add(sprintf "if %s.out {" guard)
                        control.Add "  seq {"
                        for line in fill_seq tr_c do control.Add("    " + line)
                        control.Add "  }"
                        control.Add "} else {"
                        control.Add "  seq {"
                        for line in fill_seq fl_c do control.Add("    " + line)
                        control.Add "  }"
                        control.Add "};"
                    | TyJoinPoint(JPMethod(a,c), arguments) ->
                        let _, _, _, mtag = method (a, c)
                        let is_self =
                            match ret, self_loop.Value with
                            | CalyxTail _, Some (tag, _) -> mtag = tag
                            | _ -> false
                        if is_self then
                            let _, parameters = self_loop.Value.Value
                            if arguments.Length <> parameters.Length then raise_codegen_error "Compiler error: A tail call has the wrong number of arguments."
                            let temps =
                                arguments |> Array.map (fun (L(i,t)) ->
                                    let temp = sprintf "t%d" (fresh part)
                                    let w = width t
                                    ensure part i w
                                    add_cell part (sprintf "%s = std_reg(%d);" temp w)
                                    write_group part control [] [(temp, sprintf "v%d.out" i)] "1'd1"
                                    temp)
                            Array.iter2 (fun (L(i,_)) temp ->
                                write_group part control [] [(sprintf "v%d" i, temp + ".out")] "1'd1") parameters temps
                        else
                            let cell, out_widths = invoke (a, c) arguments
                            let outs = out_widths |> Array.mapi (fun index _ -> sprintf "%s.%s" cell (out_port out_widths.Length index))
                            match ret with
                            | CalyxLocal [||] -> ()
                            | CalyxTail range when is_unit_ty range -> ()
                            | _ when outs.Length = 0 -> unsupported "a unit method in value position"
                            | CalyxLocal targets ->
                                if targets.Length <> outs.Length then raise_codegen_error "Compiler error: A call has the wrong number of results."
                                targets |> Array.iter (fun (L(i,t)) -> ensure part i (width t))
                                write_group part control [] (Array.map2 (fun (L(i,_)) port -> sprintf "v%d" i, port) targets outs |> Array.toList) "1'd1"
                            | CalyxTail _ ->
                                write_group part control [] (outs |> Array.mapi (fun index port -> ret_register outs.Length index, port) |> Array.toList) "1'd1"
                                clear_go control
                    | TyJoinPoint(JPClosure _, _) -> unsupported "closures"
                    | TyBackend(_,_,r) -> raise_codegen_error_backend r "The Calyx backend does not support nesting other backends."
                    | TyWhile(cond, body) ->
                        match ret with
                        | CalyxLocal [||] -> ()
                        | CalyxTail range when is_unit_ty range -> ()
                        | _ -> unsupported "a while loop in value position"
                        let guard = sprintf "b%d" (fresh part)
                        add_cell part (guard + " = std_reg(1);")
                        let refresh (buf : ResizeArray<string>) =
                            let jp, args = cond
                            match jp with
                            | JPMethod(a,c) ->
                                let cell, out_widths = invoke (a, c) args
                                match out_widths with
                                | [|1|] -> write_group part buf [] [(guard, cell + ".out")] "1'd1"
                                | [|w|] ->
                                    let cell_ne = sprintf "op%d" (fresh part)
                                    add_cell part (sprintf "%s = std_neq(%d);" cell_ne w)
                                    write_group part buf [sprintf "%s.left = %s.out;" cell_ne cell; sprintf "%s.right = %d'd0;" cell_ne w] [(guard, cell_ne + ".out")] "1'd1"
                                | _ -> unsupported "a while condition that is not one value"
                            | JPClosure _ -> unsupported "closures"
                        refresh control
                        let loop_body = ResizeArray<string>()
                        binds loop_body (CalyxLocal [||]) body
                        refresh loop_body
                        control.Add(sprintf "while %s.out {" guard)
                        control.Add "  seq {"
                        for line in loop_body do control.Add("    " + line)
                        control.Add "  }"
                        control.Add "};"
                    | TyDo body | TyIndent body -> binds control ret body
                    | TyConv(YPrim target, b) ->
                        let source = prim_of b
                        let text = one_port b
                        let same =
                            match source with
                            | Some s when s = target -> true
                            | Some CharT when target = Int32T -> true
                            | Some Int32T when target = CharT -> true
                            | Some (Int32T | CharT) when target = UInt32T -> true
                            | Some UInt32T when (target = Int32T || target = CharT) -> true
                            | _ -> false
                        if same then place control ret (fun dest -> if text <> dest + ".out" then write_group part control [] [(dest, text)] "1'd1")
                        else
                            match source, target with
                            | Some BoolT, t when is_int_prim t ->
                                place control ret (fun dest ->
                                    let cell = sprintf "op%d" (fresh part)
                                    add_cell part (sprintf "%s = std_pad(1, %d);" cell (width (YPrim t)))
                                    write_group part control [sprintf "%s.in = %s;" cell text] [(dest, cell + ".out")] "1'd1")
                            | Some s, BoolT when is_int_prim s ->
                                place control ret (fun dest ->
                                    let w = width (YPrim s)
                                    let cell = sprintf "op%d" (fresh part)
                                    add_cell part (sprintf "%s = std_neq(%d);" cell w)
                                    write_group part control [sprintf "%s.left = %s;" cell text; sprintf "%s.right = %d'd0;" cell w] [(dest, cell + ".out")] "1'd1")
                            | Some s, t when is_int_prim s && is_int_prim t ->
                                let source_width, target_width = width (YPrim s), width (YPrim t)
                                place control ret (fun dest ->
                                    if source_width = target_width then
                                        if text <> dest + ".out" then write_group part control [] [(dest, text)] "1'd1"
                                    elif target_width < source_width then
                                        let slice = sprintf "op%d" (fresh part)
                                        add_cell part (sprintf "%s = std_slice(%d, %d);" slice source_width target_width)
                                        write_group part control [sprintf "%s.in = %s;" slice text] [(dest, slice + ".out")] "1'd1"
                                    else
                                        let pad = sprintf "op%d" (fresh part)
                                        add_cell part (sprintf "%s = std_pad(%d, %d);" pad source_width target_width)
                                        if is_signed_prim s then
                                            let raise_sign = sprintf "op%d" (fresh part)
                                            let extend_sign = sprintf "op%d" (fresh part)
                                            add_cell part (sprintf "%s = std_lsh(%d);" raise_sign target_width)
                                            add_cell part (sprintf "%s = std_srsh(%d);" extend_sign target_width)
                                            let distance = sprintf "%d'd%d" target_width (target_width - source_width)
                                            write_group part control [
                                                sprintf "%s.in = %s;" pad text
                                                sprintf "%s.left = %s.out;" raise_sign pad
                                                sprintf "%s.right = %s;" raise_sign distance
                                                sprintf "%s.left = %s.out;" extend_sign raise_sign
                                                sprintf "%s.right = %s;" extend_sign distance
                                            ] [(dest, extend_sign + ".out")] "1'd1"
                                        else
                                            write_group part control [sprintf "%s.in = %s;" pad text] [(dest, pad + ".out")] "1'd1")
                            | _ -> unsupported "this conversion"
                    | TyFailwith _ -> unsupported "failwith"
                    | TyMacro _ -> unsupported "macros"
                    | TyOp(Global, _) -> unsupported "globals"
                    | TyOp(operation, l) ->
                        let binary symbol a b dest =
                            // symbol selects the primitive. Add and subtract are two's complement.
                            let is_shift = symbol = "lsh" || symbol = "rsh"
                            let w = if is_shift then width_of a else pair_width a b
                            let left = one_port a
                            let right =
                                let amount_width = width_of b
                                if not is_shift || amount_width = w then one_port b
                                else
                                    let resize = sprintf "op%d" (fresh part)
                                    let amount = sprintf "t%d" (fresh part)
                                    if amount_width < w then add_cell part (sprintf "%s = std_pad(%d, %d);" resize amount_width w)
                                    else add_cell part (sprintf "%s = std_slice(%d, %d);" resize amount_width w)
                                    add_cell part (sprintf "%s = std_reg(%d);" amount w)
                                    write_group part control [sprintf "%s.in = %s;" resize (one_port b)] [(amount, resize + ".out")] "1'd1"
                                    amount + ".out"
                            match symbol with
                            | "add" -> comb dest "std_add" w left right
                            | "sub" -> comb dest "std_sub" w left right
                            | "mul" -> pipe dest "std_mult_pipe" w left right "out"
                            | "div" -> pipe dest (if signed_of a then "std_sdiv_pipe" else "std_div_pipe") w left right "out_quotient"
                            | "mod" when signed_of a ->
                                let quotient = sprintf "t%d" (fresh part)
                                add_cell part (sprintf "%s = std_reg(%d);" quotient w)
                                pipe quotient "std_sdiv_pipe" w left right "out_quotient"
                                let product = sprintf "t%d" (fresh part)
                                add_cell part (sprintf "%s = std_reg(%d);" product w)
                                pipe product "std_mult_pipe" w (quotient + ".out") right "out"
                                comb dest "std_sub" w left (product + ".out")
                            | "mod" -> pipe dest "std_div_pipe" w left right "out_remainder"
                            | "lt" -> comb dest (if signed_of a then "std_slt" else "std_lt") w left right
                            | "le" -> comb dest (if signed_of a then "std_sle" else "std_le") w left right
                            | "gt" -> comb dest (if signed_of a then "std_sgt" else "std_gt") w left right
                            | "ge" -> comb dest (if signed_of a then "std_sge" else "std_ge") w left right
                            | "eq" -> comb dest "std_eq" w left right
                            | "neq" -> comb dest "std_neq" w left right
                            | "and" -> comb dest "std_and" w left right
                            | "or" -> comb dest "std_or" w left right
                            | "xor" -> comb dest "std_xor" w left right
                            | "lsh" -> comb dest "std_lsh" w left right
                            | "rsh" -> comb dest (if signed_of a then "std_srsh" else "std_rsh") w left right
                            | other -> unsupported other
                        match operation, l with
                        | Dyn, [a] when (data_term_vars a).Length <> 1 -> give control ret (data_term_vars a)
                        | Dyn, [a] -> place control ret (fun dest -> if one_port a <> dest + ".out" then write_group part control [] [(dest, one_port a)] "1'd1")
                        | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                        | Add, [a;b] -> place control ret (fun dest -> binary "add" a b dest)
                        | Sub, [a;b] -> place control ret (fun dest -> binary "sub" a b dest)
                        | Mult, [a;b] -> place control ret (fun dest -> binary "mul" a b dest)
                        | Div, [a;b] -> place control ret (fun dest -> binary "div" a b dest)
                        | Mod, [a;b] -> place control ret (fun dest -> binary "mod" a b dest)
                        | LT, [a;b] -> place control ret (fun dest -> binary "lt" a b dest)
                        | LTE, [a;b] -> place control ret (fun dest -> binary "le" a b dest)
                        | GT, [a;b] -> place control ret (fun dest -> binary "gt" a b dest)
                        | GTE, [a;b] -> place control ret (fun dest -> binary "ge" a b dest)
                        | EQ, [a;b] -> place control ret (fun dest -> binary "eq" a b dest)
                        | NEQ, [a;b] -> place control ret (fun dest -> binary "neq" a b dest)
                        | BoolAnd, [a;b] -> place control ret (fun dest -> binary "and" a b dest)
                        | BoolOr, [a;b] -> place control ret (fun dest -> binary "or" a b dest)
                        | BitwiseAnd, [a;b] -> place control ret (fun dest -> binary "and" a b dest)
                        | BitwiseOr, [a;b] -> place control ret (fun dest -> binary "or" a b dest)
                        | BitwiseXor, [a;b] -> place control ret (fun dest -> binary "xor" a b dest)
                        | BitwiseComplement, [a] -> place control ret (fun dest -> unary dest "std_not" (width_of a) (one_port a))
                        | ShiftLeft, [a;b] -> place control ret (fun dest -> binary "lsh" a b dest)
                        | ShiftRight, [a;b] -> place control ret (fun dest -> binary "rsh" a b dest)
                        | Neg, [a] ->
                            place control ret (fun dest ->
                                let w = width_of a
                                comb dest "std_sub" w (sprintf "%d'd0" w) (one_port a))
                        | StdoutFlush, [] -> ()
                        | _ -> unsupported $"the operation {operation}"
                    | other ->
                        let construct = (sprintf "%A" other).Split('(').[0]
                        unsupported construct
                and is_tail tag (body : TypedBind []) =
                    body.Length > 0 &&
                    match Array.last body with
                    | TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _) ->
                        let _, _, _, mtag = method (a, c)
                        mtag = tag
                    | TyLocalReturnOp(_, TyIf(_,tr,fl), _) -> is_tail tag tr || is_tail tag fl
                    | TyLocalReturnOp(_, TyIntSwitch(_,on_succ,on_fail), _) -> Array.exists (is_tail tag) on_succ || is_tail tag on_fail
                    | TyLocalReturnOp(_, (TyDo b | TyIndent b), _) -> is_tail tag b
                    | _ -> false
                let tail = match tag with Some t when is_tail t body -> true | _ -> false
                if tail then
                    self_loop.Value <- Some (tag.Value, parameters)
                    add_cell part "spiral_go = std_reg(1);"
                let prefix = ResizeArray<string>()
                if parameters.Length > 0 then
                    let assigns = parameters |> Array.map (fun (L(i,_)) -> sprintf "v%d" i, sprintf "in%d" i) |> Array.toList
                    write_group part prefix [] assigns "1'd1"
                if tail then write_group part prefix [] [("spiral_go", "1'd1")] "1'd1"
                let body_control = ResizeArray<string>()
                binds body_control (CalyxTail range) body
                let control = ResizeArray<string>()
                for line in prefix do control.Add line
                if tail then
                    control.Add "while spiral_go.out {"
                    control.Add "  seq {"
                    if body_control.Count = 0 then write_group part body_control [] [("spiral_tick", "1'd0")] "1'd1"
                    for line in body_control do control.Add("    " + line)
                    control.Add "  }"
                    control.Add "};"
                else
                    for line in body_control do control.Add line
                if control.Count = 0 then write_group part control [] [("spiral_tick", "1'd0")] "1'd1"
                let text = StringBuilder()
                let formals = parameters |> Array.map (fun (L(i,t)) -> sprintf "in%d: %d" i (width t)) |> String.concat ", "
                let outs = widths |> Array.mapi (fun index w -> sprintf "%s: %d" (out_port widths.Length index) w) |> String.concat ", " |> sprintf "(%s)"
                text.AppendLine(sprintf "component %s(%s) -> %s {" name formals outs) |> ignore
                text.AppendLine "  cells {" |> ignore
                for cell in part.cells do text.AppendLine cell |> ignore
                text.AppendLine "  }" |> ignore
                text.AppendLine "  wires {" |> ignore
                for wire in part.wires do text.AppendLine wire |> ignore
                for index in 0 .. widths.Length - 1 do
                    text.AppendLine(sprintf "    %s = %s.out;" (out_port widths.Length index) (ret_register widths.Length index)) |> ignore
                text.AppendLine "  }" |> ignore
                text.AppendLine "  control {" |> ignore
                text.AppendLine "    seq {" |> ignore
                for line in control do text.AppendLine("      " + line) |> ignore
                text.AppendLine "    }" |> ignore
                text.AppendLine "  }" |> ignore
                text.AppendLine "}" |> ignore
                components.Add(text.ToString())
            finally
                self_loop.Value <- saved
        and method_memo = lazy (
            let dict = Dictionary(HashIdentity.Structural)
            fun ((jp_body, key) : _ * _) ->
                match dict.TryGetValue((jp_body, key)) with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[(jp_body, key)] <- tag
                    let args = codegenMethodKeyArgs key
                    match codegenMethodBody env "Calyx" jp_body key with
                    | body, range, name ->
                        let mname = "sp_" + generatedMethodName name tag
                        let parameters = rdata_free_vars args
                        method_info.[tag] <- (mname, ret_widths range, parameters)
                        emit_function mname (Some tag) parameters range body
                    tag)
        and method (a, b) : string * int [] * TyV [] * int =
            let tag = method_memo.Force() (a, b)
            let name, out_width, parameters = method_info.[tag]
            name, out_width, parameters, tag

        let unit_main =
            match Array.tryLast x with
            | Some (TyLocalReturnOp(_,_,d)) | Some (TyLocalReturnData(d,_)) ->
                match data_term_vars d |> Array.map (function WV(L(_,t)) -> t | WLit l -> YPrim (lit_to_primitive_type l)) with
                | [||] -> true
                | [|YPrim Int32T|] -> false
                | _ -> raise_codegen_error "The return type of main in the Calyx backend should be a 32-bit int (or unit)."
            | _ -> true
        emit_function "spiral_main" None [||] (if unit_main then YB else YPrim Int32T) x
        let program = StringBuilder()
        program.AppendLine "import \"primitives/core.futil\";" |> ignore
        program.AppendLine "import \"primitives/binary_operators.futil\";" |> ignore
        program.AppendLine "import \"primitives/memories/comb.futil\";" |> ignore
        components |> Seq.iter (fun text -> program.Append text |> ignore)
        let stored = if unit_main then "32'd0" else "entry.out"
        program.AppendLine "component main() -> () {" |> ignore
        program.AppendLine "  cells {" |> ignore
        program.AppendLine "    @external spiral_io = comb_mem_d1(32, 1, 1);" |> ignore
        program.AppendLine "    entry = spiral_main();" |> ignore
        program.AppendLine "  }" |> ignore
        program.AppendLine "  wires {" |> ignore
        program.AppendLine "    group spiral_store {" |> ignore
        program.AppendLine "      spiral_io.addr0 = 1'd0;" |> ignore
        program.AppendLine "      spiral_io.write_en = 1'd1;" |> ignore
        program.AppendLine(sprintf "      spiral_io.write_data = %s;" stored) |> ignore
        program.AppendLine "      spiral_store[done] = spiral_io.done;" |> ignore
        program.AppendLine "    }" |> ignore
        program.AppendLine "  }" |> ignore
        program.AppendLine "  control {" |> ignore
        program.AppendLine "    seq {" |> ignore
        program.AppendLine "      invoke entry()();" |> ignore
        program.AppendLine "      spiral_store;" |> ignore
        program.AppendLine "    }" |> ignore
        program.AppendLine "  }" |> ignore
        program.AppendLine "}" |> ignore
        program.ToString()

    // Kotlin has general recursion, but this backend rejects it. Self-tail calls
    // become while/continue. The process exits with main's i32 and prints nothing.

    /// ### KotlinRet
    type KotlinRet =
        | KotlinLocal of TyV []
        | KotlinTail of Ty

    /// ### codegenKotlin
    /// ### valAtAssignment
    let valAtAssignment (keyword : string) (generated : string) =
        if not (generated.Contains("var v", System.StringComparison.Ordinal)) then generated
        else
            let lines = generated.Replace("\r\n", "\n").Split('\n')
            let declaration = System.Text.RegularExpressions.Regex(@"^(?<indent>[ \t]+)var (?<name>v[0-9]+): (?<type>.+?) = (?<dummy>.+)$")
            let assignment = System.Text.RegularExpressions.Regex(@"(?<![\w.])(v[0-9]+)\s*(?:\.\w+|\[[^\]\n]*\])*\s*(?:=(?![=>])|\+=|-=|\*=|/=|%=|<<=|>>=|&=|\|=|\^=)")
            let counts = Dictionary<string, int>()
            for line in lines do
                for found in assignment.Matches line do
                    let name = found.Groups.[1].Value
                    counts.[name] <- (match counts.TryGetValue name with | true, n -> n + 1 | _ -> 1)
            let output = System.Text.StringBuilder(generated.Length)
            let mutable index = 0
            let mutable first = true
            let emit (text : string) =
                if not first then output.Append('\n') |> ignore
                first <- false
                output.Append(text) |> ignore
            while index < lines.Length do
                let line = lines.[index]
                let found = declaration.Match line
                let fused =
                    if found.Success && index + 1 < lines.Length then
                        let name = found.Groups.["name"].Value
                        let prefix = found.Groups.["indent"].Value + name + " = "
                        let following = lines.[index + 1]
                        let assignedOnce = match counts.TryGetValue name with | true, 1 -> true | _ -> false
                        if following.StartsWith(prefix, System.StringComparison.Ordinal) && assignedOnce
                           && not (System.Text.RegularExpressions.Regex.IsMatch(following.Substring prefix.Length, @"(?<![\w.])" + name + @"\b")) then
                            Some (found.Groups.["indent"].Value + keyword + " " + name + ": " + found.Groups.["type"].Value + " = " + following.Substring prefix.Length)
                        else None
                    else None
                match fused with
                | Some text ->
                    emit text
                    index <- index + 2
                | None ->
                    emit line
                    index <- index + 1
            output.ToString()

    let codegenKotlin (env : PartEvalResult) (x : TypedBind []) =
        let globals = ResizeArray<string>()
        let globals_seen = HashSet<string>()
        let functions = ResizeArray<string>()
        let tuple_bodies = ResizeArray<string>()
        let tuple_names = Dictionary<string, string>()
        let method_names = Dictionary<int, string>()
        let closure_names = Dictionary<int, string>()
        let helpers = ResizeArray<string>()
        let strings_ready = ref false
        let string_helpers () =
            if not strings_ready.Value then
                strings_ready.Value <- true
                // Index returns a sign-extended byte: C's char is signed, so 0xC3 is -61, not 195.
                let q = "\""
                let line text = text + "\n"
                helpers.Add(
                    line "fun spiralUtf8(value: String): ByteArray = value.toByteArray(Charsets.UTF_8)" +
                    line "fun spiralStringLength(value: String): Int = spiralUtf8(value).size" +
                    line "fun spiralStringIndex(value: String, index: Int): Int {" +
                    line "    val bytes = spiralUtf8(value)" +
                    line "    if (!(index >= 0 && index < bytes.size)) {" +
                    line ("        System.err.println(" + q + "string index out of bounds" + q + ")") +
                    line "        System.exit(1)" +
                    line "        throw RuntimeException()" +
                    line "    }" +
                    line "    return bytes[index].toInt()" +
                    line "}" +
                    line "fun spiralStringSlice(value: String, from: Int, to: Int): String {" +
                    line "    val bytes = spiralUtf8(value)" +
                    line "    val length = bytes.size" +
                    line "    if (from < 0 || from > length || to < from - 1 || to >= length) {" +
                    line ("        System.err.println(" + q + "string slice out of bounds" + q + ")") +
                    line "        System.exit(3)" +
                    line "        throw RuntimeException()" +
                    line "    }" +
                    line ("    if (to < from) return " + q + q) +
                    line "    val start = bytes[from].toInt()" +
                    line "    val follows = to + 1 < length && ((bytes[to + 1].toInt() and 192) == 128)" +
                    line "    if ((start and 192) == 128 || follows) {" +
                    line ("        System.err.println(" + q + "string slice splits a code point" + q + ")") +
                    line "        System.exit(3)" +
                    line "        throw RuntimeException()" +
                    line "    }" +
                    line "    return bytes.copyOfRange(from, to + 1).toString(Charsets.UTF_8)" +
                    line "}")
        let unsupported what = raise_codegen_error $"The Kotlin backend doesn't support {what} yet."
        let is_unit_ty = function YB -> true | _ -> false
        // Locals are always initialized. A union's zero is its first case built from zeros.
        let union_types = ResizeArray<string>()
        let union_zero_pending = HashSet<string>()
        let union_zero_sentinels = HashSet<string>()
        let union_zeros = Dictionary<string, string>()
        let union_seen = Dictionary(HashIdentity.Reference)
        let union_recs = Dictionary(HashIdentity.Reference)
        let fun_zeros = Dictionary<string, string>()
        // Heap and heap-mutable layouts. The id is assigned before nested fields are walked.
        let layout_types = ResizeArray<string>()
        let layout_zeros = Dictionary<string, string>()
        let layout_seen = Dictionary<string, int * Data * TyV[]>()
        let tuple_name (tys : string []) =
            let key = String.concat "," tys
            match tuple_names.TryGetValue key with
            | true, name -> name
            | _ ->
                let name = $"SpiralTuple{tuple_names.Count}"
                tuple_names.[key] <- name
                let fields = tys |> Array.mapi (fun i t -> $"val v{i}: {t}") |> String.concat ", "
                tuple_bodies.Add($"class {name}({fields})\n")
                name
        let rec tyv = function
            | YPrim Int32T | YPrim CharT -> "Int"
            | YPrim UInt32T -> "UInt"
            | YPrim BoolT -> "Boolean"
            | YPrim Float32T -> "Float"
            | YPrim Float64T -> "Double"
            | YPrim Int64T -> "Long"
            | YPrim UInt64T -> "ULong"
            | YPrim Int8T -> "Byte"
            | YPrim Int16T -> "Short"
            | YPrim UInt8T -> "UByte"
            | YPrim UInt16T -> "UShort"
            | YPrim StringT -> "String"
            | YArray a ->
                match env.ty_to_data a |> data_free_vars with
                | [|L(_, t)|] -> $"Array<{tyv t}>"
                | [||] -> unsupported "an array of unit elements"
                | many ->
                    let element = many |> Array.map (fun (L(_, t)) -> tyv t) |> tuple_name
                    $"Array<{element}>"
            | YFun(domain, range, FT_Vanilla) ->
                let dom = env.ty_to_data domain |> data_free_vars |> Array.map (fun (L(_, t)) -> tyv t)
                let ret =
                    match env.ty_to_data range |> data_free_vars |> Array.map (fun (L(_, t)) -> tyv t) with
                    | [||] -> "Unit"
                    | [|t|] -> t
                    | rets -> tuple_name rets
                let dom_text = dom |> String.concat ", "
                let text = if dom.Length = 0 then $"() -> {ret}" else $"({dom_text}) -> {ret}"
                if not (fun_zeros.ContainsKey text) then
                    let dummy =
                        if dom.Length = 0 then "{ throw RuntimeException() }"
                        else
                            let formals = dom |> Array.map (fun t -> $"_: {t}") |> String.concat ", "
                            $"{{ {formals} -> throw RuntimeException() }}"
                    fun_zeros.[text] <- dummy
                text
            | YFun _ -> unsupported "this function type"
            | YUnion h -> ensure_union h
            | YLayout _ as t -> ensure_layout t
            | t -> unsupported $"the type {show_ty t}"
        // A class, not a struct: a method receives the cell and writes the caller's fields.
        and ensure_layout (t : Ty) : string =
            match t with
            | YLayout(inner, lay) ->
                match lay with
                | StackMutable -> unsupported "stack mutable layout types"
                | StackRefs | HeapRefs -> unsupported "a ref layout"
                | Heap | HeapMutable ->
                    let key = show_ty t
                    let prefix = if lay = Heap then "Heap" else "Mut"
                    match layout_seen.TryGetValue key with
                    | true, (id, _, _) -> $"{prefix}{id}"
                    | _ ->
                        let id = layout_seen.Count
                        let name = $"{prefix}{id}"
                        let data = env.ty_to_data inner
                        let free_vars =
                            match data with
                            | DRecord fields -> fields |> Map.toArray |> Array.collect (fun (_, field) -> data_free_vars field)
                            | _ -> data_free_vars data
                        // Register before walking fields so a direct cycle is a name match, not a loop.
                        layout_seen.[key] <- (id, data, free_vars)
                        free_vars |> Array.iter (fun (L(_, ft)) ->
                            if tyv ft = name then unsupported "a recursive layout")
                        let text = StringBuilder()
                        let kw = if lay = Heap then "val" else "var"
                        if free_vars.Length = 0 then
                            text.Append($"class {name}()").Append('\n') |> ignore
                            layout_zeros.[name] <- $"{name}()"
                        else
                            let formals = free_vars |> Array.map (fun (L(i, ft)) -> $"{kw} l{i}: {tyv ft}") |> String.concat ", "
                            text.Append($"class {name}({formals})").Append('\n') |> ignore
                            let args = free_vars |> Array.map (fun (L(_, ft)) -> zero (tyv ft)) |> String.concat ", "
                            layout_zeros.[name] <- $"{name}({args})"
                        layout_types.Add(text.ToString())
                        name
            | _ -> raise_codegen_error "Compiler error: Expected a layout type."
        and ensure_union (h : Union) : string =
            let key = h.Item
            match union_seen.TryGetValue key with
            | true, name -> name
            | _ ->
                let tag = union_seen.Count
                let prefix = match key.layout with UHeap -> "UH" | UStack -> "US"
                let name = $"{prefix}{tag}"
                union_seen.[key] <- name
                let sentinel = $"{name}_Zero"
                union_zeros.[name] <- sentinel
                union_zero_pending.Add name |> ignore
                let rec_f : UnionRecFsharp = { tag = tag; free_vars = key.cases |> Map.map (fun _ -> env.ty_to_data >> data_free_vars) }
                union_recs.[key] <- rec_f
                let cases = rec_f.free_vars |> Map.toArray
                if cases.Length = 0 then unsupported "an empty union"
                cases |> Array.iter (fun (_, fields) -> fields |> Array.iter (fun (L(_, t)) -> tyv t |> ignore))
                let text = StringBuilder()
                text.Append($"sealed interface {name} {{ val tag: Int }}").Append('\n') |> ignore
                cases |> Array.iter (fun ((i, _), fields) ->
                    let case_name = $"{name}_{unionCaseSuffix rec_f i}"
                    match fields with
                    | [||] -> text.Append($"object {case_name} : {name} {{ override val tag: Int = {i} }}").Append('\n') |> ignore
                    | _ ->
                        let formals = fields |> Array.mapi (fun f (L(_, t)) -> $"val f{f}: {tyv t}") |> String.concat ", "
                        text.Append($"data class {case_name}({formals}) : {name} {{ override val tag: Int = {i} }}").Append('\n') |> ignore)
                let (i0, _), fields0 = cases.[0]
                let case0 = $"{name}_{unionCaseSuffix rec_f i0}"
                let first =
                    match fields0 with
                    | [||] -> case0
                    | _ ->
                        let args = fields0 |> Array.map (fun (L(_, t)) -> zero (tyv t)) |> String.concat ", "
                        $"{case0}({args})"
                union_zeros.[name] <- first
                union_zero_pending.Remove name |> ignore
                if union_zero_sentinels.Contains name then text.Append($"object {sentinel} : {name} {{ override val tag: Int = -1 }}").Append('\n') |> ignore
                union_types.Add(text.ToString())
                name
        and zero = function
            | "Int" -> "0"
            | "UInt" -> "0u"
            | "Long" -> "0L"
            | "ULong" -> "0uL"
            | "Byte" -> "(0).toByte()"
            | "Short" -> "(0).toShort()"
            | "UByte" -> "(0).toUByte()"
            | "UShort" -> "(0).toUShort()"
            | "Boolean" -> "false"
            | "Float" -> "0.0f"
            | "Double" -> "0.0"
            | "String" -> "\"\""
            | name when union_zeros.ContainsKey name ->
                if union_zero_pending.Contains name then union_zero_sentinels.Add name |> ignore
                union_zeros.[name]
            | name when layout_zeros.ContainsKey name -> layout_zeros.[name]
            | name when fun_zeros.ContainsKey name -> fun_zeros.[name]
            | array when array.StartsWith("Array<") ->
                let inner = array.Substring(6, array.Length - 7)
                $"emptyArray<{inner}>()"
            | other -> unsupported $"a zero value of {other}"
        let union_ref (h : Union) : string * UnionRecFsharp =
            let name = ensure_union h
            name, union_recs.[h.Item]
        let union_case_tag (rec_f : UnionRecFsharp) k =
            rec_f.free_vars
            |> Seq.tryPick (function KeyValue ((tag, case_name), _) when case_name = UnionTagIdOps.text k -> Some tag | _ -> None)
            |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text k}.")
        // Kotlin strings interpolate `$`. Escape it so a message cannot become code.
        let quote_text (text : string) =
            let sb = StringBuilder(text.Length + 2)
            sb.Append('"') |> ignore
            String.iter (function
                | '"' -> sb.Append("\\\"") |> ignore
                | '\\' -> sb.Append("\\\\") |> ignore
                | '\n' -> sb.Append("\\n") |> ignore
                | '\r' -> sb.Append("\\r") |> ignore
                | '\t' -> sb.Append("\\t") |> ignore
                | '$' -> sb.Append("\\$") |> ignore
                | ch -> sb.Append(ch) |> ignore
                ) text
            sb.Append('"') |> ignore
            sb.ToString()
        let lit = function
            | LitInt32 x when x = Int32.MinValue -> "Int.MIN_VALUE"
            | LitInt32 x -> string x
            | LitUInt32 x -> $"{x}u"
            | LitBool x -> if x then "true" else "false"
            | LitChar x -> string (int x)
            | LitFloat32 x when Single.IsNaN x -> "Float.NaN"
            | LitFloat32 x when Single.IsPositiveInfinity x -> "Float.POSITIVE_INFINITY"
            | LitFloat32 x when Single.IsNegativeInfinity x -> "Float.NEGATIVE_INFINITY"
            | LitFloat32 x ->
                let text = x.ToString("R", Globalization.CultureInfo.InvariantCulture)
                let text = if text.Contains('.') || text.Contains('e') || text.Contains('E') then text else text + ".0"
                text + "f"
            | LitFloat64 x when Double.IsNaN x -> "Double.NaN"
            | LitFloat64 x when Double.IsPositiveInfinity x -> "Double.POSITIVE_INFINITY"
            | LitFloat64 x when Double.IsNegativeInfinity x -> "Double.NEGATIVE_INFINITY"
            | LitFloat64 x ->
                let text = x.ToString("R", Globalization.CultureInfo.InvariantCulture)
                if text.Contains('.') || text.Contains('e') || text.Contains('E') then text else text + ".0"
            | LitInt64 x when x = Int64.MinValue -> "Long.MIN_VALUE"
            | LitInt64 x -> x.ToString(Globalization.CultureInfo.InvariantCulture) + "L"
            | LitUInt64 x -> x.ToString(Globalization.CultureInfo.InvariantCulture) + "uL"
            | LitInt8 x -> $"({x.ToString(Globalization.CultureInfo.InvariantCulture)}).toByte()"
            | LitInt16 x -> $"({x.ToString(Globalization.CultureInfo.InvariantCulture)}).toShort()"
            | LitUInt8 x -> $"({x.ToString(Globalization.CultureInfo.InvariantCulture)}).toUByte()"
            | LitUInt16 x -> $"({x.ToString(Globalization.CultureInfo.InvariantCulture)}).toUShort()"
            | LitString x -> quote_text x
        let show_w = function WV (L(i,_)) -> $"v{i}" | WLit a -> lit a
        let prim_of = function
            | DV(L(_,YPrim t)) -> Some t
            | DLit l -> Some (lit_to_primitive_type l)
            | _ -> None
        let kotlin_of d =
            match prim_of d with
            | Some t -> tyv (YPrim t)
            | None -> unsupported "an operation on a non-primitive"
        let tup d =
            match data_term_vars d with
            | [|w|] -> show_w w
            | [||] -> ""
            | _ -> unsupported "tuple values"
        let flatten_ty t = env.ty_to_data t |> data_free_vars |> Array.map (fun (L(_, inner)) -> inner)
        let ret_ty range =
            match flatten_ty range |> Array.map tyv with
            | [||] -> ""
            | [|t|] -> t
            | many -> tuple_name many
        // Positional constructor. Argument order is the layout field order.
        let layout_new (name : string) (free_vars : TyV []) (payload : Data) =
            let terms = data_term_vars payload
            if terms.Length <> free_vars.Length then raise_codegen_error "Compiler error: A layout is built from the wrong number of values."
            let args = terms |> Array.map show_w |> String.concat ", "
            $"{name}({args})"
        let self_loop : (int * TyV []) option ref = ref None
        let rec emit_function (name : string) (tag : int option) (parameters : TyV []) (range : Ty) (body : TypedBind []) =
            let saved = self_loop.Value
            let tail = match tag with Some t when self_tail t body -> true | _ -> false
            self_loop.Value <- if tail then Some (tag.Value, parameters) else None
            try
                let text = StringBuilder()
                let formals = parameters |> Array.map (fun (L(i,t)) -> $"p{i}: {tyv t}") |> String.concat ", "
                let result = ret_ty range
                let returns = if result = "" then "" else $": {result}"
                text.Append($"fun {name}({formals}){returns} {{").Append('\n') |> ignore
                let s0 = { text = text; indent = 4 }
                parameters |> Array.iter (fun (L(i,t)) -> line s0 $"var v{i}: {tyv t} = p{i}")
                if tail then
                    line s0 "while (true) {"
                    binds (indent s0) (KotlinTail range) body
                    line s0 "}"
                    if result <> "" then
                        let dead =
                            match flatten_ty range |> Array.map tyv with
                            | [|t|] -> zero t
                            | tys ->
                                let zeros = tys |> Array.map zero |> String.concat ", "
                                $"{result}({zeros})"
                        line s0 $"return {dead}"
                else binds s0 (KotlinTail range) body
                text.Append("}").Append('\n') |> ignore
                functions.Add(text.ToString())
            finally
                self_loop.Value <- saved
        and self_tail tag (body : TypedBind []) =
            body.Length > 0 &&
            match Array.last body with
            | TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _) -> method (a,c) = tag
            | TyLocalReturnOp(_, TyIf(_,tr,fl), _) -> self_tail tag tr || self_tail tag fl
            | TyLocalReturnOp(_, TyIntSwitch(_,on_succ,on_fail), _) -> Array.exists (self_tail tag) on_succ || self_tail tag on_fail
            | TyLocalReturnOp(_, (TyDo b | TyIndent b), _) -> self_tail tag b
            | _ -> false
        and binds (s : CodegenEnv) (ret : KotlinRet) (stmts : TypedBind []) =
            Array.iter (function
                | TyLet(d,trace,a) ->
                    try
                        let vs = data_free_vars d
                        vs |> Array.iter (fun (L(i,t)) -> line s $"var v{i}: {tyv t} = {zero (tyv t)}")
                        op s (KotlinLocal vs) a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) ->
                    try op s ret a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) ->
                    try
                        match ret with
                        | KotlinLocal targets ->
                            let values = data_term_vars d
                            if targets.Length <> values.Length then raise_codegen_error "Compiler error: A binding has the wrong number of values."
                            Array.iter2 (fun (L(i,_)) w -> line s $"v{i} = {show_w w}") targets values
                        | KotlinTail range ->
                            match data_term_vars d with
                            | [||] -> if self_loop.Value.IsSome then line s "return"
                            | [|w|] -> line s $"return {show_w w}"
                            | many ->
                                let args = many |> Array.map show_w |> String.concat ", "
                                line s $"return {ret_ty range}({args})"
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) stmts
        and op (s : CodegenEnv) (ret : KotlinRet) a =
            let return' (x : string) =
                match ret with
                | KotlinLocal [||] -> if x <> "" then line s x
                | KotlinLocal [|L(i,_)|] -> line s $"v{i} = {x}"
                | KotlinLocal targets ->
                    let name = $"spiral_tuple{s.text.Length}"
                    line s $"val {name} = {x}"
                    targets |> Array.iteri (fun k (L(i,_)) -> line s $"v{i} = {name}.v{k}")
                | KotlinTail range when is_unit_ty range ->
                    if x <> "" then line s x
                    if self_loop.Value.IsSome then line s "return"
                | KotlinTail _ -> line s $"return {x}"
            let jp_text (jp, args) =
                match jp with
                | JPMethod(a,c) ->
                    let name = method_names.[method (a,c)]
                    let arguments = args |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
                    $"{name}({arguments})"
                | JPClosure(a,c) ->
                    let tag = closure (a, c)
                    let arguments = args |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
                    $"{closure_names.[tag]}({arguments})"
            let is_self (a, c) =
                match ret, self_loop.Value with
                | KotlinTail _, Some (tag, _) -> method (a,c) = tag
                | _ -> false
            let assign_reads (source : int) (fields : TyV []) =
                match ret with
                | KotlinLocal targets when targets.Length = fields.Length ->
                    Array.iter2 (fun (L(di,_)) (L(fi,_)) -> line s $"v{di} = v{source}.l{fi}") targets fields
                | KotlinTail range when fields.Length = 1 && not (is_unit_ty range) ->
                    let (L(fi,_)) = fields.[0]
                    line s $"return v{source}.l{fi}"
                | KotlinLocal _ | KotlinTail _ -> unsupported "a layout index with the wrong number of values"
            match a with
            | TyIf(cond,tr,fl) ->
                line s $"if ({tup cond}) {{"
                binds (indent s) ret tr
                line s "} else {"
                binds (indent s) ret fl
                line s "}"
            | TyJoinPoint(JPMethod(a,c), arguments) when is_self (a, c) ->
                let _, parameters = self_loop.Value.Value
                if arguments.Length <> parameters.Length then raise_codegen_error "Compiler error: A tail call has the wrong number of arguments."
                let types = parameters |> Array.map (fun (L(i,t)) -> i, t) |> dict
                let temps = System.Collections.Generic.Dictionary<int, string> ()
                for step in parallelMoves (Array.map2 (fun (L(target,_)) (L(source,_)) -> target, source) parameters arguments) do
                    match step with
                    | MoveVar (target, source) -> line s $"v{target} = v{source}"
                    | SaveTemp (slot, source) ->
                        temps.[slot] <- $"t{s.text.Length}_{source}"
                        line s $"val {temps.[slot]}: {tyv types.[source]} = v{source}"
                    | MoveTemp (target, slot) -> line s $"v{target} = {temps.[slot]}"
                line s "continue"
            | TyJoinPoint(jp, args) -> return' (jp_text (jp, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The Kotlin backend does not support nesting other backends."
            | TyWhile(cond, body) ->
                match ret with
                | KotlinLocal [||] -> ()
                | KotlinTail range when is_unit_ty range -> ()
                | _ -> unsupported "a while loop in value position"
                line s "while (true) {"
                line (indent s) $"if (!({jp_text cond})) break"
                binds (indent s) (KotlinLocal [||]) body
                line s "}"
                match ret with
                | KotlinTail _ when self_loop.Value.IsSome -> line s "return"
                | _ -> ()
            | TyDo body | TyIndent body -> binds s ret body
            | TyConv(YPrim target, b) ->
                let source = prim_of b
                let text = tup b
                let same =
                    match source with
                    | Some s when s = target -> true
                    | Some CharT when target = Int32T -> true
                    | Some Int32T when target = CharT -> true
                    | _ -> false
                let converted =
                    if same then text
                    else
                        match source, target with
                        | Some (Int32T | CharT), UInt32T -> $"({text}).toUInt()"
                        | Some UInt32T, (Int32T | CharT) -> $"({text}).toInt()"
                        | Some (Int32T | UInt32T | CharT), Float32T -> $"({text}).toFloat()"
                        | Some (Int32T | UInt32T | CharT | Float32T), Float64T -> $"({text}).toDouble()"
                        | Some Float32T, (Int32T | CharT) -> $"({text}).toInt()"
                        | Some Float32T, UInt32T -> $"({text}).toUInt()"
                        | Some Float64T, Float32T -> $"({text}).toFloat()"
                        | Some Float64T, (Int32T | CharT) -> $"({text}).toInt()"
                        | Some Float64T, UInt32T -> $"({text}).toUInt()"
                        | Some (Int32T | CharT | UInt32T), Int64T -> $"({text}).toLong()"
                        | Some (Int32T | CharT | UInt32T), UInt64T -> $"({text}).toULong()"
                        | Some Int64T, (Int32T | CharT) -> $"({text}).toInt()"
                        | Some Int64T, UInt32T -> $"({text}).toUInt()"
                        | Some Int64T, UInt64T -> $"({text}).toULong()"
                        | Some UInt64T, (Int32T | CharT) -> $"({text}).toInt()"
                        | Some UInt64T, UInt32T -> $"({text}).toUInt()"
                        | Some UInt64T, Int64T -> $"({text}).toLong()"
                        | Some (Int64T | UInt64T), Float64T -> $"({text}).toDouble()"
                        | Some (Int64T | UInt64T), Float32T -> $"({text}).toFloat()"
                        | Some (Float32T | Float64T), Int64T -> $"({text}).toLong()"
                        | Some (Float32T | Float64T), UInt64T -> $"({text}).toULong()"
                        | Some (Int32T | CharT), Int8T -> $"({text}).toByte()"
                        | Some (Int32T | CharT), Int16T -> $"({text}).toShort()"
                        | Some (Int32T | CharT), UInt8T -> $"({text}).toUByte()"
                        | Some (Int32T | CharT), UInt16T -> $"({text}).toUShort()"
                        | Some (Int8T | Int16T | UInt8T | UInt16T), (Int32T | CharT) -> $"({text}).toInt()"
                        | Some BoolT, (Int32T | CharT) -> $"(if ({text}) 1 else 0)"
                        | Some BoolT, UInt32T -> $"(if ({text}) 1u else 0u)"
                        | Some (Int32T | CharT | UInt32T), BoolT ->
                            let zero_lit = if kotlin_of b = "UInt" then "0u" else "0"
                            $"({text} != {zero_lit})"
                        | _ -> unsupported "this conversion"
                return' converted
            // C exits with EXIT_FAILURE (1) after printing the message to stderr. Throw so every Kotlin path terminates.
            | TyFailwith(_, b) ->
                line s $"System.err.println({tup b})"
                line s "System.exit(1)"
                line s "throw RuntimeException()"
            | TyMacro parts ->
                let piece = function
                    | CMText x -> x
                    | CMTerm (x, true) -> data_term_vars x |> Array.map show_w |> String.concat ", "
                    | CMTerm (x, false) -> tup x
                    | CMType x -> tyv x
                    | CMTypeLit _ -> unsupported "a macro type literal"
                return' (parts |> List.map piece |> String.concat "")
            | TyOp(Global, [DLit (LitString text)]) ->
                if globals_seen.Add text then globals.Add text
                return' ""
            | TyOp(Global, _) -> unsupported "globals"
            | TyOp(operation, l) ->
                let binary symbol a b = $"({tup a} {symbol} {tup b})"
                // Byte and Short arithmetic returns Int. Put the result back in the operand type.
                let narrow ty expr =
                    match ty with
                    | "Byte" -> $"({expr}).toByte()"
                    | "Short" -> $"({expr}).toShort()"
                    | "UByte" -> $"({expr}).toUByte()"
                    | "UShort" -> $"({expr}).toUShort()"
                    | _ -> expr
                let arith symbol a b = narrow (kotlin_of a) (binary symbol a b)
                // Kotlin shift counts are Int. UInt.shr is logical; Int.shr is arithmetic.
                // A Byte shift is the sign-extended Int shift, then narrowed, matching C's promotion.
                let shift symbol a b =
                    let count =
                        match kotlin_of b with
                        | "UInt" | "Long" | "ULong" | "Byte" | "Short" | "UByte" | "UShort" -> $"({tup b}).toInt()"
                        | _ -> tup b
                    match kotlin_of a with
                    | "Byte" | "Short" | "UByte" | "UShort" as ty ->
                        narrow ty $"(({tup a}).toInt() {symbol} {count})"
                    | _ -> $"({tup a} {symbol} {count})"
                let expr =
                    match operation, l with
                    | Dyn, [a] -> tup a
                    | UnionTag, [a] -> $"({tup a}).tag"
                    | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                    | Add, [a;b] -> arith "+" a b
                    | Sub, [a;b] -> arith "-" a b
                    | Mult, [a;b] -> arith "*" a b
                    | Div, [a;b] -> arith "/" a b
                    | Mod, [a;b] -> arith "%" a b
                    | LT, [a;b] -> binary "<" a b
                    | LTE, [a;b] -> binary "<=" a b
                    | GT, [a;b] -> binary ">" a b
                    | GTE, [a;b] -> binary ">=" a b
                    | EQ, [a;b] -> binary "==" a b
                    | NEQ, [a;b] -> binary "!=" a b
                    | BoolAnd, [a;b] -> binary "&&" a b
                    | BoolOr, [a;b] -> binary "||" a b
                    | BitwiseAnd, [a;b] -> binary "and" a b
                    | BitwiseOr, [a;b] -> binary "or" a b
                    | BitwiseXor, [a;b] -> binary "xor" a b
                    | BitwiseComplement, [a] -> $"({tup a}.inv())"
                    | ShiftLeft, [a;b] -> shift "shl" a b
                    | ShiftRight, [a;b] -> shift "shr" a b
                    | Neg, [a] -> narrow (kotlin_of a) $"(-({tup a}))"
                    | PrimToString, [a] ->
                        match a with
                        | DLit(LitChar _) | DV(L(_,YPrim CharT)) -> $"({tup a}).toChar().toString()"
                        | _ -> $"({tup a}).toString()"
                    | NanIs, [a] -> $"({tup a} != {tup a})"
                    | StdoutFlush, [] -> ""
                    | StringIndex, [a;b] ->
                        string_helpers ()
                        let index = match kotlin_of b with "Int" -> tup b | _ -> unsupported "a string index that is not an i32"
                        $"spiralStringIndex({tup a}, {index})"
                    | StringSlice, [a;b;c] ->
                        string_helpers ()
                        let index d = match kotlin_of d with "Int" -> tup d | _ -> unsupported "a string index that is not an i32"
                        $"spiralStringSlice({tup a}, {index b}, {index c})"
                    | StaticStringConcat, [a;b] -> $"({tup a} + {tup b})"
                    | ArrayIndex, [a;b] ->
                        let index = match kotlin_of b with "Int" -> tup b | _ -> unsupported "an array index that is not an i32"
                        $"{tup a}[{index}]"
                    | ArrayIndexSet, [a;b;c] ->
                        let index = match kotlin_of b with "Int" -> tup b | _ -> unsupported "an array index that is not an i32"
                        let value =
                            match data_term_vars c with
                            | [|w|] -> show_w w
                            | many ->
                                let element = many |> Array.map (function WV(L(_, t)) -> tyv t | WLit l -> tyv (YPrim (lit_to_primitive_type l))) |> tuple_name
                                let args = many |> Array.map show_w |> String.concat ", "
                                $"{element}({args})"
                        $"{tup a}[{index}] = {value}"
                    | (Sqrt | Log | Exp | Tanh | Sin | Cos), [a] when (match prim_of a with Some (Float32T | Float64T) -> true | _ -> false) ->
                        let name = match operation with Sqrt -> "sqrt" | Log -> "ln" | Exp -> "exp" | Tanh -> "tanh" | Sin -> "sin" | _ -> "cos"
                        $"kotlin.math.{name}({tup a})"
                    | Pow, [a;b] when (match prim_of a with Some Float32T -> true | _ -> false) -> $"Math.pow(({tup a}).toDouble(), ({tup b}).toDouble()).toFloat()"
                    | Pow, [a;b] when (match prim_of a with Some Float64T -> true | _ -> false) -> $"Math.pow({tup a}, {tup b})"
                    | Printf, [DLit (LitString fmt); b] ->
                        match printf_pieces fmt (data_term_vars b) with
                        | [] -> ""
                        | pieces ->
                            let text =
                                pieces |> List.map (function
                                    | Choice1Of2 piece -> show_w (WLit (LitString piece))
                                    | Choice2Of2 ('s', a) -> show_w a
                                    | Choice2Of2 (_, a) -> $"({show_w a}).toString()")
                                |> String.concat " + "
                            $"System.out.write(({text}).toByteArray(Charsets.UTF_8)); System.out.flush()"
                    | _ -> unsupported $"the operation {operation}"
                return' expr
            | TyArrayCreate(a, b) ->
                let element_zero =
                    match env.ty_to_data a |> data_free_vars |> Array.map (fun (L(_, t)) -> tyv t) with
                    | [|t|] -> zero t
                    | [||] -> unsupported "an array of unit elements"
                    | many ->
                        let zeros = many |> Array.map zero |> String.concat ", "
                        $"{tuple_name many}({zeros})"
                let n = match kotlin_of b with "Int" -> tup b | _ -> unsupported "an array length that is not an i32"
                return' $"Array({n}) {{ {element_zero} }}"
            | TyArrayLength(t, b) ->
                match t with
                | YPrim (Int32T | CharT) -> return' $"{tup b}.size"
                | _ -> unsupported "array length of this width"
            | TyStringLength(t, b) ->
                string_helpers ()
                match t with
                | YPrim (Int32T | CharT) -> return' $"spiralStringLength({tup b})"
                | _ -> unsupported "string length of this width"
            | TyUnionBox(tag_id, payload, union_h) ->
                let name, rec_f = union_ref union_h
                let i = union_case_tag rec_f tag_id
                let case_name = $"{name}_{unionCaseSuffix rec_f i}"
                let args = data_term_vars payload |> Array.map show_w |> String.concat ", "
                return' (if args = "" then case_name else $"{case_name}({args})")
            | TyUnionUnbox(scrutinees, union_h, on_succs, on_fail) ->
                let name, rec_f = union_ref union_h
                let s' = indent s
                let s'' = indent s'
                let head = match scrutinees with L(i,_) :: _ -> $"v{i}.tag" | [] -> raise_codegen_error "Compiler error: A union unbox has no scrutinee."
                let shared_tag =
                    match List.pairwise scrutinees |> List.map (fun (L(i,_), L(i',_)) -> $"v{i}.tag == v{i'}.tag") with
                    | [] -> head
                    | equal ->
                        let all_equal = String.concat " && " equal
                        $"if ({all_equal}) {head} else -1"
                line s $"when ({shared_tag}) {{"
                on_succs |> Map.iter (fun k (payloads, body) ->
                    let c = union_case_tag rec_f k
                    let case_name = $"{name}_{unionCaseSuffix rec_f c}"
                    line s' $"{c} -> {{"
                    List.iter2 (fun (L(i,_)) a ->
                        data_free_vars a |> Array.iteri (fun f (L(vi, t)) ->
                            let ft = tyv t
                            line s'' $"var v{vi}: {ft} = (v{i} as {case_name}).f{f}")) scrutinees payloads
                    binds s'' ret body
                    line s' "}")
                match on_fail with
                | Some b ->
                    line s' "else -> {"
                    binds s'' ret b
                    line s' "}"
                | None -> line s' "else -> throw RuntimeException()"
                line s "}"
            | TyApply(L(i,_), b) ->
                let arguments = data_term_vars b |> Array.map show_w |> String.concat ", "
                return' $"v{i}({arguments})"
            | TyToLayout(payload, layout_ty) ->
                let name = ensure_layout layout_ty
                let _, _, free_vars = layout_seen.[show_ty layout_ty]
                return' (layout_new name free_vars payload)
            | TyLayoutIndexAll(L(i, layout_ty)) ->
                ensure_layout layout_ty |> ignore
                let _, _, free_vars = layout_seen.[show_ty layout_ty]
                assign_reads i free_vars
            | TyLayoutIndexByKey(L(i, layout_ty), key) ->
                ensure_layout layout_ty |> ignore
                let _, data, _ = layout_seen.[show_ty layout_ty]
                match data with
                | DRecord fields ->
                    match fields |> Map.tryPick (fun (_, k) field -> if LayoutFieldNameIdOps.matchesText key k then Some (data_free_vars field) else None) with
                    | Some found -> assign_reads i found
                    | None -> raise_codegen_error "Compiler error: A layout has no such field."
                | _ -> raise_codegen_error "Compiler error: Expected a record layout."
            | TyLayoutMutableSet(L(i, layout_ty), keys, value) ->
                match layout_ty with
                | YLayout(_, HeapMutable) -> ()
                | YLayout(_, Heap) -> unsupported "setting an immutable layout"
                | YLayout(_, StackMutable) -> unsupported "stack mutable layout types"
                | YLayout _ -> unsupported "a ref layout"
                | _ -> raise_codegen_error "Compiler error: Expected a layout type."
                ensure_layout layout_ty |> ignore
                let _, data, _ = layout_seen.[show_ty layout_ty]
                let target =
                    List.fold (fun current key ->
                        match current with
                        | DRecord fields -> fields |> Map.pick (fun (_, k) field -> if LayoutFieldNameIdOps.matchesText key k then Some field else None)
                        | _ -> raise_codegen_error "Compiler error: Expected a record layout.") data keys
                let fields = data_free_vars target
                let terms = data_term_vars value
                if fields.Length <> terms.Length then raise_codegen_error "Compiler error: A layout set has the wrong number of values."
                Array.iter2 (fun (L(fi,_)) term -> line s $"v{i}.l{fi} = {show_w term}") fields terms
            | other ->
                let construct = (sprintf "%A" other).Split('(').[0]
                unsupported construct
        and method_memo = lazy (
            let dict = Dictionary(HashIdentity.Structural)
            fun ((jp_body, key) : _ * _) ->
                match dict.TryGetValue((jp_body, key)) with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[(jp_body, key)] <- tag
                    let args = codegenMethodKeyArgs key
                    match codegenMethodBody env "Kotlin" jp_body key with
                    | body, range, name ->
                        method_names.[tag] <- "sp_" + generatedMethodName name tag
                        emit_function method_names.[tag] (Some tag) (rdata_free_vars args) range body
                    tag)
        and method (a, b) : int = method_memo.Force() (a, b)
        and closure_memo = lazy (
            let dict = Dictionary(HashIdentity.Structural)
            fun ((jp_body, key & (C(args,_,fun_ty))) : _ * _) ->
                match dict.TryGetValue((jp_body, key)) with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[(jp_body, key)] <- tag
                    match fun_ty with
                    | YFun(_, range, FT_Vanilla) ->
                        match codegenClosureBody env "Kotlin" jp_body key with
                        | domain_args, body, sourceName ->
                            closure_names.[tag] <- generatedClosureName sourceName tag
                            let captured = rdata_free_vars args
                            let domain_vs = data_free_vars domain_args
                            let text = StringBuilder()
                            let cap_formals = captured |> Array.map (fun (L(i,t)) -> $"v{i}: {tyv t}") |> String.concat ", "
                            text.Append($"fun {closure_names.[tag]}({cap_formals}): {tyv fun_ty} {{").Append('\n') |> ignore
                            let s0 = { text = text; indent = 4 }
                            let dom_formals = domain_vs |> Array.map (fun (L(i,t)) -> $"v{i}: {tyv t}") |> String.concat ", "
                            // A nominal union's name is not a Kotlin type. The value's type is the union.
                            let result =
                                match env.ty_to_data range |> data_free_vars |> Array.map (fun (L(_, t)) -> tyv t) with
                                | [||] -> ""
                                | [|t|] -> t
                                | tys -> tuple_name tys
                            let returns = if result = "" then "" else $": {result}"
                            let saved = self_loop.Value
                            self_loop.Value <- None
                            try
                                line s0 $"fun body({dom_formals}){returns} {{"
                                binds (indent s0) (KotlinTail range) body
                                line s0 "}"
                            finally
                                self_loop.Value <- saved
                            let forward =
                                match domain_vs with
                                | [||] -> "{ body() }"
                                | vs ->
                                    let formals = vs |> Array.mapi (fun k (L(_, t)) -> $"p{k}: {tyv t}") |> String.concat ", "
                                    let call = vs |> Array.mapi (fun k _ -> $"p{k}") |> String.concat ", "
                                    $"{{ {formals} -> body({call}) }}"
                            line s0 $"return {forward}"
                            text.Append("}").Append('\n') |> ignore
                            functions.Add(text.ToString())
                    | _ -> unsupported "this function type"
                    tag)
        and closure (a, b) : int = closure_memo.Force() (a, b)

        let unit_main =
            match Array.tryLast x with
            | Some (TyLocalReturnOp(_,_,d)) | Some (TyLocalReturnData(d,_)) ->
                match data_term_vars d |> Array.map (function WV(L(_,t)) -> t | WLit l -> YPrim (lit_to_primitive_type l)) with
                | [||] -> true
                | [|YPrim Int32T|] -> false
                | _ -> raise_codegen_error "The return type of main in the Kotlin backend should be a 32-bit int (or unit)."
            | _ -> true
        emit_function "spiral_main" None [||] (if unit_main then YB else YPrim Int32T) x
        let program = StringBuilder()
        globals |> Seq.iter (fun text -> program.AppendLine(text) |> ignore)
        layout_types |> Seq.iter (fun text -> program.Append(text) |> ignore)
        union_types |> Seq.iter (fun text -> program.Append(text) |> ignore)
        helpers |> Seq.iter (fun text -> program.Append(text) |> ignore)
        tuple_bodies |> Seq.iter (fun text -> program.Append(text) |> ignore)
        functions |> Seq.iter (fun fn -> program.Append(fn) |> ignore)
        program.AppendLine("fun main() {") |> ignore
        program.AppendLine("    var spiral_exit_code = 0") |> ignore
        if unit_main then program.AppendLine("    val spiral_thread = Thread(null, { spiral_main() }, \"spiral_main\", 1L shl 30)") |> ignore
        else program.AppendLine("    val spiral_thread = Thread(null, { spiral_exit_code = spiral_main() }, \"spiral_main\", 1L shl 30)") |> ignore
        program.AppendLine("    spiral_thread.start()") |> ignore
        program.AppendLine("    spiral_thread.join()") |> ignore
        program.AppendLine("    System.exit(spiral_exit_code)") |> ignore
        program.AppendLine("}") |> ignore
        program.ToString() |> valAtAssignment "val"

    // Swift traps on overflowing Int arithmetic, so add, subtract, and multiply
    // of integers use the wrapping operators. The process exits with main's i32
    // and prints nothing. Self-tail calls become while/continue.

    /// ### SwiftRet
    type SwiftRet =
        | SwiftLocal of TyV []
        | SwiftTail of Ty

    /// ### codegenSwift
    let codegenSwift (env : PartEvalResult) (x : TypedBind []) =
        let globals = ResizeArray<string>()
        let globals_seen = HashSet<string>()
        let functions = ResizeArray<string>()
        let method_names = Dictionary<int, string>()
        let closure_names = Dictionary<int, string>()
        let helpers = ResizeArray<string>()
        let strings_ready = ref false
        let string_helpers () =
            if not strings_ready.Value then
                strings_ready.Value <- true
                // Int8(bitPattern:) sign-extends, matching C's signed char.
                let q = "\""
                let line text = text + "\n"
                helpers.Add(
                    line "func spiralStringLength(_ value: String) -> Int32 { Int32(value.utf8.count) }" +
                    line "func spiralStringIndex(_ value: String, _ index: Int32) -> Int32 {" +
                    line "    let bytes = Array(value.utf8)" +
                    line "    let i = Int(index)" +
                    line "    if !(i >= 0 && i < bytes.count) {" +
                    line ("        _ = fputs(" + q + "string index out of bounds\\n" + q + ", stderr)") +
                    line "        exit(1)" +
                    line "    }" +
                    line "    return Int32(Int8(bitPattern: bytes[i]))" +
                    line "}" +
                    line "func spiralStringSlice(_ value: String, _ from: Int32, _ to: Int32) -> String {" +
                    line "    let bytes = Array(value.utf8)" +
                    line "    let length = bytes.count" +
                    line "    let f = Int(from)" +
                    line "    let t = Int(to)" +
                    line "    if f < 0 || f > length || t < f - 1 || t >= length {" +
                    line ("        _ = fputs(" + q + "string slice out of bounds\\n" + q + ", stderr)") +
                    line "        exit(3)" +
                    line "    }" +
                    line ("    if t < f { return " + q + q + " }") +
                    line "    let start = Int(bytes[f])" +
                    line "    let follows = t + 1 < length && (Int(bytes[t + 1]) & 192) == 128" +
                    line "    if (start & 192) == 128 || follows {" +
                    line ("        _ = fputs(" + q + "string slice splits a code point\\n" + q + ", stderr)") +
                    line "        exit(3)" +
                    line "    }" +
                    line "    return String(decoding: bytes[f...t], as: UTF8.self)" +
                    line "}")
        let unsupported what = raise_codegen_error $"The Swift backend doesn't support {what} yet."
        let arrays_ready = ref false
        let array_helpers () =
            if not arrays_ready.Value then
                arrays_ready.Value <- true
                helpers.Add(
                    "final class SpiralArray<T> {\n" +
                    "    var items: [T]\n" +
                    "    init(_ items: [T]) { self.items = items }\n" +
                    "}\n")
        let is_unit_ty = function YB -> true | _ -> false
        // Locals are always initialized. A union's zero is its first case built from zeros.
        let union_types = ResizeArray<string>()
        let union_zero_pending = HashSet<string>()
        let union_zero_sentinels = HashSet<string>()
        let union_zeros = Dictionary<string, string>()
        let union_seen = Dictionary(HashIdentity.Reference)
        let union_recs = Dictionary(HashIdentity.Reference)
        let fun_zeros = Dictionary<string, string>()
        // Heap and heap-mutable layouts. The id is assigned before nested fields are walked.
        let layout_types = ResizeArray<string>()
        let layout_zeros = Dictionary<string, string>()
        let layout_seen = Dictionary<string, int * Data * TyV[]>()
        let rec tyv = function
            | YPrim Int32T | YPrim CharT -> "Int32"
            | YPrim UInt32T -> "UInt32"
            | YPrim BoolT -> "Bool"
            | YPrim Float32T -> "Float"
            | YPrim Float64T -> "Double"
            | YPrim Int64T -> "Int64"
            | YPrim UInt64T -> "UInt64"
            | YPrim Int8T -> "Int8"
            | YPrim Int16T -> "Int16"
            | YPrim UInt8T -> "UInt8"
            | YPrim UInt16T -> "UInt16"
            | YPrim StringT -> "String"
            | YArray a ->
                match env.ty_to_data a |> data_free_vars with
                | [|L(_, t)|] -> array_helpers (); $"SpiralArray<{tyv t}>"
                | [||] -> unsupported "an array of unit elements"
                | many ->
                    array_helpers ()
                    let element = many |> Array.map (fun (L(_, t)) -> tyv t) |> String.concat ", "
                    $"SpiralArray<({element})>"
            | YFun(domain, range, FT_Vanilla) ->
                let dom = env.ty_to_data domain |> data_free_vars |> Array.map (fun (L(_, t)) -> match t with YFun _ -> "@escaping " + tyv t | _ -> tyv t)
                let ret =
                    match env.ty_to_data range |> data_free_vars |> Array.map (fun (L(_, t)) -> tyv t) with
                    | [||] -> "Void"
                    | [|t|] -> t
                    | rets -> "(" + String.concat ", " rets + ")"
                let dom_text = dom |> String.concat ", "
                let text = if dom.Length = 0 then $"() -> {ret}" else $"({dom_text}) -> {ret}"
                if not (fun_zeros.ContainsKey text) then
                    let dummy =
                        if dom.Length = 0 then "{ () -> " + ret + " in fatalError(\"unreachable closure\") }"
                        else
                            let formals = dom |> Array.map (fun t -> $"_: {t}") |> String.concat ", "
                            "{ (" + formals + ") -> " + ret + " in fatalError(\"unreachable closure\") }"
                    fun_zeros.[text] <- dummy
                text
            | YFun _ -> unsupported "this function type"
            | YUnion h -> ensure_union h
            | YLayout _ as t -> ensure_layout t
            | t -> unsupported $"the type {show_ty t}"
        // A class, not a struct: a method receives the cell and writes the caller's fields.
        and ensure_layout (t : Ty) : string =
            match t with
            | YLayout(inner, lay) ->
                match lay with
                | StackMutable -> unsupported "stack mutable layout types"
                | StackRefs | HeapRefs -> unsupported "a ref layout"
                | Heap | HeapMutable ->
                    let key = show_ty t
                    let prefix = if lay = Heap then "Heap" else "Mut"
                    match layout_seen.TryGetValue key with
                    | true, (id, _, _) -> $"{prefix}{id}"
                    | _ ->
                        let id = layout_seen.Count
                        let name = $"{prefix}{id}"
                        let data = env.ty_to_data inner
                        let free_vars =
                            match data with
                            | DRecord fields -> fields |> Map.toArray |> Array.collect (fun (_, field) -> data_free_vars field)
                            | _ -> data_free_vars data
                        // Register before walking fields so a direct cycle is a name match, not a loop.
                        layout_seen.[key] <- (id, data, free_vars)
                        free_vars |> Array.iter (fun (L(_, ft)) ->
                            if tyv ft = name then unsupported "a recursive layout")
                        let text = StringBuilder()
                        let kw = if lay = Heap then "let" else "var"
                        text.Append("class " + name + " {").Append('\n') |> ignore
                        if free_vars.Length = 0 then
                            text.Append("    init() {}").Append('\n') |> ignore
                            layout_zeros.[name] <- name + "()"
                        else
                            free_vars |> Array.iter (fun (L(i, ft)) ->
                                text.Append("    " + kw + " l" + string i + ": " + tyv ft).Append('\n') |> ignore)
                            let formals = free_vars |> Array.map (fun (L(i, ft)) ->
                                let ty = tyv ft
                                // Stored closures are escaping. Other field types reject @escaping.
                                let escaping = if ty.Contains("->") then "@escaping " else ""
                                "l" + string i + ": " + escaping + ty) |> String.concat ", "
                            text.Append("    init(" + formals + ") {").Append('\n') |> ignore
                            free_vars |> Array.iter (fun (L(i, _)) ->
                                text.Append("        self.l" + string i + " = l" + string i).Append('\n') |> ignore)
                            text.Append("    }").Append('\n') |> ignore
                            let args = free_vars |> Array.map (fun (L(i, ft)) -> "l" + string i + ": " + zero (tyv ft)) |> String.concat ", "
                            layout_zeros.[name] <- name + "(" + args + ")"
                        text.Append("}").Append('\n') |> ignore
                        layout_types.Add(text.ToString())
                        name
            | _ -> raise_codegen_error "Compiler error: Expected a layout type."
        and ensure_union (h : Union) : string =
            let key = h.Item
            match union_seen.TryGetValue key with
            | true, name -> name
            | _ ->
                let tag = union_seen.Count
                let prefix = match key.layout with UHeap -> "UH" | UStack -> "US"
                let name = $"{prefix}{tag}"
                union_seen.[key] <- name
                let sentinel = $"{name}_Zero"
                union_zeros.[name] <- sentinel + "()"
                union_zero_pending.Add name |> ignore
                let rec_f : UnionRecFsharp = { tag = tag; free_vars = key.cases |> Map.map (fun _ -> env.ty_to_data >> data_free_vars) }
                union_recs.[key] <- rec_f
                let cases = rec_f.free_vars |> Map.toArray
                if cases.Length = 0 then unsupported "an empty union"
                cases |> Array.iter (fun (_, fields) -> fields |> Array.iter (fun (L(_, t)) -> tyv t |> ignore))
                let text = StringBuilder()
                text.Append($"protocol {name} {{ var tag: Int32 {{ get }} }}").Append('\n') |> ignore
                cases |> Array.iter (fun ((i, _), fields) ->
                    let case_name = $"{name}_{unionCaseSuffix rec_f i}"
                    match fields with
                    | [||] -> text.Append($"struct {case_name}: {name} {{ var tag: Int32 {{ {i} }} }}").Append('\n') |> ignore
                    | _ ->
                        let stored = fields |> Array.mapi (fun f (L(_, t)) -> $"var f{f}: {tyv t}") |> String.concat "; "
                        text.Append($"struct {case_name}: {name} {{ {stored}; var tag: Int32 {{ {i} }} }}").Append('\n') |> ignore)
                let (i0, _), fields0 = cases.[0]
                let case0 = $"{name}_{unionCaseSuffix rec_f i0}"
                let first =
                    match fields0 with
                    | [||] -> $"{case0}()"
                    | _ ->
                        let args = fields0 |> Array.mapi (fun f (L(_, t)) -> $"f{f}: {zero (tyv t)}") |> String.concat ", "
                        $"{case0}({args})"
                union_zeros.[name] <- first
                union_zero_pending.Remove name |> ignore
                if union_zero_sentinels.Contains name then text.Append($"struct {sentinel}: {name} {{ var tag: Int32 {{ -1 }} }}").Append('\n') |> ignore
                union_types.Add(text.ToString())
                name
        and zero = function
            | "Int32" -> "0"
            | "UInt32" -> "UInt32(0)"
            | "Int64" -> "(0 as Int64)"
            | "UInt64" -> "(0 as UInt64)"
            | "Int8" -> "Int8(0)"
            | "Int16" -> "Int16(0)"
            | "UInt8" -> "UInt8(0)"
            | "UInt16" -> "UInt16(0)"
            | "Bool" -> "false"
            | "Float" -> "(0.0 as Float)"
            | "Double" -> "(0.0 as Double)"
            | "String" -> "\"\""
            | name when union_zeros.ContainsKey name ->
                if union_zero_pending.Contains name then union_zero_sentinels.Add name |> ignore
                union_zeros.[name]
            | name when layout_zeros.ContainsKey name -> layout_zeros.[name]
            | name when fun_zeros.ContainsKey name -> fun_zeros.[name]
            | array when array.StartsWith("SpiralArray<") -> $"{array}([])"
            | other -> unsupported $"a zero value of {other}"
        let union_ref (h : Union) : string * UnionRecFsharp =
            let name = ensure_union h
            name, union_recs.[h.Item]
        let union_case_tag (rec_f : UnionRecFsharp) k =
            rec_f.free_vars
            |> Seq.tryPick (function KeyValue ((tag, case_name), _) when case_name = UnionTagIdOps.text k -> Some tag | _ -> None)
            |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text k}.")
        let quote_text (text : string) =
            let sb = StringBuilder(text.Length + 2)
            sb.Append('"') |> ignore
            String.iter (function
                | '"' -> sb.Append("\\\"") |> ignore
                | '\\' -> sb.Append("\\\\") |> ignore
                | '\n' -> sb.Append("\\n") |> ignore
                | '\r' -> sb.Append("\\r") |> ignore
                | '\t' -> sb.Append("\\t") |> ignore
                | ch -> sb.Append(ch) |> ignore
                ) text
            sb.Append('"') |> ignore
            sb.ToString()
        let lit = function
            | LitInt32 x when x = Int32.MinValue -> "Int32.min"
            | LitInt32 x -> string x
            | LitUInt32 x -> $"UInt32({x})"
            | LitBool x -> if x then "true" else "false"
            | LitChar x -> string (int x)
            | LitFloat32 x when Single.IsNaN x -> "Float.nan"
            | LitFloat32 x when Single.IsPositiveInfinity x -> "Float.infinity"
            | LitFloat32 x when Single.IsNegativeInfinity x -> "(-Float.infinity)"
            | LitFloat32 x ->
                let text = x.ToString("R", Globalization.CultureInfo.InvariantCulture)
                let text = if text.Contains('.') || text.Contains('e') || text.Contains('E') then text else text + ".0"
                $"({text} as Float)"
            | LitFloat64 x when Double.IsNaN x -> "Double.nan"
            | LitFloat64 x when Double.IsPositiveInfinity x -> "Double.infinity"
            | LitFloat64 x when Double.IsNegativeInfinity x -> "(-Double.infinity)"
            | LitFloat64 x ->
                let text = x.ToString("R", Globalization.CultureInfo.InvariantCulture)
                let text = if text.Contains('.') || text.Contains('e') || text.Contains('E') then text else text + ".0"
                $"({text} as Double)"
            | LitInt64 x when x = Int64.MinValue -> "Int64.min"
            | LitInt64 x -> $"({x.ToString(Globalization.CultureInfo.InvariantCulture)} as Int64)"
            | LitUInt64 x -> $"({x.ToString(Globalization.CultureInfo.InvariantCulture)} as UInt64)"
            | LitInt8 x when x = SByte.MinValue -> "Int8.min"
            | LitInt8 x -> $"Int8({x.ToString(Globalization.CultureInfo.InvariantCulture)})"
            | LitInt16 x when x = Int16.MinValue -> "Int16.min"
            | LitInt16 x -> $"Int16({x.ToString(Globalization.CultureInfo.InvariantCulture)})"
            | LitUInt8 x -> $"UInt8({x.ToString(Globalization.CultureInfo.InvariantCulture)})"
            | LitUInt16 x -> $"UInt16({x.ToString(Globalization.CultureInfo.InvariantCulture)})"
            | LitString x -> quote_text x
        let show_w = function WV (L(i,_)) -> $"v{i}" | WLit a -> lit a
        let prim_of = function
            | DV(L(_,YPrim t)) -> Some t
            | DLit l -> Some (lit_to_primitive_type l)
            | _ -> None
        let swift_of d =
            match prim_of d with
            | Some t -> tyv (YPrim t)
            | None -> unsupported "an operation on a non-primitive"
        let floated a b =
            match prim_of a, prim_of b with
            | Some Float32T, _ | _, Some Float32T -> true
            | Some Float64T, _ | _, Some Float64T -> true
            | _ -> false
        let tup d =
            match data_term_vars d with
            | [|w|] -> show_w w
            | [||] -> ""
            | _ -> unsupported "tuple values"
        let flatten_ty t = env.ty_to_data t |> data_free_vars |> Array.map (fun (L(_, inner)) -> inner)
        let parameter_ty t = match t with YFun _ -> "@escaping " + tyv t | _ -> tyv t
        let ret_ty range =
            match flatten_ty range |> Array.map tyv with
            | [||] -> ""
            | [|t|] -> t
            | many -> "(" + String.concat ", " many + ")"
        // Labeled constructor. Argument order is the layout field order.
        let layout_new (name : string) (free_vars : TyV []) (payload : Data) =
            let terms = data_term_vars payload
            if terms.Length <> free_vars.Length then raise_codegen_error "Compiler error: A layout is built from the wrong number of values."
            let args =
                Array.map2 (fun (L(i,_)) w -> "l" + string i + ": " + show_w w) free_vars terms
                |> String.concat ", "
            name + "(" + args + ")"
        let self_loop : (int * TyV []) option ref = ref None
        let rec emit_function (name : string) (tag : int option) (parameters : TyV []) (range : Ty) (body : TypedBind []) =
            let saved = self_loop.Value
            let tail = match tag with Some t when self_tail t body -> true | _ -> false
            self_loop.Value <- if tail then Some (tag.Value, parameters) else None
            try
                let text = StringBuilder()
                let formals = parameters |> Array.map (fun (L(i,t)) -> $"_ p{i}: {parameter_ty t}") |> String.concat ", "
                let result = ret_ty range
                let signature = if result = "" then $"func {name}({formals}) {{" else $"func {name}({formals}) -> {result} {{"
                text.Append(signature).Append('\n') |> ignore
                let s0 = { text = text; indent = 4 }
                parameters |> Array.iter (fun (L(i,t)) -> line s0 $"var v{i}: {tyv t} = p{i}")
                if tail then
                    line s0 "while true {"
                    binds (indent s0) (SwiftTail range) body
                    line s0 "}"
                    if result <> "" then
                        let dead =
                            match flatten_ty range |> Array.map tyv with
                            | [|t|] -> zero t
                            | tys -> "(" + (tys |> Array.map zero |> String.concat ", ") + ")"
                        line s0 $"return {dead}"
                else binds s0 (SwiftTail range) body
                text.Append("}").Append('\n') |> ignore
                functions.Add(text.ToString())
            finally
                self_loop.Value <- saved
        and self_tail tag (body : TypedBind []) =
            body.Length > 0 &&
            match Array.last body with
            | TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _) -> method (a,c) = tag
            | TyLocalReturnOp(_, TyIf(_,tr,fl), _) -> self_tail tag tr || self_tail tag fl
            | TyLocalReturnOp(_, TyIntSwitch(_,on_succ,on_fail), _) -> Array.exists (self_tail tag) on_succ || self_tail tag on_fail
            | TyLocalReturnOp(_, (TyDo b | TyIndent b), _) -> self_tail tag b
            | _ -> false
        and binds (s : CodegenEnv) (ret : SwiftRet) (stmts : TypedBind []) =
            Array.iter (function
                | TyLet(d,trace,a) ->
                    try
                        let vs = data_free_vars d
                        vs |> Array.iter (fun (L(i,t)) -> line s $"var v{i}: {tyv t} = {zero (tyv t)}")
                        op s (SwiftLocal vs) a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) ->
                    try op s ret a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) ->
                    try
                        match ret with
                        | SwiftLocal targets ->
                            let values = data_term_vars d
                            if targets.Length <> values.Length then raise_codegen_error "Compiler error: A binding has the wrong number of values."
                            Array.iter2 (fun (L(i,_)) w -> line s $"v{i} = {show_w w}") targets values
                        | SwiftTail range ->
                            match data_term_vars d with
                            | [||] -> if self_loop.Value.IsSome then line s "return"
                            | [|w|] -> line s $"return {show_w w}"
                            | many ->
                                let args = many |> Array.map show_w |> String.concat ", "
                                line s $"return ({args})"
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) stmts
        and op (s : CodegenEnv) (ret : SwiftRet) a =
            let return' (x : string) =
                match ret with
                | SwiftLocal [||] -> if x <> "" then line s x
                | SwiftLocal [|L(i,_)|] -> line s $"v{i} = {x}"
                | SwiftLocal targets ->
                    let name = $"spiral_tuple{s.text.Length}"
                    line s $"let {name} = {x}"
                    targets |> Array.iteri (fun k (L(i,_)) -> line s $"v{i} = {name}.{k}")
                | SwiftTail range when is_unit_ty range ->
                    if x <> "" then line s x
                    if self_loop.Value.IsSome then line s "return"
                | SwiftTail _ -> line s $"return {x}"
            let jp_text (jp, args) =
                match jp with
                | JPMethod(a,c) ->
                    let name = method_names.[method (a,c)]
                    let arguments = args |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
                    $"{name}({arguments})"
                | JPClosure(a,c) ->
                    let tag = closure (a, c)
                    let arguments = args |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
                    $"{closure_names.[tag]}({arguments})"
            let is_self (a, c) =
                match ret, self_loop.Value with
                | SwiftTail _, Some (tag, _) -> method (a,c) = tag
                | _ -> false
            let assign_reads (source : int) (fields : TyV []) =
                match ret with
                | SwiftLocal targets when targets.Length = fields.Length ->
                    Array.iter2 (fun (L(di,_)) (L(fi,_)) -> line s $"v{di} = v{source}.l{fi}") targets fields
                | SwiftTail range when fields.Length = 1 && not (is_unit_ty range) ->
                    let (L(fi,_)) = fields.[0]
                    line s $"return v{source}.l{fi}"
                | SwiftLocal _ | SwiftTail _ -> unsupported "a layout index with the wrong number of values"
            match a with
            | TyIf(cond,tr,fl) ->
                line s $"if ({tup cond}) {{"
                binds (indent s) ret tr
                line s "} else {"
                binds (indent s) ret fl
                line s "}"
            | TyJoinPoint(JPMethod(a,c), arguments) when is_self (a, c) ->
                let _, parameters = self_loop.Value.Value
                if arguments.Length <> parameters.Length then raise_codegen_error "Compiler error: A tail call has the wrong number of arguments."
                let types = parameters |> Array.map (fun (L(i,t)) -> i, t) |> dict
                let temps = System.Collections.Generic.Dictionary<int, string> ()
                for step in parallelMoves (Array.map2 (fun (L(target,_)) (L(source,_)) -> target, source) parameters arguments) do
                    match step with
                    | MoveVar (target, source) -> line s $"v{target} = v{source}"
                    | SaveTemp (slot, source) ->
                        temps.[slot] <- $"t{s.text.Length}_{source}"
                        line s $"let {temps.[slot]}: {tyv types.[source]} = v{source}"
                    | MoveTemp (target, slot) -> line s $"v{target} = {temps.[slot]}"
                line s "continue"
            | TyJoinPoint(jp, args) -> return' (jp_text (jp, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The Swift backend does not support nesting other backends."
            | TyWhile(cond, body) ->
                match ret with
                | SwiftLocal [||] -> ()
                | SwiftTail range when is_unit_ty range -> ()
                | _ -> unsupported "a while loop in value position"
                line s "while true {"
                line (indent s) $"if !({jp_text cond}) {{ break }}"
                binds (indent s) (SwiftLocal [||]) body
                line s "}"
                match ret with
                | SwiftTail _ when self_loop.Value.IsSome -> line s "return"
                | _ -> ()
            | TyDo body | TyIndent body -> binds s ret body
            | TyConv(YPrim target, b) ->
                let source = prim_of b
                let text = tup b
                let same =
                    match source with
                    | Some s when s = target -> true
                    | Some CharT when target = Int32T -> true
                    | Some Int32T when target = CharT -> true
                    | _ -> false
                let converted =
                    if same then text
                    else
                        match source, target with
                        | Some (Int32T | CharT), UInt32T -> $"UInt32(bitPattern: {text})"
                        | Some UInt32T, (Int32T | CharT) -> $"Int32(bitPattern: {text})"
                        | Some (Int32T | UInt32T | CharT), Float32T -> $"Float({text})"
                        | Some (Int32T | UInt32T | CharT | Float32T), Float64T -> $"Double({text})"
                        | Some Float32T, (Int32T | CharT) -> $"Int32({text})"
                        | Some Float32T, UInt32T -> $"UInt32({text})"
                        | Some Float64T, Float32T -> $"Float({text})"
                        | Some Float64T, (Int32T | CharT) -> $"Int32({text})"
                        | Some Float64T, UInt32T -> $"UInt32({text})"
                        | Some (Int32T | CharT | UInt32T), Int64T -> $"Int64({text})"
                        | Some (Int32T | CharT | UInt32T), UInt64T -> $"UInt64(truncatingIfNeeded: {text})"
                        | Some Int64T, (Int32T | CharT) -> $"Int32(truncatingIfNeeded: {text})"
                        | Some Int64T, UInt32T -> $"UInt32(truncatingIfNeeded: {text})"
                        | Some Int64T, UInt64T -> $"UInt64(bitPattern: {text})"
                        | Some UInt64T, (Int32T | CharT) -> $"Int32(truncatingIfNeeded: {text})"
                        | Some UInt64T, UInt32T -> $"UInt32(truncatingIfNeeded: {text})"
                        | Some UInt64T, Int64T -> $"Int64(bitPattern: {text})"
                        | Some (Int64T | UInt64T), Float64T -> $"Double({text})"
                        | Some (Int64T | UInt64T), Float32T -> $"Float({text})"
                        | Some (Float32T | Float64T), Int64T -> $"Int64({text})"
                        | Some (Float32T | Float64T), UInt64T -> $"UInt64({text})"
                        | Some (Int32T | CharT), Int8T -> $"Int8(truncatingIfNeeded: {text})"
                        | Some (Int32T | CharT), Int16T -> $"Int16(truncatingIfNeeded: {text})"
                        | Some (Int32T | CharT), UInt8T -> $"UInt8(truncatingIfNeeded: {text})"
                        | Some (Int32T | CharT), UInt16T -> $"UInt16(truncatingIfNeeded: {text})"
                        | Some (Int8T | Int16T | UInt8T | UInt16T), (Int32T | CharT) -> $"Int32({text})"
                        | Some BoolT, (Int32T | CharT) -> $"(if {text} {{ 1 }} else {{ 0 }})"
                        | Some BoolT, UInt32T -> $"UInt32(if {text} {{ 1 }} else {{ 0 }})"
                        | Some (Int32T | CharT | UInt32T), BoolT ->
                            let zero_lit = if swift_of b = "UInt32" then "UInt32(0)" else "0"
                            $"({text} != {zero_lit})"
                        | _ -> unsupported "this conversion"
                return' converted
            // exit(1) matches C's EXIT_FAILURE. withCString keeps the message a C string for fputs.
            | TyFailwith(_, b) ->
                line s $"{tup b}.withCString {{ ptr in _ = fputs(ptr, stderr) }}"
                line s "fputs(\"\\n\", stderr)"
                line s "exit(1)"
            | TyMacro parts ->
                let piece = function
                    | CMText x -> x
                    | CMTerm (x, true) -> data_term_vars x |> Array.map show_w |> String.concat ", "
                    | CMTerm (x, false) -> tup x
                    | CMType x -> tyv x
                    | CMTypeLit _ -> unsupported "a macro type literal"
                return' (parts |> List.map piece |> String.concat "")
            | TyOp(Global, [DLit (LitString text)]) ->
                if globals_seen.Add text then globals.Add text
                return' ""
            | TyOp(Global, _) -> unsupported "globals"
            | TyOp(operation, l) ->
                let binary symbol a b = $"({tup a} {symbol} {tup b})"
                let arith plain wrap a b =
                    let op = if floated a b then plain else wrap
                    $"({tup a} {op} {tup b})"
                let expr =
                    match operation, l with
                    | Dyn, [a] -> tup a
                    | UnionTag, [a] -> $"({tup a}).tag"
                    | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                    | Add, [a;b] -> arith "+" "&+" a b
                    | Sub, [a;b] -> arith "-" "&-" a b
                    | Mult, [a;b] -> arith "*" "&*" a b
                    | Div, [a;b] -> binary "/" a b
                    | Mod, [a;b] ->
                        if floated a b then unsupported "float remainder" else binary "%" a b
                    | LT, [a;b] -> binary "<" a b
                    | LTE, [a;b] -> binary "<=" a b
                    | GT, [a;b] -> binary ">" a b
                    | GTE, [a;b] -> binary ">=" a b
                    | EQ, [a;b] -> binary "==" a b
                    | NEQ, [a;b] -> binary "!=" a b
                    | BoolAnd, [a;b] -> binary "&&" a b
                    | BoolOr, [a;b] -> binary "||" a b
                    | BitwiseAnd, [a;b] -> binary "&" a b
                    | BitwiseOr, [a;b] -> binary "|" a b
                    | BitwiseXor, [a;b] -> binary "^" a b
                    | BitwiseComplement, [a] -> $"(~({tup a}))"
                    | ShiftLeft, [a;b] -> binary "<<" a b
                    | ShiftRight, [a;b] -> binary ">>" a b
                    | Neg, [a] -> $"(-({tup a}))"
                    | PrimToString, [a] ->
                        match a with
                        | DLit(LitChar _) | DV(L(_,YPrim CharT)) -> $"String(UnicodeScalar(UInt8(truncatingIfNeeded: {tup a})))"
                        | _ -> $"String({tup a})"
                    | NanIs, [a] -> $"({tup a}.isNaN)"
                    | StdoutFlush, [] -> ""
                    | StringIndex, [a;b] ->
                        string_helpers ()
                        let index = match swift_of b with "Int32" -> tup b | _ -> unsupported "a string index that is not an i32"
                        $"spiralStringIndex({tup a}, {index})"
                    | StringSlice, [a;b;c] ->
                        string_helpers ()
                        let index d = match swift_of d with "Int32" -> tup d | _ -> unsupported "a string index that is not an i32"
                        $"spiralStringSlice({tup a}, {index b}, {index c})"
                    | StaticStringConcat, [a;b] -> $"({tup a} + {tup b})"
                    | ArrayIndex, [a;b] ->
                        let index = match swift_of b with "Int32" -> tup b | _ -> unsupported "an array index that is not an i32"
                        $"{tup a}.items[Int({index})]"
                    | ArrayIndexSet, [a;b;c] ->
                        let index = match swift_of b with "Int32" -> tup b | _ -> unsupported "an array index that is not an i32"
                        let value =
                            match data_term_vars c with
                            | [|w|] -> show_w w
                            | many ->
                                let items = many |> Array.map show_w |> String.concat ", "
                                $"({items})"
                        $"{tup a}.items[Int({index})] = {value}"
                    | (Sqrt | Log | Exp | Tanh | Sin | Cos), [a] when floated a a ->
                        let name = match operation with Sqrt -> "sqrt" | Log -> "log" | Exp -> "exp" | Tanh -> "tanh" | Sin -> "sin" | _ -> "cos"
                        let suffix = match prim_of a with Some Float32T -> "f" | _ -> ""
                        $"{name}{suffix}({tup a})"
                    | Pow, [a;b] when floated a b ->
                        let suffix = match prim_of a with Some Float32T -> "f" | _ -> ""
                        $"pow{suffix}({tup a}, {tup b})"
                    | Printf, [DLit (LitString fmt); b] ->
                        match printf_pieces fmt (data_term_vars b) with
                        | [] -> ""
                        | pieces ->
                            let text =
                                pieces |> List.map (function
                                    | Choice1Of2 piece -> show_w (WLit (LitString piece))
                                    | Choice2Of2 ('s', a) -> show_w a
                                    | Choice2Of2 (_, a) -> $"String({show_w a})")
                                |> String.concat " + "
                            $"_ = fputs({text}, stdout)"
                    | _ -> unsupported $"the operation {operation}"
                return' expr
            | TyArrayCreate(a, b) ->
                let element, element_zero =
                    match env.ty_to_data a |> data_free_vars |> Array.map (fun (L(_, t)) -> tyv t) with
                    | [|t|] -> t, zero t
                    | [||] -> unsupported "an array of unit elements"
                    | many ->
                        let types = String.concat ", " many
                        let zeros = many |> Array.map zero |> String.concat ", "
                        $"({types})", $"({zeros})"
                let n = match swift_of b with "Int32" -> tup b | _ -> unsupported "an array length that is not an i32"
                return' $"SpiralArray<{element}>(Array(repeating: {element_zero}, count: Int({n})))"
            | TyArrayLength(t, b) ->
                match t with
                | YPrim (Int32T | CharT) -> return' $"Int32({tup b}.items.count)"
                | _ -> unsupported "array length of this width"
            | TyStringLength(t, b) ->
                string_helpers ()
                match t with
                | YPrim (Int32T | CharT) -> return' $"spiralStringLength({tup b})"
                | _ -> unsupported "string length of this width"
            | TyUnionBox(tag_id, payload, union_h) ->
                let name, rec_f = union_ref union_h
                let i = union_case_tag rec_f tag_id
                let case_name = $"{name}_{unionCaseSuffix rec_f i}"
                let args = data_term_vars payload |> Array.mapi (fun f w -> $"f{f}: {show_w w}") |> String.concat ", "
                return' $"{case_name}({args})"
            | TyUnionUnbox(scrutinees, union_h, on_succs, on_fail) ->
                let name, rec_f = union_ref union_h
                let s' = indent s
                let s'' = indent s'
                let head = match scrutinees with L(i,_) :: _ -> $"v{i}.tag" | [] -> raise_codegen_error "Compiler error: A union unbox has no scrutinee."
                let shared_tag =
                    match List.pairwise scrutinees |> List.map (fun (L(i,_), L(i',_)) -> $"v{i}.tag == v{i'}.tag") with
                    | [] -> head
                    | equal ->
                        let all_equal = String.concat " && " equal
                        $"({all_equal} ? {head} : -1)"
                line s $"switch {shared_tag} {{"
                on_succs |> Map.iter (fun k (payloads, body) ->
                    let c = union_case_tag rec_f k
                    let case_name = $"{name}_{unionCaseSuffix rec_f c}"
                    line s' $"case {c}:"
                    List.iter2 (fun (L(i,_)) a ->
                        data_free_vars a |> Array.iteri (fun f (L(vi, t)) ->
                            let ft = tyv t
                            line s'' $"var v{vi}: {ft} = (v{i} as! {case_name}).f{f}")) scrutinees payloads
                    binds s'' ret body)
                line s' "default:"
                match on_fail with
                | Some b -> binds s'' ret b
                | None -> line s'' "fatalError(\"unreachable union case\")"
                line s "}"
            | TyApply(L(i,_), b) ->
                let arguments = data_term_vars b |> Array.map show_w |> String.concat ", "
                return' $"v{i}({arguments})"
            | TyToLayout(payload, layout_ty) ->
                let name = ensure_layout layout_ty
                let _, _, free_vars = layout_seen.[show_ty layout_ty]
                return' (layout_new name free_vars payload)
            | TyLayoutIndexAll(L(i, layout_ty)) ->
                ensure_layout layout_ty |> ignore
                let _, _, free_vars = layout_seen.[show_ty layout_ty]
                assign_reads i free_vars
            | TyLayoutIndexByKey(L(i, layout_ty), key) ->
                ensure_layout layout_ty |> ignore
                let _, data, _ = layout_seen.[show_ty layout_ty]
                match data with
                | DRecord fields ->
                    match fields |> Map.tryPick (fun (_, k) field -> if LayoutFieldNameIdOps.matchesText key k then Some (data_free_vars field) else None) with
                    | Some found -> assign_reads i found
                    | None -> raise_codegen_error "Compiler error: A layout has no such field."
                | _ -> raise_codegen_error "Compiler error: Expected a record layout."
            | TyLayoutMutableSet(L(i, layout_ty), keys, value) ->
                match layout_ty with
                | YLayout(_, HeapMutable) -> ()
                | YLayout(_, Heap) -> unsupported "setting an immutable layout"
                | YLayout(_, StackMutable) -> unsupported "stack mutable layout types"
                | YLayout _ -> unsupported "a ref layout"
                | _ -> raise_codegen_error "Compiler error: Expected a layout type."
                ensure_layout layout_ty |> ignore
                let _, data, _ = layout_seen.[show_ty layout_ty]
                let target =
                    List.fold (fun current key ->
                        match current with
                        | DRecord fields -> fields |> Map.pick (fun (_, k) field -> if LayoutFieldNameIdOps.matchesText key k then Some field else None)
                        | _ -> raise_codegen_error "Compiler error: Expected a record layout.") data keys
                let fields = data_free_vars target
                let terms = data_term_vars value
                if fields.Length <> terms.Length then raise_codegen_error "Compiler error: A layout set has the wrong number of values."
                Array.iter2 (fun (L(fi,_)) term -> line s $"v{i}.l{fi} = {show_w term}") fields terms
            | other ->
                let construct = (sprintf "%A" other).Split('(').[0]
                unsupported construct
        and method_memo = lazy (
            let dict = Dictionary(HashIdentity.Structural)
            fun ((jp_body, key) : _ * _) ->
                match dict.TryGetValue((jp_body, key)) with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[(jp_body, key)] <- tag
                    let args = codegenMethodKeyArgs key
                    match codegenMethodBody env "Swift" jp_body key with
                    | body, range, name ->
                        method_names.[tag] <- "sp_" + generatedMethodName name tag
                        emit_function method_names.[tag] (Some tag) (rdata_free_vars args) range body
                    tag)
        and method (a, b) : int = method_memo.Force() (a, b)
        and closure_memo = lazy (
            let dict = Dictionary(HashIdentity.Structural)
            fun ((jp_body, key & (C(args,_,fun_ty))) : _ * _) ->
                match dict.TryGetValue((jp_body, key)) with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[(jp_body, key)] <- tag
                    match fun_ty with
                    | YFun(_, range, FT_Vanilla) ->
                        match codegenClosureBody env "Swift" jp_body key with
                        | domain_args, body, sourceName ->
                            closure_names.[tag] <- generatedClosureName sourceName tag
                            let captured = rdata_free_vars args
                            let domain_vs = data_free_vars domain_args
                            let text = StringBuilder()
                            let cap_formals = captured |> Array.map (fun (L(i,t)) -> $"_ v{i}: {parameter_ty t}") |> String.concat ", "
                            text.Append($"func {closure_names.[tag]}({cap_formals}) -> {tyv fun_ty} {{").Append('\n') |> ignore
                            let s0 = { text = text; indent = 4 }
                            let dom =
                                match domain_vs with
                                | [||] -> "()"
                                | vs -> vs |> Array.map (fun (L(i,t)) -> $"v{i}: {parameter_ty t}") |> String.concat ", " |> sprintf "(%s)"
                            let result =
                                match env.ty_to_data range |> data_free_vars |> Array.map (fun (L(_, t)) -> tyv t) with
                                | [||] -> "Void"
                                | [|t|] -> t
                                | rets -> "(" + String.concat ", " rets + ")"
                            let saved = self_loop.Value
                            self_loop.Value <- None
                            try
                                line s0 $"return {{ {dom} -> {result} in"
                                binds (indent s0) (SwiftTail range) body
                                line s0 "}"
                            finally
                                self_loop.Value <- saved
                            text.Append("}").Append('\n') |> ignore
                            functions.Add(text.ToString())
                    | _ -> unsupported "this function type"
                    tag)
        and closure (a, b) : int = closure_memo.Force() (a, b)

        let unit_main =
            match Array.tryLast x with
            | Some (TyLocalReturnOp(_,_,d)) | Some (TyLocalReturnData(d,_)) ->
                match data_term_vars d |> Array.map (function WV(L(_,t)) -> t | WLit l -> YPrim (lit_to_primitive_type l)) with
                | [||] -> true
                | [|YPrim Int32T|] -> false
                | _ -> raise_codegen_error "The return type of main in the Swift backend should be a 32-bit int (or unit)."
            | _ -> true
        emit_function "spiral_main" None [||] (if unit_main then YB else YPrim Int32T) x
        let program = StringBuilder()
        program.AppendLine("import CRT").AppendLine("import WinSDK") |> ignore
        globals |> Seq.iter (fun text -> program.AppendLine(text) |> ignore)
        layout_types |> Seq.iter (fun text -> program.Append(text) |> ignore)
        union_types |> Seq.iter (fun text -> program.Append(text) |> ignore)
        helpers |> Seq.iter (fun text -> program.Append(text) |> ignore)
        functions |> Seq.iter (fun fn -> program.Append(fn) |> ignore)
        program.AppendLine("nonisolated(unsafe) var spiral_exit_code: Int32 = 0") |> ignore
        if unit_main then program.AppendLine("let spiral_thread = CreateThread(nil, 1 << 30, { _ in spiral_main(); return 0 }, nil, DWORD(STACK_SIZE_PARAM_IS_A_RESERVATION), nil)") |> ignore
        else program.AppendLine("let spiral_thread = CreateThread(nil, 1 << 30, { _ in spiral_exit_code = spiral_main(); return 0 }, nil, DWORD(STACK_SIZE_PARAM_IS_A_RESERVATION), nil)") |> ignore
        program.AppendLine("WaitForSingleObject(spiral_thread, INFINITE)").AppendLine("exit(spiral_exit_code)") |> ignore
        program.ToString() |> valAtAssignment "let"

    // OpenQASM 3 classical subset. Fixed-width arithmetic wraps in the simulator.
    // There is no tuple return, and self-tail calls become while/continue.
    // output int[32] spiral_io is main's result. The program prints nothing.

    /// ### OpenQasmRet
    type OpenQasmRet =
        | OpenQasmLocal of TyV []
        | OpenQasmTail of Ty

    /// ### codegenOpenQasm
    let codegenOpenQasm (env : PartEvalResult) (x : TypedBind []) =
        let functions = ResizeArray<string>()
        let method_names = Dictionary<int, string>()
        let unsupported what = raise_codegen_error $"The OpenQASM backend doesn't support {what} yet."
        let is_unit_ty = function YB -> true | _ -> false
        let tyv = function
            | YPrim Int32T | YPrim CharT -> "int[32]"
            | YPrim UInt32T -> "uint[32]"
            | YPrim BoolT -> "bool"
            | YPrim Float32T -> "float[32]"
            | YPrim Float64T -> "float[64]"
            | YPrim Int64T -> "int[64]"
            | YPrim UInt64T -> "uint[64]"
            | YPrim Int8T -> "int[8]"
            | YPrim UInt8T -> "uint[8]"
            | YPrim Int16T -> "int[16]"
            | YPrim UInt16T -> "uint[16]"
            | YPrim t -> unsupported $"the primitive {t}"
            | t -> unsupported $"the type {show_ty t}"
        let zero = function
            | "int[32]" -> "0"
            | "uint[32]" -> "0"
            | "int[64]" -> "0"
            | "uint[64]" -> "0"
            | "int[8]" | "uint[8]" | "int[16]" | "uint[16]" -> "0"
            | "bool" -> "false"
            | "float[32]" -> "0.0"
            | "float[64]" -> "0.0"
            | other -> unsupported $"a zero value of {other}"
        let lit = function
            | LitInt32 x when x = Int32.MinValue -> "(-2147483648)"
            | LitInt32 x -> string x
            | LitUInt32 x -> string x
            | LitInt64 x when x = Int64.MinValue -> "(-9223372036854775808)"
            | LitInt64 x -> string x
            | LitUInt64 x -> string x
            | LitInt8 x when x = SByte.MinValue -> "(-128)"
            | LitInt8 x -> string x
            | LitUInt8 x -> string x
            | LitInt16 x when x = Int16.MinValue -> "(-32768)"
            | LitInt16 x -> string x
            | LitUInt16 x -> string x
            | LitBool x -> if x then "true" else "false"
            | LitChar x -> string (int x)
            | LitFloat32 x when Single.IsNaN x -> "((1e308 * 10.0) - (1e308 * 10.0))"
            | LitFloat32 x when Single.IsPositiveInfinity x -> "(1e308 * 10.0)"
            | LitFloat32 x when Single.IsNegativeInfinity x -> "(-(1e308 * 10.0))"
            | LitFloat32 x ->
                let text = x.ToString("R", Globalization.CultureInfo.InvariantCulture)
                if text.Contains('.') || text.Contains('e') || text.Contains('E') then text else text + ".0"
            | LitFloat64 x when Double.IsNaN x -> "((1e308 * 10.0) - (1e308 * 10.0))"
            | LitFloat64 x when Double.IsPositiveInfinity x -> "(1e308 * 10.0)"
            | LitFloat64 x when Double.IsNegativeInfinity x -> "(-(1e308 * 10.0))"
            | LitFloat64 x ->
                let text = x.ToString("R", Globalization.CultureInfo.InvariantCulture)
                if text.Contains('.') || text.Contains('e') || text.Contains('E') then text else text + ".0"
            | l -> unsupported $"the literal {l}"
        let show_w = function WV (L(i,_)) -> $"v{i}" | WLit a -> lit a
        let prim_of = function
            | DV(L(_,YPrim t)) -> Some t
            | DLit l -> Some (lit_to_primitive_type l)
            | _ -> None
        let qasm_of d =
            match prim_of d with
            | Some t -> tyv (YPrim t)
            | None -> unsupported "an operation on a non-primitive"
        let tup d =
            match data_term_vars d with
            | [|w|] -> show_w w
            | [||] -> ""
            | ws -> ws |> Array.map show_w |> String.concat ", "
        let rec flatten_ty t =
            match t with
            | YB -> [||]
            | YPair(a, b) -> Array.append (flatten_ty a) (flatten_ty b)
            | _ -> [|t|]
        let ret_tys range = flatten_ty range |> Array.map tyv
        let ret_ty range =
            match ret_tys range with
            | [||] -> ""
            | [|t|] -> t
            | ts -> "(" + String.concat ", " ts + ")"
        let statement (s : CodegenEnv) (text : string) =
            let trimmed = text.Trim()
            if trimmed <> "" then
                let with_semi = if trimmed.EndsWith(";") then trimmed else trimmed + ";"
                line s with_semi
        let self_loop : (int * TyV []) option ref = ref None
        let rec emit_function (name : string) (tag : int option) (parameters : TyV []) (range : Ty) (body : TypedBind []) =
            let saved = self_loop.Value
            let tail = match tag with Some t when self_tail t body -> true | _ -> false
            if tail then self_loop.Value <- Some (tag.Value, parameters)
            try
                let text = StringBuilder()
                let formals = parameters |> Array.map (fun (L(i,t)) -> $"{tyv t} p{i}") |> String.concat ", "
                let result = ret_ty range
                let signature = if result = "" then $"def {name}({formals}) {{" else $"def {name}({formals}) -> {result} {{"
                text.Append(signature).Append('\n') |> ignore
                let s0 = { text = text; indent = 4 }
                parameters |> Array.iter (fun (L(i,t)) -> statement s0 $"{tyv t} v{i} = p{i}")
                if tail then
                    line s0 "while (true) {"
                    binds (indent s0) (OpenQasmTail range) body
                    line s0 "}"
                    if result <> "" then
                        let dead = ret_tys range |> Array.map zero |> String.concat ", "
                        statement s0 $"return {dead}"
                else binds s0 (OpenQasmTail range) body
                text.Append("}").Append('\n') |> ignore
                functions.Add(text.ToString())
            finally
                self_loop.Value <- saved
        and self_tail tag (body : TypedBind []) =
            body.Length > 0 &&
            match Array.last body with
            | TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _) -> method (a,c) = tag
            | TyLocalReturnOp(_, TyIf(_,tr,fl), _) -> self_tail tag tr || self_tail tag fl
            | TyLocalReturnOp(_, TyIntSwitch(_,on_succ,on_fail), _) -> Array.exists (self_tail tag) on_succ || self_tail tag on_fail
            | TyLocalReturnOp(_, (TyDo b | TyIndent b), _) -> self_tail tag b
            | _ -> false
        and binds (s : CodegenEnv) (ret : OpenQasmRet) (stmts : TypedBind []) =
            Array.iter (function
                | TyLet(d,trace,a) ->
                    try
                        let vs = data_free_vars d
                        vs |> Array.iter (fun (L(i,t)) -> statement s $"{tyv t} v{i} = {zero (tyv t)}")
                        op s (OpenQasmLocal vs) a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) ->
                    try op s ret a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) ->
                    try
                        match ret with
                        | OpenQasmLocal targets ->
                            let values = data_term_vars d
                            if targets.Length <> values.Length then raise_codegen_error "Compiler error: A binding has the wrong number of values."
                            Array.iter2 (fun (L(i,_)) w -> statement s $"v{i} = {show_w w}") targets values
                        | OpenQasmTail _ ->
                            match data_term_vars d with
                            | [||] -> ()
                            | [|w|] -> statement s $"return {show_w w}"
                            | ws ->
                                let values = ws |> Array.map show_w |> String.concat ", "
                                statement s $"return {values}"
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) stmts
        and op (s : CodegenEnv) (ret : OpenQasmRet) a =
            let return' (x : string) =
                match ret with
                | OpenQasmLocal [||] -> statement s x
                | OpenQasmLocal [|L(i,_)|] -> statement s $"v{i} = {x}"
                | OpenQasmLocal targets ->
                    let names = targets |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
                    statement s $"{names} = {x}"
                | OpenQasmTail range when is_unit_ty range -> statement s x
                | OpenQasmTail _ -> statement s $"return {x}"
            let jp_text (jp, args) =
                match jp with
                | JPMethod(a,c) ->
                    let name = method_names.[method (a,c)]
                    let arguments = args |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
                    $"{name}({arguments})"
                | JPClosure _ -> unsupported "closures"
            let is_self (a, c) =
                match ret, self_loop.Value with
                | OpenQasmTail _, Some (tag, _) -> method (a,c) = tag
                | _ -> false
            match a with
            | TyIf(cond,tr,fl) ->
                line s $"if ({tup cond}) {{"
                binds (indent s) ret tr
                line s "} else {"
                binds (indent s) ret fl
                line s "}"
            | TyJoinPoint(JPMethod(a,c), arguments) when is_self (a, c) ->
                let _, parameters = self_loop.Value.Value
                if arguments.Length <> parameters.Length then raise_codegen_error "Compiler error: A tail call has the wrong number of arguments."
                let types = parameters |> Array.map (fun (L(i,t)) -> i, t) |> dict
                let temps = System.Collections.Generic.Dictionary<int, string> ()
                for step in parallelMoves (Array.map2 (fun (L(target,_)) (L(source,_)) -> target, source) parameters arguments) do
                    match step with
                    | MoveVar (target, source) -> statement s $"v{target} = v{source}"
                    | SaveTemp (slot, source) ->
                        temps.[slot] <- $"t{s.text.Length}_{source}"
                        statement s $"{tyv types.[source]} {temps.[slot]} = v{source}"
                    | MoveTemp (target, slot) -> statement s $"v{target} = {temps.[slot]}"
                statement s "continue"
            | TyJoinPoint(jp, args) -> return' (jp_text (jp, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The OpenQASM backend does not support nesting other backends."
            | TyWhile(cond, body) ->
                match ret with
                | OpenQasmLocal [||] -> ()
                | OpenQasmTail range when is_unit_ty range -> ()
                | _ -> unsupported "a while loop in value position"
                line s "while (true) {"
                line (indent s) $"if (!({jp_text cond})) {{"
                statement (indent (indent s)) "break"
                line (indent s) "}"
                binds (indent s) (OpenQasmLocal [||]) body
                line s "}"
            | TyDo body | TyIndent body -> binds s ret body
            | TyConv(YPrim target, b) ->
                let source = prim_of b
                let text = tup b
                let same =
                    match source with
                    | Some s when s = target -> true
                    | Some CharT when target = Int32T -> true
                    | Some Int32T when target = CharT -> true
                    | _ -> false
                let converted =
                    if same then text
                    else
                        let integral = function Int8T | UInt8T | Int16T | UInt16T | Int32T | UInt32T | CharT | Int64T | UInt64T -> true | _ -> false
                        match source, target with
                        | Some s, t when integral s && integral t -> text
                        | Some s, (Float32T | Float64T) when integral s -> $"{tyv (YPrim target)}({text})"
                        | Some (Float32T | Float64T), (Float32T | Float64T) -> $"{tyv (YPrim target)}({text})"
                        | Some (Float32T | Float64T), t when integral t -> $"{tyv (YPrim t)}({text})"
                        | Some BoolT, t when integral t -> $"(if {text} {{ 1 }} else {{ 0 }})"
                        | Some s, BoolT when integral s -> $"({text} != 0)"
                        | _ -> unsupported "this conversion"
                return' converted
            | TyFailwith _ -> unsupported "failwith"
            | TyMacro parts ->
                let piece = function
                    | CMText x -> x
                    | CMTerm (x, true) -> data_term_vars x |> Array.map show_w |> String.concat ", "
                    | CMTerm (x, false) -> tup x
                    | CMType x -> tyv x
                    | CMTypeLit _ -> unsupported "a macro type literal"
                return' (parts |> List.map piece |> String.concat "")
            | TyOp(Global, _) -> unsupported "globals"
            | TyOp(operation, l) ->
                let binary symbol a b = $"({tup a} {symbol} {tup b})"
                let expr =
                    match operation, l with
                    | Dyn, [a] -> tup a
                    | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                    | Add, [a;b] -> binary "+" a b
                    | Sub, [a;b] -> binary "-" a b
                    | Mult, [a;b] -> binary "*" a b
                    | Div, [a;b] -> binary "/" a b
                    | Mod, [a;b] -> binary "%" a b
                    | LT, [a;b] -> binary "<" a b
                    | LTE, [a;b] -> binary "<=" a b
                    | GT, [a;b] -> binary ">" a b
                    | GTE, [a;b] -> binary ">=" a b
                    | EQ, [a;b] -> binary "==" a b
                    | NEQ, [a;b] -> binary "!=" a b
                    | BoolAnd, [a;b] -> binary "&&" a b
                    | BoolOr, [a;b] -> binary "||" a b
                    | BitwiseAnd, [a;b] -> binary "&" a b
                    | BitwiseOr, [a;b] -> binary "|" a b
                    | BitwiseXor, [a;b] -> binary "^" a b
                    | BitwiseComplement, [a] -> $"(~({tup a}))"
                    | ShiftLeft, [a;b] -> binary "<<" a b
                    | ShiftRight, [a;b] -> binary ">>" a b
                    | Neg, [a] -> $"(-({tup a}))"
                    | NanIs, [a] -> $"({tup a} != {tup a})"
                    | StdoutFlush, [] -> ""
                    | Sqrt, [a] -> $"sqrt({tup a})"
                    | Exp, [a] -> $"exp({tup a})"
                    | Log, [a] -> $"log({tup a})"
                    | Sin, [a] -> $"sin({tup a})"
                    | Cos, [a] -> $"cos({tup a})"
                    | Tanh, [a] -> $"tanh({tup a})"
                    | Pow, [a;b] when (match prim_of a with Some (Float32T | Float64T) -> true | _ -> false) -> $"pow({tup a}, {tup b})"
                    | _ -> unsupported $"the operation {operation}"
                return' expr
            | other ->
                let construct = (sprintf "%A" other).Split('(').[0]
                unsupported construct
        and method_memo = lazy (
            let dict = Dictionary(HashIdentity.Structural)
            fun ((jp_body, key) : _ * _) ->
                match dict.TryGetValue((jp_body, key)) with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[(jp_body, key)] <- tag
                    let args = codegenMethodKeyArgs key
                    match codegenMethodBody env "OpenQasm" jp_body key with
                    | body, range, name ->
                        method_names.[tag] <- "sp_" + generatedMethodName name tag
                        emit_function method_names.[tag] (Some tag) (rdata_free_vars args) range body
                    tag)
        and method (a, b) : int = method_memo.Force() (a, b)

        let unit_main =
            match Array.tryLast x with
            | Some (TyLocalReturnOp(_,_,d)) | Some (TyLocalReturnData(d,_)) ->
                match data_term_vars d |> Array.map (function WV(L(_,t)) -> t | WLit l -> YPrim (lit_to_primitive_type l)) with
                | [||] -> true
                | [|YPrim Int32T|] -> false
                | _ -> raise_codegen_error "The return type of main in the OpenQASM backend should be a 32-bit int (or unit)."
            | _ -> true
        emit_function "spiral_main" None [||] (if unit_main then YB else YPrim Int32T) x
        let program = StringBuilder()
        program.AppendLine("OPENQASM 3.0;") |> ignore
        functions |> Seq.iter (fun fn -> program.Append(fn) |> ignore)
        program.AppendLine("output int[32] spiral_io;") |> ignore
        if unit_main then program.AppendLine("spiral_io = 0;") |> ignore
        else program.AppendLine("spiral_io = spiral_main();") |> ignore
        program.ToString()

    // eBPF as a C profile. Loops carry a constant trip cap, recursion is rejected,
    // and maps are a fixed array. The host C compiler runs it. Nothing is printed.

    /// ### EbpfRet
    type EbpfRet =
        | EbpfLocal of TyV []
        | EbpfTail of Ty

    /// ### codegenEbpf
    let codegenEbpf (env : PartEvalResult) (x : TypedBind []) =
        let functions = ResizeArray<string>()
        let method_names = Dictionary<int, string>()
        let tuple_structs = ResizeArray<string>()
        let tuple_names = Dictionary<string, string>()
        let unsupported what = raise_codegen_error $"The eBPF backend doesn't support {what} yet."
        let is_unit_ty = function YB -> true | _ -> false
        let tyv = function
            | YPrim Int32T | YPrim CharT -> "int32_t"
            | YPrim UInt32T -> "uint32_t"
            | YPrim BoolT -> "bool"
            | YPrim Float32T -> "float"
            | YPrim Float64T -> unsupported "f64"
            | YPrim Int64T -> "int64_t"
            | YPrim UInt64T -> "uint64_t"
            | YPrim Int8T -> "int8_t"
            | YPrim UInt8T -> "uint8_t"
            | YPrim Int16T -> "int16_t"
            | YPrim UInt16T -> "uint16_t"
            | YPrim t -> unsupported $"the primitive {t}"
            | t -> unsupported $"the type {show_ty t}"
        let zero = function
            | "int32_t" -> "0"
            | "uint32_t" -> "0u"
            | "int64_t" -> "0ll"
            | "uint64_t" -> "0ull"
            | "int8_t" | "uint8_t" | "int16_t" | "uint16_t" -> "0"
            | "bool" -> "false"
            | "float" -> "0.0f"
            | other -> unsupported $"a zero value of {other}"
        let lit = function
            | LitInt32 x when x = Int32.MinValue -> "INT32_MIN"
            | LitInt32 x -> string x
            | LitUInt32 x -> $"{x}u"
            | LitInt64 x when x = Int64.MinValue -> "INT64_MIN"
            | LitInt64 x -> $"{x}ll"
            | LitUInt64 x -> $"{x}ull"
            | LitInt8 x -> string x
            | LitUInt8 x -> string x
            | LitInt16 x -> string x
            | LitUInt16 x -> string x
            | LitBool x -> if x then "true" else "false"
            | LitChar x -> string (int x)
            | LitFloat32 x when Single.IsNaN x -> unsupported "NaN"
            | LitFloat32 x when Single.IsPositiveInfinity x -> unsupported "infinity"
            | LitFloat32 x when Single.IsNegativeInfinity x -> unsupported "infinity"
            | LitFloat32 x ->
                let text = x.ToString("R", Globalization.CultureInfo.InvariantCulture)
                let text = if text.Contains('.') || text.Contains('e') || text.Contains('E') then text else text + ".0"
                if text.StartsWith("-") then "(" + text + "f)" else text + "f"
            | l -> unsupported $"the literal {l}"
        let show_w = function WV (L(i,_)) -> $"v{i}" | WLit a -> lit a
        let prim_of = function
            | DV(L(_,YPrim t)) -> Some t
            | DLit l -> Some (lit_to_primitive_type l)
            | _ -> None
        let floated a b =
            match prim_of a, prim_of b with
            | Some Float32T, _ | _, Some Float32T -> true
            | _ -> false
        let tup d =
            match data_term_vars d with
            | [|w|] -> show_w w
            | [||] -> ""
            | _ -> unsupported "tuple values"
        let rec flatten_ty t =
            match t with
            | YB -> [||]
            | YPair(a, b) -> Array.append (flatten_ty a) (flatten_ty b)
            | _ -> [|t|]
        let tuple_name (tys : string []) =
            let key = String.concat "," tys
            match tuple_names.TryGetValue(key) with
            | true, name -> name
            | _ ->
                let name = $"SpiralTuple{tuple_names.Count}"
                tuple_names.[key] <- name
                let fields = tys |> Array.mapi (fun i t -> $"{t} v{i};") |> String.concat " "
                tuple_structs.Add($"typedef struct {{ {fields} }} {name};") |> ignore
                name
        let ret_ty range =
            match flatten_ty range |> Array.map tyv with
            | [||] -> ""
            | [|t|] -> t
            | tys -> tuple_name tys
        let statement (s : CodegenEnv) (text : string) =
            let trimmed = text.Trim()
            if trimmed <> "" then
                let with_semi = if trimmed.EndsWith(";") then trimmed else trimmed + ";"
                line s with_semi
        let self_loop : (int * TyV []) option ref = ref None
        let rec emit_function (name : string) (tag : int option) (parameters : TyV []) (range : Ty) (body : TypedBind []) =
            let saved = self_loop.Value
            let tail = match tag with Some t when self_tail t body -> true | _ -> false
            if tail then self_loop.Value <- Some (tag.Value, parameters)
            try
                let text = StringBuilder()
                let formals =
                    let parts = parameters |> Array.map (fun (L(i,t)) -> $"{tyv t} p{i}")
                    if parts.Length = 0 then "void" else String.concat ", " parts
                let result = ret_ty range
                let signature = if result = "" then $"static void {name}({formals}) {{" else $"static {result} {name}({formals}) {{"
                text.Append(signature).Append('\n') |> ignore
                let s0 = { text = text; indent = 4 }
                parameters |> Array.iter (fun (L(i,t)) -> statement s0 $"{tyv t} v{i} = p{i}")
                if tail then
                    line s0 "for (int32_t spiral_trip = 0; spiral_trip < SPIRAL_LOOP_CAP; spiral_trip++) {"
                    binds (indent s0) (EbpfTail range) body
                    line s0 "}"
                    if result <> "" then
                        statement s0 "SPIRAL_LOOP_CAPPED()"
                        let dead =
                            match result with
                            | "int32_t" | "uint32_t" | "bool" | "float" -> zero result
                            | other -> $"({other}){{0}}"
                        statement s0 $"return {dead}"
                else binds s0 (EbpfTail range) body
                text.Append("}").Append('\n') |> ignore
                functions.Add(text.ToString())
            finally
                self_loop.Value <- saved
        and self_tail tag (body : TypedBind []) =
            body.Length > 0 &&
            match Array.last body with
            | TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _) -> method (a,c) = tag
            | TyLocalReturnOp(_, TyIf(_,tr,fl), _) -> self_tail tag tr || self_tail tag fl
            | TyLocalReturnOp(_, TyIntSwitch(_,on_succ,on_fail), _) -> Array.exists (self_tail tag) on_succ || self_tail tag on_fail
            | TyLocalReturnOp(_, (TyDo b | TyIndent b), _) -> self_tail tag b
            | _ -> false
        and binds (s : CodegenEnv) (ret : EbpfRet) (stmts : TypedBind []) =
            Array.iter (function
                | TyLet(d,trace,a) ->
                    try
                        let vs = data_free_vars d
                        vs |> Array.iter (fun (L(i,t)) -> statement s $"{tyv t} v{i} = {zero (tyv t)}")
                        op s (EbpfLocal vs) a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,_) ->
                    try op s ret a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) ->
                    try
                        match ret with
                        | EbpfLocal targets ->
                            let values = data_term_vars d
                            if targets.Length <> values.Length then raise_codegen_error "Compiler error: A binding has the wrong number of values."
                            Array.iter2 (fun (L(i,_)) w -> statement s $"v{i} = {show_w w}") targets values
                        | EbpfTail range ->
                            match data_term_vars d with
                            | [||] -> ()
                            | [|w|] -> statement s $"return {show_w w}"
                            | many ->
                                let args = many |> Array.map show_w |> String.concat ", "
                                statement s $"return ({ret_ty range}){{{args}}}"
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                ) stmts
        and op (s : CodegenEnv) (ret : EbpfRet) a =
            let return' (x : string) =
                match ret with
                | EbpfLocal [||] -> statement s x
                | EbpfLocal [|L(i,_)|] -> statement s $"v{i} = {x}"
                | EbpfLocal targets ->
                    let tys = targets |> Array.map (fun (L(_,t)) -> tyv t)
                    let tmp = $"spiral_tuple{s.text.Length}"
                    statement s $"{tuple_name tys} {tmp} = {x}"
                    targets |> Array.iteri (fun k (L(i,_)) -> statement s $"v{i} = {tmp}.v{k}")
                | EbpfTail range when is_unit_ty range -> statement s x
                | EbpfTail _ -> statement s $"return {x}"
            let jp_text (jp, args) =
                match jp with
                | JPMethod(a,c) ->
                    let name = method_names.[method (a,c)]
                    let arguments = args |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
                    $"{name}({arguments})"
                | JPClosure _ -> unsupported "closures"
            let is_self (a, c) =
                match ret, self_loop.Value with
                | EbpfTail _, Some (tag, _) -> method (a,c) = tag
                | _ -> false
            match a with
            | TyIf(cond,tr,fl) ->
                line s $"if ({tup cond}) {{"
                binds (indent s) ret tr
                line s "} else {"
                binds (indent s) ret fl
                line s "}"
            | TyJoinPoint(JPMethod(a,c), arguments) when is_self (a, c) ->
                let _, parameters = self_loop.Value.Value
                if arguments.Length <> parameters.Length then raise_codegen_error "Compiler error: A tail call has the wrong number of arguments."
                let types = parameters |> Array.map (fun (L(i,t)) -> i, t) |> dict
                let temps = System.Collections.Generic.Dictionary<int, string> ()
                for step in parallelMoves (Array.map2 (fun (L(target,_)) (L(source,_)) -> target, source) parameters arguments) do
                    match step with
                    | MoveVar (target, source) -> statement s $"v{target} = v{source}"
                    | SaveTemp (slot, source) ->
                        temps.[slot] <- $"t{s.text.Length}_{source}"
                        statement s $"{tyv types.[source]} {temps.[slot]} = v{source}"
                    | MoveTemp (target, slot) -> statement s $"v{target} = {temps.[slot]}"
                statement s "continue"
            | TyJoinPoint(jp, args) -> return' (jp_text (jp, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The eBPF backend does not support nesting other backends."
            | TyWhile(cond, body) ->
                match ret with
                | EbpfLocal [||] -> ()
                | EbpfTail range when is_unit_ty range -> ()
                | _ -> unsupported "a while loop in value position"
                line s "for (int32_t spiral_trip = 0; spiral_trip < SPIRAL_LOOP_CAP; spiral_trip++) {"
                statement (indent s) $"if (!({jp_text cond})) break"
                binds (indent s) (EbpfLocal [||]) body
                line s "}"
            | TyDo body | TyIndent body -> binds s ret body
            | TyConv(YPrim target, b) ->
                let source = prim_of b
                let text = tup b
                let same =
                    match source with
                    | Some s when s = target -> true
                    | Some CharT when target = Int32T -> true
                    | Some Int32T when target = CharT -> true
                    | _ -> false
                let converted =
                    if same then text
                    else
                        let integral = function Int8T | UInt8T | Int16T | UInt16T | Int32T | UInt32T | CharT | Int64T | UInt64T -> true | _ -> false
                        match source, target with
                        | Some s, t when integral s && integral t -> $"({tyv (YPrim t)})({text})"
                        | Some s, Float32T when integral s -> $"(float)({text})"
                        | Some Float32T, t when integral t -> $"({tyv (YPrim t)})({text})"
                        | Some BoolT, t when integral t -> $"({text} ? 1 : 0)"
                        | Some s, BoolT when integral s -> $"({text} != 0)"
                        | _ -> unsupported "this conversion"
                return' converted
            | TyFailwith _ -> unsupported "failwith"
            | TyMacro parts ->
                let piece = function
                    | CMText x -> x
                    | CMTerm (x, true) -> data_term_vars x |> Array.map show_w |> String.concat ", "
                    | CMTerm (x, false) -> tup x
                    | CMType x -> tyv x
                    | CMTypeLit _ -> unsupported "a macro type literal"
                return' (parts |> List.map piece |> String.concat "")
            | TyOp(Global, _) -> unsupported "globals"
            | TyOp(operation, l) ->
                let binary symbol a b = $"({tup a} {symbol} {tup b})"
                let expr =
                    match operation, l with
                    | Dyn, [a] -> tup a
                    | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                    | Add, [a;b] -> binary "+" a b
                    | Sub, [a;b] -> binary "-" a b
                    | Mult, [a;b] -> binary "*" a b
                    | Div, [a;b] -> binary "/" a b
                    | Mod, [a;b] ->
                        if floated a b then unsupported "float remainder" else binary "%" a b
                    | LT, [a;b] -> binary "<" a b
                    | LTE, [a;b] -> binary "<=" a b
                    | GT, [a;b] -> binary ">" a b
                    | GTE, [a;b] -> binary ">=" a b
                    | EQ, [a;b] -> binary "==" a b
                    | NEQ, [a;b] -> binary "!=" a b
                    | BoolAnd, [a;b] -> binary "&&" a b
                    | BoolOr, [a;b] -> binary "||" a b
                    | BitwiseAnd, [a;b] -> binary "&" a b
                    | BitwiseOr, [a;b] -> binary "|" a b
                    | BitwiseXor, [a;b] -> binary "^" a b
                    | BitwiseComplement, [a] -> $"(~({tup a}))"
                    | ShiftLeft, [a;b] -> binary "<<" a b
                    | ShiftRight, [a;b] -> binary ">>" a b
                    | Neg, [a] -> $"(-({tup a}))"
                    | NanIs, [a] -> unsupported "NaN"
                    | StdoutFlush, [] -> ""
                    | _ -> unsupported $"the operation {operation}"
                return' expr
            | other ->
                let construct = (sprintf "%A" other).Split('(').[0]
                unsupported construct
        and method_memo = lazy (
            let dict = Dictionary(HashIdentity.Structural)
            fun ((jp_body, key) : _ * _) ->
                match dict.TryGetValue((jp_body, key)) with
                | true, tag -> tag
                | _ ->
                    let tag = dict.Count
                    dict.[(jp_body, key)] <- tag
                    let args = codegenMethodKeyArgs key
                    match codegenMethodBody env "Ebpf" jp_body key with
                    | body, range, name ->
                        method_names.[tag] <- "sp_" + generatedMethodName name tag
                        emit_function method_names.[tag] (Some tag) (rdata_free_vars args) range body
                    tag)
        and method (a, b) : int = method_memo.Force() (a, b)

        let unit_main =
            match Array.tryLast x with
            | Some (TyLocalReturnOp(_,_,d)) | Some (TyLocalReturnData(d,_)) ->
                match data_term_vars d |> Array.map (function WV(L(_,t)) -> t | WLit l -> YPrim (lit_to_primitive_type l)) with
                | [||] -> true
                | [|YPrim Int32T|] -> false
                | _ -> raise_codegen_error "The return type of main in the eBPF backend should be a 32-bit int (or unit)."
            | _ -> true
        emit_function "spiral_main" None [||] (if unit_main then YB else YPrim Int32T) x
        let program = StringBuilder()
        program.AppendLine("#include <stdint.h>") |> ignore
        program.AppendLine("#include <stdbool.h>") |> ignore
        program.AppendLine("#define SPIRAL_MAP_CAP 64") |> ignore
        program.AppendLine("#ifdef __bpf__") |> ignore
        program.AppendLine("#define SPIRAL_LOOP_CAP 8192") |> ignore
        program.AppendLine("int32_t spiral_loop_capped;") |> ignore
        program.AppendLine("#define SPIRAL_LOOP_CAPPED() (spiral_loop_capped = 1)") |> ignore
        program.AppendLine("#else") |> ignore
        program.AppendLine("#define SPIRAL_LOOP_CAP 16777216") |> ignore
        program.AppendLine("#define SPIRAL_LOOP_CAPPED() ((void)0)") |> ignore
        program.AppendLine("#endif") |> ignore
        program.AppendLine("static int32_t spiral_map_key[SPIRAL_MAP_CAP];") |> ignore
        program.AppendLine("static int32_t spiral_map_val[SPIRAL_MAP_CAP];") |> ignore
        program.AppendLine("static int32_t spiral_map_used[SPIRAL_MAP_CAP];") |> ignore
        program.AppendLine("static int32_t spiral_map_lookup(int32_t key) {") |> ignore
        program.AppendLine("    int32_t i;") |> ignore
        program.AppendLine("    for (i = 0; i < SPIRAL_MAP_CAP; i++) {") |> ignore
        program.AppendLine("        if (spiral_map_used[i] && spiral_map_key[i] == key) return spiral_map_val[i];") |> ignore
        program.AppendLine("    }") |> ignore
        program.AppendLine("    return 0;") |> ignore
        program.AppendLine("}") |> ignore
        program.AppendLine("static int32_t spiral_map_update(int32_t key, int32_t val) {") |> ignore
        program.AppendLine("    int32_t i;") |> ignore
        program.AppendLine("    int32_t free_slot = -1;") |> ignore
        program.AppendLine("    for (i = 0; i < SPIRAL_MAP_CAP; i++) {") |> ignore
        program.AppendLine("        if (spiral_map_used[i] && spiral_map_key[i] == key) { spiral_map_val[i] = val; return 0; }") |> ignore
        program.AppendLine("        if (!spiral_map_used[i] && free_slot < 0) free_slot = i;") |> ignore
        program.AppendLine("    }") |> ignore
        program.AppendLine("    if (free_slot < 0) return 1;") |> ignore
        program.AppendLine("    spiral_map_used[free_slot] = 1;") |> ignore
        program.AppendLine("    spiral_map_key[free_slot] = key;") |> ignore
        program.AppendLine("    spiral_map_val[free_slot] = val;") |> ignore
        program.AppendLine("    return 0;") |> ignore
        program.AppendLine("}") |> ignore
        tuple_structs |> Seq.iter (fun row -> program.AppendLine(row) |> ignore)
        functions |> Seq.iter (fun fn -> program.Append(fn) |> ignore)
        program.AppendLine("#ifdef __bpf__") |> ignore
        program.AppendLine("#define SEC(name) __attribute__((section(name), used))") |> ignore
        program.AppendLine("int32_t spiral_exit_code;") |> ignore
        program.AppendLine("SEC(\"socket\")") |> ignore
        program.AppendLine("int spiral_socket(void *context) {") |> ignore
        if unit_main then
            program.AppendLine("    spiral_main();") |> ignore
            program.AppendLine("    spiral_exit_code = spiral_loop_capped ? -2147483647 : 0;") |> ignore
        else
            program.AppendLine("    int32_t spiral_result = spiral_main();") |> ignore
            program.AppendLine("    spiral_exit_code = spiral_loop_capped ? -2147483647 : spiral_result;") |> ignore
        program.AppendLine("    return 0;") |> ignore
        program.AppendLine("}") |> ignore
        program.AppendLine("char LICENSE[] SEC(\"license\") = \"GPL\";") |> ignore
        program.AppendLine("#else") |> ignore
        program.AppendLine("int main(void) {") |> ignore
        if unit_main then
            program.AppendLine("    spiral_main();") |> ignore
            program.AppendLine("    return 0;") |> ignore
        else program.AppendLine("    return spiral_main();") |> ignore
        program.AppendLine("}") |> ignore
        program.AppendLine("#endif") |> ignore
        program.ToString()

    /// ## CodegenTypescript

    /// ### backend_nameTypeScript
    let backend_nameTypeScript = "TypeScript"

    /// ### litTypeScriptString
    let litTypeScriptString (x : string) =
        let strb = StringBuilder(x.Length + 2)
        strb.Append '"' |> ignore
        for c in x do
            match c with
            | '"' -> strb.Append "\\\"" |> ignore
            | '\\' -> strb.Append @"\\" |> ignore
            | '\n' -> strb.Append @"\n" |> ignore
            | '\r' -> strb.Append @"\r" |> ignore
            | '\t' -> strb.Append @"\t" |> ignore
            | '\b' -> strb.Append @"\b" |> ignore
            | c when Char.IsControl c || c = ' ' || c = ' ' -> strb.Append("\\u").Append((int c).ToString("x4")) |> ignore
            | c -> strb.Append c |> ignore
        strb.Append '"' |> ignore
        strb.ToString()

    /// ### litTypeScriptFloat
    let litTypeScriptFloat (x : float) =
        if Double.IsPositiveInfinity x then "Infinity"
        elif Double.IsNegativeInfinity x then "(-Infinity)"
        elif Double.IsNaN x then "NaN"
        else
            let text = x.ToString("R", Globalization.CultureInfo.InvariantCulture)
            if text.StartsWith "-" then $"({text})" else text

    /// ### litTypeScript
    let litTypeScript = function
        | LitInt8 x -> if x < 0y then sprintf "(%i)" x else sprintf "%i" x
        | LitInt16 x -> if x < 0s then sprintf "(%i)" x else sprintf "%i" x
        | LitInt32 x -> if x < 0 then sprintf "(%i)" x else sprintf "%i" x
        | LitInt64 x -> if x < 0L then sprintf "(%in)" x else sprintf "%in" x
        | LitUInt8 x -> sprintf "%i" x
        | LitUInt16 x -> sprintf "%i" x
        | LitUInt32 x -> sprintf "%i" x
        | LitUInt64 x -> sprintf "%in" x
        | LitFloat32 x -> litTypeScriptFloat (float x)
        | LitFloat64 x -> litTypeScriptFloat x
        | LitString x -> litTypeScriptString x
        | LitChar x ->
            if int x > 127 then raise_codegen_error $"The TypeScript backend represents chars as UTF-8 bytes; '{x}' is not ASCII."
            sprintf "%i" (int x)
        | LitBool x -> if x then "true" else "false"

    /// ### primTypeScript
    let primTypeScript = function
        | Int8T | Int16T | Int32T | UInt8T | UInt16T | UInt32T | Float32T | Float64T | CharT -> "number"
        | Int64T | UInt64T -> "bigint"
        | BoolT -> "boolean"
        | StringT -> "string"

    /// ### type_litTypeScript
    let type_litTypeScript = function
        | YLit x -> litTypeScript x
        | YSymbol x -> x
        | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."

    /// ### TsNumKind
    type TsNumKind =
        | TsSmallInt of bits : int * signed : bool
        | TsBigInt of signed : bool
        | TsFloat32
        | TsFloat64
        | TsNotNumber

    /// ### tsNumKind
    let tsNumKind = function
        | Int8T -> TsSmallInt(8, true)
        | Int16T -> TsSmallInt(16, true)
        | Int32T -> TsSmallInt(32, true)
        | UInt8T | CharT -> TsSmallInt(8, false)
        | UInt16T -> TsSmallInt(16, false)
        | UInt32T -> TsSmallInt(32, false)
        | Int64T -> TsBigInt true
        | UInt64T -> TsBigInt false
        | Float32T -> TsFloat32
        | Float64T -> TsFloat64
        | BoolT | StringT -> TsNotNumber

    /// ### tsWrapSmall
    let tsWrapSmall bits signed (x : string) =
        match bits, signed with
        | 32, true -> $"({x}) | 0"
        | 32, false -> $"({x}) >>> 0"
        | 16, true -> $"({x}) << 16 >> 16"
        | 16, false -> $"({x}) & 0xffff"
        | 8, true -> $"({x}) << 24 >> 24"
        | _ -> $"({x}) & 0xff"

    /// ### tsWrapBig
    let tsWrapBig signed (x : string) = if signed then $"BigInt.asIntN(64, {x})" else $"BigInt.asUintN(64, {x})"

    /// ### BindsReturnTypeScript
    type BindsReturnTypeScript =
        | TsDeclare of TyV []
        | TsAssign of TyV []
        | TsReturn
        | TsReturnVoid

    /// ### codegenTypeScript
    /// ### typeScriptConstLocals
    let typeScriptConstLocals (generated : string) =
        if not (generated.Contains("let v", System.StringComparison.Ordinal)) then generated
        else
            let binding = System.Text.RegularExpressions.Regex(@"\blet (v[0-9]+)\b(?=[^;\n]*=)")
            let mutation = System.Text.RegularExpressions.Regex(@"(?<![\w.])(v[0-9]+)\s*(?:\.\w+|\[[^\]\n]*\])*\s*(?:=(?![=>])|\+=|-=|\*=|/=|%=|<<=|>>>=|>>=|&=|\|=|\^=|\*\*=|\+\+|--)|(?:\+\+|--)\s*(v[0-9]+)\b")
            let body = binding.Replace(generated, "let BOUND")
            let mutated = HashSet<string>(System.StringComparer.Ordinal)
            for found in mutation.Matches body do
                mutated.Add(if found.Groups.[1].Success then found.Groups.[1].Value else found.Groups.[2].Value) |> ignore
            binding.Replace(generated, fun (found : System.Text.RegularExpressions.Match) ->
                if mutated.Contains found.Groups.[1].Value then found.Value else "const " + found.Groups.[1].Value)

    let codegenTypeScript (env : PartEvalResult) (x : TypedBind []) =
        let method_names = Dictionary<int, string>()
        let closure_names = Dictionary<int, string>()
        let types = ResizeArray()
        let functions = ResizeArray()
        let exports = ResizeArray()
        let helpers = ResizeArray<string>()
        let helper_names = HashSet<string>()
        let closure_of_var = Dictionary<int, int>()
        let falls_through (s : CodegenEnv) =
            let text = s.text
            let mutable stop = text.Length
            while stop > 0 && System.Char.IsWhiteSpace text.[stop - 1] do stop <- stop - 1
            let mutable start = stop
            while start > 0 && text.[start - 1] <> '\n' do start <- start - 1
            let last = text.ToString(start, stop - start).Trim()
            not (last.StartsWith "return" || last.StartsWith "continue" || last.StartsWith "throw ")
        let export_names = HashSet<string>()

        let print is_type show r =
            let s = {text=StringBuilder(); indent=0}
            show s r
            let text = s.text.ToString()
            if is_type then types.Add(text) else functions.Add(text)

        let layout show =
            let dict' = codegenMemoTable HashIdentity.Structural
            let dict = codegenMemoTable HashIdentity.Reference
            let f x : LayoutRecFsharp =
                match x with
                | YLayout(x,_) ->
                let x = env.ty_to_data x
                let a, b =
                    match x with
                    | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                    | _ -> data_free_vars x, Map.empty
                {data=x; free_vars=a; free_vars_by_key=b; tag=dict'.Count}
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (3).\nGot: %s{show_ty x}"
            fun x ->
                let mutable dirty = false
                let r = memoize dict (memoize dict' (fun x -> dirty <- true; f x)) x
                if dirty then print true show r
                r

        let union show =
            let dict = codegenMemoTable HashIdentity.Reference
            let f (a : Map<int * string,Ty>) : UnionRecFsharp = {free_vars=a |> Map.map (fun _ -> env.ty_to_data >> data_free_vars); tag=dict.Count}
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print true show r
                r

        let jp f show =
            let dict = codegenMemoTable HashIdentity.Structural
            let f x = f (x, dict.Count)
            fun x ->
                let mutable dirty = false
                let r = memoize dict (fun x -> dirty <- true; f x) x
                if dirty then print false show r
                r

        let mutable self_loop : (int * TyV []) option = None

        let show_w = function WV (L(i,_)) -> $"v{i}" | WLit a -> litTypeScript a
        let args (x : TyV []) = x |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
        let args' x = x |> data_term_vars |> Array.map show_w |> String.concat ", "
        let names (l : TyV []) = l |> Array.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "
        let prim_of = function
            | DV(L(_,YPrim t)) -> Some t
            | DLit x -> Some (lit_to_primitive_type x)
            | _ -> None
        let kind_of d = match prim_of d with Some t -> tsNumKind t | None -> TsNotNumber
        let is_bool d = prim_of d = Some BoolT

        let global' =
            let has_added = HashSet env.globals
            fun x -> if preservesDuplicateGlobalFragment x || has_added.Add(x) then env.globals.Add x

        let helper (name : string) (text : string) = if helper_names.Add name then helpers.Add text
        let array_helpers () =
            helper "spiral_array_index" "function spiral_array_index<T>(array: T[], index: number): T {\n    if (!(index >= 0 && index < array.length)) throw new RangeError(\"array index \" + index + \" out of bounds for length \" + array.length);\n    return array[index];\n}"
            helper "spiral_array_set" "function spiral_array_set<T>(array: T[], index: number, value: T): void {\n    if (!(index >= 0 && index < array.length)) throw new RangeError(\"array index \" + index + \" out of bounds for length \" + array.length);\n    array[index] = value;\n}"
        let string_helpers () =
            helper "spiral_utf8" "const spiral_utf8_encoder = new TextEncoder();\nconst spiral_utf8_decoder = new TextDecoder(\"utf-8\");\nlet spiral_utf8_last = \"\";\nlet spiral_utf8_bytes: Uint8Array = new Uint8Array(0);\nfunction spiral_utf8(value: string): Uint8Array {\n    if (value !== spiral_utf8_last) {\n        spiral_utf8_bytes = spiral_utf8_encoder.encode(value);\n        spiral_utf8_last = value;\n    }\n    return spiral_utf8_bytes;\n}\nfunction spiral_string_length(value: string): number {\n    return spiral_utf8(value).length;\n}\nfunction spiral_string_index(value: string, index: number): number {\n    const bytes = spiral_utf8(value);\n    if (!(index >= 0 && index < bytes.length)) throw new RangeError(\"string index \" + index + \" out of bounds for length \" + bytes.length);\n    return bytes[index];\n}\nfunction spiral_slice_abort(message: string): never {\n    console.error(message);\n    process.exit(3);\n}\nfunction spiral_string_slice(value: string, from: number, to: number): string {\n    const bytes = spiral_utf8(value);\n    const length = bytes.length;\n    if (from < 0 || from > length || to < from - 1 || to >= length) spiral_slice_abort(\"string slice \" + from + \"..\" + to + \" out of bounds for length \" + length);\n    if (to < from) return \"\";\n    if ((bytes[from] & 0xc0) === 0x80 || (to + 1 < length && (bytes[to + 1] & 0xc0) === 0x80)) spiral_slice_abort(\"string slice \" + from + \"..\" + to + \" splits a code point\");\n    return spiral_utf8_decoder.decode(bytes.subarray(from, to + 1));\n}"
        let delay_helper () =
            helper "spiral_delay_ms" "function spiral_delay_ms(ms: number): void {\n    if (ms > 0) Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);\n}"

        let is_block_op = function
            | TyIf _ | TyIntSwitch _ | TyUnionUnbox _ | TyDo _ | TyIndent _ | TyWhile _ | TyFailwith _ -> true
            | _ -> false

        let rec tyv x =
            match x with
            | YUnion a ->
                let a = a.Item
                match a.layout with
                | UHeap -> sprintf "UH%i" (uheap a.cases).tag
                | UStack -> sprintf "US%i" (ustack a.cases).tag
            | YLayout(_,lay) as a ->
                match lay with
                | Heap -> sprintf "Heap%i" (heap a).tag
                | HeapMutable -> sprintf "Mut%i" (mut a).tag
                | StackMutable -> raise_codegen_error "The TypeScript backend doesn't support stack mutable layout types (a JS object would alias where Spiral copies)."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
            | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                match r |> Map.tryPick (fun (_, k) v -> if k = backend_nameTypeScript then Some v else None) with
                | Some x -> tup_ty x
                | None -> "any"
            | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_litTypeScript a) |> String.concat ""
            | YPrim a -> primTypeScript a
            | YArray a -> sprintf "Array<%s>" (tup_ty a)
            | YFun(a,b,_) -> sprintf "((%s) => %s)" (params_ty a) (tup_ty b)
            | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
            | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
            | a -> raise_codegen_error $"Type not supported in the codegen.\nGot: %A{a}"
        and tyvs (x : Ty) = env.ty_to_data x |> data_free_vars
        and params_ty x = tyvs x |> Array.mapi (fun k (L(_,t)) -> $"a{k}: {tyv t}") |> String.concat ", "
        and tyvs_ty (x : TyV []) =
            match x |> Array.map (fun (L(_,t)) -> tyv t) with
            | [||] -> "void"
            | [|x|] -> x
            | x -> String.concat ", " x |> sprintf "[%s]"
        and tup_ty x = tyvs_ty (tyvs x)
        and param_list (x : TyV []) = x |> Array.map (fun (L(i,t)) -> $"v{i}: {tyv t}") |> String.concat ", "
        and tup x =
            match data_term_vars x with
            | [||] -> "undefined"
            | [|x|] -> show_w x
            | x -> Array.map show_w x |> String.concat ", " |> sprintf "[%s]"
        and zero (t : Ty) =
            match t with
            | YPrim (Int64T | UInt64T) -> "0n"
            | YPrim BoolT -> "false"
            | YPrim StringT -> "\"\""
            | YPrim _ -> "0"
            | t -> $"undefined as unknown as {tyv t}"
        and declare (s : CodegenEnv) (vars : TyV []) =
            vars |> Array.iter (fun (L(i,t)) -> line s $"let v{i}: {tyv t};")
        and binds (s : CodegenEnv) (ret : BindsReturnTypeScript) (stmts : TypedBind []) =
            stmts |> Array.iter (function
                | TyLet(d,trace,a) ->
                    try let d = data_free_vars d
                        if is_block_op a then
                            declare s d
                            op s (TsAssign d) a
                        else
                            op s (TsDeclare d) a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnOp(trace,a,d) ->
                    try let ret =
                            match ret with
                            | TsReturn | TsReturnVoid -> if Array.isEmpty (data_term_vars d) then TsReturnVoid else TsReturn
                            | ret -> ret
                        op s ret a
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                | TyLocalReturnData(d,trace) ->
                    try match ret with
                        | TsAssign l -> Array.iter2 (fun (L(i,_)) b -> line s $"v{i} = {show_w b};") l (data_term_vars d)
                        | TsDeclare l -> Array.iter2 (fun (L(i,t)) b -> line s $"let v{i}: {tyv t} = {show_w b};") l (data_term_vars d)
                        | TsReturn | TsReturnVoid ->
                            match data_term_vars d with
                            | [||] -> if self_loop.IsSome then line s "return;"
                            | _ -> line s $"return {tup d};"
                    with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                )
        and op (s : CodegenEnv) (ret : BindsReturnTypeScript) (a : TypedOp) =
            let is_tail = match ret with TsReturn | TsReturnVoid -> true | _ -> false
            let return' (x : string) =
                match ret with
                | TsDeclare [||] | TsAssign [||] -> line s $"{x};"
                | TsDeclare [|L(i,t)|] -> line s $"let v{i}: {tyv t} = {x};"
                | TsAssign [|L(i,_)|] -> line s $"v{i} = {x};"
                | TsDeclare l -> line s $"let [{names l}]: {tyvs_ty l} = {x};"
                | TsAssign l -> line s $"[{names l}] = {x};"
                | TsReturn -> line s $"return {x};"
                | TsReturnVoid ->
                    line s $"{x};"
                    if self_loop.IsSome then line s "return;"
            let unit_done () = if is_tail && self_loop.IsSome then line s "return;"
            let block (s : CodegenEnv) ret (x : TypedBind []) = binds (indent s) ret x
            let jp (a, b) =
                match a with
                | JPMethod(a,c) -> $"{method_names.[(method (a,c)).tag]}({args b})"
                | JPClosure(a,c) -> $"{closure_names.[(closure (a,c)).tag]}({args b})"
            let layout_index (i : int) (fields : TyV []) =
                match ret with
                | TsDeclare l -> Array.iter2 (fun (L(t,ty)) (L(f,_)) -> line s $"let v{t}: {tyv ty} = v{i}.l{f};") l fields
                | TsAssign l -> Array.iter2 (fun (L(t,_)) (L(f,_)) -> line s $"v{t} = v{i}.l{f};") l fields
                | TsReturn | TsReturnVoid ->
                    match fields |> Array.map (fun (L(f,_)) -> $"v{i}.l{f}") with
                    | [||] -> unit_done ()
                    | [|x|] -> return' x
                    | x -> String.concat ", " x |> sprintf "[%s]" |> return'
            let number_index (d : Data) = match kind_of d with TsBigInt _ -> $"Number({tup d})" | _ -> tup d
            let length_as (target : Ty) (x : string) =
                match target with
                | YPrim (Int64T | UInt64T) -> $"BigInt({x})"
                | YPrim (Int8T | Int16T | Int32T | UInt8T | UInt16T | UInt32T) -> x
                | _ -> raise_codegen_error "Compiler error: Expected an int in length"
            let arith (op' : string) (a : Data) (b : Data) =
                let x = $"{tup a} {op'} {tup b}"
                match kind_of a with
                | TsSmallInt(32, true) when op' = "*" -> $"Math.imul({tup a}, {tup b})"
                | TsSmallInt(32, false) when op' = "*" -> $"Math.imul({tup a}, {tup b}) >>> 0"
                | TsSmallInt(bits, signed) when op' = "*" -> tsWrapSmall bits signed $"Math.imul({tup a}, {tup b})"
                | TsSmallInt(bits, signed) -> tsWrapSmall bits signed x
                | TsBigInt signed -> tsWrapBig signed x
                | TsFloat32 -> $"Math.fround({x})"
                | TsFloat64 | TsNotNumber -> x
            let pow (a : Data) (b : Data) =
                match kind_of a with
                | TsBigInt signed -> tsWrapBig signed $"{tup a} ** {tup b}"
                | TsFloat32 -> $"Math.fround(Math.pow({tup a}, {tup b}))"
                | TsSmallInt(bits, signed) -> tsWrapSmall bits signed $"Math.pow({tup a}, {tup b})"
                | TsFloat64 | TsNotNumber -> $"Math.pow({tup a}, {tup b})"
            let small_count (b : Data) = match kind_of b with TsBigInt _ -> $"Number({tup b} & 63n)" | _ -> tup b
            let big_count (b : Data) = match kind_of b with TsBigInt _ -> $"({tup b} & 63n)" | _ -> $"BigInt({tup b} & 63)"
            let shift_left (a : Data) (b : Data) =
                match kind_of a with
                | TsSmallInt(32, true) -> $"{tup a} << {small_count b}"
                | TsSmallInt(bits, signed) -> tsWrapSmall bits signed $"{tup a} << {small_count b}"
                | TsBigInt signed -> tsWrapBig signed $"{tup a} << {big_count b}"
                | _ -> raise_codegen_error "Compiler error: ShiftLeft expects an integer."
            let shift_right (a : Data) (b : Data) =
                match kind_of a with
                | TsSmallInt(_, true) -> $"{tup a} >> {small_count b}"
                | TsSmallInt(_, false) -> $"{tup a} >>> {small_count b}"
                | TsBigInt _ -> $"{tup a} >> {big_count b}"
                | _ -> raise_codegen_error "Compiler error: ShiftRight expects an integer."
            let bitwise (op' : string) (bool_op : string) (a : Data) (b : Data) =
                if is_bool a then $"{tup a} {bool_op} {tup b}" else
                match kind_of a with
                | TsSmallInt(32, false) -> $"({tup a} {op'} {tup b}) >>> 0"
                | _ -> $"{tup a} {op'} {tup b}"
            let complement (a : Data) =
                if is_bool a then $"!{tup a}" else
                match kind_of a with
                | TsSmallInt(32, false) -> $"~{tup a} >>> 0"
                | TsSmallInt(bits, false) -> tsWrapSmall bits false $"~{tup a}"
                | TsBigInt false -> tsWrapBig false $"~{tup a}"
                | _ -> $"~{tup a}"
            let neg (a : Data) =
                match kind_of a with
                | TsSmallInt(bits, signed) -> tsWrapSmall bits signed $"-{tup a}"
                | TsBigInt signed -> tsWrapBig signed $"-{tup a}"
                | _ -> $"-{tup a}"
            let float_fun (f : string) (a : Data) =
                match kind_of a with
                | TsFloat32 -> $"Math.fround(Math.{f}({tup a}))"
                | _ -> $"Math.{f}({tup a})"
            let conv (target : Ty) (b : Data) =
                let x = tup b
                let source = kind_of b
                match target with
                | YPrim BoolT ->
                    match source with
                    | TsBigInt _ -> $"{x} !== 0n"
                    | TsNotNumber -> x
                    | _ -> $"{x} !== 0"
                | YPrim t ->
                    let target_kind = tsNumKind t
                    if target_kind = source then x else
                    match target_kind, source with
                    | TsFloat64, TsBigInt _ -> $"Number({x})"
                    | TsFloat64, _ -> x
                    | TsFloat32, TsBigInt _ -> $"Math.fround(Number({x}))"
                    | TsFloat32, _ -> $"Math.fround({x})"
                    | TsSmallInt(bits, signed), TsBigInt _ ->
                        let as_n = if signed then "asIntN" else "asUintN"
                        $"Number(BigInt.{as_n}({bits}, {x}))"
                    | TsSmallInt(bits, signed), _ -> tsWrapSmall bits signed x
                    | TsBigInt signed, TsBigInt _ -> tsWrapBig signed x
                    | TsBigInt signed, (TsFloat32 | TsFloat64) -> tsWrapBig signed $"BigInt(Math.trunc({x}))"
                    | TsBigInt signed, _ -> tsWrapBig signed $"BigInt({x})"
                    | TsNotNumber, _ -> raise_codegen_error $"Compiler error: Unexpected type in Conv. Got: {show_ty target}"
                | _ -> raise_codegen_error $"Compiler error: Unexpected type in Conv. Got: {show_ty target}"
            match a with
            | TyMacro a ->
                a |> List.map (function
                    | CMText x -> x
                    | CMTerm (x,inl) -> if inl then args' x else tup x
                    | CMType x -> tup_ty x
                    | CMTypeLit x -> type_litTypeScript x)
                |> String.concat "" |> return'
            | TySizeOf _ -> raise_codegen_error "The TypeScript backend has no sizeof."
            | TyIf(cond,tr,fl) ->
                line s $"if ({tup cond}) {{"
                block s ret tr
                match fl with
                | [|TyLocalReturnData(DB,_)|] when not (is_tail && self_loop.IsSome) -> ()
                | _ -> line s "} else {"; block s ret fl
                line s "}"
            | TyJoinPoint(JPMethod(a,c),args) when is_tail && (match self_loop with Some (tag, _) -> (method (a,c)).tag = tag | None -> false) ->
                let parameters = snd self_loop.Value
                let steps = parallelMoves (Array.map2 (fun (L(target,_)) (L(source,_)) -> target, source) parameters args)
                let cyclic = steps |> List.exists (function SaveTemp _ -> true | _ -> false)
                let s' = if cyclic then (line s "{"; indent s) else s
                for step in steps do
                    match step with
                    | MoveVar (target, source) -> line s' $"v{target} = v{source};"
                    | SaveTemp (slot, source) -> line s' $"const t{slot} = v{source};"
                    | MoveTemp (target, slot) -> line s' $"v{target} = t{slot};"
                if cyclic then line s "}"
                line s "continue tail;"
            | TyJoinPoint(JPClosure(a,c) as a',args) ->
                match ret with
                | TsDeclare [|L(i,_)|] when args.Length = 0 -> closure_of_var.[i] <- (closure (a,c)).tag
                | _ -> ()
                return' (jp (a', args))
            | TyJoinPoint(a,args) -> return' (jp (a, args))
            | TyBackend(_,_,r) -> raise_codegen_error_backend r "The TypeScript backend does not support nesting other backends."
            | TyWhile((JPMethod _, _) as a,b) ->
                line s $"while ({jp a}) {{"
                block s (TsAssign [||]) b
                line s "}"
                unit_done ()
            | TyWhile _ -> raise_codegen_error "Expected a regular method rather than closure create in the while conditional."
            | TyDo a | TyIndent a ->
                line s "{"
                block s ret a
                line s "}"
            | TyIntSwitch(L(i,t),on_succ,on_fail) ->
                let suffix = match t with YPrim (Int64T | UInt64T) -> "n" | _ -> ""
                let s' = indent s
                line s $"switch (v{i}) {{"
                on_succ |> Array.iteri (fun k b ->
                    line s' $"case {k}{suffix}: {{"
                    block s' ret b
                    if falls_through s' then line (indent s') "break;"
                    line s' "}")
                line s' "default: {"
                block s' ret on_fail
                line s' "}"
                line s "}"
            | TyUnionUnbox(is,x,on_succs,on_fail) ->
                let x' = x.Item
                let union_rec, prefix =
                    match x'.layout with
                    | UHeap -> uheap x'.cases, "UH"
                    | UStack -> ustack x'.cases, "US"
                let name = $"{prefix}{union_rec.tag}"
                let case_tag k =
                    union_rec.free_vars
                    |> Seq.tryPick (function KeyValue ((tag, name), _) when name = UnionTagIdOps.text k -> Some tag | _ -> None)
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text k}.")
                let head =
                    match is with
                    | [L(i,_)] -> $"v{i}.tag"
                    | L(i,_) :: _ ->
                        let same = is |> List.pairwise |> List.map (fun (L(a,_), L(b,_)) -> $"v{a}.tag === v{b}.tag") |> String.concat " && "
                        $"{same} ? v{i}.tag : -1"
                    | [] -> raise_codegen_error "Compiler error: Union unbox without a scrutinee."
                let s' = indent s
                let s'' = indent s'
                line s $"switch ({head}) {{"
                on_succs |> Map.iter (fun k (a,b) ->
                    let c = case_tag k
                    line s' $"case {c}: {{"
                    List.iter2 (fun (L(v,_)) a ->
                        let source = if List.length is = 1 then $"v{v}" else $"(v{v} as {name}_{unionCaseSuffix union_rec c})"
                        data_free_vars a |> Array.iteri (fun f (L(i,t)) -> line s'' $"let v{i}: {tyv t} = {source}.f{f};")
                        ) is a
                    binds s'' ret b
                    if falls_through s'' then line s'' "break;"
                    line s' "}")
                match on_fail with
                | Some b ->
                    line s' "default: {"
                    binds s'' ret b
                    line s' "}"
                | None -> line s' "default: throw new Error(\"Compiler error: unreachable union case.\");"
                line s "}"
            | TyUnionBox(a,b,c) ->
                let c = c.Item
                let union_rec, prefix =
                    match c.layout with
                    | UHeap -> uheap c.cases, "UH"
                    | UStack -> ustack c.cases, "US"
                let i =
                    union_rec.free_vars
                    |> Seq.tryPick (function KeyValue ((tag, name), _) when name = UnionTagIdOps.text a -> Some tag | _ -> None)
                    |> Option.defaultWith (fun () -> raise_codegen_error $"Compiler error: Emitted union type has no case named {UnionTagIdOps.text a}.")
                return' $"{prefix}{union_rec.tag}_{unionCaseSuffix union_rec i}({args' b})"
            | TyToLayout(a,b) ->
                match b with
                | YLayout(_,Heap) -> heap b |> ignore
                | YLayout(_,HeapMutable) -> mut b |> ignore
                | YLayout(_,StackMutable) -> raise_codegen_error "The TypeScript backend doesn't support stack mutable layout types."
                | _ -> raise_codegen_error $"Compiler error: Expected a layout type (4).\nGot: %s{show_ty b}"
                match a |> data_term_vars |> Array.mapi (fun k x -> $"l{k}: {show_w x}") with
                | [||] -> return' "{}"
                | fields -> String.concat ", " fields |> sprintf "{ %s }" |> return'
            | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The TypeScript backend doesn't support indexing into stack mutable layout types."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                |> fun x -> layout_index i x.free_vars
            | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> raise_codegen_error "The TypeScript backend doesn't support indexing into stack mutable layout types."
                | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                |> fun x ->
                    x.free_vars_by_key
                    |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None)
                    |> Option.iter (layout_index i)
            | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
            | TyLayoutMutableSet(L(i,t),b,c) ->
                let a = List.fold (fun s k ->
                    match s with
                    | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                    | _ -> raise_codegen_error "Compiler error: Expected a record.") (mut t).data b
                Array.iter2 (fun (L(i',_)) b -> line s $"v{i}.l{i'} = {show_w b};") (data_free_vars a) (data_term_vars c)
                unit_done ()
            | TyArrayLiteral(_,b) -> b |> List.map tup |> String.concat ", " |> sprintf "[%s]" |> return'
            | TyArrayCreate(a,b) ->
                let length = number_index b
                match tyvs a with
                | [||] -> return' $"new Array<void>({length}).fill(undefined)"
                | [|L(_,t)|] -> return' $"new Array<{tyv t}>({length}).fill({zero t})"
                | elements ->
                    let zeros = elements |> Array.map (fun (L(_,t)) -> zero t) |> String.concat ", "
                    return' $"Array.from({{ length: {length} }}, (): {tyvs_ty elements} => [{zeros}])"
            | TyArrayLength(a,b) -> return' (length_as a $"{tup b}.length")
            | TyStringLength(a,b) -> string_helpers (); return' (length_as a $"spiral_string_length({tup b})")
            | TyFailwith(_,b) -> line s $"throw new Error({tup b});"
            | TyConv(a,b) -> return' (conv a b)
            | TyApply(L(i,_),b) -> return' $"v{i}({args' b})"
            | TyOp(Global, [DLit (LitString x)]) -> global' x; unit_done ()
            | TyOp(Export, [DLit (LitString name); DV(L(i,YFun(domain,range,_)))]) ->
                if not (export_names.Add name) then raise_codegen_error $"Duplicate export: {name}."
                let tag =
                    match closure_of_var.TryGetValue i with
                    | true, tag -> tag
                    | _ -> raise_codegen_error $"Compiler error: the exported function {name} is not a closure without captures."
                let parameters = tyvs domain
                exports.Add($"export function {name}({param_list parameters}): {tup_ty range} {{\n    return {closure_names.[tag]}()({args parameters});\n}}\n")
                unit_done ()
            | TyOp(ArrayIndexSet, [a;b;c]) -> array_helpers (); return' $"spiral_array_set({tup a}, {number_index b}, {tup c})"
            | TyOp(op,l) ->
                match op, l with
                | Dyn,[a] -> tup a
                | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                | StringIndex, [a;b] -> string_helpers (); $"spiral_string_index({tup a}, {number_index b})"
                | StringSlice, [a;b;c] -> string_helpers (); $"spiral_string_slice({tup a}, {number_index b}, {number_index c})"
                | StaticStringConcat, [a;b] -> $"{tup a} + {tup b}"
                | ArrayIndex, [a;b] -> array_helpers (); $"spiral_array_index({tup a}, {number_index b})"

                | Add, [a;b] -> arith "+" a b
                | Sub, [a;b] -> arith "-" a b
                | Mult, [a;b] -> arith "*" a b
                | Div, [a;b] -> arith "/" a b
                | Mod, [a;b] -> arith "%" a b
                | Pow, [a;b] -> pow a b
                | LT, [a;b] -> $"{tup a} < {tup b}"
                | LTE, [a;b] -> $"{tup a} <= {tup b}"
                | EQ, [a;b] -> $"{tup a} === {tup b}"
                | NEQ, [a;b] -> $"{tup a} !== {tup b}"
                | GT, [a;b] -> $"{tup a} > {tup b}"
                | GTE, [a;b] -> $"{tup a} >= {tup b}"
                | BoolAnd, [a;b] -> $"{tup a} && {tup b}"
                | BoolOr, [a;b] -> $"{tup a} || {tup b}"
                | BitwiseAnd, [a;b] -> bitwise "&" "&&" a b
                | BitwiseOr, [a;b] -> bitwise "|" "||" a b
                | BitwiseXor, [a;b] -> bitwise "^" "!==" a b
                | BitwiseComplement, [a] -> complement a
                | ShiftLeft, [a;b] -> shift_left a b
                | ShiftRight, [a;b] -> shift_right a b

                | Neg, [a] -> neg a
                | Log, [a] -> float_fun "log" a
                | Exp, [a] -> float_fun "exp" a
                | Tanh, [a] -> float_fun "tanh" a
                | Sqrt, [a] -> float_fun "sqrt" a
                | Sin, [a] -> float_fun "sin" a
                | Cos, [a] -> float_fun "cos" a
                | PrimToString, [a] ->
                    match a with
                    | DLit(LitChar _) | DV(L(_,YPrim CharT)) -> $"String.fromCodePoint({tup a})"
                    | _ -> $"String({tup a})"
                | NanIs, [a] -> $"Number.isNaN({tup a})"
                | StdoutFlush, [] -> "void 0"
                | MonotonicDelayMs, [a] -> delay_helper (); $"spiral_delay_ms({number_index a})"
                | Printf, [DLit (LitString fmt); b] ->
                    match printf_pieces fmt (data_term_vars b) with
                    | [] -> "void 0"
                    | [Choice2Of2 ('s', a)] -> $"process.stdout.write({show_w a})"
                    | pieces ->
                        pieces |> List.map (function
                            | Choice1Of2 t -> litTypeScript (LitString t)
                            | Choice2Of2 ('s', a) -> show_w a
                            | Choice2Of2 (_, a) -> $"String({show_w a})")
                        |> String.concat " + " |> sprintf "process.stdout.write(%s)"
                | UnionTag, [DV(L(i,YUnion _))] ->
                    match ret with
                    | TsDeclare [|L(_,YPrim (Int64T | UInt64T))|] | TsAssign [|L(_,YPrim (Int64T | UInt64T))|] -> $"BigInt(v{i}.tag)"
                    | _ -> $"v{i}.tag"
                | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported in the TypeScript backend" op l.Length
                |> return'
        and heap : _ -> LayoutRecFsharp = layout (fun s x ->
            let fields = x.free_vars |> Array.map (fun (L(i,t)) -> $"readonly l{i}: {tyv t}") |> String.concat ", "
            line s (if fields = "" then $"type Heap{x.tag} = {{}};" else $"type Heap{x.tag} = {{ {fields} }};")
            )
        and mut : _ -> LayoutRecFsharp = layout (fun s x ->
            let fields = x.free_vars |> Array.map (fun (L(i,t)) -> $"l{i}: {tyv t}") |> String.concat ", "
            line s (if fields = "" then $"type Mut{x.tag} = {{}};" else $"type Mut{x.tag} = {{ {fields} }};")
            )
        and union_type prefix (s : CodegenEnv) (x : UnionRecFsharp) =
            let name = $"{prefix}{x.tag}"
            let cases = x.free_vars |> Map.toArray
            cases |> Array.iter (fun ((i,k),a) ->
                let fields = a |> Array.mapi (fun f (L(_,t)) -> $", readonly f{f}: {tyv t}") |> String.concat ""
                line s $"type {name}_{unionCaseSuffix x i} = {{ readonly tag: {i}{fields} }};")
            match cases |> Array.map (fun ((i,_),_) -> $"{name}_{unionCaseSuffix x i}") with
            | [||] -> line s $"type {name} = never;"
            | x -> line s $"""type {name} = {String.concat " | " x};"""
            cases |> Array.iter (fun ((i,_),a) ->
                let parameters = a |> Array.mapi (fun f (L(_,t)) -> $"f{f}: {tyv t}") |> String.concat ", "
                let fields = a |> Array.mapi (fun f _ -> $", f{f}: f{f}") |> String.concat ""
                if a.Length = 0 then line s $"const {name}_{unionCaseSuffix x i}_shared: {name} = {{ tag: {i} }}; function {name}_{unionCaseSuffix x i}(): {name} {{ return {name}_{unionCaseSuffix x i}_shared; }}"
                else line s $"function {name}_{unionCaseSuffix x i}({parameters}): {name} {{ return {{ tag: {i}{fields} }}; }}")
        and uheap : _ -> UnionRecFsharp = union (union_type "UH")
        and ustack : _ -> UnionRecFsharp = union (union_type "US")
        and method : _ -> MethodRecFsharp =
            jp (fun ((jp_body,key),i) ->
                let args = codegenMethodKeyArgs key
                match codegenMethodBody env backend_nameTypeScript jp_body key with
                | a, range, name ->
                    method_names.[i] <- generatedMethodName name i
                    {tag=i; free_vars=rdata_free_vars args; range=range; body=a}
                ) (fun s x ->
                line s $"function {method_names.[x.tag]}({param_list x.free_vars}): {tup_ty x.range} {{"
                let saved = self_loop
                if self_tail x.tag x.body then
                    self_loop <- Some (x.tag, x.free_vars)
                    line (indent s) "tail: while (true) {"
                    binds (indent (indent s)) TsReturn x.body
                    line (indent s) "}"
                else
                    self_loop <- None
                    binds (indent s) TsReturn x.body
                self_loop <- saved
                line s "}"
                )
        and self_tail tag (body : TypedBind []) =
            body.Length > 0 &&
            match Array.last body with
            | TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _) -> (method (a,c)).tag = tag
            | TyLocalReturnOp(_, TyIf(_,tr,fl), _) -> self_tail tag tr || self_tail tag fl
            | TyLocalReturnOp(_, TyUnionUnbox(_,_,on_succs,on_fail), _) -> (on_succs |> Map.exists (fun _ (_,b) -> self_tail tag b)) || (on_fail |> Option.exists (self_tail tag))
            | TyLocalReturnOp(_, TyIntSwitch(_,on_succ,on_fail), _) -> Array.exists (self_tail tag) on_succ || self_tail tag on_fail
            | TyLocalReturnOp(_, (TyDo b | TyIndent b), _) -> self_tail tag b
            | _ -> false
        and closure : _ -> ClosureRecFsharp =
            jp (fun ((jp_body,key & (C(args,_,fun_ty))),i) ->
                match fun_ty with
                | YFun(domain,range,_) ->
                    match codegenClosureBody env backend_nameTypeScript jp_body key with
                    | domain_args, body, sourceName ->
                        closure_names.[i] <- generatedClosureName sourceName i
                        {tag=i; free_vars=rdata_free_vars args; domain_args=data_free_vars domain_args; range=range; body=body}
                | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."
                ) (fun s x ->
                let range = tup_ty x.range
                let domain = x.domain_args |> Array.mapi (fun k (L(_,t)) -> $"a{k}: {tyv t}") |> String.concat ", "
                line s $"function {closure_names.[x.tag]}({param_list x.free_vars}): (({domain}) => {range}) {{"
                line (indent s) $"return ({param_list x.domain_args}): {range} => {{"
                let saved = self_loop
                self_loop <- None
                binds (indent (indent s)) TsReturn x.body
                self_loop <- saved
                line (indent s) "};"
                line s "}"
                )

        let main_tys =
            match Array.tryLast x with
            | Some (TyLocalReturnData(d,_)) | Some (TyLocalReturnOp(_,_,d)) ->
                data_term_vars d |> Array.map (function WV(L(_,t)) -> t | WLit l -> YPrim (lit_to_primitive_type l))
            | _ -> [||]
        let main_range =
            match main_tys |> Array.map tyv with
            | [||] -> "void"
            | [|t|] -> t
            | ts -> String.concat ", " ts |> sprintf "[%s]"
        let main = StringBuilder()
        binds {text=main; indent=4} TsReturn x

        let program = StringBuilder()
        env.globals |> Seq.iter (fun (x : string) -> program.AppendLine(x) |> ignore)
        helpers |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
        types |> Seq.iter (fun x -> program.Append(x) |> ignore)
        functions |> Seq.iter (fun x -> program.Append(x) |> ignore)
        if exports.Count > 0 then
            exports |> Seq.iter (fun x -> program.Append(x) |> ignore)
            program.ToString()
        else
            program.AppendLine($"export function main(): {main_range} {{").Append(main).AppendLine("}") |> ignore
            match main_tys with
            | [|YPrim Int32T|] -> program.AppendLine("process.exitCode = main();") |> ignore
            | _ -> program.AppendLine("main();") |> ignore
            program.ToString() |> typeScriptConstLocals


    /// ## RefCounting
    // Here are the reference counting analysis passes.
    open System.Collections.Generic

    /// ### varc_add
    let varc_add x i v =
        let c = Option.defaultValue 0 (Map.tryFind x v) + i
        if c = 0 then Map.remove x v else Map.add x c v

    /// ### varc_union
    let varc_union a b = Map.foldBack varc_add a b

    /// ### varc_data
    let varc_data call_data =
        let mutable v = Map.empty
        let rec f = function
            | DPair(a,b) -> f a; f b
            | DForall(_,a,_,_,_) | DFunction(_,_,a,_,_,_) -> Array.iter f a
            | DRecord l -> Map.iter (fun _ -> f) l
            | DV x -> v <- varc_add x 1 v
            | DExists(_,a) | DUnion(a,_) | DNominal(a,_) -> f a
            | DLit _ | DTLit _ | DSymbol _ | DB -> ()
            | DHashSet x -> Seq.iter f x
            | DHashMap(x,_) -> x |> Seq.iter (fun kv -> f kv.Value)
        f call_data
        v

    /// ### varc_set
    let varc_set x i = Set.fold (fun s v -> Map.add v i s) Map.empty x

    /// ### refc_used_vars
    let refc_used_vars (x : TypedBind []) =
        let g_bind : Dictionary<TypedBind, TyV Set> = Dictionary(HashIdentity.Reference)
        let fv x = x |> data_free_vars |> Set
        let jp (x : JoinPointCall) = snd x |> Set
        let rec binds x =
            Array.foldBack (fun k vs ->
                match k with
                | TyLet(d,_,o) -> vs + op o - fv d
                | TyLocalReturnOp(_,o,_) -> vs + op o
                | TyLocalReturnData(d,_) -> vs + fv d
                |> fun vs -> g_bind.Add(k,vs); vs
                ) x Set.empty
        and op (x : TypedOp) : TyV Set =
            match x with
            | TySizeOf _ -> Set.empty
            | TyMacro l -> List.fold (fun s -> function CMTerm (d,_) -> s + fv d | _ -> s) Set.empty l
            | TyArrayLiteral(_,l) | TyOp(_,l) -> List.fold (fun s x -> s + fv x) Set.empty l
            | TyToLayout(x,_) | TyUnionBox(_,x,_) | TyFailwith(_,x) | TyConv(_,x) | TyArrayCreate(_,x) | TyArrayLength(_,x) | TyStringLength(_,x) -> fv x
            | TyWhile(cond,body) -> jp cond + binds body
            | TyDo body | TyIndent body -> binds body
            | TyLayoutIndexAll(i) | TyLayoutIndexByKey(i,_) -> Set.singleton i
            | TyApply(i,d) | TyLayoutMutableSet(i,_,d) -> Set.singleton i + fv d
            | TyJoinPoint x -> jp x
            | TyBackend(_,_,_) -> Set.empty
            | TyIf(cond,tr',fl') -> fv cond + binds tr' + binds fl'
            | TyUnionUnbox(vs,_,on_succs',on_fail') ->
                let vs = vs |> Set
                let on_fail =
                    match on_fail' with
                    | Some x -> binds x
                    | None -> Set.empty
                Map.fold (fun s k (lets,body) ->
                    let lets = List.fold (fun s x -> s + fv x) Set.empty lets
                    s + (binds body - lets)
                    ) (vs + on_fail) on_succs'
            | TyIntSwitch(tag,on_succs',on_fail') ->
                let vs = Set.singleton tag
                let on_fail = binds on_fail'
                Array.fold (fun s body -> s + binds body) (vs + on_fail) on_succs'
        binds x |> ignore
        g_bind

    /// ### RefcVars
    type RefcVars = {g_incr : Dictionary<TypedBind,TyV Set>; g_decr : RefcDecrTable; g_op : Dictionary<TypedBind,Map<TyV, int>>; g_op_decr : Dictionary<TypedBind,TyV Set>}

    /// ### refc_prepass
    let refc_prepass' (borrowed : JoinPointKey -> int -> bool) (new_vars : TyV Set) (increfed_vars : TyV Set) (x : TypedBind []) =
        let used_vars = refc_used_vars x
        let g_incr : Dictionary<TypedBind, TyV Set> = Dictionary(HashIdentity.Reference)
        let g_decr : RefcDecrTable = refcDecrTable ()
        let g_op : Dictionary<TypedBind, _> = Dictionary(HashIdentity.Reference)
        let g_op_decr : Dictionary<TypedBind, TyV Set> = Dictionary(HashIdentity.Reference)

        let add (d : Dictionary<TypedBind, TyV Set>) k x = if Set.isEmpty x then () else d.Add(k,x)
        let add_cd (d : RefcDecrTable) k x = if Set.isEmpty x then () else refcDecrAdd d k x
        let add' (d : Dictionary<TypedBind, Map<TyV,int>>) k x = if Map.isEmpty x then () else d.Add(k,x)
        let fv x = x |> data_free_vars |> Set
        let rec binds (new_vars : TyV Set) (increfed_vars : TyV Set) (k : TypedBind []) =
            Array.fold (fun (new_vars, increfed_vars) k ->
                add g_incr k new_vars
                let increfed_vars = new_vars + increfed_vars

                let used_vars = used_vars.[k]
                let decref_vars = increfed_vars - used_vars
                add_cd g_decr k decref_vars
                let r = increfed_vars - decref_vars
                match k with
                | TyLet(d,_,o) ->
                    op k Set.empty o
                    let new_vars = fv d
                    match o with
                    | TyLayoutIndexAll _ | TyLayoutIndexByKey _ | TyOp(ArrayIndex,_) -> new_vars, r
                    | _ -> Set.empty, r + new_vars
                | TyLocalReturnOp(_,o,_) ->
                    op k r o
                    Set.empty, r
                | TyLocalReturnData(d,_) ->
                    add' g_op k (varc_data d)
                    add g_op_decr k r
                    Set.empty, r
                ) (new_vars, increfed_vars) k
            |> ignore
        and op k increfed_vars (x : TypedOp) : unit =
            let fun_call q = add' g_op k q; add g_op_decr k increfed_vars
            match x with
            | TyApply(a,b) -> varc_add a 1 (varc_data b) |> fun_call
            | TyJoinPoint(key,x) ->
                x |> Array.indexed |> Array.fold (fun s (i, x) -> if borrowed key i then s else varc_add x 1 s) Map.empty |> fun_call
            | TyArrayLiteral(_,x) -> List.fold (fun s x -> varc_union s (varc_data x)) Map.empty x |> fun_call
            | TyUnionBox(_,x,_) | TyToLayout(x,_) -> varc_data x |> fun_call
            | TySizeOf _ | TyLayoutIndexAll _ | TyLayoutIndexByKey _ | TyMacro _ | TyOp _ | TyFailwith _ | TyConv _
            | TyArrayCreate _ | TyArrayLength _ | TyStringLength _ | TyLayoutMutableSet _ | TyBackend _ -> ()
            | TyWhile(_,body) -> binds Set.empty Set.empty body
            | TyDo body | TyIndent body -> binds Set.empty Set.empty body
            | TyIf(_,tr',fl') -> binds Set.empty increfed_vars tr'; binds Set.empty increfed_vars fl'
            | TyUnionUnbox(_,_,on_succs',on_fail') ->
                Map.iter (fun _ (lets,body) ->
                    binds (List.fold (fun s x -> s + fv x) Set.empty lets) increfed_vars body
                    ) on_succs'
                Option.iter (binds Set.empty increfed_vars) on_fail'
            | TyIntSwitch(_,on_succs',on_fail') ->
                Array.iter (binds Set.empty increfed_vars) on_succs'
                binds Set.empty increfed_vars on_fail'
        binds new_vars increfed_vars x

        {g_incr=g_incr; g_op=g_op; g_decr=g_decr; g_op_decr=g_op_decr}

    let refc_prepass (new_vars : TyV Set) (increfed_vars : TyV Set) (x : TypedBind []) = refc_prepass' (fun _ _ -> false) new_vars increfed_vars x

    /// ## CodegenC
    module CodegenC =
        // open System
        // open System.Text
        open System.Collections.Generic

        let sizeof_tyvC = function
            | YPrim (Int64T | UInt64T | Float64T) -> 8
            | YPrim (Int32T | UInt32T | Float32T) -> 4
            | YPrim (Int16T | UInt16T) -> 2
            | YPrim (Int8T | UInt8T | CharT | BoolT) -> 1
            | _ -> 8
        let order_argsC v = v |> Array.sortWith (fun (L(_,t)) (L(_,t')) -> compare (sizeof_tyvC t') (sizeof_tyvC t))
        let lineC x s = if s <> "" then x.text.Append(' ', x.indent).AppendLine s |> ignore
        let line' x s = lineC x (String.concat " " s)

        let rec is_heap f x =
            Array.exists (fun (L(i,t)) ->
                match t with
                | YUnion a when a.Item.layout = UStack -> a.Item.tag_cases |> Array.exists (fun case -> not (isNull (box case)) && (case |> snd |> f |> is_heap f))
                | YPrim StringT -> true
                | YPrim _ -> false
                | _ -> true
                ) x
        let is_stringC = function DV(L(_,YPrim StringT)) | DLit(LitString _) -> true | _ -> false

        type BindsReturnC =
            | BindsTailEnd
            | BindsLocal of TyV []

        let term_vars_to_tysC x = x |> Array.map (function WV(L(_,t)) -> t | WLit x -> YPrim (lit_to_primitive_type x))
        let binds_last_dataC x = x |> Array.last |> function TyLocalReturnData(x,_) | TyLocalReturnOp(_,_,x) -> x | TyLet _ -> raise_codegen_error "Compiler error: Cannot find the return data of the last bind."

        type UnionRecC = {tag : int; free_vars : Map<int * string, TyV[]>}
        type LayoutRecC = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>}
        type MethodRecC = {tag : int; free_vars : L<Tag,Ty>[]; range : Ty; body : TypedBind[]; name : string option}
        type ClosureRecC = {tag : int; free_vars : L<Tag,Ty>[]; domain : Ty; domain_args : TyV[]; range : Ty; body : TypedBind[]; name : string option}
        type TupleRecC = {tag : int; tys : Ty []}
        type ArrayRecC = {tag : int; ty : Ty; tyvs : TyV[]}
        type CFunRecC = {tag : int; domain_args_ty : Ty[]; range : Ty}

        let size_t = UInt32T

        let lit_stringC x =
            let strb = StringBuilder(String.length x + 2)
            strb.Append '"' |> ignore
            String.iter (function
                | '"' -> strb.Append "\\\""
                | '\b' -> strb.Append @"\b"
                | '\t' -> strb.Append @"\t"
                | '\n' -> strb.Append @"\n"
                | '\r' -> strb.Append @"\r"
                | '\\' -> strb.Append @"\\"
                | x -> strb.Append x
                >> ignore
                ) x
            strb.Append '"' |> ignore
            strb.ToString()

        let cStaticFunctions (generated : string) =
            let topFunction =
                System.Text.RegularExpressions.Regex(
                    @"^(?!static\b|typedef\b|struct\b|union\b|enum\b|extern\b|return\b|else\b|if\b|while\b|for\b|switch\b|case\b|default\b)[A-Za-z_][\w \*]*?[\s\*](?<name>[A-Za-z_]\w*)\([^;{}]*\)\s*(?<end>\{|;)(?=\r?$)",
                    System.Text.RegularExpressions.RegexOptions.Multiline)
            let defined =
                topFunction.Matches generated
                |> Seq.filter (fun found -> found.Groups.["end"].Value = "{")
                |> Seq.map (fun found -> found.Groups.["name"].Value)
                |> Set.ofSeq
            let withStatic (found : System.Text.RegularExpressions.Match) =
                let name = found.Groups.["name"].Value
                if name <> "main" && defined.Contains name then "static " + found.Value else found.Value
            topFunction.Replace(generated, System.Text.RegularExpressions.MatchEvaluator withStatic)


        let cInlineSingleSiteLoops (loops : HashSet<string>) (rest : string) (generated : string) =
            let attributed = System.Text.RegularExpressions.Regex(@"(?m)^__attribute__\(\(noinline\)\) (?<sig>[^\n{]*?\b(?<name>[A-Za-z_]\w*)\([^;{}\n]*\)\s*)\{")
            attributed.Replace(generated, System.Text.RegularExpressions.MatchEvaluator(fun m ->
                let raw = m.Groups.["name"].Value
                let name = System.Text.RegularExpressions.Regex.Escape raw
                let mentions = System.Text.RegularExpressions.Regex.Matches(generated + "\n" + rest, @"\b" + name + @"\(").Count
                let prototype = System.Text.RegularExpressions.Regex.IsMatch(generated + "\n" + rest, @"(?m)^[A-Za-z_][\w \*]*[\s\*]" + name + @"\([^;{}\n]*\);\s*$")
                if loops.Contains raw && mentions = 2 && not prototype then "static inline " + m.Groups.["sig"].Value + "{" else m.Value))

        let fuseCDeclarations (generated : string) =
            let declaration = System.Text.RegularExpressions.Regex(@"^(?<indent>[ \t]+)(?<type>[A-Za-z_][\w \*]*?[\w\*])\s+(?<name>v[0-9]+);$")
            let storage = System.Text.RegularExpressions.Regex(@"\b(static|extern|typedef|return|goto|register)\b")
            let lines = generated.Replace("\r\n", "\n").Split('\n')
            let fused = StringBuilder(generated.Length)
            let mutable index = 0
            while index < lines.Length do
                let line = lines.[index]
                let found = declaration.Match line
                let joined =
                    if found.Success && index + 1 < lines.Length && not (storage.IsMatch found.Groups.["type"].Value) then
                        let name = found.Groups.["name"].Value
                        let prefix = found.Groups.["indent"].Value + name + " = "
                        let following = lines.[index + 1]
                        if following.StartsWith(prefix, System.StringComparison.Ordinal) && following.EndsWith(";", System.StringComparison.Ordinal) then
                            let rest = following.Substring prefix.Length
                            if System.Text.RegularExpressions.Regex.IsMatch(rest, @"\b" + name + @"\b") then None
                            else Some (found.Groups.["indent"].Value + found.Groups.["type"].Value + " " + name + " = " + rest)
                        else None
                    else None
                match joined with
                | Some text ->
                    fused.Append(text) |> ignore
                    index <- index + 2
                | None ->
                    fused.Append(line) |> ignore
                    index <- index + 1
                if index < lines.Length then fused.Append('\n') |> ignore
            fused.ToString()
        let codegenC (env : PartEvalResult) (x : TypedBind []) =
            let globals = ResizeArray()
            let fwd_dcls = ResizeArray()
            let types = ResizeArray()
            let functions = ResizeArray()
            // A `Fun` struct prints its range and domain types first (nested), and one of those can name the same
            // `Fun` in a field before the struct's typedef exists: `union rec s = Cons : u64 * (() -> s)` prints UH0
            // (field `Fun0 *`) while printing Fun0's range. Such a use emits the typedef as a forward declaration.
            let funs_printing = Collections.Generic.HashSet<int>()
            let funs_fwd = Collections.Generic.HashSet<int>()
            // Likewise for functions: a method or closure prints its body after its own signature, and the functions
            // the body calls print first (nested), so one of those calling back into it (a closure whose body calls the
            // method creating it, mutually recursive methods) ran ahead of its definition (`implicit declaration of
            // function 'build0'`). A call to a function whose definition is still printing emits a prototype at the
            // current end of the functions; the types the prototype names are complete by then.
            let fns_printing = Collections.Generic.List<string>()
            let fns_fwd = Collections.Generic.HashSet<string>()
            let borrowed_loops = HashSet<string>()
            let fn_fwd (name : string) (self_ok : bool) (proto : unit -> string) =
                let n = fns_printing.Count
                if n > 0 && fns_printing.Contains name && (not self_ok || fns_printing.[n-1] <> name) && fns_fwd.Add name then
                    functions.Add(StringBuilder().AppendLine(proto () + ";").ToString())

            let malloc, free = "malloc", "free"
            let threaded = env.globals.Contains "#define SPIRAL_THREADS 1"
            let refc_add (counter : string) (count : int) =
                if threaded then $"__atomic_fetch_add(&{counter}, {count}, __ATOMIC_RELAXED);"
                elif count = 1 then $"{counter}++;"
                else $"{counter} += {count};"
            let refc_drop (counter : string) =
                if threaded then $"__atomic_sub_fetch(&{counter}, 1, __ATOMIC_ACQ_REL) == 0" else $"--({counter}) == 0"

            let print_decref s_fun name_fun type_arg name_decref =
                line s_fun (sprintf "void %s(%s * x){" name_fun type_arg)
                let _ =
                    let s_fun = indent s_fun
                    line s_fun (sprintf "if (x != NULL && %s) { %s(x); %s(x); }" (refc_drop "x->refc") name_decref free)
                line s_fun "}"

            let print show r =
                let s_typ_fwd = {text=StringBuilder(); indent=0}
                let s_typ = {text=StringBuilder(); indent=0}
                let s_fun = {text=StringBuilder(); indent=0}
                show s_typ_fwd s_typ s_fun r
                let f (a : _ ResizeArray) (b : CodegenEnv) =
                    let text = b.text.ToString()
                    if text <> "" then a.Add(text)
                f fwd_dcls s_typ_fwd
                f types s_typ
                f functions s_fun

            let layout show =
                let dict' = codegenMemoTable HashIdentity.Structural
                let dict = codegenMemoTable HashIdentity.Reference
                let f x : LayoutRecC =
                    match x with
                    | YLayout(x,_) ->
                        let x = env.ty_to_data x
                        let a, b =
                            match x with
                            | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                            | _ -> data_free_vars x, Map.empty
                        {data=x; free_vars=a; free_vars_by_key=b; tag=dict'.Count}
                    | _ -> raise_codegen_error $"Compiler error: Expected a layout type (7).\nGot: %s{show_ty x}"
                fun x ->
                    let mutable dirty = false
                    let r = memoize dict (memoize dict' (fun x -> dirty <- true; f x)) x
                    if dirty then print show r
                    r

            let union show =
                let dict = codegenMemoTable HashIdentity.Reference
                let f (a : Union) : UnionRecC =
                    let free_vars = a.Item.cases |> Map.map (fun _ -> env.ty_to_data >> data_free_vars)
                    {free_vars=free_vars; tag=dict.Count}
                fun x ->
                    let mutable dirty = false
                    let r = memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r

            let jp f show =
                let dict = codegenMemoTable HashIdentity.Structural
                let f x = f (x, dict.Count)
                fun x ->
                    let mutable dirty = false
                    let r = memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r

            let tuple show =
                let dict = codegenMemoTable HashIdentity.Structural
                let f x = {tag=dict.Count; tys=x}
                fun x ->
                    let mutable dirty = false
                    let r = memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r

            let carray' show =
                let dict = codegenMemoTable HashIdentity.Structural
                let f x = {tag=dict.Count; ty=x; tyvs = env.ty_to_data x |> data_free_vars}
                fun x ->
                    let mutable dirty = false
                    let r = memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r

            let cstring' show =
                let mutable dirty = true
                fun () ->
                    if dirty then print show ()
                    dirty <- false

            let cstring_slice' show =
                let mutable dirty = true
                fun () ->
                    if dirty then print show ()
                    dirty <- false

            let cstring_concat' show =
                let mutable dirty = true
                fun () ->
                    if dirty then print show ()
                    dirty <- false

            let cstring_from_i64' show =
                let mutable dirty = true
                fun () ->
                    if dirty then print show ()
                    dirty <- false

            let cstring_from_u64' show =
                let mutable dirty = true
                fun () ->
                    if dirty then print show ()
                    dirty <- false

            let cstring_from_bool' show =
                let mutable dirty = true
                fun () ->
                    if dirty then print show ()
                    dirty <- false

            let cstring_from_char' show =
                let mutable dirty = true
                fun () ->
                    if dirty then print show ()
                    dirty <- false

            let cfun' show =
                let dict = codegenMemoTable HashIdentity.Structural
                let f (a : Ty, b : Ty) = {tag=dict.Count; domain_args_ty=a |> env.ty_to_data |> data_free_vars |> Array.map (fun (L(_,t)) -> t); range=b}
                fun x ->
                    let mutable dirty = false
                    let r = memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print show r
                    r

            let args x = x |> Array.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "

            let tmp =
                let mutable i = 0u
                fun () -> let x = i in i <- i + 1u; x

            let global' =
                let has_added = HashSet env.globals
                fun x -> if preservesDuplicateGlobalFragment x || has_added.Add(x) then globals.Add x

            let import x = global' $"#include <{x}>"
            let import' x = global' $"#include \"{x}\""

            let tyvs_to_tys (x : TyV []) = Array.map (fun (L(i,t)) -> t) x

            let self_loop : (int * TyV [] * int) option ref = ref None
            let self_continue_release : (CodegenEnv -> unit) ref = ref ignore
            let self_let_tail_target : (TyV [] * (CodegenEnv -> unit)) option ref = ref None
            let method_key_of_tag = Dictionary<int, obj>()
            let borrowed_param = paramEscape paramEscapeTracked env x
            let rec binds_start (args : TyV []) (s : CodegenEnv) (x : TypedBind []) = binds (refc_prepass' borrowed_param Set.empty (Set args) x) s BindsTailEnd x
            and self_continue (s : CodegenEnv) (parameters : TyV []) (args : TyV []) =
                if parameters.Length > 0 then
                    line s "{"
                    let temps = Array.map2 (fun (L(_,t)) (L(j,_)) -> let k = tmp() in line (indent s) $"{tyv t} tmp{k} = v{j};"; k) parameters args
                    self_continue_release.Value (indent s)
                    Array.iteri (fun position k -> line (indent s) $"v{position} = tmp{k};") temps
                    line s "}"
                else
                    self_continue_release.Value s
                line s "continue;"
            and return_local s ret (x : string) =
                match ret with
                | [||] -> line s $"{x};"
                | [|L(i,_)|] -> line s $"v{i} = {x};"
                | ret ->
                    let tmp_i = tmp()
                    line s $"{tup_ty_tyvs ret} tmp{tmp_i} = {x};"
                    Array.mapi (fun i (L(i',_)) -> $"v{i'} = tmp{tmp_i}.v{i};") ret |> line' s
            and binds (vars : RefcVars) (s : CodegenEnv) (ret : BindsReturnC) (stmts : TypedBind []) =
                let tup_destruct (a,b) =
                    Array.map2 (fun (L(i,_)) b ->
                        match b with
                        | WLit b -> $"v{i} = {lit b};"
                        | WV (L(i',_)) -> $"v{i} = v{i'};"
                        ) a b
                let heap_free (vars : TyV seq) = not (is_heap (env.ty_to_data >> data_free_vars) (Seq.toArray vars))
                let outer_tail_release =
                    match ret, self_let_tail_target.Value with
                    | BindsTailEnd, _ -> Some ignore
                    | BindsLocal l, Some (target, release) when l = target -> Some release
                    | _ -> None
                let self_let_tail =
                    match outer_tail_release, self_loop.Value with
                    | Some _, Some (tag, parameters, depth) when depth = fns_printing.Count && stmts.Length >= 2 ->
                        match stmts.[stmts.Length - 2], stmts.[stmts.Length - 1] with
                        | (TyLet(d,_,a) as call), (TyLocalReturnData(r,_) as last) when returns_unchanged d r && op_self_tail tag a ->
                            let touched =
                                Seq.concat [
                                    Seq.ofList (Set.toList (get_default vars.g_incr last (fun () -> Set.empty)))
                                    Seq.ofList (Set.toList (get_default vars.g_decr last (fun () -> Set.empty)))
                                    Seq.ofList (Set.toList (get_default vars.g_op_decr last (fun () -> Set.empty)))
                                    Seq.ofList (Map.toList (get_default vars.g_op last (fun () -> Map.empty)) |> List.map fst)
                                    ]
                            let direct_self_call = match a with TyJoinPoint(JPMethod(x,c),_) -> is_method_tag tag (x, c) | _ -> false
                            let at_function_tail = match ret with BindsTailEnd -> true | _ -> false
                            if direct_self_call || (at_function_tail && heap_free touched) then Some (call, last, parameters, a) else None
                        | _ -> None
                    | _ -> None
                let kept_let_tail =
                    match outer_tail_release, self_loop.Value, self_let_tail with
                    | Some outer, Some (tag, _, depth), None when depth = fns_printing.Count && stmts.Length >= 2 ->
                        match stmts.[stmts.Length - 2], stmts.[stmts.Length - 1] with
                        | (TyLet(d,_,a) as call), (TyLocalReturnData(r,_) as last) when returns_unchanged d r && op_self_tail tag a && (data_free_vars d).Length > 0 -> Some (call, last, outer)
                        | _ -> None
                    | _ -> None
                let stmts =
                    match self_let_tail with
                    | Some (_, last, _, _) -> stmts |> Array.filter (fun x -> not (obj.ReferenceEquals(x, last)))
                    | None -> stmts
                let refc_prefix (s : CodegenEnv) x =
                    let incr0 = get_default vars.g_incr x (fun () -> Set.empty)
                    let decr0 = get_default vars.g_decr x (fun () -> Set.empty)
                    let op0 = get_default vars.g_op x (fun () -> Map.empty)
                    let op_decr0 = get_default vars.g_op_decr x (fun () -> Set.empty)
                    let incr, decr, op, op_decr = varc_set incr0 1, varc_set decr0 -1, op0, varc_set op_decr0 -1
                    let incr, decr = varc_union incr decr |> varc_union op |> varc_union op_decr |> Map.partition (fun _ v -> 0 < v)
                    refc_varc incr |> line' s; refc_varc decr |> line' s
                Array.iter (fun x ->
                    refc_prefix s x
                    match x with
                    | TyLet _ when (match self_let_tail with Some (call, _, _, _) -> obj.ReferenceEquals(x, call) | None -> false) ->
                        let _, last, _, a = self_let_tail.Value
                        let direct_self_call = match a with TyJoinPoint _ -> true | _ -> false
                        let outer = Option.defaultValue ignore outer_tail_release
                        let saved_release = self_continue_release.Value
                        self_continue_release.Value <- if direct_self_call then (fun s -> refc_prefix s last; outer s) else ignore
                        op vars s BindsTailEnd a
                        self_continue_release.Value <- saved_release
                    | TyLet(d,trace,a) ->
                        try let d = data_free_vars d
                            let decl_vars = Array.map (fun (L(i,t)) -> $"{tyv t} v{i};") d
                            match a with
                            | TyMacro a ->
                                let m = a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup_data x) | CMType x -> tup_ty x | CMTypeLit x -> type_lit x) |> String.concat ""
                                let q = m.Split("\\v")
                                if q.Length = 1 then
                                    decl_vars |> line' s
                                    return_local s d m
                                else
                                    if d.Length = q.Length-1 then
                                        let w = StringBuilder(m.Length+8)
                                        let tag (L(i,_)) = i : int
                                        Array.iteri (fun i v -> w.Append(q.[i]).Append('v').Append(tag v) |> ignore) d
                                        w.Append(q.[d.Length]).Append(';').ToString() |> line s
                                    else
                                        raise_codegen_error "The special \\v macro requires the same number of free vars in its binding as there are \\v in the code."
                            | _ ->
                                decl_vars |> line' s
                                match kept_let_tail with
                                | Some (call, last, outer) when obj.ReferenceEquals(x, call) ->
                                    let saved_target = self_let_tail_target.Value
                                    self_let_tail_target.Value <- Some (d, fun s -> refc_prefix s last; outer s)
                                    op vars s (BindsLocal d) a
                                    self_let_tail_target.Value <- saved_target
                                | _ -> op vars s (BindsLocal d) a
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    | TyLocalReturnOp(trace,a,_) ->
                        try op vars s ret a
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    | TyLocalReturnData(d,trace) ->
                        try match ret with
                            | BindsLocal l -> line' s (tup_destruct (l,data_term_vars d))
                            | BindsTailEnd -> line s $"return {tup_data d};"
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    ) stmts
            and refc_change'' (f : int * Ty -> string) count (L(i,t')) =
                let v = i,t'
                let inline g decref =
                    if count = -1 then Some (decref())
                    elif 0 < count then Some (refc_add $"({f v})->refc" count)
                    else raise_codegen_error $"Compiler error: Invalid count in refc_change''. Got: {count}"
                match t' with
                | YUnion t ->
                    match t.Item.layout with
                    | UStack when ((ustack t : UnionRecC).free_vars : Map<int * string, TyV[]>) |> Map.forall (fun _ (fields : TyV[]) -> fields |> Array.forall (fun field -> Option.isNone (refc_change'' f 1 field))) -> None
                    | UStack ->
                        if count = -1 then Some $"USDecref{(ustack t).tag}(&({f v}));"
                        elif 0 < count then Some (String.replicate count $"USIncref{(ustack t).tag}(&({f v}));")
                        else raise_codegen_error $"Compiler error: Invalid count in refc_change''. UStack case. Got: {count}"
                    | UHeap -> g (fun () -> $"UHDecref{(uheap t).tag}({f v});")
                | YArray t -> g (fun () -> $"ArrayDecref{(carray t).tag}({f v});")
                | YFun(a,b,FT_Vanilla) -> g (fun () ->  $"({f v})->decref_fptr({f v});")
                | YPrim StringT -> g (fun () ->  $"StringDecref({f v});" )
                | YLayout(_,Heap) as a -> g (fun () ->  $"HeapDecref{(heap a).tag}({f v});")
                | YLayout(_,HeapMutable) as a -> g (fun () ->  $"MutDecref{(mut a).tag}({f v});")
                | _ -> None
            and refc_change' (f : int * Ty -> string) count (x : TyV []) : string [] = Array.choose (refc_change'' f count) x
            and refc_change f c x = refc_change' (fun (i,t) -> f i) c x
            and refc_varc x =
                let ar = ResizeArray(Map.count x)
                Map.iter (fun k v -> refc_change'' (fun (i,_) -> $"v{i}") v k |> Option.iter ar.Add) x
                ar
            //and refc_incr x : string [] = refc_change (fun i -> $"v{i}") 1 x
            //and refc_decr x : string [] = refc_change (fun i -> $"v{i}") -1 x
            and show_w = function WV(L(i,_)) -> sprintf "v%i" i | WLit a -> lit a
            and args' b = data_term_vars b |> Array.map show_w |> String.concat ", "
            and tup_term_vars x =
                let args = Array.map show_w x |> String.concat ", "
                if 1 < x.Length then sprintf "TupleCreate%i(%s)" (tup (term_vars_to_tysC x)).tag args else args
            and tup_data x = tup_term_vars (data_term_vars x)
            and tup_ty_tys = function
                | [||] -> "void"
                | [|x|] -> tyv x
                | x -> sprintf "Tuple%i" (tup x).tag
            and tup_ty_tyvs (x : TyV []) = tup_ty_tys (tyvs_to_tys x)
            and tup_ty x = env.ty_to_data x |> data_free_vars |> tup_ty_tyvs
            and tyv x =
                match x with
                | YUnion a ->
                    match a.Item.layout with
                    | UStack -> sprintf "US%i" (ustack a).tag
                    | UHeap -> sprintf "UH%i *" (uheap a).tag
                | YLayout(_,lay) as a ->
                    match lay with
                    | Heap -> sprintf "Heap%i *" (heap a).tag
                    | HeapMutable -> sprintf "Mut%i *" (mut a).tag
                    | StackMutable -> raise_codegen_error "Compiler error: The C backend doesn't support stack mutable layout types."
                    | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                    match r |> Map.tryPick (fun (_, k) v -> if k = "C" then Some v else None) with
                    | Some x -> tup_ty x
                    | None -> raise_codegen_error "In the type backend_switch, expected a record with the 'C' field."
                | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_lit a) |> String.concat ""
                | YPrim a -> prim a
                | YArray a -> sprintf "Array%i *" (carray a).tag
                | YFun(a,b,FT_Vanilla) ->
                    let tag = (cfun (a,b)).tag
                    if funs_printing.Contains tag && funs_fwd.Add tag then
                        fwd_dcls.Add(StringBuilder().AppendLine($"typedef struct Fun{tag} Fun{tag};").ToString())
                    sprintf "Fun%i *" tag
                | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
                | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
                | a -> raise_codegen_error (sprintf "Compiler error: Type not supported in the codegen.\nGot: %A" a)
            and prim = function
                | Int8T -> "int8_t"
                | Int16T -> "int16_t"
                | Int32T -> "int32_t"
                | Int64T -> "int64_t"
                | UInt8T -> "uint8_t"
                | UInt16T -> "uint16_t"
                | UInt32T -> "uint32_t"
                | UInt64T -> "uint64_t" // are defined in stdint.h
                | Float32T -> "float"
                | Float64T -> "double"
                | BoolT -> "bool" // is defined in stdbool.h
                | CharT -> "char"
                | StringT -> cstring(); "String *"
            and lit = function
                | LitInt8 x -> sprintf "%i" x
                | LitInt16 x -> sprintf "%i" x
                | LitInt32 x -> sprintf "%il" x
                | LitInt64 x -> sprintf "%ill" x
                | LitUInt8 x -> sprintf "%iu" x
                | LitUInt16 x -> sprintf "%iu" x
                | LitUInt32 x -> sprintf "%iul" x
                | LitUInt64 x -> sprintf "%iull" x
                | LitFloat32 x ->
                    if x = infinityf then "HUGE_VALF" // nan/inf macros are defined in math.h
                    elif x = -infinityf then "-HUGE_VALF"
                    elif Single.IsNaN x then "NAN"
                    else x.ToString("R") |> add_dec_point |> sprintf "%sf"
                | LitFloat64 x ->
                    if x = infinity then "HUGE_VAL"
                    elif x = -infinity then "-HUGE_VAL"
                    elif Double.IsNaN x then "NAN"
                    else x.ToString("R") |> add_dec_point
                | LitString x ->
                    cstring()
                    lit_stringC x |> sprintf "StringLit(%i, %s)" (System.Text.Encoding.UTF8.GetByteCount x + 1)
                | LitChar x ->
                    match x with
                    | '\b' -> @"\b"
                    | '\n' -> @"\n"
                    | '\t' -> @"\t"
                    | '\r' -> @"\r"
                    | '\\' -> @"\\"
                    | '\000' -> @"\0"
                    | x -> string x
                    |> sprintf "'%s'"
                | LitBool x -> if x then "true" else "false" // true and false are defined in stddef.h
            and type_lit = function
                | YLit x -> lit x
                | YSymbol x -> x
                | YNominal _ | YApply _ as x -> type_lit (env.nominal_apply x)
                | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."
            and op (vars : RefcVars) s (ret : BindsReturnC) a =
                let binds a b = binds vars a b
                let return' (x : string) =
                    match ret with
                    | BindsLocal ret -> return_local s ret x
                    | BindsTailEnd -> line s $"return {x};"
                let layout_index (x'_i : int) (x' : TyV []) =
                    match ret with
                    | BindsLocal x -> Array.map2 (fun (L(i,_)) (L(i',_)) -> $"v{i} = v{x'_i}->v{i'};") x x' |> line' s
                    | BindsTailEnd -> raise_codegen_error "Compiler error: Layout index should never come in end position."
                let jp (a,b') =
                    let args = args b'
                    match a with
                    | JPMethod(a,b) ->
                        let x = method (a,b)
                        let name = Option.defaultValue "method" x.name
                        fn_fwd $"{name}{x.tag}" true (fun () -> method_sig name x)
                        sprintf "%s%i(%s)" name x.tag args
                    | JPClosure(a,b) ->
                        let x = closure (a,b)
                        fn_fwd $"ClosureCreate{x.tag}" false (fun () -> closure_create_sig x)
                        sprintf "ClosureCreate%i(%s)" x.tag args
                let string_in_op = function DLit (LitString b) -> lit_stringC b | b -> $"{tup_data b}->ptr"
                match a with
                | TySizeOf t -> return' $"sizeof({tup_ty t})"
                | TyMacro _ -> raise_codegen_error "Macros are supposed to be taken care of in the `binds` function."
                | TyIf(cond,tr,fl) ->
                    line s (sprintf "if (%s){" (tup_data cond))
                    binds (indent s) ret tr
                    line s "} else {"
                    binds (indent s) ret fl
                    line s "}"
                | TyJoinPoint(JPMethod(a,b),args) when (match ret, self_loop.Value, self_let_tail_target.Value with BindsLocal l, Some (tag, _, depth), Some (target, _) -> depth = fns_printing.Count && l = target && is_method_tag tag (a, b) | _ -> false) ->
                    let _, parameters, _ = self_loop.Value.Value
                    let _, release = self_let_tail_target.Value.Value
                    let saved_release = self_continue_release.Value
                    self_continue_release.Value <- release
                    self_continue s parameters args
                    self_continue_release.Value <- saved_release
                | TyJoinPoint(JPMethod(a,b),args) when (match ret, self_loop.Value with BindsTailEnd, Some (tag, _, depth) -> depth = fns_printing.Count && is_method_tag tag (a, b) | _ -> false) ->
                    let _, parameters, _ = self_loop.Value.Value
                    self_continue s parameters args
                | TyJoinPoint(a,args) -> return' (jp (a, args))
                | TyBackend(_,_,r) -> raise_codegen_error_backend r "The C backend does not support nesting of other backends."
                | TyWhile(a,b) ->
                    let cond =
                        match a with
                        | JPMethod(a,b),b' ->
                            let x = method_while (a,b)
                            fn_fwd $"method_while{x.tag}" true (fun () -> method_sig "method_while" x)
                            sprintf "method_while%i(%s)" x.tag (args b')
                        | _ -> raise_codegen_error "Expected a regular method rather than closure create in the while conditional."
                    line s (sprintf "while (%s){" cond)
                    binds (indent s) (BindsLocal [||]) b
                    line s "}"
                | TyDo a | TyIndent a ->
                    binds s ret a
                | TyIntSwitch(L(v_i,_),on_succ,on_fail) ->
                    line s (sprintf "switch (v%i) {" v_i)
                    let _ =
                        let s = indent s
                        Array.iteri (fun i x ->
                            line s (sprintf "case %i: {" i)
                            binds (indent s) ret x
                            line (indent s) "break;"
                            line s "}"
                            ) on_succ
                        line s "default: {"
                        binds (indent s) ret on_fail
                        line s "}"
                    line s "}"
                | TyUnionUnbox(is,x,on_succs,on_fail) ->
                    let case_tags = x.Item.tags
                    let acs = match x.Item.layout with UHeap -> "->" | UStack -> "."
                    let head = List.head is |> fun (L(i,_)) -> $"v{i}{acs}tag"
                    List.pairwise is
                    |> List.map (fun (L(i,_), L(i',_)) -> $"v{i}{acs}tag == v{i'}{acs}tag")
                    |> String.concat " && "
                    |> function "" -> head | x -> $"{x} ? {head} : -1"
                    |> sprintf "switch (%s) {" |> line s
                    let exhaustive_last_case =
                        match on_fail, is with
                        | None, [_] -> on_succs |> Map.toSeq |> Seq.tryLast |> Option.map fst
                        | _ -> None
                    let _ =
                        let s = indent s
                        Map.iter (fun k (a,b) ->
                            let union_i = case_tags.[k]
                            let decr = get_default vars.g_decr (Array.head b) (fun () -> Set.empty)
                            if exhaustive_last_case = Some k then line s (sprintf "default: { // %s" (UnionTagIdOps.text k))
                            else line s (sprintf "case %i: { // %s" union_i (UnionTagIdOps.text k))
                            List.iter2 (fun (L(data_i,_)) a ->
                                let a, s = data_free_vars a, indent s
                                let qs = ResizeArray(a.Length)
                                Array.iteri (fun field_i (L(v_i,t) as v) ->
                                    if Set.contains v decr = false then qs.Add $"{tyv t} v{v_i} = v{data_i}{acs}case{union_i}.v{field_i};"
                                    ) a
                                line' s qs
                                ) is a
                            binds (indent s) ret b
                            line (indent s) "break;"
                            line s "}"
                            ) on_succs
                        on_fail |> Option.iter (fun b ->
                            line s "default: {"
                            binds (indent s) ret b
                            line s "}"
                            )
                    line s "}"
                | TyUnionBox(a,b,c') ->
                    let c = c'.Item
                    let i = c.tags.[a]
                    let vars = args' b
                    match c.layout with
                    | UHeap -> let u = uheap c' in sprintf "%s(%s)" (generatedCaseNameOfTag (sprintf "UH%i" u.tag) u.free_vars i) vars
                    | UStack -> let u = ustack c' in sprintf "%s(%s)" (generatedCaseNameOfTag (sprintf "US%i" u.tag) u.free_vars i) vars
                    |> return'
                | TyToLayout(a,b) ->
                    match b with
                    | YLayout(_,layout) ->
                        match layout with
                        | Heap -> sprintf "HeapCreate%i(%s)" (heap b).tag (args' a)
                        | HeapMutable -> sprintf "MutCreate%i(%s)" (mut b).tag (args' a)
                        | StackMutable -> raise_codegen_error "The C backend doesn't support stack mutable layout types."
                        | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                    | _ -> raise_codegen_error $"Compiler error: Expected a layout type (8).\nGot: %s{show_ty b}"
                    |> return'
                | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                    match lay with
                    | Heap -> heap a
                    | HeapMutable -> mut a
                    | StackMutable -> raise_codegen_error "The C backend doesn't support indexing into stack mutable layout types."
                    | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                    |> fun x -> x.free_vars |> layout_index i
                | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                    match lay with
                    | Heap -> heap a
                    | HeapMutable -> mut a
                    | StackMutable -> raise_codegen_error "The C backend doesn't support indexing into stack mutable layout types."
                    | StackRefs | HeapRefs -> raise_codegen_error "This backend doesn't support the stack and heap refs layout types."
                    |> fun x ->
                        x.free_vars_by_key
                        |> Map.tryPick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None)
                        |> Option.iter (layout_index i)
                | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
                | TyLayoutMutableSet(L(i,t),b,c) ->
                    let q = mut t // `mut t` is correct here, peval strips the YLayout.
                    let a = List.fold (fun s k ->
                        match s with
                        | DRecord l -> l |> Map.pick (fun (_,k') v -> if LayoutFieldNameIdOps.matchesText k k' then Some v else None)
                        | _ -> raise_codegen_error "Compiler error: Expected a record.") q.data b
                    Array.map2 (fun (L(i',_)) b -> $"&(v{i}->v{i'}), {show_w b}") (data_free_vars a) (data_term_vars c) |> String.concat ", "
                    |> sprintf "AssignMut%i(%s)" (assign_mut (tyvs_to_tys q.free_vars)).tag |> return'
                | TyArrayLiteral(a,b') ->
                    let b = List.map tup_data b' |> String.concat "," |> sprintf "{%s}"
                    $"ArrayLit{(carray a).tag}({b'.Length}, ({tup_ty a} []){b})" |> return'
                | TyArrayCreate(a,b) ->
                    let a = carray a
                    $"ArrayCreate{a.tag}({tup_data b}, true)" |> return'
                | TyFailwith(a,b) ->
                    let fmt = @"%s\n"
                    line s $"fprintf(stderr, \"{fmt}\", {string_in_op b});"
                    line s "exit(EXIT_FAILURE);" // TODO: Print out the error traces as well.
                | TyConv(a,b) -> return' $"({tyv a}){tup_data b}"
                | TyApply(L(i,_),b) ->
                    match args' b with
                    | "" -> $"v{i}->fptr(v{i})"
                    | b -> $"v{i}->fptr(v{i}, {b})"
                    |> return'
                | TyArrayLength(_,b) -> return' $"{tup_data b}->len"
                | TyStringLength(_,b) -> return' $"{tup_data b}->len-1"
                | TyOp(Global,[DLit (LitString x)]) -> global' x
                | TyOp(op,l) ->
                    let float_suffix = function
                        | DV(L(_,YPrim Float32T)) | DLit(LitFloat32 _) -> "f"
                        | _ -> ""
                    match op, l with
                    | Dyn,[a] -> tup_data a
                    | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                    | StringIndex, [a;b] -> sprintf "%s->ptr[%s]" (tup_data a) (tup_data b)
                    | StringSlice, [a;b;c] -> cstring(); cstring_slice(); sprintf "StringSlice(%s, %s, %s)" (tup_data a) (tup_data b) (tup_data c)
                    | StaticStringConcat, [a;b] -> cstring(); cstring_concat(); sprintf "StringConcat(%s, %s)" (tup_data a) (tup_data b)
                    | PrimToString, [a] ->
                        cstring()
                        let ty =
                            match a with
                            | DV(L(_,t)) -> t
                            | DLit l -> YPrim (lit_to_primitive_type l)
                            | _ -> raise_codegen_error "PrimToString expects a primitive value."
                        match ty with
                        | YPrim (Int8T | Int16T | Int32T | Int64T) -> cstring_from_i64(); sprintf "StringFromI64((int64_t)%s)" (tup_data a)
                        | YPrim (UInt8T | UInt16T | UInt32T | UInt64T) -> cstring_from_u64(); sprintf "StringFromU64((uint64_t)%s)" (tup_data a)
                        | YPrim BoolT -> cstring_from_bool(); sprintf "StringFromBool(%s)" (tup_data a)
                        | YPrim CharT -> cstring_from_char(); sprintf "StringFromChar(%s)" (tup_data a)
                        | _ -> raise_codegen_error "PrimToString expects an integer, bool or char."
                    | ArrayIndex, [DV(L(_,YArray t)) & a;b] ->
                        match tup_ty t with
                        | "void" -> "/* void array index */"
                        | _ -> sprintf "%s->ptr[%s]" (tup_data a) (tup_data b)
                    | ArrayIndexSet, [DV(L(_,YArray t)) as a;b;c] ->
                        let a',b',c' = tup_data a, tup_data b, tup_data c
                        match c' with
                        | "" -> "/* void array set */"
                        | _ -> $"AssignArray{(assign_array (tyvs_to_tys (carray t).tyvs)).tag}(&({a'}->ptr[{b'}]), {c'})"
                    // Math
                    | Add, [a;b] -> sprintf "%s + %s" (tup_data a) (tup_data b)
                    | Sub, [a;b] -> sprintf "%s - %s" (tup_data a) (tup_data b)
                    | Mult, [a;b] -> sprintf "%s * %s" (tup_data a) (tup_data b)
                    | Div, [a;b] -> sprintf "%s / %s" (tup_data a) (tup_data b)
                    | Mod, [(DV(L(_,YPrim (Float32T | Float64T))) | DLit(LitFloat32 _ | LitFloat64 _)) & a;b] -> import "math.h"; sprintf "fmod%s(%s, %s)" (float_suffix a) (tup_data a) (tup_data b)
                    | Mod, [a;b] -> sprintf "%s %% %s" (tup_data a) (tup_data b)
                    | Pow, [a;b] -> import "math.h"; sprintf "pow%s(%s,%s)" (float_suffix a) (tup_data a) (tup_data b)
                    | LT, [a;b] when is_stringC a -> import "string.h"; sprintf "strcmp(%s, %s) < 0" (string_in_op a) (string_in_op b)
                    | LTE, [a;b] when is_stringC a -> import "string.h"; sprintf "strcmp(%s, %s) <= 0" (string_in_op a) (string_in_op b)
                    | LT, [a;b] -> sprintf "%s < %s" (tup_data a) (tup_data b)
                    | LTE, [a;b] -> sprintf "%s <= %s" (tup_data a) (tup_data b)
                    // string_in_op already yields the char pointer (a C string literal, or value->ptr).
                    | EQ, [a;b] when is_stringC a -> import "string.h"; sprintf "strcmp(%s, %s) == 0" (string_in_op a) (string_in_op b)
                    | NEQ, [a;b] when is_stringC a -> import "string.h"; sprintf "strcmp(%s, %s) != 0" (string_in_op a) (string_in_op b)
                    | GT, [a;b] when is_stringC a -> import "string.h"; sprintf "strcmp(%s, %s) > 0" (string_in_op a) (string_in_op b)
                    | GTE, [a;b] when is_stringC a -> import "string.h"; sprintf "strcmp(%s, %s) >= 0" (string_in_op a) (string_in_op b)
                    | EQ, [a;b] -> sprintf "%s == %s" (tup_data a) (tup_data b)
                    | NEQ, [a;b] -> sprintf "%s != %s" (tup_data a) (tup_data b)
                    | GT, [a;b] -> sprintf "%s > %s" (tup_data a) (tup_data b)
                    | GTE, [a;b] -> sprintf "%s >= %s" (tup_data a) (tup_data b)
                    | BoolAnd, [a;b] -> sprintf "%s && %s" (tup_data a) (tup_data b)
                    | BoolOr, [a;b] -> sprintf "%s || %s" (tup_data a) (tup_data b)
                    | BitwiseAnd, [a;b] -> sprintf "%s & %s" (tup_data a) (tup_data b)
                    | BitwiseOr, [a;b] -> sprintf "%s | %s" (tup_data a) (tup_data b)
                    | BitwiseXor, [a;b] -> sprintf "%s ^ %s" (tup_data a) (tup_data b)
                    | BitwiseComplement, [a] -> sprintf "~%s" (tup_data a)

                    | ShiftLeft, [a;b] -> sprintf "%s << %s" (tup_data a) (tup_data b)
                    | ShiftRight, [a;b] -> sprintf "%s >> %s" (tup_data a) (tup_data b)

                    | Neg, [x] -> sprintf "-%s" (tup_data x)
                    | Log, [x] -> import "math.h"; sprintf "log%s(%s)" (float_suffix x) (tup_data x)
                    | Exp, [x] -> import "math.h"; sprintf "exp%s(%s)" (float_suffix x) (tup_data x)
                    | Tanh, [x] -> import "math.h"; sprintf "tanh%s(%s)" (float_suffix x) (tup_data x)
                    | Sqrt, [x] -> import "math.h"; sprintf "sqrt%s(%s)" (float_suffix x) (tup_data x)
                    | Sin, [x] -> import "math.h"; sprintf "sin%s(%s)" (float_suffix x) (tup_data x)
                    | Cos, [x] -> import "math.h"; sprintf "cos%s(%s)" (float_suffix x) (tup_data x)
                    | NanIs, [x] -> import "math.h"; sprintf "isnan(%s)" (tup_data x)
                    | StdoutFlush, [] -> import "stdio.h"; "fflush(stdout)"
                    | Assign, [a; b] -> sprintf "%s = %s" (tup_data a) (tup_data b)
                    | MonotonicDelayMs, [duration] -> import "poll.h"; sprintf "poll(0, 0, %s)" (tup_data duration)
                    | Printf, [DLit (LitString fmt); str] ->
                        // The portable format (printf_pieces) becomes a C format with one specifier per argument type.
                        import "stdio.h"
                        let data = function WV v -> DV v | WLit l -> DLit l
                        let cfmt = StringBuilder()
                        let args = ResizeArray()
                        for p in printf_pieces fmt (data_term_vars str) do
                            match p with
                            | Choice1Of2 t -> cfmt.Append(t.Replace("%", "%%")) |> ignore
                            | Choice2Of2 ('s', a) -> cfmt.Append "%s" |> ignore; args.Add(string_in_op (data a))
                            | Choice2Of2 (_, a) ->
                                let t = match a with WV(L(_,YPrim t)) -> t | WLit l -> lit_to_primitive_type l | _ -> Int32T
                                let spec, cast =
                                    match t with
                                    | Int64T -> "%lld", "(long long)"
                                    | UInt64T -> "%llu", "(unsigned long long)"
                                    | UInt8T | UInt16T | UInt32T -> "%u", "(unsigned)"
                                    | _ -> "%d", "(int)"
                                cfmt.Append spec |> ignore
                                args.Add(cast + tup_data (data a))
                        String.concat ", " (lit_stringC (cfmt.ToString()) :: List.ofSeq args) |> sprintf "printf(%s)"
                    | UnionTag, [DV(L(i,YUnion l)) as x] ->
                        match l.Item.layout with
                        | UHeap -> "->tag"
                        | UStack -> ".tag"
                        |> sprintf "v%i%s" i
                    | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported" op l.Length
                    |> return'
            and print_ordered_args s v = // Unlike C# for example, C keeps the struct fields in input order. To reduce padding, it is best to order the fields from largest to smallest.
                order_argsC v |> Array.iter (fun (L(i,x)) -> line s $"{tyv x} v{i};")
            and owned_params (x : MethodRecC) =
                let jp_body, key = method_key_of_tag.[x.tag] :?> (string ConsedNode * E) * ConsedNode<RData [] * Ty []>
                x.free_vars |> Array.indexed |> Array.filter (fun (i, _) -> not (borrowed_param (JPMethod(jp_body, key)) i)) |> Array.map snd
            and method_templ is_while fun_name : _ -> MethodRecC =
                jp (fun ((jp_body,key),i) ->
                    let args = codegenMethodKeyArgs key
                    method_key_of_tag.[i] <- box (jp_body, key)
                    match codegenMethodBody env "C" jp_body key with
                    | a, range, name -> {tag=i; free_vars=rdata_free_vars args; range=range; body=a; name=name}
                    ) (fun _ s_typ s_fun x ->
                    let fun_name = Option.defaultValue fun_name x.name
                    let borrowed_loop = not is_while && self_tail x.tag x.body && (owned_params x).Length < x.free_vars.Length
                    if borrowed_loop then borrowed_loops.Add $"{fun_name}{x.tag}" |> ignore
                    line s_fun ((if borrowed_loop then "__attribute__((noinline)) " else "") + method_sig fun_name x + "{")
                    fns_printing.Add $"{fun_name}{x.tag}"
                    let saved = self_loop.Value
                    let saved_release = self_continue_release.Value
                    let saved_target = self_let_tail_target.Value
                    self_continue_release.Value <- ignore
                    self_let_tail_target.Value <- None
                    if not is_while && self_tail x.tag x.body then
                        self_loop.Value <- Some (x.tag, x.free_vars, fns_printing.Count)
                        line (indent s_fun) "while (1) {"
                        binds_start (owned_params x) (indent (indent s_fun)) x.body
                        line (indent s_fun) "}"
                    else
                        self_loop.Value <- None
                        binds_start (if is_while then [||] else owned_params x) (indent s_fun) x.body
                    self_loop.Value <- saved
                    self_continue_release.Value <- saved_release
                    self_let_tail_target.Value <- saved_target
                    fns_printing.RemoveAt(fns_printing.Count - 1)
                    line s_fun "}"
                    )
            and self_tail tag (body : TypedBind []) =
                body.Length > 0 &&
                match Array.last body with
                | TyLocalReturnOp(_, a, _) -> op_self_tail tag a
                | TyLocalReturnData(r,_) when body.Length >= 2 ->
                    match body.[body.Length - 2] with
                    | TyLet(d,_,a) when returns_unchanged d r -> op_self_tail tag a
                    | _ -> false
                | _ -> false
            and op_self_tail tag (a : TypedOp) =
                match a with
                | TyJoinPoint(JPMethod(x,c),_) -> is_method_tag tag (x, c)
                | TyIf(_,tr,fl) -> self_tail tag tr || self_tail tag fl
                | TyUnionUnbox(_,_,on_succs,on_fail) -> (on_succs |> Map.exists (fun _ (_,b) -> self_tail tag b)) || (on_fail |> Option.exists (self_tail tag))
                | TyIntSwitch(_,on_succ,on_fail) -> Array.exists (self_tail tag) on_succ || self_tail tag on_fail
                | TyDo b | TyIndent b -> self_tail tag b
                | _ -> false
            and returns_unchanged d r =
                let bound = data_free_vars d
                let returned = data_term_vars r
                bound.Length = returned.Length && Array.forall2 (fun (L(i,_)) w -> match w with WV(L(j,_)) -> i = j | WLit _ -> false) bound returned
            and is_method_tag tag (x, c) =
                match method_key_of_tag.TryGetValue tag with
                | true, k -> k.Equals(box (x, c))
                | _ -> false
            and method_sig fun_name (x : MethodRecC) =
                let ret_ty = tup_ty x.range
                let args = x.free_vars |> Array.mapi (fun i (L(_,x)) -> $"{tyv x} v{i}") |> String.concat ", "
                sprintf "%s %s%i(%s)" ret_ty fun_name x.tag args
            and closure_create_sig (x : ClosureRecC) =
                let fun_tag = (cfun (x.domain,x.range)).tag
                let free_vars = x.free_vars |> Array.map (fun (L(i,t)) -> $"{tyv t} v{i}")
                sprintf "Fun%i * ClosureCreate%i(%s)" fun_tag x.tag (String.concat ", " free_vars)
            and method_while : _ -> MethodRecC = method_templ true "method_while"
            and method : _ -> MethodRecC = method_templ false "method"
            and closure : _ -> ClosureRecC =
                jp (fun ((jp_body,key & (C(args,_,fun_ty))),i) ->
                    match fun_ty with
                    | YFun(domain,range,FT_Vanilla) ->
                        match codegenClosureBody env "C" jp_body key with
                        | domain_args, body, name -> {tag=i; free_vars=rdata_free_vars args; domain=domain; domain_args=data_free_vars domain_args; range=range; body=body; name=name}
                    | YFun(_,_,_)-> raise_codegen_error "Non-standard functions are not supported in the C backend."
                    | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."
                    ) (fun _ s_typ s_fun x ->
                    let i, range, cname = x.tag, tup_ty x.range, generatedClosureName x.name x.tag
                    let fun_tag = (cfun (x.domain,x.range)).tag
                    fns_printing.Add $"ClosureCreate{i}"
                    line s_typ (sprintf "typedef struct Closure%i Closure%i;" i i)
                    line s_typ (sprintf "struct Closure%i {" i)
                    let _ =
                        let s_typ = indent s_typ
                        line s_typ $"Fun{fun_tag} base;"
                        print_ordered_args s_typ x.free_vars
                    line s_typ "};"

                    line s_fun (sprintf "static inline void ClosureDecrefBody%i(Closure%i * x){" i i)
                    let _ =
                        let s_fun = indent s_fun
                        match x.free_vars |> refc_change (fun i -> $"x->v{i}") -1 with
                        | [||] -> line s_fun "(void)x;"
                        | decrefs -> decrefs |> line' s_fun
                    line s_fun "}"

                    line s_fun $"void ClosureDecref{i}(Fun{fun_tag} * self){{"
                    let _ =
                        let s_fun = indent s_fun
                        line s_fun $"Closure{i} * x = (Closure{i} *) self;"
                        line s_fun (sprintf "if (x != NULL && %s) { ClosureDecrefBody%i(x); %s(x); }" (refc_drop "x->base.refc") i free)
                    line s_fun "}"

                    match x.domain_args |> Array.map (fun (L(i,t)) -> $"{tyv t} v{i}") |> String.concat ", " with
                    | "" -> sprintf "%s %s(Fun%i * self){" range cname fun_tag
                    | domain_args -> sprintf "%s %s(Fun%i * self, %s){" range cname fun_tag domain_args
                    |> line s_fun
                    let _ =
                        let s_fun = indent s_fun
                        if x.free_vars.Length > 0 then line s_fun $"Closure{i} * x = (Closure{i} *) self;"
                        x.free_vars |> Array.map (fun (L(i,t)) -> $"{tyv t} v{i} = x->v{i};") |> line' s_fun
                        // A call consumes a reference to the closure, so ClosureDecref can free it here, and with
                        // it the captured values: take a reference to each first and let the body own them
                        // (released at their last use). Without it, `f` capturing an array and called through
                        // its last reference read the freed array (native_closure_array_capture: 40, not 42).
                        x.free_vars |> refc_change (fun i -> $"v{i}") 1 |> line' s_fun
                        line s_fun $"ClosureDecref{i}(self);"
                        // -Wunused-parameter: a domain argument the body never reads still has to be in the
                        // signature, so void-cast exactly those arguments
                        let used = refc_used_vars x.body |> Seq.map (fun kv -> kv.Value) |> Set.unionMany |> Set.map (fun (L(tag,_)) -> tag)
                        x.domain_args |> Array.iter (fun (L(tag,_)) -> if not (used.Contains tag) then line s_fun $"(void)v{tag};")
                        binds_start (Array.append x.free_vars x.domain_args) s_fun x.body
                    line s_fun "}"

                    line s_fun (closure_create_sig x + "{")
                    let _ =
                        let s_fun = indent s_fun
                        line s_fun $"Closure{i} * x = {malloc}(sizeof(Closure{i}));"
                        line s_fun "x->base.refc = 1;"
                        line s_fun $"x->base.decref_fptr = ClosureDecref{i};"
                        line s_fun $"x->base.fptr = {cname};"
                        x.free_vars |> Array.map (fun (L(i,_)) -> $"x->v{i} = v{i};")  |> line' s_fun
                        line s_fun "return &x->base;"
                    line s_fun "}"
                    fns_printing.RemoveAt(fns_printing.Count - 1)
                    )
            and cfun : _ -> CFunRecC =
                cfun' (fun _ s_typ s_fun x ->
                    let i = x.tag
                    funs_printing.Add i |> ignore
                    let range = tup_ty x.range
                    let fptr =
                        match x.domain_args_ty |> Array.map tyv |> String.concat ", " with
                        | "" -> $"{range} (*fptr)(Fun{i} *);"
                        | domain_args_ty -> $"{range} (*fptr)(Fun{i} *, {domain_args_ty});"
                    funs_printing.Remove i |> ignore
                    if funs_fwd.Contains i = false then line s_typ $"typedef struct Fun{i} Fun{i};"
                    line s_typ (sprintf "struct Fun%i{" i)
                    let _ =
                        let s_typ = indent s_typ
                        line s_typ $"int refc;"
                        line s_typ $"void (*decref_fptr)(Fun{i} *);"
                        line s_typ fptr
                    line s_typ "};"
                    )
            and tup : _ -> TupleRecC =
                tuple (fun _ s_typ s_fun x ->
                    let name = sprintf "Tuple%i" x.tag
                    line s_typ "typedef struct {"
                    x.tys |> Array.mapi (fun i x -> L(i,x)) |> print_ordered_args (indent s_typ)
                    line s_typ (sprintf "} %s;" name)

                    let args = x.tys |> Array.mapi (fun i x -> $"{tyv x} v{i}")
                    line s_fun (sprintf "static inline %s TupleCreate%i(%s){" name x.tag (String.concat ", " args))
                    let _ =
                        let s_fun = indent s_fun
                        line s_fun $"{name} x;"
                        Array.init args.Length (fun i -> $"x.v{i} = v{i};") |> line' s_fun
                        line s_fun $"return x;"
                    line s_fun "}"
                    )
            and assign_mut : _ -> TupleRecC =
                tuple (fun _ s_typ s_fun x ->
                    let tyvs = Array.mapi (fun i t -> L(i,t)) x.tys
                    let args = Array.mapi (fun i t -> let t = tyv t in $"{t} * a{i}, {t} b{i}") x.tys |> String.concat ", "
                    line s_fun (sprintf "static inline void AssignMut%i(%s){" x.tag args)
                    let _ =
                        let s_fun = indent s_fun
                        refc_change (fun i -> $"b{i}") 1 tyvs |> line' s_fun
                        refc_change (fun i -> $"*a{i}") -1 tyvs |> line' s_fun
                        Array.init tyvs.Length (fun i -> $"*a{i} = b{i};") |> line' s_fun
                    line s_fun "}"
                    )
            and assign_array : _ -> TupleRecC =
                tuple (fun _ s_typ s_fun x ->
                    let tyvs, t = Array.mapi (fun i t -> L(i,t)) x.tys, tup_ty_tys x.tys
                    line s_fun (sprintf "static inline void AssignArray%i(%s * a, %s b){" x.tag t t)
                    let _ =
                        let s_fun = indent s_fun
                        match tyvs with
                        | [||] -> raise_codegen_error "Compiler error: Void types not allowed in assign."
                        | [|L(_, YFun _)|] ->
                            refc_change (fun i -> "b") 1 tyvs |> line' s_fun
                            // ArrayCreate zero-fills the slot. A null closure has no decref.
                            line s_fun "if (*a) { (*a)->decref_fptr(*a); }"
                            line s_fun "*a = b;"
                        | [|t|] ->
                            refc_change (fun i -> "b") 1 tyvs |> line' s_fun
                            refc_change (fun i -> "*a") -1 tyvs |> line' s_fun
                            $"*a = b;" |> line s_fun
                        | _ ->
                            refc_change (fun i -> $"b.v{i}") 1 tyvs |> line' s_fun
                            refc_change (fun i -> $"a->v{i}") -1 tyvs |> line' s_fun
                            $"*a = b;" |> line s_fun
                    line s_fun "}"
                    )
            and layout_tmpl name : _ -> LayoutRecC =
                layout (fun _ s_typ s_fun (x : LayoutRecC) ->
                    let i = x.tag
                    let name' = sprintf "%s%i" name i

                    line s_typ "typedef struct {"
                    let _ =
                        let s_typ = indent s_typ
                        line s_typ "int refc;"
                        print_ordered_args s_typ x.free_vars
                    line s_typ (sprintf "} %s;" name')

                    line s_fun (sprintf "static inline void %sDecrefBody%i(%s * x){" name i name')
                    let _ =
                        let s_fun = indent s_fun
                        match x.free_vars |> refc_change (fun i -> $"x->v{i}") -1 with
                        | [||] -> line s_fun "(void)x;"
                        | decrefs -> decrefs |> line' s_fun
                    line s_fun "}"

                    print_decref s_fun $"{name}Decref{i}" name' $"{name}DecrefBody{i}"

                    let args = x.free_vars |> Array.map (fun (L(i,x)) -> $"{tyv x} v{i}")
                    line s_fun (sprintf "%s * %sCreate%i(%s){" name' name i (String.concat ", " args))
                    let _ =
                        let s_fun = indent s_fun
                        line s_fun $"{name'} * x = {malloc}(sizeof({name'}));"
                        line s_fun "x->refc = 1;"
                        Array.init args.Length (fun i -> $"x->v{i} = v{i};") |> line' s_fun
                        line s_fun $"return x;"
                    line s_fun "}"
                    )
            and heap : _ -> LayoutRecC = layout_tmpl "Heap"
            and mut : _ -> LayoutRecC = layout_tmpl "Mut"
            and union_tmpl is_stack : Union -> UnionRecC =
                let inline map_iteri f x = Map.iter (fun ((tag : int, _) as k) v -> f tag k v) x
                union (fun s_fwd s_typ s_fun x ->
                    let i = x.tag
                    match is_stack with
                    | true  -> line s_typ "typedef struct {"
                    | false ->
                        line s_fwd (sprintf "typedef struct UH%i UH%i;" i i)
                        line s_typ (sprintf "struct UH%i {" i)
                    let _ =
                        let s_typ = indent s_typ
                        match is_stack with
                        | true -> ()
                        | false -> line s_typ "int refc;"
                        line s_typ "int tag;"
                        line s_typ "union {"
                        let _ =
                            let s_typ = indent s_typ
                            map_iteri (fun tag (_, k) v ->
                                if Array.isEmpty v = false then
                                    line s_typ "struct {"
                                    print_ordered_args (indent s_typ) v
                                    line s_typ (sprintf "} case%i; // %s" tag k)
                                ) x.free_vars
                        line s_typ "};"
                    match is_stack with
                    | true  -> line s_typ (sprintf "} US%i;" i)
                    | false -> line s_typ "};"

                    let print_refc name typ q =
                        line s_fun (sprintf "static inline void %s(%s * x){" name typ)
                        let _ =
                            let s_fun = indent s_fun
                            line s_fun "switch (x->tag) {"
                            map_iteri (fun tag k v ->
                                let s_fun = indent s_fun
                                let refc = v |> refc_change (fun i -> $"x->case{tag}.v{i}") q
                                if refc.Length <> 0 then
                                    line s_fun (sprintf "case %i: {" tag)
                                    let _ =
                                        let s_fun = indent s_fun
                                        refc |> line' s_fun
                                        line s_fun "break;"
                                    line s_fun "}"
                                ) x.free_vars
                            line s_fun "}"
                        line s_fun "}"

                    match is_stack with
                    | true  ->
                        print_refc $"USIncrefBody{i}" $"US{i}" 1
                        print_refc $"USDecrefBody{i}" $"US{i}" -1
                    | false -> print_refc $"UHDecrefBody{i}" $"UH{i}" -1

                    match is_stack with
                    | true  ->
                        line s_fun (sprintf "void USIncref%i(US%i * x){ USIncrefBody%i(x); }" i i i)
                        line s_fun (sprintf "void USDecref%i(US%i * x){ USDecrefBody%i(x); }" i i i)
                    | false ->
                        line s_fwd (sprintf "void UHDecref%i(UH%i * x);" i i)
                        let is_same_union (L(_,t)) = match t with YUnion u -> u.Item.layout = UHeap && (uheap u).tag = i | _ -> false
                        if x.free_vars |> Map.exists (fun _ v -> Array.exists is_same_union v) then
                            line s_fun (sprintf "void UHDecref%i(UH%i * x){" i i)
                            let _ =
                                let s_fun = indent s_fun
                                line s_fun (sprintf "while (x != NULL && %s) {" (refc_drop "x->refc"))
                                let _ =
                                    let s_fun = indent s_fun
                                    line s_fun (sprintf "UH%i * next = NULL;" i)
                                    line s_fun "switch (x->tag) {"
                                    map_iteri (fun tag k v ->
                                        let s_fun = indent s_fun
                                        let next_field = v |> Array.tryFindBack is_same_union
                                        let others = v |> Array.filter (fun field -> Some field <> next_field)
                                        let refc = others |> refc_change (fun i -> $"x->case{tag}.v{i}") -1
                                        if refc.Length <> 0 || next_field.IsSome then
                                            line s_fun (sprintf "case %i: {" tag)
                                            let _ =
                                                let s_fun = indent s_fun
                                                refc |> line' s_fun
                                                next_field |> Option.iter (fun (L(field,_)) -> line s_fun $"next = x->case{tag}.v{field};")
                                                line s_fun "break;"
                                            line s_fun "}"
                                        ) x.free_vars
                                    line s_fun "}"
                                    line s_fun $"{free}(x);"
                                    line s_fun "x = next;"
                                line s_fun "}"
                            line s_fun "}"
                        else
                            print_decref s_fun $"UHDecref{i}" $"UH{i}" $"UHDecrefBody{i}"

                    map_iteri (fun tag (_, k) v ->
                        let args = v |> Array.map (fun (L(i,t)) -> $"{tyv t} v{i}") |> String.concat ", "
                        if is_stack then
                            line s_fun (sprintf "US%i %s(%s) { // %s" i (generatedCaseNameOfTag (sprintf "US%i" i) x.free_vars tag) args k)
                            let _ =
                                let s_fun = indent s_fun
                                line s_fun $"US{i} x;"
                                line s_fun $"x.tag = {tag};"
                                if v.Length <> 0 then
                                    v |> Array.map (fun (L(i,t)) -> $"x.case{tag}.v{i} = v{i};") |> line' s_fun
                                line s_fun "return x;"
                            line s_fun "}"
                        else
                            line s_fun (sprintf "UH%i * %s(%s) { // %s" i (generatedCaseNameOfTag (sprintf "UH%i" i) x.free_vars tag) args k)
                            if v.Length = 0 then
                                let s_fun = indent s_fun
                                line s_fun $"static UH{i} x = {{ .refc = {System.Int32.MaxValue / 2}, .tag = {tag} }};"
                                line s_fun "return &x;"
                            else
                                let s_fun = indent s_fun
                                line s_fun $"UH{i} * x = {malloc}(sizeof(UH{i}));"
                                line s_fun $"x->tag = {tag};"
                                line s_fun "x->refc = 1;"
                                if v.Length <> 0 then
                                    v |> Array.map (fun (L(i,t)) -> $"x->case{tag}.v{i} = v{i};") |> line' s_fun
                                line s_fun $"return x;"
                            line s_fun "}"
                        ) x.free_vars
                    )
            and ustack : _ -> UnionRecC = union_tmpl true
            and uheap : _ -> UnionRecC = union_tmpl false
            and carray : _ -> ArrayRecC =
                carray' (fun _ s_typ s_fun x ->
                    let i, len_t, ptr_t = x.tag, prim size_t, tup_ty_tyvs x.tyvs
                    line s_typ "typedef struct {"
                    let _ =
                        let s_typ = indent s_typ
                        line s_typ "int refc;"
                        line s_typ $"{len_t} len;"
                        if ptr_t <> "void" then line s_typ $"{ptr_t} ptr[];" // flexible array member
                    line s_typ (sprintf "} Array%i;" i)


                    let print_body p s_fun q =
                        let refcs = x.tyvs |> refc_change (fun i -> if 1 < x.tyvs.Length then $"v.v{i}" else "v") q
                        if refcs.Length <> 0 then
                            p()
                            line s_fun (sprintf "for (%s i=0; i < len; i++){" len_t)
                            let _ =
                                let s_fun = indent s_fun
                                line s_fun $"{ptr_t} v = ptr[i];"
                                refcs |> line' s_fun
                            line s_fun "}"

                    line s_fun (sprintf "static inline void ArrayDecrefBody%i(Array%i * x){" i i)
                    let _ =
                        let s_fun = indent s_fun
                        print_body (fun () ->
                            line s_fun $"{len_t} len = x->len;"
                            line s_fun $"{ptr_t} * ptr = x->ptr;"
                            ) s_fun -1
                        if Array.isEmpty (x.tyvs |> refc_change (fun _ -> "v") -1) then line s_fun "(void)x;"
                    line s_fun "}"

                    print_decref s_fun $"ArrayDecref{i}" $"Array{i}" $"ArrayDecrefBody{i}"

                    line s_fun (sprintf "Array%i * ArrayCreate%i(%s len, bool init_at_zero){" i i len_t)
                    let _ =
                        let s_fun = indent s_fun
                        match ptr_t with
                        | "void" -> line s_fun $"{len_t} size = sizeof(Array{i});"
                        | _ -> line s_fun $"{len_t} size = sizeof(Array{i}) + sizeof({ptr_t}) * len;"
                        line s_fun $"Array{i} * x = {malloc}(size);"
                        line s_fun "if (init_at_zero) { memset(x,0,size); }"
                        line s_fun "x->refc = 1;"
                        line s_fun "x->len = len;"
                        line s_fun "return x;"
                    line s_fun "}"

                    line s_fun (sprintf "Array%i * ArrayLit%i(%s len, %s * ptr){" i i len_t ptr_t)
                    let _ =
                        let s_fun = indent s_fun
                        line s_fun $"Array{i} * x = ArrayCreate{i}(len, false);"
                        if ptr_t <> "void" then
                            line s_fun $"memcpy(x->ptr, ptr, sizeof({ptr_t}) * len);"
                            print_body (fun () -> ()) (indent s_fun) 1
                        line s_fun "return x;"
                    line s_fun "}"
                    )
            and cstring : unit -> unit =
                cstring' (fun _ s_typ s_fun () ->
                    let char = YPrim CharT
                    let size_t, ptr_t, tag = prim size_t, tyv char, (carray char).tag
                    line s_typ $"typedef Array{tag} String;"

                    line s_fun "static inline void StringDecref(String * x){"
                    line (indent s_fun) $"return ArrayDecref{tag}(x);"
                    line s_fun "}"

                    line s_fun (sprintf "static inline String * StringLit(%s len, %s * ptr){" size_t ptr_t)
                    line (indent s_fun) $"return ArrayLit{tag}(len, ptr);"
                    line s_fun "}"
                    )
            and cstring_slice : unit -> unit =
                cstring_slice' (fun _ _ s_fun () ->
                    let tag = (carray (YPrim CharT)).tag
                    line s_fun "static inline String * StringSlice(String * value, int32_t from, int32_t to){"
                    let s_slice = indent s_fun
                    line s_slice "int32_t length = (int32_t)value->len - 1;"
                    line s_slice "if (from < 0 || from > length || to < from - 1 || to >= length) { abort(); }"
                    line s_slice "uint32_t slice_len = to < from ? 0u : (uint32_t)(to - from + 1);"
                    line s_slice "if (slice_len != 0u && ((((uint8_t)value->ptr[from] & 0xC0u) == 0x80u) || (to + 1 < length && (((uint8_t)value->ptr[to + 1] & 0xC0u) == 0x80u)))) { abort(); }"
                    line s_slice $"String * result = ArrayCreate{tag}(slice_len + 1, false);"
                    line s_slice "if (slice_len != 0u) { memcpy(result->ptr, value->ptr + from, slice_len); }"
                    line s_slice "result->ptr[slice_len] = '\\0';"
                    line s_slice "return result;"
                    line s_fun "}"
                    )
            and cstring_concat : unit -> unit =
                cstring_concat' (fun _ _ s_fun () ->
                    let tag = (carray (YPrim CharT)).tag
                    line s_fun "static inline String * StringConcat(String * left, String * right){"
                    let s_concat = indent s_fun
                    line s_concat "uint32_t left_len = left->len - 1;"
                    line s_concat "uint32_t right_len = right->len - 1;"
                    line s_concat $"String * result = ArrayCreate{tag}(left_len + right_len + 1, false);"
                    line s_concat "memcpy(result->ptr, left->ptr, left_len);"
                    line s_concat "memcpy(result->ptr + left_len, right->ptr, right_len + 1);"
                    line s_concat "return result;"
                    line s_fun "}"
                    )
            and cstring_from_i64 : unit -> unit =
                cstring_from_i64' (fun _ _ s_fun () ->
                    let tag = (carray (YPrim CharT)).tag
                    line s_fun "static inline String * StringFromI64(int64_t value){"
                    let s_body = indent s_fun
                    line s_body "char buffer[24];"
                    line s_body "int length = snprintf(buffer, sizeof buffer, \"%lld\", (long long)value);"
                    line s_body $"String * result = ArrayCreate{tag}((uint32_t)length + 1, false);"
                    line s_body "memcpy(result->ptr, buffer, (size_t)length + 1);"
                    line s_body "return result;"
                    line s_fun "}"
                    )
            and cstring_from_u64 : unit -> unit =
                cstring_from_u64' (fun _ _ s_fun () ->
                    let tag = (carray (YPrim CharT)).tag
                    line s_fun "static inline String * StringFromU64(uint64_t value){"
                    let s_body = indent s_fun
                    line s_body "char buffer[24];"
                    line s_body "int length = snprintf(buffer, sizeof buffer, \"%llu\", (unsigned long long)value);"
                    line s_body $"String * result = ArrayCreate{tag}((uint32_t)length + 1, false);"
                    line s_body "memcpy(result->ptr, buffer, (size_t)length + 1);"
                    line s_body "return result;"
                    line s_fun "}"
                    )
            and cstring_from_bool : unit -> unit =
                cstring_from_bool' (fun _ _ s_fun () ->
                    line s_fun "static inline String * StringFromBool(bool value){"
                    line (indent s_fun) "return value ? StringLit(5, \"true\") : StringLit(6, \"false\");"
                    line s_fun "}"
                    )
            and cstring_from_char : unit -> unit =
                cstring_from_char' (fun _ _ s_fun () ->
                    let tag = (carray (YPrim CharT)).tag
                    line s_fun "static inline String * StringFromChar(char value){"
                    let s_body = indent s_fun
                    line s_body $"String * result = ArrayCreate{tag}(2, false);"
                    line s_body "result->ptr[0] = value;"
                    line s_body "result->ptr[1] = '\\0';"
                    line s_body "return result;"
                    line s_fun "}"
                    )

            match binds_last_dataC x |> data_term_vars |> term_vars_to_tysC with
            | [|YPrim Int32T|] ->
                import "stdbool.h"
                import "stdint.h"
                import "stdio.h"
                import "stdlib.h"

                let main_defs = {text=StringBuilder(); indent=0}
                import "string.h" // for memcpy

                line main_defs (sprintf "%s main(){" (prim Int32T))
                binds_start [||] (indent main_defs) x
                line main_defs "}"

                let program = StringBuilder()

                Seq.append globals env.globals |> Seq.distinct |> Seq.iter (fun x -> program.AppendLine(x) |> ignore)
                let generated = StringBuilder()
                fwd_dcls |> Seq.iter (fun x -> generated.Append(x) |> ignore)
                types |> Seq.iter (fun x -> generated.Append(x) |> ignore)
                functions |> Seq.iter (fun x -> generated.Append(x) |> ignore)
                program.Append(cStaticFunctions (generated.ToString()) |> cInlineSingleSiteLoops borrowed_loops (main_defs.text.ToString())).Append(main_defs.text).ToString() |> fuseCDeclarations
            | _ ->
                raise_codegen_error "The return type of main in the C backend should be a 32-bit int."

    /// ## CodegenCpp
    // Upstream: The Spiral Language 2/CodegenCpp.fs @ 0cb0fda0 (host_cpp_and_cuda_backend, v2.18.10). One shared
    // section for both cores. Every line that differs from upstream carries a `// ws:` comment saying why; the
    // differences are the workspace's types (records/union cases keyed by `int * string`, interned ids,
    // the PartEvalResult join point tables), reached through CodegenAdapter, plus a few bug fixes.
    module CodegenCpp =
        // ws: `open Spiral...` lines dropped: everything lives in the enclosing `spiral_compiler` module.
        open System.Collections.Generic

        type backend_args =
            | ArgsCudaDevice of args : L<int,Ty>[] * binds : TypedBind[] * backend_entry_name : string
            | ArgsCudaHost of args : L<int,Ty>[] * binds: TypedBind[] * backend_entry_name : string
            | ArgsCppHost of binds : TypedBind[] * backend_entry_name : string

        let private max_tag = 255uy

        let prim = function
            | Int8T -> "char"
            | Int16T -> "short"
            | Int32T -> "int"
            | Int64T -> "long long"
            | UInt8T -> "unsigned char"
            | UInt16T -> "unsigned short"
            | UInt32T -> "unsigned int"
            | UInt64T -> "unsigned long long"
            | Float32T -> "float"
            | Float64T -> "double"
            | BoolT -> "bool" // part of c++ standard
            | CharT -> "char"
            | StringT -> "const char *"

        /// Replaces the default types in the corelib.cuh library.
        let replace_default_types (default_env : DefaultEnv) (x : string) =
            let opts = System.Text.RegularExpressions.RegexOptions.Multiline // ws: System.Text is not opened here
            System.Text.RegularExpressions.Regex.Replace(x, @"(^using default_int = )(.*?)(;)", $"$1{prim default_env.default_int}$3", opts)
            |> fun x -> System.Text.RegularExpressions.Regex.Replace(x, @"(^using default_uint = )(.*?)(;)", $"$1{prim default_env.default_uint}$3", opts)

        let is_string = function DV(L(_,YPrim StringT)) | DLit(LitString _) -> true | _ -> false
        let sizeof_tyv = function
            | YPrim (Int64T | UInt64T | Float64T) -> 8
            | YPrim (Int32T | UInt32T | Float32T) -> 4
            | YPrim (Int16T | UInt16T) -> 2
            | YPrim (Int8T | UInt8T | CharT | BoolT) -> 1
            | _ -> 8
        let order_args v = v |> Array.sortWith (fun (L(_,t)) (L(_,t')) -> compare (sizeof_tyv t') (sizeof_tyv t))
        let line x s = if s <> "" then x.text.Append(' ', x.indent).AppendLine s |> ignore
        let line' x s = line x (String.concat " " s)

        type BindsReturn =
            | BindsTailEnd
            | BindsLocal of TyV []

        let term_vars_to_tys x = x |> Array.map (function WV(L(_,t)) -> t | WLit x -> YPrim (lit_to_primitive_type x))
        let binds_last_data x = x |> Array.last |> function TyLocalReturnData(x,_) | TyLocalReturnOp(_,_,x) -> x | TyLet _ -> raise_codegen_error "Compiler error: Cannot find the return data of the last bind."

        type LayoutRec = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>} // ws: record keys are `int * string`
        type UnionRec = {tag : int; free_vars : Map<int * string, TyV[]>; is_heap : bool} // ws: union cases are keyed `tag * name`
        type MethodRec = {tag : int; free_vars : TyV[]; range : Ty; body : TypedBind[]; name : string option; backend : backend_cpp}
        type ClosureRec = {tag : int; free_vars : TyV[]; domain : Ty; range : Ty; funtype : FunType; body : TypedBind[]; backend : backend_cpp}
        type TupleRec = {tag : int; tys : Ty []}
        type CFunRec = {tag : int; domain : Ty; range : Ty; funtype : FunType}
        type GlobalRec = {tag : int; text : string}
        type show_env =
            {
                globals : string_builder_env
                fwd_types : string_builder_env
                fwd_methods : string_builder_env
                fwd_main_defs : string_builder_env
                types : string_builder_env
                functions : string_builder_env
            }

        // ws: a record field by its name. Records are keyed `int * string` in the workspace (declaration order first),
        // and hopac compares interned field ids, so upstream's `m.[key]` / `Map.tryFind key m` go through these.
        let field_by_key key (m : Map<int * string, 'a>) = m |> Map.pick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None)
        let field_try_find (name : string) (m : Map<int * string, 'a>) = m |> Map.tryPick (fun (_, k) v -> if k = name then Some v else None)

        // Replaces the invalid symbols in Spiral method names for the C++ backend.
        let fix_method_name (x : string) = x.Replace(''','_') + "_"

        let unroll_pop (s : Stack<int>) = if s.Count > 0 then s.Pop() else -1
        let unroll_peek (s : Stack<int>) = if s.Count > 0 then s.Peek() else -1

        let lit_string x =
            let strb = StringBuilder(String.length x + 2)
            strb.Append '"' |> ignore
            String.iter (function
                | '"' -> strb.Append "\\\""
                | '\b' -> strb.Append @"\b"
                | '\t' -> strb.Append @"\t"
                | '\n' -> strb.Append @"\n"
                | '\r' -> strb.Append @"\r"
                | '\\' -> strb.Append @"\\"
                | x -> strb.Append x
                >> ignore
                ) x
            strb.Append '"' |> ignore
            strb.ToString()

        let codegen' backend_handler (part_eval_env : PartEvalResult) (code_env : backend_cpp -> codegen_env) =
            let mutable backend_ref = backend_cpp.CppHost
            let backend() = backend_ref
            let backend_group() =
                match backend_ref with
                | backend_cpp.CppHost -> backend_cpp.CppHost
                | backend_cpp.CudaHost -> backend_cpp.CudaHost
                | backend_cpp.CudaDevice -> backend_cpp.CudaHost // NVCC cannot see the types inside the #ifdef __CUDA_ARCH__
            /// Runs the closure with the new backend. Restores the old one after the backend has been executed.
            let inline substitute_backend_with backend f =
                let old_backend = backend_ref
                backend_ref <- backend
                f()
                backend_ref <- old_backend

            let print (show : show_env -> _ -> unit) r =
                let s_globals = {text=StringBuilder(); indent=0}
                let s_fwd_dcls_types = {text=StringBuilder(); indent=0}
                let s_fwd_dcls_methods = {text=StringBuilder(); indent=0}
                let s_fwd_dcls_main_defs = {text=StringBuilder(); indent=0}
                let s_typ = {text=StringBuilder(); indent=0}
                let s_fun = {text=StringBuilder(); indent=0}
                show {globals = s_globals; fwd_types = s_fwd_dcls_types; fwd_methods = s_fwd_dcls_methods; fwd_main_defs = s_fwd_dcls_main_defs; types = s_typ; functions = s_fun} r
                let f (a : string ResizeArray) (b : string_builder_env) =
                    let text = b.text.ToString()
                    if text <> "" then a.Add(text)
                let code_env = code_env (backend())
                f code_env.globals s_globals
                f code_env.fwd_dcls_types s_fwd_dcls_types
                f code_env.fwd_dcls_methods s_fwd_dcls_methods
                f code_env.fwd_dcls_main_defs s_fwd_dcls_main_defs
                f code_env.types s_typ
                f code_env.functions s_fun

            let layout show =
                let dict' = codegenMemoTable HashIdentity.Structural // ws: CodegenAdapter's table (hopac: concurrent)
                let dict = codegenMemoTable HashIdentity.Reference // ws: as above
                let f x : LayoutRec =
                    match x with
                    | YLayout(x,_) ->
                        let x = part_eval_env.ty_to_data x
                        let a, b =
                            match x with
                            | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                            | _ -> data_free_vars x, Map.empty
                        {data=x; free_vars=a; free_vars_by_key=b; tag=dict'.Count}
                    | _ -> raise_codegen_error $"Compiler error: Expected a layout type (1).\nGot: %s{show_ty x}"
                fun x ->
                    let r,dirty = Utils.memoize dict (Utils.memoize dict' (fun x -> f x, HashSet())) x
                    if dirty.Add (backend_group()) then print show r
                    r

            let union show =
                let dict = codegenMemoTable HashIdentity.Reference // ws: CodegenAdapter's table
                let f (a : Union) : UnionRec =
                    let free_vars = a.Item.cases |> Map.map (fun _ -> part_eval_env.ty_to_data >> data_free_vars)
                    {free_vars=free_vars; tag=dict.Count; is_heap=a.Item.layout = UHeap}
                fun x ->
                    let r,dirty = Utils.memoize dict (fun x -> f x, HashSet()) x
                    if dirty.Add (backend_group()) then print show r
                    r

            let jp_method f show =
                let dict = codegenMemoTable HashIdentity.Structural // ws: CodegenAdapter's table
                let f x = f (x, dict.Count) : MethodRec
                fun x ->
                    let r,dirty = Utils.memoize dict (fun x -> f x, HashSet()) (x, backend())
                    if dirty.Add (backend_group()) then print show r
                    r

            let jp_closure f show =
                let dict = codegenMemoTable HashIdentity.Structural // ws: CodegenAdapter's table
                let f x = f (x, dict.Count) : ClosureRec
                fun x ->
                    let r,dirty = Utils.memoize dict (fun x -> f x, HashSet()) (x, backend())
                    if dirty.Add (backend_group()) then print show r
                    r

            let tuple show =
                let dict = codegenMemoTable HashIdentity.Structural // ws: CodegenAdapter's table
                let f x = {tag=dict.Count; tys=x}
                fun x ->
                    let r,dirty = Utils.memoize dict (fun x -> f x, HashSet()) x
                    if dirty.Add (backend_group()) then print show r
                    r

            let cfun' show =
                let dict = codegenMemoTable HashIdentity.Structural // ws: CodegenAdapter's table
                let f (a : Ty, b : Ty, t : FunType) = {tag=dict.Count; domain=a; range=b; funtype=t}
                fun x ->
                    let r,dirty = Utils.memoize dict (fun x -> f x, HashSet()) x
                    if dirty.Add (backend_group()) then print show r
                    r

            let global' =
                let dict = codegenMemoTable HashIdentity.Structural // ws: CodegenAdapter's table
                let show (s : show_env) (x : GlobalRec) = line s.globals x.text
                let f x = {tag = dict.Count; text = x}
                fun x ->
                    // ws: a multi-line global arrives as fragments whose continuation lines (indented, or `}`) repeat
                    // across globals; deduplicating them cut lines out of later blocks (CodegenUtils).
                    if preservesDuplicateGlobalFragment x then
                        let r = f x
                        print show r
                        r
                    else
                        let r,dirty = Utils.memoize dict (fun x -> f x, HashSet()) x
                        if dirty.Add (backend_group()) then print show r
                        r

            let args x = x |> Array.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "

            let tmp =
                let mutable i = 0u
                fun () -> let x = i in i <- i + 1u; x


            let import x = global' $"#include <%s{x}>"
            let import' x = global' $"#include \"%s{x}\""

            let tyvs_to_tys (x : TyV []) = Array.map (fun (L(i,t)) -> t) x

            let rec binds_start (s : string_builder_env) (x : TypedBind []) = binds (Stack()) s BindsTailEnd x
            and return_local s ret (x : string) =
                match ret with
                | [||] -> line s $"{x};"
                | [|L(i,_)|] -> line s $"v{i} = {x};"
                | ret ->
                    let tmp_i = tmp()
                    line s $"{tup_ty_tyvs ret} tmp{tmp_i} = {x};"
                    Array.mapi (fun i (L(i',_)) -> $"v{i'} = tmp{tmp_i}.v{i};") ret |> line' s
            and get_layout_rec lay a =
                match lay with
                | Heap -> heap a
                | HeapMutable -> mut a
                | StackMutable -> stack_mut a
                | StackRefs -> stack_refs a
                | HeapRefs -> heap_refs a
            and binds (unroll : Stack<int>) (s : string_builder_env) (ret : BindsReturn) (stmts : TypedBind []) =
                let tup_destruct (a,b) =
                    Array.map2 (fun (L(i,_)) b ->
                        match b with
                        | WLit b -> $"v{i} = {lit b};"
                        | WV (L(i',_)) -> $"v{i} = v{i'};"
                        ) a b
                Array.forall (fun x ->
                    match x with
                    | TyLet(d,trace,a) ->
                        try let d = data_free_vars d
                            let decl_vars () = Array.map (fun (L(i,t)) -> $"{tyv t} v{i};") d
                            let layout_index layout (x'_i : int) (x' : TyV []) =
                                match layout with
                                | Heap | HeapMutable -> Array.map2 (fun (L(i,t)) (L(i',_)) -> $"{tyv t} v{i} = v{x'_i}.base->v{i'};") d x' |> line' s
                                | StackMutable -> Array.map2 (fun (L(i,t)) (L(i',_)) -> $"{tyv t} v{i} = v{x'_i}.v{i'};") d x' |> line' s
                                | HeapRefs -> Array.map2 (fun (L(i,t)) (L(i',_)) -> $"{tyv t} & v{i} = v{x'_i}.base->v{i'};") d x' |> line' s
                                | StackRefs -> Array.map2 (fun (L(i,t)) (L(i',_)) -> $"{tyv t} & v{i} = v{x'_i}.v{i'};") d x' |> line' s
                            match a with
                            | TyToLayout(a,YLayout(_,(StackMutable | StackRefs)) & b) ->
                                match d with
                                | [|L(i,YLayout(_,StackMutable))|] -> // For the regular arrays.
                                    let tag = (stack_mut b).tag
                                    line s $"StackMut{tag} v{i}{{{args' a}}};"
                                    true
                                | [|L(i,YLayout(_,StackRefs))|] -> // For the regular arrays.
                                    let tag = (stack_refs b).tag
                                    line s $"StackRefs{tag} v{i}{{{args' a}}};"
                                    true
                                | _ ->
                                    raise_codegen_error "Compiler error: Expected a stack mutable or a stack refs layout type."
                            | TyLayoutIndexAll(x) ->
                                match x with
                                | L(i,YLayout(_,lay) & a) -> (get_layout_rec lay a).free_vars |> layout_index lay i
                                | _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
                                true
                            | TyLayoutIndexByKey(x,key) ->
                                match x with
                                | L(i,YLayout(_,lay) & a) -> (get_layout_rec lay a).free_vars_by_key |> field_by_key key |> layout_index lay i // ws: field_by_key
                                | _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index by key to be a layout type."
                                true
                            | TyMacro a ->
                                let m = a |> List.map (function CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup_data x) | CMType x -> tup_ty x | CMTypeLit x -> type_lit x) |> String.concat ""
                                if m.StartsWith("#pragma") then
                                    line s m
                                    true
                                elif m = "break" then
                                    line s "break;"
                                    false
                                elif m.StartsWith("return") then
                                    line s $"{m};"
                                    false
                                else
                                    let q = m.Split("\\v")
                                    if q.Length = 1 then
                                        decl_vars() |> line' s
                                        return_local s d m
                                        true
                                    else
                                        if d.Length = q.Length-1 then
                                            let w = StringBuilder(m.Length+8)
                                            let tag (L(i,_)) = i : int
                                            Array.iteri (fun i v -> w.Append(q.[i]).Append('v').Append(tag v) |> ignore) d
                                            w.Append(q.[d.Length]).Append(';').ToString() |> line s
                                            true
                                        else
                                            raise_codegen_error "The special \\v macro requires the same number of free vars in its binding as there are \\v in the code."
                            | TyArrayLiteral(a,b') ->
                                let inits = List.map tup_data b' |> String.concat ","
                                match d with
                                | [|L(i,YArray t)|] -> // For the regular arrays.
                                    line s $"%s{tup_ty t} v{i}[] = {{%s{inits}}};"
                                    true
                                | _ ->
                                    raise_codegen_error "Compiler error: Expected a single variable on the left side of an array literal op."
                            | TyArrayCreate(a,b) ->
                                match d with
                                | [|L(i,YArray t)|] ->
                                    match tup_ty t with
                                    | "void" -> line s "/* void array create */"
                                    | t -> line s $"{t} v{i}[{tup_data b}];"
                                    true
                                | _ -> raise_codegen_error "Compiler error: Expected a single variable on the left side of an array create op."
                            | TyJoinPoint(JPClosure(a,b),b') ->
                                match d with
                                | [|L(i,_)|] ->
                                    let x = closure (a,b)
                                    match x.funtype with
                                    | FT_Pointer ->
                                        let y = cfun (x.domain,x.range,x.funtype)
                                        line s $"Fun{y.tag} v{i} = FunPointerMethod{x.tag};"
                                    | FT_Vanilla ->
                                        let args = args b'
                                        line s $"Closure{x.tag} v{i}{{{args}}};"
                                    | FT_Closure ->
                                        let y = cfun (x.domain,x.range,x.funtype)
                                        let args = args b'
                                        line s $"Fun{y.tag} v{i}{{new Closure{x.tag}{{{args}}}}};"
                                    true
                                | _ -> raise_codegen_error "Compiler error: Expected a single variable on the left side of a closure join point."
                            | _ ->
                                decl_vars() |> line' s
                                op unroll s (BindsLocal d) a
                                true
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    | TyLocalReturnOp(trace,a,_) ->
                        try op unroll s ret a
                            true
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    | TyLocalReturnData(d,trace) ->
                        try match ret with
                            | BindsLocal l -> line' s (tup_destruct (l,data_term_vars d))
                            | BindsTailEnd -> line s $"return {tup_data d};"
                            true
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0, e.Data1)
                    ) stmts
                |> ignore
            and show_w = function WV(L(i,_)) -> sprintf "v%i" i | WLit a -> lit a
            and args' b = data_term_vars b |> Array.map show_w |> String.concat ", "
            and tup_term_vars x =
                let args = Array.map show_w x |> String.concat ", "
                if 1 < x.Length then sprintf "Tuple%i{%s}" (tup (term_vars_to_tys x)).tag args else args
            and tup_data x = tup_term_vars (data_term_vars x)
            and tup_ty_tys = function
                | [||] -> "void"
                | [|x|] -> tyv x
                | x -> sprintf "Tuple%i" (tup x).tag
            and tup_ty_tyvs (x : TyV []) = tup_ty_tys (tyvs_to_tys x)
            and tup_ty x = part_eval_env.ty_to_data x |> data_free_vars |> tup_ty_tyvs
            and tyv = function
                | YUnion a ->
                    match a.Item.layout with
                    | UStack -> sprintf "Union%i" (unions a).tag
                    | UHeap -> sprintf "sptr<Union%i>" (unions a).tag
                | YLayout(_,lay) as a ->
                    match lay with
                    | Heap -> sprintf "sptr<Heap%i>" (heap a).tag
                    | HeapMutable -> sprintf "sptr<Mut%i>" (mut a).tag
                    | HeapRefs -> sprintf "sptr<HeapRefs%i>" (heap_refs a).tag
                    | StackMutable -> sprintf "StackMut%i &" (stack_mut a).tag
                    | StackRefs -> sprintf "StackRefs%i &" (stack_refs a).tag
                | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                    match field_try_find "Cpp" r with // ws: field_try_find (records keyed `int * string`)
                    | Some x -> tup_ty x
                    | None -> raise_codegen_error $"In the type backend_switch, expected a record with the 'Cpp' field."
                | YMacro a ->
                    a
                    |> List.map (function
                        | Text a ->
                            match a.Split " @ "  with
                            | [|a|] -> a
                            | [|a;b|] -> global' b |> ignore; a
                            | _ -> raise_codegen_error $"Encountered a malformed type macro. Got: {a}"
                        | Type a -> tup_ty a
                        | TypeLit a -> type_lit a
                        )
                    |> String.concat ""
                | YPrim a -> prim a
                | YArray a -> $"{tup_ty a} *"
                | YFun(a,b,t) -> $"Fun%i{(cfun (a,b,t)).tag}"
                | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
                | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
                | a -> raise_codegen_error (sprintf "Compiler error: Type not supported in the codegen.\nGot: %A" a)
            and lit = function
                | LitInt8 x -> sprintf "%i" x
                | LitInt16 x -> sprintf "%i" x
                | LitInt32 x -> sprintf "%i" x
                | LitInt64 x -> sprintf "%ill" x
                | LitUInt8 x -> sprintf "%iu" x
                | LitUInt16 x -> sprintf "%iu" x
                | LitUInt32 x -> sprintf "%iu" x
                | LitUInt64 x -> sprintf "%iull" x
                | LitFloat32 x ->
                    if x = infinityf then "1.0f / 0.0f"
                    elif x = -infinityf then "-1.0f / 0.0f"
                    elif Single.IsNaN x then "0.0f / 0.0f"
                    else x.ToString("R") |> add_dec_point |> sprintf "%sf"
                | LitFloat64 x ->
                    if x = infinity then "1.0 / 0.0"
                    elif x = -infinity then "-1.0 / 0.0"
                    elif Double.IsNaN x then "0.0 / 0.0"
                    else x.ToString("R") |> add_dec_point
                | LitString x -> lit_string x
                | LitChar x ->
                    match x with
                    | '\b' -> @"\b"
                    | '\n' -> @"\n"
                    | '\t' -> @"\t"
                    | '\r' -> @"\r"
                    | '\\' -> @"\\"
                    | '\'' -> @"\'" // ws: upstream printed ''' (a C++ syntax error)
                    | '\000' -> @"\0"
                    | x -> string x
                    |> sprintf "'%s'"
                | LitBool x -> if x then "true" else "false" // true and false are defined in stddef.h
            and type_lit = function
                | YLit x -> lit x
                | YSymbol x -> x
                | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."
            and op (unroll : Stack<int>)s (ret : BindsReturn) a =
                let binds a b = binds unroll a b
                let return' (x : string) =
                    match ret with
                    | BindsLocal ret -> return_local s ret x
                    | BindsTailEnd -> line s $"return {x};"
                let jp (a,b') =
                    let args = args b'
                    match a with
                    | JPMethod(a,b) ->
                        let x = method (a,b)
                        let method_name = Option.defaultValue "method_" x.name
                        $"{method_name}{x.tag}({args})"
                    | JPClosure(a,b) ->
                        let x = closure (a,b)
                        match x.funtype with
                        | FT_Vanilla -> raise_codegen_error "Compiler error: The vanilla function case should have been blocked elsewhere."
                        | FT_Pointer -> $"FunPointerMethod{x.tag}"
                        | FT_Closure -> $"csptr<ClosureBase{x.tag}>{{new Closure{x.tag}{{{args}}}}}"
                match a with
                | TyMacro _ -> raise_codegen_error "Macros are supposed to be taken care of in the `binds` function."
                | TyIf(cond,tr,fl) ->
                    line s (sprintf "if (%s){" (tup_data cond))
                    binds (indent s) ret tr
                    line s "} else {"
                    binds (indent s) ret fl
                    line s "}"
                | TyJoinPoint(a,args) -> return' (jp (a, args))
                | TyBackend(a,b,c) -> line s $"auto kernel = {backend_handler (a,b,c) (backend())};"
                | TyWhile(a,b) ->
                    let cond =
                        match a with
                        | JPMethod(a,b),b' -> sprintf "while_method_%i(%s)" (method_while (a,b)).tag (args b')
                        | _ -> raise_codegen_error "Expected a regular method rather than closure create in the while conditional."
                    match unroll_peek unroll with
                    | -1 -> ()
                    | 0 -> line s $"#pragma unroll"
                    | i -> line s $"#pragma unroll %i{i}"
                    line s (sprintf "while (%s){" cond)
                    binds (indent s) (BindsLocal [||]) b
                    line s "}"
                | TyDo a | TyIndent a -> binds s ret a // ws: workspace-only ops (`!!!!Do`/`!!!!Indent`), inlined as in CodegenC
                | TyIntSwitch(L(v_i,_),on_succ,on_fail) ->
                    line s (sprintf "switch (v%i) {" v_i)
                    let _ =
                        let s = indent s
                        Array.iteri (fun i x ->
                            line s (sprintf "case %i: {" i)
                            binds (indent s) ret x
                            line (indent s) "break;"
                            line s "}"
                            ) on_succ
                        line s "default: {"
                        binds (indent s) ret on_fail
                        line s "}"
                    line s "}"
                | TyUnionUnbox(is,x,on_succs,on_fail) ->
                    let case_tags = x.Item.tags
                    let acs = match x.Item.layout with UHeap -> ".base->" | UStack -> "."
                    let head = List.head is |> fun (L(i,_)) -> $"v{i}{acs}tag"
                    List.pairwise is
                    |> List.map (fun (L(i,_), L(i',_)) -> $"v{i}{acs}tag == v{i'}{acs}tag")
                    |> String.concat " && "
                    |> function "" -> head | x -> $"{x} ? {head} : {max_tag}"
                    |> sprintf "switch (%s) {" |> line s
                    let _ =
                        let s = indent s
                        Map.iter (fun k (a,b) ->
                            let union_i = case_tags.[k]
                            line s (sprintf "case %i: { // %s" union_i (UnionTagIdOps.text k)) // ws: the workspace's tags are interned ids
                            List.iter2 (fun (L(data_i,_)) a ->
                                let a, s = data_free_vars a, indent s
                                let qs = ResizeArray(a.Length)
                                Array.iteri (fun field_i (L(v_i,t) as v) ->
                                    qs.Add $"{tyv t} v{v_i} = v{data_i}{acs}case{union_i}.v{field_i};"
                                    ) a
                                line' s qs
                                ) is a
                            binds (indent s) ret b
                            line (indent s) "break;"
                            line s "}"
                            ) on_succs
                        line s "default: {"
                        let _ =
                            let s = indent s
                            match on_fail with
                            | Some b -> binds s ret b
                            | None ->
                                line s "assert(\"Invalid tag.\" && false);"
                                match backend() with
                                | backend_cpp.CppHost | backend_cpp.CudaHost -> line s "exit(-1);"
                                | backend_cpp.CudaDevice -> line s "__trap();"
                        line s "}"
                    line s "}"
                | TyUnionBox(a,b,c') ->
                    let c = c'.Item
                    let i = c.tags.[a]
                    let vars = args' b
                    let u = unions c'
                    let tag = u.tag
                    let case_ty = generatedCaseNameOfTag $"Union{tag}" u.free_vars i
                    match c.layout with
                    | UHeap -> $"sptr<Union{tag}>{{new Union{tag}{{{case_ty}{{{vars}}}}}}}"
                    | UStack -> $"Union{tag}{{{case_ty}{{{vars}}}}}"
                    |> return'
                | TyToLayout(a,b) ->
                    match b with
                    | YLayout(_,layout) ->
                        match layout with
                        | Heap ->
                            let tag = (heap b).tag
                            $"sptr<Heap{tag}>{{new Heap{tag}{{{args' a}}}}}"
                        | HeapMutable ->
                            let tag = (mut b).tag
                            $"sptr<Mut{tag}>{{new Mut{tag}{{{args' a}}}}}"
                        | HeapRefs ->
                            let tag = (heap_refs b).tag
                            $"sptr<HeapRefs{tag}>{{new HeapRefs{tag}{{{args' a}}}}}"
                        | StackMutable -> raise_codegen_error "Compiler error: The Cuda backend handles stack mutable layout types as statements and they should never be generated as expressions."
                        | StackRefs -> raise_codegen_error "Compiler error: The Cuda backend handles stack refs layout types as statements and they should never be generated as expressions."
                    | _ -> raise_codegen_error "Compiler error: Expected a layout type (2)."
                    |> return'
                | TyLayoutIndexAll(x) -> raise_codegen_error "Compiler error: TyLayoutIndexAll should have been taken care of in TyLet."
                | TyLayoutIndexByKey(x,key) -> raise_codegen_error "Compiler error: TyLayoutIndexByKey should have been taken care of in TyLet."
                | TyLayoutMutableSet(L(i,t),b,c) ->
                    match t with
                    | YLayout(_,lay) ->
                        let heap is_refs =
                            let a = List.fold (fun s k -> match s with DRecord l -> field_by_key k l | _ -> raise_codegen_error "Compiler error: Expected a record.") (if is_refs then heap_refs t else mut t).data b // ws: field_by_key
                            Array.map2 (fun (L(i',_)) b -> $"v{i}.base->v{i'} = {show_w b};") (data_free_vars a) (data_term_vars c)
                        let stack is_refs =
                            let a = List.fold (fun s k -> match s with DRecord l -> field_by_key k l | _ -> raise_codegen_error "Compiler error: Expected a record.") (if is_refs then stack_refs t else stack_mut t).data b // ws: field_by_key
                            Array.map2 (fun (L(i',_)) b -> $"v{i}.v{i'} = {show_w b};") (data_free_vars a) (data_term_vars c)
                        match lay with
                        | HeapMutable -> heap false
                        | HeapRefs -> heap true
                        | StackMutable -> stack false
                        | StackRefs -> stack true
                        | Heap -> raise_codegen_error "Compiler error (1): TyLayoutMutableSet should only be HeapMutable, StackMutable, HeapRefs and StackRefs."
                    | _ -> raise_codegen_error "Compiler error (2): TyLayoutMutableSet should only be HeapMutable or StackMutable."
                    |> String.concat " " |> line s
                | TyArrayLiteral(a,b') -> raise_codegen_error "Compiler error: TyArrayLiteral should have been taken care of in TyLet."
                | TyArrayCreate(a,b) ->  raise_codegen_error "Compiler error: TyArrayCreate should have been taken care of in TyLet."
                | TyFailwith(a,b) ->
                    let string_in_op = function
                        | DLit (LitString b) -> lit_string b
                        | DV(L(_, YPrim StringT)) as b -> tup_data b
                        | _ -> raise_codegen_error "In the Cuda backend, the exception message must be a string."
                    let fmt = @"%s\n"
                    line s $"printf(\"{fmt}\", {string_in_op b});"
                    match backend() with
                    | backend_cpp.CppHost | backend_cpp.CudaHost -> line s "exit(-1);"
                    | backend_cpp.CudaDevice -> line s "__trap();"
                | TyConv(a,b) -> return' $"({tyv a}){tup_data b}"
                | TyApply(L(i,_),b) ->
                    let rec loop = function
                        | DPair(a,b) -> tup_data a :: loop b
                        | a -> [tup_data a]
                    let args = loop b |> List.filter ((<>) "") |> String.concat ", "
                    $"v{i}({args})" |> return'
                | TyArrayLength(_,b) ->
                    // ws: upstream returns `{array}.size()` on the host backends, but arrays are bare `T *` there too, so
                    // the C++ did not compile (cpp_checks t_array_length). Report it at codegen time on every backend.
                    raise_codegen_error "Array length is not supported in the Cuda C++ backend as they are bare pointers."
                | TyStringLength(_,b) -> raise_codegen_error "String length is not supported in the Cuda C++ backend."
                | TySizeOf t -> return' $"sizeof({tup_ty t})"
                | TyOp(Global,[DLit (LitString x)]) -> global' x |> ignore
                | TyOp(PragmaUnrollPush,[DLit (LitInt32 x)]) -> unroll.Push(x); line s $"// Pushing the loop unrolling to: {x}"
                | TyOp(PragmaUnrollPop,[]) -> line s $"// Poping the loop unrolling to: {unroll_pop unroll}"
                | TyOp(op,l) ->
                    match op, l with
                    | Dyn,[a] -> tup_data a
                    | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                    | StringIndex, [a;b] -> sprintf "%s[%s]" (tup_data a) (tup_data b)
                    | StringSlice, [a;b;c] -> raise_codegen_error "String slice is not supported natively in the C++ backend. Use a library implementation instead."
                    | ArrayIndex, [DV(L(_,YArray t)) & a;b] ->
                        match tup_ty t with
                        | "void" -> "/* void array index */"
                        | _ -> sprintf "%s[%s]" (tup_data a) (tup_data b)
                    | ArrayIndexSet, [DV(L(_,YArray t)) as a;b;c] ->
                        let a',b',c' = tup_data a, tup_data b, tup_data c
                        match c' with
                        | "" -> "/* void array set */"
                        | _ -> $"{a'}[{b'}] = {c'}"
                    // Math
                    | Add, [a;b] -> sprintf "%s + %s" (tup_data a) (tup_data b)
                    | Sub, [a;b] -> sprintf "%s - %s" (tup_data a) (tup_data b)
                    | Mult, [a;b] -> sprintf "%s * %s" (tup_data a) (tup_data b)
                    | Div, [a;b] -> sprintf "%s / %s" (tup_data a) (tup_data b)
                    | Mod, [(DV(L(_,YPrim (Float32T | Float64T))) | DLit(LitFloat32 _ | LitFloat64 _)) & a;b] -> import "cmath"; sprintf "fmod(%s, %s)" (tup_data a) (tup_data b)
                    | Mod, [a;b] -> sprintf "%s %% %s" (tup_data a) (tup_data b)
                    | Pow, [a;b] -> sprintf "pow(%s,%s)" (tup_data a) (tup_data b)
                    | LT, [a;b] -> sprintf "%s < %s" (tup_data a) (tup_data b)
                    | LTE, [a;b] -> sprintf "%s <= %s" (tup_data a) (tup_data b)
                    | EQ, [a;b] | NEQ, [a;b] | GT, [a;b] | GTE, [a;b] when is_string a -> raise_codegen_error "String comparison operations are not supported in the Cuda C++ backend."
                    | EQ, [a;b] -> sprintf "%s == %s" (tup_data a) (tup_data b)
                    | NEQ, [a;b] -> sprintf "%s != %s" (tup_data a) (tup_data b)
                    | GT, [a;b] -> sprintf "%s > %s" (tup_data a) (tup_data b)
                    | GTE, [a;b] -> sprintf "%s >= %s" (tup_data a) (tup_data b)
                    | BoolAnd, [a;b] -> sprintf "%s && %s" (tup_data a) (tup_data b)
                    | BoolOr, [a;b] -> sprintf "%s || %s" (tup_data a) (tup_data b)
                    | BitwiseAnd, [a;b] -> sprintf "%s & %s" (tup_data a) (tup_data b)
                    | BitwiseOr, [a;b] -> sprintf "%s | %s" (tup_data a) (tup_data b)
                    | BitwiseXor, [a;b] -> sprintf "%s ^ %s" (tup_data a) (tup_data b)
                    | BitwiseComplement, [a] -> sprintf "~%s" (tup_data a)

                    | ShiftLeft, [a;b] -> sprintf "%s << %s" (tup_data a) (tup_data b)
                    | ShiftRight, [a;b] -> sprintf "%s >> %s" (tup_data a) (tup_data b)

                    | Neg, [x] -> sprintf "-%s" (tup_data x)
                    | Log, [x] -> sprintf "log(%s)" (tup_data x)
                    | Exp, [x] -> sprintf "exp(%s)" (tup_data x)
                    | Tanh, [x] -> sprintf "tanh(%s)" (tup_data x)
                    | Sqrt, [x] -> sprintf "sqrt(%s)" (tup_data x)
                    | Sin, [x] -> sprintf "sin(%s)" (tup_data x)
                    | Cos, [x] -> sprintf "cos(%s)" (tup_data x)
                    | NanIs, [x] -> sprintf "isnan(%s)" (tup_data x)
                    // ws: workspace-only ops (portable flush and delay, see the C backend).
                    | StdoutFlush, [] -> import "cstdio" |> ignore; "std::fflush(stdout)"
                    | MonotonicDelayMs, [duration] -> import "thread" |> ignore; import "chrono" |> ignore; sprintf "std::this_thread::sleep_for(std::chrono::milliseconds(%s))" (tup_data duration)
                    | Printf, [fmt;str] ->
                        match args' str with
                        | "" -> sprintf "printf(%s)" (tup_data fmt)
                        | str -> sprintf "printf(%s,%s)" (tup_data fmt) str
                    | UnionTag, [DV(L(i,YUnion l)) as x] ->
                        match l.Item.layout with
                        | UHeap -> ".base->tag"
                        | UStack -> ".tag"
                        |> sprintf "v%i%s" i
                    | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported" op l.Length
                    |> return'
            and print_ordered_args' s (type_suffix : string) v = // Unlike C# for example, C keeps the struct fields in input order. To reduce padding, it is best to order the fields from largest to smallest.
                order_args v |> Array.iter (fun (L(i,x)) -> line s $"{tyv x}{type_suffix} v{i};")
            and print_ordered_args s v = print_ordered_args' s "" v
            and method_template is_while : _ -> MethodRec =
                jp_method (fun (((jp_body,key),backend : backend_cpp),i) -> // ws: the key's shape differs per core
                    let a, range, name = codegenMethodBody part_eval_env backend.Name jp_body key // ws: CodegenAdapter (raises on a malformed table)
                    {tag=i; free_vars=rdata_free_vars (codegenMethodKeyArgs key); range=range; body=a; name=Option.map fix_method_name name; backend=backend}
                    ) (fun s (x : MethodRec) ->
                    let ret_ty = tup_ty x.range
                    let fun_name = Option.defaultValue (if is_while then "while_method_" else "method_") x.name
                    let args = x.free_vars |> Array.mapi (fun i (L(_,x)) -> $"{tyv x} v{i}") |> String.concat ", "
                    let __device__ =
                        match x.backend with
                        | backend_cpp.CppHost | backend_cpp.CudaHost -> ""
                        | backend_cpp.CudaDevice -> "__device__ "
                    let inline_ =
                        if is_while then
                            // ws: closure classes are printed into the .hpp ahead of every method body, so a closure whose
                            // body has a `while` loop needs this declaration (cpp_checks t_closure_while; upstream: none).
                            line s.fwd_methods $"{__device__}inline {ret_ty} {fun_name}{x.tag}({args});"
                            "inline "
                        else
                            line s.fwd_methods $"{__device__}{ret_ty} {fun_name}{x.tag}({args});"
                            if fun_name.StartsWith "noinline" then "__noinline__ " else ""
                    line s.functions $"{__device__}{inline_}{ret_ty} {fun_name}{x.tag}({args}){{"
                    binds_start (indent s.functions) x.body
                    line s.functions "}"
                    )
            and method : _ -> MethodRec = method_template false
            and method_while : _ -> MethodRec = method_template true
            and closure_args domain count_start =
                let rec loop = function
                    | YPair(a,b) -> a :: loop b
                    | a -> [a]
                let mutable count = count_start
                let rename x = Array.map (fun (L(i,t)) -> let x = L(count,t) in count <- count+1; x) x
                let mutable i = 0
                loop domain |> List.choose (fun x ->
                    let n = part_eval_env.ty_to_data x |> data_free_vars
                    let x = if n.Length <> 0 then Some(i, tup_ty_tyvs n, n |> rename) else None
                    i <- i+1
                    x
                    )
            and closure : _ -> ClosureRec =
                jp_closure (fun (((jp_body,key & (C(args,_,fun_ty))),backend : backend_cpp),i) ->
                    match fun_ty with
                    | YFun(domain,range,t) ->
                        let _, body, _ = codegenClosureBody part_eval_env backend.Name jp_body key // ws: CodegenAdapter (raises on a malformed table)
                        {tag=i; domain=domain; range=range; body=body; free_vars=rdata_free_vars args; funtype=t; backend=backend}
                    | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."
                    ) (fun s (x : ClosureRec) ->
                    let i, range = x.tag, tup_ty x.range
                    let closure_args = closure_args x.domain x.free_vars.Length
                    let args = closure_args |> List.map (fun (i,ty,_) -> $"{ty} tup{i}") |> String.concat ", "
                    let print_body s_fun =
                        let s_fun = indent s_fun
                        x.free_vars |> Array.map (fun (L(i,t)) ->
                            $"{tyv t} & v{i} = this->v{i};"
                            ) |> String.concat " " |> line s_fun
                        closure_args |> List.map (fun (i'',_,vars) ->
                            Array.mapi (fun i' (L(i,t)) ->
                                if vars.Length <> 1 then $"{tyv t} v{i} = tup{i''}.v{i'};"
                                else $"{tyv t} v{i} = tup{i''};"
                                ) vars
                            |> String.concat " "
                            ) |> String.concat " " |> line s_fun
                        binds_start s_fun x.body
                    let __device__ =
                        match x.backend with
                        | backend_cpp.CppHost | backend_cpp.CudaHost -> ""
                        | backend_cpp.CudaDevice -> "__device__ "
                    match x.funtype with
                    | FT_Pointer ->
                        line s.fwd_methods $"{__device__}{range} FunPointerMethod{i}({args});" // ws: as for while methods, closure classes in the .hpp may take its address
                        line s.functions $"{__device__}{range} FunPointerMethod{i}({args}){{"
                        print_body s.functions
                        line s.functions "}"
                    | FT_Vanilla | FT_Closure ->
                        match x.funtype with
                        | FT_Pointer -> raise_codegen_error "Compiler error: The pointer case have been taken care of (1)."
                        | FT_Closure ->
                            let i' = (cfun (x.domain,x.range,x.funtype)).tag
                            line s.types $"struct Closure{i} : public ClosureBase{i'} {{"
                        | FT_Vanilla ->
                            line s.types $"struct Closure{i} {{"
                        let () =
                            let s_typ = indent s.types
                            let () = // free vars in the environment
                                print_ordered_args s_typ x.free_vars
                            let () = // operator()
                                match x.funtype with
                                | FT_Pointer -> raise_codegen_error "Compiler error: The pointer case have been taken care of (2)."
                                | FT_Vanilla -> line s_typ $"{__device__}{range} operator()({args}){{"
                                | FT_Closure -> line s_typ $"{__device__}{range} operator()({args}) override {{"
                                print_body s_typ
                                line s_typ "}"
                            let () = // constructor
                                match x.free_vars with
                                | [||] -> ()
                                | _ ->
                                    let constructor_args =
                                        x.free_vars
                                        |> Array.map (fun (L(i,t)) -> $"{tyv t} _v{i}")
                                        |> String.concat ", "
                                    let initializer_args =
                                        x.free_vars
                                        |> Array.map (fun (L(i,t)) -> $"v{i}(_v{i})")
                                        |> String.concat ", "
                                    line s_typ $"{__device__}Closure{i}({constructor_args}) : {initializer_args} {{ }}"
                            let () = // destructor
                                match x.funtype with
                                | FT_Pointer | FT_Vanilla -> ()
                                | FT_Closure ->
                                    // ws: no `destroy(vN);` calls. The fields' own destructors run right after this body, so
                                    // upstream's explicit calls released each captured sptr twice and freed objects that were
                                    // still referenced (cpp_checks t_closure; g++ -O1 drops the `base = nullptr` store).
                                    line s_typ $"{__device__}~Closure{i}() override {{ }}"
                            ()
                        line s.types "};"
                    )
            and cfun : _ -> CFunRec =
                cfun' (fun s x ->
                    let i, range = x.tag, tup_ty x.range
                    let domain_args_ty = closure_args x.domain 0 |> List.map (fun (_,ty,_) -> ty) |> String.concat ", "
                    match x.funtype with
                    | FT_Vanilla -> raise_codegen_error "Regular functions do not have a composable type in the Cuda backend. Consider explicitly converting them to either closures or pointers using `to_closure` or `to_fptr` if you want to pass them through boundaries."
                    | FT_Pointer -> line s.fwd_types $"typedef {range} (* Fun{i})({domain_args_ty});"
                    | FT_Closure ->
                        line s.fwd_types $"struct ClosureBase{i} {{ int refc{{0}}; __host__ __device__ virtual {range} operator()({domain_args_ty}) = 0; __host__ __device__ virtual ~ClosureBase{i}(){{}}; }};" // ws: upstream wrote `host __device__ virtual ~ClosureBase` (does not compile)
                        line s.fwd_types $"typedef csptr<ClosureBase{i}> Fun{i};"
                    )
            and tup : _ -> TupleRec =
                tuple (fun s x ->
                    let name = sprintf "Tuple%i" x.tag
                    line s.fwd_types $"struct {name};"
                    line s.types $"struct {name} {{"
                    x.tys |> Array.mapi (fun i x -> L(i,x)) |> print_ordered_args (indent s.types)
                    let concat x = String.concat ", " x
                    let args = x.tys |> Array.mapi (fun i x -> $"{tyv x} t{i}")
                    let con_init = x.tys |> Array.mapi (fun i x -> $"v{i}(t{i})")
                    if args.Length <> 0 then
                        line (indent s.types) $"__host__ __device__ {name}() = default;"
                        line (indent s.types) $"__host__ __device__ {name}({concat args}) : {concat con_init} {{}}"
                    line s.types "};"
                    )
            and unions : _ -> UnionRec =
                // ws: `k` is the case's `tag * name` key; its tag equals the iteration index, so the numbering below is
                // the peval's tag. The comments print the name only (`snd k`), as upstream does.
                // a case's tag is its key's (a GADT-indexed union keeps only its inhabited cases, so a position is not a tag)
                let inline map_iteri f x = Map.iter (fun ((tag : int, _) as k) v -> f tag k v) x
                union (fun s x ->
                    let i = x.tag
                    let case_ty (tag : int) = generatedCaseNameOfTag $"Union{i}" x.free_vars tag
                    line s.fwd_types $"struct Union{i};" // Forward declaration for the union.
                    map_iteri (fun tag k v -> // The individual union cases.
                        line s.types $"struct {case_ty tag} {{ // {snd k}"
                        // The free vars in the env.
                        print_ordered_args (indent s.types) v
                        let () = // constructors
                            let s_typ = indent s.types
                            let concat x = String.concat ", " x
                            let args = v |> Array.map (fun (L(i,x)) -> $"{tyv x} t{i}")
                            let con_init = v |> Array.map (fun (L(i,x)) -> $"v{i}(t{i})")
                            if v.Length <> 0 then
                                line s_typ $"__host__ __device__ {case_ty tag}({concat args}) : {concat con_init} {{}}"
                                line s_typ $"__host__ __device__ {case_ty tag}() = delete;"
                        line s.types "};"
                        ) x.free_vars

                    line s.types $"struct Union{i} {{" // The union definition.
                    let _ = // Union cases inside the union.
                        let s_typ = indent s.types
                        line s_typ $"union {{"
                        let _ =
                            let s_typ = indent s_typ
                            map_iteri (fun tag k v -> line s_typ $"{case_ty tag} case{tag}; // {snd k}") x.free_vars
                        line s_typ "};"

                        if x.is_heap then line s_typ "int refc{0};"
                        if x.free_vars.Count > int max_tag then raise_codegen_error $"Too many union cases. They should not be more than {max_tag}."
                        line s_typ $"unsigned char tag{{{max_tag}}};"
                        line s_typ $"__host__ __device__ Union{i}() {{}}" // default constructor, the refc and tag have def value so we don't have to do anything here.

                        map_iteri (fun tag k v -> // The constructors for all the union cases.
                            line s_typ $"__host__ __device__ Union{i}({case_ty tag} t) : tag({tag}), case{tag}(t) {{}} // {snd k}"
                            ) x.free_vars

                        line s_typ $"__host__ __device__ Union{i}(const Union{i} & x) : tag(x.tag) {{" // copy constructor
                        let () =
                            let s_typ = indent s_typ
                            line s_typ "switch(x.tag){"
                            let () = // copy constructor cases
                                let s_typ = indent s_typ
                                map_iteri (fun tag k v ->
                                    line s_typ $"case {tag}: new (&this->case{tag}) {case_ty tag}(x.case{tag}); break; // {snd k}"
                                    ) x.free_vars
                            line s_typ "}"
                        line s_typ "}"
                        line s_typ $"__host__ __device__ Union{i}(const Union{i} && x) : tag(x.tag) {{" // move constructor
                        let () =
                            let s_typ = indent s_typ
                            line s_typ "switch(x.tag){"
                            let () = // move constructor cases
                                let s_typ = indent s_typ
                                map_iteri (fun tag k v ->
                                    line s_typ $"case {tag}: new (&this->case{tag}) {case_ty tag}(std::move(x.case{tag})); break; // {snd k}"
                                    ) x.free_vars
                            line s_typ "}"
                        line s_typ "}"
                        line s_typ $"__host__ __device__ Union{i} & operator=(const Union{i} & x) {{" // copy assignment operator
                        let () =
                            let s_typ = indent s_typ
                            line s_typ "if (this->tag == x.tag) {"
                            let () =
                                let s_typ = indent s_typ
                                line s_typ "switch(x.tag){"
                                let () = // copy assignment cases
                                    let s_typ = indent s_typ
                                    map_iteri (fun tag k v ->
                                        line s_typ $"case {tag}: this->case{tag} = x.case{tag}; break; // {snd k}"
                                        ) x.free_vars
                                line s_typ "}"
                            line s_typ "} else {"
                            let () =
                                let s_typ = indent s_typ
                                line s_typ $"this->~Union{i}();"
                                line s_typ $"new (this) Union{i}{{x}};"
                            line s_typ "}"
                            line s_typ "return *this;"
                        line s_typ "}"
                        line s_typ $"__host__ __device__ Union{i} & operator=(const Union{i} && x) {{" // move assignment operator
                        let () =
                            let s_typ = indent s_typ
                            line s_typ "if (this->tag == x.tag) {"
                            let () =
                                let s_typ = indent s_typ
                                line s_typ "switch(x.tag){"
                                let () = // move assignment cases
                                    let s_typ = indent s_typ
                                    map_iteri (fun tag k v ->
                                        line s_typ $"case {tag}: this->case{tag} = std::move(x.case{tag}); break; // {snd k}"
                                        ) x.free_vars
                                line s_typ "}"
                            line s_typ "} else {"
                            let () =
                                let s_typ = indent s_typ
                                line s_typ $"this->~Union{i}();"
                                line s_typ $"new (this) Union{i}{{std::move(x)}};"
                            line s_typ "}"
                            line s_typ "return *this;"
                        line s_typ "}"
                        line s_typ $"__host__ __device__ ~Union{i}() {{"
                        let () = // destructor
                            let s_typ = indent s_typ
                            line s_typ "switch(this->tag){"
                            let () = // destructor cases
                                let s_typ = indent s_typ
                                map_iteri (fun tag k v ->
                                    line s_typ $"case {tag}: this->case{tag}.~{case_ty tag}(); break; // {snd k}"
                                    ) x.free_vars
                            line s_typ "}"
                            line s_typ $"this->tag = {max_tag};"
                        line s_typ "}"
                    line s.types "};"
                    )
            and layout_tmpl is_heap is_refs name : _ -> LayoutRec =
                layout (fun s (x : LayoutRec) ->
                    let name = sprintf "%s%i" name x.tag
                    line s.fwd_types $"struct {name};"
                    line s.types $"struct {name} {{"
                    let () =
                        let s_typ = indent s.types
                        if is_heap then line s_typ "int refc{0};"
                        let type_suffix = if is_refs then " &" else ""
                        print_ordered_args' s_typ type_suffix x.free_vars
                        let concat x = String.concat ", " x
                        let args = x.free_vars |> Array.map (fun (L(i,x)) -> $"{tyv x}{type_suffix} t{i}")
                        let con_init = x.free_vars |> Array.map (fun (L(i,x)) -> $"v{i}(t{i})")
                        if args.Length <> 0 then
                            line s_typ $"__host__ __device__ {name}() = default;"
                            line s_typ $"__host__ __device__ {name}({concat args}) : {concat con_init} {{}}"
                    line s.types "};"
                    )
            and heap : _ -> LayoutRec = layout_tmpl true false "Heap"
            and mut : _ -> LayoutRec = layout_tmpl true false "Mut"
            and stack_mut : _ -> LayoutRec = layout_tmpl false false "StackMut"
            and heap_refs : _ -> LayoutRec = layout_tmpl true false "HeapRefs"
            and stack_refs : _ -> LayoutRec = layout_tmpl false true "StackRefs"

            function
            | ArgsCppHost(x,backend_entry_name) ->
                substitute_backend_with backend_cpp.CppHost <| fun () ->
                    // ws: globals the partial evaluator collected for the entry backend (PartEvalResult.globals) come
                    // first, as in CodegenC; the same text from a TyOp(Global) later is deduplicated by global'.
                    part_eval_env.globals |> Seq.toArray |> Array.iter (global' >> ignore)
                    let ret_ty, is_unit = // ws: `is_unit` (decision D10)
                        let er() = raise_codegen_error $"The return type of {backend_entry_name} function in the Cpp host backend should be a i32."
                        match binds_last_data x with
                        | DLit(LitInt32 _) | DV(L(_, YPrim Int32T)) -> "int", false
                        // ws (D10): a unit entry (every notebook cell: Eval.prepareSpi wraps the cell in a unit `main`)
                        // runs its body as statements and returns 0; upstream rejects it.
                        | DB -> "int", true
                        | _ -> er()

                    let s = {text=StringBuilder(); indent=0}
                    let code_env = code_env (backend())
                    code_env.fwd_dcls_main_defs.Add($"{ret_ty} {backend_entry_name}();\n")
                    line s $"{ret_ty} {backend_entry_name}() {{"
                    if is_unit then // ws (D10)
                        binds (Stack()) (indent s) (BindsLocal [||]) x
                        line (indent s) "return 0;"
                    else
                        binds_start (indent s) x
                    line s "}"
                    code_env.main_defs.Add(s.text.ToString())
            | ArgsCudaHost(vs,x,backend_entry_name) ->
                substitute_backend_with backend_cpp.CudaHost <| fun () ->
                    let ret_ty =
                        match binds_last_data x with
                        | DB -> "void"
                        | _ -> raise_codegen_error "The return type of the entry in the Cuda host backend should be a void type."
                    let s = {text=StringBuilder(); indent=0}
                    let args = vs |> Array.mapi (fun i (L(_,x)) -> $"{tyv x} v{i}") |> String.concat ", "
                    let code_env = code_env (backend())
                    code_env.fwd_dcls_main_defs.Add($"{ret_ty} {backend_entry_name}(%s{args});\n")
                    line s $"{ret_ty} {backend_entry_name}(%s{args}) {{"
                    binds_start (indent s) x
                    line s "}"
                    code_env.main_defs.Add(s.text.ToString())
            | ArgsCudaDevice(vs,x,backend_entry_name) ->
                substitute_backend_with backend_cpp.CudaDevice <| fun () ->
                    let ret_ty =
                        let er() = raise_codegen_error "The return type of the __global__ kernel in the Cuda backend should be a void type or a record of type {cluster_dims : {x : int; y : int; z : int}}."
                        match binds_last_data x with
                        | DRecord m when m.Count = 1 ->
                            match field_try_find "cluster_dims" m with // ws: field_try_find (records keyed `int * string`)
                            | Some(DRecord m) when m.Count = 3 ->
                                match field_try_find "x" m, field_try_find "y" m, field_try_find "z" m with // ws: as above
                                | Some(DSymbol x), Some(DSymbol y), Some(DSymbol z) ->  $"void __cluster_dims__({x},{y},{z})"
                                | Some(DV _), _, _ | _, Some(DV _), _ | _, _, Some(DV _) ->  raise_codegen_error "All the variables have to be known at compile time."
                                | _ -> er()
                            | _ -> er()
                        | DB -> "void"
                        | _ -> er()
                    let s = {text=StringBuilder(); indent=0}
                    let args = vs |> Array.mapi (fun i (L(_,x)) -> $"{tyv x} v{i}") |> String.concat ", "
                    let code_env = code_env (backend())
                    code_env.fwd_dcls_main_defs.Add($"extern \"C\" __global__ {ret_ty} {backend_entry_name}(%s{args});\n")
                    line s $"extern \"C\" __global__ {ret_ty} {backend_entry_name}(%s{args}) {{"
                    binds_start (indent s) x
                    line s "}"
                    code_env.main_defs.Add(s.text.ToString())

        let codegen (default_env : DefaultEnv) (file_path : string) part_eval_env x : GeneratedFile list = // ws: Startup. prefix and the annotation (GeneratedFile is the workspace's anonymous record alias)
            let g = codegenMemoTable HashIdentity.Structural // ws: CodegenAdapter's table
            let code_env_cpp_host = codegen_env.Create()
            let code_env_cuda_host = codegen_env.Create()
            let code_env_cuda_device =
                {
                    code_env_cuda_host with
                        fwd_dcls_methods = ResizeArray()
                        fwd_dcls_main_defs = ResizeArray()
                        functions = ResizeArray()
                        main_defs = ResizeArray()
                }
            let code_env = function
                | backend_cpp.CppHost -> code_env_cpp_host
                | backend_cpp.CudaHost -> code_env_cuda_host
                | backend_cpp.CudaDevice -> code_env_cuda_device

            let rec main_codegen =
                codegen' (fun (jp_body,key,r') previous_backend ->
                    let backend_name = codegenOwnerBackendName jp_body // ws: CodegenAdapter (hopac owners are not pairs)
                    match previous_backend with
                    | backend_cpp.CudaHost ->
                        match backend_name with
                        | "CudaDevice" ->
                            Utils.memoize g (fun (jp_body,key) ->
                                let args = rdata_free_vars (codegenMethodKeyArgs key) // ws: CodegenAdapter
                                let backend_entry_name = $"cuda_device_entry{g.Count}"
                                let a, _, _ = codegenMethodBody part_eval_env "CudaDevice" jp_body key // ws: CodegenAdapter (raises on a malformed table)
                                main_codegen (ArgsCudaDevice(args, a, backend_entry_name))
                                backend_entry_name
                                ) (jp_body,key)
                        | x -> raise_codegen_error_backend r' $"The Cuda host backend does not support the {x} backend."
                    | backend_cpp.CppHost ->
                        match backend_name with
                        | "CudaHost" ->
                            Utils.memoize g (fun (jp_body,key) ->
                                let args = rdata_free_vars (codegenMethodKeyArgs key) // ws: CodegenAdapter
                                let backend_entry_name = $"cuda_host_entry{g.Count}"
                                let a, _, _ = codegenMethodBody part_eval_env "CudaHost" jp_body key // ws: CodegenAdapter (raises on a malformed table)
                                main_codegen (ArgsCudaHost(args, a, backend_entry_name))
                                backend_entry_name
                                ) (jp_body,key)
                        | x -> raise_codegen_error_backend r' $"The C++ host backend does not support the {x} backend."
                    | backend_cpp.CudaDevice ->
                        raise_codegen_error_backend r' $"The Cuda device backend does not support nesting of backends."
                    ) part_eval_env code_env

            main_codegen (ArgsCppHost(x, "main"))

            let code_corelib_hpp =
                let dir f = codegen_runtime_file f // ws: CodegenUtils.codegen_runtime_file (upstream: next to the compiler DLL)
                dir "corelib.cuh" |> replace_default_types default_env

            // ws: upstream's unused `merge` (over System.Collections.Generic.OrderedDictionary) is left out.

            let file_name = System.IO.Path.GetFileNameWithoutExtension file_path // ws: System.IO qualified
            let code_hpp =
                StringBuilder()
                    .AppendLine("#pragma once")
                    .AppendLine($"#include \"{file_name}.corelib.hpp\"")
                    .AppendLine("#ifdef __CUDACC__")
                    // .AppendJoin("", code_env_cuda_device.globals) // The Cuda device globals and types are merged into the Cuda host arrays
                    .AppendJoin("", code_env_cuda_host.globals)
                    // .AppendJoin("", code_env_cuda_device.fwd_dcls_types)
                    .AppendJoin("", code_env_cuda_host.fwd_dcls_types)
                    // .AppendJoin("", code_env_cuda_device.types)
                    .AppendJoin("", code_env_cuda_host.types)
                    .AppendLine("#ifdef __CUDA_ARCH__")
                    .AppendLine("// Cuda device backend")
                    .AppendJoin("", code_env_cuda_device.fwd_dcls_methods)
                    .AppendLine("#else")
                    .AppendLine("// Cuda host backend")
                    .AppendJoin("", code_env_cuda_host.fwd_dcls_methods)
                    .AppendJoin("", code_env_cuda_device.fwd_dcls_main_defs)
                    .AppendLine("#endif")
                    .AppendLine("#else")
                    .AppendLine("// Cpp host backend")
                    .AppendJoin("", code_env_cpp_host.globals)
                    .AppendJoin("", code_env_cpp_host.fwd_dcls_types)
                    .AppendJoin("", code_env_cpp_host.fwd_dcls_methods)
                    .AppendJoin("", code_env_cuda_host.fwd_dcls_main_defs)
                    .AppendJoin("", code_env_cpp_host.fwd_dcls_main_defs)
                    .AppendJoin("", code_env_cpp_host.types)
                    .AppendLine("#endif")
                    .ToString()
            let code_cpp =
                StringBuilder()
                    .AppendLine($"#include \"{file_name}.hpp\"")
                    .AppendJoin("", code_env_cpp_host.functions)
                    .AppendJoin("", code_env_cpp_host.main_defs)
                    .ToString()
            let code_cu =
                StringBuilder()
                    .AppendLine($"#include \"{file_name}.hpp\"")
                    .AppendJoin("", code_env_cuda_device.functions)
                    .AppendJoin("", code_env_cuda_device.main_defs)
                    .AppendJoin("", code_env_cuda_host.functions)
                    .AppendJoin("", code_env_cuda_host.main_defs)
                    .ToString()

            [
                {|code = code_corelib_hpp; file_extension = ".corelib.hpp"|}
                {|code = code_hpp; file_extension = ".hpp"|}
                {|code = code_cpp; file_extension = ".cpp"|}
                {|code = code_cu; file_extension = ".cu"|}
            ]
    /// ## CodegenPython
    // Upstream: The Spiral Language 2/CodegenPython.fs @ 0cb0fda0 (host_cpp_and_cuda_backend, v2.18.10). One shared
    // section for both cores; every line that differs from upstream carries a `// ws:` comment. Kernels
    // (`join_backend CudaDevice`) go through CodegenCpp.codegen'. The host program runs without a GPU: the prelude
    // binds numpy to `cp` when no CUDA device answers (see `cupy_prelude`).
    module CodegenPython =
        // ws: `open Spiral...` lines dropped: everything lives in the enclosing `spiral_compiler` module.
        open System.Collections.Generic

        let private backend_name = "Python"
        let private pythonWrapHelper = "def spiral_wrap(x, bits, signed):\n    x &= (1 << bits) - 1\n    return x - (1 << bits) if signed and x >> (bits - 1) else x"
        let private pythonStringHelpers = "import sys\ndef spiral_utf8(s):\n    return s.encode('utf-8', 'surrogateescape')\ndef spiral_string_length(s):\n    return len(s) if s.isascii() else len(spiral_utf8(s))\ndef spiral_string_index(s, i):\n    return s[i] if s.isascii() else chr(spiral_utf8(s)[i])\ndef spiral_string_slice(s, a, b):\n    data = s.encode('ascii') if s.isascii() else spiral_utf8(s)\n    n = len(data)\n    if a < 0 or a > n or b < a - 1 or b >= n: sys.exit(3)\n    if b >= a and ((data[a] & 0xC0) == 0x80 or (b + 1 < n and (data[b + 1] & 0xC0) == 0x80)): sys.exit(3)\n    return s[a:b + 1] if s.isascii() else data[a:b + 1].decode('utf-8', 'surrogateescape')"
        let private pythonPrimWidth = function
            | Int8T -> Some (8, true) | Int16T -> Some (16, true) | Int32T -> Some (32, true) | Int64T -> Some (64, true)
            | UInt8T -> Some (8, false) | UInt16T -> Some (16, false) | UInt32T -> Some (32, false) | UInt64T -> Some (64, false)
            | _ -> None
        let private pythonIntWidth = function
            | DV(L(_,YPrim t)) -> pythonPrimWidth t
            | DLit l -> pythonPrimWidth (lit_to_primitive_type l)
            | _ -> None

        let lit = function
            | LitInt8 x -> sprintf "%i" x
            | LitInt16 x -> sprintf "%i" x
            | LitInt32 x -> sprintf "%i" x
            | LitInt64 x -> sprintf "%i" x
            | LitUInt8 x -> sprintf "%i" x
            | LitUInt16 x -> sprintf "%i" x
            | LitUInt32 x -> sprintf "%i" x
            | LitUInt64 x -> sprintf "%i" x
            | LitFloat32 x ->
                if x = infinityf then "float('inf')"
                elif x = -infinityf then "float('-inf')"
                elif Single.IsNaN x then "float('nan')" // ws: upstream wrote float() (= 0.0)
                else x.ToString("R") |> add_dec_point
            | LitFloat64 x ->
                if x = infinity then "float('inf')"
                elif x = -infinity then "float('-inf')"
                elif Double.IsNaN x then "float('nan')" // ws: upstream wrote float() (= 0.0)
                else x.ToString("R") |> add_dec_point
            | LitString x ->
                let strb = StringBuilder(x.Length+2)
                strb.Append '"' |> ignore
                String.iter (function
                    | '"' -> strb.Append "\\\""
                    | '\b' -> strb.Append @"\b"
                    | '\t' -> strb.Append @"\t"
                    | '\n' -> strb.Append @"\n"
                    | '\r' -> strb.Append @"\r"
                    | '\\' -> strb.Append @"\\"
                    | x -> strb.Append x
                    >> ignore
                    ) x
                strb.Append '"' |> ignore
                strb.ToString()
            | LitChar x ->
                match x with
                | '\b' -> @"\b"
                | '\n' -> @"\n"
                | '\t' -> @"\t"
                | '\r' -> @"\r"
                | '\\' -> @"\\"
                | '\'' -> @"\'" // ws: upstream printed ''' (a Python syntax error)
                | '\000' -> @"\x00"
                | x -> string x
                |> sprintf "'%s'"
            | LitBool x -> if x then "True" else "False"

        let type_lit = function
            | YLit x -> lit x
            | YSymbol x -> x
            | x -> raise_codegen_error "Compiler error: Expecting a type literal in the macro."

        let show_w = function WV(L(i,_)) -> sprintf "v%i" i | WLit a -> lit a
        let args x = x |> Array.map (fun (L(i,_)) -> sprintf "v%i" i) |> String.concat ", "
        let args' b = data_term_vars b |> Array.map show_w |> String.concat ", "
        let prim x = show_primt x // ws: Infer's show_primt is not in a module here
        let cupy_ty x =
            let er () = raise_codegen_error "Only stack allocated primitive types (i8,i16,i32,i64 and u8,u16,u32,u64 and f32,f64 and bool) are allowed in CuPy arrays."
            match x with
            | [|L(_,x)|] ->
                match x with
                | YPrim x ->
                    match x with
                    | Int8T -> "cp.int8"
                    | Int16T -> "cp.int16"
                    | Int32T -> "cp.int32"
                    | Int64T -> "cp.int64"
                    | UInt8T -> "cp.uint8"
                    | UInt16T -> "cp.uint16"
                    | UInt32T -> "cp.uint32"
                    | UInt64T -> "cp.uint64"
                    | Float32T -> "cp.float32"
                    | Float64T -> "cp.float64"
                    | BoolT -> "cp.bool_"
                    | _ -> "object"
                | _ -> "object"
            | _ -> "object"

        type UnionRec = {tag : int; free_vars : Map<int * string, TyV[]>} // ws: union cases are keyed `tag * name`
        type LayoutRec = {tag : int; data : Data; free_vars : TyV[]; free_vars_by_key : Map<int * string, TyV[]>} // ws: record keys are `int * string`
        type MethodRec = {tag : int; free_vars : L<Tag,Ty>[]; range : Ty; body : TypedBind[]; name : string}
        type ClosureRec = {tag : int; free_vars : L<Tag,Ty>[]; domain : Ty; domain_args : TyV[]; range : Ty; body : TypedBind[]; name : string}

        type BindsReturn =
            | BindsTailEnd
            | BindsLocal of TyV []

        let line x s = if s <> "" then x.text.Append(' ', x.indent).AppendLine s |> ignore

        // ws: a record field by its name (records keyed `int * string`; hopac compares interned field ids).
        let field_by_key key (m : Map<int * string, 'a>) = m |> Map.pick (fun (_, k) v -> if LayoutFieldNameIdOps.matchesText key k then Some v else None)

        // ws: replaces upstream's `import cupy as cp`. CuPy when it imports and a CUDA device answers; otherwise numpy
        // under the same name, which has every name the generator prints (cp.int32.., cp.bool_, cp.empty, cp.array,
        // cp.ndarray, .item(), .size), so host-only programs run on the CPU. `cuda` tells library code whether
        // kernels can run; SPIRAL_CUDA=0 forces the CPU path. (py_checks: cupy imports here but raises on first use.)
        let cupy_prelude =
            String.concat "\n" [
                "import os"
                "try: # CuPy when a CUDA device answers, otherwise numpy under the same name (SPIRAL_CUDA=0 forces numpy)."
                "    if os.environ.get('SPIRAL_CUDA', '1') == '0': raise ImportError('SPIRAL_CUDA=0')"
                "    import cupy as cp"
                "    if cp.cuda.runtime.getDeviceCount() < 1: raise RuntimeError('no CUDA device')"
                "    cuda = True"
                "except Exception:"
                "    import numpy as cp"
                "    cuda = False"
            ]

        let pythonWithoutDels (text : string) =
            let delLine = System.Text.RegularExpressions.Regex(@"^\s*del v[0-9]+(, v[0-9]+)*\s*$")
            let lines = text.Replace("\r\n", "\n").Split('\n') |> Array.filter (fun line -> not (delLine.IsMatch line))
            let indentOf (line : string) = line.Length - line.TrimStart(' ').Length
            let output = ResizeArray<string>()
            for index = 0 to lines.Length - 1 do
                let line = lines.[index]
                output.Add line
                if line.TrimEnd().EndsWith(":") && not (line.TrimStart().StartsWith("#")) then
                    let following = lines |> Seq.skip (index + 1) |> Seq.tryFind (fun next -> next.Trim() <> "")
                    match following with
                    | Some next when indentOf next > indentOf line -> ()
                    | _ -> output.Add(System.String(' ', indentOf line + 4) + "pass")
            System.String.Join("\n", output)

        let codegen' backend_handler (part_eval_env : PartEvalResult) (code_env : codegen_env) =
            let global' =
                let has_added = HashSet()
                // ws: continuation fragments of a multi-line global repeat legitimately (CodegenUtils).
                fun x -> if preservesDuplicateGlobalFragment x || has_added.Add x then code_env.globals.Add x

            let import x = global' $"import {x}"
            let from x = global' $"from {x}"

            let print is_type show r =
                let s = {text=StringBuilder(); indent=0}
                show s r
                let text = s.text.ToString()
                if is_type then code_env.types.Add(text) else code_env.functions.Add(text)

            let union show =
                let dict = codegenMemoTable HashIdentity.Reference // ws: CodegenAdapter's table (hopac: concurrent)
                let f (a : Union) : UnionRec =
                    let free_vars = a.Item.cases |> Map.map (fun _ -> part_eval_env.ty_to_data >> data_free_vars)
                    {free_vars=free_vars; tag=dict.Count}
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print true show r
                    r

            let layout show =
                let dict' = codegenMemoTable HashIdentity.Structural // ws: CodegenAdapter's table
                let dict = codegenMemoTable HashIdentity.Reference // ws: as above
                let f x : LayoutRec =
                    match x with
                    | YLayout(x,_) ->
                        let x = part_eval_env.ty_to_data x
                        let a, b =
                            match x with
                            | DRecord a -> let a = Map.map (fun _ -> data_free_vars) a in a |> Map.toArray |> Array.collect snd, a
                            | _ -> data_free_vars x, Map.empty
                        {data=x; free_vars=a; free_vars_by_key=b; tag=dict'.Count}
                    | _ -> raise_codegen_error $"Compiler error: Expected a layout type (5).\nGot: %s{show_ty x}"
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (Utils.memoize dict' (fun x -> dirty <- true; f x)) x
                    if dirty then print true show r
                    r

            let jp is_type f show =
                let dict = codegenMemoTable HashIdentity.Structural // ws: CodegenAdapter's table
                let f x = f (x, dict.Count)
                fun x ->
                    let mutable dirty = false
                    let r = Utils.memoize dict (fun x -> dirty <- true; f x) x
                    if dirty then print is_type show r
                    r

            let cupy_ty x = part_eval_env.ty_to_data x |> data_free_vars |> cupy_ty
            // ws: set while writing a method that calls itself in tail position: Python has no tail calls (RecursionError past
            // ~1,000 frames), so the body runs in `while True:`, a tail value `return`s and the self call reassigns the
            // parameters and `continue`s (Rust's and Pascal's self_loop; lane G's python_self_tail_call_depth).
            let self_loop : (int * TyV []) option ref = ref None
            let rec binds_start (args : TyV []) (s : string_builder_env) (x : TypedBind []) = binds (refc_prepass Set.empty (Set args) x).g_decr s BindsTailEnd x // ws: RefCounting is not in a module here
            and binds g_decr (s : string_builder_env) (ret : BindsReturn) (stmts : TypedBind []) =
                let s_len = s.text.Length
                let tup_destruct (a,b) =
                    if 0 < Array.length a then
                        let a = args a
                        let b = Array.map show_w (data_term_vars b) |> String.concat ", "
                        sprintf "%s = %s" a b |> line s
                Array.iter (fun x ->
                    let _ =
                        let f (g : RefcDecrTable) = match g.TryGetValue(x) with true, x -> Seq.toArray x | _ -> [||] // ws: CodegenAdapter's table type
                        match args (f g_decr) with "" -> () | x -> sprintf "del %s" x |> line s
                    match x with
                    | TyLet(d,trace,a) ->
                        try op g_decr s (BindsLocal (data_free_vars d)) a
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                    | TyLocalReturnOp(trace,a,_) ->
                        try op g_decr s ret a
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                    | TyLocalReturnData(d,trace) ->
                        try match ret with
                            | BindsLocal l -> tup_destruct (l, d)
                            | BindsTailEnd -> line s $"return {tup_data' d}"
                        with :? CodegenError as e -> raise_codegen_error' trace (e.Data0,e.Data1)
                    ) stmts
                if s.text.Length = s_len then line s "pass"
            and tup_data' x =
                match Array.map show_w (data_term_vars x) with
                | [||] -> ""
                | [|x|] -> x
                | args -> String.concat ", " args
            and tup_data x =
                match Array.map show_w (data_term_vars x) with
                | [||] -> "None"
                | [|x|] -> x
                | args -> sprintf "(%s)" (String.concat ", " args)
            and tyv = function
                | YUnion a ->
                    match a.Item.layout with
                    | UHeap -> sprintf "UH%i" (uheap a).tag
                    | UStack -> sprintf "US%i" (ustack a).tag
                | YLayout(_,lay) as a ->
                    match lay with
                    | Heap -> sprintf "Heap%i" (heap a).tag
                    | HeapMutable -> sprintf "Mut%i" (mut a).tag
                    | StackMutable -> raise_codegen_error "The Python backend doesn't support stack mutable layout types."
                    | StackRefs | HeapRefs -> raise_codegen_error "The Python backend doesn't support stack and heap refs layout types."
                | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                    match r |> Map.tryPick (fun (_, k) v -> if k = backend_name then Some v else None) with // ws: records keyed `int * string`
                    | Some x -> tup_ty x
                    | None -> raise_codegen_error $"In the Python type backend_switch, expected a record with the '{backend_name}' field."
                | YMacro a -> a |> List.map (function Text a -> a | Type a -> tup_ty a | TypeLit a -> type_lit a) |> String.concat ""
                | YPrim a -> prim a
                | YArray a -> "cp.ndarray"
                | YFun(a,b,FT_Vanilla) ->
                    let a = part_eval_env.ty_to_data a |> data_free_vars |> Array.map (fun (L(_,t)) -> tyv t) |> String.concat ", "
                    $"Callable[[{a}], {tup_ty b}]"
                | YExists -> raise_codegen_error "Existentials are not supported at runtime. They are a compile time feature only."
                | YForall -> raise_codegen_error "Foralls are not supported at runtime. They are a compile time feature only."
                | a -> raise_codegen_error $"Complier error: Type not supported in the codegen.\nGot: %A{a}"
            and tup_ty x =
                match part_eval_env.ty_to_data x |> data_free_vars |> Array.map (fun (L(_,t)) -> tyv t) with
                | [||] -> "None"
                | [|x|] -> x
                | x -> String.concat ", " x |> sprintf "Tuple[%s]"
            // ws: an annotation of a macro type. lib/spiral's type text is often another backend's (`Result<i32, string>`,
            // `System.Threading.CancellationToken`): Python evaluates annotations of a `def` and checks a NamedTuple's,
            // a SyntaxError or NameError. A (subscripted) dotted name is written as a string, a forward reference that
            // is never evaluated; any other text as `object`. `tyv` stays verbatim for macro text and conversions.
            and annot t =
                match t with
                | YMacro [Text "backend_switch "; Type (YRecord r)] ->
                    match r |> Map.tryPick (fun (_, k) v -> if k = backend_name then Some v else None) with
                    | Some x -> tup_annot x
                    | None -> tyv t
                | YMacro _ ->
                    let x = (tyv t).Trim()
                    if System.Text.RegularExpressions.Regex.IsMatch(x, @"^[A-Za-z_][\w.]*(?:\[[\w., \[\]]*\])?$") then $"'{x}'" else "object"
                | YFun(a,b,FT_Vanilla) ->
                    let a = part_eval_env.ty_to_data a |> data_free_vars |> Array.map (fun (L(_,t)) -> annot t) |> String.concat ", "
                    $"Callable[[{a}], {tup_annot b}]"
                | _ -> tyv t
            and tup_annot x =
                match part_eval_env.ty_to_data x |> data_free_vars |> Array.map (fun (L(_,t)) -> annot t) with
                | [||] -> "None"
                | [|x|] -> x
                | x -> String.concat ", " x |> sprintf "Tuple[%s]"
            and op g_decr s (ret : BindsReturn) a =
                let return' (x : string) =
                    match ret with
                    | BindsTailEnd -> line s $"return {x}"
                    | BindsLocal ret -> line s (if ret.Length = 0 then x else sprintf "%s = %s" (args ret) x)
                let jp (a,b) =
                    let args = args b
                    match a with
                    | JPMethod(a,b) -> sprintf "%s(%s)" (method (a,b)).name args
                    | JPClosure(a,b) -> sprintf "%s(%s)" (closure (a,b)).name args
                let layout_index i x' =
                    x' |> Array.map (fun (L(i',_)) -> $"v{i}.v{i'}")
                    |> String.concat ", "
                    |> return'

                match a with
                | TySizeOf t -> raise_codegen_error $"The following type in `sizeof` is not supported in the Python back end.\nGot: {show_ty t}"
                | TyMacro a ->
                    a
                    |> List.map (function
                        // ws: lib/spiral writes F# interpolated strings (`$'$"...{!x}"'`) in code shared by every
                        // backend; turn them into Python f-strings. Drop this arm once those macros are per backend.
                        | CMText x when x.StartsWith("$\"", System.StringComparison.Ordinal) -> "f\"" + x.Replace("%A{", "{").Substring 2
                        | CMText x -> x | CMTerm (x,inl) -> (if inl then args' x else tup_data x) | CMType x -> tup_ty x | CMTypeLit a -> type_lit a)
                    |> String.concat "" |> return'
                | TyIf(cond,tr,fl) ->
                    line s (sprintf "if %s:" (tup_data cond))
                    binds g_decr (indent s) ret tr
                    line s "else:"
                    binds g_decr (indent s) ret fl
                | TyJoinPoint(JPMethod(a,c),b) when (match ret, self_loop.Value with BindsTailEnd, Some (tag, _) -> (method (a,c)).tag = tag | _ -> false) -> // ws: see self_loop
                    let parameters = snd self_loop.Value.Value
                    if parameters.Length > 0 then line s $"{args parameters} = {args b}"
                    line s "continue"
                | TyJoinPoint(a,args) -> return' (jp (a, args))
                | TyBackend(a,b,c) -> line s $"kernel = \"{backend_handler (a,b,c)}\""
                | TyWhile(a,b) ->
                    line s (sprintf "while %s:" (jp a))
                    binds g_decr (indent s) (BindsLocal [||]) b
                | TyDo a | TyIndent a -> binds g_decr s ret a // ws: workspace-only ops (`!!!!Do`/`!!!!Indent`), inlined as in CodegenC
                | TyIntSwitch(L(v_i,_),on_succ,on_fail) ->
                    Array.iteri (fun i x ->
                        if i = 0 then line s $"if v{v_i} == {i}:"
                        else line s $"elif v{v_i} == {i}:"
                        binds g_decr (indent s) ret x
                        ) on_succ
                    line s "else:"
                    binds g_decr (indent s) ret on_fail
                | TyUnionUnbox(is,x,on_succs,on_fail) ->
                    let case_tags = x.Item.tags
                    line s (sprintf "match %s:" (is |> List.map (fun (L(i,_)) -> $"v{i}") |> String.concat ", "))
                    let s = indent s
                    let union_rec, prefix =
                        match x.Item.layout with
                        | UHeap -> let u = uheap x in u, sprintf "UH%i" u.tag
                        | UStack -> let u = ustack x in u, sprintf "US%i" u.tag
                    Map.iter (fun k (a,b) ->
                        let i = case_tags.[k]
                        let cases =
                            a |> List.map (fun a ->
                                let x = data_free_vars a
                                let g_decr' = Utils.get_default g_decr (Array.head b) (fun () -> Set.empty)
                                let x,g_decr' = Array.mapFold (fun g_decr (L(i,_) as v) -> if Set.contains v g_decr then "_", Set.remove v g_decr else sprintf "v%i" i, g_decr) g_decr' x
                                g_decr.[Array.head b] <- g_decr'
                                sprintf "%s(%s)" (generatedCaseNameOfTag prefix union_rec.free_vars i) (String.concat ", " x)
                                )
                            |> String.concat ", "
                        line s (sprintf "case %s: # %s" cases (UnionTagIdOps.text k)) // ws: the workspace's tags are interned ids
                        binds g_decr (indent s) ret b
                        ) on_succs
                    line s "case t:"
                    match on_fail with
                    | Some b -> binds g_decr (indent s) ret b
                    | None -> line (indent s) "raise Exception(f'Pattern matching miss. Got: {t}')"
                | TyUnionBox(a,b,c') ->
                    let c = c'.Item
                    let i = c.tags.[a]
                    let vars = tup_data' b
                    let pythonNullary (cases : Map<int * string, TyV[]>) (tag : int) = cases |> Map.exists (fun (j, _) fields -> j = tag && fields.Length = 0)
                    let pythonConstruct (name : string) (nullary : bool) (args : string) = if nullary then name + "_shared" else sprintf "%s(%s)" name args
                    match c.layout with
                    | UHeap -> let u = uheap c' in pythonConstruct (generatedCaseNameOfTag (sprintf "UH%i" u.tag) u.free_vars i) (pythonNullary u.free_vars i) vars
                    | UStack -> let u = ustack c' in pythonConstruct (generatedCaseNameOfTag (sprintf "US%i" u.tag) u.free_vars i) (pythonNullary u.free_vars i) vars
                    |> return'
                | TyToLayout(a,b) ->
                    match b with
                    | YLayout(_,layout) ->
                        match layout with
                        | Heap -> sprintf "Heap%i(%s)" (heap b).tag (tup_data' a)
                        | HeapMutable -> sprintf "Mut%i(%s)" (mut b).tag (tup_data' a)
                        | StackMutable -> raise_codegen_error "The Python backend doesn't support stack mutable layout types."
                        | StackRefs | HeapRefs -> raise_codegen_error "The Python backend doesn't support stack and heap refs layout types."
                    | _ -> raise_codegen_error "Compiler error: Expected a layout type (6)."
                    |> return'
                | TyLayoutIndexAll(L(i,YLayout(_,lay) & a)) ->
                    match lay with
                    | Heap -> heap a
                    | HeapMutable -> mut a
                    | StackMutable -> raise_codegen_error "The Python backend doesn't support indexing into stack mutable layout types."
                    | StackRefs | HeapRefs -> raise_codegen_error "The Python backend doesn't support indexing into stack and heap refs layout types."
                    |> fun x -> x.free_vars |> layout_index i
                | TyLayoutIndexByKey(L(i,YLayout(_,lay) & a),key) ->
                    match lay with
                    | Heap -> heap a
                    | HeapMutable -> mut a
                    | StackMutable -> raise_codegen_error "The Python backend doesn't support indexing into stack mutable layout types."
                    | StackRefs | HeapRefs -> raise_codegen_error "The Python backend doesn't support indexing into stack and heap refs layout types."
                    |> fun x -> x.free_vars_by_key |> field_by_key key |> layout_index i // ws: field_by_key
                | TyLayoutIndexAll _ | TyLayoutIndexByKey _ -> raise_codegen_error "Compiler error: Expected the TyV in layout index to be a layout type."
                | TyLayoutMutableSet(L(i,t),b,c) ->
                    let a = List.fold (fun s k -> match s with DRecord l -> field_by_key k l | _ -> raise_codegen_error "Compiler error: Expected a record.") (mut t).data b // ws: field_by_key
                    Array.iter2 (fun (L(i',_)) b -> line s $"v{i}.v{i'} = {show_w b}") (data_free_vars a) (data_term_vars c)
                // ws: non-primitive elements (strings, tuples, unions: lib/spiral's parser buffers and list'.to_array') are
                // object arrays, which CuPy can't hold: those stay NumPy arrays on the host (as at the fork's HEAD).
                | TyArrayLiteral(a,b) ->
                    let dt = cupy_ty a
                    if dt = "object" then
                        // One element per item: `numpy.array` would flatten tuple elements (or build a 2-D array).
                        global' "def spiral_object_array(*items):\n    import numpy\n    array = numpy.empty(len(items), dtype=object)\n    for i, x in enumerate(items): array[i] = x\n    return array"
                        return' <| sprintf "spiral_object_array(%s)" (b |> List.map (fun x -> "(" + tup_data' x + ")") |> String.concat ", ")
                    else return' <| sprintf "cp.array([%s],dtype=%s)" (List.map tup_data' b |> String.concat ", ") dt
                | TyArrayCreate(a,b) ->
                    let dt = cupy_ty a
                    if dt = "object" then return' $"__import__('numpy').empty({tup_data b},dtype={dt})"
                    else return' $"cp.zeros({tup_data b},dtype={dt})"
                | TyFailwith(a,b) -> line s $"raise Exception({tup_data' b})"
                | TyConv(a,b) ->
                    match (match a with YPrim t -> pythonPrimWidth t | _ -> None) with
                    | Some (bits, signed) -> global' pythonWrapHelper; return' (sprintf "spiral_wrap(int(%s), %i, %s)" (tup_data b) bits (if signed then "True" else "False"))
                    | None -> return' $"{tyv a}({tup_data b})"
                | TyApply(L(i,_),b) -> return' $"v{i}({tup_data' b})"
                | TyArrayLength(a,b) -> return' $"{tup_data b}.size"
                | TyStringLength(a,b) -> global' pythonStringHelpers; return' $"spiral_string_length({tup_data b})"
                | TyOp(Global,[DLit (LitString x)]) -> global' x
                | TyOp(op,l) ->
                    let pythonWrapped d expr =
                        match pythonIntWidth d with
                        | Some (bits, signed) -> global' pythonWrapHelper; sprintf "spiral_wrap(%s, %i, %s)" expr bits (if signed then "True" else "False")
                        | None -> expr
                    match op, l with
                    | ToPythonRecord,[DRecord x] -> Map.foldBack (fun k v l -> $"'{snd k}': {tup_data v}" :: l) x [] |> String.concat ", " |> sprintf "{%s}" // ws: `snd k` (records keyed `int * string`)
                    | ToPythonNamedTuple,[n;DRecord x] ->
                        import "collections"
                        let field_names = Map.foldBack (fun k v l -> $"'{snd k}'" :: l) x [] |> String.concat ", " // ws: `snd k`
                        let args = Map.foldBack (fun k v l -> tup_data v :: l) x [] |> String.concat ", "
                        $"collections.namedtuple({tup_data n},[{field_names}])({args})"
                    | Dyn,[a] -> tup_data a
                    | TypeToVar, _ -> raise_codegen_error "The use of `` should never appear in generated code."
                    | StringIndex, [a;b] -> global' pythonStringHelpers; sprintf "spiral_string_index(%s, %s)" (tup_data a) (tup_data b)
                    | StringSlice, [a;b;c] -> global' pythonStringHelpers; sprintf "spiral_string_slice(%s, %s, %s)" (tup_data a) (tup_data b) (tup_data c)
                    | StaticStringConcat, [a;b] -> sprintf "%s + %s" (tup_data a) (tup_data b) // ws: upstream's Python generator has no string concat (sm.concat)
                    | ArrayIndex, [a;b] ->
                        // Upstream assumes primitive CuPy arrays. Foreign/corelib containers can return
                        // ordinary tuples/objects instead; object arrays must preserve those values too.
                        global' "def spiral_array_index(array, index):\n    value = array[index]\n    return value.item() if isinstance(array, cp.ndarray) and array.dtype.kind != 'O' else value"
                        sprintf "spiral_array_index(%s, %s)" (tup_data a) (tup_data b)
                    | ArrayIndexSet, [a;b;c] ->
                        match tup_data' c with
                        | "" -> "pass # void array set"
                        | c -> sprintf "%s[%s] = %s" (tup_data a) (tup_data b) c
                    // Math
                    | Add, [a;b] -> pythonWrapped a (sprintf "%s + %s" (tup_data a) (tup_data b))
                    | Sub, [a;b] -> pythonWrapped a (sprintf "%s - %s" (tup_data a) (tup_data b))
                    | Mult, [a;b] -> pythonWrapped a (sprintf "%s * %s" (tup_data a) (tup_data b))
                    | Div, [(DV(L(_,YPrim (Float32T | Float64T))) | DLit(LitFloat32 _ | LitFloat64 _)) & a;b] -> sprintf "%s / %s" (tup_data a) (tup_data b)
                    | Div, [a;b] when (pythonIntWidth a).IsSome -> global' "def spiral_div_trunc(a, b):\n    q = abs(a) // abs(b)\n    return q if (a < 0) == (b < 0) else -q"; pythonWrapped a (sprintf "spiral_div_trunc(%s, %s)" (tup_data a) (tup_data b))
                    | Div, [a;b] -> sprintf "%s // %s" (tup_data a) (tup_data b)
                    | Mod, [a;b] when (pythonIntWidth a).IsSome -> global' "def spiral_mod_trunc(a, b):\n    r = abs(a) % abs(b)\n    return -r if a < 0 else r"; sprintf "spiral_mod_trunc(%s, %s)" (tup_data a) (tup_data b)
                    | Mod, [(DV(L(_,YPrim (Float32T | Float64T))) | DLit(LitFloat32 _ | LitFloat64 _)) & a;b] -> import "math"; sprintf "math.fmod(%s, %s)" (tup_data a) (tup_data b)
                    | Mod, [a;b] -> sprintf "%s %% %s" (tup_data a) (tup_data b)
                    | Pow, [a;b] -> sprintf "pow(%s,%s)" (tup_data a) (tup_data b)
                    | LT, [a;b] -> sprintf "%s < %s" (tup_data a) (tup_data b)
                    | LTE, [a;b] -> sprintf "%s <= %s" (tup_data a) (tup_data b)
                    | EQ, [a;b] -> sprintf "%s == %s" (tup_data a) (tup_data b)
                    | NEQ, [a;b] -> sprintf "%s != %s" (tup_data a) (tup_data b)
                    | GT, [a;b] -> sprintf "%s > %s" (tup_data a) (tup_data b)
                    | GTE, [a;b] -> sprintf "%s >= %s" (tup_data a) (tup_data b)
                    | BoolAnd, [a;b] -> sprintf "%s and %s" (tup_data a) (tup_data b)
                    | BoolOr, [a;b] -> sprintf "%s or %s" (tup_data a) (tup_data b)
                    | BitwiseAnd, [a;b] -> sprintf "%s & %s" (tup_data a) (tup_data b)
                    | BitwiseOr, [a;b] -> sprintf "%s | %s" (tup_data a) (tup_data b)
                    | BitwiseXor, [a;b] -> sprintf "%s ^ %s" (tup_data a) (tup_data b)
                    | BitwiseComplement, [a] -> pythonWrapped a (sprintf "~%s" (tup_data a))

                    | ShiftLeft, [a;b] -> pythonWrapped a (sprintf "%s << %s" (tup_data a) (tup_data b))
                    | ShiftRight, [a;b] -> sprintf "%s >> %s" (tup_data a) (tup_data b)

                    | Neg, [x] -> pythonWrapped x (sprintf "-%s" (tup_data x))
                    | Log, [x] -> import "math"; sprintf "math.log(%s)" (tup_data x)
                    | Exp, [x] -> import "math"; sprintf "math.exp(%s)" (tup_data x)
                    | Tanh, [x] -> import "math"; sprintf "math.tanh(%s)" (tup_data x)
                    | Sqrt, [x] -> import "math"; sprintf "math.sqrt(%s)" (tup_data x)
                    | Sin, [x] -> import "math"; sprintf "math.sin(%s)" (tup_data x) // ws: upstream's C++ generator has Sin/Cos, its Python one does not
                    | Cos, [x] -> import "math"; sprintf "math.cos(%s)" (tup_data x) // ws: as above
                    | PrimToString, [x] ->
                        match x with
                        | DLit(LitBool _) | DV(L(_,YPrim BoolT)) -> sprintf "(\"true\" if %s else \"false\")" (tup_data x)
                        | DLit(LitChar _) | DV(L(_,YPrim CharT)) -> tup_data x
                        | _ -> sprintf "str(%s)" (tup_data x)
                    | NanIs, [x] -> import "math"; sprintf "math.isnan(%s)" (tup_data x)
                    // ws: workspace-only ops (portable flush and delay, see the C backend).
                    | StdoutFlush, [] -> import "sys"; "sys.stdout.flush()"
                    | MonotonicDelayMs, [duration] -> import "time"; sprintf "time.sleep(%s / 1000)" (tup_data duration)
                    | UnionTag, [DUnion(_,l) | DV(L(_,YUnion l)) as x] -> sprintf "%s.tag" (tup_data x)
                    | Printf, [DLit (LitString fmt); b] ->
                        match printf_pieces fmt (data_term_vars b) |> List.map (function Choice1Of2 t -> lit (LitString t) | Choice2Of2 (_, a) -> show_w a) with
                        | [] -> "pass"
                        | [x] -> $"print({x}, end='')"
                        | l -> String.concat ", " l |> sprintf "print(%s, sep='', end='')"
                    | _ -> raise_codegen_error <| sprintf "Compiler error: %A with %i args not supported" op l.Length
                    |> return'
            and uheap : _ -> UnionRec = union (fun s x ->
                let cases = x.free_vars |> Map.toArray |> Array.map (fun ((i : int, _), _) -> "\"" + generatedCaseNameOfTag (sprintf "UH%i" x.tag) x.free_vars i + "\"") |> function [|x|] -> x | x -> x |> String.concat ", " |> sprintf "Union[%s]"
                code_env.fwd_dcls_types.Add $"UH{x.tag} = {cases}\n" // ws: the newline; upstream joined the aliases straight into the next line (py_checks: SyntaxError)
                x.free_vars |> Map.iter (fun ((i : int, _) as k) a ->
                    let case_name = generatedCaseNameOfTag (sprintf "UH%i" x.tag) x.free_vars i
                    line s $"class {case_name}(NamedTuple): # {snd k}" // ws: `snd k` (cases keyed `tag * name`)
                    let body = indent s
                    a |> Array.iter (fun (L(i,t)) -> line body $"v{i} : {annot t}")
                    line body $"tag = {i}"
                    if a.Length = 0 then line s $"{case_name}_shared = {case_name}()"
                    )
                )
            and ustack : _ -> UnionRec = union (fun s x ->
                x.free_vars |> Map.iter (fun ((i : int, _) as k) a ->
                    let case_name = generatedCaseNameOfTag (sprintf "US%i" x.tag) x.free_vars i
                    line s $"class {case_name}(NamedTuple): # {snd k}" // ws: `snd k`
                    let body = indent s
                    a |> Array.iter (fun (L(i,t)) -> line body $"v{i} : {annot t}")
                    line body $"tag = {i}"
                    if a.Length = 0 then line s $"{case_name}_shared = {case_name}()"
                    )
                let cases = x.free_vars |> Map.toArray |> Array.map (fun ((i : int, _), _) -> generatedCaseNameOfTag (sprintf "US%i" x.tag) x.free_vars i) |> function [|x|] -> x | x -> x |> String.concat ", " |> sprintf "Union[%s]"
                line s $"US{x.tag} = {cases}"
                )
            and heap : _ -> LayoutRec = layout (fun s x ->
                line s $"class Heap{x.tag}(NamedTuple):"
                let s = indent s
                if x.free_vars.Length = 0 then line s "pass"
                else x.free_vars |> Array.iter (fun (L(i,t)) -> line s $"v{i} : {annot t}")
                )
            and mut : _ -> LayoutRec = layout (fun s x ->
                line s "@dataclass"
                line s $"class Mut{x.tag}:"
                let s = indent s
                if x.free_vars.Length = 0 then line s "pass"
                else x.free_vars |> Array.iter (fun (L(i,t)) -> line s $"v{i} : {annot t}")
                )
            and method : _ -> MethodRec =
                jp false (fun ((jp_body,key),i) -> // ws: the key's shape differs per core
                    let a, range, name = codegenMethodBody part_eval_env backend_name jp_body key // ws: CodegenAdapter (raises on a malformed table)
                    {tag=i; free_vars=rdata_free_vars (codegenMethodKeyArgs key); range=range; body=a; name=generatedMethodName name i}
                    ) (fun s x ->
                    let method_args = x.free_vars |> Array.map (fun (L(i,t)) -> $"v{i} : {annot t}") |> String.concat ", "
                    line s $"def {x.name}({method_args}) -> {tup_annot x.range}:"
                    let saved = self_loop.Value
                    if self_tail x.tag x.body then // ws: see self_loop
                        self_loop.Value <- Some (x.tag, x.free_vars)
                        line (indent s) "while True:"
                        binds_start x.free_vars (indent (indent s)) x.body
                    else
                        self_loop.Value <- None
                        binds_start x.free_vars (indent s) x.body
                    self_loop.Value <- saved
                    )
            and self_tail tag (body : TypedBind []) = // ws: see self_loop
                body.Length > 0 &&
                match Array.last body with
                | TyLocalReturnOp(_, TyJoinPoint(JPMethod(a,c),_), _) -> (method (a,c)).tag = tag
                | TyLocalReturnOp(_, TyIf(_,tr,fl), _) -> self_tail tag tr || self_tail tag fl
                | TyLocalReturnOp(_, TyUnionUnbox(_,_,on_succs,on_fail), _) -> (on_succs |> Map.exists (fun _ (_,b) -> self_tail tag b)) || (on_fail |> Option.exists (self_tail tag))
                | TyLocalReturnOp(_, TyIntSwitch(_,on_succ,on_fail), _) -> Array.exists (self_tail tag) on_succ || self_tail tag on_fail
                | TyLocalReturnOp(_, (TyDo b | TyIndent b), _) -> self_tail tag b
                | _ -> false
            and closure : _ -> ClosureRec =
                jp true (fun ((jp_body,key & (C(args,_,fun_ty))),i) ->
                    match fun_ty with
                    | YFun(domain,range,FT_Vanilla) ->
                        let domain_args, body, source_name = codegenClosureBody part_eval_env backend_name jp_body key // ws: CodegenAdapter (raises on a malformed table)
                        {tag=i; free_vars=rdata_free_vars args; domain=domain; domain_args=data_free_vars domain_args; range=range; body=body; name=generatedClosureName source_name i}
                    | YFun _ -> raise_codegen_error "Non-standard functions are not supported in the Python backend."
                    | _ -> raise_codegen_error "Compiler error: Unexpected type in the closure join point."
                    ) (fun s x ->
                    let env_args = x.free_vars |> Array.map (fun (L(i,t)) -> $"env_v{i} : {annot t}") |> String.concat ", "
                    line s $"def {x.name}({env_args}):"
                    let s = indent s
                    let inner_args = x.domain_args |> Array.map (fun (L(i,t)) -> $"v{i} : {annot t}") |> String.concat ", "
                    line s $"def inner({inner_args}) -> {tup_annot x.range}:"
                    let _ =
                        let s = indent s
                        if x.free_vars.Length > 0 then
                            let nonlocal_args = x.free_vars |> Array.map (fun (L(i,t)) -> $"env_v{i}") |> String.concat ", "
                            line s $"nonlocal {nonlocal_args}"
                            x.free_vars |> Array.map (fun (L(i,t)) -> $"v{i} = env_v{i}") |> String.concat "; " |> line s
                        let saved = self_loop.Value // ws: see self_loop
                        self_loop.Value <- None
                        binds_start x.free_vars s x.body
                        self_loop.Value <- saved
                    line s "return inner"
                    )

            fun (x : TypedBind []) ->
                from "dataclasses import dataclass"
                from "typing import NamedTuple, Union, Callable, Tuple"
                part_eval_env.globals |> Seq.toArray |> Array.iter global' // ws: globals collected by the partial evaluator (PartEvalResult.globals), as in CodegenC
                code_env.globals.Add "i8 = int; i16 = int; i32 = int; i64 = int; u8 = int; u16 = int; u32 = int; u64 = int; f32 = float; f64 = float; char = str; string = str"
                import "sys"
                code_env.globals.Add "sys.setrecursionlimit(1 << 30)"
                code_env.globals.Add ""

                let s = {text=StringBuilder(); indent=0}

                line s "def main():"
                binds_start [||] (indent s) x
                s.text.AppendLine() |> ignore

                match Array.tryLast x with
                | Some (TyLocalReturnData(d,_)) | Some (TyLocalReturnOp(_,_,d)) when (match data_term_vars d with [|WV(L(_,YPrim Int32T))|] | [|WLit (LitInt32 _)|] -> true | _ -> false) ->
                    import "sys"
                    line s "if __name__ == '__main__': sys.exit(main())"
                | _ -> line s "if __name__ == '__main__': main()"
                code_env.main_defs.Add(s.text.ToString())
                let reaches_arrays (texts : string ResizeArray) = texts |> Seq.exists (fun text -> System.Text.RegularExpressions.Regex.IsMatch(text, @"\bcp\.|\bcuda\b"))
                if [code_env.globals; code_env.types; code_env.functions; code_env.main_defs] |> List.exists reaches_arrays then code_env.globals.Insert(0, cupy_prelude)
                else
                    for parts in [code_env.functions; code_env.main_defs] do
                        for index = 0 to parts.Count - 1 do parts.[index] <- pythonWithoutDels parts.[index]

        let codegen (default_env : DefaultEnv) (file_path : string) part_eval_env (x : TypedBind[]) : GeneratedFile list = // ws: Startup. prefix and the annotation
            let g = codegenMemoTable HashIdentity.Structural // ws: CodegenAdapter's table (upstream's unused `cuda_kernels` builder is left out)

            let host_code_env = codegen_env.Create()
            let device_code_env = codegen_env.Create()

            let cuda_codegen =
                CodegenCpp.codegen' (fun (jp_body,key,r') previous_backend -> // ws: CodegenCpp (upstream: Cpp)
                    raise_codegen_error_backend r' $"The Cuda backend does not support nesting of backends."
                    ) part_eval_env (fun _ -> device_code_env)
            let python_code =
                codegen' (fun (jp_body,key,r') ->
                    let backend_name = codegenOwnerBackendName jp_body // ws: CodegenAdapter (hopac owners are not pairs)
                    match backend_name with
                    | "CudaDevice" ->
                        Utils.memoize g (fun (jp_body,key) ->
                            let args = rdata_free_vars (codegenMethodKeyArgs key) // ws: CodegenAdapter
                            let backend_entry_name = $"entry{g.Count}"
                            let a, _, _ = codegenMethodBody part_eval_env "CudaDevice" jp_body key // ws: CodegenAdapter (raises on a malformed table)
                            cuda_codegen (CodegenCpp.ArgsCudaDevice(args,a,backend_entry_name)) // ws: CodegenCpp
                            backend_entry_name
                            ) (jp_body,key)
                    | x -> raise_codegen_error_backend r' $"The Python + Cuda backend does not support the {x} backend."
                    ) part_eval_env host_code_env x

            let append_lines (l : string seq) = (StringBuilder(), l) ||> Seq.fold (fun s -> s.AppendLine)

            let file_name = System.IO.Path.GetFileNameWithoutExtension file_path // ws: System.IO qualified

            let aux_library_code =
                let dir f = codegen_runtime_file f // ws: CodegenUtils.codegen_runtime_file (upstream: next to the compiler DLL)
                let aux_library_code_python = dir "corelib.py"
                let aux_library_code_cuda =
                    // ws: the 0cb0fda0 corelib marks its members `__host__ __device__` and guards `__host__`, so upstream's
                    // plain `__host__` -> `__device__` gave `__device__ __device__` members and a second `#ifndef __device__`
                    // block. The kernel text is device-only, as with the older corelib: drop the `__host__` guard first.
                    System.Text.RegularExpressions.Regex.Replace(dir "corelib.cuh", @"^#ifndef __host__\r?\n#define __host__\r?\n#endif\r?\n", "", System.Text.RegularExpressions.RegexOptions.Multiline)
                        .Replace("__host__ __device__", "__device__").Replace("__host__", "__device__")
                    |> CodegenCpp.replace_default_types default_env // ws: CodegenCpp

                StringBuilder()
                    .AppendLine("kernels_aux = r\"\"\"")
                    .AppendLine(aux_library_code_cuda)
                    .AppendLine("\"\"\"")
                    .AppendLine(aux_library_code_python)
                    .ToString()

            let code_main =
                StringBuilder()
                    .AppendLine("kernels_main = r\"\"\"")
                    .AppendJoin("", device_code_env.globals)
                    .AppendJoin("", device_code_env.fwd_dcls_types)
                    .AppendJoin("", device_code_env.fwd_dcls_methods)
                    .AppendJoin("", device_code_env.fwd_dcls_main_defs)
                    .AppendJoin("", device_code_env.types)
                    .AppendJoin("", device_code_env.functions)
                    .AppendJoin("", device_code_env.main_defs)
                    .AppendLine("\"\"\"")
                    .Replace("__host__ __device__", "__device__")
                    .AppendLine($"from {file_name}_auto import *")
                    .AppendLine("kernels = kernels_aux + kernels_main")
                    .Append(host_code_env.globals |> append_lines)
                    .AppendJoin("", host_code_env.fwd_dcls_types)
                    .AppendJoin("", host_code_env.fwd_dcls_methods)
                    .AppendJoin("", host_code_env.fwd_dcls_main_defs)
                    .AppendJoin("", host_code_env.types)
                    .AppendJoin("", host_code_env.functions)
                    .AppendJoin("", host_code_env.main_defs)
                    .ToString()

            [
                {|code = aux_library_code; file_extension = "_auto.py"|}
                {|code = code_main; file_extension = ".py"|}
            ]
    /// ## WDiff
    // open System
    open System.IO
    open System.Collections.Generic
    

    // Full name: Microsoft.FSharp.Core.Result<_,_>.Ok
    

    open FSharp.Core
    

    open Hopac
    open Hopac.Infixes
    open Hopac.Extensions
    open Hopac.Stream
    

    /// ### process_errors
    let process_errors line (ers : LineTokenErrors list) : RString list =
        ers |> List.mapi (fun i l ->
            let i = line + i
            l |> List.map (fun (r,x) -> x, ({|line=i; character=r.from|}, {|line=i; character=r.nearTo|}))
            )
        |> List.concat
        |> List.groupBy snd
        |> List.map (fun (k,v) -> k, process_error (List.map fst v))
    

    type [<ReferenceEquality>] TokenizerState = {
        lines_text : string PersistentVector
        lines_token : LineTokens
        // The lexical state each line ends in, which the next one starts in (`tokenize_line`).
        lines_state : LexState PersistentVector
        blocks : LineTokens Block list
        // The error for a `"""` string or `(* *)` comment the file ends inside; `errors` starts with it.
        eof_errors : RString list
        errors : RString list
        }
    

    /// ### wdiff_tokenizer_init
    let wdiff_tokenizer_init = { lines_text = PersistentVector.empty; lines_token = PersistentVector.empty; lines_state = PersistentVector.empty; blocks = []; eof_errors = []; errors = [] }
    

    /// ### triple_balance
    let triple_balance (blk : LineTokens) =
        let count_in_line acc (line : LineToken PersistentVector) =
            PersistentVector.fold (fun acc (_, tok) ->
                match tok with
                | TokStringOpen -> acc + 1
                | TokStringClose -> acc - 1
                | _ -> acc) acc line
        PersistentVector.fold count_in_line 0 blk
    

    /// ### append_lines
    let append_lines (a : LineTokens) (b : LineTokens) : LineTokens =
        PersistentVector.fold (fun acc line -> PersistentVector.conj line acc) a b
    

    /// ### merge_triple_blocks
    let merge_triple_blocks (blocks : LineTokens Block list) : LineTokens Block list =
        let rec loop acc pending pendingBal rest =
            match pending, rest with
            | None, [] -> List.rev acc
            | Some p, [] -> List.rev (p :: acc)
            | None, x :: xs ->
                let bal = triple_balance x.block
                if bal = 0 then loop (x :: acc) None 0 xs
                else loop acc (Some x) bal xs
            | Some p, x :: xs ->
                let merged =
                    {   block  = append_lines p.block x.block
                        offset = p.offset }
                let bal = pendingBal + triple_balance x.block
                if bal = 0 then loop (merged :: acc) None 0 xs
                else loop acc (Some merged) bal xs
        loop [] None 0 blocks
    

    /// ### lex_state_at
    /// The lexical state line `i` starts in.
    let lex_state_at (state : TokenizerState) i = if i = 0 then lex_state_init else state.lines_state.[i-1]
    

    /// ### replace'
    /// Immutably updates the state based on the request. Does diffing to make the operation efficient.
    /// It is possible for the server to go out of sync, in which case an error is returned.
    /// The edited lines are tokenized in the lexical state the line before them ends in, and the edit grows over
    /// the lines after it for as long as their start state changed (an edit that opens or closes a `"""` string
    /// or a `(* *)` comment re-tokenizes the lines it captures or releases, and only those).
    let replace' (state : TokenizerState) (edit : SpiEdit) =
        let old_length = state.lines_text.Length
        let toks = ResizeArray()
        let ers = ResizeArray()
        let states = ResizeArray()
        let lines = ResizeArray(edit.lines)
        let tokenize_next lex text =
            let a, b, lex = tokenize_line lex text
            toks.Add a; ers.Add b; states.Add lex
            lex
        let mutable lex = Array.fold tokenize_next (lex_state_at state edit.from) edit.lines
        let mutable nearTo = edit.nearTo
        while nearTo < old_length && lex <> lex_state_at state nearTo do
            let text = state.lines_text.[nearTo]
            lines.Add text
            lex <- tokenize_next lex text
            nearTo <- nearTo + 1
        let edit : SpiEdit = {|from=edit.from; nearTo=nearTo; lines=lines.ToArray()|}
        let lines_text = replace edit.from edit.nearTo edit.lines state.lines_text
        let lines_token = replace edit.from edit.nearTo toks state.lines_token
        let lines_state = replace edit.from edit.nearTo states state.lines_state
        let errors =
            let adj = edit.lines.Length - (edit.nearTo - edit.from)
            List.skip state.eof_errors.Length state.errors |> List.choose (fun ((a : VSCPos,b),c as x) ->
                if edit.from <= a.line && a.line < edit.nearTo then None
                elif edit.nearTo <= a.line && adj <> 0 then Some (add_line_to_range adj (a,b),c)
                else Some x
                )
        let errors = List.append errors (process_errors edit.from (List.ofSeq ers))
        let eof_errors =
            let last = lines_state.Length - 1
            match lex_state_error (if last < 0 then lex_state_init else lines_state.[last]) with
            | Some message ->
                // Reported on the line the unterminated string or comment opens in.
                let mutable i = last
                while 0 < i && lines_state.[i-1] <> lex_state_init do i <- i - 1
                process_errors i [[({from=0; nearTo=max 1 lines_text.[i].Length}, message)]]
            | None -> []
        let blocks =
            wdiff_block_all state.blocks (lines_token, edit.lines.Length, edit.from, edit.nearTo)
            |> merge_triple_blocks
        {lines_text=lines_text; lines_token=lines_token; lines_state=lines_state; blocks=blocks; eof_errors=eof_errors; errors=List.append eof_errors errors}
    

    /// ### wdiff_tokenizer_all
    let wdiff_tokenizer_all (state : TokenizerState) text =
        let text = (*Utils.*)lines text
        let text' = state.lines_text |> Seq.toArray
        // The edit is the text between the longest common prefix and the longest common suffix that doesn't
        // overlap it.
        let common = min text.Length text'.Length
        let mutable from = 0
        while from < common && text.[from] = text'.[from] do from <- from + 1
        if from = text.Length && text.Length = text'.Length then state else
        let mutable fromRev = 0
        while fromRev < common - from && text.[text.Length-1-fromRev] = text'.[text'.Length-1-fromRev] do fromRev <- fromRev + 1
        replace' state {|from=from; nearTo=text'.Length-fromRev; lines=text.[from..text.Length-1-fromRev]|}
    

    /// ### wdiff_tokenizer_edit
    let wdiff_tokenizer_edit (state : TokenizerState) (edit : SpiEdit) =
        if edit.nearTo <= state.lines_text.Length then
            Ok (replace' state edit)
        else
            Error "The edit is out of bounds and cannot be applied. The language server and the editor are out of sync. Try reopening the file being edited."
    

    /// ### semantic_updates_apply
    let semantic_updates_apply (block : LineTokens) updates =
        Seq.fold (fun (block : LineTokens) (c : VectorCord, l) ->
            if c.row < block.Length then
                let line = block.[c.row]
                if c.col < line.Length then
                    let r, tok = line.[c.col]
                    let tok' =
                        match tok with
                        | TokVar(a,_) -> TokVar(a,l)
                        | TokSymbol(a,_) -> TokSymbol(a,l)
                        | TokOperator(a,_) -> TokOperator(a,l)
                        | TokUnaryOperator(a,_) -> TokUnaryOperator(a,l)
                        | x -> x
                    PersistentVector.updateNth c.row c.col (r, tok') block
                else block
            else block) block updates
    


    /// ### raw_string_layout
    /// The column each token lays out at, and the text of raw strings without their indentation. A string or macro
    /// that closes on a later line than it opens carries its opening column: what follows the close on that line
    /// lays out past the opener, so `f """...\n""" x` applies `f` to `x` like a one-line string would. A raw string
    /// whose closing quotes start their line after `w` spaces is a block: each line after the opener's drops `w`
    /// spaces, the newline before the closing line is dropped, and so is the opener's when nothing follows it.
    let raw_string_layout (tokens : (VSCRange * SpiralToken) []) =
        let layout = Array.zeroCreate tokens.Length
        let opens = System.Collections.Generic.Stack<int>()
        let mutable errors = []
        let mutable row = -1
        let mutable shift = 0
        let dedent opener closer =
            let open_row = (fst (fst tokens.[opener])).line
            let close_row = (fst (fst tokens.[closer])).line
            let indent =
                if (fst (fst tokens.[closer])).character = 0 then Some 0
                else
                    match tokens.[closer - 1] with
                    | (a, _), TokText x when a.line = close_row && a.character = 0 && x.Trim(' ') = "" -> Some x.Length
                    | _ -> None
            match indent with
            | Some w when 0 < w ->
                let prefix = System.String(' ', w)
                let mutable last_line = -1
                for j in opener + 1 .. closer - 1 do
                    match tokens.[j] with
                    | (a, _ as r), TokText x when a.line = open_row ->
                        if x = "\n" then tokens.[j] <- r, TokText ""
                        last_line <- j
                    | (a, _ as r), TokText _ when a.line = close_row -> tokens.[j] <- r, TokText ""
                    | r, TokText x ->
                        let line = x.TrimEnd('\n')
                        if line.StartsWith(prefix, StringComparison.Ordinal) then tokens.[j] <- r, TokText (x.Substring w)
                        elif line.Trim(' ') = "" then tokens.[j] <- r, TokText "\n"
                        else errors <- (r, RawStringLineUnderIndented) :: errors
                        last_line <- j
                    | _ -> ()
                if 0 <= last_line then
                    match tokens.[last_line] with
                    | r, TokText x when x.EndsWith '\n' -> tokens.[last_line] <- r, TokText (x.Substring(0, x.Length - 1))
                    | _ -> ()
            | _ -> ()
        let mutable row_start = 0
        for i in 0 .. tokens.Length - 1 do
            let (a, _), t = tokens.[i]
            if a.line <> row then
                row <- a.line
                row_start <- i
                shift <- 0
            let close_spanning_lines () =
                let opener = opens.Pop()
                let (open_from, open_to), _ = tokens.[opener]
                if open_from.line <> a.line then
                    shift <- layout.[opener] + 1
                    for j in row_start .. i - 1 do layout.[j] <- (fst (fst tokens.[j])).character + shift
                    Some (opener, 3 <= open_to.character - open_from.character)
                else None
            match t with
            | TokStringClose when 0 < opens.Count ->
                match close_spanning_lines () with
                | Some (opener, true) -> dedent opener i
                | _ -> ()
            | TokMacroClose when 0 < opens.Count -> close_spanning_lines () |> ignore
            | _ -> ()
            layout.[i] <- a.character + shift
            match t with
            | TokStringOpen | TokMacroOpen -> opens.Push i
            | _ -> ()
        layout, List.rev errors

    /// ### parse_block
    let parse_block default_env is_top_down (block : LineTokens) =
        let comments, cords_tokens =
            Array.init block.Length (fun line ->
                let x = block.[line]
                let comment, len =
                    match PersistentVector.tryLast x with
                    | Some (r, TokComment c) -> Some (r, c), x.Length - 1
                    | _ -> None, x.Length
                let tokens = Array.init len (fun i ->
                    let r, t = x.[i]
                    {|row=line; col=i|},
                    (({| line=line; character=r.from |}, {| line=line; character=r.nearTo |}), t))
                comment, tokens
                )
            |> Array.unzip
        let cords, tokens = Array.unzip (Array.concat cords_tokens)
        let layout_columns, raw_string_errors = raw_string_layout tokens

        let semantic_updates = ResizeArray()
        let env = {
            tokens_cords = cords; semantic_updates = semantic_updates
            comments = comments; tokens = tokens; layout_columns = layout_columns; i = ref 0; is_top_down = is_top_down
            default_env = default_env
            continuation_column = None
            operator_floor = None
            }
        assert (env.tokens_cords.Length = env.tokens.Length)
        let result = if List.isEmpty raw_string_errors then blockParsingParse env else Error raw_string_errors
        {result=result; semantic_tokens=semantic_updates_apply block semantic_updates}
    

    /// ### wdiff_parse_init
    let wdiff_parse_init is_top_down : ParserState = {is_top_down=is_top_down; blocks=[]}
    

    /// ### wdiff_parse
    let wdiff_parse default_env (state : ParserState) (unparsed_blocks : LineTokens Block list) =
        let dict = Collections.Concurrent.ConcurrentDictionary(HashIdentity.Reference)
        // Offset should be ignored when memoizing the results of parsing.
        List.iter (fun (a,b) -> dict.TryAdd(a,b.block) |> ignore) state.blocks
        let blocks = unparsed_blocks |> List.map (fun x ->
            x.block, {block=memoize dict (fun a -> Promise.Now.withValue ((parse_block default_env state.is_top_down) a)) x.block; offset=x.offset}
            )
        {state with blocks = blocks }
    

    /// ### ModuleState
    type ModuleState = { tokenizer : TokenizerState; bundler : BlockBundleState; parser : ParserState }
    

    /// ### wdiff_module_init
    let wdiff_module_init is_top_down = {tokenizer = wdiff_tokenizer_init; bundler = wdiff_block_bundle_init; parser = wdiff_parse_init is_top_down}
    

    /// ### wdiff_module_body
    let wdiff_module_body default_env state tokenizer =
        if state.tokenizer = tokenizer then state else
        let parser = wdiff_parse default_env state.parser tokenizer.blocks
        let bundler = wdiff_block_bundle state.bundler parser
        {tokenizer=tokenizer; parser=parser; bundler=bundler}
    

    /// ### wdiff_module_edit
    let wdiff_module_edit default_env (state : ModuleState) x = wdiff_tokenizer_edit state.tokenizer x |> Result.map (wdiff_module_body default_env state)
    

    /// ### wdiff_module_all
    let wdiff_module_all default_env state x = wdiff_tokenizer_all state.tokenizer x |> wdiff_module_body default_env state
    

    /// ### wdiff_module_init_all
    let wdiff_module_init_all default_env is_top_down x = wdiff_module_all default_env (wdiff_module_init is_top_down) x
    

    /// ### FileState<'input,'result,'state>
    type [<ReferenceEquality>] FileState<'input,'result,'state> = { input : 'input; result : 'result; state : 'state }
    

    /// ### FileFuns<'a,'b,'state>
    type FileFuns<'a,'b,'state> =
        abstract member eval : 'state * 'a -> 'b
        abstract member diff : 'state * 'b * 'a -> 'b
        abstract member init : 'a -> FileState<'a,'b,'state>
    

    /// ### TypecheckerStateValue
    type TypecheckerStateValue = Bundle option * InferResult * TopEnv
    

    /// ### TypecheckerStatePropagated
    type TypecheckerStatePropagated = (bool * TopEnv) Promise
    

    /// ### TypecheckerState
    type TypecheckerState = FileState<PackageId * ModuleId * BlockBundleState, TypecheckerStateValue Stream, TypecheckerStatePropagated>
    

    /// ### AutoExportCurried
    module AutoExportCurried =
        let trace = System.Environment.GetEnvironmentVariable "SPIRAL_AUTO_EXPORT_TRACE" = "1"
        let synthesize bundle =
            match bundle with
            | BundleInl(com, r, (rn, name), term, td) ->
                let rec parameters (e : RawExpr) acc =
                    match e with
                    | RawFun(_, [ (PatAnnot(_, PatVar(_, v), t), body) ]) -> parameters body ((v, t) :: acc)
                    | RawAnnot(_, _, t) -> List.rev acc, Some t
                    | _ -> List.rev acc, None
                let ps, result = parameters term []
                let rec poly (t : RawTExpr) =
                    match t with
                    | RawTMetaVar _ | RawTWildcard _ | RawTForall _ | RawTExists _ | RawTTypecase _ | RawTTerm _ | RawTMacro _ -> true
                    | RawTPair(_, a, b) | RawTFun(_, a, b, _) | RawTApply(_, a, b) -> poly a || poly b
                    | RawTArray(_, a) | RawTLayout(_, a, _) -> poly a
                    | RawTRecord(_, m) -> m |> Map.exists (fun _ v -> poly v)
                    | RawTUnion(_, m, _, _) -> m |> Map.exists (fun _ (_, v) -> poly v)
                    | _ -> false
                if ps.Length < 2 || result.IsNone || ps |> List.exists (snd >> poly) || (result |> Option.exists poly) then None
                else
                    let ps = ps |> List.mapi (fun i (_, t) -> $"auto_export_arg{i}", t)
                    let pattern = ps |> List.map (fun (v, _) -> PatVar(r, v)) |> List.reduceBack (fun a b -> PatPair(r, a, b))
                    let domain = ps |> List.map snd |> List.reduceBack (fun a b -> RawTPair(r, a, b))
                    let call = ps |> List.fold (fun acc (v, _) -> RawApply(r, acc, RawV(r, v, false))) (RawV(r, name, false))
                    let body = match result with Some t -> RawAnnot(r, call, t) | None -> call
                    if trace then eprintfn "auto-export: synthesized %s__uncurried of arity %d" name ps.Length
                    Some (BundleInl(com, r, (rn, name + "__uncurried"), RawFun(r, [ (PatAnnot(r, pattern, domain), body) ]), td))
            | _ -> None

    /// ### typecheck
    let rec typecheck (package_id,module_id,env : TopEnv) x = x >>=* function
        | Cons((_,b : BlockBundleValue), ls) ->
            match b.bundle with
            | Some bundle ->
                let x = infer package_id module_id env bundle
                let x =
                    match bundle with
                    | BundleInl(com, r, w, body, true) when x.self_unbound && not (upstreamDialectPids.ContainsKey package_id) ->
                        infer package_id module_id env (BundleRecInl([ com, r, w, body ], true))
                    | _ -> x
                let adds = match x.top_env_additions with AOpen x | AInclude x | AIncludePrivate (_, x) -> x
                let env = inferUnion adds env
                match (if autoExportPids.ContainsKey package_id then AutoExportCurried.synthesize bundle else None) with
                | Some extra ->
                    let x2 = infer package_id module_id env extra
                    let adds2 = match x2.top_env_additions with AOpen x | AInclude x | AIncludePrivate (_, x) -> x
                    let env2 = inferUnion adds2 env
                    Job.result (Cons((b.bundle,x,env), Promise.Now.withValue (Cons((Some extra,x2,env2), typecheck (package_id,module_id,env2) ls))))
                | None ->
                    Job.result (Cons((b.bundle,x,env),typecheck (package_id,module_id,env) ls))
            | None ->
                typecheck (package_id,module_id,env) ls :> _ Job
        | Nil ->
            Job.result Nil
    

    /// ### diff
    let rec diff (package_id,module_id,env) (result,input : BlockBundleState) =
        let tc () = typecheck (package_id,module_id,env) input
        if Promise.Now.isFulfilled result then
            input >>** fun input ->
            match Promise.Now.get result,input with
            | Cons((b',_,env as x),next), Cons((_,b),bs) when b' = b.bundle -> Promise.Now.withValue (Cons(x,diff (package_id,module_id,env) (next,bs)))
            | _ -> tc()
        else tc()
    

    /// ### funs_file_tc
    let funs_file_tc = {new FileFuns<PackageId * ModuleId * BlockBundleState, TypecheckerStateValue Stream, TypecheckerStatePropagated> with
        member _.eval(state,(pid,mid,x)) =
            state >>=* fun (_,env) ->
            typecheck (pid,mid,env) x
        member _.diff(state,b,(pid,mid,a)) =
            state >>=* fun (_,env) -> diff (pid,mid,env) (b,a)
        member _.init x = {
            input = x
            result = Promise.Now.never()
            state = Promise.Now.never()
            }
        }
    

    /// ### wdiff_file_update_state
    let wdiff_file_update_state (funs : FileFuns<'a,'b,'state>) (state : FileState<'a,'b,'state>) (x : 'state) =
        if state.state = x then state else {state with state=x; result=funs.eval(x,state.input)}
    

    /// ### wdiff_file_update_input
    let wdiff_file_update_input (funs : FileFuns<'a,'b,'state>) (state : FileState<'a,'b,'state>) (x : 'a) =
        if state.input = x then state else {state with input=x; result=funs.diff(state.state,state.result,x)}
    

    /// ### wdiff_file
    let wdiff_file (funs : FileFuns<'a,'b,'state>) (state : FileState<'a,'b,'state>) (a,b) =
        if state.state = a then wdiff_file_update_input funs state b else {state=a; input=b; result=funs.eval(a,b)}
    

    /// ### ProjFilesTree
    type ProjFilesTree =
        | File of module_id: ModuleId * path: string * name: string option
        | Directory of dir_id: DirId * name: string * ProjFilesTree list
    

    /// ### ProjFiles
    type ProjFiles = { tree : ProjFilesTree list; num_dirs : int; num_files : int }
    

    /// ### ProjFileFuns<'a,'state>
    type ProjFileFuns<'a,'state> =
        abstract member file : string option * 'state * 'a -> 'a * 'state
        abstract member union : 'state * 'state -> 'state
        abstract member in_module : string * 'state -> 'state
        abstract member default' : DefaultEnv -> 'state
        abstract member empty : 'state
    

    /// ### ProjFilesState<'a,'state>
    type [<ReferenceEquality>] ProjFilesState<'a,'state> = {
        init : 'state
        uids_file : ('a * 'state) []
        uids_directory : 'state []
        files : ProjFiles
        result : 'state
        }
    

    /// ### proj_files_diff
    let proj_files_diff (uids_file : ('a * 'b) [], uids_directory : 'b [], files) (uids, files') =
        let uids_file' = Array.zeroCreate (Array.length uids)
        let uids_directory' = Array.zeroCreate files'.num_dirs
        // Ref equality is done first for performance. Most of the time the strings will be the same.
        let eq a b = System.Object.ReferenceEquals(a,b) || a = b
        let rec loop = function
            | File(mid,path,name), File(mid',path',name') when mid = mid' && eq path path' && eq name name' ->
                let x = uids_file.[mid]
                if uids.[mid] = fst x then uids_file'.[mid] <- x; true else false
            | Directory(uid,name,l), Directory(uid',name',l') when uid = uid' && eq name name' && list (l,l') ->
                uids_directory'.[uid] <- uids_directory.[uid]; true
            | _ -> false
        and list = function
            | x :: xs, y :: ys -> loop (x,y) && list (xs,ys)
            | _ -> false
        if list (files.tree, files'.tree) then None else Some (uids_file',uids_directory')
    

    /// ### proj_files
    let proj_files (funs : ProjFileFuns<'a,'state>) uids_file uids_directory uids s l =
        let memo (uids : _ []) uid f =
            let x = uids.[uid]
            if isNull (box x) then let x = f() in uids.[uid] <- x; x
            else x
        let rec loop state = function
            | File(mid,_,name) -> memo uids_file mid (fun () -> funs.file(name,state,Array.get uids mid)) |> snd
            | Directory(uid,name,l) -> memo uids_directory uid (fun () -> funs.in_module(name,list state l))
        and list s l =
            List.fold (fun (empty,big) x ->
                let small = loop big x
                funs.union(small,empty), funs.union(small,big)
                ) (funs.empty, s) l |> fst
        list s l.tree
    

    /// ### wdiff_proj_files_update_files
    let wdiff_proj_files_update_files (funs : ProjFileFuns<'a,'state>) (state : ProjFilesState<'a,'state >) (uids,files : ProjFiles) =
        match proj_files_diff (state.uids_file,state.uids_directory,state.files) (uids,files) with
        | Some (uids_file, uids_directory) -> {state with files=files; uids_file=uids_file; uids_directory=uids_directory; result=proj_files funs uids_file uids_directory uids state.init files}
        | None -> state
    

    /// ### wdiff_proj_files_update_packages
    let wdiff_proj_files_update_packages (funs : ProjFileFuns<'a,'state>) (state : ProjFilesState<'a,'state >) (init : 'state) =
        if state.init = init then state else
        let uids_file, uids_directory = Array.zeroCreate state.uids_file.Length, Array.zeroCreate state.uids_directory.Length
        let uids = HopacExtensions.S.map fst state.uids_file
        {state with init=init; uids_file=uids_file; uids_directory=uids_directory; result=proj_files funs uids_file uids_directory uids init state.files}
    

    /// ### wdiff_proj_files
    let wdiff_proj_files (funs : ProjFileFuns<'a,'state>) (state : ProjFilesState<'a,'state >) (init,(uids,files)) =
        if state.init = init then wdiff_proj_files_update_files funs state (uids,files)
        else
            let uids_file, uids_directory = Array.zeroCreate files.num_files, Array.zeroCreate files.num_dirs
            {files=files; init=init; uids_file=uids_file; uids_directory=uids_directory; result=proj_files funs uids_file uids_directory uids init files}
    

    /// ### typechecker_results_summary
    let typechecker_results_summary l =
        Stream.foldFun (fun (has_error,big) (_,x : InferResult,_) ->
            has_error || List.isEmpty x.errors = false,
            match x.top_env_additions with
            | AOpen _ -> big
            | AInclude small | AIncludePrivate (small, _) -> inferUnion small big
            ) (false,inferTop_env_empty) l
    

    /// ### funs_proj_file_tc
    let funs_proj_file_tc = {new ProjFileFuns<TypecheckerState,TypecheckerStatePropagated> with
        member _.file(name,state,x) =
            let x = wdiff_file_update_state funs_file_tc x state
            let env =
                typechecker_results_summary x.result >>-* fun (has_error,env) ->
                has_error, match name with None -> env | Some name -> inferIn_module name env
            x,env
        member _.union(small,big) = small >>=* fun small -> big >>- fun big -> fst small || fst big, inferUnion (snd small) (snd big)
        member _.in_module(name,small) = small >>-* fun (has_error,env) -> has_error, inferIn_module name env
        member _.default' default_env = Promise.Now.withValue (false,inferTop_env_default default_env)
        member _.empty = Promise.Now.withValue (false,inferTop_env_empty)
        }
    

    /// ### PackageEnv
    type PackageEnv = {
        nominals_aux : Map<PackageId,Map<GlobalId, {|name : NominalNameId; kind : TT|}>>
        nominals : Map<PackageId,Map<GlobalId, {|vars : Var list; body : T|}>>
        prototypes_instances : Map<PackageId,Map<GlobalId * GlobalId, Constraint Set list>>
        prototypes : Map<PackageId,Map<GlobalId, {|name : PrototypeNameId; signature : T; kind : TT|}>>
        ty : Map<TypeNameId,T>
        term : Map<TermNameId,T>
        constraints : Map<ConstraintNameId,ConstraintOrModule>
        }
    

    /// ### union
    let union small big = {
        nominals_aux = Map.foldBack Map.add small.nominals_aux big.nominals_aux
        nominals = Map.foldBack Map.add small.nominals big.nominals
        prototypes_instances = Map.foldBack Map.add small.prototypes_instances big.prototypes_instances
        prototypes = Map.foldBack Map.add small.prototypes big.prototypes
        ty = Map.foldBack Map.add small.ty big.ty
        term = Map.foldBack Map.add small.term big.term
        constraints = Map.foldBack Map.add small.constraints big.constraints
        }
    

    /// ### in_moduleWDiff
    let in_moduleWDiff m (a : PackageEnv) =
        {a with
            ty = Map.add (TypeNameIdOps.create m) (TyModule (typeMapToModuleMembers a.ty)) Map.empty
            term = Map.add (TermNameIdOps.create m) (TyModule (termMapToModuleMembers a.term)) Map.empty
            constraints = Map.add (ConstraintNameIdOps.create m) (M a.constraints) Map.empty
            }
    

    /// ### package_to_file
    let package_to_file (x : PackageEnv) = {
        nominals_next_tag = 0
        nominals_aux = Map.foldBack (fun _ -> Map.foldBack Map.add) x.nominals_aux Map.empty
        nominals = Map.foldBack (fun _ -> Map.foldBack Map.add) x.nominals Map.empty
        prototypes_next_tag = 0
        prototypes_instances = Map.foldBack (fun _ -> Map.foldBack Map.add) x.prototypes_instances Map.empty
        prototypes = Map.foldBack (fun _ -> Map.foldBack Map.add) x.prototypes Map.empty
        ty = x.ty
        term = x.term
        constraints = x.constraints
        }
    

    /// ### add_file_to_package
    let add_file_to_package package_id (small : TopEnv) (big : PackageEnv): PackageEnv = {
        nominals_aux = Map.add package_id small.nominals_aux big.nominals_aux
        nominals = Map.add package_id small.nominals big.nominals
        prototypes_instances = Map.add package_id small.prototypes_instances big.prototypes_instances
        prototypes = Map.add package_id small.prototypes big.prototypes
        ty = small.ty
        term = small.term
        constraints = small.constraints
        }
    

    /// ### package_env_empty
    let package_env_empty = {
        nominals_aux = Map.empty
        nominals = Map.empty
        prototypes_instances = Map.empty
        prototypes = Map.empty
        ty = Map.empty
        term = Map.empty
        constraints = Map.empty
        }
    

    /// ### package_env_default
    let package_env_default default_env =
        let x = inferTop_env_default default_env
        {package_env_empty with ty = x.ty; term = x.term; constraints = x.constraints}
    

    /// ### ProjPackagesState<'a>
    type ProjPackagesState<'a> = {
        packages : (string option * 'a) list
        result : 'a
        }
    

    /// ### ProjState<'file_inputs,'files,'packages>
    type ProjState<'file_inputs,'files,'packages> = {
        package_id : PackageId
        packages : 'packages ProjPackagesState
        files : ProjFilesState<'file_inputs,'files>
        result : 'packages
        }
    

    /// ### TypecheckerStateTop
    type TypecheckerStateTop = (bool * PackageEnv) Promise
    

    /// ### ProjStateTC
    type ProjStateTC = ProjState<TypecheckerState,TypecheckerStatePropagated,TypecheckerStateTop>
    

    /// ### ProjEnvTC
    type ProjEnvTC = Map<PackageId,ProjStateTC>
    

    /// ### ProjPackageFuns<'file,'package>
    type ProjPackageFuns<'file,'package> =
        abstract member unions : DefaultEnv -> (string option * 'package) list -> 'package
        abstract member union : 'package * 'package -> 'package
        abstract member in_module : string * 'package -> 'package
        abstract member package_to_file : 'package -> 'file
        abstract member add_file_to_package : PackageId * 'file * 'package -> 'package
        abstract member default' : DefaultEnv -> 'package
        abstract member empty : 'package
    

    /// ### funs_proj_package_tc
    let funs_proj_package_tc = {new ProjPackageFuns<TypecheckerStatePropagated,TypecheckerStateTop> with
        member funs.unions default_env l =
            let f = function Some name, small -> funs.in_module(name,small) | None, small -> small
            let dependencies = List.fold (fun big x -> funs.union(f x,big)) (funs.default' default_env) l
            funs.union(funs.default' default_env, dependencies)
        member _.union(small,big) =
            Job.delay <| fun () ->
                if Promise.Now.isFulfilled big = false then HopacExtensions.start (big >>- ignore)
                small >>= fun a ->
                big >>- fun b ->
                fst a || fst b, union (snd a) (snd b)
            |> Hopac.memo
        member _.in_module(name,x) = x >>-* fun (has_error,env) -> has_error, in_moduleWDiff name env
        member _.package_to_file(x) = x >>-* fun (has_error,env) -> has_error, package_to_file env
        member _.add_file_to_package(pid,a,b) =
            a >>=* fun (has_error,env) ->
            b >>-* fun (has_error',env') ->
            has_error || has_error', add_file_to_package pid env env'
        member _.default' default_env = Promise.Now.withValue (false, package_env_default default_env)
        member _.empty = Promise.Now.withValue (false, package_env_empty)
        }
    

    /// ### wdiff_proj_init
    let wdiff_proj_init default_env (funs_packages : ProjPackageFuns<'file,'package>) (funs_files : ProjFileFuns<'file_input,'file>) package_id : ProjState<'file_input,'file,'package> =
        let packages = { packages = []; result = funs_packages.default' default_env}
        let files = {
            files={tree=[]; num_dirs=0; num_files=0}
            uids_file=[||]; uids_directory=[||]
            init=funs_files.default' default_env; result=funs_files.empty
            }
        let result = funs_packages.empty
        { package_id = package_id; packages = packages; files = files; result = result}
    

    /// ### wdiff_proj_packages
    let wdiff_proj_packages default_env (funs : ProjPackageFuns<_,'a>) (state : 'a ProjPackagesState) x =
        if state.packages = x then state else {packages = x; result = funs.unions default_env x }
    

    /// ### wdiff_proj_update_packages
    let wdiff_proj_update_packages default_env funs_packages funs_files (state : ProjState<'a,'b,'state>) x =
        let packages = wdiff_proj_packages default_env funs_packages state.packages x
        if state.packages = packages then state else
        let files = wdiff_proj_files_update_packages funs_files state.files (funs_packages.package_to_file(packages.result))
        let result = funs_packages.add_file_to_package(state.package_id,files.result,packages.result)
        {state with packages=packages; files=files; result=result}
    

    /// ### wdiff_proj_update_files
    let wdiff_proj_update_files (funs_packages : ProjPackageFuns<_,_>) funs_files (state : ProjState<'a,'b,'state>) x =
        let files = wdiff_proj_files_update_files funs_files state.files x
        if state.files = files then state else
        let result = funs_packages.add_file_to_package(state.package_id,files.result,state.packages.result)
        {state with files=files; result=result}
    

    /// ### wdiff_proj
    let wdiff_proj default_env (funs_packages : ProjPackageFuns<_,_>) funs_files (state : ProjState<'file_input,'file,'state>) (packages,files) =
        let packages = wdiff_proj_packages default_env funs_packages state.packages packages
        if state.packages = packages then wdiff_proj_update_files funs_packages funs_files state files
        else
            let files = wdiff_proj_files funs_files state.files (funs_packages.package_to_file(packages.result),files)
            let result = funs_packages.add_file_to_package(state.package_id,files.result,packages.result)
            {state with packages=packages; files=files; result=result}
    

    /// ### ProjEnvUpdate<'a>
    type ProjEnvUpdate<'a> =
        | UpdatePackageModule of PackageId * (string option * PackageId) list * ('a [] * ProjFiles)
        | UpdatePackage of PackageId * (string option * PackageId) list
    

    /// ### map_packages
    let map_packages s packages = packages |> List.map (fun (a,b) -> a, (Map.find b s).result)
    

    /// ### wdiff_projenv
    let wdiff_projenv (default_env_of : PackageId -> DefaultEnv) funs_packages funs_files (s : Map<PackageId,ProjState<'a,'b,'state>>) l =
        List.fold (fun s -> function
            | UpdatePackageModule(uid,packages,files) -> Map.add uid (wdiff_proj (default_env_of uid) funs_packages funs_files s.[uid] (map_packages s packages,files)) s
            | UpdatePackage(uid,packages) -> Map.add uid (wdiff_proj_update_packages (default_env_of uid) funs_packages funs_files s.[uid] (map_packages s packages)) s
            ) s l
    

    /// ## WDiffPrepass
    open Hopac
    open Hopac.Infixes
    open Hopac.Extensions
    open Hopac.Stream
    

    /// ### PrepassStateValue
    type PrepassStateValue = InferResult * PrepassTopEnv AdditionType * PrepassTopEnv
    

    /// ### PrepassStatePropagated
    type PrepassStatePropagated = PrepassTopEnv Promise
    

    /// ### PrepassState
    type PrepassState = FileState<PackageId * ModuleId * string * TypecheckerStateValue Stream, PrepassStateValue Stream, PrepassStatePropagated>
    

    /// ### prepass
    let rec prepass (package_id,module_id,path,env) = function
        | Cons((_,r,_) : TypecheckerStateValue, ls) ->
            r.filled_top >>- fun filled_top ->
            let x = (prepassPrepass package_id module_id path env).filled_top filled_top
            let adds = match x with AOpen x | AInclude x | AIncludePrivate (_, x) -> x
            let env = prepassUnion adds env
            Cons((r,x,env),ls >>=* prepass (package_id,module_id,path,env))
        | Nil ->
            Job.result Nil
    

    /// ### diffWDiffPrepass
    let rec diffWDiffPrepass (package_id,module_id,path,env) (result,input : TypecheckerStateValue Stream) =
        input >>** fun input ->
        let tc () = prepass (package_id,module_id,path,env) input |> Hopac.memo
        if Promise.Now.isFulfilled result then
            match Promise.Now.get result,input with
            | Cons((b',_,env as x),next), Cons((_,b,_),bs) when b' = b -> Cons(x,diffWDiffPrepass (package_id,module_id,path,env) (next,bs)) |> Promise.Now.withValue
            | _ -> tc()
        else tc()
    

    /// ### funs_file_prepass
    let funs_file_prepass = {new FileFuns<PackageId * ModuleId * string * TypecheckerStateValue Stream, PrepassStateValue Stream, PrepassStatePropagated> with
        member _.eval(state,(pid,mid,path,x)) =
            state >>=* fun env ->
            x >>= prepass (pid,mid,path,env)
        member _.diff(state,b,(pid,mid,path,a)) =
            state >>=* fun env -> diffWDiffPrepass (pid,mid,path,env) (b,a)
        member _.init x = {
            input = x
            result = Promise.Now.never()
            state = Promise.Now.never()
            }
        }
    

    /// ### prepass_results_summary
    let prepass_results_summary l =
        Stream.foldFun (fun big (_,x,_) ->
            match x with
            | AOpen _ -> big
            | AInclude small | AIncludePrivate (small, _) -> prepassUnion small big
            ) (prepassTop_env_empty) l
    

    /// ### funs_proj_file_prepass
    let funs_proj_file_prepass = {new ProjFileFuns<PrepassState,PrepassStatePropagated> with
        member _.file(name,state,x) =
            let x = wdiff_file_update_state funs_file_prepass x state
            let env =
                prepass_results_summary x.result >>-* fun env ->
                match name with None -> env | Some name -> in_modulePrepass name env
            x,env
        member _.union(small,big) = small >>=* fun small -> big >>- fun big -> prepassUnion small big
        member _.in_module(name,small) = small >>-* in_modulePrepass name
        member _.default' default_env = Promise.Now.withValue (prepassTop_env_default default_env)
        member _.empty = Promise.Now.withValue prepassTop_env_empty
        }
    

    /// ### PrepassPackageEnv
    type PrepassPackageEnv = {
        prototypes_instances : Map<int, Map<GlobalId * GlobalId,E>>
        nominals : Map<int, Map<GlobalId,{|body : TPrepass; name : string|}>>
        term : Map<TermNameId,E>
        ty : Map<TypeNameId,TPrepass>
        }
    

    /// ### unionWDiffPrepass
    let unionWDiffPrepass small big = {
        prototypes_instances = Map.foldBack Map.add small.prototypes_instances big.prototypes_instances
        nominals = Map.foldBack Map.add small.nominals big.nominals
        term = Map.foldBack Map.add small.term big.term
        ty = Map.foldBack Map.add small.ty big.ty
        }
    

    /// ### in_module
    let in_module m (a : PrepassPackageEnv) =
        {a with
            ty = Map.add (TypeNameIdOps.create m) (TModule a.ty) Map.empty
            term = Map.add (TermNameIdOps.create m) (EModule a.term) Map.empty
            }
    

    /// ### package_env_emptyWDiffPrepass
    let package_env_emptyWDiffPrepass = {
        prototypes_instances = Map.empty
        nominals = Map.empty
        term = Map.empty
        ty = Map.empty
        }
    

    /// ### package_to_fileWDiffPrepass
    let package_to_fileWDiffPrepass (x : PrepassPackageEnv) = {
        nominals_next_tag = 0
        nominals = Map.foldBack (fun _ -> Map.foldBack Map.add) x.nominals Map.empty
        prototypes_next_tag = 0
        prototypes_instances = Map.foldBack (fun _ -> Map.foldBack Map.add) x.prototypes_instances Map.empty
        ty = x.ty
        term = x.term
        }
    

    /// ### add_file_to_packageWDiffPrepass
    let add_file_to_packageWDiffPrepass package_id (small : PrepassTopEnv) (big : PrepassPackageEnv): PrepassPackageEnv = {
        nominals = Map.add package_id small.nominals big.nominals
        prototypes_instances = Map.add package_id small.prototypes_instances big.prototypes_instances
        ty = small.ty
        term = small.term
        }
    

    /// ### package_env_defaultWDiffPrepass
    let package_env_defaultWDiffPrepass default_env = { package_env_emptyWDiffPrepass with ty = (prepassTop_env_default default_env).ty }
    

    /// ### ProjStatePrepass
    type ProjStatePrepass = ProjState<PrepassState,PrepassStatePropagated,PrepassPackageEnv Promise>
    

    /// ### funs_proj_package_prepass
    let funs_proj_package_prepass = {new ProjPackageFuns<PrepassStatePropagated,PrepassPackageEnv Promise> with
        member funs.unions default_env l =
            let f = function Some name, small -> funs.in_module(name,small) | None, small -> small
            let dependencies = List.fold (fun big x -> funs.union(f x,big)) (funs.default' default_env) l
            funs.union(funs.default' default_env, dependencies)
        member _.union(small,big) =
            Job.delay <| fun () ->
                if Promise.Now.isFulfilled big = false then HopacExtensions.start (big >>- ignore)
                small >>= fun a -> big >>- unionWDiffPrepass a
            |> Hopac.memo
        member _.in_module(name,x) = x >>-* fun env -> in_module name env
        member _.package_to_file(x) = x >>-* package_to_fileWDiffPrepass
        member _.add_file_to_package(pid,a,b) =
            a >>=* fun env ->
            b >>-* add_file_to_packageWDiffPrepass pid env
        member _.default' default_env = Promise.Now.withValue (package_env_defaultWDiffPrepass default_env)
        member _.empty = Promise.Now.withValue package_env_emptyWDiffPrepass
        }
    

    /// ## SpiProj
    // Everything that deals with Spiral project files themselves goes here
    open FParsec
    // open Common

    /// ### RawFileHierarchy
    type RawFileHierarchy =
        | Directory of VSCRange * RString * RawFileHierarchy list
        | File of VSCRange * RString * is_top_down : bool * is_include : bool

    /// ### ConfigResumableError
    type ConfigResumableError =
        | DuplicateFiles of VSCRange [] []
        | DuplicateRecordFields of VSCRange [] []
        | MissingNecessaryRecordFields of string [] * VSCRange

    /// ### ConfigFatalError
    type ConfigFatalError =
        | Tabs of VSCRange []
        | ParserError of string * VSCRange

    /// ### ConfigException
    exception ConfigException of ConfigFatalError

    /// ### spaces_template
    let rec spaces_template s = (spaces >>. optional (followedByString "//" >>. skipRestOfLine true >>. spaces_template)) s

    /// ### spacesSpiProj
    let spacesSpiProj s = spaces_template s

    /// ### raise'
    let raise' x = raise (ConfigException x)

    /// ### raise_if_not_empty
    let raise_if_not_empty exn l = if Array.isEmpty l = false then raise' (exn l)

    /// ### add_to_exception_list'
    let add_to_exception_list' (p: CharStream<ResizeArray<ConfigResumableError>>) = p.State.UserState.Add

    /// ### add_to_exception_list
    let add_to_exception_list (p: CharStream<ResizeArray<ConfigResumableError>>) exn l = if Array.isEmpty l = false then p.State.UserState.Add (exn l)

    /// ### column
    let column (p : CharStream<_>) = p.Column

    /// ### pos
    let pos (p : CharStream<_>) : VSCPos = {|line=int p.Line - 1; character=int p.Column - 1|}

    /// ### pos'
    let pos' p = Reply(pos p)

    /// ### rangeSpiProj
    let rangeSpiProj f p = pipe3 pos' f pos' (fun a b c -> ((a, c) : VSCRange), b) p

    /// ### is_small_var_char_startingSpiProj
    let is_small_var_char_startingSpiProj c = isAsciiLower c

    /// ### is_var_charSpiProj
    let is_var_charSpiProj c = isAsciiLetter c || c = '_' || c = ''' || isDigit c

    /// ### file'
    let file' p = many1Satisfy2L is_small_var_char_startingSpiProj is_var_charSpiProj "lowercase variable name" p

    /// ### fileSpiProj
    let fileSpiProj p = (rangeSpiProj file' .>> spacesSpiProj) p

    /// ### file_verify
    let file_verify p = (skipMany1Satisfy2L is_small_var_char_startingSpiProj is_var_charSpiProj "lowercase variable name" .>> spacesSpiProj .>> eof) p

    /// ### file_hierarchy
    let rec file_hierarchy p =
        let i = column p
        let expr p = if i = column p then file_or_directory p else Reply(ReplyStatus.Error,expected "file or directory on the same or greater indentation as the first one")
        (many expr |>> fun l ->
            let _ =
                l |> List.toArray
                |> Array.choose (function | File(_,(a,b),_,_) -> Some (b,a) | _ -> None)
                |> Array.groupBy fst
                |> Array.choose (fun (a,b) -> if b.Length > 1 then Some (Array.map snd b) else None)
                |> add_to_exception_list p DuplicateFiles
            l
            ) p

    and file_or_directory p =
        let i = column p
        let file_hierarchy p = if i < column p then file_hierarchy p else Reply([])
        (rangeSpiProj (rangeSpiProj file' >>= fun (r,name) p ->
            let adjust_range ((a,b) : VSCRange) : VSCRange = if b.character < a.character then a,{|line=b.line-1; character=Int32.MaxValue|} else a,b
            let x = p.Peek2()
            match x.Char0, x.Char1 with
            | '/',_ -> p.Skip(); (spacesSpiProj >>. file_hierarchy |>> fun files r' -> Directory(adjust_range r',(r,name),files)) p
            | '-',_ -> p.Skip(); (spacesSpiProj >>% fun r' -> File(adjust_range r',(r,name),true,true)) p
            | '*','-' -> p.Skip(2); (spacesSpiProj >>% fun r' -> File(adjust_range r',(r,name),false,true)) p
            | '*',_ -> p.Skip(); (spacesSpiProj >>% fun r' -> File(adjust_range r',(r,name),false,false)) p
            | _ -> (spacesSpiProj >>% fun r' -> File(adjust_range r',(r,name),true,false)) p
            )
        |>> fun (r',f) -> f r') p

    /// ### RawSchemaPackages
    type RawSchemaPackages = {range : VSCRange; name : string; is_in_compiler_dir : bool; is_include : bool}

    /// ### packages
    let packages p =
        let i = column p
        let relativePath p = many1Satisfy2L (fun c -> c = '.') (fun c -> is_var_charSpiProj c || c = '.' || c = '/') "relative package path" p
        let file = rangeSpiProj (((skipChar '|' >>% true) <|>% false) .>>. (relativePath <|> file')) >>= fun (r,(is_in_compiler_dir,name)) p ->
            match p.Peek() with
            | '-' -> p.Skip(); (spacesSpiProj >>% {range=r; name=name; is_in_compiler_dir=is_in_compiler_dir; is_include=true}) p
            | _ -> (spacesSpiProj >>% {range=r; name=name; is_in_compiler_dir=is_in_compiler_dir; is_include=false}) p
        let file p = if i <= column p then file p else Reply(ReplyStatus.Error,expected "directory on the same or greater indentation as the first one")
        many file p

    /// ### crate_lines
    let crate_lines p =
        let i = column p
        let crate p = if i <= column p then (many1Satisfy (fun c -> c <> '\n' && c <> '\r' && c <> ' ') .>> spacesSpiProj) p else Reply(ReplyStatus.Error,expected "crate on the same or greater indentation as the first one")
        many crate p

    /// ### rust_extern_lines
    let rust_extern_lines p =
        let i = column p
        let entry p = if i <= column p then (many1Satisfy (fun c -> c <> '\n' && c <> '\r') .>> spacesSpiProj) p else Reply(ReplyStatus.Error,expected "rust-extern entry on the same or greater indentation as the first one")
        (many entry |>> List.map (fun (text : string) ->
            match text.Split('=', 2) with
            | [| name; traits |] -> name.Trim (), (traits.Split ',' |> Array.map (fun trait_name -> trait_name.Trim ()) |> Array.filter (fun trait_name -> trait_name <> "") |> List.ofArray)
            | _ -> text.Trim (), [])) p

    /// ### tab_positions
    let tab_positions (str : string): VSCRange [] =
        let mutable line = -1
        lines str |> Array.choose (fun x ->
            line <- line + 1
            let x = vscpos line (x.IndexOf("\t"))
            if x.character <> -1 then Some(x,vscpos x.line (x.character+1)) else None
            )

    /// ### record_reduce
    let record_reduce (field: Parser<'schema -> 'schema, _>) s p =
        let record_body p =
            let i = column p
            let indent expr p = if i = column p then expr p else Reply(ReplyStatus.Error,expected "record field on the same indentation as the first one")
            many (indent field) p
        (rangeSpiProj record_body |>> fun (r,l) -> r, List.fold (|>) s l) p

    /// ### record_field
    let record_field (name, p) =
        (skipString name >>. skipChar ':' >>. spacesSpiProj >>. rangeSpiProj p)
        |>> (fun (r,f) (s,l) -> f s, (r, name) :: l)

    /// ### record
    let record fields fields_necessary schema =
        let fields = choice (List.map record_field fields)
        record_reduce fields (schema, []) >>= fun (range,(schema,l)) p ->
            let l = List.toArray l
            let _ =
                let names = Array.map snd l
                Set fields_necessary - Set names
                |> Set.toArray
                |> add_to_exception_list p (fun fields -> MissingNecessaryRecordFields(fields,range))
            let _ =
                Array.groupBy snd l
                |> Array.choose (fun (k, v) -> if v.Length > 1 then Some (Array.map fst v) else None)
                |> add_to_exception_list p DuplicateRecordFields

            Reply(schema)

    /// ### RawSchema
    type RawSchema = {
        name : RString option
        version : RString option
        moduleDir : RString option
        modules : RawFileHierarchy list
        packageDir : RString option
        packages : RawSchemaPackages list
        link : RawSchemaPackages list
        defaultInt : RString option
        defaultFloat : RString option
        edition : RString option
        rustExtern : (string * string list) list
        autoExport : RString option
        }

    // Restore the FParsec operator scope after the adaptive assembly boundary.
    open FParsec

    /// ### schema_def
    open FParsec
    let schema_def: RawSchema = {
        name=None
        version=None
        moduleDir=None
        modules=[]
        packageDir=None
        packages=[]
        link=[]
        defaultInt=None
        defaultFloat=None
        edition=None
        rustExtern=[]
        autoExport=None
        }

    /// ### ConfigError
    type ConfigError = ResumableError of ConfigResumableError [] | ConfigFatalError of ConfigFatalError

    /// ### tomlManifestText
    let tomlManifestText (text : string) =
        let lines = text.Replace("\r\n", "\n").Split '\n'
        let unquote (value : string) =
            let value = value.Trim ()
            if value.Length >= 2 && (value.[0] = '"' || value.[0] = ''') && value.[value.Length - 1] = value.[0] then value.Substring (1, value.Length - 2)
            else value
        let items (value : string) =
            value.Trim().TrimStart('[').TrimEnd(']').Split ',' |> Array.map unquote |> Array.filter (fun item -> item <> "")
        let out = ResizeArray<string> ()
        let mutable i = 0
        while i < lines.Length do
            let line = lines.[i]
            let trimmed = line.Trim ()
            let equals = trimmed.IndexOf '='
            if trimmed = "" || trimmed.StartsWith "#" then
                out.Add ""
                i <- i + 1
            elif equals <= 0 then
                out.Add line
                i <- i + 1
            else
                let key = trimmed.Substring(0, equals).Trim ()
                let value = trimmed.Substring(equals + 1).Trim ()
                if value.StartsWith "'''" then
                    out.Add (key + ":")
                    let rest = value.Substring 3
                    if rest.Trim () <> "" then out.Add ("    " + rest)
                    i <- i + 1
                    while i < lines.Length && not (lines.[i].Trim().EndsWith "'''") do
                        out.Add (if lines.[i].Trim () = "" then "" else "    " + lines.[i])
                        i <- i + 1
                    if i < lines.Length then
                        let last = lines.[i].Substring(0, lines.[i].LastIndexOf "'''")
                        if last.Trim () <> "" then out.Add ("    " + last)
                        i <- i + 1
                elif value.StartsWith "[" then
                    let mutable collected = value
                    while not (collected.TrimEnd().EndsWith "]") && i + 1 < lines.Length do
                        i <- i + 1
                        collected <- collected + " " + lines.[i].Trim ()
                    out.Add (key + ":")
                    for item in items collected do out.Add ("    " + item)
                    i <- i + 1
                else
                    out.Add (key + ": " + unquote value)
                    i <- i + 1
        String.concat "\n" out

    /// ### isTomlManifest
    let isTomlManifest (text : string) =
        text.Replace("\r\n", "\n").Split '\n'
        |> Array.tryFind (fun line -> let t = line.Trim () in t <> "" && not (t.StartsWith "#"))
        |> Option.exists (fun line -> System.Text.RegularExpressions.Regex.IsMatch (line, @"^\s*[A-Za-z][\w-]*\s*="))

    /// ### config
    let config text =
        let text = if isTomlManifest text then tomlManifestText text else text
        try
            let _ = tab_positions text |> raise_if_not_empty Tabs

            let directory p = (rangeSpiProj (restOfLine false) .>> spacesSpiProj |>> fun (r,x) -> Some(r,x.Trim())) p

            let fields = [
                "version", rangeSpiProj (restOfLine true .>> spacesSpiProj) |>> fun (r,x) s -> ({s with version=Some (r,x.TrimEnd())} : RawSchema)
                "name", fileSpiProj |>> fun x s -> {s with name=Some x}
                "moduleDir", directory |>> fun x s -> {s with moduleDir=x}
                "modules", file_hierarchy |>> fun x s -> {s with modules=x}
                "packageDir", directory |>> fun x s -> {s with packageDir=x}
                "packages", packages |>> fun x s -> {s with packages=x}
                "link", packages |>> fun x s -> {s with link=x}
                "default-int", directory |>> fun x s -> {s with defaultInt=x}
                "default-float", directory |>> fun x s -> {s with defaultFloat=x}
                "edition", directory |>> fun x s -> {s with edition=x}
                "dialect", directory |>> fun x s -> {s with edition = x |> Option.map (fun (r, v) -> r, (match v.Trim().Trim([| '\''; '"' |]) with "i574n" -> "3" | "upstream" -> "2" | other -> other))}
                "crates", crate_lines |>> fun _ s -> s
                "rust-extern", rust_extern_lines |>> fun x s -> {s with rustExtern=x}
                "auto-export", directory |>> fun x s -> {s with autoExport=x}
                ]
            let necessary = []

            match runParserOnString (spacesSpiProj >>. record fields necessary schema_def .>> eof) (ResizeArray()) "spiral.config" text with
            | Success(a,userstate,_) ->
                if userstate.Count > 0 then userstate.ToArray() |> ResumableError |> Result.Error else Result.Ok a
            | Failure(messages,error,_) ->
                let x = vscpos (int error.Position.Line - 1) (int error.Position.Column - 1)
                ConfigFatalError.ParserError(messages, (x,vscpos x.line (x.character+1))) |> ConfigFatalError |> Result.Error
        with
            | :? ConfigException as e -> e.Data0 |> ConfigFatalError |> Result.Error

        |> Result.mapError (fun x ->
            let fatal_error = function
                | Tabs l -> l |> Array.map (fun r -> r, "Tab not allowed.")
                | ConfigFatalError.ParserError(x,r) -> [|r, (lines x).[3..] |> String.concat "\n"|]
            let inline duplicate er = Array.collect (fun l -> let er = er (Array.length l) in Array.map (fun r -> r, er) l)
            let resumable_error = function
                | DuplicateFiles l -> duplicate (sprintf "Duplicate name. Count: %i") l
                | DuplicateRecordFields l -> duplicate (sprintf "Duplicate record field. Count: %i") l
                | MissingNecessaryRecordFields (l,r) -> [|r, sprintf "Record is missing the fields: %s" (String.concat ", " l)|]
            match x with
            | ResumableError x -> Array.collect resumable_error x
            | ConfigFatalError x -> fatal_error x
            |> Array.toList
            )

    /// ### FileHierarchy
    type FileHierarchy =
        | Directory of VSCRange * path: RString * name : string * FileHierarchy list
        | File of VSCRange * path: RString * string option

    /// ### SchemaPackages
    type SchemaPackages = {dir : RString; name : string option}

    /// ### Schema
    type Schema = {
        moduleDir : VSCRange option * string
        modules : FileHierarchy list
        packageDir : VSCRange option * string
        packages : SchemaPackages list
        link : SchemaPackages list
        defaultInt : string option
        defaultFloat : string option
        edition : string option
        rustExtern : (string * string list) list
        autoExport : string option
        }

    /// ### SchemaException
    exception SchemaException of RString

    /// ### SchemaResult
    type SchemaResult = Result<Schema,RString list>

    open Microsoft.FSharp.Core

    /// ### canonical_directory
    let canonical_directory (path : string) =
        let full = Path.GetFullPath path
        let root = Path.GetPathRoot full
        full.Substring(root.Length).Split([| Path.DirectorySeparatorChar; Path.AltDirectorySeparatorChar |], StringSplitOptions.RemoveEmptyEntries)
        |> Array.fold (fun (resolved : string) part ->
            let next = Path.Combine(resolved, part)
            match (try Directory.ResolveLinkTarget(next, true) with _ -> null) with
            | null -> next
            | target -> target.FullName) root

    /// ### derivedModulesBlock
    let derivedModulesBlock (moduleRoot : string) (prelude : string list) : Result<string, string> =
        let skipped = set [ "target"; "node_modules"; "deps"; "bin"; "obj"; "_build"; "build"; ".git"; ".history" ]
        let rec moduleFiles (dir : string) : string list =
            let own = Directory.GetFiles dir |> Array.filter (fun f -> f.EndsWith ".spi" || f.EndsWith ".spir") |> Array.sort |> List.ofArray
            let nested =
                Directory.GetDirectories dir |> Array.sort |> List.ofArray |> List.collect (fun d ->
                    let info = DirectoryInfo d
                    if skipped.Contains info.Name || info.Attributes.HasFlag FileAttributes.ReparsePoint
                       || File.Exists (Path.Combine (d, "spiral.toml")) || File.Exists (Path.Combine (d, "package.spiproj")) then []
                    else moduleFiles d)
            own @ nested
        let root = (Path.GetFullPath moduleRoot).TrimEnd ('\\', '/')
        let modules =
            moduleFiles root |> List.map (fun file ->
                let relative = file.Substring(root.Length + 1).Replace ('\\', '/')
                let extension = Path.GetExtension file
                let id = relative.Substring (0, relative.Length - extension.Length)
                id, (id.Substring (id.LastIndexOf '/' + 1), extension = ".spir", file))
            |> Map.ofList
        let ids = modules |> Map.toList |> List.map fst
        let byLeaf = modules |> Map.toList |> List.groupBy (fun (_, (leaf, _, _)) -> leaf) |> List.map (fun (leaf, xs) -> leaf, List.map fst xs) |> Map.ofList
        let codeText (file : string) =
            let kept = ResizeArray<string> ()
            let mutable inTest = false
            let mutable closing : string option = None

            let strip (line : string) =
                let c = System.Text.RegularExpressions.Regex.Replace (line, @"(?<![\w'])'(?:\\.|[^'\\])'", "")
                let c = System.Text.RegularExpressions.Regex.Replace (c, @"\$'[^']*'", "")
                let c = System.Text.RegularExpressions.Regex.Replace (c, "\\$\"(?:[^\"\\\\]|\\\\.)*\"", "")
                let c = System.Text.RegularExpressions.Regex.Replace (c, "\"(?:[^\"\\\\]|\\\\.)*\"", "")
                let cut = c.IndexOf "//"
                if cut >= 0 then c.Substring (0, cut) else c
            for line in File.ReadAllLines file do
                if closing.IsNone && System.Text.RegularExpressions.Regex.IsMatch (line, @"^(test|:#) ") then inTest <- true
                else
                    if closing.IsNone && line.Length > 0 && not (Char.IsWhiteSpace line.[0]) then inTest <- false
                    if not inTest && (closing.IsSome || not (line.TrimStart().StartsWith "//")) then
                        let rest =
                            match closing with
                            | Some close ->
                                match line.IndexOf (close : string) with
                                | -1 -> None
                                | k ->
                                    closing <- None
                                    Some (line.Substring (k + close.Length))
                            | None -> Some line
                        match rest with
                        | None -> ()
                        | Some rest ->
                            let triple = rest.IndexOf "\"\"\""
                            let triples = (rest.Length - rest.Replace("\"\"\"", "").Length) / 3
                            if triple >= 0 && triples % 2 = 1 then
                                closing <- Some "\"\"\""
                                kept.Add (strip (rest.Substring (0, triple)))
                            else
                                let c = strip rest
                                let continued = rest.TrimEnd().EndsWith "\\"
                                let macro = c.IndexOf "$'"
                                let text = c.IndexOf '"'
                                if continued && macro >= 0 && (text < 0 || macro < text) then
                                    closing <- Some "'"
                                    kept.Add (c.Substring (0, macro))
                                elif continued && text >= 0 then
                                    closing <- Some "\""
                                    kept.Add (c.Substring (0, text))
                                else kept.Add c
            String.concat "\n" kept
        let deps =
            modules |> Map.map (fun id (_, _, file) ->
                let text = codeText file
                let names =
                    Seq.append
                        (System.Text.RegularExpressions.Regex.Matches (text, @"(?m)^\s*:<\s+([\w':]+)") |> Seq.collect (fun m -> m.Groups.[1].Value.Split ([| "::" |], StringSplitOptions.RemoveEmptyEntries)))
                        (System.Text.RegularExpressions.Regex.Matches (text, @"(?<![\w'.!$])([a-z_][\w']*)(?:\.|::)[a-z_(]") |> Seq.map (fun m -> m.Groups.[1].Value))
                names |> Seq.collect (fun name -> match Map.tryFind name byLeaf with Some targets -> targets | None -> []) |> Seq.filter (fun target -> target <> id) |> Set.ofSeq)
        let closure (id : string) =
            let rec go seen = function
                | [] -> seen
                | x :: rest -> let fresh = Set.difference deps.[x] seen in go (Set.union seen fresh) (Set.toList fresh @ rest)
            go Set.empty [ id ]
        let preludeIds =
            prelude |> List.map (fun p ->
                match ids |> List.filter (fun id -> id = p || (let leaf, _, _ = modules.[id] in leaf) = p) with
                | [ id ] -> Ok id
                | found -> Error (sprintf "prelude entry '%s' matches %i modules" p found.Length))
        match preludeIds |> List.tryPick (function Error e -> Some e | Ok _ -> None) with
        | Some e -> Error e
        | None ->
            let preludeIds = preludeIds |> List.map (function Ok id -> id | Error _ -> "")
            let edges = Collections.Generic.Dictionary<string, Collections.Generic.HashSet<string>> ()
            for id in ids do edges.[id] <- Collections.Generic.HashSet<string> (deps.[id])
            preludeIds |> List.pairwise |> List.iter (fun (earlier, later) -> edges.[later].Add earlier |> ignore)
            let mutable cumulative = Set.empty
            for p in preludeIds do
                cumulative <- Set.union cumulative (closure p)
                for id in ids do
                    if not (List.contains id preludeIds) && id <> p && not (cumulative.Contains id) then edges.[id].Add p |> ignore
            let indegree = Collections.Generic.Dictionary<string, int> ()
            let dependents = Collections.Generic.Dictionary<string, ResizeArray<string>> ()
            for id in ids do
                indegree.[id] <- edges.[id].Count
                for d in edges.[id] do
                    if not (dependents.ContainsKey d) then dependents.[d] <- ResizeArray ()
                    dependents.[d].Add id
            let ready = Collections.Generic.SortedSet<string> (StringComparer.Ordinal)
            for id in ids do
                if indegree.[id] = 0 then ready.Add id |> ignore
            let order = ResizeArray<string> ()
            while ready.Count > 0 do
                let next = ready.Min
                ready.Remove next |> ignore
                order.Add next
                match dependents.TryGetValue next with
                | true, ds ->
                    for d in ds do
                        indegree.[d] <- indegree.[d] - 1
                        if indegree.[d] = 0 then ready.Add d |> ignore
                | _ -> ()
            if order.Count <> ids.Length then
                Error (sprintf "the module reference graph has a cycle among: %s" (ids |> List.filter (fun id -> not (order.Contains id)) |> String.concat ", "))
            else
                let lines = ResizeArray<string> ()
                let mutable openDirs : string list = []
                for id in order do
                    let parts = id.Split '/'
                    let dirs = parts.[.. parts.Length - 2] |> List.ofArray
                    let common = Seq.zip openDirs dirs |> Seq.takeWhile (fun (a, b) -> a = b) |> Seq.length
                    for k in common .. dirs.Length - 1 do lines.Add (String.replicate k "    " + dirs.[k] + "/")
                    openDirs <- dirs
                    let _, real, _ = modules.[id]
                    let flag = (if real then "*" else "") + (if List.contains id preludeIds then "-" else "")
                    lines.Add (String.replicate dirs.Length "    " + parts.[parts.Length - 1] + flag)
                Ok (String.concat "\n" lines)

    /// ### withDerivedModules
    let withDerivedModules (pdir : string) (text : string) : Result<string, string> =
        if not (isTomlManifest text) then Ok text
        else
            let lines = text.Replace("\r\n", "\n").Split '\n'
            let keyOf (line : string) =
                let t = line.Trim ()
                let e = t.IndexOf '='
                if e > 0 && not (t.StartsWith "#") then t.Substring(0, e).Trim () else ""
            if lines |> Array.exists (fun line -> keyOf line = "modules") then Ok text
            else
                let unquote (value : string) = value.Trim().Trim('\'').Trim('"')
                let mutable prelude : string list = []
                let mutable moduleDir = None
                let kept = Array.copy lines
                let mutable i = 0
                while i < lines.Length do
                    match keyOf lines.[i] with
                    | "prelude" ->
                        let mutable collected = lines.[i].Substring(lines.[i].IndexOf '=' + 1)
                        kept.[i] <- ""
                        while not (collected.TrimEnd().EndsWith "]") && i + 1 < lines.Length do
                            i <- i + 1
                            collected <- collected + " " + lines.[i].Trim ()
                            kept.[i] <- ""
                        prelude <- collected.Trim().TrimStart('[').TrimEnd(']').Split ',' |> Array.map unquote |> Array.filter (fun x -> x <> "") |> List.ofArray
                    | "moduleDir" -> moduleDir <- Some (unquote (lines.[i].Substring(lines.[i].IndexOf '=' + 1)))
                    | _ -> ()
                    i <- i + 1
                let root = match moduleDir with Some d -> Path.Combine (pdir, d) | None -> pdir
                derivedModulesBlock root prelude
                |> Result.map (fun block -> (String.concat "\n" kept).TrimEnd () + "\nmodules = '''\n" + block + "\n'''\n")

    /// ### schema
    let schema (pdir,text) : SchemaResult = (match withDerivedModules pdir text with Ok text -> config text | Error message -> Error [ ((vscpos 0 0, vscpos 0 1) : VSCRange), message ]) |> Result.bind (fun x ->
        try
            let combine a (r,b) =
                try
                    Path.Combine(a,b)
                    |> canonical_directory
                    |> fun result ->
                        let result' = result |> SpiralFileSystem.standardize_path
                        // trace Verbose (fun () -> $"""SpiProj.schema.combine / a: {a} / b: {b} / result: {result |> SpiralSm.replace "\\" "|"} / result': {result'}""") _locals
                        result'
                with e ->
                    raise (SchemaException(r,e.Message))
            let module_dir =
                match x.moduleDir with
                | Some(r,_ as x) -> Some r, combine pdir x
                | None -> None, pdir
            let package_dir =
                match x.packageDir with
                | Some(r,_ as x) -> Some r, combine pdir x
                | None -> None, Path.Combine(pdir,"..") |> canonical_directory
            // trace Verbose (fun () -> $"""SpiProj.schema / pdir: {pdir} / module_dir: {module_dir |> snd} / package_dir: {package_dir |> snd |> SpiralSm.replace "\\" "|"}""") _locals
            let modules =
                let rec loop prefix = function
                    | RawFileHierarchy.Directory(r,(r',a),l) ->
                        let prefix = Path.Combine(prefix,a)
                        let prefix' = prefix |> SpiralFileSystem.standardize_path
                        trace Verbose (fun () -> $"SpiProj.schema.modules.loop | RawFileHierarchy.Directory(r,(r',a),l) / prefix: {prefix} / prefix': {prefix'}") _locals
                        let prefix = prefix'
                        Directory(r,(r',prefix),a,List.map (loop prefix) l)
                    | RawFileHierarchy.File(r,(r',a),is_top_down,is_include) ->
                        let path = Path.Combine(prefix,a + if is_top_down then ".spi" else ".spir")
                        let path' = path |> SpiralFileSystem.standardize_path
                        // trace Verbose (fun () -> $"SpiProj.schema.modules.loop | RawFileHierarchy.File(r,(r',a),is_top_down,is_include) / path: {path} / path': {path'}") _locals
                        let path = path'
                        File(r,(r',path),if is_include then None else Some a)
                List.map (loop (snd module_dir)) x.modules
            let resolve_packages (l : RawSchemaPackages list) =
                let compiler_dir = lazy (
                    let configured = Environment.GetEnvironmentVariable "SPIRAL_COMPILER_PACKAGE_DIR"
                    let plugin = "deps/The-Spiral-Language/VS Code Plugin"
                    if String.IsNullOrWhiteSpace configured then
                        let rec ancestors (d : DirectoryInfo) = seq { if not (isNull d) then yield d.FullName; yield! ancestors d.Parent }
                        let candidates (start : string) =
                            ancestors (DirectoryInfo start) |> Seq.collect (fun d -> [ Path.Combine(d, plugin); Path.Combine(d, "deps/spiral", plugin); Path.Combine(d, "../spiral", plugin) ])
                        Seq.append (candidates (SpiralFileSystem.get_workspace_root ())) (candidates pdir)
                        |> Seq.map Path.GetFullPath
                        |> Seq.tryFind Directory.Exists
                        |> Option.defaultWith (fun () -> Path.Combine (SpiralFileSystem.get_workspace_root (), plugin) |> Path.GetFullPath)
                    else
                        configured |> Path.GetFullPath
                    )
                let lib_root = lazy (
                    let configured = Environment.GetEnvironmentVariable "SPIRAL_LIB_ROOT"
                    if String.IsNullOrWhiteSpace configured then None else Some (Path.GetFullPath configured)
                    )
                l |> List.map (fun x ->
                    let relative = x.name.StartsWith "."
                    let name = if x.is_include then None elif relative then Some (Path.GetFileName (x.name.TrimEnd '/')) else Some x.name
                    let base_dir =
                        if x.is_in_compiler_dir then compiler_dir.Value
                        elif relative then pdir
                        else
                            match lib_root.Value with
                            | Some root when Directory.Exists (Path.Combine(root, x.name)) -> root
                            | _ -> snd package_dir
                    let dir = Path.Combine(base_dir,x.name)
                    let dir' = dir |> SpiralFileSystem.standardize_path
                    let dir'' = dir' |> SpiralFileSystem.standardize_path
                    trace Verbose (fun () -> $"""SpiProj.schema.packages / dir: {dir |> SpiralSm.replace "\\" "|"} / dir': {dir'} / dir'': {dir''}""") _locals
                    let dir = dir''
                    {name = name; dir = x.range, dir}
                    )
            let packages = resolve_packages x.packages
            Ok {moduleDir = module_dir; modules = modules; packageDir = package_dir; packages = packages; link = resolve_packages x.link; defaultInt = x.defaultInt |> Option.map snd; defaultFloat = x.defaultFloat |> Option.map snd; edition = x.edition |> Option.map snd; rustExtern = x.rustExtern; autoExport = x.autoExport |> Option.map snd}
        with :? SchemaException as e -> Error [e.Data0]
        )

    /// ## Formatter
    module FormatterLexed =


        [<AbstractClass; Sealed>]
        type AsRead = class end

        [<AbstractClass; Sealed>]
        type Spaced = class end

        [<AbstractClass; Sealed>]
        type Flat = class end

        [<AbstractClass; Sealed>]
        type Laid = class end

        [<Struct>]
        type Span = { From : int; NearTo : int }

        type Verbatim =
            private
            | Verbatim of string
            member this.Text = let (Verbatim text) = this in text
            member this.Length = this.Text.Length

        type Gap =
            | Whitespace of int
            | Embedded of Verbatim

        type Lexeme =
            { Span : Span
              Token : SpiralToken
              Text : Verbatim
              InsideMacro : bool
              Before : Gap }

        type OpaqueCause =
            | InComment
            | InString
            | InMacro
            | Unlexable

        type LineShape =
            | Blank
            | Code of indent : int * lexemes : Lexeme[] * tail : Verbatim
            | Opaque of Verbatim * OpaqueCause
            | Remark of Verbatim

        type Line<'phase> = { Number : int; Shape : LineShape }

        type Edition =
            | Edition2
            | Edition3

        type Unit' =
            | TopDown
            | BottomUp

        type Source<'phase> =
            private
                { Path : string
                  Edition : Edition
                  Unit : Unit'
                  Lines : Line<'phase>[] }
            member this.FilePath = this.Path
            member this.FileEdition = this.Edition
            member this.FileUnit = this.Unit
            member this.SourceLines = this.Lines

        type SourceUser<'result> =
            abstract Use<'phase> : Source<'phase> -> 'result

        type AnySource =
            abstract Apply<'result> : SourceUser<'result> -> 'result

        let seal (source : Source<'phase>) =
            { new AnySource with
                member _.Apply user = user.Use source }

        let verbatimOf (text : string) (span : Span) = Verbatim (text.Substring (span.From, span.NearTo - span.From))

        let verbatimTail (text : string) (from : int) = Verbatim (text.Substring from)

        let trimmedTail (tail : Verbatim) = Verbatim (tail.Text.TrimEnd ())

        let verbatimLine (text : string) = Verbatim text

        let render (line : Line<'phase>) =
            match line.Shape with
            | Blank -> ""
            | Opaque (text, _) -> text.Text
            | Remark text -> text.Text
            | Code (indent, lexemes, tail) ->
                let builder = System.Text.StringBuilder ()
                builder.Append (' ', indent) |> ignore
                lexemes
                |> Array.iteri (fun index lexeme ->
                    if index > 0 then
                        match lexeme.Before with
                        | Whitespace count -> builder.Append (' ', count) |> ignore
                        | Embedded text -> builder.Append text.Text |> ignore
                    builder.Append lexeme.Text.Text |> ignore)
                builder.Append(tail.Text).ToString ()

        let displayWidth (text : string) =
            let wide (rune : int) =
                (rune >= 0x1100 && rune <= 0x115F) || (rune >= 0x2E80 && rune <= 0xA4CF) || (rune >= 0xAC00 && rune <= 0xD7A3)
                || (rune >= 0xF900 && rune <= 0xFAFF) || (rune >= 0xFE30 && rune <= 0xFE4F) || (rune >= 0xFF00 && rune <= 0xFF60)
                || (rune >= 0xFFE0 && rune <= 0xFFE6) || (rune >= 0x1F300 && rune <= 0x1FAFF) || (rune >= 0x20000 && rune <= 0x3FFFD)
            let elements = System.Globalization.StringInfo.GetTextElementEnumerator text
            let mutable width = 0
            while elements.MoveNext () do
                let element = elements.GetTextElement ()
                let rune = System.Char.ConvertToUtf32 (element, 0)
                width <- width + (if rune = 1 then 1000 elif rune = 2 then 0 elif wide rune then 2 elif System.Globalization.CharUnicodeInfo.GetUnicodeCategory rune = System.Globalization.UnicodeCategory.NonSpacingMark then 0 else 1)
            width

        let isMacroOpening token =
            match token with
            | TokMacroOpen -> true
            | _ -> false

        let isMacroClosing token =
            match token with
            | TokMacroClose -> true
            | _ -> false

        let lexLine (state : LexState) (text : string) =
            let tokens, errors, next = tokenize_line state text
            let startsPlain = state = lex_state_init
            let endsPlain = next = lex_state_init
            let shape =
                if text.Length = 0 && startsPlain && endsPlain then Blank
                elif not startsPlain || not endsPlain || not (List.isEmpty errors) then
                    let cause =
                        if 0 < state.comment_depth || 0 < next.comment_depth then InComment
                        elif state.in_triple || next.in_triple then InString
                        elif not (List.isEmpty errors) then Unlexable
                        else InMacro
                    Opaque (verbatimLine text, cause)
                elif tokens.Length = 0 then Remark (verbatimLine text)
                else
                    let mutable depth = 0
                    let mutable previous = 0
                    let lexemes =
                        [| for (range, token) in tokens do
                               if isMacroOpening token then depth <- depth + 1
                               let inside = depth > 0
                               if isMacroClosing token then depth <- depth - 1
                               let span = { From = range.from; NearTo = range.nearTo }
                               let between = text.Substring (previous, max 0 (range.from - previous))
                               let gap = if between.Trim().Length = 0 then Whitespace between.Length else Embedded (Verbatim between)
                               previous <- range.nearTo
                               yield { Span = span; Token = token; Text = verbatimOf text span; InsideMacro = inside; Before = gap } |]
                    let last = lexemes.[lexemes.Length - 1].Span.NearTo
                    Code (lexemes.[0].Span.From, lexemes, verbatimTail text last)
            shape, next

        let splitLines (text : string) =
            let lines = text.Replace("\r\n", "\n").Split '\n'
            if lines.Length > 1 && lines.[lines.Length - 1] = "" then lines.[0 .. lines.Length - 2] else lines

        let lexText (path : string) (edition : Edition) (text : string) : Source<AsRead> =
            let mutable state = lex_state_init
            let lines =
                splitLines text
                |> Array.mapi (fun index lineText ->
                    let shape, next = lexLine state lineText
                    state <- next
                    { Number = index + 1; Shape = shape })
            { Path = path
              Edition = edition
              Unit = (if path.EndsWith ".spir" then BottomUp else TopDown)
              Lines = lines }

        let relex (source : Source<'phase>) (texts : string[]) : Source<'next> =
            let mutable state = lex_state_init
            let lines =
                texts
                |> Array.mapi (fun index lineText ->
                    let shape, next = lexLine state lineText
                    state <- next
                    { Number = index + 1; Shape = shape })
            { Path = source.Path
              Edition = source.Edition
              Unit = source.Unit
              Lines = lines }

        let renderAll (source : Source<'phase>) = source.Lines |> Array.map render

        let joinLines (lines : string[]) = String.concat "\n" lines + "\n"

    module FormatterParsed =

        open System
        open System.Text
        open Microsoft.FSharp.Reflection
        open FormatterLexed

        let environmentOf edition : DefaultEnv =
            { port = 0
              default_int = Int32T
              default_uint = UInt32T
              default_float = Float64T
              edition = (match edition with Edition2 -> UpstreamEdition2 | Edition3 -> ForkEdition3)
              test_entry = None }

        type ShapeKind =
            | PositionShape
            | EnumShape
            | UnionShape of tag : (obj -> int) * cases : (UnionCaseInfo * (obj -> obj[]))[]
            | TupleShape of fields : (obj -> obj[])
            | RecordShape of fields : (obj -> obj[])
            | PairShape
            | ArrayShape
            | EnumerableShape
            | OtherShape

        let shapeKinds = Collections.Concurrent.ConcurrentDictionary<Type, ShapeKind> ()

        let shapeKindOf (shape : Type) =
            shapeKinds.GetOrAdd (shape, fun shape ->
                let isPosition =
                    FSharpType.IsRecord (shape, true)
                    && (FSharpType.GetRecordFields (shape, true) |> Array.map (fun field -> field.Name) |> Array.sort) = [| "character"; "line" |]
                if isPosition then PositionShape
                elif shape.IsEnum then EnumShape
                elif FSharpType.IsUnion (shape, true) then
                    let cases = FSharpType.GetUnionCases (shape, true)
                    let declaring = cases.[0].DeclaringType
                    UnionShape (FSharpValue.PreComputeUnionTagReader (declaring, true), cases |> Array.map (fun case -> case, FSharpValue.PreComputeUnionReader (case, true)))
                elif FSharpType.IsTuple shape then TupleShape (FSharpValue.PreComputeTupleReader shape)
                elif FSharpType.IsRecord (shape, true) then RecordShape (FSharpValue.PreComputeRecordReader (shape, true))
                elif shape.IsGenericType && shape.GetGenericTypeDefinition () = typedefof<Collections.Generic.KeyValuePair<_, _>> then PairShape
                elif shape.IsArray then ArrayShape
                elif typeof<Collections.IEnumerable>.IsAssignableFrom shape then EnumerableShape
                else OtherShape)

        let unionFieldsOf (value : obj) =
            if isNull value then None
            else
                match shapeKindOf (value.GetType ()) with
                | UnionShape (tag, cases) ->
                    let case, read = cases.[tag value]
                    Some (case, read value)
                | _ -> None

        let rec foldedConcat (value : obj) : string option =
            match unionFieldsOf value with
            | None -> None
            | Some (case, fields) ->
                match case.Name with
                | "RawLit" when fields.Length = 2 ->
                    match unionFieldsOf fields.[1] with
                    | Some (literalCase, literalFields) when literalCase.Name = "LitString" -> Some (literalFields.[0] :?> string)
                    | _ -> None
                | "RawApply" when fields.Length = 3 && not (isNull fields.[1]) ->
                    match unionFieldsOf fields.[1] with
                    | Some (innerCase, innerFields) when innerCase.Name = "RawApply" && innerFields.Length = 3 && not (isNull innerFields.[1]) ->
                        match unionFieldsOf innerFields.[1] with
                        | Some (operatorCase, operatorFields) when operatorCase.Name = "RawV" && operatorFields.Length >= 2 && (operatorFields.[1] :? string) && (operatorFields.[1] :?> string) = "^^" ->
                            match foldedConcat innerFields.[2], foldedConcat fields.[2] with
                            | Some a, Some b -> Some (a + b)
                            | _ -> None
                        | _ -> None
                    | _ -> None
                | "RawAnnot" when fields.Length = 3 && not (isNull fields.[2]) ->
                    match unionFieldsOf fields.[2] with
                    | Some (typeCase, typeFields) when typeCase.Name = "RawTPrim" && typeFields.Length = 2 && string typeFields.[1] = "StringT" -> foldedConcat fields.[1]
                    | _ -> None
                | "RawOp" when fields.Length = 3 ->
                    match unionFieldsOf fields.[1] with
                    | Some (opCase, _) when opCase.Name = "StaticStringConcat" ->
                        let args = (fields.[2] :?> Collections.IEnumerable) |> Seq.cast<obj> |> List.ofSeq
                        match args |> List.map foldedConcat with
                        | [ Some a; Some b ] -> Some (a + b)
                        | _ -> None
                    | _ -> None
                | _ -> None

        type ShapeStep =
            | Emit of string
            | Visit of obj

        let rawSeqHalves (item : obj) =
            match unionFieldsOf item with
            | Some (case, fields) when case.Name = "RawSeq" && fields.Length = 3 -> Some (fields.[1], fields.[2])
            | _ -> None

        let sequenced (value : obj) =
            let items = ResizeArray<obj> ()
            let unopened = Collections.Generic.Stack<obj> ()
            unopened.Push value
            while unopened.Count > 0 do
                let item = unopened.Pop ()
                match rawSeqHalves item with
                | Some (first, rest) ->
                    unopened.Push rest
                    unopened.Push first
                | None -> items.Add item
            List.ofSeq items

        let macroTextOf (item : obj) =
            match unionFieldsOf item with
            | Some (case, fields) when case.Name = "RawMacroText" && fields.Length = 2 && (fields.[1] :? string) -> Some (fields.[1] :?> string)
            | _ -> None

        let enumeratedSteps (value : Collections.IEnumerable) =
            let steps = ResizeArray<ShapeStep> ()
            let joined = StringBuilder ()
            let flush () =
                if joined.Length > 0 then
                    steps.Add (Emit ("(RawMacroText <pp> \"" + string joined.Length + ":" + joined.ToString () + ")"))
                    joined.Clear () |> ignore
            for item in value do
                match macroTextOf item with
                | Some text -> joined.Append text |> ignore
                | None ->
                    flush ()
                    steps.Add (Visit item)
            flush ()
            List.ofSeq steps

        let shapeSteps (value : obj) : ShapeStep list =
            let enclosed (opening : string) (children : obj seq) (closing : string) = Emit opening :: [ for child in children -> Visit child ] @ [ Emit closing ]
            let spaced (opening : string) (children : obj seq) = Emit opening :: [ for child in children do yield! [ Emit " "; Visit child ] ] @ [ Emit ")" ]
            match value with
            | null -> [ Emit "n" ]
            | :? string as text -> [ Emit ("\"" + string text.Length + ":" + text) ]
            | :? bool | :? char | :? int | :? int8 | :? int16 | :? int64 | :? uint8 | :? uint16 | :? uint32 | :? uint64 -> [ Emit (value.ToString () + ";") ]
            | :? float32 as number -> [ Emit (string (BitConverter.SingleToInt32Bits number) + "f") ]
            | :? float as number -> [ Emit (string (BitConverter.DoubleToInt64Bits number) + "d") ]
            | _ ->
                let shape = value.GetType ()
                match shapeKindOf shape with
                | PositionShape -> [ Emit "p" ]
                | EnumShape -> [ Emit (value.ToString () + ";") ]
                | UnionShape (tag, cases) ->
                    match foldedConcat value with
                    | Some text -> [ Emit ("(RawLit <pp> (LitString \"" + string text.Length + ":" + text + "))") ]
                    | None when (rawSeqHalves value).IsSome -> spaced "(RawSeq*" (sequenced value)
                    | None ->
                        let case, read = cases.[tag value]
                        spaced ("(" + case.Name) (read value)
                | TupleShape read -> enclosed "<" (read value) ">"
                | RecordShape read -> enclosed "{" (read value) "}"
                | PairShape -> enclosed "{" [ shape.GetProperty("Key").GetValue value; shape.GetProperty("Value").GetValue value ] "}"
                | ArrayShape -> enclosed "[" (Seq.cast<obj> (value :?> Array)) "]"
                | EnumerableShape -> Emit "[" :: enumeratedSteps (value :?> Collections.IEnumerable) @ [ Emit "]" ]
                | OtherShape -> [ Emit ("?" + shape.Name) ]

        let shapeOf (builder : StringBuilder) (root : obj) =
            let pending = Collections.Generic.Stack<ShapeStep> ()
            pending.Push (Visit root)
            while pending.Count > 0 do
                match pending.Pop () with
                | Emit text -> builder.Append text |> ignore
                | Visit value -> for step in List.rev (shapeSteps value) do pending.Push step

        type BlockShape =
            { Offset : int
              Shape : string }

        let blockShapes (edition : Edition) (unit : Unit') (text : string) =
            let state = wdiff_tokenizer_all wdiff_tokenizer_init text
            let environment = environmentOf edition
            let topDown = (match unit with TopDown -> true | BottomUp -> false)
            let shapeOfResult (result : ParseResult) =
                let builder = StringBuilder ()
                match result with
                | Ok statement -> shapeOf builder (box statement)
                | Error errors ->
                    builder.Append "error" |> ignore
                    for (_, error) in errors do
                        builder.Append ' ' |> ignore
                        shapeOf builder (box error)
                builder.ToString ()
            let testHeader (block : LineTokens Block) =
                block.block
                |> Seq.tryFindIndex (fun line -> line.Length > 0)
                |> Option.bind (fun index ->
                    match snd block.block.[index].[0] with
                    | TokVar ("test", _) -> Some index
                    | _ -> None)
            state.blocks
            |> List.map (fun block ->
                match testHeader block with
                | Some header ->
                    let body = [ for index in header + 1 .. block.block.Length - 1 -> state.lines_text.[block.offset + index] ]
                    let headerText = state.lines_text.[block.offset + header]
                    let sameLine =
                        block.block.[header]
                        |> Seq.tryFind (fun (_, token) -> match token with TokOperator ("=", _) -> true | _ -> false)
                        |> Option.map (fun (range, _) -> headerText.Substring range.nearTo)
                        |> Option.defaultValue ""
                    let synthetic = String.concat "\n" (("inl test_block_body () =" + sameLine) :: body)
                    let inner = wdiff_tokenizer_all wdiff_tokenizer_init synthetic
                    let shape =
                        match inner.blocks with
                        | first :: _ ->
                            "test " + shapeOfResult (parse_block environment topDown first.block).result
                        | [] -> "test empty"
                    { Offset = block.offset; Shape = shape }
                | None -> { Offset = block.offset; Shape = shapeOfResult (parse_block environment topDown block.block).result })

        let shapeKeyOf (shapes : BlockShape list) =
            shapes |> List.map (fun shape -> shape.Shape) |> String.concat "\n"

        type ParseAgreement =
            | SameParse
            | ParseDiffers of firstBlockLine : int
            | OriginalHasErrors

        let compareParses (edition : Edition) (unit : Unit') (before : string) (after : string) =
            let left = blockShapes edition unit before |> List.filter (fun block -> block.Shape <> "error")
            let leftHasErrors = left |> List.exists (fun block -> block.Shape.StartsWith "error (" || block.Shape.StartsWith "test error (")
            let right = blockShapes edition unit after |> List.filter (fun block -> block.Shape <> "error")
            let pairs = List.zip (List.truncate (min left.Length right.Length) left) (List.truncate (min left.Length right.Length) right)
            match pairs |> List.tryFind (fun (a, b) -> a.Shape <> b.Shape && not (a.Shape.StartsWith "error (") && not (a.Shape.StartsWith "test error (")) with
            | Some (a, _) when not leftHasErrors || left.Length = right.Length -> ParseDiffers (a.Offset + 1)
            | _ when left.Length <> right.Length && leftHasErrors -> OriginalHasErrors
            | Some (a, _) -> ParseDiffers (a.Offset + 1)
            | None when left.Length <> right.Length ->
                let line = if left.Length < right.Length then right.[left.Length].Offset else left.[right.Length].Offset
                ParseDiffers (line + 1)
            | None -> SameParse

    module FormatterSpacing =

        open FormatterLexed

        type Respacing =
            | OperatorSpace
            | SeparatorTight
            | SeparatorSpace
            | ApplicationSpace
            | MacroOpTight
            | BracketInnerSpace
            | EmptyBracketTight
            | ConstraintBraceTight
            | OperatorSectionTight

        type GapRule =
            | AsWritten
            | Fixed of Respacing * width : int

        type LineChange =
            | TrailingWhitespace
            | Respaced of Respacing
            | GuardKept

        type SpacedLine =
            { Line : Line<Spaced>
              Changes : LineChange list }

        let binaryOperator token =
            match token with
            | TokOperator (name, _) -> Some name
            | _ -> None

        let isUnary token =
            match token with
            | TokUnaryOperator _ -> true
            | _ -> false

        let isOpening shape token =
            match token with
            | TokParenthesis (kind, Open) -> kind = shape
            | _ -> false

        let isClosing shape token =
            match token with
            | TokParenthesis (kind, Close) -> kind = shape
            | _ -> false

        let isAnyOpening token =
            match token with
            | TokParenthesis (_, Open) -> true
            | _ -> false

        let isSeparator name = name = "," || name = ";"

        let isSequence name = name = "."

        let appliesToParenthesis token =
            match token with
            | TokVar _ -> true
            | TokParenthesis (Round, Close) -> true
            | _ -> false

        let constraintBraces (lexemes : Lexeme[]) =
            let marks = Array.zeroCreate lexemes.Length
            let mutable inForall = false
            let mutable inInstanceHead = false
            let mutable braceDepth = 0
            lexemes
            |> Array.iteri (fun index lexeme ->
                match lexeme.Token with
                | TokKeyword SpecForall -> inForall <- true
                | TokKeyword SpecInstance when index = 0 -> inInstanceHead <- true
                | TokOperator (".", _) when inForall && braceDepth = 0 -> inForall <- false
                | TokOperator ("=", _) when inInstanceHead && braceDepth = 0 -> inInstanceHead <- false
                | TokParenthesis (Curly, Open) when inForall || inInstanceHead ->
                    braceDepth <- braceDepth + 1
                    marks.[index] <- true
                | TokParenthesis (Curly, Close) when braceDepth > 0 ->
                    braceDepth <- braceDepth - 1
                    marks.[index] <- true
                | _ -> ())
            marks

        let arrayBrackets (lexemes : Lexeme[]) =
            let marks = Array.zeroCreate lexemes.Length
            let openers = System.Collections.Generic.Stack<bool> ()
            lexemes
            |> Array.iteri (fun index lexeme ->
                match lexeme.Token with
                | TokParenthesis (Square, Open) ->
                    let array = index > 0 && (match lexemes.[index - 1].Token with TokUnaryOperator (";", _) -> true | _ -> false)
                    openers.Push array
                    marks.[index] <- array
                | TokParenthesis (Square, Close) -> marks.[index] <- (openers.Count = 0 || openers.Pop ())
                | _ -> ())
            marks

        let gapRule (lexemes : Lexeme[]) (constraintMarks : bool[]) (arrayMarks : bool[]) (index : int) =
            let left = lexemes.[index - 1]
            let right = lexemes.[index]
            let at offset = if index + offset >= 0 && index + offset < lexemes.Length then Some lexemes.[index + offset].Token else None
            let macroInterior =
                (right.InsideMacro && right.Token <> TokMacroOpen) || (left.InsideMacro && left.Token <> TokMacroClose)
            match left.Before, right.Before with
            | _, Embedded _ -> AsWritten
            | _ when macroInterior -> AsWritten
            | _ when isUnary left.Token -> AsWritten
            | _ when isOpening Round right.Token && (match at -2 with Some (TokUnaryOperator ("!!!!", _)) -> true | _ -> false) -> Fixed (MacroOpTight, 0)
            | _ ->
                let sectionOpen = isOpening Round left.Token && (binaryOperator right.Token).IsSome && (at 1 |> Option.exists (isClosing Round))
                let sectionClose = isClosing Round right.Token && (binaryOperator left.Token).IsSome && (at -2 |> Option.exists (isOpening Round))
                let innerOperator =
                    ((binaryOperator left.Token).IsSome && (match right.Token with TokParenthesis (_, Close) -> true | _ -> false))
                    || ((binaryOperator right.Token).IsSome && isAnyOpening left.Token)
                if sectionOpen || sectionClose then Fixed (OperatorSectionTight, 0)
                elif innerOperator then AsWritten
                else
                    match binaryOperator left.Token, binaryOperator right.Token with
                    | _, Some name when isSeparator name -> Fixed (SeparatorTight, 0)
                    | Some name, _ when isSeparator name -> Fixed (SeparatorSpace, 1)
                    | Some name, _ when isSequence name -> AsWritten
                    | _, Some name when isSequence name -> AsWritten
                    | Some _, _ -> Fixed (OperatorSpace, 1)
                    | _, Some _ -> Fixed (OperatorSpace, 1)
                    | None, None ->
                        let constraintGap = constraintMarks.[index - 1] && isAnyOpening left.Token || constraintMarks.[index] && not (isAnyOpening right.Token)
                        if constraintGap then Fixed (ConstraintBraceTight, 0)
                        elif appliesToParenthesis left.Token && isOpening Round right.Token && left.Span.NearTo = right.Span.From then Fixed (ApplicationSpace, 1)
                        elif isOpening Curly left.Token && isClosing Curly right.Token then Fixed (EmptyBracketTight, 0)
                        elif isOpening Square left.Token && isClosing Square right.Token then Fixed (EmptyBracketTight, 0)
                        elif (arrayMarks.[index - 1] && isOpening Square left.Token) || (arrayMarks.[index] && isClosing Square right.Token) then AsWritten
                        elif isOpening Curly left.Token || isOpening Square left.Token then Fixed (BracketInnerSpace, 1)
                        elif isClosing Curly right.Token || isClosing Square right.Token then Fixed (BracketInnerSpace, 1)
                        else AsWritten

        let tokenSignature (lexemes : Lexeme[]) =
            lexemes |> Array.map (fun lexeme -> lexeme.Text.Text, (sprintf "%A" lexeme.Token).GetHashCode ())

        let tokenKinds (lexemes : Lexeme[]) =
            lexemes
            |> Array.map (fun lexeme ->
                let kind =
                    match lexeme.Token with
                    | TokOperator _ -> "op"
                    | TokUnaryOperator _ -> "unary"
                    | TokVar _ -> "var"
                    | TokSymbol _ -> "symbol"
                    | TokKeyword keyword -> sprintf "%A" keyword
                    | TokParenthesis (shape, state) -> sprintf "%A%A" shape state
                    | other -> (sprintf "%A" other).Split(' ').[0]
                kind, lexeme.Text.Text)

        let respaceLine (line : Line<AsRead>) : Line<Spaced> * LineChange list * string option =
            match line.Shape with
            | Blank | Opaque _ -> { Number = line.Number; Shape = line.Shape }, [], None
            | Remark text ->
                let trimmed = trimmedTail text
                if trimmed.Length = text.Length then { Number = line.Number; Shape = line.Shape }, [], None
                else
                    match lexLine lex_state_init trimmed.Text with
                    | Remark _, _ -> { Number = line.Number; Shape = Remark trimmed }, [ TrailingWhitespace ], None
                    | Blank, _ -> { Number = line.Number; Shape = Blank }, [ TrailingWhitespace ], None
                    | _ -> { Number = line.Number; Shape = line.Shape }, [ GuardKept ], Some trimmed.Text
            | Code (indent, lexemes, tail) ->
                let marks = constraintBraces lexemes
                let arrays = arrayBrackets lexemes
                let changes = ResizeArray ()
                let respaced =
                    lexemes
                    |> Array.mapi (fun index lexeme ->
                        if index = 0 then lexeme
                        else
                            match gapRule lexemes marks arrays index, lexeme.Before with
                            | Fixed (reason, width), Whitespace current when current <> width ->
                                changes.Add (Respaced reason)
                                { lexeme with Before = Whitespace width }
                            | _ -> lexeme)
                let trimmed = trimmedTail tail
                if trimmed.Length <> tail.Length then changes.Add TrailingWhitespace
                let candidate = { Number = line.Number; Shape = Code (indent, respaced, trimmed) }
                if changes.Count = 0 then candidate, [], None
                else
                    let text = render candidate
                    match lexLine lex_state_init text with
                    | Code (_, relexed, _), _ when tokenKinds relexed = tokenKinds lexemes -> candidate, List.ofSeq changes, None
                    | _ ->
                        let original = { Number = line.Number; Shape = Code (indent, lexemes, trimmed) }
                        original, [ GuardKept ], Some text

        let respace (source : Source<AsRead>) =
            let results = source.SourceLines |> Array.map respaceLine
            let lines = results |> Array.map (fun (line, _, _) -> line)
            let mutable last = lines.Length
            while last > 0 && (match lines.[last - 1].Shape with Blank -> true | _ -> false) do
                last <- last - 1
            let texts = lines.[0 .. last - 1] |> Array.map render
            let spaced : Source<Spaced> = relex source texts
            let changes = results |> Array.map (fun (line, changes, guard) -> line.Number, changes, guard)
            spaced, changes

    module FormatterCheck =

        open FormatterLexed

        let lineLimit = 120

        type LiteralKind =
            | PlainString
            | Macro
            | RawString
            | Character

        type Construct =
            | LiteralTooWide of LiteralKind * width : int
            | CommentTail
            | OpaqueText
            | DefinitionHead
            | Binding
            | Pipeline
            | MatchArm
            | IfThenElse
            | Record
            | UnionCase
            | TypeDefinition
            | Application

        type Overflow =
            { Line : int
              Width : int
              Construct : Construct }

        let constructName construct =
            match construct with
            | LiteralTooWide (PlainString, _) -> "literal-string"
            | LiteralTooWide (Macro, _) -> "literal-macro"
            | LiteralTooWide (RawString, _) -> "literal-raw"
            | LiteralTooWide (Character, _) -> "literal-char"
            | CommentTail -> "comment"
            | OpaqueText -> "opaque"
            | DefinitionHead -> "head"
            | Binding -> "binding"
            | Pipeline -> "pipeline"
            | MatchArm -> "arm"
            | IfThenElse -> "if"
            | Record -> "record"
            | UnionCase -> "union-case"
            | TypeDefinition -> "type"
            | Application -> "application"

        let literalSpans (lexemes : Lexeme[]) =
            let spans = ResizeArray ()
            let mutable opened = None
            for lexeme in lexemes do
                match lexeme.Token, opened with
                | TokMacroOpen, None -> opened <- Some (Macro, lexeme.Span.From)
                | TokStringOpen, None -> opened <- Some (PlainString, lexeme.Span.From)
                | TokMacroClose, Some (Macro, from) ->
                    spans.Add (Macro, lexeme.Span.NearTo - from)
                    opened <- None
                | TokStringClose, Some (PlainString, from) ->
                    spans.Add (PlainString, lexeme.Span.NearTo - from)
                    opened <- None
                | TokValue (LitString _), None -> spans.Add (RawString, lexeme.Span.NearTo - lexeme.Span.From)
                | TokValue (LitChar _), None -> spans.Add (Character, lexeme.Span.NearTo - lexeme.Span.From)
                | _ -> ()
            List.ofSeq spans

        let topLevelOperators (lexemes : Lexeme[]) =
            let mutable depth = 0
            [ for lexeme in lexemes do
                  match lexeme.Token with
                  | _ when lexeme.InsideMacro -> ()
                  | TokParenthesis (_, Open) -> depth <- depth + 1
                  | TokParenthesis (_, Close) -> depth <- depth - 1
                  | TokOperator (name, _) when depth = 0 -> yield name, lexeme
                  | TokKeyword keyword when depth = 0 -> yield sprintf "%A" keyword, lexeme
                  | _ -> () ]

        let classify (indent : int) (lexemes : Lexeme[]) =
            let room = lineLimit - indent - 4
            let codeEnd = lexemes.[lexemes.Length - 1].Span.NearTo
            match literalSpans lexemes |> List.tryFind (fun (_, width) -> width > room) with
            | Some (kind, width) -> LiteralTooWide (kind, width)
            | None when codeEnd <= lineLimit -> CommentTail
            | None ->
                let operators = topLevelOperators lexemes
                let has name = operators |> List.exists (fun (found, _) -> found = name)
                match lexemes.[0].Token with
                | TokKeyword (SpecInl | SpecLet | SpecAnd) ->
                    match operators |> List.tryFind (fun (name, _) -> name = "=") with
                    | Some (_, equals) when equals.Span.NearTo < codeEnd && equals.Span.NearTo <= lineLimit -> Binding
                    | _ -> DefinitionHead
                | TokKeyword (SpecType | SpecNominal | SpecUnion | SpecPrototype | SpecInstance) -> TypeDefinition
                | TokOperator ("|", _) -> if has "=>" then MatchArm else UnionCase
                | TokKeyword (SpecIf | SpecElif | SpecThen | SpecElse) -> IfThenElse
                | _ when has "SpecIf" -> IfThenElse
                | _ when has "|>" || has "||>" || has "|||>" -> Pipeline
                | TokParenthesis (Curly, Open) -> Record
                | _ -> Application

        let overflows (source : Source<'phase>) =
            source.SourceLines
            |> Array.choose (fun line ->
                let text = render line
                if displayWidth text <= lineLimit then None
                else
                    let construct =
                        match line.Shape with
                        | Code (indent, lexemes, _) -> classify indent lexemes
                        | Remark _ -> CommentTail
                        | Opaque _ | Blank -> OpaqueText
                    Some { Line = line.Number; Width = displayWidth text; Construct = construct })

    module FormatterConvert =

        open FormatterLexed

        type Spelling =
            | Words
            | Symbols

        let symbolOf keyword =
            match keyword with
            | SpecInl -> Some ":="
            | SpecLet -> Some ":~"
            | SpecRec -> Some "^"
            | SpecAnd -> Some ":&"
            | SpecIn -> Some ";;"
            | SpecFun -> Some "\\"
            | SpecFunction -> Some "\\|"
            | SpecForall -> Some "\\*"
            | SpecExists -> Some "\\?"
            | SpecIf -> Some "?"
            | SpecThen -> Some "?>"
            | SpecElif -> Some "|?"
            | SpecElse -> Some "|:"
            | SpecMatch -> Some "?="
            | SpecTypecase -> Some "?:"
            | SpecWith -> Some "?|"
            | SpecWithout -> Some "-|"
            | SpecAs -> Some "&="
            | SpecWhen -> Some "?&"
            | SpecType -> Some ":=="
            | SpecNominal -> Some ":!"
            | SpecUnion -> Some ":|"
            | SpecPrototype -> Some ":?"
            | SpecInstance -> Some ":+"
            | SpecOpen -> Some ":<"
            | SpecReal -> Some "~>"
            | SpecJoin -> Some "~~"
            | SpecJoinBackend -> Some "~~>"
            | SpecInm | SpecInb | SpecWildcard -> None

        let wordOf keyword =
            match keyword with
            | SpecIn -> "in" | SpecAnd -> "and" | SpecFun -> "fun" | SpecMatch -> "match" | SpecTypecase -> "typecase"
            | SpecFunction -> "function" | SpecWith -> "with" | SpecWithout -> "without" | SpecAs -> "as" | SpecWhen -> "when"
            | SpecInl -> "inl" | SpecForall -> "forall" | SpecExists -> "exists" | SpecLet -> "let" | SpecInm -> "inm"
            | SpecInb -> "inb" | SpecRec -> "rec" | SpecIf -> "if" | SpecThen -> "then" | SpecElif -> "elif" | SpecElse -> "else"
            | SpecJoin -> "join" | SpecJoinBackend -> "join_backend" | SpecType -> "type" | SpecNominal -> "nominal"
            | SpecReal -> "real" | SpecUnion -> "union" | SpecOpen -> "open" | SpecWildcard -> "_" | SpecPrototype -> "prototype"
            | SpecInstance -> "instance"

        let isWordText (text : string) = text.Length > 0 && (System.Char.IsLetterOrDigit text.[0] || text.[0] = '_')

        let respell (target : Spelling) (lexeme : Lexeme) =
            match target, lexeme.Token with
            | Symbols, TokUnescapedChar c when (c = '@' || c = '#' || c = '$') && lexeme.Text.Text = "\\" + string c -> Some (string c + string c)
            | Words, TokUnescapedChar c when (c = '@' || c = '#' || c = '$') && lexeme.Text.Text = string c + string c -> Some ("\\" + string c)
            | _ when lexeme.InsideMacro -> None
            | _ ->
                match target, lexeme.Token with
                | Symbols, TokKeyword keyword when isWordText lexeme.Text.Text -> symbolOf keyword
                | Symbols, TokValue (LitBool value) when isWordText lexeme.Text.Text -> Some (if value then "!+" else "!-")
                | Words, TokKeyword keyword when not (isWordText lexeme.Text.Text) -> Some (wordOf keyword)
                | Words, TokValue (LitBool value) when not (isWordText lexeme.Text.Text) -> Some (if value then "true" else "false")
                | Symbols, TokSymbol _ when lexeme.Text.Text.StartsWith "." -> Some ("::" + lexeme.Text.Text.Substring 1)
                | Words, TokSymbol _ when lexeme.Text.Text.StartsWith "::" -> Some ("." + lexeme.Text.Text.Substring 2)
                | _ -> None

        let tokenIdentity (token : SpiralToken) =
            match token with
            | TokKeyword keyword -> sprintf "keyword %A" keyword
            | TokValue (LitBool value) -> sprintf "bool %b" value
            | TokOperator (name, _) -> "op " + name
            | TokUnaryOperator (name, _) -> "unary " + name
            | other -> sprintf "%A" other

        let fuses (left : string) (right : string) =
            let last = left.[left.Length - 1]
            let first = right.[0]
            (is_var_char last && is_var_char first) || (is_operator_char last && is_operator_char first && first <> ',')

        type LineConversion =
            | Unchanged
            | Converted of string
            | Rejected of attempted : string

        let headerSpelling (target : Spelling) (lexeme : Lexeme) =
            match target, lexeme.Text.Text with
            | Symbols, "test" -> Some ":#"
            | Words, ":#" -> Some "test"
            | _ -> None

        let convertLine (target : Spelling) (line : Line<'phase>) =
            match line.Shape with
            | Code (_, lexemes, tail) ->
                let header = lexemes.Length > 0 && lexemes.[0].Span.From = 0 && (lexemes.[0].Text.Text = "test" || lexemes.[0].Text.Text = ":#")
                let spelledAt index lexeme =
                    if not header then respell target lexeme
                    elif index = 0 then headerSpelling target lexeme
                    else None
                let pieces = lexemes |> Array.mapi (fun index lexeme -> lexeme, spelledAt index lexeme)
                if pieces |> Array.forall (fun (_, spelled) -> spelled.IsNone) then Unchanged
                else
                    let spell (guarded : bool) =
                        let builder = System.Text.StringBuilder ()
                        pieces
                        |> Array.iteri (fun index (lexeme, spelled) ->
                            let text = defaultArg spelled lexeme.Text.Text
                            if index = 0 then builder.Append (' ', lexeme.Span.From) |> ignore
                            else
                                let previousEnd = (fst pieces.[index - 1]).Span.NearTo
                                let gap = lexeme.Span.From - previousEnd
                                let previousText = match snd pieces.[index - 1] with Some t -> t | None -> (fst pieces.[index - 1]).Text.Text
                                let needsSpace = guarded && gap = 0 && (spelled.IsSome || (snd pieces.[index - 1]).IsSome) && fuses previousText text
                                match lexeme.Before with
                                | Embedded embedded -> builder.Append embedded.Text |> ignore
                                | Whitespace width -> builder.Append (' ', (if needsSpace then max 1 width else width)) |> ignore
                            builder.Append text |> ignore)
                        builder.Append tail.Text |> ignore
                        builder.ToString ()
                    let keepsTokens (attempted : string) =
                        match lexLine lex_state_init attempted with
                        | Code (_, relexed, _), _ -> (relexed |> Array.map (fun l -> tokenIdentity l.Token)) = (lexemes |> Array.map (fun l -> tokenIdentity l.Token))
                        | _ -> false
                    let tight = spell false
                    if keepsTokens tight then Converted tight
                    else
                        let spaced = spell true
                        if keepsTokens spaced then Converted spaced else Rejected spaced
            | _ -> Unchanged

        let convert (target : Spelling) (source : Source<'phase>) =
            let results = source.SourceLines |> Array.map (fun line -> line, convertLine target line)
            let texts =
                results
                |> Array.map (fun (line, result) ->
                    match result with
                    | Converted text -> text
                    | Unchanged | Rejected _ -> render line)
            let rejected = results |> Array.choose (fun (line, result) -> match result with Rejected text -> Some (line.Number, text) | _ -> None)
            let converted = results |> Array.filter (fun (_, result) -> match result with Converted _ -> true | _ -> false) |> Array.length
            texts, converted, rejected

    module FormatterFlatten =

        open System.Text
        open FormatterLexed

        type Unflattenable =
            | MultilineLiteralOrComment
            | CommentWithDelimiters
            | IndentationBelowBlock

        type FlatLine =
            | Kept of string
            | Joined of string * lineStarts : (string * bool) list * sourceLines : (int * string option * string list) list

        type FlatBlock =
            | Flattened of FlatLine list * original : string list
            | Refused of Unflattenable * firstLine : int * lines : string list

        type CodeLine =
            { Number : int
              Indent : int
              Lexemes : Lexeme[]
              Remark : string option
              Leading : string list }

        let blankMarker = "(* *)"

        let leadingPrefix (line : CodeLine) = if line.Leading.IsEmpty then "" else String.concat " " line.Leading + " "

        let codeText (lexemes : Lexeme[]) =
            let builder = StringBuilder ()
            lexemes
            |> Array.iteri (fun index lexeme ->
                if index > 0 then
                    match lexeme.Before with
                    | Whitespace count -> builder.Append (' ', count) |> ignore
                    | Embedded text -> builder.Append text.Text |> ignore
                builder.Append lexeme.Text.Text |> ignore)
            builder.ToString ()

        let inlineComment (text : string) =
            let body = text.Trim ()
            if body.Contains "(*" || body.Contains "*)" then None
            else Some ("(* " + body + " *)")

        let isStatementStart (lexemes : Lexeme[]) =
            match lexemes.[0].Token with
            | TokKeyword (SpecInl | SpecLet | SpecOpen) -> true
            | _ -> false

        let startsAsContinuation (lexemes : Lexeme[]) =
            match lexemes.[0].Token with
            | TokOperator _ -> true
            | TokKeyword (SpecThen | SpecElse | SpecElif | SpecWith | SpecWhen | SpecIn | SpecAs | SpecAnd) -> true
            | TokParenthesis (_, Close) -> true
            | _ -> false

        type Opening =
            | BodyOpening
            | ItemsOpening
            | GroupOpening
            | NoOpening

        let unclosedCurly (lexemes : Lexeme[]) =
            let depth =
                lexemes
                |> Array.fold (fun depth lexeme ->
                    match lexeme.Token with
                    | TokParenthesis (Curly, Open) when not lexeme.InsideMacro -> depth + 1
                    | TokParenthesis (Curly, Close) when not lexeme.InsideMacro -> depth - 1
                    | _ -> depth) 0
            depth > 0

        let openingOf (lexemes : Lexeme[]) =
            match lexemes.[lexemes.Length - 1].Token with
            | TokKeyword SpecWith when unclosedCurly lexemes -> ItemsOpening
            | TokOperator (("=" | "=>"), _) -> BodyOpening
            | TokKeyword (SpecThen | SpecElse | SpecIn | SpecReal | SpecFunction | SpecWith | SpecJoin | SpecJoinBackend) -> BodyOpening
            | TokParenthesis ((Curly | Square), Open) -> ItemsOpening
            | TokParenthesis (Round, Open) -> GroupOpening
            | _ -> NoOpening

        let lambdaStart (lexemes : Lexeme[]) =
            match lexemes.[lexemes.Length - 1].Token with
            | TokOperator ("=>", _) ->
                let arm = match lexemes.[0].Token with TokOperator ("|", _) -> true | _ -> false
                if arm then None
                else
                    match lexemes |> Array.tryFindIndexBack (fun lexeme -> lexeme.Token = TokKeyword SpecFun || lexeme.Token = TokKeyword SpecFunction) with
                    | Some index -> Some index
                    | None -> lexemes |> Array.tryFindIndex (fun lexeme -> lexeme.Token = TokKeyword SpecForall)
            | _ -> None

        let separatorAfter (typeLevel : bool) (context : Opening) (element : CodeLine) (lastLine : CodeLine) (next : CodeLine) =
            if startsAsContinuation next.Lexemes then " "
            else
                match lastLine.Lexemes.[lastLine.Lexemes.Length - 1].Token with
                | TokOperator _ | TokParenthesis (_, Open) -> " "
                | TokKeyword (SpecThen | SpecElse | SpecIn | SpecWith | SpecFun) -> " "
                | _ when context = ItemsOpening -> "; "
                | _ when typeLevel -> " "
                | _ when context = NoOpening -> " "
                | _ when isStatementStart element.Lexemes -> " in "
                | _ -> " . "

        let roundDepth (lexemes : Lexeme[]) =
            lexemes
            |> Array.fold (fun depth lexeme ->
                match lexeme.Token with
                | TokParenthesis (Round, Open) when not lexeme.InsideMacro -> depth + 1
                | TokParenthesis (Round, Close) when not lexeme.InsideMacro -> depth - 1
                | _ -> depth) 0

        let itemDepth (lexemes : Lexeme[]) =
            lexemes
            |> Array.fold (fun depth lexeme ->
                match lexeme.Token with
                | TokParenthesis ((Curly | Square), Open) when not lexeme.InsideMacro -> depth + 1
                | TokParenthesis ((Curly | Square), Close) when not lexeme.InsideMacro -> depth - 1
                | _ -> depth) 0

        let remarkSuffix (line : CodeLine) = match line.Remark with Some comment when comment <> "" -> " " + comment | _ -> ""

        let rec flattenRegion (typeLevel : bool) (context : Opening) (lines : CodeLine list) : string =
            match lines with
            | [] -> ""
            | first :: _ ->
                let column = first.Indent
                let rec split (rest : CodeLine list) =
                    match rest with
                    | [] -> []
                    | head :: tail ->
                        let inside = tail |> List.takeWhile (fun line -> line.Indent > column)
                        (head, inside) :: split (List.skip inside.Length tail)
                let rec elementText (head : CodeLine) (inside : CodeLine list) =
                    let prefix = leadingPrefix head
                    if prefix <> "" then prefix + elementText { head with Leading = [] } inside else
                    let headText = codeText head.Lexemes + remarkSuffix head
                    if inside.IsEmpty then headText
                    else
                        let opening =
                            match openingOf head.Lexemes with
                            | BodyOpening when context = ItemsOpening && head.Lexemes.[head.Lexemes.Length - 1].Token = TokKeyword SpecWith -> ItemsOpening
                            | other -> other
                        let quotesTerm =
                            head.Lexemes.Length >= 2
                            && (match head.Lexemes.[head.Lexemes.Length - 2].Token with TokUnaryOperator ("`", _) -> true | _ -> false)
                        let innerTypeLevel = typeLevel && not quotesTerm
                        let trailingClosers =
                            List.rev inside |> List.takeWhile (fun line -> match line.Lexemes.[0].Token with TokParenthesis (Round, Close) -> true | _ -> false) |> List.rev
                        let beforeClosers = List.take (inside.Length - trailingClosers.Length) inside
                        let unclosedRound = roundDepth head.Lexemes > 0 && roundDepth head.Lexemes + (beforeClosers |> List.sumBy (fun line -> roundDepth line.Lexemes)) > 0
                        let closers, bodyLines = if unclosedRound then trailingClosers, beforeClosers else [], inside
                        let closerText = closers |> List.map (fun line -> codeText line.Lexemes + remarkSuffix line) |> String.concat " "
                        let withClosers (text : string) = if closerText = "" then text else text + " " + closerText
                        if bodyLines.IsEmpty then withClosers headText else
                        let body = flattenRegion innerTypeLevel opening bodyLines
                        let armsOrCases = match (List.head bodyLines).Lexemes.[0].Token with TokOperator ("|", _) -> true | _ -> false
                        let armColumn = (List.head bodyLines).Indent
                        let operatorAfterArms =
                            if not armsOrCases || innerTypeLevel || opening <> BodyOpening then None
                            else
                                bodyLines
                                |> List.tryFindIndex (fun line -> line.Indent = armColumn && (match line.Lexemes.[0].Token with TokOperator (name, _) -> name <> "|" | _ -> false))
                                |> Option.bind (fun at ->
                                    head.Lexemes
                                    |> Array.tryFindIndexBack (fun lexeme -> not lexeme.InsideMacro && (lexeme.Token = TokKeyword SpecFunction || lexeme.Token = TokKeyword SpecMatch))
                                    |> Option.map (fun opener -> at, opener))
                        match operatorAfterArms with
                        | Some (at, opener) when closers.IsEmpty ->
                            let arms = flattenRegion innerTypeLevel opening (List.take at bodyLines)
                            let after = flattenRegion typeLevel NoOpening (List.skip at bodyLines)
                            let before = if opener = 0 then "" else codeText head.Lexemes.[0 .. opener - 1] + " "
                            before + "(" + codeText head.Lexemes.[opener ..] + " " + arms + ")" + remarkSuffix head + " " + after
                        | _ ->
                        match opening with
                        | BodyOpening when innerTypeLevel || armsOrCases -> withClosers (headText + " " + body)
                        | BodyOpening ->
                            match lambdaStart head.Lexemes with
                            | Some index when not unclosedRound ->
                                let before = if index = 0 then "" else codeText head.Lexemes.[0 .. index - 1] + " "
                                before + "(" + codeText head.Lexemes.[index ..] + " (" + body + "))" + remarkSuffix head
                            | _ -> withClosers (headText + " (" + body + ")")
                        | ItemsOpening | GroupOpening | NoOpening -> withClosers (headText + " " + body)
                let opensScope (head : CodeLine) =
                    head.Lexemes
                    |> Array.exists (fun lexeme ->
                        not lexeme.InsideMacro
                        && (match lexeme.Token with
                            | TokKeyword (SpecFun | SpecFunction | SpecMatch | SpecIf | SpecInl | SpecLet) -> true
                            | _ -> false))
                let continues (last : CodeLine) (next : CodeLine) =
                    startsAsContinuation next.Lexemes
                    || (match last.Lexemes.[last.Lexemes.Length - 1].Token with
                        | TokOperator _ | TokParenthesis (_, Open) -> true
                        | TokKeyword (SpecThen | SpecElse | SpecIn | SpecWith | SpecFun) -> true
                        | _ -> false)
                let items =
                    let grouped = ResizeArray<ResizeArray<CodeLine * CodeLine list>> ()
                    let rec absorbBody (elements : (CodeLine * CodeLine list) list) =
                        match elements with
                        | (head, []) :: rest when not rest.IsEmpty && (match head.Lexemes.[head.Lexemes.Length - 1].Token with TokOperator ("=", _) | TokKeyword SpecJoin -> true | _ -> false) ->
                            [ (head, rest |> List.collect (fun (h, i) -> h :: i)) ]
                        | (head, inside) :: rest when not rest.IsEmpty && not inside.IsEmpty && (let last = List.last inside in match last.Lexemes.[last.Lexemes.Length - 1].Token with TokOperator ("=", _) | TokKeyword SpecJoin -> true | _ -> false) ->
                            let last = List.last inside
                            let absorbed = rest |> List.collect (fun (h, i) -> h :: i)
                            let shift = last.Indent + 4 - (absorbed |> List.map (fun line -> line.Indent) |> List.min)
                            [ (head, inside @ (absorbed |> List.map (fun line -> { line with Indent = line.Indent + max 0 shift }))) ]
                        | (head, inside) :: rest when not rest.IsEmpty && (let last = (match List.tryLast inside with Some l -> l | None -> head) in match last.Lexemes.[last.Lexemes.Length - 1].Token with TokKeyword (SpecThen | SpecElse) | TokOperator ("=>", _) -> true | _ -> false)
                                                      && not (startsAsContinuation (fst (List.head rest)).Lexemes) ->
                            let last = match List.tryLast inside with Some l -> l | None -> head
                            let taken =
                                let balanceOf (h : CodeLine, i : CodeLine list) = (h :: i) |> List.sumBy (fun line -> itemDepth line.Lexemes + roundDepth line.Lexemes)
                                let opensArms (h : CodeLine, i : CodeLine list) =
                                    let lastLine = match List.tryLast i with Some line -> line | None -> h
                                    match lastLine.Lexemes.[lastLine.Lexemes.Length - 1].Token with
                                    | TokKeyword (SpecWith | SpecFunction) -> true
                                    | _ -> false
                                let isArm (h : CodeLine) = match h.Lexemes.[0].Token with TokOperator ("|", _) -> true | _ -> false
                                let rec take (items : (CodeLine * CodeLine list) list) (openIfs : int) (balance : int) (armsOpen : bool) =
                                    match items with
                                    | (h, i) :: tail when balance > 0 && balance + balanceOf (h, i) >= 0 ->
                                        (h, i) :: take tail openIfs (balance + balanceOf (h, i)) (armsOpen || opensArms (h, i))
                                    | (h, i) :: tail when armsOpen && isArm h ->
                                        (h, i) :: take tail openIfs (balance + balanceOf (h, i)) true
                                    | (h, i) :: tail when not (startsAsContinuation h.Lexemes) ->
                                        let opensIf = h.Lexemes.[0].Token = TokKeyword SpecIf
                                        (h, i) :: take tail (if opensIf then openIfs + 1 else openIfs) (balance + balanceOf (h, i)) (armsOpen || opensArms (h, i))
                                    | (h, i) :: tail when openIfs > 0 && (h.Lexemes.[0].Token = TokKeyword SpecElse || h.Lexemes.[0].Token = TokKeyword SpecElif || h.Lexemes.[0].Token = TokKeyword SpecThen) ->
                                        (h, i) :: take tail (if h.Lexemes.[0].Token = TokKeyword SpecElse then openIfs - 1 else openIfs) (balance + balanceOf (h, i)) armsOpen
                                    | _ -> []
                                take rest 0 0 false
                            let remaining = List.skip taken.Length rest
                            let absorbed = taken |> List.collect (fun (h, i) -> h :: i)
                            let shift = last.Indent + 4 - (absorbed |> List.map (fun line -> line.Indent) |> List.min)
                            (head, inside @ (absorbed |> List.map (fun line -> { line with Indent = line.Indent + max 0 shift }))) :: absorbBody remaining
                        | element :: rest -> element :: absorbBody rest
                        | [] -> []
                    let mutable openBrackets = 0
                    for (head, inside) in absorbBody (split lines) do
                        let lastOfCurrent =
                            if grouped.Count = 0 then None
                            else
                                let (h, i) = grouped.[grouped.Count - 1].[grouped.[grouped.Count - 1].Count - 1]
                                Some (match List.tryLast i with Some line -> line | None -> h)
                        let balance = itemDepth head.Lexemes + (inside |> List.sumBy (fun line -> itemDepth line.Lexemes))
                        match lastOfCurrent with
                        | Some last when openBrackets > 0 || continues last head ->
                            grouped.[grouped.Count - 1].Add (head, inside)
                            openBrackets <- openBrackets + balance
                        | _ ->
                            grouped.Add (ResizeArray [ (head, inside) ])
                            openBrackets <- max 0 balance
                    grouped |> Seq.map List.ofSeq |> List.ofSeq
                let statementRegion = not typeLevel && context <> ItemsOpening && context <> NoOpening && items.Length > 1
                let openerIndex (lexemes : Lexeme[]) =
                    let mutable depth = 0
                    let mutable found = None
                    for index in 0 .. lexemes.Length - 1 do
                        let lexeme = lexemes.[index]
                        if not lexeme.InsideMacro && found.IsNone then
                            match lexeme.Token with
                            | TokParenthesis (_, Open) -> depth <- depth + 1
                            | TokParenthesis (_, Close) -> depth <- max 0 (depth - 1)
                            | TokKeyword (SpecFun | SpecFunction | SpecMatch | SpecIf | SpecReal | SpecJoin | SpecJoinBackend) when depth = 0 -> found <- Some index
                            | _ -> ()
                    found
                let isOperatorContinuation (head : CodeLine) =
                    match head.Lexemes.[0].Token with
                    | TokOperator (name, _) -> name <> "|"
                    | _ -> false
                let itemText (item : (CodeLine * CodeLine list) list) =
                    let array = Array.ofList item
                    let first = fst array.[0]
                    let builder = StringBuilder ()
                    let openers = System.Collections.Generic.Stack<int * bool> ()
                    let note (head : CodeLine) (start : int) =
                        let isArm = match head.Lexemes.[0].Token with TokOperator ("|", _) -> true | _ -> false
                        if not isArm then
                            match openerIndex head.Lexemes with
                            | Some at ->
                                let prefix = (leadingPrefix head).Length + (if at = 0 then 0 else (codeText head.Lexemes.[0 .. at - 1]).Length + 1)
                                openers.Push ((start + prefix, head.Lexemes.[at].Token = TokKeyword SpecIf))
                            | None -> ()
                    let close (stopAtIf : bool) =
                        let mutable stop = false
                        while openers.Count > 0 && not stop do
                            let position, isIf = openers.Peek ()
                            if stopAtIf && isIf then stop <- true
                            else
                                openers.Pop () |> ignore
                                builder.Insert (position, "(") |> ignore
                                builder.Append ")" |> ignore
                    let depthOf (head : CodeLine, inside : CodeLine list) = itemDepth head.Lexemes + (inside |> List.sumBy (fun line -> itemDepth line.Lexemes))
                    let mutable bracketDepth = depthOf array.[0]
                    note first 0
                    builder.Append (elementText first (snd array.[0])) |> ignore
                    for index in 1 .. array.Length - 1 do
                        let head, inside = array.[index]
                        let previousHead, previousInside = array.[index - 1]
                        let previousLast = match List.tryLast previousInside with Some line -> line | None -> previousHead
                        let previousOpen =
                            match previousLast.Lexemes.[previousLast.Lexemes.Length - 1].Token with
                            | TokOperator _ | TokParenthesis (_, Open) -> true
                            | _ -> false
                        let field = bracketDepth > 0 && not previousOpen && not (startsAsContinuation head.Lexemes)
                        bracketDepth <- bracketDepth + depthOf (head, inside)
                        if isOperatorContinuation head then close false
                        else
                            match head.Lexemes.[0].Token with
                            | TokKeyword (SpecThen | SpecElse | SpecElif) -> close true
                            | _ -> ()
                        builder.Append (if field then "; " else " ") |> ignore
                        let start = builder.Length
                        note head start
                        builder.Append (elementText head inside) |> ignore
                    let text = builder.ToString ()
                    let head = first
                    if context = NoOpening && head.Indent > 0 && opensScope head && not (startsAsContinuation head.Lexemes) then "(" + text + ")"
                    elif statementRegion && not (isStatementStart head.Lexemes) then "(" + text + ")"
                    else text
                let rec join (items : (CodeLine * CodeLine list) list list) =
                    match items with
                    | [] -> ""
                    | item :: rest ->
                        let text = itemText item
                        match rest with
                        | [] -> text
                        | next :: _ ->
                            let head = fst (List.head item)
                            let nextHead = fst (List.head next)
                            let separator =
                                if context = ItemsOpening then "; "
                                elif typeLevel || context = NoOpening then " "
                                elif isStatementStart head.Lexemes then " in "
                                else " . "
                            let tail = join rest
                            let tail = if separator = " . " && isStatementStart nextHead.Lexemes then "(" + tail + ")" else tail
                            text + separator + tail
                join items

        let segmentHead = "inl spiral_format_segment () ="
        let segmentTail = "spiral_format_segment_end"

        let flattenBlock (lines : Line<'phase> list) : FlatBlock =
            let leading = lines |> List.takeWhile (fun line -> match line.Shape with Code (0, _, _) -> false | _ -> true)
            let afterLeading = lines |> List.skip leading.Length
            let lastCode = afterLeading |> List.tryFindIndexBack (fun line -> match line.Shape with Code _ | Opaque _ -> true | _ -> false)
            let rest, trailingLines =
                match lastCode with
                | Some at -> List.take (at + 1) afterLeading, List.skip (at + 1) afterLeading
                | None -> afterLeading, []
            let leadingText = leading |> List.map (fun line -> Kept (render line))
            let trailingText = trailingLines |> List.map (fun line -> Kept (render line))
            if rest |> List.exists (fun line -> match line.Shape with Opaque _ -> true | _ -> false) then
                Refused (MultilineLiteralOrComment, (List.head lines).Number, lines |> List.map render)
            elif rest.IsEmpty then Flattened (leadingText @ trailingText, [])
            else
                let code = ResizeArray<CodeLine> ()
                let pending = ResizeArray<string> ()
                let mutable refused = None
                for line in rest do
                    match line.Shape with
                    | Code (indent, lexemes, tail) ->
                        let remark = if tail.Text.Trim().Length = 0 then None else inlineComment tail.Text
                        if tail.Text.Trim().Length > 0 && remark.IsNone then refused <- Some CommentWithDelimiters
                        code.Add { Number = line.Number; Indent = indent; Lexemes = lexemes; Remark = remark; Leading = List.ofSeq pending }
                        pending.Clear ()
                    | Remark text ->
                        match inlineComment text.Text with
                        | Some comment -> pending.Add comment
                        | None -> refused <- Some CommentWithDelimiters
                    | Blank -> if code.Count > 0 && (pending.Count = 0 || pending.[pending.Count - 1] <> blankMarker) then pending.Add blankMarker
                    | Opaque _ -> ()

                match refused with
                | Some reason -> Refused (reason, (List.head lines).Number, lines |> List.map render)
                | None ->
                    let typeLevel =
                        match code.[0].Lexemes.[0].Token with
                        | TokKeyword (SpecType | SpecNominal | SpecUnion | SpecPrototype) -> true
                        | TokKeyword SpecAnd when code.[0].Lexemes.Length > 1 && code.[0].Lexemes.[1].Token = TokKeyword SpecUnion -> true
                        | _ -> false
                    let startsArm (line : CodeLine) = match line.Lexemes.[0].Token with TokOperator ("|", _) -> true | _ -> false
                    let endsWithArrow (line : CodeLine) = match line.Lexemes.[line.Lexemes.Length - 1].Token with TokOperator ("=>", _) -> true | _ -> false
                    let guardOnOwnLine (previous : CodeLine) (line : CodeLine) =
                        line.Lexemes.[0].Token = TokKeyword SpecWhen && line.Leading.IsEmpty && previous.Remark.IsNone
                        && startsArm previous && not (endsWithArrow previous) && line.Indent > previous.Indent
                    let armsWithGuards =
                        code
                        |> Seq.fold (fun (merged : CodeLine list) line ->
                            match merged with
                            | previous :: earlier when guardOnOwnLine previous line ->
                                let glued = Array.append [| { line.Lexemes.[0] with Before = Whitespace 1 } |] line.Lexemes.[1..]
                                { previous with Lexemes = Array.append previous.Lexemes glued; Remark = line.Remark } :: earlier
                            | _ -> line :: merged) []
                        |> List.rev
                    let text = flattenRegion typeLevel NoOpening armsWithGuards
                    let lineStarts = [ for line in armsWithGuards do for index in 0 .. line.Lexemes.Length - 1 -> line.Lexemes.[index].Text.Text, index = 0 ]
                    let writtenLexemes = code |> Seq.map (fun line -> line.Number, line.Lexemes.Length) |> dict
                    let sourceLines =
                        [ for line in armsWithGuards ->
                            let unmerged = writtenLexemes.[line.Number] = line.Lexemes.Length
                            let written =
                                match line.Remark with
                                | None -> Some (codeText line.Lexemes)
                                | Some remark when remark.StartsWith "(* //" && remark.EndsWith " *)" -> Some (codeText line.Lexemes + " " + remark.Substring (3, remark.Length - 6))
                                | Some _ -> None
                            line.Indent, (if unmerged then written else None), line.Leading ]
                    Flattened (leadingText @ [ Joined (text, lineStarts, sourceLines) ] @ trailingText, rest |> List.map render)

        let segmentBlocks (lines : Line<'phase> list) : FlatBlock list option =
            let isOpaque (line : Line<'phase>) = match line.Shape with Opaque _ -> true | _ -> false
            let kept (part : Line<'phase> list) = Flattened (part |> List.map (fun line -> Kept (render line)), [])
            let leading = lines |> List.takeWhile (fun line -> match line.Shape with Code (0, _, _) -> false | _ -> true)
            let rest = lines |> List.skip leading.Length
            let endsWithEquals (line : Line<'phase>) =
                match line.Shape with
                | Code (_, lexemes, _) when lexemes.Length > 0 -> (match lexemes.[lexemes.Length - 1].Token with TokOperator ("=", _) -> true | _ -> false)
                | _ -> false
            if not (rest |> List.exists isOpaque) then None
            else
                match List.tryFindIndex endsWithEquals rest with
                | Some headEnd when not (List.take (headEnd + 1) rest |> List.exists isOpaque) ->
                    let head = List.take (headEnd + 1) rest
                    let body = List.skip (headEnd + 1) rest
                    let codeIndents = body |> List.choose (fun line -> match line.Shape with Code (indent, _, _) -> Some indent | _ -> None)
                    match codeIndents with
                    | 4 :: _ when codeIndents |> List.forall (fun indent -> indent >= 4) ->
                        let statements = ResizeArray<Line<'phase> list> ()
                        let current = ResizeArray<Line<'phase>> ()
                        let opensStatement (line : Line<'phase>) (previousOpaque : bool) =
                            match line.Shape with
                            | Code (4, _, _) -> true
                            | Opaque (verbatim, _) -> not previousOpaque && verbatim.Text.Length > 4 && verbatim.Text.StartsWith "    " && verbatim.Text.[4] <> ' '
                            | _ -> false
                        let mutable previousOpaque = false
                        for line in body do
                            if opensStatement line previousOpaque && current |> Seq.exists (fun l -> match l.Shape with Code _ | Opaque _ -> true | _ -> false) then
                                statements.Add (List.ofSeq current)
                                current.Clear ()
                            current.Add line
                            previousOpaque <- isOpaque line
                        if current.Count > 0 then statements.Add (List.ofSeq current)
                        let synthetic (number : int) (text : string) = { Number = number; Shape = fst (lexLine lex_state_init text) }
                        let laid (run : Line<'phase> list) =
                            match flattenBlock ((synthetic (-1) segmentHead :: run) @ [ synthetic (-2) ("    " + segmentTail) ]) with
                            | Flattened _ as block -> block
                            | Refused _ -> kept run
                        let headFits = head |> List.forall (fun line -> displayWidth (render line) <= 120)
                        let headBlock =
                            if headFits then kept head
                            else
                                match flattenBlock (head @ [ synthetic (-2) ("    " + segmentTail) ]) with
                                | Flattened _ as block -> block
                                | Refused _ -> kept head
                        let blocks = ResizeArray<FlatBlock> (if leading.IsEmpty then [ headBlock ] else [ kept leading; headBlock ])
                        let run = ResizeArray<Line<'phase>> ()
                        let flush () =
                            if run.Count > 0 then
                                blocks.Add (laid (List.ofSeq run))
                                run.Clear ()
                        for statement in statements do
                            if statement |> List.exists isOpaque then
                                flush ()
                                blocks.Add (kept statement)
                            else run.AddRange statement
                        flush ()
                        Some (List.ofSeq blocks)
                    | _ -> None
                | _ -> None

        let flattenBlocks (lines : Line<'phase> list) : FlatBlock list =
            match segmentBlocks lines with
            | Some blocks -> blocks
            | None -> [ flattenBlock lines ]

        let blocksOf (source : Source<'phase>) =
            let lines = List.ofArray source.SourceLines
            let rec split (rest : Line<'phase> list) (current : Line<'phase> list) (seenCode : bool) =
                match rest with
                | [] -> if current.IsEmpty then [] else [ List.rev current ]
                | line :: tail ->
                    let startsBlock = match line.Shape with Code (0, _, _) -> true | _ -> false
                    let isLead = match line.Shape with Remark _ | Blank -> true | _ -> false
                    if startsBlock && seenCode then List.rev current :: split tail [ line ] true
                    elif isLead && seenCode && (match tail |> List.tryFind (fun l -> match l.Shape with Remark _ | Blank -> false | _ -> true) with Some next -> (match next.Shape with Code (0, _, _) -> true | _ -> false) | None -> false) && (match line.Shape with Remark text -> not (text.Text.StartsWith " ") | _ -> true) then
                        List.rev current :: split tail [ line ] false
                    else split tail (line :: current) (seenCode || startsBlock)
            split lines [] false

        let flatten (source : Source<'phase>) =
            let blocks = blocksOf source |> List.collect flattenBlocks
            let lines =
                blocks
                |> List.collect (function
                    | Flattened (flat, _) -> flat |> List.map (function Kept text | Joined (text, _, _) -> text)
                    | Refused (_, _, original) -> original)
            lines, blocks

    module FormatterLayout =

        open System.Text
        open FormatterLexed
        open FormatterFlatten
        open FormatterParsed

        type Node =
            | Leaf of Lexeme
            | Group of opening : Lexeme * inner : Node list * closing : Lexeme

        type LaidLine = { Indent : int; Text : string }

        let rec firstLexeme (node : Node) =
            match node with
            | Leaf lexeme -> lexeme
            | Group (opening, _, _) -> opening

        let isStringGroup (node : Node) =
            match node with
            | Group (opening, _, _) -> opening.Token = TokStringOpen
            | _ -> false

        let isConcatOperator (node : Node) =
            match node with
            | Leaf lexeme -> not lexeme.InsideMacro && (match lexeme.Token with TokOperator ("^^", _) -> true | _ -> false)
            | _ -> false

        let rec mergeConcatenations (nodes : Node list) : Node list =
            match nodes with
            | (Group (opening, inner, _) as first) :: op :: (Group (_, nextInner, nextClosing) as second) :: rest when isStringGroup first && isConcatOperator op && isStringGroup second ->
                let glued =
                    match nextInner with
                    | Leaf lexeme :: tail -> Leaf { lexeme with Before = Whitespace 0 } :: tail
                    | other -> other
                mergeConcatenations (Group (opening, inner @ glued, nextClosing) :: rest)
            | node :: rest -> node :: mergeConcatenations rest
            | [] -> []

        let rec nodesOf (lexemes : Lexeme list) : Node list * Lexeme list =
            match lexemes with
            | [] -> [], []
            | lexeme :: rest ->
                match lexeme.Token with
                | TokParenthesis (_, Open) when not lexeme.InsideMacro ->
                    let inner, afterInner = nodesOf rest
                    match afterInner with
                    | closing :: afterClosing ->
                        let siblings, remaining = nodesOf afterClosing
                        Group (lexeme, inner, closing) :: siblings, remaining
                    | [] -> [ Leaf lexeme ], []
                | TokParenthesis (_, Close) when not lexeme.InsideMacro -> [], lexemes
                | TokStringOpen | TokMacroOpen ->
                    let closing = match lexeme.Token with TokStringOpen -> TokStringClose | _ -> TokMacroClose
                    let rec collect (rest : Lexeme list) (depth : int) (taken : Lexeme list) =
                        match rest with
                        | next :: tail when next.Token = lexeme.Token -> collect tail (depth + 1) (next :: taken)
                        | next :: tail when next.Token = closing && depth = 0 -> List.rev taken, Some next, tail
                        | next :: tail when next.Token = closing -> collect tail (depth - 1) (next :: taken)
                        | next :: tail -> collect tail depth (next :: taken)
                        | [] -> List.rev taken, None, []
                    match collect rest 0 [] with
                    | inside, Some closingLexeme, after ->
                        let siblings, remaining = nodesOf after
                        Group (lexeme, inside |> List.map Leaf, closingLexeme) :: siblings, remaining
                    | _ ->
                        let siblings, remaining = nodesOf rest
                        Leaf lexeme :: siblings, remaining
                | _ ->
                    let siblings, remaining = nodesOf rest
                    Leaf lexeme :: siblings, remaining

        let gapBefore (lexeme : Lexeme) =
            match lexeme.Before with
            | Whitespace 0 -> ""
            | Whitespace _ -> " "
            | Embedded text when text.Text.Replace("(* *)", "").Trim().Length = 0 -> " "
            | Embedded text -> text.Text

        let commaBeforeKeyword (nodes : Node list) =
            nodes
            |> List.takeWhile (fun node -> match node with Leaf l -> not (not l.InsideMacro && (match l.Token with TokKeyword _ -> true | _ -> false)) | Group _ -> true)
            |> List.exists (fun node -> match node with Leaf l -> not l.InsideMacro && (match l.Token with TokOperator (",", _) -> true | _ -> false) | Group _ -> false)

        let rec simplify (nodes : Node list) : Node list =
            let isRound (opening : Lexeme) = opening.Token = TokParenthesis (Round, Open)
            let mapped =
                nodes
                |> List.map (fun node ->
                    match node with
                    | Group (opening, [ Group (innerOpening, inner, innerClosing) ], _) when isRound opening && isRound innerOpening && not inner.IsEmpty ->
                        Group (opening, simplify inner, innerClosing)
                    | Group (opening, inner, closing) -> Group (opening, simplify inner, closing)
                    | Leaf _ -> node)
            let rec afterArrow (rest : Node list) =
                match rest with
                | arrow :: [ Group (opening, inner, _) ] when (match arrow with Leaf l -> (match l.Token with TokOperator ("=>", _) | TokKeyword (SpecThen | SpecElse | SpecIn) -> not l.InsideMacro | _ -> false) | Group _ -> false)
                                                             && isRound opening && not inner.IsEmpty && not (match inner with Leaf l :: _ -> (match l.Token with TokKeyword (SpecInl | SpecLet | SpecOpen) -> true | _ -> false) | _ -> false) && not (List.exists (function Leaf l -> not l.InsideMacro && (l.Token = TokKeyword SpecIn || (match l.Token with TokOperator (".", _) -> true | _ -> false)) | Group _ -> false) inner) && ((match arrow with Leaf l -> (match l.Token with TokOperator ("=>", _) -> true | _ -> false) | Group _ -> false) || not (commaBeforeKeyword inner) || (match inner with Leaf l :: _ -> (match l.Token with TokKeyword _ -> true | _ -> false) | _ -> false)) ->
                    [ arrow ] @ withGap arrow inner
                | node :: tail -> node :: afterArrow tail
                | [] -> []
            and withGap (arrow : Node) (inner : Node list) =
                match inner with
                | Leaf first :: tail -> Leaf { first with Before = Whitespace 1 } :: tail
                | Group (opening, i, c) :: tail -> Group ({ opening with Before = Whitespace 1 }, i, c) :: tail
                | [] -> []

            afterArrow mapped

        let authoredBreaks = new System.Threading.ThreadLocal<System.Collections.Generic.HashSet<int>> (fun () -> System.Collections.Generic.HashSet<int> ())
        let syntheticTokens = new System.Threading.ThreadLocal<System.Collections.Generic.HashSet<int>> (fun () -> System.Collections.Generic.HashSet<int> ())
        let authoredBreakMark = '\u0001'
        let syntheticMark = '\u0002'

        let appendMarked (builder : StringBuilder) (lexeme : Lexeme) =
            if builder.Length > 0 && authoredBreaks.Value.Contains lexeme.Span.From then builder.Append authoredBreakMark |> ignore
            if syntheticTokens.Value.Contains lexeme.Span.From then builder.Append syntheticMark |> ignore
            builder.Append lexeme.Text.Text |> ignore

        let markedText (lexeme : Lexeme) = (if syntheticTokens.Value.Contains lexeme.Span.From then string syntheticMark else "") + lexeme.Text.Text

        let stripMarks (text : string) = text.Replace(string authoredBreakMark, "").Replace(string syntheticMark, "")

        let dropSyntheticParentheses (text : string) =
            let builder = StringBuilder ()
            let mutable index = 0
            while index < text.Length do
                let current = text.[index]
                if current = syntheticMark && index + 1 < text.Length && (text.[index + 1] = '(' || text.[index + 1] = ')') then index <- index + 2
                elif current = syntheticMark || current = authoredBreakMark then index <- index + 1
                else
                    builder.Append current |> ignore
                    index <- index + 1
            builder.ToString ()

        let liftSyntheticGroups (lines : string list) =
            let opener = string syntheticMark + "("
            let closer = string syntheticMark + ")"
            let indentOf (line : string) = line.Length - line.TrimStart(' ').Length
            let laid = Array.ofList lines
            let output = ResizeArray<string> ()
            let shifts = System.Collections.Generic.Stack<int> ()
            let mutable shifted = 0
            for index in 0 .. laid.Length - 1 do
                let line = laid.[index]
                let trimmed = line.Trim ()
                if trimmed = opener && index + 1 < laid.Length then
                    let shift = max 0 (indentOf laid.[index + 1] - indentOf line)
                    shifts.Push shift
                    shifted <- shifted + shift
                elif trimmed = closer && shifts.Count > 0 then shifted <- shifted - shifts.Pop ()
                else output.Add (line.Substring (min shifted (indentOf line)))
            List.ofSeq output

        let tokenLines = new System.Threading.ThreadLocal<System.Collections.Generic.Dictionary<int, int>> (fun () -> System.Collections.Generic.Dictionary<int, int> ())
        let sourceLineTable = new System.Threading.ThreadLocal<(int * string option * string list)[]> (fun () -> [||])
        let sourceLineTokens = new System.Threading.ThreadLocal<int[]> (fun () -> [||])
        let relaidSpans = new System.Threading.ThreadLocal<System.Collections.Generic.List<int * int>> (fun () -> System.Collections.Generic.List<int * int> ())
        let relayOnly = new System.Threading.ThreadLocal<int[] option> (fun () -> None)


        let markAuthoredBreaks (lexemes : Lexeme[]) (lineStarts : (string * bool) list) (sourceLines : (int * string option * string list) list) =
            let breaks = authoredBreaks.Value
            let synthetic = syntheticTokens.Value
            let lines = tokenLines.Value
            breaks.Clear ()
            synthetic.Clear ()
            lines.Clear ()
            let table = Array.ofList sourceLines
            let counts = Array.zeroCreate<int> table.Length
            let starts = Array.ofList lineStarts
            let mutable next = 0
            let mutable line = -1
            let mutable aligned = true
            for lexeme in lexemes do
                if next < starts.Length && lexeme.Text.Text = fst starts.[next] then
                    if snd starts.[next] then
                        line <- line + 1
                        if next > 0 then breaks.Add lexeme.Span.From |> ignore
                    if line >= 0 && line < counts.Length then
                        lines.[lexeme.Span.From] <- line
                        counts.[line] <- counts.[line] + 1
                    else aligned <- false
                    next <- next + 1
                else synthetic.Add lexeme.Span.From |> ignore
            if next < starts.Length || not aligned then
                breaks.Clear ()
                synthetic.Clear ()
                lines.Clear ()
                sourceLineTable.Value <- [||]
                sourceLineTokens.Value <- [||]
            else
                sourceLineTable.Value <- table
                sourceLineTokens.Value <- counts

        let rec inlineText (raw : Node list) =
            let nodes = simplify raw
            let builder = StringBuilder ()
            let rec emit (first : bool) (node : Node) =
                match node with
                | Leaf lexeme ->
                    if not first then builder.Append (gapBefore lexeme) |> ignore
                    appendMarked builder lexeme
                | Group (opening, inner, closing) ->
                    if not first then builder.Append (gapBefore opening) |> ignore
                    appendMarked builder opening
                    let padded =
                        not inner.IsEmpty
                        && not opening.InsideMacro
                        && (match opening.Token with
                            | TokParenthesis (Square, Open) -> true
                            | TokParenthesis (Curly, Open) -> (match (firstLexeme (List.head inner)).Before with Whitespace 0 -> false | _ -> true)
                            | _ -> false)
                    if padded then builder.Append ' ' |> ignore
                    inner |> List.iteri (fun index child -> emit (index = 0) child)
                    if padded then builder.Append ' ' |> ignore
                    appendMarked builder closing
            nodes |> List.iteri (fun index node -> emit (index = 0) node)
            builder.ToString ()

        let bareTrailingLambda (list : Node list) =
            let isRound (opening : Lexeme) = opening.Token = TokParenthesis (Round, Open)
            let rec strip (node : Node) =
                match node with
                | Group (opening, [ (Group (innerOpening, _, _) as inner) ], _) when isRound opening && isRound innerOpening -> strip inner
                | _ -> node
            match List.rev list with
            | last :: before ->
                match strip last with
                | Group (opening, (first :: _ as inner), _) when isRound opening && (match first with Leaf l -> not l.InsideMacro && (l.Token = TokKeyword SpecFun || l.Token = TokKeyword SpecFunction) | Group _ -> false) ->
                    List.rev before @ (match inner with Leaf l :: tail -> Leaf { l with Before = Whitespace 1 } :: tail | other -> other)
                | _ -> list
            | _ -> list

        let inlineComplete (nodes : Node list) = inlineText (bareTrailingLambda (simplify nodes))

        let isKeyword (keyword : TokenKeyword) (node : Node) =
            match node with
            | Leaf lexeme -> not lexeme.InsideMacro && lexeme.Token = TokKeyword keyword
            | Group _ -> false

        let isOperator (name : string) (node : Node) =
            match node with
            | Leaf lexeme -> not lexeme.InsideMacro && (match lexeme.Token with TokOperator (found, _) -> found = name | _ -> false)
            | Group _ -> false

        let splitOn (separator : Node -> bool) (nodes : Node list) =
            let segments = ResizeArray<Node list> ()
            let current = ResizeArray<Node> ()
            let mutable quantified = false
            for node in nodes do
                if isKeyword SpecForall node || isKeyword SpecExists node then quantified <- true
                if quantified && isOperator "." node then
                    quantified <- false
                    current.Add node
                elif separator node then
                    segments.Add (List.ofSeq current)
                    current.Clear ()
                else current.Add node
            segments.Add (List.ofSeq current)
            List.ofSeq segments

        let isStatement (nodes : Node list) =
            match nodes with
            | first :: _ -> isKeyword SpecInl first || isKeyword SpecLet first || isKeyword SpecOpen first
            | [] -> false

        let commentsIn (gap : string) =
            let parts = ResizeArray<string> ()
            let mutable rest = gap
            while rest.Contains "(*" && rest.Contains "*)" do
                let start = rest.IndexOf "(*"
                let stop = rest.IndexOf ("*)", start)
                parts.Add (rest.Substring(start + 2, stop - start - 2).Trim ())
                rest <- rest.Substring (stop + 2)
            List.ofSeq parts
        let trailingRemark (node : Node) =
            match node with
            | Leaf lexeme ->
                match lexeme.Before with
                | Embedded gap -> (commentsIn gap.Text |> List.filter (fun comment -> comment <> "")).Length = 1
                | Whitespace _ -> false
            | Group _ -> false

        let statements (nodes : Node list) =
            let segments = ResizeArray<Node list> ()
            let current = ResizeArray<Node> ()
            let mutable openStatements = 0
            let mutable quantified = false
            let mutable inArms = false
            for node in nodes do
                if isKeyword SpecForall node || isKeyword SpecExists node then quantified <- true
                if openStatements = 0 && (isKeyword SpecWith node || isKeyword SpecFunction node) then inArms <- true
                if quantified && isOperator "." node then
                    quantified <- false
                    current.Add node
                elif isKeyword SpecIn node then
                    openStatements <- openStatements - 1
                    if openStatements = 0 then
                        if trailingRemark node then current.Add node
                        segments.Add (List.ofSeq current)
                        current.Clear ()
                    else current.Add node
                elif isOperator "." node && openStatements = 0 && not inArms then
                    if trailingRemark node then current.Add node
                    segments.Add (List.ofSeq current)
                    current.Clear ()
                else
                    if (isKeyword SpecInl node || isKeyword SpecLet node || isKeyword SpecOpen node) && not (current.Count > 0 && isKeyword SpecAnd (current.[current.Count - 1])) then openStatements <- openStatements + 1
                    current.Add node
            segments.Add (List.ofSeq current)
            segments |> List.ofSeq |> List.filter (fun segment -> not segment.IsEmpty)

        let hasTopComma (nodes : Node list) = commaBeforeKeyword nodes

        let startsWithKeyword (nodes : Node list) =
            match nodes with
            | Leaf lexeme :: _ -> not lexeme.InsideMacro && (match lexeme.Token with TokKeyword _ -> true | _ -> false)
            | _ -> false

        let rec unwrapBody (nodes : Node list) =
            match nodes with
            | [ Group (opening, inner, _) ] when opening.Token = TokParenthesis (Round, Open) && not inner.IsEmpty ->
                let plain (gap : Gap) = match gap with Whitespace _ -> true | Embedded _ -> false
                let carried =
                    match inner with
                    | Leaf first :: tail when not (plain opening.Before) && plain first.Before -> Leaf { first with Before = opening.Before } :: tail
                    | Group (innerOpening, innerNodes, innerClosing) :: tail when not (plain opening.Before) && plain innerOpening.Before ->
                        Group ({ innerOpening with Before = opening.Before }, innerNodes, innerClosing) :: tail
                    | _ -> inner
                unwrapBody carried
            | _ -> nodes

        let fits (indent : int) (text : string) = indent + displayWidth text <= 120

        let indexOfTop (predicate : Node -> bool) (nodes : Node list) =
            let mutable quantified = false
            let mutable found = None
            nodes
            |> List.iteri (fun index node ->
                if found.IsNone then
                    if isKeyword SpecForall node || isKeyword SpecExists node then quantified <- true
                    if quantified && isOperator "." node then quantified <- false
                    elif not quantified && predicate node then found <- Some index)
            found


        let rec withoutLeadingGap (nodes : Node list) : Node list * string list =
            match nodes with
            | Leaf lexeme :: tail ->
                match lexeme.Before with
                | Embedded gap -> Leaf { lexeme with Before = Whitespace 1 } :: tail, commentsIn gap.Text
                | Whitespace _ -> nodes, []
            | Group (opening, inner, closing) :: tail ->
                match opening.Before with
                | Embedded gap -> Group ({ opening with Before = Whitespace 1 }, inner, closing) :: tail, commentsIn gap.Text
                | Whitespace _ -> nodes, []
            | [] -> [], []

        let splitArms (nodes : Node list) : (string list * Node list) list =
            let arms = ResizeArray<string list * Node list> ()
            let current = ResizeArray<Node> ()
            let mutable carried : string list = []
            let mutable quantified = false
            let flush () =
                if current.Count > 0 then
                    let stripped, leading = withoutLeadingGap (List.ofSeq current)
                    arms.Add (carried @ leading, stripped)
                    carried <- []
                current.Clear ()
            for node in nodes do
                if isKeyword SpecForall node || isKeyword SpecExists node then quantified <- true
                if quantified && isOperator "." node then
                    quantified <- false
                    current.Add node
                elif isOperator "|" node then
                    flush ()
                    match node with
                    | Leaf lexeme ->
                        match lexeme.Before with
                        | Embedded gap -> carried <- carried @ commentsIn gap.Text
                        | Whitespace _ -> ()
                    | Group _ -> ()
                else current.Add node
            flush ()
            List.ofSeq arms
        type LiteralSplitting() =
            member val Enabled = false with get, set

        let literalSplitting = LiteralSplitting ()

        let textElementsOf (text : string) : string list =
            let elements = System.Globalization.StringInfo.GetTextElementEnumerator text
            [ while elements.MoveNext () do yield elements.GetTextElement () ]

        let literalChain (indent : int) (node : Node) : LaidLine list option =
            match node with
            | Group (opening, inner, closing) when literalSplitting.Enabled && opening.Token = TokStringOpen && not (fits indent (inlineText [ node ])) ->
                let units =
                    inner
                    |> List.collect (fun child ->
                        match child with
                        | Leaf lexeme ->
                            match lexeme.Token with
                            | TokText text -> textElementsOf lexeme.Text.Text
                            | _ -> [ lexeme.Text.Text ]
                        | _ -> [ inlineText [ child ] ])
                let room = max 40 (120 - indent - 3 - 3)
                let pieces = ResizeArray<string> ()
                let current = StringBuilder ()
                let mutable lastSpace = -1
                let mutable lastNewline = -1
                let mutable width = 0
                for unit in units do
                    current.Append unit |> ignore
                    width <- width + displayWidth unit
                    if unit = " " then lastSpace <- current.Length
                    if unit = "\\n" then lastNewline <- current.Length
                    if width >= room then
                        let cut = if lastNewline > room / 4 then lastNewline elif lastSpace > room / 2 then lastSpace else current.Length
                        let text = current.ToString ()
                        pieces.Add (text.Substring (0, cut))
                        current.Clear().Append (text.Substring cut) |> ignore
                        width <- displayWidth (current.ToString ())
                        lastSpace <- -1
                        lastNewline <- -1
                if current.Length > 0 then pieces.Add (current.ToString ())
                Some (pieces |> List.ofSeq |> List.mapi (fun index piece -> { Indent = indent; Text = (if index = 0 then "" else "^^ ") + "\"" + piece + "\"" }))
            | _ -> None

        let gluedWords (nodes : Node list) : Node list list =
            nodes
            |> List.fold (fun (words : Node list list) node ->
                match words, (firstLexeme node).Before with
                | word :: earlier, Whitespace 0 -> (word @ [ node ]) :: earlier
                | _ -> [ node ] :: words) []
            |> List.rev

        let splitMacroLine (line : string) : string list =
            if not literalSplitting.Enabled || line.Length <= 120 then [ line ]
            else
                match lexLine lex_state_init line with
                | Code (indent, lexemes, tail), _ when tail.Text.Trim().Length = 0 ->
                    let opens = lexemes |> Array.indexed |> Array.filter (fun (_, lexeme) -> lexeme.Token = TokMacroOpen) |> Array.map fst
                    let spans =
                        opens
                        |> Array.choose (fun start ->
                            let rec find index depth =
                                if index >= lexemes.Length then None
                                else
                                    match lexemes.[index].Token with
                                    | TokMacroOpen when index <> start -> find (index + 1) (depth + 1)
                                    | TokMacroClose when depth = 0 -> Some index
                                    | TokMacroClose -> find (index + 1) (depth - 1)
                                    | _ -> find (index + 1) depth
                            find (start + 1) 0 |> Option.map (fun stop -> start, stop))
                    match spans |> Array.filter (fun (start, stop) -> lexemes.[stop].Span.NearTo - lexemes.[start].Span.From >= 24) |> Array.sortByDescending (fun (start, stop) -> lexemes.[stop].Span.NearTo - lexemes.[start].Span.From) |> Array.tryHead with
                    | Some (start, stop) ->
                        let openText = lexemes.[start].Text.Text
                        let closeText = lexemes.[stop].Text.Text
                        let units =
                            let rec collect index (acc : string list) =
                                if index >= stop then List.rev acc
                                else
                                    let lexeme = lexemes.[index]
                                    let gapBefore at = line.Substring (lexemes.[at - 1].Span.NearTo, lexemes.[at].Span.From - lexemes.[at - 1].Span.NearTo)
                                    match lexeme.Token with
                                    | TokMacroExpression (_, Open) ->
                                        let rec closing at depth =
                                            if at >= stop then stop - 1
                                            else
                                                match lexemes.[at].Token with
                                                | TokMacroExpression (_, Close) when depth = 0 -> at
                                                | TokMacroExpression (_, Close) -> closing (at + 1) (depth - 1)
                                                | TokMacroExpression (_, Open) -> closing (at + 1) (depth + 1)
                                                | _ -> closing (at + 1) depth
                                        let last = closing (index + 1) 0
                                        let whole = gapBefore index + line.Substring (lexeme.Span.From, lexemes.[last].Span.NearTo - lexeme.Span.From)
                                        collect (last + 1) (whole :: acc)
                                    | TokText _ when (gapBefore index).Length = 0 -> collect (index + 1) (List.rev (textElementsOf lexeme.Text.Text) @ acc)
                                    | _ -> collect (index + 1) ((gapBefore index + lexeme.Text.Text) :: acc)
                            collect (start + 1) []
                        let prefix = line.Substring (0, lexemes.[start].Span.From)
                        let suffix = line.Substring lexemes.[stop].Span.NearTo
                        let roomFor (index : int) = max 40 (if index = 0 then 120 - prefix.Length - openText.Length - 2 else 120 - indent - 4 - 2)
                        let pieces = ResizeArray<string> ()
                        let current = StringBuilder ()
                        let mutable lastSpace = -1
                        let mutable lastCommaSpace = -1
                        let mutable lastSemicolonSpace = -1
                        let rec glueHoles (pending : string list) =
                            match pending with
                            | "{" :: expression :: "}" :: rest when expression.StartsWith "!" -> ("{" + expression + "}") :: glueHoles rest
                            | unit :: rest -> unit :: glueHoles rest
                            | [] -> []
                        for unit in glueHoles units do
                            current.Append unit |> ignore
                            let leadingSpaces = unit.Length - unit.TrimStart(' ').Length
                            let spaceAt =
                                if unit = " " then Some (current.Length, current.Length - 2)
                                elif leadingSpaces > 0 && leadingSpaces < unit.Length then Some (current.Length - unit.Length + leadingSpaces, current.Length - unit.Length - 1)
                                else None
                            match spaceAt with
                            | Some (after, before) ->
                                lastSpace <- after
                                if before >= 0 && current.[before] = ',' then lastCommaSpace <- after
                                if before >= 0 && current.[before] = ';' then lastSemicolonSpace <- after
                            | None -> ()
                            let room = roomFor pieces.Count
                            if current.Length >= room then
                                let cut = if lastSemicolonSpace > room / 2 then lastSemicolonSpace elif lastCommaSpace > room / 2 then lastCommaSpace elif lastSpace > room / 2 then lastSpace else current.Length
                                let text = current.ToString ()
                                pieces.Add (text.Substring (0, cut))
                                current.Clear().Append (text.Substring cut) |> ignore
                                lastSpace <- -1
                                lastCommaSpace <- -1
                                lastSemicolonSpace <- -1
                        if current.Length > 0 then pieces.Add (current.ToString ())
                        let pieces =
                            pieces
                            |> List.ofSeq
                            |> List.fold (fun (kept : string list) piece ->
                                let leadingSpaces = piece.Length - piece.TrimStart(' ').Length
                                match kept with
                                | previous :: earlier when leadingSpaces > 0 -> piece.Substring leadingSpaces :: (previous + piece.Substring (0, leadingSpaces)) :: earlier
                                | _ -> piece :: kept) []
                            |> List.rev
                            |> List.filter (fun piece -> piece.Length > 0)
                        if pieces.Length < 2 || roomFor 0 < 12 || pieces |> List.exists (fun piece -> piece.StartsWith " ") then [ line ]
                        else
                            let continuation = System.String (' ', indent + 4)
                            pieces
                            |> List.mapi (fun index piece ->
                                let lead = if index = 0 then prefix + openText else continuation
                                let trail = if index = pieces.Length - 1 then closeText + suffix else "\\"
                                lead + piece + trail)
                    | None -> [ line ]
                | _ -> [ line ]

        let rec lexemesOfNodes (nodes : Node list) : Lexeme list =
            nodes |> List.collect (fun node -> match node with Leaf lexeme -> [ lexeme ] | Group (opening, inner, closing) -> opening :: lexemesOfNodes inner @ [ closing ])

        let asWrittenStatement (indent : int) (nodes : Node list) : LaidLine list option =
            let table = sourceLineTable.Value
            if table.Length = 0 then None
            else
                let owned = lexemesOfNodes nodes |> List.filter (fun lexeme -> not (syntheticTokens.Value.Contains lexeme.Span.From))
                let lineOf (lexeme : Lexeme) = match tokenLines.Value.TryGetValue lexeme.Span.From with | true, line -> line | _ -> -1
                let lines = owned |> List.map lineOf
                match lines with
                | [] -> None
                | first :: _ when List.contains -1 lines -> None
                | first :: _ ->
                    let last = List.max lines
                    let total = [ first .. last ] |> List.sumBy (fun line -> sourceLineTokens.Value.[line])
                    let ordered = lines |> List.pairwise |> List.forall (fun (a, b) -> a <= b)
                    if not ordered || total <> owned.Length then None
                    else
                        let baseIndent = let i, _, _ = table.[first] in i
                        let candidate =
                            [ for line in first .. last ->
                                let i, text, leading = table.[line]
                                i - baseIndent + indent, text, (if line > first then leading else []) ]
                        let splitLater (i : int) (text : string) =
                            match splitMacroLine (System.String (' ', i) + text) with
                            | [ _ ] -> false
                            | pieces -> pieces |> List.forall (fun piece -> piece.Length <= 120)
                        let remarkOf (entry : string) =
                            if entry.StartsWith "(* //" && entry.EndsWith " *)" then Some (entry.Substring (3, entry.Length - 6)) else None
                        let keepable (i : int) (text : string option) (leading : string list) =
                            i >= 0
                            && leading |> List.forall (fun entry -> entry = blankMarker || (remarkOf entry).IsSome)
                            && (match text with Some t -> fits i t || splitLater i t | None -> false)
                        let joinHeads =
                            owned
                            |> List.pairwise
                            |> List.filter (fun (opening, keyword) ->
                                opening.Token = TokParenthesis (Round, Open)
                                && not opening.InsideMacro
                                && isKeyword SpecJoin (Leaf keyword)
                                && lineOf opening = lineOf keyword
                                && (owned |> List.tryFind (fun other -> lineOf other = lineOf opening) |> Option.exists (fun other -> other.Span.From = opening.Span.From)))
                            |> List.map (fun (opening, _) -> lineOf opening)
                            |> Set.ofList
                        let bareJoinHeads (rows : (int * string option * string list) list) =
                            let rows = Array.ofList rows
                            for at in 0 .. rows.Length - 2 do
                                match rows.[at], rows.[at + 1] with
                                | (i, Some t, leading), (ni, Some next, _) when Set.contains (first + at) joinHeads && ni = i && next.StartsWith "|> " && t.StartsWith "(join " && t.EndsWith ")" && not (t.Contains "\"") && not (t.Contains "'('") && not (t.Contains "')'") ->
                                    let inner = t.Substring (1, t.Length - 2)
                                    let mutable depth = 0
                                    let mutable balanced = true
                                    for c in inner do
                                        if c = '(' then depth <- depth + 1
                                        elif c = ')' then
                                            depth <- depth - 1
                                            if depth < 0 then balanced <- false
                                    if balanced && depth = 0 then rows.[at] <- (i, Some inner, leading)
                                | _ -> ()
                            List.ofArray rows
                        let asWritten () =
                            Some (bareJoinHeads candidate |> List.collect (fun (i, text, leading) ->
                                (leading |> List.map (fun entry -> match remarkOf entry with Some remark -> { Indent = i; Text = remark } | None -> { Indent = 0; Text = "" }))
                                @ [ { Indent = i; Text = Option.get text } ]))
                        let complete = candidate |> List.forall (fun (i, text, leading) -> i >= 0 && text.IsSome && leading |> List.forall (fun entry -> entry = blankMarker || (remarkOf entry).IsSome))
                        if candidate |> List.forall (fun (i, text, leading) -> keepable i text leading) then asWritten ()
                        else
                            match relayOnly.Value with
                            | Some allowed when complete && not (Array.contains first allowed) -> asWritten ()
                            | Some _ -> None
                            | None ->
                                relaidSpans.Value.Add ((first, last))
                                None

        let rec layoutBlock (indent : int) (nodes : Node list) : LaidLine list =
            let parts = statements nodes
            if parts.Length > 1 then parts |> List.collect (layoutRecursiveGroup indent)
            else layoutRecursiveGroup indent nodes

        and layoutRecursiveGroup (indent : int) (nodes : Node list) : LaidLine list =
            let andAt =
                nodes
                |> List.indexed
                |> List.filter (fun (index, node) -> index > 0 && isKeyword SpecAnd node && (match List.tryItem (index + 1) nodes with Some next -> isKeyword SpecInl next || isKeyword SpecLet next | None -> false))
                |> List.map fst
            if andAt.IsEmpty || not (isStatement nodes) then layoutStatement indent nodes
            else
                let bounds = (0 :: andAt) @ [ nodes.Length ]
                List.pairwise bounds
                |> List.collect (fun (a, b) ->
                    let part = nodes.[a .. b - 1]
                    if a = 0 then layoutStatement indent part
                    else
                        match layoutStatement indent (List.tail part) with
                        | first :: rest when fits first.Indent ("and " + first.Text) -> { first with Text = "and " + first.Text } :: rest
                        | _ ->
                            match layoutStatement (indent + 4) (List.tail part) |> List.map (fun line -> if line.Text = "" then line else { line with Indent = line.Indent - 4 }) with
                            | first :: rest -> { first with Text = "and " + first.Text } :: rest
                            | [] -> [])

        and attachRemark (indent : int) (remark : string) (lines : LaidLine list) : LaidLine list =
            match List.rev lines with
            | last :: before when fits last.Indent (last.Text + " " + remark) -> List.rev ({ last with Text = last.Text + " " + remark } :: before)
            | _ :: _ -> { Indent = indent; Text = remark } :: lines
            | [] -> [ { Indent = indent; Text = remark } ]

        and layoutStatement (indent : int) (wrapped : Node list) : LaidLine list =
            let closingRemark =
                match wrapped with
                | [ Group (opening, inner, closing) ] when opening.Token = TokParenthesis (Round, Open) && not opening.InsideMacro && not inner.IsEmpty ->
                    match closing.Before with
                    | Embedded gap when (commentsIn gap.Text |> List.filter (fun comment -> comment <> "")).Length = 1 && (commentsIn gap.Text |> List.filter (fun comment -> comment <> "") |> List.head).StartsWith "//" ->
                        Some (commentsIn gap.Text |> List.filter (fun comment -> comment <> "") |> List.head, Group (opening, inner, { closing with Before = Whitespace 0 }))
                    | _ -> None
                | _ -> None
            match closingRemark with
            | Some (remark, bare) ->
                attachRemark indent remark (layoutStatement indent [ bare ])
            | None ->
            let stripped, comments = withoutLeadingGap (unwrapBody wrapped)
            if not comments.IsEmpty then
                (comments |> List.map (fun comment -> if comment = "" then { Indent = 0; Text = "" } else { Indent = indent; Text = comment })) @ layoutStatement indent stripped
            else
            match List.tryLast stripped with
            | Some (Leaf last as node) when (isKeyword SpecIn node || isOperator "." node) && trailingRemark node ->
                let remark = match last.Before with Embedded gap -> commentsIn gap.Text |> List.filter (fun comment -> comment <> "") |> String.concat " " | Whitespace _ -> ""
                attachRemark indent remark (layoutStatement indent (List.take (stripped.Length - 1) stripped))
            | _ ->
            let nodes = stripped
            match asWrittenStatement indent nodes with
            | Some lines -> lines
            | None ->
            match nodes with
            | first :: second :: _ when isKeyword SpecAnd first && (isKeyword SpecInl second || isKeyword SpecLet second) ->
                match layoutStatement indent (List.tail nodes) with
                | head :: rest -> { head with Text = inlineText [ first ] + " " + head.Text } :: rest
                | [] -> []
            | _ ->
            if (statements nodes).Length > 1 then layoutBlock indent nodes else
            let whole = inlineComplete nodes
            let unionAt = nodes |> List.tryFindIndex (fun node -> isKeyword SpecUnion node)
            match nodes with
            | first :: _ when (isKeyword SpecUnion first || (isKeyword SpecAnd first && unionAt = Some 1)) && (indexOfTop (isOperator "=") nodes).IsSome ->
                let at = (indexOfTop (isOperator "=") nodes).Value
                let cases = splitOn (isOperator "|") (List.skip (at + 1) nodes) |> List.filter (fun case -> not case.IsEmpty)
                let headText = inlineText (List.take (at + 1) nodes)
                let headLines = if fits indent headText then [ { Indent = indent; Text = headText } ] else packNodes indent "" "" (List.take (at + 1) nodes)
                headLines @ (cases |> List.collect (layoutUnionCase (indent + 4)))
            | first :: _ when (isKeyword SpecType first || isKeyword SpecNominal first) && (indexOfTop (isOperator "=") nodes).IsSome
                              && (match List.skip ((indexOfTop (isOperator "=") nodes).Value + 1) nodes with
                                  | [ Leaf quote; Group (opening, inner, _) ] -> quote.Token = TokUnaryOperator ("`", SemanticTokenLegend.unary_operator) && opening.Token = TokParenthesis (Round, Open) && ((statements inner).Length > 1 || not (fits indent whole))
                                  | _ -> false) ->
                let at = (indexOfTop (isOperator "=") nodes).Value
                match List.skip (at + 1) nodes with
                | [ Leaf quote; Group (opening, inner, closing) ] ->
                    { Indent = indent; Text = inlineText (List.take (at + 1) nodes) }
                    :: { Indent = indent + 4; Text = quote.Text.Text + (markedText opening) }
                    :: layoutBlock (indent + 8) inner
                    @ [ { Indent = indent + 4; Text = (markedText closing) } ]
                | _ -> [ { Indent = indent; Text = whole } ]
            | first :: _ when (isKeyword SpecType first || isKeyword SpecNominal first) && (indexOfTop (isOperator "=") nodes).IsSome && (not (fits indent whole) || (isKeyword SpecType first && (match List.skip ((indexOfTop (isOperator "=") nodes).Value + 1) nodes with [ record ] -> (match fieldRecord record with Some _ -> true | None -> false) | _ -> false))) ->
                let at = (indexOfTop (isOperator "=") nodes).Value
                match List.skip (at + 1) nodes with
                | [ Group (opening, inner, closing) ] when opening.Token = TokParenthesis (Curly, Open) ->
                    { Indent = indent; Text = inlineText (List.take (at + 1) nodes) }
                    :: { Indent = indent + 4; Text = (markedText opening) }
                    :: (splitOn (isOperator ";") inner |> List.filter (fun field -> not field.IsEmpty) |> List.map (fun field -> { Indent = indent + 8; Text = inlineText field }))
                    @ [ { Indent = indent + 4; Text = (markedText closing) } ]
                | prefix when (match List.tryLast prefix with Some (Group (opening, _, _)) -> opening.Token = TokParenthesis (Curly, Open) | _ -> false) ->
                    match List.last prefix with
                    | Group (opening, inner, closing) ->
                        { Indent = indent; Text = inlineText (List.take (at + 1) nodes) }
                        :: { Indent = indent + 4; Text = inlineText (List.take (prefix.Length - 1) prefix) + " " + (markedText opening) }
                        :: (splitOn (isOperator ";") inner |> List.filter (fun field -> not field.IsEmpty) |> List.map (fun field -> { Indent = indent + 8; Text = inlineText field }))
                        @ [ { Indent = indent + 4; Text = (markedText closing) } ]
                    | _ -> [ { Indent = indent; Text = whole } ]
                | body when not (fits indent whole) ->
                    let head = List.take (at + 1) nodes
                    let headLines = if fits indent (inlineText head) then [ { Indent = indent; Text = inlineText head } ] else packNodes indent "" "" head
                    headLines @ layoutType (indent + 4) "" body
                | _ -> [ { Indent = indent; Text = whole } ]
            | Leaf head :: _ when indent = 0 && head.Token = TokVar ("test", SemanticTokenLegend.variable) && (List.tryFindIndex (isOperator "=") nodes).IsSome ->
                let at = (List.tryFindIndex (isOperator "=") nodes).Value
                { Indent = indent; Text = inlineText (List.take (at + 1) nodes) } :: layoutBlock (indent + 4) (unwrapBody (List.skip (at + 1) nodes))
            | first :: _ when isKeyword SpecInl first || isKeyword SpecLet first || (isKeyword SpecInstance first && indent = 0) ->
                match indexOfTop (isOperator "=") nodes with
                | Some at ->
                    let head = List.take (at + 1) nodes
                    let body = unwrapBody (List.skip (at + 1) nodes)
                    let headText = inlineText head
                    let bodyParts = statements body
                    let functionBody = match body with first :: (next :: _) when isKeyword SpecFunction first && isOperator "|" next -> true | _ -> false
                    if functionBody then
                        let arms = splitArms (List.tail body)
                        { Indent = indent; Text = headText + " function" } :: layoutArms (indent + 4) arms
                    elif bodyParts.Length = 1 && fits indent (headText + " " + inlineComplete body) && (indent > 0 || isKeyword SpecInstance first) && not (opensLayout body) then [ { Indent = indent; Text = headText + " " + inlineComplete body } ]
                    elif indent > 0 && not (List.exists isPipe body) && fits indent headText && bodyParts.Length = 1 && (lastArgumentLambda indent headText body).IsSome && (trailingLambdaNeedsBlock body || not (fits indent whole)) then
                        (lastArgumentLambda indent headText body).Value
                    else
                        match asWrittenStatement indent head with
                        | Some lines -> lines @ layoutBlock (indent + 4) body
                        | None when fits indent headText -> { Indent = indent; Text = headText } :: layoutBlock (indent + 4) body
                        | None -> layoutHead indent (List.take at nodes) @ [ { Indent = indent + 4; Text = "=" } ] @ layoutBlock (indent + 4) body
                | None -> [ { Indent = indent; Text = whole } ]
            | _ -> layoutExpression indent nodes

        and packNodes (indent : int) (prefix : string) (suffix : string) (nodes : Node list) : LaidLine list =
            let lines = ResizeArray<LaidLine> ()
            let current = ResizeArray<Node> ()
            let mutable lineIndent = indent
            let mutable linePrefix = prefix
            for word in gluedWords nodes do
                let candidate = linePrefix + inlineText (List.ofSeq current @ word)
                if current.Count > 0 && not (fits lineIndent (candidate + suffix)) then
                    lines.Add { Indent = lineIndent; Text = linePrefix + inlineText (List.ofSeq current) }
                    current.Clear ()
                    lineIndent <- indent + 4
                    linePrefix <- ""
                current.AddRange word
            if current.Count > 0 then lines.Add { Indent = lineIndent; Text = linePrefix + inlineText (List.ofSeq current) + suffix }
            List.ofSeq lines

        and layoutUnionCase (indent : int) (case : Node list) : LaidLine list =
            let whole = "| " + inlineText case
            if fits indent whole then [ { Indent = indent; Text = whole } ]
            else
                let afterForall =
                    match case |> List.tryFindIndex (fun node -> isKeyword SpecForall node) with
                    | Some forallAt ->
                        match case |> List.skip forallAt |> List.tryFindIndex (isOperator ".") with
                        | Some dot -> forallAt + dot + 1
                        | None -> 0
                    | None -> 0
                let headEnd =
                    if afterForall > 0 then afterForall
                    else
                        match indexOfTop (isOperator "::") case with
                        | Some at -> at + 1
                        | None -> match indexOfTop (isOperator ":") case with Some at -> at + 1 | None -> 0
                if headEnd = 0 then packNodes indent "| " "" case
                else
                    let headLines = packNodes indent "| " "" (List.take headEnd case)
                    let body = List.skip headEnd case
                    let segments = splitOn (isOperator "->") body |> List.filter (fun segment -> not segment.IsEmpty)
                    let segmentLines =
                        segments
                        |> List.mapi (fun index segment ->
                            let arrow = if index < segments.Length - 1 then " ->" else ""
                            if fits (indent + 4) (inlineText segment + arrow) then [ { Indent = indent + 4; Text = inlineText segment + arrow } ]
                            else
                            match segment with
                            | [ Group (opening, inner, closing) ] when opening.Token = TokParenthesis (Curly, Open) && not opening.InsideMacro && not inner.IsEmpty ->
                                { Indent = indent + 4; Text = (markedText opening) }
                                :: (splitOn (isOperator ";") inner |> List.filter (fun field -> not field.IsEmpty) |> List.map (fun field -> { Indent = indent + 8; Text = inlineText field }))
                                @ [ { Indent = indent + 4; Text = (markedText closing) + arrow } ]
                            | _ -> layoutType (indent + 4) arrow segment)
                        |> List.concat
                    headLines @ segmentLines

        and quantifierPrefix (nodes : Node list) =
            match nodes with
            | first :: _ when isKeyword SpecExists first || isKeyword SpecForall first ->
                nodes |> List.tryFindIndex (isOperator ".") |> Option.filter (fun dot -> dot + 1 < nodes.Length) |> Option.map (fun dot -> List.take (dot + 1) nodes, List.skip (dot + 1) nodes)
            | _ -> None

        and layoutTypeSeparated (at : int) (suffix : string) (separator : string) (parts : Node list list) : LaidLine list =
            parts
            |> List.mapi (fun position part -> layoutType at (if position < parts.Length - 1 then " " + separator else suffix) part)
            |> List.concat

        and layoutType (at : int) (suffix : string) (nodes : Node list) : LaidLine list =
            let whole = inlineText nodes
            let topLevel (separator : string) = splitOn (isOperator separator) nodes |> List.filter (fun part -> not part.IsEmpty)
            if fits at (whole + suffix) then [ { Indent = at; Text = whole + suffix } ]
            else
            match quantifierPrefix nodes with
            | Some (prefix, body) ->
                let prefixLines = if fits at (inlineText prefix) then [ { Indent = at; Text = inlineText prefix } ] else packNodes at "" "" prefix
                prefixLines @ layoutType (at + 4) suffix body
            | None ->
            if (topLevel "->").Length > 1 then layoutTypeSeparated at suffix "->" (topLevel "->")
            elif (topLevel "*").Length > 1 then layoutTypeSeparated at suffix "*" (topLevel "*")
            else
            match nodes with
            | [ Group (opening, inner, closing) ] when opening.Token = TokParenthesis (Round, Open) && not opening.InsideMacro && not inner.IsEmpty ->
                match quantifierPrefix inner with
                | Some (prefix, body) when fits at ((markedText opening) + inlineText prefix) ->
                    { Indent = at; Text = (markedText opening) + inlineText prefix } :: layoutType (at + 4) ((markedText closing) + suffix) body
                | _ -> { Indent = at; Text = (markedText opening) } :: layoutType (at + 4) "" inner @ [ { Indent = at; Text = (markedText closing) + suffix } ]
            | [ Group (opening, inner, closing) ] when opening.Token = TokParenthesis (Curly, Open) && not opening.InsideMacro && not inner.IsEmpty ->
                let fields = splitOn (isOperator ";") inner |> List.filter (fun field -> not field.IsEmpty)
                let fieldLines (field : Node list) =
                    match indexOfTop (isOperator ":") field with
                    | Some colon when colon > 0 && not (fits (at + 4) (inlineText field)) ->
                        { Indent = at + 4; Text = inlineText (List.take (colon + 1) field) } :: layoutType (at + 8) "" (List.skip (colon + 1) field)
                    | _ -> [ { Indent = at + 4; Text = inlineText field } ]
                { Indent = at; Text = (markedText opening) } :: (fields |> List.collect fieldLines) @ [ { Indent = at; Text = (markedText closing) + suffix } ]
            | _ ->
                let plainWord (word : Node list) = word |> List.forall (fun node -> match node with Leaf lexeme -> not lexeme.InsideMacro | Group _ -> false)
                match gluedWords nodes with
                | callee :: arguments when not arguments.IsEmpty && fits at (inlineText callee) && List.forall plainWord arguments ->
                    let lines = ResizeArray<LaidLine> [ { Indent = at; Text = inlineText callee } ]
                    let current = ResizeArray<Node> ()
                    for word in arguments do
                        if current.Count > 0 && not (fits (at + 4) (inlineText (List.ofSeq current @ word) + suffix)) then
                            lines.Add { Indent = at + 4; Text = inlineText (List.ofSeq current) }
                            current.Clear ()
                        current.AddRange word
                    lines.Add { Indent = at + 4; Text = inlineText (List.ofSeq current) + suffix }
                    List.ofSeq lines
                | callee :: arguments when not arguments.IsEmpty && fits at (inlineText callee) ->
                    let lines = ResizeArray<LaidLine> [ { Indent = at; Text = inlineText callee } ]
                    let run = ResizeArray<Node> ()
                    let flush (last : bool) =
                        if run.Count > 0 then
                            lines.Add { Indent = at + 4; Text = inlineText (List.ofSeq run) + (if last then suffix else "") }
                            run.Clear ()
                    arguments
                    |> List.iteri (fun position argument ->
                        let last = position = arguments.Length - 1
                        if plainWord argument then
                            if run.Count > 0 && not (fits (at + 4) (inlineText (List.ofSeq run @ argument) + suffix)) then flush false
                            run.AddRange argument
                            if last then flush true
                        else
                            flush false
                            lines.AddRange (layoutType (at + 4) (if last then suffix else "") argument))
                    List.ofSeq lines
                | _ -> [ { Indent = at; Text = whole + suffix } ]

        and layoutHead (indent : int) (head : Node list) : LaidLine list =
            let afterForall =
                match head |> List.tryFindIndex (fun node -> isKeyword SpecForall node) with
                | Some forallAt ->
                    match head |> List.skip forallAt |> List.tryFindIndex (isOperator ".") with
                    | Some dot -> forallAt + dot + 1
                    | None -> 0
                | None -> 0
            let nameEnd =
                if afterForall > 0 then afterForall
                else
                    let leading = head |> List.takeWhile (fun node -> isKeyword SpecInl node || isKeyword SpecLet node || isKeyword SpecRec node)
                    min head.Length (leading.Length + 1)
            let first = List.take nameEnd head
            let rest = List.skip nameEnd head
            let annotationAt = indexOfTop (isOperator ":") rest
            let parameters, annotation =
                match annotationAt with
                | Some at -> List.take at rest, List.skip at rest
                | None -> rest, []
            let packed = ResizeArray<LaidLine> ()
            let current = ResizeArray<Node> ()
            let wideParameter (parameter : Node) =
                match parameter with
                | Group (opening, inner, closing) when opening.Token = TokParenthesis (Round, Open) && not (fits (indent + 4) (inlineText [ parameter ])) ->
                    match List.rev inner with
                    | Group (tupleOpening, tupleInner, tupleClosing) :: before when tupleOpening.Token = TokParenthesis (Round, Open) && hasTopComma tupleInner ->
                        let items = splitOn (isOperator ",") tupleInner |> List.filter (fun item -> not item.IsEmpty)
                        let head = (markedText opening) + (if before.IsEmpty then "" else inlineText (List.rev before) + " ") + (markedText tupleOpening)
                        Some (
                            { Indent = indent + 4; Text = head }
                            :: (items |> List.mapi (fun index item -> { Indent = indent + 8; Text = inlineText item + (if index < items.Length - 1 then "," else "") }))
                            @ [ { Indent = indent + 4; Text = (markedText tupleClosing) + (markedText closing) } ])
                    | _ ->
                        match indexOfTop (isOperator ":") inner with
                        | Some colon when colon > 0 && colon < inner.Length - 1 && fits (indent + 4) ((markedText opening) + inlineText (List.take (colon + 1) inner)) ->
                            Some ({ Indent = indent + 4; Text = (markedText opening) + inlineText (List.take (colon + 1) inner) } :: layoutType (indent + 8) (markedText closing) (List.skip (colon + 1) inner))
                        | _ ->
                            let bareName (node : Node) = match node with Leaf lexeme -> (match lexeme.Token with TokVar _ -> not lexeme.InsideMacro | _ -> false) | Group _ -> false
                            match inner with
                            | Group (recordOpening, names, recordClosing) :: annotation when recordOpening.Token = TokParenthesis (Curly, Open) && not names.IsEmpty && List.forall bareName names ->
                                let closingText = (markedText recordClosing) + (if annotation.IsEmpty then "" else " " + inlineText annotation) + (markedText closing)
                                if fits (indent + 4) closingText then
                                    Some (
                                        { Indent = indent + 4; Text = (markedText opening) + (markedText recordOpening) }
                                        :: (names |> List.map (fun name -> { Indent = indent + 8; Text = inlineText [ name ] }))
                                        @ [ { Indent = indent + 4; Text = closingText } ])
                                else None
                            | _ -> None
                | _ -> None
            for parameter in parameters do
                let candidate = inlineText (List.ofSeq current @ [ parameter ])
                match wideParameter parameter with
                | Some lines ->
                    if current.Count > 0 then packed.Add { Indent = indent + 4; Text = inlineText (List.ofSeq current) }
                    current.Clear ()
                    packed.AddRange lines
                | None ->
                    if current.Count > 0 && not (fits (indent + 4) candidate) then
                        packed.Add { Indent = indent + 4; Text = inlineText (List.ofSeq current) }
                        current.Clear ()
                    current.Add parameter
            if current.Count > 0 then packed.Add { Indent = indent + 4; Text = inlineText (List.ofSeq current) }
            let annotationLines =
                if annotation.IsEmpty then []
                elif fits (indent + 4) (inlineText annotation) then [ { Indent = indent + 4; Text = inlineText annotation } ]
                else
                    let rec typeLines (at : int) (nodes : Node list) : LaidLine list =
                        let packedNodes = packNodes at "" "" nodes
                        match List.rev nodes with
                        | Group (opening, inner, closing) :: before when packedNodes |> List.exists (fun line -> not (fits line.Indent line.Text)) && opening.Token = TokParenthesis (Round, Open) && not inner.IsEmpty && fits at ((if before.IsEmpty then "" else inlineText (List.rev before) + " ") + (markedText opening)) ->
                            { Indent = at; Text = (if before.IsEmpty then "" else inlineText (List.rev before) + " ") + (markedText opening) }
                            :: typeLines (at + 4) inner
                            @ [ { Indent = at; Text = (markedText closing) } ]
                        | _ -> packedNodes
                    let packedAnnotation = typeLines (indent + 4) annotation
                    let typeNodes = List.tail annotation
                    let arrowsOrPairs = (splitOn (isOperator "->") typeNodes |> List.filter (fun part -> not part.IsEmpty)).Length > 1 || (splitOn (isOperator "*") typeNodes |> List.filter (fun part -> not part.IsEmpty)).Length > 1
                    let packedFits = packedAnnotation |> List.forall (fun line -> fits line.Indent line.Text)
                    if packedFits && (packedAnnotation.Length = 1 || not arrowsOrPairs) then packedAnnotation
                    else
                        let colon = inlineText [ List.head annotation ] + " "
                        match layoutType (indent + 4 + colon.Length) "" typeNodes with
                        | first :: rest -> { Indent = indent + 4; Text = colon + first.Text } :: (rest |> List.map (fun line -> { line with Indent = max (indent + 4) (line.Indent - colon.Length) }))
                        | [] -> packedAnnotation
            let firstLines = if fits indent (inlineText first) then [ { Indent = indent; Text = inlineText first } ] else packNodes indent "" "" first
            firstLines @ List.ofSeq packed @ annotationLines

        and longPipeline (nodes : Node list) =
            let firstKeyword = nodes |> List.tryFindIndex (fun node -> match node with Leaf lexeme -> not lexeme.InsideMacro && (match lexeme.Token with TokKeyword _ -> true | _ -> false) | Group _ -> false)
            let limit = defaultArg firstKeyword nodes.Length
            (nodes |> List.indexed |> List.filter (fun (index, node) -> index < limit && isPipe node) |> List.length) >= 3

        and carriesComment (nodes : Node list) =
            let commented (gap : Gap) = match gap with Embedded text -> commentsIn text.Text |> List.exists (fun comment -> comment <> "") | Whitespace _ -> false
            nodes |> List.exists (fun node -> match node with Leaf lexeme -> commented lexeme.Before | Group (opening, inner, closing) -> commented opening.Before || commented closing.Before || carriesComment inner)

        and fieldRecord (node : Node) =
            match node with
            | Group (opening, inner, _) when opening.Token = TokParenthesis (Curly, Open) && not opening.InsideMacro ->
                let fields = splitOn (isOperator ";") inner |> List.filter (fun field -> not field.IsEmpty)
                if fields.Length >= 2 then Some fields else None
            | _ -> None

        and functionRecord (node : Node) =
            match node with
            | Group (opening, inner, _) when opening.Token = TokParenthesis (Curly, Open) && not opening.InsideMacro ->
                splitOn (isOperator ";") inner |> List.exists (fun field -> (indexOfTop (isOperator "=") field).IsSome && field |> List.exists (fun part -> isKeyword SpecFun part || (match unwrapLambda [ part ] with first :: _ -> isKeyword SpecFun first | [] -> false)))
            | _ -> false

        and splitListLambda (nodes : Node list) : (Node list * Node * Node list) option =
            let isList (node : Node) = match node with Group (opening, inner, _) -> opening.Token = TokParenthesis (Square, Open) && not opening.InsideMacro && not inner.IsEmpty | Leaf _ -> false
            let withArrow (lambda : Node list) = match lambda with first :: _ when isKeyword SpecFun first && (indexOfTop (isOperator "=>") lambda).IsSome -> Some lambda | _ -> None
            match List.rev nodes with
            | (Group _ as lambdaGroup) :: list :: before when not before.IsEmpty && isList list ->
                withArrow (unwrapLambda [ lambdaGroup ]) |> Option.map (fun lambda -> List.rev before, list, lambda)
            | _ ->
                match nodes |> List.tryFindIndex (fun node -> isKeyword SpecFun node) with
                | Some at when at >= 2 && isList nodes.[at - 1] ->
                    withArrow (List.skip at nodes) |> Option.map (fun lambda -> List.take (at - 1) nodes, nodes.[at - 1], lambda)
                | _ -> None

        and listThenLambda (nodes : Node list) = (splitListLambda nodes).IsSome

        and opensLayout (nodes : Node list) =
            match nodes with
            | _ when listThenLambda nodes -> true
            | _ when nodes |> List.exists functionRecord -> true
            | _ when nodes.Length > 1 && trailingLambdaNeedsBlock nodes -> true
            | _ when longPipeline nodes -> true
            | _ when carriesComment nodes -> true
            | _ when (match List.tryFindIndex (fun node -> isKeyword SpecFunction node) nodes with Some at -> (match List.tryItem (at + 1) nodes with Some next -> isOperator "|" next | None -> false) | None -> false) -> true
            | first :: rest when isKeyword SpecIf first && sourceLineTable.Value.Length > 0 ->
                let breaks = authoredBreaks.Value
                let rec anyBreak (nodes : Node list) =
                    match nodes with
                    | Leaf lexeme :: tail -> breaks.Contains lexeme.Span.From || anyBreak tail
                    | Group (opening, inner, closing) :: tail -> breaks.Contains opening.Span.From || anyBreak inner || breaks.Contains closing.Span.From || anyBreak tail
                    | [] -> false
                anyBreak rest
            | first :: _ when isKeyword SpecMatch first || isKeyword SpecIf first || isKeyword SpecTypecase first -> true
            | first :: _ when isKeyword SpecFun first ->
                match indexOfTop (isOperator "=>") nodes with
                | Some arrow ->
                    let body = unwrapBody (List.skip (arrow + 1) nodes)
                    (statements body).Length > 1 || isStatement body || opensLayout body
                | None -> false
            | _ -> false

        and layoutArms (indent : int) (arms : (string list * Node list) list) =
            let rec walk (pending : string list) (rest : (string list * Node list) list) =
                match rest with
                | [] -> pending |> List.rev |> List.map (fun pattern -> { Indent = indent; Text = "| " + pattern })
                | (comments, armNodes) :: tail ->
                    let commentLines = comments |> List.map (fun comment -> if comment = "" then { Indent = 0; Text = "" } else { Indent = indent; Text = comment })
                    let flushed = if comments.IsEmpty then [] else pending |> List.rev |> List.map (fun pattern -> { Indent = indent; Text = "| " + pattern })
                    let pending = if comments.IsEmpty then pending else []
                    if (indexOfTop (isOperator "=>") armNodes).IsNone && not (carriesComment armNodes) then
                        flushed @ commentLines @ walk (inlineText armNodes :: pending) tail
                    else
                        let laid = layoutArm indent armNodes
                        let merged =
                            match pending, laid with
                            | [], _ -> laid
                            | _, first :: others when first.Text.StartsWith "| " && fits indent ("| " + String.concat " | " (List.rev pending) + " " + first.Text) ->
                                { first with Text = "| " + String.concat " | " (List.rev pending) + " " + first.Text } :: others
                            | _, _ -> (pending |> List.rev |> List.map (fun pattern -> { Indent = indent; Text = "| " + pattern })) @ laid
                        flushed @ commentLines @ merged @ walk [] tail
            walk [] arms

        and layoutArm (indent : int) (armNodes : Node list) : LaidLine list =
                match indexOfTop (isOperator "=>") armNodes with
                | Some at ->
                    let pattern = List.take (at + 1) armNodes
                    let body = unwrapBody (List.skip (at + 1) armNodes)
                    let line = "| " + inlineComplete armNodes
                    let whenAt = indexOfTop (isKeyword SpecWhen) pattern
                    if (statements body).Length = 1 && fits indent line && not (opensLayout body) then [ { Indent = indent; Text = line } ]
                    elif whenAt.IsSome && not (fits indent ("| " + inlineText pattern)) then
                        let at = whenAt.Value
                        let guard = pattern.[at + 1 .. pattern.Length - 2]
                        let guardLines = breakLong (indent + 4) guard
                        let bodyText = "=> " + inlineComplete body
                        let tail =
                            if (statements body).Length = 1 && fits (indent + 4) bodyText && not (opensLayout body) then [ { Indent = indent + 4; Text = bodyText } ]
                            else { Indent = indent + 4; Text = "=>" } :: layoutBlock (indent + 8) body
                        { Indent = indent; Text = "| " + inlineText (List.take (at + 1) pattern) } :: guardLines @ tail
                    elif whenAt.IsNone && not (fits indent ("| " + inlineText pattern)) && List.take at pattern |> List.exists (isOperator ",") then
                        let components = splitOn (isOperator ",") (List.take at pattern) |> List.filter (fun part -> not part.IsEmpty)
                        let bodyText = "=> " + inlineComplete body
                        let tail =
                            if (statements body).Length = 1 && fits (indent + 4) bodyText && not (opensLayout body) then [ { Indent = indent + 4; Text = bodyText } ]
                            else { Indent = indent + 4; Text = "=>" } :: layoutBlock (indent + 8) body
                        let componentLines =
                            components
                            |> List.mapi (fun index part ->
                                let comma = if index < components.Length - 1 then "," else ""
                                let prefix = if index = 0 then "| " else ""
                                let partIndent = if index = 0 then indent else indent + 4
                                match List.rev part with
                                | Group (opening, inner, closing) :: before when not (fits partIndent (prefix + inlineText part + comma)) && opening.Token = TokParenthesis (Round, Open) && List.exists (isOperator ",") inner ->
                                    let items = splitOn (isOperator ",") inner |> List.filter (fun item -> not item.IsEmpty)
                                    { Indent = partIndent; Text = prefix + (if before.IsEmpty then "" else inlineText (List.rev before) + " ") + (markedText opening) }
                                    :: (items |> List.mapi (fun position item -> layoutPatternItem (indent + 8) (if position < items.Length - 1 then "," else "") item) |> List.concat)
                                    @ [ { Indent = indent + 4; Text = (markedText closing) + comma } ]
                                | _ when prefix = "" -> layoutPatternItem partIndent comma part
                                | _ -> [ { Indent = partIndent; Text = prefix + inlineText part + comma } ])
                            |> List.concat
                        componentLines @ tail
                    elif whenAt.IsNone && not (fits indent ("| " + inlineText pattern))
                         && (match List.rev (List.take at pattern) with
                             | Group (opening, inner, _) :: before -> not before.IsEmpty && opening.Token = TokParenthesis (Round, Open) && not opening.InsideMacro && List.exists (isOperator ",") inner && not (carriesComment inner)
                             | _ -> false) then
                        match List.rev (List.take at pattern) with
                        | Group (opening, inner, closing) :: before ->
                            let items = splitOn (isOperator ",") inner |> List.filter (fun item -> not item.IsEmpty)
                            let bodyText = "=> " + inlineComplete body
                            let tail =
                                if (statements body).Length = 1 && fits (indent + 4) bodyText && not (opensLayout body) then [ { Indent = indent + 4; Text = bodyText } ]
                                else { Indent = indent + 4; Text = "=>" } :: layoutBlock (indent + 8) body
                            { Indent = indent; Text = "| " + inlineText (List.rev before) + " " + (markedText opening) }
                            :: (items |> List.mapi (fun position item -> layoutPatternItem (indent + 8) (if position < items.Length - 1 then "," else "") item) |> List.concat)
                            @ [ { Indent = indent + 4; Text = (markedText closing) } ]
                            @ tail
                        | _ -> [ { Indent = indent; Text = line } ]
                    else
                        match body with
                        | first :: _ when isKeyword SpecFun first ->
                            match layoutExpression indent body with
                            | lambdaHead :: lambdaBody when fits indent ("| " + inlineText pattern + " " + lambdaHead.Text) && lambdaHead.Text.EndsWith "=>" ->
                                { Indent = indent; Text = "| " + inlineText pattern + " " + lambdaHead.Text } :: lambdaBody
                            | lambdaHead :: lambdaBody when lambdaHead.Text.EndsWith "=> {" && fits indent ("| " + inlineText pattern + " " + lambdaHead.Text.Substring(0, lambdaHead.Text.Length - 2)) ->
                                { Indent = indent; Text = "| " + inlineText pattern + " " + lambdaHead.Text.Substring(0, lambdaHead.Text.Length - 2) }
                                :: { Indent = indent + 4; Text = "{" }
                                :: (lambdaBody |> List.map (fun laid -> { laid with Indent = laid.Indent + 4 }))
                            | _ -> { Indent = indent; Text = "| " + inlineText pattern } :: layoutExpression (indent + 4) body
                        | _ -> { Indent = indent; Text = "| " + inlineText pattern } :: layoutBlock (indent + 4) body
                | None -> [ { Indent = indent; Text = "| " + inlineText armNodes } ]

        and layoutPatternItem (at : int) (suffix : string) (item : Node list) : LaidLine list =
            if fits at (inlineText item + suffix) then [ { Indent = at; Text = inlineText item + suffix } ]
            else
                match List.rev item with
                | Group (opening, inner, closing) :: before when opening.Token = TokParenthesis (Round, Open) && not opening.InsideMacro && List.exists (isOperator ",") inner && not (carriesComment inner) ->
                    let items = splitOn (isOperator ",") inner |> List.filter (fun part -> not part.IsEmpty)
                    { Indent = at; Text = (if before.IsEmpty then "" else inlineText (List.rev before) + " ") + (markedText opening) }
                    :: (items |> List.mapi (fun position part -> layoutPatternItem (at + 4) (if position < items.Length - 1 then "," else "") part) |> List.concat)
                    @ [ { Indent = at; Text = (markedText closing) + suffix } ]
                | Group (opening, inner, closing) :: before when opening.Token = TokParenthesis (Round, Open) && not opening.InsideMacro && not inner.IsEmpty && not (carriesComment inner) && fits at ((if before.IsEmpty then "" else inlineText (List.rev before) + " ") + (markedText opening)) ->
                    { Indent = at; Text = (if before.IsEmpty then "" else inlineText (List.rev before) + " ") + (markedText opening) }
                    :: layoutPatternItem (at + 4) "" inner
                    @ [ { Indent = at; Text = (markedText closing) + suffix } ]
                | _ -> [ { Indent = at; Text = inlineText item + suffix } ]

        and layoutExpression (indent : int) (nodes : Node list) : LaidLine list =
            let whole = inlineComplete nodes
            let hasTopKeyword = nodes |> List.exists (fun node -> match node with Leaf lexeme -> not lexeme.InsideMacro && (match lexeme.Token with TokKeyword _ -> true | TokOperator ("=>", _) -> true | _ -> false) | _ -> false)
            let annotationAt =
                if hasTopKeyword then None
                elif not (fits indent whole) then indexOfTop (isOperator ":") nodes
                else
                    match indexOfTop (isOperator ":") nodes with
                    | Some at when at > 0 && opensLayout (unwrapBody (List.take at nodes)) -> Some at
                    | _ -> None
            let arrowAt =
                if fits indent whole then None
                else
                    match nodes with
                    | first :: _ when isOperator "|" first || isKeyword SpecMatch first || isKeyword SpecFunction first || isKeyword SpecTypecase first || isKeyword SpecIf first -> None
                    | _ when nodes |> List.exists (fun node -> isPipe node || (match node with Leaf lexeme -> not lexeme.InsideMacro && (match lexeme.Token with TokKeyword keyword -> keyword <> SpecForall | _ -> false) | _ -> false)) -> None
                    | _ -> indexOfTop (isOperator "=>") nodes
            match nodes with
            | [ single ] when (literalChain indent single).IsSome -> (literalChain indent single).Value
            | _ when not (fits indent whole) && not (carriesComment nodes) && not (match lexemesOfNodes nodes with _ :: rest -> rest |> List.exists (fun lexeme -> authoredBreaks.Value.Contains lexeme.Span.From) | [] -> false) && (match chainSegments nodes with Some (_, _, depth) -> depth >= 3 | None -> false) && (fillChain indent nodes |> List.forall (fun laid -> fits laid.Indent laid.Text)) ->
                fillChain indent nodes
            | _ when annotationAt.IsSome && annotationAt.Value > 0 ->
                let at = annotationAt.Value
                let left = List.take at nodes
                let annotation = inlineText (List.skip at nodes)
                match layoutExpression indent left with
                | [ single ] when fits single.Indent (single.Text + " " + annotation) -> [ { single with Text = single.Text + " " + annotation } ]
                | laid -> laid @ [ { Indent = indent; Text = annotation } ]
            | _ when arrowAt.IsSome && fits indent (inlineText (List.take (arrowAt.Value + 1) nodes)) ->
                let at = arrowAt.Value
                { Indent = indent; Text = inlineText (List.take (at + 1) nodes) } :: layoutBlock (indent + 4) (unwrapBody (List.skip (at + 1) nodes))
            | [ (Leaf tick); (Group (opening, inner, closing)) ] when not tick.InsideMacro && (match tick.Token with TokUnaryOperator ("`", _) -> true | _ -> false) && opening.Token = TokParenthesis (Round, Open) && not (fits indent whole) && not inner.IsEmpty && not (carriesComment inner) ->
                { Indent = indent; Text = tick.Text.Text + (markedText opening) } :: layoutType (indent + 4) "" inner @ [ { Indent = indent; Text = (markedText closing) } ]
            | [ (Leaf unary); (Group (opening, inner, closing)) ] when (match unary.Token with TokUnaryOperator _ -> true | _ -> false) && opening.Token = TokParenthesis (Square, Open) && not (fits indent whole) && not inner.IsEmpty ->
                let items = splitOn (isOperator ";") inner |> List.filter (fun item -> not item.IsEmpty)
                { Indent = indent; Text = unary.Text.Text + (markedText opening) } :: (items |> List.collect (layoutExpression (indent + 4))) @ [ { Indent = indent; Text = (markedText closing) } ]
            | [ Group (opening, inner, closing) as record ] when opening.Token = TokParenthesis (Curly, Open) && functionRecord record ->
                let openText, fields = recordOpening opening inner
                { Indent = indent; Text = openText } :: layoutFields (indent + 4) fields @ [ { Indent = indent; Text = (markedText closing) } ]
            | [ Group (opening, _, _) as record ] when (opening.Token = TokParenthesis (Curly, Open) || opening.Token = TokParenthesis (Square, Open)) && not (fits indent whole) -> layoutArgument indent record
            | [ first; (Group (opening, inner, _)) ] when (isKeyword SpecReal first || isKeyword SpecJoin first) && opening.Token = TokParenthesis (Round, Open) && (not (fits indent whole) || (statements (unwrapBody inner)).Length > 1 || isStatement (unwrapBody inner) || opensLayout (unwrapBody inner)) ->
                { Indent = indent; Text = inlineText [ first ] } :: layoutBlock (indent + 4) (unwrapBody inner)
            | first :: (_ :: _ :: _ as rest) when isKeyword SpecJoin first && not (fits indent whole) && not (carriesComment nodes) ->
                { Indent = indent; Text = inlineText [ first ] } :: layoutBlock (indent + 4) rest
            | first :: (second :: _ as rest) when isKeyword SpecReal first && not (fits indent whole) && (match second with Group (opening, _, _) -> opening.Token <> TokParenthesis (Round, Open) | Leaf _ -> true) ->
                { Indent = indent; Text = inlineText [ first ] } :: layoutBlock (indent + 4) rest
            | [ Group (opening, _, _) ] when opening.Token = TokParenthesis (Round, Open) && (not (fits indent whole) || opensLayout (unwrapLambda nodes)) && (match unwrapLambda nodes with first :: _ -> isKeyword SpecFun first || isKeyword SpecFunction first | [] -> false) ->
                layoutExpression indent (unwrapLambda nodes)
            | [ Group (opening, _, _) ] when opening.Token = TokParenthesis (Round, Open) && (not (fits indent whole) || opensLayout (unwrapBody nodes)) && (match unwrapBody nodes with first :: _ -> isKeyword SpecIf first || isKeyword SpecMatch first || isKeyword SpecTypecase first || isKeyword SpecReal first || (List.tryFindIndex (fun node -> isKeyword SpecFunction node) (unwrapBody nodes)).IsSome | [] -> false) ->
                layoutExpression indent (unwrapBody nodes)
            | [ Group (opening, inner, _) as group ] when opening.Token = TokParenthesis (Round, Open) && not inner.IsEmpty && not (fits indent whole) && (match unwrapLambda nodes with first :: _ -> not (isKeyword SpecFun first) | [] -> true) ->
                layoutArgument indent group
            | first :: _ when isKeyword SpecMatch first || isKeyword SpecTypecase first ->
                match indexOfTop (isKeyword SpecWith) nodes with
                | Some at ->
                    let head = List.take (at + 1) nodes
                    let arms = splitArms (List.skip (at + 1) nodes)
                    let headLines =
                        if fits indent (inlineText head) || at < 2 then [ { Indent = indent; Text = inlineText head } ]
                        else
                            { Indent = indent; Text = inlineText [ List.head head ] }
                            :: layoutExpression (indent + 4) (head.[1 .. head.Length - 2])
                            @ [ { Indent = indent; Text = inlineText [ List.last head ] } ]
                    headLines @ layoutArms indent arms
                | None -> [ { Indent = indent; Text = whole } ]
            | first :: _ when isKeyword SpecIf first && (statements nodes).Length = 1 && fits indent whole && not (opensLayout nodes) -> [ { Indent = indent; Text = whole } ]
            | first :: _ when isKeyword SpecIf first ->
                let branches = ResizeArray<Node * Node list> ()
                let mutable keyword = first
                let current = ResizeArray<Node> ()
                let mutable depth = 0
                for node in List.tail nodes do
                    if isKeyword SpecIf node then depth <- depth + 1
                    if depth = 0 && (isKeyword SpecThen node || isKeyword SpecElif node || isKeyword SpecElse node) then
                        branches.Add (keyword, List.ofSeq current)
                        current.Clear ()
                        keyword <- node
                    else
                        if isKeyword SpecElse node && depth > 0 then depth <- depth - 1
                        current.Add node
                branches.Add (keyword, List.ofSeq current)
                let thenStaysOnCondition (keywordNode : Node) =
                    match keywordNode with
                    | Leaf _ when isKeyword SpecThen keywordNode -> true
                    | _ -> false
                let thenWord (text : string) = if text = "?>" || text.StartsWith "?> " then "?>" else "then"
                let isThenWord (text : string) = text = "then" || text = "?>"
                let startsWithThen (text : string) = text.StartsWith "then " || text.StartsWith "?> "
                let thenAuthoredOnOwnLine (thenNode : Node) =
                    match thenNode with
                    | Leaf lexeme -> authoredBreaks.Value.Contains lexeme.Span.From
                    | Group _ -> false
                let rec mergeThen (pending : (Node * bool * LaidLine list) list) =
                    match pending with
                    | (conditionNode, _, condition) :: (thenNode, bodyOnOwnLine, thenLine :: body) :: rest
                        when (isKeyword SpecIf conditionNode || isKeyword SpecElif conditionNode)
                             && thenStaysOnCondition thenNode
                             && not condition.IsEmpty
                             && (List.last condition).Indent = thenLine.Indent
                             && (isThenWord thenLine.Text || (startsWithThen thenLine.Text && not bodyOnOwnLine && not (thenAuthoredOnOwnLine thenNode)))
                             && fits thenLine.Indent ((List.last condition).Text + " " + thenLine.Text) ->
                        let last = List.last condition
                        List.take (condition.Length - 1) condition @ [ { last with Text = last.Text + " " + thenLine.Text } ] @ body @ mergeThen rest
                    | (conditionNode, _, condition) :: (thenNode, true, thenLine :: body) :: rest
                        when (isKeyword SpecIf conditionNode || isKeyword SpecElif conditionNode)
                             && thenStaysOnCondition thenNode
                             && not condition.IsEmpty
                             && (List.last condition).Indent = thenLine.Indent
                             && startsWithThen thenLine.Text
                             && fits thenLine.Indent ((List.last condition).Text + " " + thenWord thenLine.Text) ->
                        let last = List.last condition
                        let word = thenWord thenLine.Text
                        List.take (condition.Length - 1) condition
                        @ [ { last with Text = last.Text + " " + word } ]
                        @ [ { Indent = thenLine.Indent + 4; Text = thenLine.Text.Substring (word.Length + 1) } ]
                        @ body
                        @ mergeThen rest
                    | (_, _, lines) :: rest -> lines @ mergeThen rest
                    | [] -> []
                branches
                |> List.ofSeq
                |> List.map (fun (keywordNode, branch) ->
                    let keywordComments =
                        match keywordNode with
                        | Leaf lexeme ->
                            match lexeme.Before with
                            | Embedded gap -> commentsIn gap.Text |> List.filter (fun comment -> comment <> "") |> List.map (fun comment -> { Indent = indent; Text = comment })
                            | Whitespace _ -> []
                        | Group _ -> []
                    let word = inlineText [ keywordNode ]
                    let body = if isKeyword SpecIf keywordNode || isKeyword SpecElif keywordNode then branch else unwrapBody branch
                    let line = word + " " + inlineComplete (if isKeyword SpecIf keywordNode || isKeyword SpecElif keywordNode then branch else body)
                    let elseIfChain () =
                        match body with
                        | first :: _ when isKeyword SpecElse keywordNode && isKeyword SpecIf first && (statements body).Length = 1 ->
                            let asElif (lines : LaidLine list) (shift : int) =
                                match lines |> List.map (fun line -> if line.Text = "" then line else { line with Indent = line.Indent - shift }) with
                                | head :: rest when head.Indent = indent && (head.Text = "if" || head.Text.StartsWith "if ") && fits indent ("el" + head.Text) -> Some ({ head with Text = "el" + head.Text } :: rest)
                                | _ -> None
                            match layoutExpression indent body with
                            | head :: _ when head.Indent = indent && (head.Text = "if" || head.Text.StartsWith "if ") && not (fits indent ("el" + head.Text)) ->
                                asElif (layoutExpression (indent + 2) body) 2
                            | laid -> asElif laid 0
                        | _ -> None
                    let elseIfBody = isKeyword SpecElse keywordNode && (match body with first :: _ -> isKeyword SpecIf first | [] -> false)
                    let laid =
                        if (statements body).Length = 1 && fits indent line && not (opensLayout body) && not elseIfBody then [ { Indent = indent; Text = line } ]
                        else
                            match elseIfChain () with
                            | Some chain -> chain
                            | None -> { Indent = indent; Text = word } :: layoutBlock (indent + 4) body
                    let bodyOnOwnLine = match body with Leaf lexeme :: _ -> authoredBreaks.Value.Contains lexeme.Span.From | Group (opening, _, _) :: _ -> authoredBreaks.Value.Contains opening.Span.From | [] -> false
                    keywordNode, bodyOnOwnLine, keywordComments @ laid)
                |> mergeThen
            | _ ->
                match List.tryFindIndexBack (isKeyword SpecFunction) nodes with
                | Some at when at = nodes.Length - 1 || (match List.tryItem (at + 1) nodes with Some next -> isOperator "|" next | None -> false) ->
                    let head = List.take (at + 1) nodes
                    let arms = splitArms (List.skip (at + 1) nodes)
                    if arms.IsEmpty then [ { Indent = indent; Text = whole } ]
                    else
                        let headLines = if fits indent (inlineText head) then [ { Indent = indent; Text = inlineText head } ] else breakLong indent head
                        headLines @ layoutArms (indent + 4) arms
                | _ when fits indent whole && trailingLambdaNeedsBlock nodes -> (if List.exists isPipe nodes then breakLong indent nodes else match lastArgumentLambda indent "" nodes with Some lines -> lines | None -> breakLong indent nodes)
                | _ ->
                    let pipeBeforeLambda =
                        match nodes |> List.tryFindIndex (fun node -> isKeyword SpecFun node) with
                        | Some at -> nodes |> List.take at |> List.exists (fun node -> isPipe node || (match node with Leaf l -> not l.InsideMacro && (match l.Token with TokOperator (name, _) -> not (List.contains name [ ","; ":"; "="; "=>"; "|"; "."; ";"; "<-" ]) | _ -> false) | _ -> false))
                        | None -> false
                    match nodes |> List.tryFindIndexBack (fun node -> isKeyword SpecFun node) with
                    | _ when pipeBeforeLambda && (not (fits indent whole) || opensLayout (List.skip (List.findIndex (fun node -> isKeyword SpecFun node) nodes) nodes)) -> breakLong indent nodes
                    | Some at when (indexOfTop (isOperator "=>") (List.skip at nodes)).IsSome && (let arrow = (indexOfTop (isOperator "=>") (List.skip at nodes)).Value in let body = unwrapBody (List.skip (at + arrow + 1) nodes) in (statements body).Length > 1 || opensLayout body || not (fits indent whole)) ->
                        let arrow = (indexOfTop (isOperator "=>") (List.skip at nodes)).Value
                        let head = List.take (at + arrow + 1) nodes
                        let body = unwrapBody (List.skip (at + arrow + 1) nodes)
                        if listThenLambda nodes then breakLong indent nodes else
                        match body with
                        | [ Group (opening, inner, closing) as record ] when opening.Token = TokParenthesis (Curly, Open) && not opening.InsideMacro && (fieldRecord record).IsSome && fits indent (inlineText head + " " + fst (recordOpening opening inner)) ->
                            let openText, fields = recordOpening opening inner
                            { Indent = indent; Text = inlineText head + " " + openText } :: layoutFields (indent + 4) fields @ [ { Indent = indent; Text = (markedText closing) } ]
                        | _ ->
                        if fits indent (inlineText head) || at = 0 then { Indent = indent; Text = inlineText head } :: layoutBlock (indent + 4) body
                        else breakLong indent nodes
                    | _ -> if fits indent whole && not (longPipeline nodes) && not (carriesComment nodes) && not (nodes |> List.exists functionRecord) && not (listThenLambda nodes) then [ { Indent = indent; Text = whole } ] else breakLong indent nodes

        and isPipe (node : Node) = isOperator "|>" node || isOperator "||>" node || isOperator "|||>" node

        and breakLong (indent : int) (nodes : Node list) : LaidLine list =
            let whole = inlineText nodes
            let firstKeyword = nodes |> List.tryFindIndex (fun node -> match node with Leaf lexeme -> not lexeme.InsideMacro && (match lexeme.Token with TokKeyword _ -> true | _ -> false) | Group _ -> false)
            let limit = defaultArg firstKeyword nodes.Length
            let pipes = nodes |> List.indexed |> List.filter (fun (index, node) -> index < limit && isPipe node) |> List.map fst
            let precedenceOf (node : Node) =
                match node with
                | Leaf lexeme when not lexeme.InsideMacro ->
                    match lexeme.Token with
                    | TokOperator (name, _) ->
                        match name with
                        | "," | ":" | "=>" | "|" | "." | ";" | "<-" -> None
                        | "||" -> Some 20
                        | "&&" -> Some 30
                        | "=" | "=." | "<>." | "<" | "<=" | ">" | ">=" | "<>" -> Some 40
                        | "::" -> Some 50
                        | _ when name.StartsWith "+" || name.StartsWith "-" -> Some 60
                        | _ when name.StartsWith "*" || name.StartsWith "/" || name.StartsWith "%" -> Some 70
                        | _ -> Some 45
                    | _ -> None
                | _ -> None
            let operators = nodes |> List.indexed |> List.filter (fun (index, node) -> index > 0 && index < limit && (precedenceOf node).IsSome)
            let commaItems =
                if not (hasTopComma nodes) then []
                elif firstKeyword.IsNone then splitOn (isOperator ",") nodes |> List.filter (fun item -> not item.IsEmpty)
                else
                    let lastCommaBeforeKeyword = nodes |> List.take firstKeyword.Value |> List.findIndexBack (isOperator ",")
                    (splitOn (isOperator ",") (List.take lastCommaBeforeKeyword nodes) |> List.filter (fun item -> not item.IsEmpty))
                    @ [ List.skip (lastCommaBeforeKeyword + 1) nodes ]
            if commaItems.Length > 1 then
                commaItems
                |> List.mapi (fun index item ->
                    let parenthesizedIf =
                        match item with
                        | [ Group (opening, _, _) ] -> opening.Token = TokParenthesis (Round, Open) && not opening.InsideMacro && (match unwrapBody item with first :: _ -> isKeyword SpecIf first | [] -> false)
                        | _ -> false
                    let lines =
                        if parenthesizedIf && fits indent (inlineText item + ",") && not (carriesComment item) then [ { Indent = indent; Text = inlineText item } ]
                        else
                            match layoutExpression indent item with
                            | [ single ] when index < commaItems.Length - 1 && not (fits single.Indent (single.Text + ",")) ->
                                layoutExpression (indent + 1) item |> List.map (fun line -> { line with Indent = max 0 (line.Indent - 1) })
                            | laid -> laid
                    let lines = if index < commaItems.Length - 1 then keepLambdaParentheses item lines else lines
                    if index = commaItems.Length - 1 then lines
                    else
                        match List.rev lines with
                        | last :: before -> List.rev ({ last with Text = last.Text + "," } :: before)
                        | [] -> [])
                |> List.concat
            elif pipes.IsEmpty && not operators.IsEmpty then
                let lowest = operators |> List.map (fun (_, node) -> (precedenceOf node).Value) |> List.min
                let cuts = operators |> List.filter (fun (_, node) -> (precedenceOf node).Value = lowest) |> List.map fst
                let bounds = (0 :: cuts) @ [ nodes.Length ]
                let pureApplication (inner : Node list) =
                    not inner.IsEmpty
                    && inner |> List.forall (fun node ->
                        match node with
                        | Leaf lexeme -> not lexeme.InsideMacro && (match lexeme.Token with TokVar _ | TokSymbol _ | TokValue _ | TokValueSuffix | TokDefaultValue _ -> true | _ -> false)
                        | Group (opening, _, _) -> opening.Token = TokParenthesis (Round, Open) && not opening.InsideMacro)
                let unwrapApplication (operand : Node list) =
                    match operand with
                    | [ Group (opening, inner, _) ] when opening.Token = TokParenthesis (Round, Open) && not opening.InsideMacro && pureApplication inner && not (carriesComment operand) -> inner
                    | [ op; Group (opening, inner, _) ] when (precedenceOf op).IsSome && opening.Token = TokParenthesis (Round, Open) && not opening.InsideMacro && pureApplication inner && not (carriesComment operand) ->
                        op :: (match inner with Leaf first :: tail -> Leaf { first with Before = Whitespace 1 } :: tail | other -> other)
                    | _ -> operand
                List.pairwise bounds
                |> List.mapi (fun index (a, b) ->
                    let withGap = unwrapApplication nodes.[a .. b - 1]
                    if index = 0 then
                        match withGap with
                        | [ single ] when lowest >= 45 && (literalChain (indent + 4) single).IsSome ->
                            { Indent = indent; Text = "(" } :: (literalChain (indent + 4) single).Value @ [ { Indent = indent; Text = ")" } ]
                        | [ Group (opening, _, closing) ] when opening.Token = TokParenthesis (Round, Open) && not opening.InsideMacro && not (carriesComment withGap) && not (fits indent (inlineText withGap)) && (match unwrapBody withGap with first :: _ -> isKeyword SpecIf first || isKeyword SpecMatch first || isKeyword SpecTypecase first | [] -> false) ->
                            match layoutExpression (indent + 4) (unwrapBody withGap) with
                            | first :: rest ->
                                match List.rev ({ Indent = indent; Text = (markedText opening) + first.Text } :: rest) with
                                | last :: before -> List.rev ({ last with Text = last.Text + (markedText closing) } :: before)
                                | [] -> layoutExpression indent withGap
                            | [] -> layoutExpression indent withGap
                        | _ -> layoutExpression indent withGap
                    else
                        let segment, comments = withoutLeadingGap withGap
                        let commentLines = comments |> List.map (fun comment -> if comment = "" then { Indent = 0; Text = "" } else { Indent = indent; Text = comment })
                        let op = inlineText [ List.head segment ]
                        let operand = List.tail segment
                        let text = op + " " + inlineComplete operand
                        let lambdaOperand =
                            match operand with
                            | first :: _ when isKeyword SpecFun first -> Some operand
                            | [ Group _ ] when index = bounds.Length - 2 && (match unwrapLambda operand with first :: _ -> isKeyword SpecFun first | [] -> false) -> Some (unwrapLambda operand)
                            | _ -> None
                        let laidOperand =
                            if fits indent text && not (carriesComment operand) then [ { Indent = indent; Text = text } ]
                            elif lambdaOperand.IsSome && not (carriesComment operand) then
                                match layoutExpression indent lambdaOperand.Value with
                                | first :: rest -> { Indent = indent; Text = op + " " + first.Text } :: rest
                                | [] -> [ { Indent = indent; Text = text } ]
                            elif (match operand with [ single ] -> (literalChain (indent + 4) single).IsSome | _ -> false) then
                                { Indent = indent; Text = op + " (" } :: (literalChain (indent + 4) (List.head operand)).Value @ [ { Indent = indent; Text = ")" } ]
                            elif (match operand with [ Group (opening, inner, _) ] -> opening.Token = TokParenthesis (Round, Open) && not inner.IsEmpty && not (hasTopComma inner) && not (fits indent text) | _ -> false) then
                                match operand with
                                | [ Group (_, inner, _) ] -> { Indent = indent; Text = op + " (" } :: layoutBlock (indent + 4) (unwrapBody inner) @ [ { Indent = indent; Text = ")" } ]
                                | _ -> [ { Indent = indent; Text = text } ]
                            else
                                match layoutExpression (indent + op.Length + 1) operand with
                                | first :: rest ->
                                    let aligned = indent + op.Length + 1
                                    let closesOperand (line : LaidLine) = line.Indent = aligned && (let text = (stripMarks line.Text).TrimStart () in text.StartsWith ")" || text.StartsWith "]" || text.StartsWith "}")
                                    let shift = if rest |> List.forall (fun line -> line.Text = "" || line.Indent >= aligned + 4 || closesOperand line) then op.Length + 1 else 0
                                    { Indent = indent; Text = op + " " + first.Text } :: (rest |> List.map (fun line -> if line.Text = "" then line else { line with Indent = line.Indent - shift }))
                                | [] -> [ { Indent = indent; Text = op } ]
                        commentLines @ laidOperand)
                |> List.concat
            elif not pipes.IsEmpty then
                let bounds = (0 :: pipes) @ [ nodes.Length ]
                let segments = List.pairwise bounds |> List.map (fun (a, b) -> nodes.[a .. b - 1])
                segments
                |> List.mapi (fun index withGap ->
                    if index = 0 then
                        let endsWithLambda =
                            match List.tryLast withGap with
                            | Some (Group _ as last) -> (match unwrapLambda [ last ] with first :: _ -> isKeyword SpecFun first | [] -> false)
                            | _ -> false
                        if not endsWithLambda then layoutExpression indent withGap
                        elif fits indent (inlineText withGap) && not (carriesComment withGap) && not (listThenLambda withGap) && not (opensLayout (unwrapLambda [ List.last withGap ])) then [ { Indent = indent; Text = inlineText withGap } ]
                        elif withGap.Length = 1 then layoutExpression indent withGap
                        else breakLong indent withGap
                    else
                        let segment, comments = withoutLeadingGap withGap
                        let commentLines = comments |> List.map (fun comment -> if comment = "" then { Indent = 0; Text = "" } else { Indent = indent; Text = comment })
                        let op = inlineText [ List.head segment ]
                        let stage = List.tail segment
                        let stageText = op + " " + (if index < segments.Length - 1 then inlineText stage else inlineComplete stage)
                        let laidStage =
                            if fits indent stageText && not (opensLayout stage) && not (trailingLambdaNeedsBlock stage) && not (stage |> List.exists (fun node -> isKeyword SpecFun node) && opensLayout (List.skip (List.findIndex (fun node -> isKeyword SpecFun node) stage) stage)) then [ { Indent = indent; Text = stageText } ]
                            else
                                let isLambdaArgument (node : Node) =
                                    match node with
                                    | Group (opening, _, _) when opening.Token = TokParenthesis (Round, Open) && not opening.InsideMacro -> (match unwrapLambda [ node ] with first :: _ -> isKeyword SpecFun first | [] -> false)
                                    | _ -> false
                                let middleLambda () =
                                    match stage |> List.indexed |> List.filter (fun (_, node) -> isLambdaArgument node) with
                                    | [ (at, group) ] when at > 0 && at < stage.Length - 1 && not (carriesComment stage) ->
                                        let lambda = unwrapLambda [ group ]
                                        match indexOfTop (isOperator "=>") lambda with
                                        | Some arrow ->
                                            let headText = op + " " + inlineText (List.take at stage) + " " + inlineText (List.take (arrow + 1) lambda)
                                            let body = unwrapBody (List.skip (arrow + 1) lambda)
                                            if fits indent headText && not body.IsEmpty then
                                                Some ({ Indent = indent; Text = headText } :: layoutBlock (indent + 8) body @ (List.skip (at + 1) stage |> List.collect (layoutArgument (indent + 4))))
                                            else None
                                        | None -> None
                                    | _ -> None
                                match lastArgumentLambda indent op stage |> Option.orElseWith middleLambda with
                                | Some lines -> lines
                                | None ->
                                    let wrappedLambda = index = segments.Length - 1 && (match stage with [ Group _ ] -> (match unwrapLambda stage with first :: _ -> isKeyword SpecFun first | [] -> false) | _ -> false)
                                    let bareLambda = wrappedLambda || stage |> List.exists (fun node -> isKeyword SpecFun node)
                                    match layoutExpression (if bareLambda then indent else indent + op.Length + 1) (if wrappedLambda && index = segments.Length - 1 then unwrapLambda stage else stage) with
                                    | first :: rest ->
                                        let aligned = indent + op.Length + 1
                                        let shift = if bareLambda || rest.IsEmpty then 0 elif rest |> List.forall (fun line -> line.Text = "" || line.Indent >= aligned + 4) then op.Length + 1 else 0
                                        { Indent = indent; Text = op + " " + first.Text } :: (rest |> List.map (fun line -> if line.Text = "" then line else { line with Indent = line.Indent - shift }))
                                    | [] -> [ { Indent = indent; Text = op } ]
                        commentLines @ laidStage)
                |> List.concat
            else
                let isSimple (node : Node) =
                    match node with
                    | Leaf lexeme ->
                        not lexeme.InsideMacro
                        && (match lexeme.Token with
                            | TokVar _ | TokSymbol _ | TokValue _ | TokDefaultValue _ | TokValueSuffix | TokUnaryOperator _ | TokKeyword SpecExists -> true
                            | _ -> false)
                    | Group (opening, [ Leaf section ], _) ->
                        opening.Token = TokParenthesis (Round, Open) && (match section.Token with TokOperator _ | TokUnaryOperator _ -> true | _ -> false)
                    | Group _ -> false
                let isUnary (node : Node) = match node with Leaf lexeme -> not lexeme.InsideMacro && (match lexeme.Token with TokUnaryOperator _ -> true | _ -> false) | _ -> false
                let rec countHead (index : int) =
                    if index >= nodes.Length then index
                    elif isUnary nodes.[index] && index + 2 < nodes.Length && (match nodes.[index + 2] with Group (opening, [ Group (innerOpening, _, _) ], _) when innerOpening.Token = TokParenthesis (Curly, Open) -> false | Group (opening, _, _) -> opening.Token = TokParenthesis (Round, Open) && (match nodes.[index] with Leaf l -> l.Text.Text.StartsWith "!!!!" | _ -> false) | _ -> false) then countHead (index + 3)
                    elif isUnary nodes.[index] then countHead (index + 2)
                    elif isSimple nodes.[index] then countHead (index + 1)
                    else index
                let adjacent (node : Node) = match (firstLexeme node).Before with Whitespace 0 -> true | _ -> false
                let rec extendHead (count : int) = if count < nodes.Length && count > 0 && adjacent nodes.[count] && (match nodes.[count] with Group _ -> false | _ -> true) then extendHead (count + 1) else count
                let plainCallee = match nodes with Leaf callee :: _ -> not callee.InsideMacro && (match callee.Token with TokVar _ | TokSymbol _ -> true | _ -> false) | _ -> false
                let headCount =
                    let counted = extendHead (min nodes.Length (countHead 0))
                    if counted > 1 && plainCallee && extendHead 1 = 1 && not (fits indent (inlineText (List.take counted nodes))) then 1 else counted
                let rest = List.skip headCount nodes
                let rec bindUnary (items : Node list) : Node list list =
                    match items with
                    | unary :: operand :: tail when isUnary unary -> [ unary; operand ] :: bindUnary tail
                    | node :: tail -> [ node ] :: bindUnary tail
                    | [] -> []
                let arguments =
                    bindUnary rest
                    |> List.fold (fun (groups : Node list list) group ->
                        match groups, group with
                        | previous :: earlier, first :: _ when adjacent first -> (previous @ group) :: earlier
                        | _ -> group :: groups) []
                    |> List.rev
                let restIsArguments =
                    headCount > 0 && not rest.IsEmpty && not (List.take headCount nodes |> List.forall isUnary)
                    && rest |> List.forall (fun node -> match node with Group _ -> true | Leaf lexeme -> not lexeme.InsideMacro && (match lexeme.Token with TokVar _ | TokSymbol _ | TokValue _ | TokValueSuffix | TokDefaultValue _ | TokUnaryOperator _ -> true | _ -> false))
                let isCurly (node : Node) = match node with Group (opening, _, _) -> opening.Token = TokParenthesis (Curly, Open) | Leaf _ -> false
                let intrinsicHead = nodes.Length - 1
                let intrinsicTuple =
                    match nodes with
                    | Leaf bang :: _ when not bang.InsideMacro && (match bang.Token with TokUnaryOperator _ -> true | _ -> false) && (intrinsicHead = 1 || intrinsicHead = 2) ->
                        match List.last nodes with
                        | Group (opening, inner, _) -> opening.Token = TokParenthesis (Round, Open) && hasTopComma inner && not (fits indent whole) && (List.take intrinsicHead nodes |> List.forall (fun node -> match node with Leaf _ -> true | Group _ -> false))
                        | Leaf _ -> false
                    | _ -> false
                let bracketThenLambda =
                    match splitListLambda nodes with
                    | Some (before, Group (opening, inner, closing), lambda) ->
                            let arrow = (indexOfTop (isOperator "=>") lambda).Value
                            let headText = inlineText before
                            let lambdaHead = inlineText (List.take (arrow + 1) lambda)
                            let simpleHead = before |> List.forall (fun node -> match node with Leaf l -> not l.InsideMacro && (match l.Token with TokVar _ | TokSymbol _ | TokValue _ | TokUnaryOperator _ -> true | _ -> false) | Group _ -> true)
                            if simpleHead && fits indent (headText + " " + (markedText opening)) then
                                let items = splitOn (isOperator ";") inner |> List.filter (fun item -> not item.IsEmpty)
                                Some (
                                    { Indent = indent; Text = headText + " " + (markedText opening) }
                                    :: (items |> List.collect (layoutExpression (indent + 4)))
                                    @ [ { Indent = indent; Text = (markedText closing) + " " + lambdaHead } ]
                                    @ layoutBlock (indent + 4) (unwrapBody (List.skip (arrow + 1) lambda)))
                            else None
                    | _ -> None
                let rec soleLiteral (inner : Node list) =
                    match inner with
                    | [ literal ] when isStringGroup literal -> Some literal
                    | [ Group (opening, nested, _) ] when opening.Token = TokParenthesis (Round, Open) -> soleLiteral nested
                    | _ -> None
                let intrinsicLiteral =
                    match nodes with
                    | [ Leaf bang; Leaf name; Group (opening, inner, closing) ]
                        when not bang.InsideMacro && bang.Text.Text.StartsWith "!!!!" && opening.Token = TokParenthesis (Round, Open) && (soleLiteral inner).IsSome && not (fits indent whole) ->
                        let literal = (soleLiteral inner).Value
                        literalChain (indent + 4) literal
                        |> Option.map (fun pieces ->
                            let gap = match opening.Before with Whitespace 0 -> "" | _ -> " "
                            { Indent = indent; Text = inlineText [ Leaf bang; Leaf name ] + gap + (markedText opening) }
                            :: pieces
                            @ [ { Indent = indent; Text = (markedText closing) } ])
                    | _ -> None
                match (if intrinsicTuple then None elif intrinsicLiteral.IsSome then intrinsicLiteral elif bracketThenLambda.IsSome then bracketThenLambda else lastArgumentLambda indent "" nodes) with
                | Some lines -> lines
                | None when (match List.rev nodes with
                             | Group (opening, inner, _) :: Leaf unary :: before ->
                                 not before.IsEmpty && not unary.InsideMacro && (match unary.Token with TokUnaryOperator _ -> true | _ -> false)
                                 && opening.Token = TokParenthesis (Square, Open) && not inner.IsEmpty && not (fits indent whole)
                                 && (match opening.Before with Whitespace 0 -> true | _ -> false)
                                 && fits indent (inlineText (List.rev before) + " " + unary.Text.Text + (markedText opening))
                             | _ -> false) ->
                    match List.rev nodes with
                    | Group (opening, inner, closing) :: Leaf unary :: before ->
                        let items = splitOn (isOperator ";") inner |> List.filter (fun item -> not item.IsEmpty)
                        { Indent = indent; Text = inlineText (List.rev before) + " " + unary.Text.Text + (markedText opening) }
                        :: (items |> List.collect (layoutExpression (indent + 4)))
                        @ [ { Indent = indent; Text = (markedText closing) } ]
                    | _ -> [ { Indent = indent; Text = whole } ]
                | None when (match List.rev nodes with
                             | (Group (opening, _, _) as record) :: before ->
                                 not before.IsEmpty && opening.Token = TokParenthesis (Curly, Open) && not opening.InsideMacro
                                 && (functionRecord record || not (fits indent whole))
                                 && fits indent (inlineText (List.rev before) + " " + (markedText opening))
                                 && not (List.rev before |> List.exists (fun node -> isPipe node || (match node with Leaf l -> not l.InsideMacro && (match l.Token with TokKeyword _ | TokOperator _ -> true | _ -> false) | Group _ -> false)))
                             | _ -> false) ->
                    match List.rev nodes with
                    | Group (opening, inner, closing) :: before ->
                        let openText, fields = recordOpening opening inner
                        { Indent = indent; Text = inlineText (List.rev before) + " " + openText }
                        :: layoutFields (indent + 4) fields
                        @ [ { Indent = indent; Text = (markedText closing) } ]
                    | _ -> [ { Indent = indent; Text = whole } ]
                | None when (match List.rev nodes with
                             | Group (opening, inner, _) :: before ->
                                 not before.IsEmpty && opening.Token = TokParenthesis (Square, Open) && not opening.InsideMacro && not inner.IsEmpty
                                 && not (fits indent whole)
                                 && (match opening.Before with Whitespace 0 -> false | _ -> true)
                                 && fits indent (inlineText (List.rev before) + " " + (markedText opening))
                                 && List.rev before |> List.forall (fun node -> match node with Leaf l -> not l.InsideMacro && (match l.Token with TokVar _ | TokSymbol _ | TokValue _ -> true | _ -> false) | Group _ -> true)
                             | _ -> false) ->
                    match List.rev nodes with
                    | Group (opening, inner, closing) :: before ->
                        let items = splitOn (isOperator ";") inner |> List.filter (fun item -> not item.IsEmpty)
                        { Indent = indent; Text = inlineText (List.rev before) + " " + (markedText opening) }
                        :: (items |> List.collect (layoutExpression (indent + 4)))
                        @ [ { Indent = indent; Text = (markedText closing) } ]
                    | _ -> [ { Indent = indent; Text = whole } ]
                | None when intrinsicTuple ->
                    match layoutTuple indent (List.last nodes) with
                    | opening :: inner -> { Indent = indent; Text = inlineText (List.take intrinsicHead nodes) + (match (firstLexeme (List.last nodes)).Before with Whitespace 0 -> "" | _ -> " ") + opening.Text } :: inner
                    | [] -> [ { Indent = indent; Text = whole } ]
                | None ->
                let intrinsicRecord =
                    match rest with
                    | [ Group (opening, [ Group (innerOpening, _, _) ], _) ] -> opening.Token = TokParenthesis (Round, Open) && innerOpening.Token = TokParenthesis (Curly, Open)
                    | _ -> false
                let tupleArgument =
                    match rest with
                    | [ Group (opening, inner, _) ] -> opening.Token = TokParenthesis (Round, Open) && hasTopComma inner && not (fits indent whole) && fits indent (inlineText (List.take headCount nodes) + " " + (markedText opening))
                    | _ -> false
                if restIsArguments && tupleArgument then
                    match layoutTuple indent (List.head rest) with
                    | opening :: inner -> { Indent = indent; Text = inlineText (List.take headCount nodes) + " " + opening.Text } :: inner
                    | [] -> [ { Indent = indent; Text = whole } ]
                elif restIsArguments && rest.Length = 1 && not intrinsicRecord && not (fits indent whole) && fits indent (inlineText (List.take headCount nodes) + " (")
                     && (match List.head rest with Group (opening, inner, _) -> opening.Token = TokParenthesis (Round, Open) && not opening.InsideMacro && not inner.IsEmpty && not (carriesComment [ List.head rest ]) | Leaf _ -> false)
                     && (match unwrapLambda [ List.head rest ] with first :: _ -> not (isKeyword SpecFun first || isKeyword SpecFunction first) | [] -> false) then
                    let opened =
                        match List.head rest with
                        | Group (_, inner, closing) when not (hasTopComma inner) -> layoutBlock (indent + 4) (unwrapBody inner) @ [ { Indent = indent; Text = (markedText closing) } ]
                        | group -> List.tail (layoutTuple indent group)
                    { Indent = indent; Text = inlineText (List.take headCount nodes) + " (" } :: opened
                elif restIsArguments && intrinsicRecord then
                    match List.head rest with
                    | Group (opening, [ Group (innerOpening, fields, innerClosing) ], closing) ->
                        { Indent = indent; Text = inlineText (List.take headCount nodes) + " " + (markedText opening) + (markedText innerOpening) }
                        :: layoutFields (indent + 4) fields
                        @ [ { Indent = indent; Text = (markedText innerClosing) + (markedText closing) } ]
                    | _ -> [ { Indent = indent; Text = whole } ]
                elif restIsArguments && rest.Length = 1 && isCurly (List.head rest) then
                    match List.head rest with
                    | Group (opening, inner, closing) ->
                        let openText, fields = recordOpening opening inner
                        { Indent = indent; Text = inlineText (List.take headCount nodes) + " " + openText }
                        :: layoutFields (indent + 4) fields
                        @ [ { Indent = indent; Text = (markedText closing) } ]
                    | Leaf _ -> [ { Indent = indent; Text = whole } ]
                elif restIsArguments && rest.Length = 1 && (literalChain (indent + 4) (match List.head rest with Group (opening, [ single ], _) when opening.Token = TokParenthesis (Round, Open) && isStringGroup single -> single | other -> other)).IsSome then
                    let literal = match List.head rest with Group (opening, [ single ], _) when opening.Token = TokParenthesis (Round, Open) && isStringGroup single -> single | other -> other
                    { Indent = indent; Text = inlineText (List.take headCount nodes) + " (" } :: (literalChain (indent + 4) literal).Value @ [ { Indent = indent; Text = ")" } ]
                elif restIsArguments && rest.Length = 1 && (match List.head rest with Group (opening, _, _) -> (match opening.Token with TokStringOpen | TokMacroOpen -> true | _ -> false) | _ -> false) && not (fits (indent + 4) (inlineText rest)) then
                    [ { Indent = indent; Text = whole } ]
                elif restIsArguments then
                    { Indent = indent; Text = inlineText (List.take headCount nodes) }
                    :: (arguments |> List.collect (fun withGap -> let argument, comments = withoutLeadingGap withGap in (comments |> List.map (fun comment -> if comment = "" then { Indent = 0; Text = "" } else { Indent = indent + 4; Text = comment })) @ match argument with [ single ] when not (fits (indent + 4) (inlineText [ single ])) && (literalChain (indent + 8) single).IsSome -> { Indent = indent + 4; Text = "(" } :: (literalChain (indent + 8) single).Value @ [ { Indent = indent + 4; Text = ")" } ] | [ single ] -> layoutArgument (indent + 4) single | [ unary; (Group (opening, _, _) as array) ] when opening.Token = TokParenthesis (Square, Open) && not (fits (indent + 4) (inlineComplete argument)) -> (match layoutArgument (indent + 4) array with first :: rest -> { first with Text = inlineText [ unary ] + first.Text } :: rest | [] -> []) | bound -> [ { Indent = indent + 4; Text = inlineComplete bound } ]))
                elif headCount = nodes.Length && not (fits indent whole) && nodes |> List.forall (fun node -> match node with Leaf l -> not l.InsideMacro && (match l.Token with TokVar _ | TokSymbol _ | TokValue _ | TokValueSuffix | TokDefaultValue _ | TokUnaryOperator _ | TokOperator (".", _) -> true | _ -> false) | Group _ -> false) && (gluedWords nodes).Length >= 2 then
                    match gluedWords nodes with
                    | callee :: words -> { Indent = indent; Text = inlineText callee } :: (words |> List.map (fun word -> { Indent = indent + 4; Text = inlineText word }))
                    | [] -> [ { Indent = indent; Text = whole } ]
                elif nodes.Length > 1 && not (fits indent whole)
                     && (match List.last nodes with Group (opening, inner, _) -> opening.Token = TokParenthesis (Round, Open) && not opening.InsideMacro && hasTopComma inner && not (carriesComment inner) | Leaf _ -> false)
                     && List.take (nodes.Length - 1) nodes |> List.forall (fun node -> match node with Leaf l -> not l.InsideMacro && (match l.Token with TokVar _ | TokSymbol _ | TokUnaryOperator _ -> true | _ -> false) | Group _ -> false)
                     && fits indent (inlineText (List.take (nodes.Length - 1) nodes) + " (") then
                    match layoutTuple indent (List.last nodes) with
                    | opening :: inner -> { Indent = indent; Text = inlineText (List.take (nodes.Length - 1) nodes) + (match (firstLexeme (List.last nodes)).Before with Whitespace 0 -> "" | _ -> " ") + opening.Text } :: inner
                    | [] -> [ { Indent = indent; Text = whole } ]
                else [ { Indent = indent; Text = whole } ]

        and trailingLambdaNeedsBlock (nodes : Node list) =
            match List.tryLast nodes with
            | Some last ->
                match unwrapLambda [ last ] with
                | (first :: _) as lambda when isKeyword SpecFun first -> opensLayout lambda
                | first :: next :: _ when isKeyword SpecFunction first && isOperator "|" next -> true
                | _ -> false
            | _ -> false

        and lastArgumentLambda (indent : int) (prefix : string) (nodes : Node list) : LaidLine list option =
            let isLambdaGroup (node : Node) =
                match node with
                | Group _ -> (match unwrapLambda [ node ] with first :: _ -> isKeyword SpecFun first | [] -> false)
                | Leaf _ -> false
            let otherLambdas = nodes |> List.take (max 0 (nodes.Length - 1)) |> List.exists isLambdaGroup
            match List.tryLast nodes with
            | Some _ when otherLambdas -> None
            | Some last when nodes.Length > 1 ->
                match unwrapLambda [ last ] with
                | first :: arms when isKeyword SpecFunction first && (match arms with next :: _ -> isOperator "|" next | [] -> false) ->
                    let headText = (if prefix = "" then "" else prefix + " ") + inlineText (List.take (nodes.Length - 1) nodes) + " " + inlineText [ first ]
                    if fits indent headText then Some ({ Indent = indent; Text = headText } :: layoutArms (indent + 4) (splitArms arms)) else None
                | (first :: _) as lambda when isKeyword SpecFun first ->
                    match indexOfTop (isOperator "=>") lambda with
                    | Some arrow ->
                        let lambdaHead = List.take (arrow + 1) lambda
                        let body = unwrapBody (List.skip (arrow + 1) lambda)
                        let headText = (if prefix = "" then "" else prefix + " ") + inlineText (List.take (nodes.Length - 1) nodes) + " " + inlineText lambdaHead
                        match body with
                        | [ Group (opening, inner, closing) ] when opening.Token = TokParenthesis (Curly, Open) && not opening.InsideMacro && sourceLineTable.Value.Length > 0 && not (authoredBreaks.Value.Contains opening.Span.From) && fits indent (headText + " " + fst (recordOpening opening inner)) ->
                            let openText, fields = recordOpening opening inner
                            Some ({ Indent = indent; Text = headText + " " + openText } :: layoutFields (indent + 4) fields @ [ { Indent = indent; Text = (markedText closing) } ])
                        | _ ->
                        if fits indent headText then Some ({ Indent = indent; Text = headText } :: layoutBlock (indent + 4) body)
                        else None
                    | None -> None
                | _ -> None
            | _ -> None

        and layoutArgument (indent : int) (argument : Node) : LaidLine list =
            match argument with
            | Group (opening, inner, closing) when opening.Token = TokParenthesis (Square, Open) && not inner.IsEmpty && not (fits indent (inlineText [ argument ])) ->
                let items = splitOn (isOperator ";") inner |> List.filter (fun item -> not item.IsEmpty)
                { Indent = indent; Text = (markedText opening) } :: (items |> List.collect (layoutExpression (indent + 4))) @ [ { Indent = indent; Text = (markedText closing) } ]
            | Group (opening, inner, closing) when opening.Token = TokParenthesis (Round, Open) && not inner.IsEmpty && not (hasTopComma inner) && (not (fits indent (inlineText [ argument ])) || carriesComment [ argument ]) && (match unwrapLambda [ argument ] with first :: _ -> not (isKeyword SpecFun first) | [] -> true) ->
                let closingComments =
                    match closing.Before with
                    | Embedded gap -> commentsIn gap.Text |> List.filter (fun comment -> comment <> "") |> List.map (fun comment -> { Indent = indent + 4; Text = comment })
                    | Whitespace _ -> []
                { Indent = indent; Text = (markedText opening) } :: layoutBlock (indent + 4) (unwrapBody inner) @ closingComments @ [ { Indent = indent; Text = (markedText closing) } ]
            | Group (opening, inner, _) when opening.Token = TokParenthesis (Round, Open) && hasTopComma inner && not (fits indent (inlineText [ argument ])) -> layoutTuple indent argument
            | Group (opening, inner, closing) when opening.Token = TokParenthesis (Curly, Open) && not (fits indent (inlineText [ argument ])) ->
                let openText, fields = recordOpening opening inner
                { Indent = indent; Text = openText } :: layoutFields (indent + 4) fields @ [ { Indent = indent; Text = (markedText closing) } ]
            | _ -> layoutExpression indent (unwrapLambda [ argument ])

        and keepLambdaParentheses (item : Node list) (lines : LaidLine list) =
            let opensScope =
                match unwrapBody item with
                | first :: _ -> isKeyword SpecFun first || isKeyword SpecFunction first || isKeyword SpecMatch first || isKeyword SpecTypecase first || isKeyword SpecIf first
                | [] -> false
            let scopeWords = [ "fun "; "function"; "match "; "typecase "; "if " ]
            match lines with
            | first :: _ when opensScope && scopeWords |> List.exists (fun word -> first.Text.StartsWith word || first.Text = word.Trim ()) ->
                let wrapped = { first with Text = "(" + first.Text } :: List.tail lines
                match List.rev wrapped with
                | last :: before -> List.rev ({ last with Text = last.Text + ")" } :: before)
                | [] -> wrapped
            | _ -> lines

        and layoutTuple (indent : int) (argument : Node) : LaidLine list =
            match argument with
            | Group (opening, inner, closing) ->
                let items = splitOn (isOperator ",") inner |> List.filter (fun item -> not item.IsEmpty)
                let laid =
                    items
                    |> List.mapi (fun index item ->
                        let lines =
                            match layoutExpression (indent + 4) item with
                            | [ single ] when index < items.Length - 1 && not (fits single.Indent (single.Text + ",")) ->
                                layoutExpression (indent + 5) item |> List.map (fun line -> { line with Indent = max 0 (line.Indent - 1) })
                            | laid -> laid
                        let lines = if index < items.Length - 1 then keepLambdaParentheses item lines else lines
                        if index = items.Length - 1 then lines
                        else
                            match List.rev lines with
                            | last :: before -> List.rev ({ last with Text = last.Text + "," } :: before)
                            | [] -> [])
                    |> List.concat
                { Indent = indent; Text = (markedText opening) } :: laid @ [ { Indent = indent; Text = (markedText closing) } ]
            | Leaf _ -> layoutExpression indent [ argument ]

        and chainSegments (nodes : Node list) : (string list * string * int) option =
            let plain (part : Node list) =
                not (opensLayout part)
                && part |> List.forall (fun node ->
                    match node with
                    | Leaf lexeme -> not lexeme.InsideMacro && (match lexeme.Token with TokKeyword _ -> false | TokOperator ("=>", _) -> false | _ -> true)
                    | Group (opening, _, _) -> not opening.InsideMacro)
            match List.tryLast nodes with
            | Some (Group (opening, inner, closing)) when opening.Token = TokParenthesis (Round, Open) && not opening.InsideMacro && not inner.IsEmpty ->
                let head = List.take (nodes.Length - 1) nodes
                let items = splitOn (isOperator ",") inner |> List.filter (fun item -> not item.IsEmpty)
                let lead = List.take (items.Length - 1) items
                if not (plain head) || not (lead |> List.forall plain) then None
                else
                    match chainSegments (List.last items) with
                    | Some (segments, closers, depth) ->
                        let headText = if head.IsEmpty then "" else inlineText head + " "
                        let leadText = if lead.IsEmpty then "" else (lead |> List.map inlineText |> String.concat ", ") + ", "
                        Some ((headText + (markedText opening) + leadText) :: segments, closers + (markedText closing), depth + 1)
                    | None -> if plain inner then Some ([ inlineText nodes ], "", 0) else None
            | _ -> if plain nodes && not nodes.IsEmpty then Some ([ inlineText nodes ], "", 0) else None

        and fillChain (indent : int) (nodes : Node list) : LaidLine list =
            match chainSegments nodes with
            | Some (first :: rest, closers, _) ->
                let lines = ResizeArray<LaidLine> ()
                let mutable current = { Indent = indent; Text = first }
                for segment in rest do
                    if fits current.Indent (current.Text + segment) || current.Text.Length = 0 then current <- { current with Text = current.Text + segment }
                    else
                        lines.Add ({ current with Text = current.Text.TrimEnd () })
                        current <- { Indent = indent + 4; Text = segment }
                lines.Add ({ current with Text = current.Text + closers })
                List.ofSeq lines
            | _ -> [ { Indent = indent; Text = inlineComplete nodes } ]

        and recordOpening (opening : Lexeme) (inner : Node list) =
            match indexOfTop (isKeyword SpecWith) inner with
            | Some at when at > 0 -> (markedText opening) + " " + inlineText (List.take (at + 1) inner), List.skip (at + 1) inner
            | _ -> (markedText opening), inner

        and layoutFields (indent : int) (inner : Node list) : LaidLine list =
            splitOn (isOperator ";") inner
            |> List.filter (fun field -> not field.IsEmpty)
            |> List.collect (fun field ->
                let text = inlineComplete field
                match indexOfTop (isOperator "=") field with
                | Some at when not (fits indent text) || opensLayout (unwrapBody (List.skip (at + 1) field)) || (statements (unwrapBody (List.skip (at + 1) field))).Length > 1 ->
                    let body = unwrapBody (List.skip (at + 1) field)
                    let headText = inlineText (List.take (at + 1) field)
                    match body with
                    | first :: _ when isKeyword SpecFun first && (indexOfTop (isOperator "=>") body).IsSome ->
                        let arrow = (indexOfTop (isOperator "=>") body).Value
                        let lambdaHead = inlineText (List.take (arrow + 1) body)
                        { Indent = indent; Text = headText + " " + lambdaHead } :: layoutBlock (indent + 4) (unwrapBody (List.skip (arrow + 1) body))
                    | _ -> { Indent = indent; Text = headText } :: layoutBlock (indent + 4) body
                | _ -> [ { Indent = indent; Text = text } ])

        and unwrapLambda (nodes : Node list) =
            match nodes with
            | [ Group (opening, (first :: _ as inner), _) ] when opening.Token = TokParenthesis (Round, Open) && (isKeyword SpecFun first || isKeyword SpecFunction first) -> inner
            | [ Group (opening, ([ Group _ ] as inner), _) ] when opening.Token = TokParenthesis (Round, Open) ->
                match unwrapLambda inner with
                | first :: _ as unwrapped when isKeyword SpecFun first || isKeyword SpecFunction first -> unwrapped
                | _ -> nodes
            | _ -> nodes

        let rec mergeAll (nodes : Node list) : Node list =
            nodes
            |> List.map (fun node ->
                match node with
                | Group (opening, inner, closing) when opening.Token <> TokStringOpen && opening.Token <> TokMacroOpen -> Group (opening, mergeAll inner, closing)
                | _ -> node)
            |> fun merged -> if literalSplitting.Enabled then mergeConcatenations merged else merged

        type FlatLayout =
            | LaidOut of string list
            | AsWritten
            | CommentsMisplaced of expected : int * placed : int
            | CommentsInline of count : int
            | NotOneCodeLine

        let layoutFlatLine (text : string) (lineStarts : (string * bool) list) (sourceLines : (int * string option * string list) list) : FlatLayout =
            match lexLine lex_state_init text with
            | Code (0, lexemes, tail), _ when tail.Text.Trim().Length = 0 ->
                let expected = lexemes |> Array.sumBy (fun lexeme -> match lexeme.Before with Embedded gap -> (commentsIn gap.Text |> List.filter (fun comment -> comment <> "")).Length | Whitespace _ -> 0)
                markAuthoredBreaks lexemes lineStarts sourceLines
                let nodes = mergeAll (fst (nodesOf (List.ofArray lexemes)))
                let laid = layoutBlock 0 nodes |> List.map (fun line -> System.String (' ', line.Indent) + line.Text)
                authoredBreaks.Value.Clear ()
                syntheticTokens.Value.Clear ()
                tokenLines.Value.Clear ()
                sourceLineTable.Value <- [||]
                sourceLineTokens.Value <- [||]
                let mutable state = lex_state_init
                let mutable placed = 0
                let mutable inlined = 0
                for line in laid do
                    let shape, next = lexLine state (stripMarks line)
                    state <- next
                    match shape with
                    | Remark _ -> placed <- placed + 1
                    | Code (_, lexemes, tail) ->
                        let embedded = lexemes |> Array.sumBy (fun lexeme -> match lexeme.Before with Embedded gap -> (commentsIn gap.Text |> List.filter (fun comment -> comment <> "")).Length | Whitespace _ -> 0)
                        inlined <- inlined + embedded + (if tail.Text.Contains "(*" then 1 else 0)
                        if tail.Text.TrimStart().StartsWith "//" then placed <- placed + 1
                    | Opaque _ | Blank -> ()
                if inlined > 0 then CommentsInline inlined
                elif placed <> expected then CommentsMisplaced (expected, placed)
                else LaidOut laid
            | _ -> NotOneCodeLine

        let isOpenLine (text : string) = text.StartsWith "open "

        let joinMacroContinuations (text : string) =
            if not literalSplitting.Enabled then text
            else
                let output = ResizeArray<string> ()
                let authored = ResizeArray<string> ()
                let mutable state = lex_state_init
                let mutable pending : string option = None
                let keepOrJoin (joined : string) =
                    if authored |> Seq.exists (fun line -> line.Length > 120) then output.Add joined else output.AddRange authored
                    authored.Clear ()
                for line in splitLines text do
                    let shape, next = lexLine state line
                    let joined = match pending with Some head -> head + line.TrimStart () | None -> line
                    authored.Add line
                    match shape with
                    | Opaque (_, InMacro) when line.EndsWith "\\" && next <> lex_state_init -> pending <- Some (joined.Substring (0, joined.Length - 1))
                    | _ ->
                        keepOrJoin joined
                        pending <- None
                    state <- next
                pending |> Option.iter keepOrJoin
                String.concat "\n" output + (if text.EndsWith "\n" then "\n" else "")

        type LayoutTally() =
            member val VerbatimBlocks = 0 with get, set
            member val VerbatimLines = 0 with get, set
            member val GuardedBlocks = 0 with get, set
            member val Kept = ResizeArray<string * string> ()

        let layoutTally = LayoutTally ()

        let rewrapComments (lines : string list) =
            let mutable fenced = false
            lines
            |> List.collect (fun line ->
                let trimmed = line.TrimStart ()
                if not (trimmed.StartsWith "//") then [ line ]
                else
                    let indent = line.Length - trimmed.Length
                    let slashes = trimmed |> Seq.takeWhile (fun c -> c = '/') |> Seq.length
                    let marker = trimmed.Substring (0, slashes)
                    let body = trimmed.Substring(slashes).TrimStart ()
                    if body.StartsWith "```" then
                        fenced <- not fenced
                        [ line ]
                    elif fenced || line.Length <= 120 || body.StartsWith "#" || body.StartsWith ">" then [ line ]
                    else
                        let prefix = System.String (' ', indent) + marker + " "
                        let words = body.Split ' ' |> Array.filter (fun word -> word.Length > 0)
                        let output = ResizeArray<string> ()
                        let current = StringBuilder (prefix)
                        for word in words do
                            if current.Length > prefix.Length && current.Length + 1 + word.Length > 120 then
                                output.Add (current.ToString ())
                                current.Clear().Append(prefix) |> ignore
                            if current.Length > prefix.Length then current.Append ' ' |> ignore
                            current.Append word |> ignore
                        if current.Length > prefix.Length then output.Add (current.ToString ())
                        List.ofSeq output)

        let layout (source : Source<'phase>) =
            let _, blocks = flatten source
            let output = ResizeArray<string> ()
            let mutable previousCode : string option = None
            let mutable previousSingleInstance = false
            let mutable pendingBlanks = 0
            for block in blocks do
                let lines =
                    match block with
                    | Flattened (flat, original) ->
                        flat |> List.collect (function
                            | Kept text -> [ text ]
                            | Joined (text, lineStarts, sourceLines) ->
                                let shapes (lines : string list) =
                                    blockShapes source.FileEdition source.FileUnit (String.concat "\n" lines + "\n")
                                    |> List.map (fun block -> block.Shape)
                                    |> List.filter (fun shape -> shape <> "error")
                                let kept () = original |> List.rev |> List.skipWhile (fun line -> line.Trim().Length = 0) |> List.rev
                                let head () = original |> List.tryFind (fun line -> line.Trim().Length > 0 && not (line.TrimStart().StartsWith "//")) |> Option.defaultValue ""
                                let expected = lazy (shapes original)
                                let sameParse (lines : string list) = not (expected.Value |> List.exists (fun shape -> shape.StartsWith "error (")) && shapes lines = expected.Value
                                let chosen (marked : string list) =
                                    let preferred = List.map dropSyntheticParentheses (liftSyntheticGroups marked)
                                    if sameParse preferred then Some preferred
                                    else
                                        let plain = List.map stripMarks marked
                                        if sameParse plain then Some plain else None
                                let fitsAsWritten = original |> List.forall (fun line -> line.TrimStart().StartsWith "//" || displayWidth line <= 120)
                                relaidSpans.Value.Clear ()
                                let retried () =
                                    let spans = relaidSpans.Value |> Seq.distinct |> List.ofSeq
                                    let inside (a1, b1) (a2, b2) = a2 <= a1 && b1 <= b2
                                    let leaves = spans |> List.filter (fun span -> not (spans |> List.exists (fun other -> other <> span && inside other span)))
                                    let around span = spans |> List.filter (fun other -> inside span other)
                                    let parentheses (lines : string list) = lines |> List.sumBy (fun line -> line |> Seq.filter (fun c -> c = '(' || c = ')') |> Seq.length)
                                    let authored = parentheses original
                                    let mutable accepted : (int * int) list = []
                                    let mutable best = None
                                    for leaf in leaves do
                                        relayOnly.Value <- Some ((accepted @ around leaf) |> List.map fst |> List.distinct |> Array.ofList)
                                        match layoutFlatLine text lineStarts sourceLines with
                                        | LaidOut retry ->
                                            match chosen retry with
                                            | Some laid when parentheses laid = authored ->
                                                accepted <- accepted @ around leaf
                                                best <- Some laid
                                            | _ -> ()
                                        | _ -> ()
                                    relayOnly.Value <- None
                                    best
                                let joinThenLines (lines : string list) : string list =
                                    let rows = ResizeArray<string>(lines)
                                    let indentOf (line : string) = line.Length - line.TrimStart(' ').Length
                                    let quoteSafe (line : string) =
                                        not (line.Contains "\"\"\"") && not (line.EndsWith "\\") && (line |> Seq.filter (fun c -> c = '"') |> Seq.length) % 2 = 0
                                    let conditionHead (text : string) = text.StartsWith "? " || text.StartsWith "|? " || text.StartsWith "if " || text.StartsWith "elif "
                                    let thenText (text : string) = text = "?>" || text.StartsWith "?> " || text = "then" || text.StartsWith "then "
                                    let mutable at = 1
                                    while at < rows.Count do
                                        let line = rows.[at]
                                        let trimmed = line.Trim ()
                                        let previous = rows.[at - 1]
                                        if thenText trimmed
                                           && indentOf line = indentOf previous
                                           && conditionHead (previous.TrimStart ())
                                           && not (previous.Contains "//")
                                           && quoteSafe previous
                                           && quoteSafe line
                                           && displayWidth (previous + " " + trimmed) <= 120 then
                                            rows.[at - 1] <- previous + " " + trimmed
                                            rows.RemoveAt at
                                        else at <- at + 1
                                    List.ofSeq rows
                                let textHabits (lines : string list) : string list =
                                    let rows = ResizeArray<string>(lines)
                                    let indentOf (line : string) = line.Length - line.TrimStart(' ').Length
                                    let pad (indent : int) (text : string) = System.String (' ', indent) + text
                                    let balanced (text : string) =
                                        not (text.Contains "\"")
                                        && not (text.Contains "'('")
                                        && not (text.Contains "')'")
                                        && (text |> Seq.fold (fun depth c -> if depth < 0 then depth elif c = '(' then depth + 1 elif c = ')' then depth - 1 else depth) 0) = 0
                                    let pipeStageAt (at : int) (indent : int) = at < rows.Count && indentOf rows.[at] = indent && rows.[at].TrimStart().StartsWith "|> "
                                    let mutable at = 0
                                    while at < rows.Count - 1 do
                                        let line = rows.[at]
                                        let trimmed = line.Trim ()
                                        let i = indentOf line
                                        if trimmed.StartsWith "(join " && trimmed.EndsWith ")" && pipeStageAt (at + 1) i && balanced (trimmed.Substring (1, trimmed.Length - 2)) then
                                            rows.[at] <- pad i (trimmed.Substring (1, trimmed.Length - 2))
                                        elif trimmed = "("
                                             && at + 3 < rows.Count
                                             && rows.[at + 1].TrimStart().StartsWith "join "
                                             && indentOf rows.[at + 1] = i + 4
                                             && rows.[at + 2].Trim () = ")"
                                             && indentOf rows.[at + 2] = i
                                             && pipeStageAt (at + 3) i
                                             && balanced (rows.[at + 1].Trim ()) then
                                            rows.[at] <- pad i (rows.[at + 1].Trim ())
                                            rows.RemoveRange (at + 1, 2)
                                        at <- at + 1
                                    let quoteSafe (line : string) =
                                        not (line.Contains "\"\"\"") && not (line.EndsWith "\\") && (line |> Seq.filter (fun c -> c = '"') |> Seq.length) % 2 = 0
                                    let mutable at = 0
                                    while at < rows.Count - 1 do
                                        let line = rows.[at]
                                        let i = indentOf line
                                        if line.TrimStart().StartsWith "|> " && rows.[at + 1].Trim () <> "" && indentOf rows.[at + 1] = i + 7 then
                                            let stop = [ at + 1 .. rows.Count - 1 ] |> List.tryFind (fun k -> rows.[k].Trim () <> "" && indentOf rows.[k] <= i) |> Option.defaultValue rows.Count
                                            let block = [ at + 1 .. stop - 1 ]
                                            if block |> List.forall (fun k -> rows.[k].Trim () = "" || (indentOf rows.[k] >= i + 3 && quoteSafe rows.[k])) then
                                                for k in block do
                                                    if rows.[k].Trim () <> "" then rows.[k] <- rows.[k].Substring 3
                                                let head = rows.[at + 1].Trim ()
                                                if head.StartsWith "fun " && head.EndsWith "=>" && at + 2 < stop && indentOf rows.[at + 2] > i + 4 && fits 0 (line + " " + head) then
                                                    rows.[at] <- line + " " + head
                                                    rows.RemoveAt (at + 1)
                                        at <- at + 1
                                    let leavesOpen (line : string) =
                                        let mutable depth = 0
                                        for c in line do
                                            if c = '{' || c = '(' || c = '[' then depth <- depth + 1
                                            elif c = '}' || c = ')' || c = ']' then depth <- depth - 1
                                        depth > 0
                                    let mutable at = 1
                                    while at < rows.Count do
                                        let line = rows.[at]
                                        let i = indentOf line
                                        let previous = rows.[at - 1]
                                        let p = indentOf previous
                                        if line.Trim () <> "" && i % 4 <> 0 && p % 4 = 0 && i > p && quoteSafe line && quoteSafe previous && leavesOpen previous then
                                            let mutable k = at
                                            while k < rows.Count && rows.[k].Trim () <> "" && indentOf rows.[k] = i && quoteSafe rows.[k] do k <- k + 1
                                            if [ at .. k - 1 ] |> List.forall (fun j -> fits (p + 4) (rows.[j].TrimStart ())) then
                                                for j in at .. k - 1 do rows.[j] <- pad (p + 4) (rows.[j].TrimStart ())
                                                let mutable close = k
                                                while close < rows.Count && (rows.[close].Trim () = "" || indentOf rows.[close] >= i) do close <- close + 1
                                                if close < rows.Count && indentOf rows.[close] > p && quoteSafe rows.[close] && (let text = rows.[close].TrimStart () in text.StartsWith ")" || text.StartsWith "]" || text.StartsWith "}") then
                                                    rows.[close] <- pad p (rows.[close].TrimStart ())
                                            at <- k
                                        else at <- at + 1
                                    joinThenLines (List.ofSeq rows)
                                match (if fitsAsWritten then AsWritten else layoutFlatLine text lineStarts sourceLines) with
                                | AsWritten ->
                                    let written = kept ()
                                    let habitual = textHabits written
                                    if habitual <> written && sameParse habitual then habitual else written
                                | LaidOut marked ->
                                    match chosen marked with
                                    | Some laid ->
                                        let joined = joinThenLines laid
                                        let laid = if joined <> laid && sameParse joined then joined else laid
                                        let split = laid |> List.collect splitMacroLine
                                        if split = laid || sameParse split then split else laid
                                    | None ->
                                        match retried () with
                                        | Some laid ->
                                            layoutTally.Kept.Add ("parse-guard-partial", head ())
                                            let split = laid |> List.collect splitMacroLine
                                            if split = laid || sameParse split then split else laid
                                        | None ->
                                            layoutTally.GuardedBlocks <- layoutTally.GuardedBlocks + 1
                                            layoutTally.Kept.Add ("parse-guard", head ())
                                            match Environment.GetEnvironmentVariable "SPIRAL_FORMAT_GUARD_DUMP" with
                                            | null | "" -> ()
                                            | directory ->
                                                let originalText = String.concat "\n" original
                                                let candidateText = String.concat "\n" (List.map stripMarks marked)
                                                let name = sprintf "%08x.txt" ((originalText.GetHashCode ()) &&& 0x7fffffff)
                                                Directory.CreateDirectory directory |> ignore
                                                File.WriteAllText (Path.Combine (directory, name), "== original\n" + originalText + "\n== candidate\n" + candidateText + "\n== expected shapes\n" + String.concat "\n" expected.Value + "\n== candidate shapes\n" + String.concat "\n" (shapes (List.map stripMarks marked)) + "\n")
                                            kept ()
                                | refusal ->
                                    let lines = kept ()
                                    layoutTally.VerbatimBlocks <- layoutTally.VerbatimBlocks + 1
                                    layoutTally.VerbatimLines <- layoutTally.VerbatimLines + lines.Length
                                    let reason =
                                        match refusal with
                                        | CommentsInline count -> sprintf "comments-inline %d" count
                                        | CommentsMisplaced (expected, placed) -> sprintf "comments-misplaced %d/%d" placed expected
                                        | NotOneCodeLine | LaidOut _ | AsWritten -> "not-one-code-line"
                                    layoutTally.Kept.Add (reason, head ())
                                    lines)
                    | Refused (_, _, original) -> original
                let lines = lines |> List.filter (fun line -> let trimmed = line.Trim () in trimmed <> segmentHead && trimmed <> segmentTail)
                let isBlankLine (line : string) = line.Trim().Length = 0
                let leadingBlanks = lines |> List.takeWhile isBlankLine |> List.length
                let trailingBlanks = lines |> List.rev |> List.takeWhile isBlankLine |> List.length
                let lines = lines |> List.skipWhile isBlankLine |> List.rev |> List.skipWhile isBlankLine |> List.rev
                match lines with
                | [] -> pendingBlanks <- pendingBlanks + leadingBlanks
                | first :: _ ->
                    let codeStart = lines |> List.tryFind (fun line -> not (line.TrimStart().StartsWith "//") && line.Trim().Length > 0)
                    let codeLines = lines |> List.filter (fun line -> not (line.TrimStart().StartsWith "//") && line.Trim().Length > 0)
                    let oneLineInstance = codeLines.Length = 1 && codeLines.Head.StartsWith "instance "
                    let singleInstance = oneLineInstance && first = codeLines.Head
                    match previousCode with
                    | Some _ -> for _ in 1 .. pendingBlanks + leadingBlanks do output.Add ""
                    | None -> ()
                    pendingBlanks <- trailingBlanks
                    match block with
                    | Refused _ -> output.AddRange lines
                    | Flattened _ ->
                        output.AddRange (rewrapComments lines)
                    previousCode <- match codeStart with Some c -> Some c | None -> previousCode
                    previousSingleInstance <- oneLineInstance
            List.ofSeq output

    module FormatterFormat =

        open System
        open System.IO
        open FormatterLexed
        open FormatterParsed
        open FormatterSpacing
        open FormatterCheck
        open FormatterConvert
        open FormatterFlatten
        open FormatterLayout

        type Entry =
            { Corpus : string
              Edition : Edition
              Path : string
              Rel : string }

        let readEntries (inputs : string list) =
            inputs
            |> List.collect (fun input ->
                if input.EndsWith ".tsv" then
                    File.ReadAllLines input
                    |> Array.filter (fun row -> row.Length > 0)
                    |> Array.map (fun row ->
                        let cells = row.Split '\t'
                        { Corpus = cells.[0]
                          Edition = (if cells.[1] = "2" then Edition2 else Edition3)
                          Path = cells.[2]
                          Rel = cells.[3] })
                    |> List.ofArray
                else [ { Corpus = "files"; Edition = Edition3; Path = input; Rel = Path.GetFileName input } ])

        let readText (entry : Entry) = File.ReadAllText(entry.Path).Replace ("\r\n", "\n")

        type Tally() =
            let counts = Collections.Generic.SortedDictionary<string, int> (StringComparer.Ordinal)
            member _.Add (key : string) (amount : int) =
                counts.[key] <- (match counts.TryGetValue key with | true, current -> current + amount | _ -> amount)
            member _.Get (key : string) = match counts.TryGetValue key with | true, current -> current | _ -> 0
            member _.Rows = counts |> Seq.map (fun pair -> pair.Key, pair.Value) |> List.ofSeq

        let printTally (title : string) (tally : Tally) =
            printfn "%s" title
            for key, value in tally.Rows do
                printfn "  %s\t%d" key value

        let corpora (entries : Entry list) = entries |> List.map (fun entry -> entry.Corpus) |> List.distinct

        let runCheck (entries : Entry list) (listing : TextWriter) =
            let tally = Tally ()
            for entry in entries do
                let source = lexText entry.Path entry.Edition (readText entry)
                tally.Add (entry.Corpus + "\tlines") source.SourceLines.Length
                for overflow in overflows source do
                    let name = constructName overflow.Construct
                    tally.Add (entry.Corpus + "\tover120") 1
                    tally.Add (entry.Corpus + "\tover120\t" + name) 1
                    listing.WriteLine (sprintf "%s:%d\t%d\t%s" entry.Rel overflow.Line overflow.Width name)
            printTally "check" tally
            tally

        let changeName change =
            match change with
            | TrailingWhitespace -> "trailing-whitespace"
            | GuardKept -> "guard-kept"
            | Respaced reason -> sprintf "%A" reason

        let tokenStream (source : Source<'phase>) =
            source.SourceLines
            |> Array.collect (fun line ->
                match line.Shape with
                | Code (_, lexemes, _) -> tokenKinds lexemes |> Array.map (fun (kind, text) -> kind + " " + text)
                | Opaque (text, _) -> [| "opaque " + text.Text.TrimEnd () |]
                | Remark _ | Blank -> [||])

        let runSpace (entries : Entry list) (outDir : string option) (listing : TextWriter) (verifyParse : bool) =
            let tally = Tally ()
            for entry in entries do
                let text = readText entry
                let source = lexText entry.Path entry.Edition text
                let spaced, changes = respace source
                let output = joinLines (renderAll spaced)
                let changedLines = changes |> Array.filter (fun (_, lineChanges, _) -> not (List.isEmpty lineChanges))
                tally.Add (entry.Corpus + "\tfiles") 1
                tally.Add (entry.Corpus + "\tlines") source.SourceLines.Length
                tally.Add (entry.Corpus + "\tlines-changed") (changedLines |> Array.filter (fun (_, c, _) -> c <> [ GuardKept ]) |> Array.length)
                if output <> text then tally.Add (entry.Corpus + "\tfiles-changed") 1
                for number, lineChanges, guard in changedLines do
                    for change in List.distinct lineChanges do
                        tally.Add (entry.Corpus + "\trule\t" + changeName change) 1
                    let names = lineChanges |> List.map changeName |> List.distinct |> String.concat ","
                    listing.WriteLine (sprintf "%s:%d\t%s%s" entry.Rel number names (match guard with Some rejected -> "\t" + rejected | None -> ""))
                let again, _ = respace (lexText entry.Path entry.Edition output)
                if joinLines (renderAll again) <> output then
                    tally.Add (entry.Corpus + "\tG1-not-idempotent") 1
                    listing.WriteLine (sprintf "%s\tG1-not-idempotent" entry.Rel)
                if tokenStream source <> tokenStream spaced then
                    tally.Add (entry.Corpus + "\tF6-token-drift") 1
                    listing.WriteLine (sprintf "%s\tF6-token-drift" entry.Rel)
                if verifyParse && output <> text then
                    match compareParses entry.Edition spaced.FileUnit text output with
                    | SameParse -> tally.Add (entry.Corpus + "\tparse-same") 1
                    | OriginalHasErrors -> tally.Add (entry.Corpus + "\tparse-original-has-errors") 1
                    | ParseDiffers line ->
                        tally.Add (entry.Corpus + "\tparse-differs") 1
                        listing.WriteLine (sprintf "%s:%d\tparse-differs" entry.Rel line)
                match outDir with
                | Some dir ->
                    let target = Path.Combine (dir, entry.Corpus, entry.Rel.Replace ('/', Path.DirectorySeparatorChar))
                    Directory.CreateDirectory (Path.GetDirectoryName target) |> ignore
                    File.WriteAllText (target, output)
                | None -> ()
            printTally "space" tally
            tally

        let runConvert (entries : Entry list) (outDir : string option) (listing : TextWriter) (verifyParse : bool) =
            let tally = Tally ()
            for entry in entries do
                let text = readText entry
                let source = lexText entry.Path entry.Edition text
                let original = joinLines (renderAll source)
                let symbols, converted, rejected = convert Symbols source
                let symbolText = joinLines symbols
                let words, _, rejectedBack = convert Words (lexText entry.Path Edition3 symbolText)
                let roundTrip = joinLines words
                tally.Add (entry.Corpus + "\tfiles") 1
                tally.Add (entry.Corpus + "\tlines-converted") converted
                tally.Add (entry.Corpus + "\tlines-rejected") rejected.Length
                tally.Add (entry.Corpus + "\tlines-rejected-back") rejectedBack.Length
                for number, attempted in rejected do
                    listing.WriteLine (sprintf "%s:%d\trejected\t%s" entry.Rel number attempted)
                if roundTrip = original then tally.Add (entry.Corpus + "\tround-trip-identical") 1
                else
                    tally.Add (entry.Corpus + "\tround-trip-differs") 1
                    listing.WriteLine (sprintf "%s\tround-trip-differs" entry.Rel)
                if verifyParse && converted > 0 then
                    match compareParses entry.Edition source.FileUnit original symbolText with
                    | SameParse -> tally.Add (entry.Corpus + "\tparse-same") 1
                    | OriginalHasErrors -> tally.Add (entry.Corpus + "\tparse-original-has-errors") 1
                    | ParseDiffers line ->
                        tally.Add (entry.Corpus + "\tparse-differs") 1
                        listing.WriteLine (sprintf "%s:%d\tparse-differs" entry.Rel line)
                match outDir with
                | Some dir ->
                    let target = Path.Combine (dir, entry.Corpus, entry.Rel.Replace ('/', Path.DirectorySeparatorChar))
                    Directory.CreateDirectory (Path.GetDirectoryName target) |> ignore
                    File.WriteAllText (target, symbolText)
                | None -> ()
            printTally "convert" tally
            tally

        let runFlatten (entries : Entry list) (outDir : string option) (listing : TextWriter) =
            let tally = Tally ()
            for entry in entries do
                let text = readText entry
                let source = lexText entry.Path entry.Edition text
                let lines, blocks = flatten source
                let flatText = joinLines (Array.ofList lines)
                tally.Add (entry.Corpus + "\tfiles") 1
                tally.Add (entry.Corpus + "\tlines-in") source.SourceLines.Length
                tally.Add (entry.Corpus + "\tlines-out") lines.Length
                for block in blocks do
                    match block with
                    | Flattened _ -> tally.Add (entry.Corpus + "\tblocks-flattened") 1
                    | Refused (reason, line, _) ->
                        tally.Add (entry.Corpus + "\tblocks-refused\t" + (sprintf "%A" reason)) 1
                        listing.WriteLine (sprintf "%s:%d\trefused\t%A" entry.Rel line reason)
                let relexed = lexText entry.Path entry.Edition flatText
                let opaque = relexed.SourceLines |> Array.filter (fun line -> match line.Shape with Opaque _ -> true | _ -> false) |> Array.length
                let opaqueBefore = source.SourceLines |> Array.filter (fun line -> match line.Shape with Opaque _ -> true | _ -> false) |> Array.length
                if opaque > opaqueBefore then
                    tally.Add (entry.Corpus + "\tG7-1-lex-errors") 1
                    listing.WriteLine (sprintf "%s\tG7-1-lex-errors\t%d" entry.Rel (opaque - opaqueBefore))
                match compareParses entry.Edition source.FileUnit text flatText with
                | SameParse -> tally.Add (entry.Corpus + "\tG7-parse-same") 1
                | OriginalHasErrors -> tally.Add (entry.Corpus + "\tG7-original-has-errors") 1
                | ParseDiffers line ->
                    tally.Add (entry.Corpus + "\tG7-parse-differs") 1
                    listing.WriteLine (sprintf "%s:%d\tG7-parse-differs" entry.Rel line)
                match outDir with
                | Some dir ->
                    let target = Path.Combine (dir, entry.Corpus, entry.Rel.Replace ('/', Path.DirectorySeparatorChar))
                    Directory.CreateDirectory (Path.GetDirectoryName target) |> ignore
                    File.WriteAllText (target, flatText)
                | None -> ()
            printTally "flatten" tally
            tally

        let formatText (path : string) (edition : Edition) (text : string) =
            let prespaced = let spaced, _ = respace (lexText path edition (joinMacroContinuations text)) in joinLines (renderAll spaced)
            let laid = joinLines (Array.ofList (layout (lexText path edition prespaced)))
            if laid = prespaced && Environment.GetEnvironmentVariable "SPIRAL_FORMAT_FULL_SECOND_PASS" <> "1" then prespaced
            else
                let spaced, _ = respace (lexText path edition laid)
                joinLines (renderAll spaced)

        let commentWords (source : Source<'phase>) =
            let words (text : string) =
                text.Replace("(*", " ").Replace("*)", " ").Split ([| ' '; '\t' |], StringSplitOptions.RemoveEmptyEntries)
                |> Array.map (fun word -> word.TrimStart '/')
                |> Array.filter (fun word -> word.Length > 0 && word <> "!" && word <> "-" && word <> ">")
            source.SourceLines
            |> Array.collect (fun line ->
                match line.Shape with
                | Remark text -> words text.Text
                | Opaque (text, (InComment | Unlexable)) -> words text.Text
                | Opaque (_, (InString | InMacro)) -> [||]
                | Code (_, lexemes, tail) ->
                    let embedded = lexemes |> Array.collect (fun lexeme -> match lexeme.Before with Embedded gap -> words gap.Text | Whitespace _ -> [||])
                    Array.append embedded (words tail.Text)
                | Blank -> [||])

        let runFormat (entries : Entry list) (outDir : string option) (listing : TextWriter) =
            let tally = Tally ()
            for entry in entries do
                let text = readText entry
                let original = joinLines (renderAll (lexText entry.Path entry.Edition text))
                let guardedBefore = layoutTally.GuardedBlocks
                let blocksBefore = layoutTally.VerbatimBlocks
                let linesBefore = layoutTally.VerbatimLines
                let keptBefore = layoutTally.Kept.Count
                let formatted = formatText entry.Path entry.Edition text
                for index in keptBefore .. layoutTally.Kept.Count - 1 do
                    let reason, head = layoutTally.Kept.[index]
                    listing.WriteLine (sprintf "%s\tkept-verbatim\t%s\t%s" entry.Rel reason (head.Trim ()))
                tally.Add (entry.Corpus + "\tverbatim-comment-blocks") (layoutTally.VerbatimBlocks - blocksBefore)
                tally.Add (entry.Corpus + "\tverbatim-parse-guard-blocks") (layoutTally.GuardedBlocks - guardedBefore)
                tally.Add (entry.Corpus + "\tverbatim-comment-block-lines") (layoutTally.VerbatimLines - linesBefore)
                let originalLines = splitLines original |> Array.filter (fun line -> line.Trim().Length > 0)
                let formattedLines = splitLines formatted |> Array.filter (fun line -> line.Trim().Length > 0)
                let originalSet = System.Collections.Generic.HashSet<string> (originalLines |> Array.map (fun l -> l.TrimEnd ()))
                let kept = formattedLines |> Array.filter (fun line -> originalSet.Contains line) |> Array.length
                tally.Add (entry.Corpus + "\tfiles") 1
                tally.Add (entry.Corpus + "\tlines-in-nonblank") originalLines.Length
                tally.Add (entry.Corpus + "\tlines-out-nonblank") formattedLines.Length
                tally.Add (entry.Corpus + "\tlines-out-found-in-input") kept
                tally.Add (entry.Corpus + "\tover120-out") (formattedLines |> Array.filter (fun l -> displayWidth l > 120) |> Array.length)
                let insideFences =
                    formattedLines
                    |> Array.fold (fun (fenced : bool, marks : bool list) line ->
                        let body = line.TrimStart().TrimStart('/').TrimStart ()
                        let isComment = line.TrimStart().StartsWith "//"
                        if isComment && body.StartsWith "```" then (not fenced, true :: marks)
                        else (fenced, (fenced && isComment) :: marks)) (false, [])
                    |> snd
                    |> List.rev
                    |> Array.ofList
                let outsideFences = Array.zip formattedLines insideFences |> Array.filter (fun (line, fenced) -> displayWidth line > 120 && not fenced) |> Array.map fst
                tally.Add (entry.Corpus + "\tover120-out-outside-fences") outsideFences.Length
                for line in outsideFences do listing.WriteLine (sprintf "%s\tover120-left\t%d\t%s" entry.Rel (displayWidth line) (line.Trim().Substring (0, min 60 (line.Trim().Length))))
                let formattedSource = lexText entry.Path entry.Edition formatted
                let inputSource = lexText entry.Path entry.Edition text
                let layoutOverflows (source : Source<'p>) =
                    overflows source |> Array.filter (fun overflow -> match overflow.Construct with LiteralTooWide _ | CommentTail | OpaqueText -> false | _ -> true)
                tally.Add (entry.Corpus + "\tover120-layout-in") (layoutOverflows inputSource).Length
                tally.Add (entry.Corpus + "\tover120-layout-out") (layoutOverflows formattedSource).Length
                let inputTrimmed = System.Collections.Generic.HashSet<string> (originalLines |> Array.map (fun l -> l.Trim ()))
                let created = layoutOverflows formattedSource |> Array.filter (fun overflow -> not (inputTrimmed.Contains ((splitLines formatted).[overflow.Line - 1].Trim ())))
                let fencedLineNumbers =
                    let all = splitLines formatted
                    let mutable fenced = false
                    all
                    |> Array.mapi (fun index line ->
                        let isComment = line.TrimStart().StartsWith "//"
                        let body = line.TrimStart().TrimStart('/').TrimStart ()
                        if isComment && body.StartsWith "```" then
                            fenced <- not fenced
                            None
                        elif fenced && isComment then Some (index + 1)
                        else None)
                    |> Array.choose id
                    |> Set.ofArray
                let sha256 (text : string) = Security.Cryptography.SHA256.HashData(Text.Encoding.UTF8.GetBytes text) |> Convert.ToHexString |> fun hex -> hex.ToLowerInvariant ()
                let unparsableLines =
                    let shapes = blockShapes entry.Edition formattedSource.FileUnit formatted
                    let total = (splitLines formatted).Length
                    shapes
                    |> List.mapi (fun index block ->
                        let stop = match List.tryItem (index + 1) shapes with Some next -> next.Offset | None -> total
                        if block.Shape.StartsWith "error (" || block.Shape.StartsWith "test error (" then [ block.Offset + 1 .. stop ] else [])
                    |> List.concat
                    |> Set.ofList
                for overflow in overflows formattedSource do
                    let sourceLine = formattedSource.SourceLines |> Array.find (fun line -> line.Number = overflow.Line)
                    let longIdentifier =
                        match sourceLine.Shape with
                        | Code (_, lexemes, _) ->
                            let leading =
                                match lexemes |> Array.tryHead with
                                | Some first when (match first.Token with TokOperator ("|", _) | TokParenthesis (_, Open) -> true | _ -> false) -> Array.truncate 2 lexemes |> Array.skip 1
                                | _ -> Array.truncate 1 lexemes
                            leading
                            |> Array.tryFind (fun lexeme ->
                                not lexeme.InsideMacro
                                && (match lexeme.Token with TokVar _ | TokSymbol _ -> true | _ -> false)
                                && lexeme.Span.NearTo - lexeme.Span.From >= 40
                                && lexeme.Span.NearTo > 118)
                        | _ -> None
                    let unparsable = unparsableLines.Contains overflow.Line
                    let allowable = match overflow.Construct with LiteralTooWide _ | CommentTail | OpaqueText -> true | _ -> longIdentifier.IsSome || unparsable
                    if allowable && not (fencedLineNumbers.Contains overflow.Line) then
                        let lineText = (render sourceLine).Trim ()
                        let key =
                            match overflow.Construct, sourceLine.Shape with
                            | LiteralTooWide (_, width), Code (_, lexemes, _) ->
                                let rendered = render sourceLine
                                literalSpans lexemes
                                |> List.indexed
                                |> List.tryFind (fun (_, (_, spanWidth)) -> spanWidth = width)
                                |> Option.bind (fun (position, _) ->
                                    let opens = lexemes |> Array.filter (fun lexeme -> match lexeme.Token with TokMacroOpen -> true | TokStringOpen -> true | TokValue value -> (match value with LitString _ -> true | LitChar _ -> true | _ -> false) | _ -> false)
                                    Array.tryItem position opens |> Option.map (fun opening -> rendered.Substring (opening.Span.From, min width (rendered.Length - opening.Span.From))))
                                |> Option.defaultValue lineText
                            | _ -> match longIdentifier with Some lexeme -> lexeme.Text.Text | None -> lineText
                        let kind =
                            match overflow.Construct, longIdentifier with
                            | (LiteralTooWide _ | CommentTail | OpaqueText), _ -> constructName overflow.Construct
                            | _, Some _ -> "identifier"
                            | _, None when unparsable -> "unparsable"
                            | _, None -> constructName overflow.Construct
                        listing.WriteLine (sprintf "%s\tallow\t%s\t%s\t%d" entry.Rel kind (sha256 key) overflow.Width)
                tally.Add (entry.Corpus + "\tover120-layout-created") created.Length
                for overflow in created do listing.WriteLine (sprintf "%s:%d\tover120-created\t%s" entry.Rel overflow.Line (constructName overflow.Construct))
                let before = commentWords inputSource |> Array.sort
                let after = commentWords formattedSource |> Array.sort
                if before <> after then
                    tally.Add (entry.Corpus + "\tcomments-differ") 1
                    listing.WriteLine (sprintf "%s\tcomments-differ\t%d\t%d" entry.Rel before.Length after.Length)
                else tally.Add (entry.Corpus + "\tcomments-same") 1
                if formatted = original then tally.Add (entry.Corpus + "\tfiles-unchanged") 1
                let again = formatText entry.Path entry.Edition formatted
                if again <> formatted then
                    tally.Add (entry.Corpus + "\tG1-not-idempotent") 1
                    listing.WriteLine (sprintf "%s\tG1-not-idempotent" entry.Rel)
                let flatText = let lines, _ = flatten (lexText entry.Path entry.Edition (joinMacroContinuations text)) in joinLines (Array.ofList lines)
                if formatText entry.Path entry.Edition flatText <> formatted then
                    tally.Add (entry.Corpus + "\tG7-2-format-of-flat-differs") 1
                    listing.WriteLine (sprintf "%s\tG7-2-format-of-flat-differs" entry.Rel)
                else tally.Add (entry.Corpus + "\tG7-2-same") 1
                match compareParses entry.Edition (lexText entry.Path entry.Edition text).FileUnit text formatted with
                | SameParse -> tally.Add (entry.Corpus + "\tparse-same") 1
                | OriginalHasErrors -> tally.Add (entry.Corpus + "\tparse-original-has-errors") 1
                | ParseDiffers line ->
                    tally.Add (entry.Corpus + "\tparse-differs") 1
                    listing.WriteLine (sprintf "%s:%d\tparse-differs" entry.Rel line)
                match outDir with
                | Some dir ->
                    let target = Path.Combine (dir, entry.Corpus, entry.Rel.Replace ('/', Path.DirectorySeparatorChar))
                    Directory.CreateDirectory (Path.GetDirectoryName target) |> ignore
                    File.WriteAllText (target, formatted)
                | None -> ()
            printTally "format" tally
            tally

    module TokensCli =
        let render (text : string) =
            let out = System.Text.StringBuilder()
            let mutable lex = lex_state_init
            text.Replace("\r\n", "\n").Split('\n') |> Array.iteri (fun line lineText ->
                let tokens, _, next = tokenize_line lex lineText
                lex <- next
                for (range, token) in tokens do
                    out.Append(line).Append('\t').Append(range.from).Append('\t').Append(range.nearTo).Append('\t').Append(token_groups token).Append('\n') |> ignore)
            out.ToString()

        let run (args : string list) =
            match args with
            | [ "--stdin" ] -> System.Console.Out.Write(render (System.Console.In.ReadToEnd())); 0
            | [ file ] when System.IO.File.Exists file -> System.Console.Out.Write(render (System.IO.File.ReadAllText file)); 0
            | _ -> eprintfn "usage: SpiralCompiler tokens <file> | tokens --stdin   (one row per token: line, from, nearTo, semantic class)"; 2

    module SplitUnitsCli =
        let definedName (line : string) =
            let m = System.Text.RegularExpressions.Regex.Match(line, @"^:(?:=|~|\||!|==|\+)\s+(?:\^\s+)?([A-Za-z_][\w']*)")
            if m.Success then Some m.Groups.[1].Value else None
        let isFunction (line : string) = line.StartsWith ":= " || line.StartsWith ":~ "
        let blocks (text : string) =
            let lines = text.Replace("\r\n", "\n").TrimEnd('\n').Split('\n')
            let result = ResizeArray<string []>()
            let current = ResizeArray<string>()
            for line in lines do
                if line.Length > 0 && line.[0] = ':' && current.Count > 0 then
                    let mutable cut = current.Count
                    while cut > 0 && (current.[cut - 1].StartsWith "//" || current.[cut - 1].Trim() = "") do cut <- cut - 1
                    let carried = current.GetRange(cut, current.Count - cut).ToArray() |> Array.skipWhile (fun l -> l.Trim() = "")
                    if cut > 0 then result.Add(current.GetRange(0, cut).ToArray())
                    current.Clear()
                    current.AddRange carried
                current.Add line
            if current.Count > 0 then result.Add(current.ToArray())
            result.ToArray()
        let head (block : string []) = block |> Array.tryFind (fun l -> l.Length > 0 && l.[0] = ':') |> Option.defaultValue ""
        let referenced (lines : string seq) =
            let names = System.Collections.Generic.HashSet<string>()
            let mutable lex = lex_state_init
            for line in lines do
                let tokens, _, next = tokenize_line lex line
                lex <- next
                for (_, token) in tokens do
                    match token with
                    | TokVar(name, _) -> names.Add name |> ignore
                    | _ -> ()
            names
        let run (args : string list) =
            match args with
            | [ file; "--list" ] when System.IO.File.Exists file ->
                blocks (System.IO.File.ReadAllText file) |> Array.iteri (fun i b -> printfn "%d\t%s" i (head b |> definedName |> Option.defaultValue "-"))
                0
            | file :: "--cut" :: k :: "--out" :: out :: rest when System.IO.File.Exists file && (match rest with [] | [ "--source"; _ ] -> true | _ -> false) ->
                let forced = System.Collections.Generic.HashSet<string>(match rest with [ _; names ] -> names.Split(',', System.StringSplitOptions.RemoveEmptyEntries) | _ -> [||])
                let all = blocks (System.IO.File.ReadAllText file)
                match System.Int32.TryParse k with
                | true, k when k >= 1 && k < all.Length ->
                    let model, app = all.[.. k - 1], all.[k ..]
                    if model |> Array.exists (fun b -> definedName (head b) = Some "main") then
                        eprintfn "split-units: cut %d leaves main in the model unit; cut before main" k; 2
                    else
                        let used = referenced (app |> Seq.concat)
                        let crossing =
                            let monomorphic (h : string) = not (h.Contains "\\*") && System.Text.RegularExpressions.Regex.IsMatch(h, @"^:[=~]\s+(\^\s+)?[\w']+\s+((\(\)|\([^()]*:[^()]*\))\s*)+:\s*[^=]+=")
                            let macroBody (b : string []) =
                                System.Text.RegularExpressions.Regex.IsMatch(head b, @"=\s*\$""")
                                || (b |> Array.skipWhile (fun l -> not (l.Length > 0 && l.[0] = ':')) |> Array.skip 1 |> Array.tryFind (fun l -> l.Trim() <> "") |> Option.exists (fun l -> l.Trim().StartsWith "$\""))
                            model |> Array.choose (fun b -> let h = head b in if isFunction h then definedName h |> Option.map (fun n -> n, not (monomorphic h) || macroBody b || h.StartsWith ":= ^" || forced.Contains n) else None)
                            |> Array.filter (fun (n, _) -> used.Contains n) |> Array.distinctBy fst
                        let exports = crossing |> Array.filter (fun (_, generic) -> not generic) |> Array.map fst
                        let generics = crossing |> Array.filter snd |> Array.map fst
                        let modelDir = System.IO.Path.Combine(out, "model")
                        let appDir = System.IO.Path.Combine(out, "app")
                        System.IO.Directory.CreateDirectory modelDir |> ignore
                        System.IO.Directory.CreateDirectory appDir |> ignore
                        let body (bs : string [] []) = bs |> Array.map (String.concat "\n") |> String.concat "\n\n"
                        let exportName (n : string) = "model_" + n.Replace("'", "_")
                        let main = exports |> Array.map (fun n -> "    !!!!Export(\"" + exportName n + "\", " + n + ")") |> String.concat "\n"
                        System.IO.File.WriteAllText(System.IO.Path.Combine(modelDir, "model.spi"), body model + "\n\n:= main () : i32 =\n" + (if main = "" then "" else main + "\n") + "    0i32\n")
                        let sourceDir = System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath file)
                        let projPath = System.IO.Path.Combine(sourceDir, "package.spiproj")
                        let projLines = if System.IO.File.Exists projPath then System.IO.File.ReadAllLines projPath else [||]
                        let packages =
                            match projLines |> Array.tryFindIndex (fun l -> l.TrimStart().StartsWith "packages:") with
                            | Some i ->
                                let inline_entries = projLines.[i].Trim().Substring("packages:".Length).Split([| ' '; '\t' |], System.StringSplitOptions.RemoveEmptyEntries)
                                let block = projLines.[i + 1 ..] |> Array.takeWhile (fun l -> l.StartsWith " " || l.StartsWith "\t") |> Array.map (fun l -> l.Trim()) |> Array.filter (fun l -> l <> "")
                                Array.append inline_entries block
                            | None -> [||]
                        let packageDir =
                            projLines |> Array.tryPick (fun l -> if l.StartsWith "packageDir:" then Some (l.Substring("packageDir:".Length).Trim()) else None)
                            |> Option.map (fun d -> "packageDir: " + System.IO.Path.GetFullPath(System.IO.Path.Combine(sourceDir, d)).Replace('\\', '/') + "\n")
                            |> Option.defaultValue ""
                        let packageLines (extra : string list) = match List.ofArray packages @ extra with [] -> "" | ps -> "packages:\n" + (ps |> List.map (fun p -> "    " + p + "\n") |> String.concat "")
                        System.IO.File.WriteAllText(System.IO.Path.Combine(modelDir, "package.spiproj"), packageDir + packageLines [] + "modules:\n    model\n")
                        System.IO.File.WriteAllText(System.IO.Path.Combine(appDir, "main.spi"), ":< model\n\n" + body app + "\n")
                        System.IO.File.WriteAllText(System.IO.Path.Combine(appDir, "package.spiproj"), packageDir + packageLines [ "model-" ] + (if exports.Length = 0 then "" else "link:\n    model-\n") + "modules:\n    main\n")
                        printfn "split %s at %d: model %d blocks, app %d blocks, generics by source %s, exports %s" file k model.Length app.Length (if generics.Length = 0 then "-" else String.concat "," generics) (if exports.Length = 0 then "-" else String.concat "," exports)
                        0
                | _ -> eprintfn "split-units: the cut must be between 1 and %d" (all.Length - 1); 2
            | _ -> eprintfn "usage: SpiralCompiler split-units <file.spi> --list | split-units <file.spi> --cut <k> --out <dir> [--source a,b]   (blocks [0,k) become package model with !!!!Export of every function the rest uses; [k,n) become app linking model)"; 2

    module FormatterCli =
        open System
        open System.IO
        open FormatterLexed
        open FormatterLayout
        open FormatterFormat

        let option name (args : string list) =
            let rec find rest =
                match rest with
                | key :: value :: _ when key = name -> Some value
                | _ :: tail -> find tail
                | [] -> None
            find args

        let positional (args : string list) =
            let rec collect (rest : string list) =
                match rest with
                | key :: _ :: tail when key.StartsWith "--" && key <> "--no-parse" && key <> "--derive" && key <> "--split-literals" && key <> "--no-split-literals" && key <> "--check" && key <> "--stdin" && key <> "--list-sugar" && key <> "--respell-drift" && key <> "--respell" -> collect tail
                | key :: tail when key = "--no-parse" || key = "--derive" || key = "--split-literals" || key = "--no-split-literals" || key = "--check" || key = "--stdin" || key = "--list-sugar" || key = "--respell-drift" || key = "--respell" -> collect tail
                | value :: tail -> value :: collect tail
                | [] -> []
            collect args

        let withListing (path : string option) (action : TextWriter -> 'result) =
            match path with
            | Some file ->
                use writer = new StreamWriter (file, false, Text.UTF8Encoding false)
                writer.NewLine <- "\n"
                action writer
            | None -> action TextWriter.Null

        let onLargeStack (action : unit -> int) =
            let result = ref 0
            let worker = Threading.Thread ((fun () -> result.Value <- action ()), 1 <<< 30)
            worker.Start ()
            worker.Join ()
            result.Value

        let corpusOnThisStack (arguments : string list) : int =
            match arguments with
            | "check" :: rest ->
                let tally = withListing (option "--list" rest) (runCheck (readEntries (positional rest)))
                if corpora (readEntries (positional rest)) |> List.exists (fun name -> tally.Get (name + "\tover120") > 0) then 1 else 0
            | "space" :: rest ->
                withListing (option "--list" rest) (fun writer -> runSpace (readEntries (positional rest)) (option "--out" rest) writer (not (List.contains "--no-parse" rest))) |> ignore
                0
            | "convert" :: rest ->
                withListing (option "--list" rest) (fun writer -> runConvert (readEntries (positional rest)) (option "--out" rest) writer (not (List.contains "--no-parse" rest))) |> ignore
                0
            | "flatten" :: rest ->
                withListing (option "--list" rest) (fun writer -> runFlatten (readEntries (positional rest)) (option "--out" rest) writer) |> ignore
                0
            | "format" :: rest ->
                literalSplitting.Enabled <- List.contains "--split-literals" rest
                withListing (option "--list" rest) (fun writer -> runFormat (readEntries (positional rest)) (option "--out" rest) writer) |> ignore
                0
            | _ ->
                eprintfn "usage: format-corpus check|space|convert|flatten|format [--list file] [--out dir] [--no-parse] [--split-literals] <corpus.tsv|file.spi>..."
                2

        let corpus (arguments : string list) : int = onLargeStack (fun () -> corpusOnThisStack arguments)

        let editionOf (path : string) =
            let rec search (dir : DirectoryInfo) =
                if isNull dir then Edition3
                else
                    let toml = Path.Combine (dir.FullName, "spiral.toml")
                    let project = if File.Exists toml then toml else Path.Combine (dir.FullName, "package.spiproj")
                    if File.Exists project then
                        let declares2 = File.ReadAllLines project |> Array.exists (fun line -> let t = line.Trim().Replace(" ", "").Replace("'", "").Replace("\"", "") in t = "edition:2" || t = "edition=2" || t = "dialect:upstream" || t = "dialect=upstream")
                        if declares2 then Edition2 else Edition3
                    else search dir.Parent
            search (DirectoryInfo (Path.GetDirectoryName (Path.GetFullPath path)))

        let generatedDirectories = set [ "target"; "node_modules"; "deps"; "bin"; "obj"; "_build"; ".git"; ".history" ]

        let rec sourceFilesUnder (directory : string) : string seq =
            seq {
                yield! Directory.EnumerateFiles directory |> Seq.filter (fun file -> file.EndsWith ".spi" || file.EndsWith ".spir")
                for child in Directory.EnumerateDirectories directory do
                    let info = DirectoryInfo child
                    if not (generatedDirectories.Contains info.Name) && not (info.Attributes.HasFlag FileAttributes.ReparsePoint) then
                        yield! sourceFilesUnder child
            }

        let sourceFiles (input : string) =
            if Directory.Exists input then sourceFilesUnder input |> Seq.sort |> List.ofSeq
            else [ input ]

        let formatDegree () =
            match Int32.TryParse (Environment.GetEnvironmentVariable "SPIRAL_FORMAT_PARALLEL") with
            | true, degree when degree > 0 -> degree
            | _ -> max 1 (Environment.ProcessorCount / 2)

        let formatInParallel (files : string[]) (examine : string -> 'outcome) (report : string * 'outcome -> unit) =
            let degree = formatDegree ()
            let chunkSize = max 1 (degree * 4)
            let mutable start = 0
            while start < files.Length do
                let chunk = files.[start .. min files.Length (start + chunkSize) - 1]
                let outcomes : 'outcome[] = Array.zeroCreate chunk.Length
                let next = [| -1 |]
                let work () =
                    let mutable index = Threading.Interlocked.Increment &next.[0]
                    while index < chunk.Length do
                        outcomes.[index] <- examine chunk.[index]
                        index <- Threading.Interlocked.Increment &next.[0]
                let workers = Array.init (min degree chunk.Length) (fun _ -> Threading.Thread ((fun () -> work ()), 256 <<< 20))
                for worker in workers do worker.Start ()
                for worker in workers do worker.Join ()
                Array.iteri (fun index outcome -> report (chunk.[index], outcome)) outcomes
                start <- start + chunkSize

        let rec manifestsUnder (directory : string) : string seq =
            seq {
                let project = Path.Combine (directory, "package.spiproj")
                if File.Exists project then yield project
                for child in Directory.EnumerateDirectories directory do
                    let info = DirectoryInfo child
                    if not (generatedDirectories.Contains info.Name) && not (info.Attributes.HasFlag FileAttributes.ReparsePoint) then
                        yield! manifestsUnder child
            }

        let tomlOfSpiproj (text : string) : Result<string, string> =
            let lines = text.Replace("\r\n", "\n").TrimEnd('\n').Split '\n'
            let out = ResizeArray<string> ()
            let mutable problem = None
            let quoted (value : string) =
                if value.Contains "'" then problem <- Some (sprintf "a value holds a quote: %s" value)
                "'" + value + "'"
            let mutable i = 0
            while i < lines.Length do
                let line = lines.[i]
                if line.Trim () = "" then i <- i + 1
                else
                    let colon = line.IndexOf ':'
                    let key = if colon > 0 then line.Substring(0, colon).Trim () else line.Trim ()
                    let value = if colon > 0 then line.Substring(colon + 1).Trim () else ""
                    i <- i + 1
                    let body = ResizeArray<string> ()
                    while i < lines.Length && (lines.[i] = "" || Char.IsWhiteSpace lines.[i].[0]) do
                        body.Add lines.[i]
                        i <- i + 1
                    while body.Count > 0 && body.[body.Count - 1].Trim () = "" do body.RemoveAt (body.Count - 1)
                    if key = "modules" then
                        out.Add "modules = '''"
                        if value <> "" then out.Add value
                        for b in body do out.Add (if b.StartsWith "    " then b.Substring 4 else b.TrimStart ())
                        out.Add "'''"
                    elif key = "packages" || key = "crates" then
                        out.Add (key + " = [" + (Seq.append (value.Split (' ', StringSplitOptions.RemoveEmptyEntries)) (body |> Seq.map (fun b -> b.Trim ())) |> Seq.filter (fun b -> b <> "") |> Seq.map quoted |> String.concat ", ") + "]")
                    elif value <> "" && value |> Seq.forall Char.IsDigit then out.Add (key + " = " + value)
                    else out.Add (key + " = " + quoted value)
            match problem with
            | Some reason -> Error reason
            | None -> Ok (String.concat "\n" out + "\n")

        let moduleEntries (spiproj : string) : string list =
            let lines = spiproj.Replace("\r\n", "\n").Split '\n'
            match lines |> Array.tryFindIndex (fun line -> line.TrimEnd () = "modules:") with
            | None -> []
            | Some start ->
                let entries = ResizeArray<string> ()
                let mutable dirs : (int * string) list = []
                let mutable i = start + 1
                while i < lines.Length && (lines.[i] = "" || Char.IsWhiteSpace lines.[i].[0]) do
                    let line = lines.[i]
                    if line.Trim () <> "" then
                        let indent = line.Length - line.TrimStart().Length
                        let entry = line.Trim ()
                        dirs <- dirs |> List.filter (fun (level, _) -> level < indent)
                        if entry.EndsWith "/" then dirs <- dirs @ [ indent, entry ]
                        else entries.Add ((dirs |> List.map snd |> String.concat "") + entry)
                    i <- i + 1
                List.ofSeq entries

        let derivedTomlOfSpiproj (original : string) (toml : string) : string =
            let prelude =
                moduleEntries original
                |> List.filter (fun entry -> entry.EndsWith "-")
                |> List.map (fun entry -> let name = entry.TrimEnd('-').TrimEnd('*') in name.Substring (name.LastIndexOf '/' + 1))
            let start = toml.IndexOf "modules = '''"
            if start < 0 then toml
            else
                let close = toml.IndexOf ("'''", start + 13) + 3
                let line = if prelude.IsEmpty then "" else "prelude = [" + (prelude |> List.map (fun name -> "\"" + name + "\"") |> String.concat ", ") + "]\n"
                toml.Substring (0, start) + line + toml.Substring(close).TrimStart('\n')

        let manifestToml (arguments : string list) : int =
            let significant (text : string) =
                text.Replace("\r\n", "\n").Split '\n'
                |> Array.collect (fun line ->
                    let key = if line.IndexOf ':' > 0 then line.Substring(0, line.IndexOf ':') else ""
                    let value = if key = "" then "" else line.Substring(key.Length + 1).Trim ()
                    if value <> "" && (key = "packages" || key = "crates") then Array.append [| key + ":" |] (value.Split (' ', StringSplitOptions.RemoveEmptyEntries) |> Array.map (fun item -> "    " + item))
                    elif value <> "" && key = "modules" then [| "modules:"; "    " + value |]
                    else [| line |])
                |> Array.map (fun line -> line.TrimEnd ())
                |> Array.filter (fun line -> line <> "")
            let derive = List.contains "--derive" arguments
            let mutable failures = 0
            for directory in positional arguments do
                for project in manifestsUnder directory |> Seq.sort do
                    let target = Path.Combine (Path.GetDirectoryName project, "spiral.toml")
                    if File.Exists target then printfn "kept: %s" target
                    else
                        let original = File.ReadAllText project
                        match tomlOfSpiproj original with
                        | Error reason ->
                            failures <- failures + 1
                            eprintfn "manifest error: %s: %s" project reason
                        | Ok toml when derive ->
                            let derived = derivedTomlOfSpiproj original toml
                            match withDerivedModules (Path.GetDirectoryName project) derived with
                            | Error reason ->
                                failures <- failures + 1
                                eprintfn "manifest error: %s: %s" project reason
                            | Ok resolved when Set.ofList (moduleEntries (tomlManifestText resolved)) <> Set.ofList (moduleEntries original) ->
                                failures <- failures + 1
                                eprintfn "manifest error: %s: the derived modules are not the listed ones" project
                            | Ok _ ->
                                File.WriteAllText (target, derived)
                                printfn "wrote: %s (module list derived)" target
                        | Ok toml when significant (tomlManifestText toml) <> significant original ->
                            failures <- failures + 1
                            eprintfn "manifest error: %s: the spiral.toml would not read back as this manifest" project
                        | Ok toml ->
                            File.WriteAllText (target, toml)
                            printfn "wrote: %s" target
            if failures > 0 then 2 else 0

        let runOnThisStack (arguments : string list) : int =
            literalSplitting.Enabled <- not (List.contains "--no-split-literals" arguments)
            if option "--manifest" arguments = Some "toml" then manifestToml arguments
            elif List.contains "--stdin" arguments then
                let path = defaultArg (option "--path" arguments) "stdin.spi"
                use input = new StreamReader (Console.OpenStandardInput (), Text.UTF8Encoding false)
                let text = input.ReadToEnd().Replace ("\r\n", "\n")
                let bytes = (Text.UTF8Encoding false).GetBytes (formatText path (editionOf path) text)
                use output = Console.OpenStandardOutput ()
                output.Write (bytes, 0, bytes.Length)
                0
            else
                let check = List.contains "--check" arguments
                let listSugar = List.contains "--list-sugar" arguments
                let listSugarFindings = ref 0
                let listSugarLint (file : string) (text : string) =
                    [ for line in (lexText file (editionOf file) text).SourceLines do
                        match line.Shape with
                        | Code (_, lexemes, _) ->
                            for index in 0 .. lexemes.Length - 1 do
                                let lexeme = lexemes.[index]
                                let typeApplied = index + 1 < lexemes.Length && lexemes.[index + 1].Text.Text.StartsWith "`"
                                match lexeme.Token with
                                | TokVar ("Nil", _) when not lexeme.InsideMacro && not typeApplied -> yield line.Number, lexeme.Span.From + 1, "list-nil (write [] for the empty list)"
                                | TokVar ("Cons", _) when not lexeme.InsideMacro -> yield line.Number, lexeme.Span.From + 1, "list-cons (write head :: tail)"
                                | _ -> ()
                        | _ -> () ]
                let respellDrift = List.contains "--respell-drift" arguments
                let respellDriftFindings = ref 0
                let respellDriftLint (file : string) (text : string) =
                    [ match editionOf file with
                      | Edition3 ->
                        let lexed = lexText file Edition3 text
                        let converted, _, _ = FormatterConvert.convert FormatterConvert.Symbols lexed
                        let converted = Seq.toArray converted
                        let original = text.Split '\n'
                        let respelled (number : int) = number >= 1 && number <= converted.Length && number <= original.Length && converted.[number - 1] <> original.[number - 1]
                        for line in lexed.SourceLines do
                            match line.Shape with
                            | Code (_, lexemes, _) when respelled line.Number ->
                                for lexeme in lexemes do
                                    match FormatterConvert.respell FormatterConvert.Symbols lexeme with
                                    | Some spelled -> yield line.Number, lexeme.Span.From + 1, $"respell-drift (write {spelled} for {lexeme.Text.Text})"
                                    | None -> ()
                            | _ -> ()
                      | _ -> () ]
                let respellAndFormat = List.contains "--respell" arguments
                let spelling =
                    match option "--spelling" arguments with
                    | Some "symbols" -> Some FormatterConvert.Symbols
                    | Some "words" -> Some FormatterConvert.Words
                    | _ when respellAndFormat -> Some FormatterConvert.Symbols
                    | _ -> None
                let changed = ResizeArray<string> ()
                let failed = ref 0
                let optsOutOfRespell (text : string) =
                    text.Split '\n'
                    |> Seq.map (fun line -> line.Trim ())
                    |> Seq.takeWhile (fun line -> line = "" || line.StartsWith "//")
                    |> Seq.exists (fun line -> line.StartsWith "///-" && Array.contains "--no-respell" (line.Split ' '))
                let examine (file : string) =
                    try
                        if File.Exists file then
                            let text = File.ReadAllText(file).Replace ("\r\n", "\n")
                            match spelling with
                            | Some _ when optsOutOfRespell text -> Ok (Some (text, text))
                            | Some target ->
                                let lines, converted, _ = FormatterConvert.convert target (lexText file (editionOf file) text)
                                let spelled = if converted = 0 then text else joinLines lines
                                Ok (Some (text, (if respellAndFormat then formatText file (editionOf file) spelled else spelled)))
                            | None -> Ok (Some (text, formatText file (editionOf file) text))
                        else Ok None
                    with error -> Error error.Message
                let report (file : string, outcome : Result<(string * string) option, string>) =
                    match outcome with
                    | Ok None -> printfn "vanished: %s" file
                    | Ok (Some (text, formatted)) ->
                        if formatted <> text then
                            changed.Add file
                            if not check then File.WriteAllText (file, formatted)
                            printfn "%s %s" (if check then "would change:" else "formatted:") file
                        if check then
                            formatted.Split '\n' |> Array.iteri (fun index line -> let width = displayWidth line in if width > 120 then printfn "%s:%d:121: over-120 (%d columns)" file (index + 1) width)
                        if listSugar then
                            for number, column, finding in listSugarLint file text do
                                listSugarFindings.Value <- listSugarFindings.Value + 1
                                printfn "%s:%d:%d: %s" file number column finding
                        if respellDrift && not (optsOutOfRespell text) then
                            for number, column, finding in respellDriftLint file text do
                                respellDriftFindings.Value <- respellDriftFindings.Value + 1
                                printfn "%s:%d:%d: %s" file number column finding
                    | Error message ->
                        failed.Value <- failed.Value + 1
                        eprintfn "format error: %s: %s" file message
                formatInParallel (positional arguments |> List.collect sourceFiles |> Array.ofList) examine report
                if failed.Value > 0 then 2 elif check && changed.Count > 0 then 1 elif listSugar && listSugarFindings.Value > 0 then 1 elif respellDrift && respellDriftFindings.Value > 0 then 1 else 0

        let run (arguments : string list) : int = onLargeStack (fun () -> runOnThisStack arguments)

    /// ## GraphIdentity
    type GraphPathId = string
    module GraphPathIdOps =
        let create (value : string) : GraphPathId = value
        let text (value : GraphPathId) : string = value
    type SchemaPathId = string
    module SchemaPathIdOps =
        let create (value : string) : SchemaPathId = value
        let text (value : SchemaPathId) : string = value
    type ModulePathId = string
    module ModulePathIdOps =
        let create (value : string) : ModulePathId = value
        let text (value : ModulePathId) : string = value
    type ProjectionPathId = string
    module ProjectionPathIdOps =
        let create (value : string) : ProjectionPathId = value
        let text (value : ProjectionPathId) : string = value
    type PackagePathIndex = Map<SchemaPathId,PackageId>
    type PackagePathReverseIndex = Map<PackageId,SchemaPathId>
    type PackagePathBiIndex = PackagePathIndex * PackagePathReverseIndex
    /// ## Graph
    open System.Collections.Generic
    


    /// ### Graph
    type Graph = Map<GraphPathId,GraphPathId Set>
    

    /// ### MirroredGraph
    type MirroredGraph = Graph * Graph
    

    /// ### mirrored_graph_empty
    let mirrored_graph_empty : MirroredGraph = Map.empty, Map.empty
    

    /// ### link_add'
    let link_add' (abs : Graph) a b: Graph =
        match Map.tryFind a abs with
        | Some bs -> Map.add a (Set.add b bs) abs
        | None -> Map.add a (Set.singleton b) abs
    

    /// ### link_add
    let link_add (s : MirroredGraph) a b: MirroredGraph = link_add' (fst s) a b, link_add' (snd s) b a
    

    /// ### link_remove'
    let link_remove' (abs : Graph) a b =
        match Map.tryFind a abs with
        | Some bs ->
            let bs = Set.remove b bs
            if Set.isEmpty bs then Map.remove a abs else Map.add a bs abs
        | None -> abs
    

    /// ### link_remove
    let link_remove (s : MirroredGraph) a b: MirroredGraph = link_remove' (fst s) a b, link_remove' (snd s) b a
    

    /// ### links_remove
    let links_remove ((abs,bas as s) : MirroredGraph) a: MirroredGraph =
        match Map.tryFind a abs with
        | Some bs -> Map.remove a abs, Set.fold (fun bas b -> link_remove' bas b a) bas bs
        | None -> s
    

    /// ### links_add
    let links_add s a bs = List.fold (fun s b -> link_add s a b) s bs
    

    /// ### links_replace
    let links_replace (s : MirroredGraph) a bs = links_add (links_remove s a) a bs
    

    /// ### links_get
    let links_get (abs : Graph) a = Map.tryFind a abs |> Option.defaultValue Set.empty
    

    /// ### link_exists
    let link_exists ((abs,bas) : MirroredGraph) x = Map.containsKey x abs || Map.containsKey x bas




    

    /// ### topological_sort_template
    let topological_sort_template add bas dirty_nodes =
        let sort_visited = HashSet()
        let rec dfs_rev a = if sort_visited.Add(a) then Seq.iter dfs_rev (links_get bas a); add a
        Seq.iter dfs_rev dirty_nodes
        sort_visited
    

    /// ### topological_sort'
    // Returns the order end -> mid -> start.
    let topological_sort' bas start_nodes = let sort_order = Queue() in sort_order, topological_sort_template sort_order.Enqueue bas start_nodes
    

    /// ### topological_sort
    // Returns the order start -> mid -> end.
    let topological_sort bas start_nodes = let sort_order = Stack() in sort_order, topological_sort_template sort_order.Push bas start_nodes
    

    /// ### circular_nodes
    let circular_nodes ((abs,bas) : MirroredGraph) dirty_nodes =
        let dirtyNodeIds = dirty_nodes |> Seq.map GraphPathIdOps.create
        let sort_order, sort_visited = topological_sort bas dirtyNodeIds
        let orderIds = sort_order.ToArray()
        let visited = HashSet()
        let circularNodes = Dictionary<SchemaPathId,int>()
        Array.fold (fun i a ->
            let sc = ResizeArray() // This array stores the strongly connected components.
            let rec dfs a = if sort_visited.Contains(a) && visited.Add(a) then Seq.iter dfs (links_get abs a); sc.Add a
            dfs a
            if 1 < sc.Count then
                sc
                |> Seq.iter (fun x ->
                    x
                    |> GraphPathIdOps.text
                    |> SchemaPathIdOps.create
                    |> fun pathId -> circularNodes.Add(pathId,i) |> ignore)
                i+1
            else
                i
            ) 0 orderIds |> ignore
        orderIds |> Array.map GraphPathIdOps.text, circularNodes
    

    /// ## OutputFiles

    /// ### write_output_atomically_async
    let write_output_atomically_async (path : string) (text : string) = async {
        let staged = path + ".tmp"
        do! System.IO.File.WriteAllTextAsync(staged, text) |> Async.AwaitTask
        System.IO.File.Move(staged, path, true)
        }

    /// ## ServerUtils
    // open System
    open System.IO
    open System.Collections.Generic
    

    open Microsoft.FSharp.Core
    

    // open Common
    

    /// ### ProjectCodeAction
    type ProjectCodeAction =
        | CreateFile of {|filePath : string|}
        | DeleteFile of {|range: VSCRange; filePath : string|} // The range here includes the postfix operators.
        | RenameFile of {|filePath : string; target : string|}
        | CreateDirectory of {|dirPath : string|}
        | DeleteDirectory of {|range: VSCRange; dirPath : string|} // The range here is for the whole tree, not just the code action activation.
        | RenameDirectory of {|dirPath : string; target : string; validate_as_file : bool|}
    

    /// ### code_action_execute
    let code_action_execute a =
        try match a with
            | CreateDirectory a -> Directory.CreateDirectory(a.dirPath) |> ignore; Ok null
            | DeleteDirectory a -> Directory.Delete(a.dirPath,true); Ok a.dirPath
            | RenameDirectory a ->
                if a.validate_as_file then
                    match FParsec.CharParsers.run file_verify a.target with
                    | FParsec.CharParsers.ParserResult.Success _ -> Directory.Move(a.dirPath,Path.Combine(a.dirPath,"..",a.target)); Ok a.dirPath
                    | FParsec.CharParsers.ParserResult.Failure(er,_,_) -> Error er
                else
                    Directory.Move(a.dirPath,Path.Combine(a.dirPath,"..",a.target)); Ok a.dirPath
            | CreateFile a ->
                if File.Exists(a.filePath) then Error "File already exists."
                else
                    Directory.GetParent(a.filePath).Create()
                    File.Create(a.filePath).Dispose()
                    Ok null
            | DeleteFile a -> File.Delete(a.filePath); Ok a.filePath
            | RenameFile a ->
                match FParsec.CharParsers.run file_verify a.target with
                | FParsec.CharParsers.ParserResult.Success _ -> File.Move(a.filePath,Path.Combine(a.filePath,"..",a.target+Path.GetExtension(a.filePath)),false); Ok a.filePath
                | FParsec.CharParsers.ParserResult.Failure(er,_,_) -> Error er
        with e -> Error e.Message
    

    /// ### RAction
    type RAction = VSCRange * ProjectCodeAction
    

    /// ### SchemaState
    type SchemaState = { schema : Schema; errors_parse : RString list; errors_modules : RString list; errors_packages : RString list}
    

    /// ### SchemaEnv
    type SchemaEnv = Map<SchemaPathId,SchemaState>

    module SchemaEnv =
        let tryFindText path (env:SchemaEnv) = Map.tryFind (SchemaPathIdOps.create path) env
        let containsText path (env:SchemaEnv) = Map.containsKey (SchemaPathIdOps.create path) env
        let addText path value (env:SchemaEnv) = Map.add (SchemaPathIdOps.create path) value env
        let removeText path (env:SchemaEnv) = Map.remove (SchemaPathIdOps.create path) env
        let keysText (env:SchemaEnv) = env |> Map.toSeq |> Seq.map (fst >> SchemaPathIdOps.text)
    

    /// ### ModuleEnv
    type ModuleEnv = Map<ModulePathId,ModuleState>

    module ModuleEnv =
        let tryFindText path (env:ModuleEnv) = Map.tryFind (ModulePathIdOps.create path) env
        let containsText path (env:ModuleEnv) = Map.containsKey (ModulePathIdOps.create path) env
        let addText path value (env:ModuleEnv) = Map.add (ModulePathIdOps.create path) value env
        let removeText path (env:ModuleEnv) = Map.remove (ModulePathIdOps.create path) env
        let keysText (env:ModuleEnv) = env |> Map.toSeq |> Seq.map (fst >> ModulePathIdOps.text)
    

    /// ### ss_empty
    let ss_empty = {
        schema = {moduleDir = None, null; modules = []; packageDir = None, null; packages = []; link = []; defaultInt = None; defaultFloat = None; edition = None; rustExtern = []; autoExport = None}
        errors_parse = []; errors_modules = []; errors_packages = []
        }
    

    /// ### ss_from_result
    let ss_from_result = function
        | Ok schema -> {ss_empty with schema = schema}
        | Error ers -> {ss_empty with errors_parse = ers}
    

    /// ### ss_validate_module
    let ss_validate_module (packages : SchemaEnv) (modules : ModuleEnv) (x : SchemaState) =
        let errors = ResizeArray()
        let rec loop = function
            | FileHierarchy.Directory(_,(r,path),_,l) ->
                trace Verbose (fun () -> $"ss_validate_module / dir path: {path}") _locals
                if SchemaEnv.containsText path packages then errors.Add(r,"Module directory has a package file in it.")
                list l
            | FileHierarchy.File(_,(r,path),_) ->
                let path' = path |> SpiralFileSystem.standardize_path
                trace Verbose (fun () -> $"ss_validate_module / file / path: {path} / path': {path'}") _locals
                if ModuleEnv.containsText path' modules = false then errors.Add(r,$"Module {path'} is not loaded.")
        and list l = List.iter loop l
        list x.schema.modules
        Seq.toList errors
    

    /// ### ss_validate_modules
    let ss_validate_modules (packages : SchemaEnv) modules order =
        Array.fold (fun s x ->
            match SchemaEnv.tryFindText x s with
            | Some v -> SchemaEnv.addText x ({v with errors_modules = ss_validate_module packages modules v} : SchemaState) s
            | None -> s
            ) packages order
    

    /// ### ss_has_error
    let ss_has_error x =
        (List.isEmpty x.errors_parse && List.isEmpty x.errors_modules && List.isEmpty x.errors_packages) = false

    /// ### package_default_env
    let package_default_env (default_env : DefaultEnv) (schema : SchemaState) : DefaultEnv =
        let env =
            match schema.schema.defaultInt with
            | Some "i8" -> {default_env with default_int = Int8T; default_uint = UInt8T}
            | Some "i16" -> {default_env with default_int = Int16T; default_uint = UInt16T}
            | Some "i32" -> {default_env with default_int = Int32T; default_uint = UInt32T}
            | Some "i64" -> {default_env with default_int = Int64T; default_uint = UInt64T}
            | Some "u8" -> {default_env with default_int = UInt8T; default_uint = UInt8T}
            | Some "u16" -> {default_env with default_int = UInt16T; default_uint = UInt16T}
            | Some "u32" -> {default_env with default_int = UInt32T; default_uint = UInt32T}
            | Some "u64" -> {default_env with default_int = UInt64T; default_uint = UInt64T}
            | _ -> default_env
        let env =
            match schema.schema.defaultFloat with
            | Some "f32" -> {env with default_float = Float32T}
            | Some "f64" -> {env with default_float = Float64T}
            | _ -> env
        match schema.schema.edition with
        | Some ("2" | "upstream") -> {env with edition = UpstreamEdition2}
        | Some ("3" | "i574n") -> {env with edition = ForkEdition3}
        | _ -> env

    /// ### file_default_env
    let file_default_env (default_env : DefaultEnv) (packages : SchemaEnv) (file : string) : DefaultEnv =
        let rec owner (dir : string) =
            if System.String.IsNullOrEmpty dir then default_env
            else
                match SchemaEnv.tryFindText (SpiralFileSystem.standardize_path dir) packages with
                | Some schema -> package_default_env default_env schema
                | None -> owner (System.IO.Path.GetDirectoryName dir)
        let env = owner (System.IO.Path.GetDirectoryName file)
        match test_entry_selection with
        | Some (path, name) when path = file -> { env with test_entry = Some name }
        | _ -> env

    /// ### file_rust_extern
    let file_rust_extern (packages : SchemaEnv) (file : string) =
        let rec owner (dir : string) =
            if System.String.IsNullOrEmpty dir then []
            else
                match SchemaEnv.tryFindText (SpiralFileSystem.standardize_path dir) packages with
                | Some schema -> schema.schema.rustExtern
                | None -> owner (System.IO.Path.GetDirectoryName dir)
        owner (System.IO.Path.GetDirectoryName file)
    

    /// ### file_auto_export
    let file_auto_export (packages : SchemaEnv) (file : string) =
        let rec owner (dir : string) =
            if System.String.IsNullOrEmpty dir then None
            else
                match SchemaEnv.tryFindText (SpiralFileSystem.standardize_path dir) packages with
                | Some schema -> schema.schema.autoExport
                | None -> owner (System.IO.Path.GetDirectoryName dir)
        owner (System.IO.Path.GetDirectoryName file)

    /// ### LinkAutoExport
    module LinkAutoExport =
        let trace = System.Environment.GetEnvironmentVariable "SPIRAL_AUTO_EXPORT_TRACE" = "1"
        let rec candidate (annotated : bool) (e : E) =
            match e with
            | EAnnot(_, a, _) -> candidate true a
            | EFun'(_, _, _, body, t) -> (annotated || t.IsSome) && (match body with EFun' _ | EForall' _ -> false | _ -> true)
            | _ -> false
        let shape (e : E) = match e with EAnnot(_, EFun' _, _) -> "annot-fun" | EFun' _ -> "fun" | EAnnot _ -> "annot-other" | _ -> "other"
        let main (unit : string) (own : Map<string, E>) (main : E) =
            let exports = own |> Map.toList |> List.filter (fun (name, e) -> name <> "main" && candidate false e)
            if trace then
                let shapes = own |> Map.toList |> List.map (fun (name, e) -> $"{name}:{shape e}") |> String.concat " "
                eprintfn "auto-export: unit %s own %d [%s] candidates [%s] main %s" unit own.Count shapes (exports |> List.map fst |> String.concat " ") (shape main)
            let inject (r : Range) (body : E) = List.foldBack (fun (name, e) acc -> ESeq(r, EOp(r, Export, [ELit(r, LitString $"{unit}_{name}"); e]), acc)) exports body
            match main with
            | _ when exports.IsEmpty -> main
            | EAnnot(r, EFun'(r2, scope, id, body, t), ty) -> EAnnot(r, EFun'(r2, scope, id, inject r body, t), ty)
            | EFun'(r, scope, id, body, t) -> EFun'(r, scope, id, inject r body, t)
            | _ -> main

    /// ### readUnitGraph
    /// The unions a built unit exports, from its `<stem>.unit.json` graphs (unitGraphDir of its package folder); None until
    /// it is built.
    module RustLinkedShapes =
        let private decl = System.Text.RegularExpressions.Regex(@"(?m)^(?:pub )?struct (\w+) \{(?= (?:pub )?l0: )(.*)\}\r?$")
        let private word = System.Text.RegularExpressions.Regex(@"\b\w+\b")
        let private hash (text : string) = System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes text) |> Array.take 6 |> Array.map (fun b -> b.ToString "x2") |> String.concat ""
        let shapes (code : string) =
            let decls = decl.Matches code |> Seq.map (fun m -> m.Groups.[1].Value, m.Groups.[2].Value.Replace("pub ", "")) |> Array.ofSeq
            let initial = Dictionary<string, string>()
            for (n, _) in decls do initial.[n] <- "T"
            let current = ref initial
            for _ in 1 .. 6 do
                let next = Dictionary<string, string>()
                for (n, fields) in decls do
                    next.[n] <- hash (word.Replace(fields, fun (w : System.Text.RegularExpressions.Match) -> match current.Value.TryGetValue w.Value with | true, h -> "S" + h | _ -> w.Value))
                current.Value <- next
            current.Value
        let read (dir : string) =
            (try System.IO.Directory.GetFiles(unitGraphDir dir, "*.rust-shapes.json") with _ -> [||])
            |> Array.collect (fun f -> System.Text.Json.JsonSerializer.Deserialize<string []>(System.IO.File.ReadAllText f))
            |> Set.ofArray
        let import (linked : Map<int, LinkedUnit>) (code : string) =
            if linked.IsEmpty then code
            else
                let owners = linked |> Map.toList |> List.collect (fun (_, l) -> l.shapes |> Set.toList |> List.map (fun h -> h, l.unit)) |> List.distinctBy fst |> Map.ofList
                let candidates = shapes code |> Seq.choose (fun kv -> owners |> Map.tryFind kv.Value |> Option.map (fun unit -> kv.Key, kv.Value, unit)) |> Array.ofSeq
                let fieldsOf = decl.Matches code |> Seq.map (fun m -> m.Groups.[1].Value, m.Groups.[2].Value) |> Seq.distinctBy fst |> dict
                let localTypes = System.Text.RegularExpressions.Regex(@"(?m)^(?:pub )?(?:enum|struct|type|union) (\w+)").Matches code |> Seq.map (fun m -> m.Groups.[1].Value) |> Set.ofSeq
                let rec settle (kept : (string * string * string) []) =
                    let names = kept |> Array.map (fun (n, _, _) -> n) |> Set.ofArray
                    let closed (n, _, _) =
                        match fieldsOf.TryGetValue n with
                        | true, fields -> word.Matches fields |> Seq.forall (fun w -> w.Value = n || names.Contains w.Value || not (localTypes.Contains w.Value))
                        | _ -> false
                    let next = kept |> Array.filter closed
                    if next.Length = kept.Length then kept else settle next
                let taken = settle candidates
                if taken.Length = 0 then code
                else
                    let dropped =
                        taken |> Array.fold (fun (code : string) (name, _, _) ->
                            [ $@"(?m)^#\[derive\([^\]]*\)\]\r?\n(?=(pub )?struct {name} \{{)"
                              $@"(?m)^(pub )?struct {name} \{{.*\}}\r?\n"
                              $@"(?ms)^impl Default for {name} \{{\r?\n.*?^\}}\r?\n" ]
                            |> List.fold (fun (code : string) pattern -> System.Text.RegularExpressions.Regex.Replace(code, pattern, "")) code) code
                    dropped + (taken |> Array.map (fun (name, h, unit) -> $"use {unit}::SpiralShape_{h} as {name};\n") |> String.concat "")
        let export (code : string) =
            if not (System.Text.RegularExpressions.Regex.IsMatch(code, @"(?m)^pub fn ")) then code, [||]
            else
                let distinct = shapes code |> Seq.map (fun kv -> kv.Key, kv.Value) |> Seq.distinctBy snd |> Array.ofSeq
                let field = System.Text.RegularExpressions.Regex(@"(?<=^ |, )(?=l\d+: )")
                let opened = decl.Replace(code, fun (m : System.Text.RegularExpressions.Match) -> "pub struct " + m.Groups.[1].Value + " {" + field.Replace(m.Groups.[2].Value, "pub ") + "}")
                opened + (distinct |> Array.map (fun (name, h) -> $"pub type SpiralShape_{h} = {name};\n") |> String.concat ""), distinct |> Array.map snd
        let write (packageDir : string) (source : string) (hashes : string []) =
            let path = System.IO.Path.Combine(unitGraphDir packageDir, System.IO.Path.GetFileNameWithoutExtension source + ".rust-shapes.json")
            if hashes.Length = 0 then (if System.IO.File.Exists path then System.IO.File.Delete path)
            else
                let json = System.Text.Json.JsonSerializer.Serialize hashes
                if not (System.IO.File.Exists path && System.IO.File.ReadAllText path = json) then
                    System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName path) |> ignore
                    System.IO.File.WriteAllText(path, json)

    module GleamLinkedPrelude =
        let private preludes = [ "SpiralArray", "SpiralArrayStore"; "SpiralRef", "SpiralRefCell" ]
        let private declares (code : string) (name : string) = code.Contains $"pub type {name}(a) {{"
        let read (dir : string) =
            (try System.IO.Directory.GetFiles(unitGraphDir dir, "*.gleam-prelude.json") with _ -> [||])
            |> Array.collect (fun f -> System.Text.Json.JsonSerializer.Deserialize<string []>(System.IO.File.ReadAllText f))
            |> Set.ofArray
        let write (packageDir : string) (source : string) (code : string) =
            let stem = System.IO.Path.GetFileNameWithoutExtension source
            let path = System.IO.Path.Combine(unitGraphDir packageDir, stem + ".gleam-prelude.json")
            let graph = System.IO.Path.Combine(unitGraphDir packageDir, stem + ".unit.json")
            let names = if System.IO.File.Exists graph then preludes |> List.filter (fun (name, _) -> declares code name) |> List.map (fun (name, _) -> "gleam:" + name) |> Array.ofList else [||]
            if names.Length = 0 then (if System.IO.File.Exists path then System.IO.File.Delete path)
            else
                let json = System.Text.Json.JsonSerializer.Serialize names
                if not (System.IO.File.Exists path && System.IO.File.ReadAllText path = json) then
                    System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName path) |> ignore
                    System.IO.File.WriteAllText(path, json)
        let import (linked : Map<int, LinkedUnit>) (code : string) =
            if linked.IsEmpty then code
            else
                let owner (name : string) = linked |> Map.toList |> List.tryPick (fun (_, l) -> if l.shapes.Contains ("gleam:" + name) then Some l.unit else None)
                let taken = preludes |> List.choose (fun (name, store) -> if declares code name then owner name |> Option.map (fun unit -> unit, name, store) else None)
                if taken.IsEmpty then code
                else
                    let dropped =
                        taken |> List.fold (fun (code : string) (_, name, store) ->
                            let code = System.Text.RegularExpressions.Regex.Replace(code, $@"(?m)^pub type {store}\(a\)\r?\n(\r?\n)?", "")
                            System.Text.RegularExpressions.Regex.Replace(code, $@"(?ms)^pub type {name}\(a\) \{{\r?\n.*?^\}}\r?\n(\r?\n)?", "")) code
                    taken |> List.groupBy (fun (unit, _, _) -> unit) |> List.fold (fun (code : string) (unit, items) ->
                        let names = items |> List.collect (fun (_, name, store) -> [ $"type {name}"; name; $"type {store}" ])
                        let line = System.Text.RegularExpressions.Regex($@"(?m)^import {System.Text.RegularExpressions.Regex.Escape unit}(\.\{{(.*)\}})?\r?$")
                        let m = line.Match code
                        if m.Success then
                            let existing = if m.Groups.[2].Success then m.Groups.[2].Value.Split(',') |> Array.map (fun s -> s.Trim()) |> Array.filter (fun s -> s <> "") |> List.ofArray else []
                            code.Remove(m.Index, m.Length).Insert(m.Index, $"""import {unit}.{{{existing @ names |> List.distinct |> String.concat ", "}}}""")
                        else $"""import {unit}.{{{names |> String.concat ", "}}}""" + "\n" + code) dropped

    let readUnitGraph (dir : string) : Map<string * string, string> option =
        match (try System.IO.Directory.GetFiles(unitGraphDir dir, "*.unit.json") with _ -> [||]) with
        | [||] -> None
        | files ->
            files
            |> Array.collect (fun file ->
                use graph = System.Text.Json.JsonDocument.Parse(System.IO.File.ReadAllText file)
                [| for u in graph.RootElement.GetProperty("unions").EnumerateArray() -> (u.GetProperty("source").GetString(), u.GetProperty("shape").GetString()), u.GetProperty("name").GetString() |])
            |> Map.ofArray
            |> Some

    /// ### readUnitCalls
    /// The exported definitions of a built unit, (file, name) -> export name, from its unit graphs; empty until it is built.
    let readUnitCalls (dir : string) : Map<string * string, string> =
        (try System.IO.Directory.GetFiles(unitGraphDir dir, "*.unit.json") with _ -> [||])
        |> Array.collect (fun file ->
            use graph = System.Text.Json.JsonDocument.Parse(System.IO.File.ReadAllText file)
            [| for e in graph.RootElement.GetProperty("exports").EnumerateArray() do
                match e.TryGetProperty "target_path", e.TryGetProperty "target_name" with
                | (true, p), (true, n) when p.GetString() <> "" && n.GetString() <> "" -> yield (p.GetString(), n.GetString()), e.GetProperty("name").GetString()
                | _ -> () |])
        |> Map.ofArray

    /// ### readUnitWraps
    let readUnitWraps (dir : string) : Map<string * string, string> =
        (try System.IO.Directory.GetFiles(unitGraphDir dir, "*.unit.json") with _ -> [||])
        |> Array.collect (fun file ->
            use graph = System.Text.Json.JsonDocument.Parse(System.IO.File.ReadAllText file)
            match graph.RootElement.TryGetProperty "wraps" with
            | true, rows -> [| for w in rows.EnumerateArray() -> (w.GetProperty("path").GetString(), w.GetProperty("name").GetString()), w.GetProperty("export").GetString() |]
            | _ -> [||])
        |> Map.ofArray

    /// ### file_package_dir
    /// The folder of the package that owns the file (its nearest package.spiproj / spiral.toml in the schema env).
    let file_package_dir (packages : SchemaEnv) (file : string) =
        let rec owner (dir : string) =
            if System.String.IsNullOrEmpty dir then System.IO.Path.GetDirectoryName file
            else
                let standardized = SpiralFileSystem.standardize_path dir
                match SchemaEnv.tryFindText standardized packages with
                | Some _ -> standardized
                | None -> owner (System.IO.Path.GetDirectoryName dir)
        owner (System.IO.Path.GetDirectoryName file)

    /// ### file_linked_units
    /// The units the file's package links (`link:` in its package.spiproj), as package id -> unit (the linked package's
    /// folder name, plus its unit graph once built). Unions those units export come from them instead of being emitted here.
    let file_linked_units (packages : SchemaEnv) (package_ids : Map<string, int>) (file : string) : Map<int, LinkedUnit> =
        let rec owner (dir : string) =
            if System.String.IsNullOrEmpty dir then Map.empty
            else
                match SchemaEnv.tryFindText (SpiralFileSystem.standardize_path dir) packages with
                | Some schema ->
                    schema.schema.link
                    |> List.choose (fun l -> let dir = snd l.dir in Map.tryFind dir package_ids |> Option.map (fun id -> id, {unit = System.IO.Path.GetFileName(dir.TrimEnd('/', '\\')); exported = readUnitGraph dir; calls = readUnitCalls dir; wraps = readUnitWraps dir; shapes = Set.union (RustLinkedShapes.read dir) (GleamLinkedPrelude.read dir)}))
                    |> Map.ofList
                | None -> owner (System.IO.Path.GetDirectoryName dir)
        owner (System.IO.Path.GetDirectoryName file)

    /// ### ss_validate_packages
    let ss_validate_packages (packages : SchemaEnv) (order : string [], socs : Dictionary<SchemaPathId,int>) : SchemaEnv =
        Array.fold (fun s path ->
            match SchemaEnv.tryFindText path s with
            | Some (x : SchemaState) ->
                let c p = match socs.TryGetValue(SchemaPathIdOps.create p) with true,b -> b | false,_ -> -1
                let is_circular x = x <> -1
                let are_in_same_strong_component a b = is_circular a && is_circular b && a = b
                let ers =
                    let cpath = c path
                    (x.schema.packages, []) ||> List.foldBack (fun {dir=r,p} ers ->
                        let cp = c p
                        if are_in_same_strong_component cpath cp then (r,"Package is circular and loops through the current one.") :: ers
                        elif path = p then (r,"Self referential links are not allowed.") :: ers
                        else
                            match SchemaEnv.tryFindText p s with
                            | Some s' when ss_has_error s' ->
                                let firstError = s'.errors_parse @ s'.errors_modules @ s'.errors_packages |> List.tryHead |> Option.map (snd >> sprintf " First error: %s") |> Option.defaultValue ""
                                (r,$"Package {p} has an error.{firstError}") :: ers
                            | Some _ -> ers
                            | None -> (r,$"Package {p} is not loaded.") :: ers
                        )
                SchemaEnv.addText path {x with errors_packages=ers} s
            | _ -> s
            ) packages order
    

    /// ### ss_validate
    let ss_validate packages modules (order,socs) =
        let packages = ss_validate_modules packages modules order
        ss_validate_packages packages (order,socs)
    

    /// ### ResultMap<'a,'b>
    type ResultMap<'a,'b> when 'a : comparison = {ok : Map<'a,'b>; error: Map<'a,'b>}
    

    /// ### ProjEnvTCResult
    type ProjEnvTCResult = ResultMap<PackageId,ProjStateTC>
    

    /// ### wdiff_projenvr_sync_schema
    let wdiff_projenvr_sync_schema default_env funs_packages funs_files (ids : PackagePathIndex) (packages : SchemaEnv)
            (state : ResultMap<PackageId,ProjState<'file_input,'file,'package>>) order =
        Array.fold (fun (s : ResultMap<_,_>) x ->
            let x' = x |> SpiralFileSystem.standardize_path
            let xId = SchemaPathIdOps.create x'
            trace Verbose (fun () -> $"ServerUtils.wdiff_projenvr_sync_schema / x: {x} / x': {x'}") _locals
            match Map.tryFind xId ids with
            | Some pid ->
                match Map.tryFind xId packages with
                | Some schema ->
                    match Map.tryFind pid s.ok, Map.tryFind pid s.error, ss_has_error schema with
                    | Some _, Some _,_ -> failwith "Compiler error: The ok and error maps should be disjoint."
                    | Some x, None, true -> {ok=Map.remove pid s.ok; error=Map.add pid x s.error}
                    | None, Some x, false -> {ok=Map.add pid x s.ok; error=Map.remove pid s.error}
                    | None, None, c ->
                        let x = wdiff_proj_init (package_default_env default_env schema) funs_packages funs_files pid
                        if c then {s with error=Map.add pid x s.error} else {s with ok=Map.add pid x s.ok}
                    | _ -> s
                | None -> {ok=Map.remove pid s.ok; error=Map.remove pid s.error}
            | None -> s
            ) state order
    

    /// ### projenv_update_packages
    let projenv_update_packages default_env funs_packages funs_files (ids : PackagePathIndex) (packages : SchemaEnv)
            (state : Map<PackageId,ProjState<'a,'b,'state>>)  (dirty_packages : Dictionary<_,_>, order : string []) =
        let package_envs = Dictionary<PackageId,DefaultEnv>()
        Array.foldBack (fun x l ->
            let x' = x |> SpiralFileSystem.standardize_path
            let xId = SchemaPathIdOps.create x'
            trace Verbose (fun () -> $"ServerUtils.projenv_update_packages / x: {x} / x': {x'}") _locals
            match Map.tryFind xId packages with
            | None -> l
            | Some schema when ss_has_error schema -> l
            | Some schema ->
                let pid = ids.[xId]
                package_envs.[pid] <- package_default_env default_env schema
                let packages =
                    schema.schema.packages
                    |> List.map (fun dependency ->
                        dependency.name,
                        ids.[dependency.dir |> snd |> SchemaPathIdOps.create])
                match dirty_packages.TryGetValue(ProjectionPathIdOps.create x') with
                | true, x -> UpdatePackageModule(pid,packages,x) :: l
                | false, _ -> UpdatePackage(pid,packages) :: l
            ) order []
        |> wdiff_projenv (fun pid -> match package_envs.TryGetValue pid with | true, env -> env | _ -> default_env) funs_packages funs_files state
    

    /// ### proj_file_iter_file
    let proj_file_iter_file f (files : ProjFiles) =
        let rec loop = function
            | ProjFilesTree.File(module_id,path,_) -> f module_id path
            | ProjFilesTree.Directory(_,_,l) -> list l
        and list l = List.iter loop l
        list files.tree
    

    /// ### proj_file_get_input
    let proj_file_get_input uids_file (x : ProjFiles) =
        let d = Dictionary(Array.length uids_file)
        proj_file_iter_file (fun mid path -> d.Add(path, Array.get uids_file mid |> fst)) x
        d
    

    /// ### proj_file_from_schema
    let proj_file_from_schema (x : Schema) : ProjFiles =
        let mutable num_files = 0
        let mutable num_dirs = 0
        let rec loop = function
            | FileHierarchy.File(_,(_,path),name) ->
                let uid = num_files
                num_files <- num_files + 1
                let path' = path |> SpiralFileSystem.standardize_path
                trace Verbose (fun () -> $"ServerUtils.proj_file_from_schema / path: {path} / path': {path'}") _locals
                ProjFilesTree.File(uid,path',name)
            | FileHierarchy.Directory(_,_,name,l) ->
                let uid = num_dirs
                num_dirs <- num_dirs + 1
                ProjFilesTree.Directory(uid,name,list l)
        and list l = List.map loop l
        let tree = list x.modules
        { tree = tree; num_files = num_files; num_dirs = num_dirs }
    

    /// ### proj_file_make_input
    let proj_file_make_input f (files : ProjFiles) =
        let ar = Array.zeroCreate files.num_files
        proj_file_iter_file (fun mid path -> ar.[mid] <- f mid path) files
        ar
    

    /// ### dirty_nodes_template
    let dirty_nodes_template funs (ids : PackagePathIndex) (packages : SchemaEnv) modules
            (state : Map<PackageId,_>) (dirty_packages : string HashSet) =
        let d = Dictionary<ProjectionPathId,_ [] * ProjFiles>()
        dirty_packages |> Seq.iter (fun path ->
            let path' = path |> SpiralFileSystem.standardize_path
            let pathId = SchemaPathIdOps.create path'
            trace Verbose (fun () -> $"ServerUtils.dirty_nodes_template / path: {path} / path': {path'}") _locals
            match Map.tryFind pathId ids with
            | Some pid ->
                match Map.tryFind pid state with
                | Some x ->
                    let modules = modules pid
                    let files = proj_file_from_schema packages.[pathId].schema
                    let state =
                        let state = proj_file_get_input x.files.uids_file x.files.files
                        proj_file_make_input (fun mid path ->
                            trace Verbose (fun () -> $"ServerUtils.dirty_nodes_template / proj_file_make_input / path: {path} / path': {path'}") _locals
                            match state.TryGetValue(path) with
                            | true, x -> wdiff_file_update_input funs x (modules mid path)
                            | false, _ -> funs.init (modules mid path)
                            ) files
                    d.Add(ProjectionPathIdOps.create path',(state,files))
                | None -> ()
            | None -> ()
            )
        d
    

    /// ### dirty_nodes_tc
    let dirty_nodes_tc (ids : PackagePathIndex) (packages : SchemaEnv) (modules : ModuleEnv)
            (state : Map<PackageId,ProjStateTC>) (dirty_packages : string HashSet) =
        dirty_nodes_template funs_file_tc ids packages (fun pid mid path -> pid, mid, modules.[ModulePathIdOps.create path].bundler) state dirty_packages
    

    /// ### dirty_nodes_prepass
    let dirty_nodes_prepass (ids : PackagePathIndex) (packages : SchemaEnv) (modules : Map<PackageId,ProjStateTC>)
            (state : Map<PackageId,ProjStatePrepass>) (dirty_packages : string HashSet) =
        let modules pid =
            let x = modules.[pid]
            let state = proj_file_get_input x.files.uids_file x.files.files
            fun (mid : ModuleId) path -> pid, mid, path, state.[path].result
        dirty_nodes_template funs_file_prepass ids packages modules state dirty_packages
    

    /// ### wdiff_projenvr
    let wdiff_projenvr default_env dirty_nodes funs_proj_package funs_proj_file
            ids packages modules (state : ResultMap<PackageId,_>) (dirty_packages, order) =
        let state = wdiff_projenvr_sync_schema default_env funs_proj_package funs_proj_file ids packages state order
        let dirty_packages = dirty_nodes ids packages modules state.ok dirty_packages
        {state with ok=projenv_update_packages default_env funs_proj_package funs_proj_file ids packages state.ok (dirty_packages, order)}
    

    /// ### wdiff_projenvr_tc
    let wdiff_projenvr_tc default_env ids packages modules state (dirty_packages, order) =
        wdiff_projenvr default_env dirty_nodes_tc funs_proj_package_tc funs_proj_file_tc
            ids packages modules state (dirty_packages, order)
    

    /// ### wdiff_projenvr_prepass
    let wdiff_projenvr_prepass default_env ids packages modules state (dirty_packages, order) =
        wdiff_projenvr default_env dirty_nodes_prepass funs_proj_package_prepass funs_proj_file_prepass
            ids packages modules state (dirty_packages, order)
    

    /// ### LoadResult
    type LoadResult =
        | LoadModule of path: string * ModuleState option
        | LoadPackage of package_dir: string * SchemaState option
    

    /// ### is_top_down
    open System.Threading.Tasks
    

    let is_top_down (x : string) = Path.GetExtension x = ".spi"
    

    /// ### spiproj_suffix
    let spiproj_suffix x =
        let toml = Path.Combine(x,"spiral.toml")
        if File.Exists toml then toml else Path.Combine(x,"package.spiproj")
    

    /// ### loader_package
    let loader_package default_env (packages : SchemaEnv) (modules : ModuleEnv) (pdir, text) =
        let pdir' = pdir |> SpiralFileSystem.standardize_path
        trace Verbose (fun () -> $"ServerUtils.loader_package / pdir: {pdir} / pdir': {pdir'}") _locals
        let pdir = pdir'
        let queue = Queue()
        let load_module modules path =
            match ModuleEnv.tryFindText path modules with
            | Some _ -> ()
            | None ->
                task {
                    if File.Exists path then
                        try let! x = File.ReadAllTextAsync(path)
                            let parsed = ref Unchecked.defaultof<_>
                            let failure : exn ref = ref null
                            let env = file_default_env default_env packages path
                            test_entry_parsed.[path] <- env.test_entry
                            let parser = System.Threading.Thread((fun () -> try parsed.Value <- wdiff_module_init_all env (is_top_down path) x with error -> failure.Value <- error), 512 <<< 20)
                            parser.Start ()
                            parser.Join ()
                            if not (isNull failure.Value) then raise failure.Value
                            return LoadModule(path,parsed.Value |> Some)
                        with _ -> return LoadModule(path,None)
                    else return LoadModule(path,None) // Note: We need this case otherwise 'con' might cause the file read to deadlock. https://superuser.com/questions/86999/why-cant-i-name-a-folder-or-file-con-in-windows
                } |> queue.Enqueue
    

        let schema (pdir,text) = schema (pdir,text) |> fun x -> LoadPackage(pdir,Some (ss_from_result x))
        let load_package_from_disk packages pdir =
            trace Verbose (fun () -> $"ServerUtils.loader_package.load_package_from_disk / pdir: {pdir}") _locals
            task {
                if Directory.Exists pdir then
                    try
                        let! x = File.ReadAllTextAsync(spiproj_suffix pdir)
                        return schema (pdir,x)
                    with _ ->
                        return LoadPackage(pdir,None)
                else return LoadPackage(pdir,None) // Ditto.
            } |> queue.Enqueue
        let load_package_some (pdir,text) =
            trace Verbose (fun () -> $"ServerUtils.loader_package.load_package_some / pdir: {pdir}") _locals
            schema (pdir,text) |> Task.FromResult |> queue.Enqueue
        let load_package_none packages pdir =
            let pdir' = pdir |> SpiralFileSystem.standardize_path
            trace Verbose (fun () -> $"ServerUtils.loader_package.load_package_none / pdir: {pdir} / pdir': {pdir'}") _locals
            let pdir = pdir'
            match SchemaEnv.tryFindText pdir packages with
            | Some _ -> ()
            | None -> load_package_from_disk packages pdir
    

        let dirty_packages = HashSet()
        let rec invalidate_parent packages (x : DirectoryInfo) =
            if x <> null then
                let x' = x.FullName |> SpiralFileSystem.standardize_path
                // trace Verbose (fun () -> $"""ServerUtils.loader_package.invalidate_parent / x.FullName: {x.FullName |> SpiralSm.replace "\\" "|"} / x': {x'} / packages: %A{packages |> Map.keys} / pdir: {pdir}""") _locals
                let x_ = x
                let x = {| FullName = x' |}
                if SchemaEnv.containsText x.FullName packages then dirty_packages.Add(x.FullName) |> ignore
                else invalidate_parent packages x_.Parent
    

        let mutable packages = packages
        let mutable modules = modules
    

        match text with
        | Some text -> load_package_some (pdir,text)
        | None ->
            // trace Verbose (fun () -> $"ServerUtils.loader_package / pdir: {pdir}") _locals
            match SchemaEnv.tryFindText pdir packages with
            | Some x -> LoadPackage(pdir,Some x) |> Task.FromResult |> queue.Enqueue
            | None -> load_package_from_disk packages pdir
    

        while 0 < queue.Count do
            match queue.Dequeue().Result with
            | LoadPackage(pdir,Some x) ->
                let pdir' = pdir |> SpiralFileSystem.standardize_path
                // trace Verbose (fun () -> $"ServerUtils.loader_package.LoadPackage / pdir: {pdir} / pdir': {pdir'}") _locals
                packages <- SchemaEnv.addText pdir' x packages; dirty_packages.Add(pdir') |> ignore; invalidate_parent packages (Directory.GetParent(pdir'))
                x.schema.packages |> List.iter (fun x -> load_package_none packages (snd x.dir))
                let rec loop = function
                    | FileHierarchy.Directory(_,_,_,l) -> list l
                    | FileHierarchy.File(_,(_,path),_) ->
                        let path' = path |> SpiralFileSystem.standardize_path
                        trace Verbose (fun () -> $"ServerUtils.loader_package.LoadPackage | FileHierarchy.File(_,(_,path),_) / path: {path} / path': {path'}") _locals
                        load_module modules path'
                and list l = List.iter loop l
                list x.schema.modules
            | LoadPackage(pdir,None) -> packages <- SchemaEnv.removeText pdir packages; dirty_packages.Add(pdir) |> ignore; invalidate_parent packages (Directory.GetParent(pdir))
            | LoadModule(mdir,Some x) ->
                let mdir' = mdir |> SpiralFileSystem.standardize_path
                trace Verbose (fun () -> $"ServerUtils.loader_package.LoadModule / mdir: {mdir} / mdir': {mdir'}") _locals
                modules <- ModuleEnv.addText mdir' x modules
            | LoadModule(mdir,None) -> modules <- ModuleEnv.removeText mdir modules
        packages, dirty_packages, modules
    

    /// ### graph_update
    let graph_update (packages : SchemaEnv) (g : MirroredGraph) (dirty_packages : string HashSet) =
        Seq.fold (fun g x ->
            let graphPath = GraphPathIdOps.create x
            match Map.tryFind (SchemaPathIdOps.create x) packages with
            | Some v ->
                v.schema.packages
                |> List.map (fun dependency -> dependency.dir |> snd |> GraphPathIdOps.create)
                |> links_replace g graphPath
            | None -> links_remove g graphPath
            ) g dirty_packages
    

    /// ### package_ids_update
    let package_ids_update (packages : SchemaEnv) (package_ids:PackagePathBiIndex) (dirty_packages : string HashSet) =
        let adds,removals =
            dirty_packages
            |> Seq.toArray
            |> Array.partition (fun path -> SchemaEnv.containsText path packages)
        let adds =
            adds
            |> Array.map SchemaPathIdOps.create
            |> Array.filter (fun pathId -> Map.containsKey pathId (fst package_ids) = false)
            |> HopacExtensions.A.mapi (fun i pathId -> i,pathId)
        let package_ids, removed_pids =
            removals
            |> Array.fold (fun ((forward,reverse),removed as state) path ->
                let pathId = SchemaPathIdOps.create path
                match Map.tryFind pathId forward with
                | Some packageId ->
                    (Map.remove pathId forward, Map.remove packageId reverse), packageId :: removed
                | None -> state
                ) (package_ids,[])
        removed_pids,
        if Array.isEmpty adds then package_ids else
        Map.fold (fun candidates packageId _ ->
            Array.mapFold (fun nextCandidate candidate ->
                if nextCandidate = fst candidate then
                    (nextCandidate + 1, snd candidate), nextCandidate + 1
                else candidate, nextCandidate
                ) packageId candidates
            |> fst
            ) adds (snd package_ids)
        |> Array.fold (fun (forward,reverse) (packageId,pathId) ->
            Map.add pathId packageId forward,
            Map.add packageId pathId reverse
            ) package_ids
    

    /// ### package_ids_remove
    let package_ids_remove (s : ResultMap<PackageId,_>) l =
        List.fold (fun s x -> {ok=Map.remove x s.ok; error=Map.remove x s.error}) s l
    

    /// ## SignalRSupervisor
    // open System
    open System.IO
    open System.Collections.Generic

    open Hopac
    open Hopac.Infixes
    open Hopac.Extensions
    open Hopac.Stream

    // open Common
    open SpiralFileSystem.Operators

    /// ### LocalizedErrors
    type LocalizedErrors = {|uri : string; errors : RString list|}

    /// ### TracedError
    type TracedError = {|trace : string list; message : string|}

    /// ### SupervisorErrorSources
    type SupervisorErrorSources = {
        fatal : string Ch
        tokenizer : LocalizedErrors Ch
        parser : LocalizedErrors Ch
        typer : LocalizedErrors Ch
        package : LocalizedErrors Ch
        traced : TracedError Ch
        }

    /// ### SupervisorReq
    type ProjectFileReq = {|uri : string; spiprojText : string|}
    type UriReq = {|uri : string|}
    type ProjectCodeActionReq = {|uri : string; action : ProjectCodeAction|}
    type ProjectCodeActionResult = {|result : string option|}
    type FileOpenReq = {|uri : string; spiText : string|}
    type FileChangeReq = {|uri : string; spiEdit : SpiEdit|}
    type FileDeleteReq = {|uris : string []|}
    type FileTokenRangeReq = {|uri : string; range : VSCRange|}
    type HoverAtReq = {|uri : string; pos : VSCPos|}
    type BuildFileReq = {|uri : string; backend : string|}
    type SupervisorReq =
        | ProjectFileOpen of ProjectFileReq
        | ProjectFileChange of ProjectFileReq
        | ProjectFileLinks of UriReq * RString list IVar
        | ProjectCodeActions of UriReq * RAction list IVar
        | ProjectCodeActionExecute of ProjectCodeActionReq * ProjectCodeActionResult IVar
        | FileOpen of FileOpenReq
        | FileChange of FileChangeReq
        | FileDelete of FileDeleteReq
        | FileTokenRange of FileTokenRangeReq * int [] IVar
        | HoverAt of HoverAtReq * string option IVar
        | BuildFile of BuildFileReq * string option IVar

    /// ### SupervisorState
    type SupervisorState = {
        packages : SchemaEnv
        modules : ModuleEnv
        packages_infer : ResultMap<PackageId,ProjStateTC>
        packages_prepass : ResultMap<PackageId,ProjStatePrepass>
        graph : MirroredGraph
        package_ids : Map<string,int> * Map<int,string>
        }

    /// ### proj_validate
    let proj_validate default_env s dirty_packages =
        let order,socs = circular_nodes s.graph dirty_packages
        let packages = ss_validate s.packages s.modules (order,socs)
        package_dirs_by_id <- fst s.package_ids |> Map.toSeq |> Seq.map (fun (dir, pid) -> pid, dir) |> Map.ofSeq
        for KeyValue(dir, pid) in fst s.package_ids do
            match SchemaEnv.tryFindText (SpiralFileSystem.standardize_path dir) packages with
            | Some schema when schema.schema.autoExport = Some "monomorphic" -> autoExportPids.[pid] <- true
            | _ -> autoExportPids.TryRemove pid |> ignore
            match SchemaEnv.tryFindText (SpiralFileSystem.standardize_path dir) packages with
            | Some schema when (package_default_env default_env schema).edition = UpstreamEdition2 -> upstreamDialectPids.[pid] <- true
            | _ -> upstreamDialectPids.TryRemove pid |> ignore
        let packages_infer = wdiff_projenvr_tc default_env (fst s.package_ids) packages s.modules s.packages_infer (dirty_packages, order)
        order, {s with packages_infer = packages_infer; packages=packages}

    /// ### proj_graph_update
    let proj_graph_update default_env s dirty_packages =
        let removed_pids,package_ids = package_ids_update s.packages s.package_ids dirty_packages
        let packages_infer, packages_prepass = package_ids_remove s.packages_infer removed_pids, package_ids_remove s.packages_prepass removed_pids
        let graph = graph_update s.packages s.graph dirty_packages
        proj_validate default_env {s with graph = graph; package_ids = package_ids; packages_infer = packages_infer; packages_prepass = packages_prepass} dirty_packages

    /// ### proj_open
    let proj_open default_env s (dir, text) =
        let packages,dirty_packages,modules = loader_package default_env s.packages s.modules (dir,text)
        proj_graph_update default_env {s with packages = packages; modules = modules} dirty_packages

    /// ### proj_revalidate_owner
    let proj_revalidate_owner default_env s file =
        let rec loop (x : DirectoryInfo) =
            if x = null then [||], s
            else
                let x' = x.FullName |> SpiralFileSystem.standardize_path
                // trace Verbose (fun () -> $"""Supervisor.proj_revalidate_owner / x.FullName: {x.FullName |> SpiralSm.replace "\\" "|"} / x': {x'}""") _locals
                let x_ = x
                let x = {| FullName = x' |}
                if Map.containsKey x.FullName s.packages then proj_validate default_env s (HashSet [x.FullName])
                elif File.Exists(spiproj_suffix x.FullName) then proj_open default_env s (x.FullName,None)
                else loop x_.Parent
        loop (Directory.GetParent(file))

    /// ### file_delete
    let file_delete default_env s (files : string []) =
        let deleted_modules = HashSet()
        let deleted_packages = HashSet()
        files |> Array.iter (fun k ->
            s.packages |> Map.iter (fun k' _ -> if (spiproj_suffix k').StartsWith(k) then deleted_packages.Add(k') |> ignore)
            s.modules |> Map.iter (fun k' _ -> if k'.StartsWith(k) then deleted_modules.Add(k') |> ignore)
            )
        let modules = Seq.foldBack Map.remove deleted_modules s.modules
        let packages = Seq.foldBack Map.remove deleted_packages s.packages
        let dirty_packages = HashSet(deleted_packages)
        let revalidate_parent (x : string) =
            trace Verbose (fun () -> $"Supervisor.file_delete.revalidate_parent.loop / x.FullName: {x}") _locals
            let rec loop (x : DirectoryInfo) =
                if x <> null then
                    let x' = x.FullName |> SpiralFileSystem.standardize_path
                    let x = DirectoryInfo x'
                    if Map.containsKey x.FullName s.packages then dirty_packages.Add(x.FullName) |> ignore
                    else loop x.Parent
            loop(Directory.GetParent x)
        Seq.iter revalidate_parent deleted_modules; Seq.iter revalidate_parent deleted_packages
        Seq.toArray deleted_modules, proj_graph_update default_env {s with modules = modules; packages = packages} dirty_packages

    /// ### AttentionState
    type AttentionState = {
        modules : string Set * string list
        packages : string Set * string list
        old_packages : SchemaEnv
        supervisor : SupervisorState
        }

    /// ### attention_server
    let attention_server (errors : SupervisorErrorSources) (req : _ Ch) =
        let push path (s,o) = Set.add path s, path :: o
        let add (s,o) l = Array.foldBack (fun x (s,o as z) -> if Set.contains x s then z else Set.add x s, x :: o) l (s,o)
        let update (s : AttentionState) (modules,packages,supervisor) = {modules = add s.modules modules; packages = add s.packages packages; supervisor = supervisor; old_packages = s.supervisor.packages}
        let rec loop (s : AttentionState) : Promise<Void> =
            let clear uri =
                Hopac.start (Ch.send errors.tokenizer {|uri=uri; errors=[]|})
                Hopac.start (Ch.send errors.parser {|uri=uri; errors=[]|})
                Hopac.start (Ch.send errors.typer {|uri=uri; errors=[]|})
            let send_tokenizer uri x = Hopac.start (Ch.send errors.tokenizer {|uri=uri; errors=x|})
            let clear_parse uri = Hopac.start (Ch.send errors.parser {|uri=uri; errors=[]|})
            let clear_typer uri = Hopac.start (Ch.send errors.typer {|uri=uri; errors=[]|})
            let clear_old_package x = Map.tryFind x s.old_packages |> Option.iter (fun x ->
                let rec loop = function
                    | FileHierarchy.File(_,(_,pdir),_) -> clear (file_uri pdir)
                    | FileHierarchy.Directory(_,_,_,l) -> list l
                and list l = List.iter loop l
                list x.schema.modules
                )

            let inline body uri interrupt ers ers' src next =
                Ch.Try.take req >>=* function
                | Some x -> interrupt x
                | None ->
                    if List.isEmpty ers then next ers'
                    else
                        let ers = List.append ers ers'
                        Hopac.start (Ch.send src {|uri=uri; errors=ers|})
                        next ers

            let loop_module (s : AttentionState) mpath (m : ModuleState) =
                let uri = file_uri mpath
                let interrupt x = loop (update {s with modules=push mpath s.modules} x)
                let rec bundler (r : BlockBundleState) ers' = r >>=* function
                    | Cons((_,x),rs) -> body uri interrupt x.errors ers' errors.parser (bundler rs)
                    | Nil -> loop s
                send_tokenizer uri m.tokenizer.errors
                clear_parse uri
                clear_typer uri
                bundler m.bundler []

            let rec loop_package (s : AttentionState) pdir = function
                | (mpath,l) :: ls ->
                    let mpath' = mpath |> SpiralFileSystem.standardize_path
                    let uri = file_uri mpath
                    let pdir' = pdir |> SpiralFileSystem.standardize_path
                    trace Verbose (fun () -> $"Supervisor.attention_server.loop.loop_package / mpath: {mpath} / mpath': {mpath'} / uri: {uri} / pdir: {pdir} / pdir': {pdir'}") _locals
                    let interrupt x = loop (update {s with packages=push pdir s.packages} x)
                    let rec typer (r : TypecheckerStateValue Stream) ers' = r >>=* function
                        | Cons((_,x,_),rs) -> body uri interrupt x.errors ers' errors.typer (typer rs)
                        | Nil -> loop_package s pdir' ls
                    let rec bundler (r : BlockBundleState) ers' = r >>=* function
                        | Cons((_,x),rs) -> body uri interrupt x.errors ers' errors.parser (bundler rs)
                        | Nil -> clear_typer uri; typer l []
                    match Map.tryFind mpath' s.supervisor.modules with
                    | None ->
                        let message = $"Attention server cannot find module state for {mpath'} while processing package {pdir'}."
                        trace Critical (fun () -> message) _locals
                        Hopac.start (Ch.send errors.fatal message)
                        loop s
                    | Some m ->
                        trace Verbose (fun () -> $"Supervisor.attention_server.loop_package.module_ready / mpath: {mpath'}") _locals
                        send_tokenizer uri m.tokenizer.errors
                        clear_parse uri
                        bundler m.bundler []
                | [] -> loop s

            let package s =
                match s.packages with
                | se,x :: xs ->
                    let x' = x |> SpiralFileSystem.standardize_path
                    trace Verbose (fun () -> $"Supervisor.attention_server.loop.package / x: {x} / x': {x'}") _locals
                    let x = x'
                    let s = {s with packages=Set.remove x se,xs}
                    let package_errors =
                        match Map.tryFind x s.supervisor.packages with
                        | Some v -> List.concat [v.errors_parse; v.errors_modules; v.errors_packages]
                        | None -> []
                    Hopac.start (Ch.send errors.package ({|uri=file_uri(spiproj_suffix x); errors=package_errors|}))
                    clear_old_package x
                    match Map.tryFind x (fst s.supervisor.package_ids) with
                    | Some uid ->
                        match Map.tryFind uid s.supervisor.packages_infer.ok with
                        | Some v ->
                            let path_tcvals =
                                let uids_file = v.files.uids_file
                                let rec loop x s =
                                    match x with
                                    | ProjFilesTree.File(mid,path,_) ->
                                        let path' = path |> SpiralFileSystem.standardize_path
                                        trace Verbose (fun () -> $"Supervisor.attention_server.loop | WDiff.File(mid,path,_) / path: {path} / path': {path'}") _locals
                                        (path', (fst uids_file.[mid]).result) :: s
                                    | ProjFilesTree.Directory(_,_,l) -> list l s
                                and list l s = List.foldBack loop l s
                                list v.files.files.tree []
                            loop_package s x path_tcvals
                        | None -> loop s
                    | None -> loop s
                | _, [] -> req >>=* (update s >> loop)

            match s.modules with
            | se,x :: xs ->
                let s = {s with modules=Set.remove x se,xs}
                let x' = x |> SpiralFileSystem.standardize_path
                trace Verbose (fun () -> $"Supervisor.attention_server.loop / x: {x} / x': {x'}") _locals
                match Map.tryFind x s.supervisor.modules with
                | Some v ->
                    let codeDir = x |> System.IO.Path.GetDirectoryName
                    let tokensPath = codeDir </> "tokens.json"
                    if tokensPath |> System.IO.File.Exists |> not
                    then loop_module s x v
                    else
                        trace Verbose (fun () -> $"Supervisor.attention_server.loop / tokens found, skipping / x: {x}") _locals
                        package s
                | None -> clear (file_uri x); package s
            | _,[] -> package s

        (req >>=* fun (modules,packages,supervisor) ->
            loop {modules = Set.ofArray modules, Array.toList modules; packages = Set.ofArray packages, Array.toList packages; supervisor = supervisor; old_packages = Map.empty}
            )

    /// ### show_position
    let show_position (s : SupervisorState) (x : Range) =
        let line = (fst x.range).line
        let col = (fst x.range).character
        let er_code = s.modules.[x.path].tokenizer.lines_text.[line]
        StringBuilder()
            .AppendLine(sprintf "Error trace on line: %i, column: %i in module: %s ." (line+1) (col+1) x.path)
            .AppendLine(er_code)
            .Append(' ',col)
            .AppendLine("^")
            .ToString()

    /// ### show_trace
    let show_trace s (x : Trace) (msg : string) =
        let rec loop (l : Trace) = function
            | (x : Range) :: xs ->
                match l with
                | x' :: _ when x.path = x'.path && fst x.range = fst x'.range -> loop l xs
                | _ -> loop (x :: l) xs
            | _ -> l
        List.map (show_position s) (loop [] x), msg

    /// ### BuildResult
    type BuildResult =
        | BuildOk of GeneratedFile list
        | BuildErrorTrace of string list * string
        | BuildFatalError of string
        | BuildSkip

    /// ### workspaceRoot
    let workspaceRoot = SpiralFileSystem.get_workspace_root ()

    /// ### targetDir
    let targetDir = workspaceRoot </> "target/spiral_Eval"

    /// ### traceDir
    let traceDir = targetDir </> "supervisor_trace"

    /// ### dir
    let dir uri =
        let result = System.IO.FileInfo(System.Uri(uri).LocalPath).Directory.FullName
        let result' = result |> SpiralFileSystem.standardize_path
        trace Verbose (fun () -> $"Supervisor.dir / uri: {uri} / result: {result} / result': {result'}") _locals
        result'

    /// ### file
    let file uri =
        let result =
            try
                System.IO.FileInfo(System.Uri(uri).LocalPath).FullName
            with ex ->
                trace Verbose (fun () -> $"Supervisor.file / uri: {uri} / ex: %A{ex}") _locals
                uri
        let result' = result |> SpiralFileSystem.standardize_path
        // let result = result |> SpiralSm.replace "\\" "|"
        // trace Verbose (fun () -> $"Supervisor.file / uri: {uri} / result: {result} / result': {result'}") _locals
        result'

    let select_test_entry (uri : string) (name : string option) =
        test_entry_selection <- name |> Option.map (fun name -> file uri, name)

    /// ### supervisor_server
    let supervisor_server (default_env : DefaultEnv) atten (errors : SupervisorErrorSources) req =
        let fatal x = Hopac.start (Ch.send errors.fatal x)
        let handle_packages (dirty_packages,s) = Hopac.start (Ch.send atten ([||],dirty_packages,s)); s
        let handle_file_packages file (dirty_packages,s) = Hopac.start (Ch.send atten ([|file|],dirty_packages,s)); s
        let handle_files_packages (dirty_files,(dirty_packages,s)) = Hopac.start (Ch.send atten (dirty_files,dirty_packages,s)); s
        let loop (s : SupervisorState) = req >>- function
            | SupervisorReq.ProjectFileChange x | SupervisorReq.ProjectFileOpen x -> proj_open default_env s (dir x.uri,Some x.spiprojText) |> handle_packages
            | SupervisorReq.FileOpen x ->
                let file = file x.uri
                // trace Verbose (fun () -> $"Supervisor.supervisor_server.loop.FileOpen / x: %A{x} / file: {file}") _locals
                let env = file_default_env default_env s.packages file
                let parsed_with = match test_entry_parsed.TryGetValue file with | true, v -> v | _ -> None
                match Map.tryFind file s.modules with
                | Some m when parsed_with = env.test_entry -> wdiff_module_all env m x.spiText
                | _ -> test_entry_parsed.[file] <- env.test_entry; wdiff_module_init_all env (is_top_down file) x.spiText
                |> fun v -> proj_revalidate_owner default_env {s with modules = Map.add file v s.modules} file
                |> handle_file_packages file
            | SupervisorReq.FileChange x ->
                let file = file x.uri
                trace Verbose (fun () -> $"Supervisor.supervisor_server.loop.FileChange / x: %A{x} / file: {file}") _locals
                match Map.tryFind file s.modules with
                | None -> fatal "It is not possible to apply a change to a file that is not present in the environment. Try reopening it in the editor."; s
                | Some m ->
                    match wdiff_module_edit (file_default_env default_env s.packages file) m x.spiEdit with
                    | Ok v -> proj_revalidate_owner default_env {s with modules = Map.add file v s.modules} file |> handle_file_packages file
                    | Error er -> fatal er; s
            | SupervisorReq.FileDelete x ->
                trace Verbose (fun () -> $"Supervisor.supervisor_server.loop.FileDelete / x: {x}") _locals
                file_delete default_env s (Array.map file x.uris) |> handle_files_packages
            | SupervisorReq.ProjectFileLinks(x,res) ->
                let l =
                    match Map.tryFind (dir x.uri) s.packages with
                    | None -> []
                    | Some x ->
                        let mutable l = []
                        x.schema.packages |> List.iter (fun x ->
                            let r,dir = x.dir
                            trace Verbose (fun () -> $"Supervisor.supervisor_server.ProjectFileLinks / x.schema.packages |> List.iter / dir: {dir}") _locals
                            if Map.containsKey dir s.packages then l <- (r,file_uri (spiproj_suffix dir)) :: l
                            )
                        let rec loop = function
                            | FileHierarchy.Directory(_,_,_,l) -> list l
                            | FileHierarchy.File(_,(r,path),_) ->
                                trace Verbose (fun () -> $"Supervisor.supervisor_server.ProjectFileLinks.loop | SpiProj.FileHierarchy.File(_,(r,path),_) / path: {path}") _locals
                                if Map.containsKey path s.modules then l <- (r,file_uri path) :: l
                        and list l = List.iter loop l
                        list x.schema.modules
                        l
                Hopac.start (IVar.fill res l)
                s
            | SupervisorReq.ProjectCodeActions(x,res) ->
                let z =
                    match Map.tryFind (dir x.uri) s.packages with
                    | None -> []
                    | Some x ->
                        let mutable z = []
                        let actions_dir (r,path) =
                            match r with
                            | None -> ()
                            | Some r ->
                                if Directory.Exists(path) then
                                    z <- (r,RenameDirectory {|dirPath=path; target=null; validate_as_file=false|}) :: (r,DeleteDirectory {|dirPath=path; range=r|}) :: z
                                else
                                    z <- (r,CreateDirectory {|dirPath=path|}) :: z
                        actions_dir x.schema.moduleDir
                        actions_dir x.schema.packageDir

                        let rec actions_module = function
                            | FileHierarchy.Directory(r',(r,path),_,l) ->
                                trace Verbose (fun () -> $"Supervisor.supervisor_server.ProjectCodeActions.actions_module | SpiProj.FileHierarchy.Directory(r',(r,path),_,l) / path: {path}") _locals
                                if Directory.Exists(path) then
                                    z <- (r,RenameDirectory {|dirPath=path; target=null; validate_as_file=true|}) :: (r,DeleteDirectory {|dirPath=path; range=r'|}) :: z
                                else
                                    z <- (r,CreateDirectory {|dirPath=path|}) :: z
                                actions_modules l
                            | FileHierarchy.File(r',(r,path),_) ->
                                trace Verbose (fun () -> $"Supervisor.supervisor_server.ProjectCodeActions.actions_module | SpiProj.FileHierarchy.File(r',(r,path),_) / path: {path}") _locals
                                if Map.containsKey path s.modules then
                                    z <- (r,RenameFile {|filePath=path; target=null|}) :: (r,DeleteFile {|range=r'; filePath=path|}) :: z
                                else
                                    z <- (r,CreateFile {|filePath=path|}) :: z
                        and actions_modules l = List.iter actions_module l
                        actions_modules x.schema.modules
                        z
                Hopac.start (IVar.fill res z)
                s
            | SupervisorReq.ProjectCodeActionExecute(x,res) ->
                let error, s =
                    match code_action_execute x.action with
                    | Error x -> Some x, s
                    | Ok null -> None, proj_open default_env s (dir x.uri,None) |> handle_packages
                    | Ok path -> None, file_delete default_env s [|path|] |> handle_files_packages
                Hopac.start (IVar.fill res {|result=error|})
                s
            | SupervisorReq.FileTokenRange(x, res) ->
                let v =
                    match Map.tryFind (file x.uri) s.modules with
                    | Some v -> Some v
                    | None -> None


                match v with
                | Some v ->
                    Hopac.start (semantic_tokens v.parser >>=* (vscode_tokens x.range >> IVar.fill res))
                | None ->
                    if x.uri |> SpiralSm.starts_with "vscode-notebook-cell" |> not then
                        trace Debug
                            (fun () -> $"Supervisor.supervisor_server.FileTokenRange")
                            (fun () -> $"module=None / x.uri: {x.uri} / {_locals ()}")

                    Hopac.start (IVar.fill res [||])
                s
            | SupervisorReq.HoverAt(x,res) ->
                let file = file x.uri
                let pos = x.pos
                let _locals () = $"x: %A{x} / file: {file} / res: %A{res}"
                trace Verbose (fun () -> $"Supervisor.supervisor_server.HoverAt") _locals
                let go_hover x =
                    match x with
                    | None -> None
                    | Some (x : InferResult) ->
                        x.hovers |> Array.tryPick (fun ((a,b),r) ->
                            if pos.line = a.line && (a.character <= pos.character && pos.character < b.character) then Some r else None
                            )
                    |> (fun x ->
                        let _locals () = $"x: %A{x}"
                        trace Verbose (fun () -> $"Supervisor.supervisor_server.HoverAt.go_hover") _locals
                        x
                    )
                    |> IVar.fill res
                let go_block (x : TypecheckerState) =
                    let rec loop s (x : TypecheckerStateValue Stream) =
                        x >>=* function
                        | Nil -> go_hover s
                        | Cons((_,x,_),b) ->
                            let _locals () = $"b: {b}"
                            trace Verbose (fun () -> $"Supervisor.supervisor_server.HoverAt.go_block.loop Cons") _locals
                            if x.offset <= pos.line then loop (Some x) b
                            // If the block is over the offset that means the previous one must be the right choice.
                            else go_hover s
                    Hopac.start (loop None x.result)
                let rec go_file uids_file trees =
                    let rec loop = function
                        | ProjFilesTree.File(uid,file',_) -> if file = file' then go_block (Array.get uids_file uid |> fst); true else false
                        | ProjFilesTree.Directory(_,_,l) -> list l
                    and list l = List.exists loop l
                    list trees
                let rec go_parent (x : DirectoryInfo) =
                    trace Verbose (fun () -> $"Supervisor.supervisor_server.HoverAt.go_parent / x: %A{x}") _locals
                    if x = null then false
                    else
                        let path = x.FullName |> SpiralFileSystem.standardize_path
                        if Map.containsKey path s.packages then
                            let pid = (fst s.package_ids).[path]
                            match Map.tryFind pid s.packages_infer.ok with
                            | None -> false
                            | Some x -> go_file x.files.uids_file x.files.files.tree
                        else
                            go_parent x.Parent
                if go_parent (Directory.GetParent(file)) = false then Hopac.start (IVar.fill res None)
                s
            | SupervisorReq.BuildFile (x, res) ->
                let backend = x.backend
                let file = file x.uri
                let _locals () = $"x: %A{x} / file: {file}"
                trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile") _locals
                let handle_build_result = function
                    | BuildOk l ->
                        // Answer only once every file is written: a multi-file backend's caller (`spiral cpp`
                        // on main.cpp) compiles its siblings (main.hpp, main.corelib.hpp) right away.
                        job {
                            do! Job.fromAsync (async {
                                try
                                    for x in l do
                                        let file = Path.ChangeExtension(file,null) // null removes the extension from path.
                                        do! write_output_atomically_async (file + x.file_extension) x.code
                                with ex ->
                                    trace Critical (fun () -> $"Supervisor.supervisor_server.BuildFile.handle_build_result / write: {ex |> SpiralSm.format_exception}") _locals
                            })
                            do!
                                l
                                |> List.map (fun x -> x.code)
                                |> String.concat "\n"
                                |> Some
                                |> IVar.fill res
                        }
                    | BuildFatalError x as x' ->
                        trace Info (fun () -> $"Supervisor.supervisor_server.BuildFile.handle_build_result / BuildFatalError x: %A{x}") _locals
                        Hopac.start (Ch.send errors.fatal x)
                        IVar.fill res None
                    | BuildErrorTrace(a,b) as x' ->
                        trace Info (fun () -> $"Supervisor.supervisor_server.BuildFile.handle_build_result / BuildErrorTrace x': %A{x'}") _locals
                        Hopac.start (Ch.send errors.traced {|trace=a; message=b|})
                        IVar.fill res None
                    | BuildSkip ->
                        trace Info (fun () -> $"Supervisor.supervisor_server.BuildFile.handle_build_result.BuildSkip") _locals
                        IVar.fill res None
                let file_build (s : SupervisorState) pdir mid (tc : ProjStateTC, prepass : ProjStatePrepass) =
                    trace Verbose (fun () -> $"""Supervisor.supervisor_server.BuildFile.file_build / modules: %A{s.modules.Keys |> SpiralSm.concat ", "} / packages: %A{s.packages.Keys |> SpiralSm.concat ", "} / package_ids: %A{s.package_ids |> fst |> fun x -> x.Keys |> SpiralSm.concat ", "}""") _locals
                    let a,b = tc.files.uids_file.[mid]
                    let x,_x = prepass.files.uids_file.[mid]
                    trace Verbose (fun () -> "Supervisor.supervisor_server.BuildFile.file_build.wait_type_input") _locals
                    // A compiler exception anywhere in type checking, the prepass or the build (a Hopac job: e.g. fill's
                    // 'These cases should not appear in fill') used to kill the job, so the build never replied and the
                    // caller hung at 0% CPU: report it as the build's fatal error instead.
                    Hopac.start (Job.tryWith (a.state >>=* fun (has_error',_) ->
                        trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build.type_input_ready / has_error: {has_error'}") _locals
                        b >>=* fun (has_error,_) ->
                        trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build.type_path_ready / has_error: {has_error}") _locals
                        if has_error || has_error' then
                            // The editor gets the typer's errors from the attention loop; a batch build only gets this
                            // message, so it carries the package's errors itself.
                            // The files of the entry's package and its dependencies, the entry's first: the error is
                            // often in a dependency. Not every package this supervisor ever loaded: a long-lived host
                            // (polyglot's Supervisor) accumulates packages, including ones whose directories were
                            // deleted after their build, and folding their streams kept a type-error build from ever
                            // replying (polyglot Supervisor's type-error tests timed out; alone the same build replied in
                            // 5 s). A batch host (one process per compile) loads exactly these packages anyway.
                            // A package state that was reset holds null slots in uids_file (Array.zeroCreate): skip them.
                            let rec files (tc : ProjStateTC) x acc =
                                match x with
                                | ProjFilesTree.File(mid,path,_) ->
                                    let slot = if mid < tc.files.uids_file.Length then tc.files.uids_file.[mid] else Unchecked.defaultof<_>
                                    if isNull (box slot) || isNull (box (fst slot)) then acc
                                    else (path, (fst slot).result) :: acc
                                | ProjFilesTree.Directory(_,_,l) -> List.foldBack (files tc) l acc
                            let states =
                                let seen = HashSet<obj>(HashIdentity.Reference)
                                let dependencies, _ = topological_sort' (fst s.graph) [pdir]
                                let state_of pdir' =
                                    Map.tryFind pdir' (fst s.package_ids) |> Option.bind (fun uid ->
                                        match Map.tryFind uid s.packages_infer.ok with
                                        | Some state -> Some state
                                        | None -> Map.tryFind uid s.packages_infer.error)
                                (dependencies |> Seq.filter (fun d -> d <> pdir) |> Seq.choose state_of |> List.ofSeq) @ [tc]
                                |> List.filter (fun state -> seen.Add (box state))
                            let rec availableErrors acc (stream : Stream<_>) =
                                if Promise.Now.isFulfilled stream then
                                    match Promise.Now.get stream with
                                    | Hopac.Stream.Cons((_, x : InferResult, _), next) -> availableErrors (acc @ x.errors) next
                                    | Hopac.Stream.Nil -> acc
                                else acc
                            let errors =
                                try
                                    states |> List.collect (fun state -> List.foldBack (files state) state.files.files.tree [])
                                    |> List.map (fun (path,result) ->
                                        availableErrors [] result
                                        |> List.map (fun ((a,_),message) -> $"{path}:{a.line + 1}:{a.character + 1}: {message}"))
                                with ex -> [[$"(could not list the typer's errors: {ex.GetType().Name}: {ex.Message})"]]
                            // The entry file's tokenizer and parser errors first: a block that fails to parse is left out,
                            // so its callers' 'Unbound variable' is only the symptom (lane H's empty `match`, lane C's `!!!!EQ`).
                            let _,_,entry_bundles = a.input
                            let entry_tokenizer_errors = match Map.tryFind file s.modules with Some m -> m.tokenizer.errors | None -> []
                            Stream.foldFun (fun errors (_,bundle : BlockBundleValue) -> errors @ bundle.errors) entry_tokenizer_errors entry_bundles
                            >>= fun parse_errors ->
                                let parse_errors = parse_errors |> List.map (fun ((p,_),message) -> $"{file}:{p.line + 1}:{p.character + 1}: {message}")
                                // The other files' (the entry's package and its dependencies) dropped blocks too: a lib
                                // function that fails to parse surfaces only as its callers' 'Unbound variable' otherwise.
                                let other_parse_errors =
                                    try
                                        let rec available acc (stream : BlockBundleState) =
                                            if Promise.Now.isFulfilled stream then
                                                match Promise.Now.get stream with
                                                | Hopac.Stream.Cons((_,x : BlockBundleValue), next) -> available (acc @ x.errors) next
                                                | Hopac.Stream.Nil -> acc
                                            else acc
                                        let rec other_files (tc' : ProjStateTC) x acc =
                                            match x with
                                            | ProjFilesTree.File(mid,path,_) when path <> file ->
                                                let slot = if mid < tc'.files.uids_file.Length then tc'.files.uids_file.[mid] else Unchecked.defaultof<_>
                                                if isNull (box slot) || isNull (box (fst slot)) then acc
                                                else
                                                    let _,_,bundles = (fst slot).input
                                                    let tok = match Map.tryFind path s.modules with Some m -> m.tokenizer.errors | None -> []
                                                    ((tok @ available [] bundles) |> List.map (fun ((p,_),message) -> $"{path}:{p.line + 1}:{p.character + 1}: {message} (this block is left out of its module)")) @ acc
                                            | ProjFilesTree.File _ -> acc
                                            | ProjFilesTree.Directory(_,_,l) -> List.foldBack (other_files tc') l acc
                                        states |> List.collect (fun state -> List.foldBack (other_files state) state.files.files.tree [])
                                    with _ -> []
                                let errors = parse_errors :: other_parse_errors :: errors
                                let details = errors |> Seq.concat |> String.concat "\n"
                                let details = if details = "" then "" else $"\n{details}"
                                fatal $"File {Path.GetFileNameWithoutExtension file} has a type error somewhere in its path.{details}"
                                IVar.fill res None
                        else
                        trace Verbose (fun () -> "Supervisor.supervisor_server.BuildFile.file_build.wait_prepass") _locals
                        // Also note whether the entry file defines `main` itself: an `open` can bring another module's
                        // `main` into scope too (a sub-package whose module `main` opens its dependency's module `main`).
                        Stream.foldFun (fun (own_main,own_terms,_) ((_,adds,env) : PrepassStateValue) ->
                            let own_terms = match adds with AInclude small | AIncludePrivate (small, _) -> Map.foldBack Map.add small.term own_terms | AOpen _ -> own_terms
                            own_main || (match adds with AInclude small | AIncludePrivate (small, _) -> Map.containsKey "main" small.term | AOpen _ -> false), own_terms, env
                            ) (false,Map.empty,prepassTop_env_empty) x.result >>=* fun (own_main,own_terms,env) ->
                        trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build.prepass_ready / terms: {env.term.Count} / own_main: {own_main}") _locals
                        // A block that fails to tokenize or parse is left out of its module and the build goes on, so its
                        // tokenizer and parser errors are reported here (they ride on the bundles type checking consumed).
                        // The entry file's errors always end the build: a dropped block makes callers fail with a bare
                        // `Unbound variable`, or vanishes without a word when nothing calls it (the megas' negatives
                        // "passed" that way). The other files of the entry's own package end it too, whether or not the
                        // entry defines `main` (CHECK-SILENT-DROP: a broken sibling module built with exit 0). Dependencies' errors don't end the build
                        // (a library's dead block shouldn't break its users). The entry's bundle stream is complete; for
                        // the other files only the part already there is read (a file the entry doesn't reach may never
                        // be bundled).
                        let entry_errors =
                            let _,_,bundles = a.input
                            let tokenizer_errors = match Map.tryFind file s.modules with Some m -> m.tokenizer.errors | None -> []
                            Stream.foldFun (fun errors (_,bundle : BlockBundleValue) -> errors @ bundle.errors) tokenizer_errors bundles
                            |> Job.map (List.map (fun e -> file, e))
                        let package_errors =
                            let rec available acc (stream : BlockBundleState) =
                                if Promise.Now.isFulfilled stream then
                                    match Promise.Now.get stream with
                                    | Hopac.Stream.Cons((_,x : BlockBundleValue), next) -> available (acc @ x.errors) next
                                    | Hopac.Stream.Nil -> acc
                                else acc
                            let rec files x acc =
                                match x with
                                | ProjFilesTree.File(mid,path,_) when path <> file ->
                                    let slot = if mid < tc.files.uids_file.Length then tc.files.uids_file.[mid] else Unchecked.defaultof<_>
                                    if isNull (box slot) || isNull (box (fst slot)) then acc
                                    else
                                        let _,_,bundles = (fst slot).input
                                        let tok = match Map.tryFind path s.modules with Some m -> m.tokenizer.errors | None -> []
                                        ((tok @ available [] bundles) |> List.map (fun e -> path, e)) @ acc
                                | ProjFilesTree.File _ -> acc
                                | ProjFilesTree.Directory(_,_,l) -> List.foldBack files l acc
                            try List.foldBack files tc.files.files.tree [] with _ -> []
                        // The dependencies' blocks that fail to tokenize or parse don't end the build (a library's dead
                        // block shouldn't break its users), but they were dropped without a word (a lib/spiral edit that
                        // broke one definition surfaced only as 'Unbound variable' in its callers): warn on stderr.
                        let dependency_warnings () =
                            try
                                let rec available acc (stream : BlockBundleState) =
                                    if Promise.Now.isFulfilled stream then
                                        match Promise.Now.get stream with
                                        | Hopac.Stream.Cons((_,x : BlockBundleValue), next) -> available (acc @ x.errors) next
                                        | Hopac.Stream.Nil -> acc
                                    else acc
                                let rec files (tc' : ProjStateTC) x acc =
                                    match x with
                                    | ProjFilesTree.File(mid,path,_) ->
                                        let slot = if mid < tc'.files.uids_file.Length then tc'.files.uids_file.[mid] else Unchecked.defaultof<_>
                                        if isNull (box slot) || isNull (box (fst slot)) then acc
                                        else
                                            let _,_,bundles = (fst slot).input
                                            let tok = match Map.tryFind path s.modules with Some m -> m.tokenizer.errors | None -> []
                                            ((tok @ available [] bundles) |> List.map (fun e -> path, e)) @ acc
                                    | ProjFilesTree.Directory(_,_,l) -> List.foldBack (files tc') l acc
                                let dependencies, _ = topological_sort' (fst s.graph) [pdir]
                                dependencies
                                |> Seq.filter (fun d -> d <> pdir)
                                |> Seq.choose (fun d -> Map.tryFind d (fst s.package_ids) |> Option.bind (fun uid -> match Map.tryFind uid s.packages_infer.ok with Some x -> Some x | None -> Map.tryFind uid s.packages_infer.error))
                                |> Seq.collect (fun tc' -> List.foldBack (files tc') tc'.files.files.tree [])
                                |> Seq.iter (fun (path,((p,_),message)) -> eprintfn "warning: %s:%i:%i: %O (this block is left out of its module)" path (p.line + 1) (p.character + 1) message)
                            with _ -> ()
                        entry_errors >>=* fun entry_errors ->
                        let entry_errors = entry_errors @ package_errors
                        let literal_warnings () =
                            try
                                let rec available acc (stream : Stream<_>) =
                                    if Promise.Now.isFulfilled stream then
                                        match Promise.Now.get stream with
                                        | Hopac.Stream.Cons((_, x : InferResult, _), next) -> available (acc @ x.warnings) next
                                        | Hopac.Stream.Nil -> acc
                                    else acc
                                let rec own_files x acc =
                                    match x with
                                    | ProjFilesTree.File(mid,path,_) ->
                                        let slot = if mid < tc.files.uids_file.Length then tc.files.uids_file.[mid] else Unchecked.defaultof<_>
                                        if isNull (box slot) || isNull (box (fst slot)) then acc
                                        else (available [] (fst slot).result |> List.map (fun w -> path, w)) @ acc
                                    | ProjFilesTree.Directory(_,_,l) -> List.foldBack own_files l acc
                                let found = List.foldBack own_files tc.files.files.tree [] |> List.distinct
                                found |> List.truncate 50 |> List.iter (fun (path,((p,_),message)) -> eprintfn "warning: %s:%i:%i: %s" path (p.line + 1) (p.character + 1) message)
                                if found.Length > 50 then eprintfn "warning: %d more WTY-RedundantLiteralSuffix warnings in this package (SPIRAL_WARN_LITERAL_SUFFIX=0 turns them off)" (found.Length - 50)
                            with _ -> ()
                        if List.isEmpty entry_errors then (dependency_warnings (); literal_warnings ())
                        let body() =
                            let test_entry = (file_default_env default_env s.packages file).test_entry
                            match backend, Map.tryFind (match test_entry with Some name -> blockParsingTestEntryName name | None -> "main") env.term with
                            | "Check", _ -> BuildSkip
                            | _, _ when not (List.isEmpty entry_errors) ->
                                let details = entry_errors |> List.map (fun (path,((a,_),message)) -> $"\n{path}:{a.line + 1}:{a.character + 1}: {message}") |> String.concat ""
                                BuildFatalError $"The package of {Path.GetFileNameWithoutExtension file} has blocks that fail to tokenize or parse (such a block is left out of its module: its definitions would be missing without a word).{details}"
                            | _, Some main ->
                                let main =
                                    if file_auto_export s.packages file = Some "monomorphic" then
                                        let own_terms =
                                            let mutable acc = own_terms
                                            prepass.files.uids_file |> Array.iteri (fun i (other, _) ->
                                                if i <> mid && not (isNull (box other)) then
                                                    let rec walk (stream : PrepassStateValue Stream) =
                                                        if not (isNull (box stream)) && Promise.Now.isFulfilled stream then
                                                            match Promise.Now.get stream with
                                                            | Hopac.Stream.Cons((_, adds, _), next) ->
                                                                match adds with
                                                                | AInclude small | AIncludePrivate (small, _) ->
                                                                    for KeyValue(name, e) in small.term do
                                                                        if not (acc.ContainsKey name) then acc <- acc.Add(name, e)
                                                                | AOpen _ -> ()
                                                                walk next
                                                            | Hopac.Stream.Nil -> ()
                                                    walk other.result)
                                            acc
                                        LinkAutoExport.main (System.IO.Path.GetFileName((file_package_dir s.packages file).TrimEnd('/', '\\'))) own_terms main
                                    else main
                                let prototypes_instances = Dictionary(env.prototypes_instances)
                                let nominals =
                                    let t = HashConsTable()
                                    let d = Dictionary()
                                    env.nominals |> Map.iter (fun k v -> d.Add(k, nominal_add t k v))
                                    d
                                try
                                    let inline build_many codegen backend =
                                        trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build.peval_start / backend: {backend}") _locals
                                        RustGapTrace.clear_missing_arm ()
                                        packageDirsById.Value <- fst s.package_ids |> Map.toSeq |> Seq.map (fun (dir, id) -> id, dir) |> Map.ofSeq
                                        ExternCalls.warned.Value.Clear()
                                        ExternCalls.wrapped.Value <-
                                            if backend = "Rust" || backend = "Gleam" || backend = "Zig" then
                                                file_linked_units s.packages (fst s.package_ids) file
                                                |> Map.fold (fun m _ (l : LinkedUnit) -> l.wraps |> Map.fold (fun m k e -> Map.add k $"{l.unit}.{e}" m) m) Map.empty
                                            else Map.empty
                                        ExternCalls.current.Value <-
                                            let calls (call : LinkedUnit -> string -> ExternCalls.Call) =
                                                file_linked_units s.packages (fst s.package_ids) file
                                                |> Map.fold (fun m _ (l : LinkedUnit) -> l.calls |> Map.fold (fun m k e -> Map.add k (call l e) m) m) Map.empty
                                            if backend = "Rust" then calls (fun l e -> {call = $"{l.unit}::{e}"; import_text = None; borrow_strings = true; unit_path = $"{l.unit}::"; struct_records = true; flat_records = false; multi_ranges = true; copy_tuples = false; pascal_records = false})
                                            elif backend = "Gleam" then calls (fun l e -> {call = $"{l.unit}.{e}"; import_text = Some $"import {l.unit}"; borrow_strings = false; unit_path = $"{l.unit}."; struct_records = true; flat_records = true; multi_ranges = true; copy_tuples = false; pascal_records = true})
                                            elif backend = "Zig" then calls (fun l e -> {call = $"{l.unit}.{e}"; import_text = Some $"const {l.unit} = @import(\"{l.unit}.zig\");"; borrow_strings = false; unit_path = $"{l.unit}."; struct_records = false; flat_records = true; multi_ranges = true; copy_tuples = true; pascal_records = false})
                                            else Map.empty
                                        let (a,_),b = PartEvalSeams.with_conflict_restart (fun inline_restart -> peval {prototypes_instances=prototypes_instances; nominals=nominals; backend=backend; inline_restart=inline_restart} main)
                                        trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build.peval_ready / backend: {backend}") _locals
                                        // LF on every OS: backends that build with StringBuilder.AppendLine (TypeScript, Python, Gleam, C++, ...) get the platform
                                        // newline from .NET, CRLF on Windows.
                                        let generated = codegen file b a |> List.map (fun (f : GeneratedFile) -> {| f with code = f.code.Replace("\r\n", "\n") |})
                                        trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build.codegen_ready / backend: {backend} / files: {List.length generated}") _locals
                                        match generated |> List.tryFind (fun f -> RustGapTrace.missing_arm.IsMatch f.code) with
                                        | Some f -> BuildFatalError (RustGapTrace.missing_arm_error backend f.code)
                                        | None -> BuildOk generated
                                    let build codegen backend file_extension =
                                        build_many (fun file b a ->
                                            let code = codegen b (DeadPureLetElision.block a) |> UnusedGlobals.prune b.globals
                                            [generated_file code file_extension]) backend
                                    match backend with
                                    | "Gleam" ->
                                        build_many (fun file b a ->
                                            let ffi_module = System.IO.Path.GetFileNameWithoutExtension file + "_ffi"
                                            let linked, a = file_linked_units s.packages (fst s.package_ids) file, DeadPureLetElision.block a
                                            writeUnitGraph (file_package_dir s.packages file) file linked b a
                                            let code, ffi = codegenGleam ffi_module linked b a
                                            let code = GleamLinkedPrelude.import linked code
                                            GleamLinkedPrelude.write (file_package_dir s.packages file) file code
                                            generated_file (UnusedGlobals.prune b.globals code |> gleamTidy) ".gleam"
                                            :: match ffi with
                                               | NoGleamFfi -> []
                                               | GleamStorageFfi(arrays, refs, catches) -> [generated_file (gleamStorageFfiErlang ffi_module arrays refs catches) "_ffi.erl"; generated_file (gleamStorageFfiJavaScript arrays refs) "_ffi.mjs"]) "Gleam"
                                    | "Lua" -> build codegenLua "Lua" ".lua"
                                    | "Fsharp" -> build codegenFsharp "Fsharp" ".fsx"
                                    | "Rust" ->
                                        build_many (fun file b a ->
                                            let linked, a = file_linked_units s.packages (fst s.package_ids) file, DeadPureLetElision.block a
                                            writeUnitGraph (file_package_dir s.packages file) file linked b a
                                            let code, hashes = codegenRust (file_rust_extern s.packages file) linked b a |> UnusedGlobals.prune b.globals |> RustLinkedShapes.import linked |> RustLinkedShapes.export
                                            RustLinkedShapes.write (file_package_dir s.packages file) file hashes
                                            [generated_file code ".rs"]) "Rust"
                                    | "Pascal" | "Delphi" ->
                                        let refc (parameters : TyV []) (body : TypedBind []) =
                                            let vars = refc_prepass Set.empty (Set parameters) body
                                            fun stmt ->
                                                let incr = match vars.g_incr.TryGetValue stmt with | true, v -> varc_set v 1 | _ -> Map.empty
                                                let decr = match vars.g_decr.TryGetValue stmt with | true, v -> varc_set v -1 | _ -> Map.empty
                                                let op = match vars.g_op.TryGetValue stmt with | true, v -> v | _ -> Map.empty
                                                let op_decr = match vars.g_op_decr.TryGetValue stmt with | true, v -> varc_set v -1 | _ -> Map.empty
                                                incr |> varc_union decr |> varc_union op |> varc_union op_decr
                                        build (codegenPascal refc) "Pascal" ".pas"
                                    | "Zig" ->
                                        build_many (fun file b a ->
                                            let linked, a = file_linked_units s.packages (fst s.package_ids) file, DeadPureLetElision.block a
                                            writeUnitGraph (file_package_dir s.packages file) file linked b a
                                            [generated_file (codegenZig linked b a |> UnusedGlobals.prune b.globals) ".zig"]) "Zig"
                                    | "Wasm" -> build codegenWasm "Wasm" ".wat"
                                    | "Wgsl" -> build codegenWgsl "Wgsl" ".wgsl"
                                    | "Calyx" -> build codegenCalyx "Calyx" ".futil"
                                    | "Kotlin" -> build codegenKotlin "Kotlin" ".kt"
                                    | "Swift" -> build codegenSwift "Swift" ".swift"
                                    | "OpenQasm" -> build codegenOpenQasm "OpenQasm" ".qasm"
                                    | "Ebpf" -> build codegenEbpf "Ebpf" ".ebpf"
                                    | "Lean" -> build codegenLean "Lean" ".lean"
                                    | "Bend" -> build codegenBend "Bend" ".bend"
                                    | "TypeScript" -> build codegenTypeScript "TypeScript" ".ts"
                                    | "C" -> build CodegenC.codegenC "C" ".c"
                                    | "Python + Cuda" -> build_many (CodegenPython.codegen default_env) "Python"
                                    | "Cpp + Cuda" -> build_many (CodegenCpp.codegen default_env) "CppHost"

                                    | "Cuda C++" -> BuildFatalError "The host C++ backend originally made for FPGAs, and then ported to Cuda has been removed in v2.10.0 of Spiral. Please use an earlier version to access it." // Date: 5/8/2024
                                    | "Python" -> BuildFatalError "The prototype Python backend has been replaced by the Python + Cuda one in v2.5.0 of Spiral. Please use an earlier version to access it." // Date: 11/3/2023
                                    | "UPMEM: Python + C" -> BuildFatalError "The UPMEM Python + C backend has been replaced by the Python + Cuda one in v2.5.0 of Spiral. Please use an earlier version to access it." // Date: 11/3/2023
                                    | "HLS C++" -> BuildFatalError "The HLS C++ backend has been replaced by the Cuda one in v2.5.0 of Spiral. Please use an earlier version to access it." // Date: 10/17/2023
                                    | "Cython*" | "Cython" -> BuildFatalError "The Cython backend has been replaced by the Python one in v2.3.1 of Spiral. Please use an earlier version to access it." // Date: 12/27/2022
                                    | _ -> BuildFatalError $"Cannot recognize the backend: {backend}"
                                with
                                    | :? PartEvalTypeError as e -> BuildErrorTrace(show_trace s e.Data0 e.Data1)
                                    | :? CodegenError as e -> BuildFatalError(e.Data1)
                                    | :? CodegenErrorWithPos as e -> BuildErrorTrace(show_trace s e.Data0 e.Data1)
                                    | ex ->
                                        if System.IO.Directory.Exists traceDir then
                                            let guid = System.DateTime.Now |> SpiralDateTime.new_guid_from_date_time
                                            let trace_file = traceDir </> $"{guid}_error.json"
                                            async {
                                                try
                                                    do! $"{ex}" |> SpiralFileSystem.write_all_text_async trace_file
                                                with ex ->
                                                    trace Critical (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build / ex: {ex |> SpiralSm.format_exception}") _locals
                                            }
                                            |> Async.Start
                                        trace Critical (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build / ex: %A{ex}") _locals
                                        BuildFatalError(ex.Message)
                            | _, None ->
                                match test_entry with
                                | Some name -> BuildFatalError $"Cannot find test `{name}` in file {Path.GetFileNameWithoutExtension file} (a static test is a prelude, not an entry)."
                                | None -> BuildFatalError $"Cannot find `main` in file {Path.GetFileNameWithoutExtension file}."

                        // The partial evaluator is using too much stack space, so as a temporary fix, I am running it on a separate thread with much more of it.
                        // Restored 2026-09-30: commit 1eb2ecf had replaced the thread with an inline call, so peval ran
                        // on a 1.5 MB Hopac worker stack and overflowed on file_system.read_link (apps/spiral's wall).
                        let result = IVar()
                        let thread = new System.Threading.Thread((fun () -> body () |> IVar.fill result |> Hopac.start), 1536 <<< 20)
                        // Background: a build that outlives its caller's timeout (a runaway peval) must not keep the
                        // process alive after the caller is done (dotnet-repl hung at 400% cpu after the notebook ended).
                        thread.IsBackground <- true
                        thread.Start()
                        IVar.read result >>= handle_build_result
                        ) (fun ex ->
                            trace Critical (fun () -> $"Supervisor.supervisor_server.BuildFile.file_build / ex: %A{ex}") _locals
                            fatal $"Compiler error while building {Path.GetFileNameWithoutExtension file}: {ex.GetType().Name}: {ex.Message}"
                            IVar.tryFill res None))
                let file_find (s : SupervisorState) pdir =
                    trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_find / pdir: {pdir}") _locals
                    let uid = (fst s.package_ids).[pdir]
                    match Map.tryFind uid s.packages_infer.ok, Map.tryFind uid s.packages_prepass.ok with
                    | Some a, Some b ->
                        let rec loop = function
                            | ProjFilesTree.Directory(_,_,l) -> list l
                            | ProjFilesTree.File(mid,path,_) ->
                                trace Verbose (fun () -> $"Supervisor.supervisor_server.BuildFile.file_find.loop | File(mid,path,_) / path: {path}") _locals
                                if file = path then file_build s pdir mid (a, b); true else false
                        and list l = List.exists loop l
                        if list b.files.files.tree = false then fatal $"File {Path.GetFileNameWithoutExtension file} cannot be found in the project {spiproj_suffix pdir}"

                        s
                    | None, None ->
                        let ownerErrors =
                            match Map.tryFind pdir s.packages with
                            | Some schema -> schema.errors_parse @ schema.errors_modules @ schema.errors_packages |> List.map snd
                            | None -> []
                        let detail = if List.isEmpty ownerErrors then "" else " " + String.concat " " ownerErrors
                        fatal $"Owner of file {Path.GetFileNameWithoutExtension file} has an error. Location: {spiproj_suffix pdir}.{detail}"
                        s
                    | _ -> failwith "Compiler error: The project status should be the same in both infer and prepass."
                let update_owner pdir =
                    let order,dirty_packages = topological_sort' (fst s.graph) [pdir]
                    let packages_prepass = wdiff_projenvr_prepass default_env (fst s.package_ids) s.packages s.packages_infer.ok s.packages_prepass (dirty_packages, order.ToArray())
                    file_find {s with packages_prepass = packages_prepass} pdir
                let rec find_owner (x : DirectoryInfo) =
                    if x = null then fatal $"Cannot find the package file of {file}"; s
                    else
                        let x' = x.FullName |> SpiralFileSystem.standardize_path
                        trace Verbose (fun () -> $"""Supervisor.supervisor_server.BuildFile.find_owner / x.FullName: {x.FullName |> SpiralSm.replace "\\" "|"} / x': {x'}""") _locals
                        let x_ = x
                        let x = {| FullName = x' |}
                        if Map.containsKey x.FullName s.packages then update_owner x.FullName
                        else find_owner x_.Parent
                find_owner (Directory.GetParent(file))

        Job.iterateServer {
            packages = Map.empty
            modules = Map.empty
            packages_infer = {ok=Map.empty; error=Map.empty}
            packages_prepass = {ok=Map.empty; error=Map.empty}
            graph = mirrored_graph_empty
            package_ids = Map.empty, Map.empty
            } loop

    /// ### ClientReq
    type ClientReq =
        | ProjectFileOpen of ProjectFileReq
        | ProjectFileChange of ProjectFileReq
        | ProjectFileLinks of UriReq
        | ProjectCodeActionExecute of ProjectCodeActionReq
        | ProjectCodeActions of UriReq
        | FileOpen of FileOpenReq
        | FileChange of FileChangeReq
        | FileDelete of FileDeleteReq // Also works for project files and directories.
        | FileTokenRange of FileTokenRangeReq
        | HoverAt of HoverAtReq
        | BuildFile of BuildFileReq
        | Ping of bool
        | Exit of bool

    /// ### ClientErrorsRes
    type ClientErrorsRes =
        | FatalError of string
        | TracedError of TracedError
        | PackageErrors of LocalizedErrors
        | TokenizerErrors of LocalizedErrors
        | ParserErrors of LocalizedErrors
        | TypeErrors of LocalizedErrors

    /// ### Supervisor
    type Supervisor = {
        supervisor_ch : SupervisorReq Ch
        }

    /// ## ServerHooks
    let serverTraceFilesEnabled = true
    let exitAfterParentProcessGone () = System.Environment.Exit 1
    let noteClientErrorsDelivered (_ : ClientErrorsRes) = ()
    let exitClientAfterShutdown () = System.Diagnostics.Process.GetCurrentProcess().Kill ()
    let mainTraceLevel = SpiralTrace.TraceLevel.US0_1
    let mainEntered () = ()
    let mainBeforeArguments () = ()
    let mainAnnounceServer (uri_server : string) = printfn "Server bound to: %s" uri_server
    let mainBeforeWebHost () = ()
    let mainBeforeRun () = ()
    let mainHostExitCode () = 0
    let mainRun (mainCore : string [] -> int) (args : string []) = mainCore args
    /// ## new_server
    

    
    open Hopac
    open Hopac.Infixes
    

    let private serializeServerResult (value: 'T) : string =
        match box value with
        | null -> null
        | :? Option<string> as optional -> optional.Value
        | boxed -> FSharp.Json.Json.serialize boxed

    type ServerRuntime(
        errorsStream: FSharp.Control.AsyncSeq<ClientErrorsRes>,
        supervisorChannel: Ch<SupervisorReq>) =

        member _.errors = errorsStream
        member _.supervisor = supervisorChannel

        member _.job_null<'TJob when 'TJob :> Job<unit>>(jobToStart: 'TJob) : Task<string> =
            HopacExtensions.start (jobToStart :> Job<unit>)
            task { return null }

        member _.job_val<'T, 'TJob, 'TJobResult when 'TJob :> Job<'TJobResult>>
            (jobFactory: IVar<'T> -> 'TJob) : Task<string> =
            let resultCell : IVar<'T> = IVar()
            let scheduled : Job<'TJobResult> = jobFactory resultCell :> Job<'TJobResult>
            HopacExtensions.queueAsTask (
                scheduled
                >>=. IVar.read resultCell
                >>- serializeServerResult
            )

    let private newServerCore () : ServerRuntime =
        let subscribers = System.Collections.Concurrent.ConcurrentDictionary<System.Threading.Channels.Channel<ClientErrorsRes>, unit>()
        let publish (x : ClientErrorsRes) =
            for KeyValue (subscriber, ()) in subscribers do
                subscriber.Writer.TryWrite x |> ignore
        let stream =
            { new FSharp.Control.IAsyncEnumerable<ClientErrorsRes> with
                member _.GetEnumerator () =
                    let pending = System.Threading.Channels.Channel.CreateUnbounded<ClientErrorsRes>()
                    subscribers.TryAdd (pending, ()) |> ignore
                    { new FSharp.Control.IAsyncEnumerator<ClientErrorsRes> with
                        member _.MoveNext () = async {
                            let! ct = Async.CancellationToken
                            let! msg = pending.Reader.ReadAsync(ct).AsTask() |> Async.AwaitTask
                            return Some msg
                        }
                        member _.Dispose () =
                            subscribers.TryRemove pending |> ignore
                    }
            }
    

        let error_ch_create msg =
            let x = Ch()
            HopacExtensions.server (Job.forever (Ch.take x >>= (
                msg >> fun (x : ClientErrorsRes) ->
                    Hopac.Job.awaitUnitTask (
                        task {
                            publish x
                            noteClientErrorsDelivered x
                            trace Verbose (fun () -> $"spiral_compiler.new_server / error_ch_create / x: %A{x}") (fun () -> "")
                            ()
                        }
                        |> (fun (x : System.Threading.Tasks.Task<unit>) -> x :> System.Threading.Tasks.Task)
                    )
            )))
            x
    

        let errors : SupervisorErrorSources = {
            fatal = error_ch_create FatalError
            package = error_ch_create PackageErrors
            tokenizer = error_ch_create TokenizerErrors
            parser = error_ch_create ParserErrors
            typer = error_ch_create TypeErrors
            traced = error_ch_create TracedError
            }
        let supervisor = Ch()
        let atten = Ch()
    

        if System.Environment.GetEnvironmentVariable "SPIRAL_ATTENTION_SERVER" = "0" then
            HopacExtensions.server (Job.forever (Ch.take atten |> Job.Ignore))
        else
            HopacExtensions.server (attention_server errors atten)
    

        let args = [| "--port"; "0" |]
        let env = startupParse args
        do HopacExtensions.start (supervisor_server env atten errors supervisor)
    

        ServerRuntime(stream, supervisor)

    let new_server<'a, 'b, 'c, 'd, 'e when 'd :> Job<'e> and 'a :> Job<unit> and 'b : null> ()
        :
        {|
            errors: FSharp.Control.AsyncSeq<ClientErrorsRes>
            job_null: 'a -> Task<'b>
            job_val: (IVar<'c> -> 'd) -> Task<string>
            supervisor: Ch<SupervisorReq>
        |} =
        let runtime = newServerCore ()
        let jobNull (jobToStart: 'a) : Task<'b> =
            HopacExtensions.start (jobToStart :> Job<unit>)
            task { return null }
        let jobVal (jobFactory: IVar<'c> -> 'd) : Task<string> =
            let resultCell : IVar<'c> = IVar()
            let scheduled : Job<'e> = jobFactory resultCell :> Job<'e>
            HopacExtensions.queueAsTask (
                scheduled
                >>=. IVar.read resultCell
                >>- serializeServerResult
            )
        {|
            errors = runtime.errors
            job_null = jobNull
            job_val = jobVal
            supervisor = runtime.supervisor
        |}
    

    /// ### tests
    

    /// ## getParentProcessId
    let getParentProcessId () =
        if SpiralPlatform.is_windows () |> not
        then 0u
        else
            let pid = System.Environment.ProcessId
            let query = $"SELECT ParentProcessId FROM Win32_Process WHERE ProcessId = {pid}"
            use searcher = new System.Management.ManagementObjectSearcher (query)
            use results = searcher.Get ()
            let data = results |> Seq.cast<System.Management.ManagementObject>
            if data |> Seq.isEmpty
            then 0u
            else data |> Seq.head |> (fun mo -> mo.["ParentProcessId"] :?> uint32)

    /// ## assemblyName
    let assemblyName = System.Reflection.Assembly.GetEntryAssembly().GetName().Name

    /// ## startParentWatcher
    let startParentWatcher () =
        let parentAsyncChild = async {
            let parentProcessId = getParentProcessId ()
            trace Verbose
                (fun () -> "spiral_compiler.startParentWatcher")
                (fun () -> $"parentProcessId: {parentProcessId} / {_locals ()}")
    

            if parentProcessId > 0u then
                let parentProcess = parentProcessId |> int |> System.Diagnostics.Process.GetProcessById
                do! parentProcess.WaitForExitAsync () |> Async.AwaitTask
                trace Debug
                    (fun () -> "spiral_compiler.startParentWatcher / Parent process has exited. Performing cleanup...")
                    (fun () -> $"{_locals ()}")
                do! Async.Sleep 1000
                exitAfterParentProcessGone ()
        }
    

        HopacExtensions.start (Job.fromAsync parentAsyncChild)
    

    /// ## SpiralHub
    open System.IO
    open System.Collections.Generic
    

    open Hopac
    open Hopac.Infixes
    open Hopac.Extensions
    open Hopac.Stream
    

    open SpiralFileSystem.Operators
    

    open Microsoft.AspNetCore.SignalR
    open Microsoft.AspNetCore.SignalR.Client
    

    type SpiralHub(supervisor : Supervisor) =
        inherit Hub()
    

        member _.ClientToServerMsg (x : string) =
            let job_null job = HopacExtensions.start job; task { return null }
    

            let serialize (x : obj) =
                match x with
                | null -> null
                | :? Option<string> as x -> x.Value
                | _ -> FSharp.Json.Json.serialize x
    

            let job_val job = let res = IVar() in HopacExtensions.queueAsTask (job res >>=. IVar.read res >>- serialize)
            let supervisor = supervisor.supervisor_ch
    

            let client_req = FSharp.Json.Json.deserialize x
    

            if serverTraceFilesEnabled && Directory.Exists traceDir then
                match client_req with
                | Ping _ -> ()
                | _ ->
                    let req_name = client_req.GetType().Name
                    let guid = System.DateTime.Now |> SpiralDateTime.new_guid_from_date_time
                    let trace_file = traceDir </> $"{guid}_{req_name}.json"
    

                    HopacExtensions.start (job {
                        do! HopacExtensions.sleepMs 500
                        try
                            do! Job.fromAsync (SpiralFileSystem.write_all_text_async trace_file x)
                        with ex ->
                            trace Critical (fun () -> $"SpiralHub.ClientToServerMsg / ex: {ex |> SpiralSm.format_exception}") _locals
                    })
    

            match client_req with
            | ProjectFileOpen x -> job_null (supervisor *<+ SupervisorReq.ProjectFileOpen x)
            | ProjectFileChange x -> job_null (supervisor *<+ SupervisorReq.ProjectFileChange x)
            | ProjectCodeActionExecute x -> job_val (fun res -> supervisor *<+ SupervisorReq.ProjectCodeActionExecute(x,res))
            | ProjectFileLinks x -> job_val (fun res -> supervisor *<+ SupervisorReq.ProjectFileLinks(x,res))
            | ProjectCodeActions x -> job_val (fun res -> supervisor *<+ SupervisorReq.ProjectCodeActions(x,res))
            | FileOpen x -> job_null (supervisor *<+ SupervisorReq.FileOpen x)
            | FileChange x -> job_null (supervisor *<+ SupervisorReq.FileChange x)
            | FileDelete x -> job_null (supervisor *<+ SupervisorReq.FileDelete x)
            | FileTokenRange x -> job_val (fun res -> supervisor *<+ SupervisorReq.FileTokenRange(x,res))
            | HoverAt x -> job_val (fun res -> supervisor *<+ SupervisorReq.HoverAt(x,res))
            | BuildFile x -> job_val (fun res -> supervisor *<+ SupervisorReq.BuildFile(x,res))
            | Ping _ -> task { return null }
            | Exit _ ->
                task {
                    trace Debug (fun () -> "Supervisor.SpiralHub.ClientToServerMsg / exiting...") _locals
                    HopacExtensions.start (job {
                        do! HopacExtensions.sleepMs 300
                        exitClientAfterShutdown ()
                    })
                    return null
                }
    

    /// ## main
    open Microsoft.AspNetCore.Builder
    open Microsoft.AspNetCore.Hosting
    open Microsoft.Extensions.DependencyInjection
    open Microsoft.Extensions.Logging

    let private mainCore (args : string []) =
        mainEntered ()
        mainTraceLevel |> set_trace_level
        mainBeforeArguments ()

        let env = startupParse args

        let uri_server = $"http://localhost:{env.port}"

        mainAnnounceServer uri_server
        trace Debug (fun () -> $"pwd: {System.Environment.CurrentDirectory}") _locals
        let dllPath = System.Reflection.Assembly.GetExecutingAssembly().Location |> System.IO.Path.GetDirectoryName
        trace Debug (fun () -> $"dllPath: {dllPath}") _locals
        trace Debug (fun () -> $"targetDir: {targetDir}") _locals
        mainBeforeWebHost ()
        let builder = Microsoft.AspNetCore.Builder.WebApplication.CreateBuilder()
        builder.Logging.SetMinimumLevel LogLevel.Warning |> ignore
        builder.Services
            .AddCors()
            .AddSignalR(fun x ->
                x.MaximumReceiveMessageSize <- 1 <<< 20
                x.EnableDetailedErrors <- true
                ) |> ignore

        builder.Services
            .AddSingleton<Supervisor>(fun s ->
                let hub = s.GetService<IHubContext<SpiralHub>>()
                let broadcast x =
                    hub.Clients.All.SendCoreAsync("ServerToClientMsg",[|FSharp.Json.Json.serialize x|])

                let server = new_server ()

                server.errors
                |> FSharp.Control.AsyncSeq.mapAsync (fun x ->
                    broadcast x |> Async.AwaitTask
                )
                |> FSharp.Control.AsyncSeq.iterAsyncParallel (fun x -> async { () })
                |> Async.StartChild
                |> Async.RunSynchronously
                |> ignore

                {supervisor_ch=server.supervisor}
                ) |> ignore
        builder.WebHost.UseUrls [|uri_server|] |> ignore
        builder.Logging.SetMinimumLevel(LogLevel.Warning) |> ignore

        let app = builder.Build()
        app.UseCors(fun x ->
            x.SetIsOriginAllowed(fun _ -> true)
                .AllowAnyHeader()
                .AllowAnyMethod()
                .AllowCredentials() |> ignore
            ) |> ignore
        app.MapHub<SpiralHub> "" |> ignore

        startParentWatcher ()

        printfn $"Starting the Spiral Server. It is bound to: {uri_server}"
        mainBeforeRun ()
        app.Run()
        mainHostExitCode ()

    let main args = mainRun mainCore args
